        public BLReturnObject SaveGroupRights(String sa_id, DataSet ds_UploadData, String GroupID)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            objBLReturnObject.ExecutionStatus = 2;
            objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

            #region Primary Validation

            if (sa_id.Trim() == "")
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Please Provide sa_Id";
                return objBLReturnObject;
            }
            if (ds_UploadData == null)
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "There is no data to save";
                return objBLReturnObject;
            }

            #endregion

            obMenuright = (Ds_group_rights)ds_UploadData;

            Boolean isValid = DeleteOldRights(GroupID);

            if (isValid)
            {
                //////////////////////////////
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                ///////////////////////////////////////////////////////////////
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obMenuright.group_rights, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obMenuright.group_rights.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Save successfully.";
                    return objBLReturnObject;
                }
            }
            else
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Error occured in saving data.";
                return objBLReturnObject;
            }
        }

