        public DataTable get_user_data_for_pay_slip(String user_id, String sem_code, string current_sem, string current_year)
        {// 05072023
            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                String SqlSelect = "";

                SqlSelect = "select * from user_mst  " +
                                         " INNER JOIN department_mst on  user_mst.dept_code =  department_mst.dept_code  " +
                                         " INNER JOIN year_mst on user_mst.year_code = year_mst.year_code " +
                                         " INNER JOIN fees_bank_dtl on user_mst.dept_code = fees_bank_dtl.dept_code and user_mst.prog_code = fees_bank_dtl.prog_code " +
                                         " and user_mst.year_code = fees_bank_dtl.year_code and  user_mst.gender = fees_bank_dtl.gender ";

                if (current_sem == "M" && current_year == "2023")
                {

                    SqlSelect += " and (ISNULL(fees_bank_dtl.nationality,'') = (select  Case ISNULL(nationality,'I')  " +
                                             " When 'I' Then '' when 'India' Then '' WHen 'Indian' Then '' " +
                                             " Else 'International'  End  as nationality from user_mst where user_type ='S' and user_id = @user_id))";
                }
                else if (Convert.ToInt32(current_year) > Convert.ToInt32("2023"))
                {

                    SqlSelect += " and (ISNULL(fees_bank_dtl.nationality,'') = (select  Case ISNULL(nationality,'I')  " +
                                             " When 'I' Then '' when 'India' Then '' WHen 'Indian' Then '' " +
                                             " Else 'International'  End  as nationality from user_mst where user_type ='S' and user_id = @user_id))";
                }

                SqlSelect += " WHERE user_mst.user_status_flag = 'A'  and user_mst.user_id = @user_id  and fees_bank_dtl.semester_type ='" + current_sem + "' and fees_bank_dtl.year_semester ='" + current_year + "' ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@user_id";
                para1.DbType = DbType.String;
                para1.Value = user_id;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DataSet ds = new DataSet();
                try
                {
                    DBDataAdpterObject.Fill(ds);
                    if (ds.Tables[0].Rows.Count <= 0)
                        return null;
                    else
                        return ds.Tables[0];

                }
                catch (Exception ex)
                {
                    return null;
                }
            }
            catch (Exception ex)
            {

                return null;
            }
        }

