                SqlSelect = "select * from user_mst " +
                      " INNER JOIN department_mst on  user_mst.dept_code =  department_mst.dept_code  " +
                      " INNER JOIN year_mst on user_mst.year_code = year_mst.year_code INNER JOIN fees_bank_dtl on user_mst.dept_code = fees_bank_dtl.dept_code and user_mst.prog_code = fees_bank_dtl.prog_code and   user_mst.year_code = fees_bank_dtl.year_code " +
               " WHERE user_mst.user_status_flag = 'A'  and user_mst.user_id =@user_id " +
               "  and fees_bank_dtl.semester_type ='" + cept_sem_code + "' and fees_bank_dtl.year_semester ='" + year_code + "'  and fees_bank_dtl.gender = '" + gender + "' and fees_bank_dtl.cancel_flag ='N'";
                if (dt_get_user_type != null)
                {
                    if (dt_get_user_type.Rows[0]["nationality"].ToString().ToLower() != "i" && dt_get_user_type.Rows[0]["nationality"].ToString().ToLower() != "india" && dt_get_user_type.Rows[0]["nationality"].ToString() != string.Empty)
                    {
                        if (cept_sem_code == "M" && year_code == "2023")
                        {
                            SqlSelect += " and fees_bank_dtl.nationality ='International'";
                        }
                        else if (Convert.ToInt32(year_code) > Convert.ToInt32("2023"))
                        {
                            SqlSelect += " and fees_bank_dtl.nationality ='International'";

                        }
                    }
                    else { SqlSelect += " and fees_bank_dtl.nationality is Null "; }
                }
                else { SqlSelect += " and fees_bank_dtl.nationality is Null "; }

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@user_id";
                para1.DbType = DbType.String;
                para1.Value = user_id;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);


                //IDataParameter para2 = DBObjectFactory.GetParameterObject();
                //para2.ParameterName = "@sem_id";
                //para2.DbType = DbType.String;
                //para2.Value = sem_code;
                //DBDataAdpterObject.SelectCommand.Parameters.Add(para2);

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DataSet ds = new DataSet();
                try
                {
                    DBDataAdpterObject.Fill(ds);
                    if (ds.Tables[0].Rows.Count <= 0)
                        return null;
                    else
                        return ds.Tables[0];

                }
                catch (Exception ex)
                {
                    return null;
                }
            }
            catch (Exception ex)
            {

                return null;
            }
        }

