        public DataTable get_online_payment_transaction_id(String user_id, String sem_code, String year_code)
        {
            try
            {
                String SqlSelect = "";

                //"SELECT user_mst.*, w_employee_master.user_name as full_name,  w_employee_master.first_name, w_employee_master.middle_name, w_employee_master.last_name, " +
                //"w_employee_master.user_short_name FROM user_mst LEFT OUTER JOIN w_employee_master ON user_mst.user_id = w_employee_master.user_id " +
                //"WHERE (user_mst.user_id = @userid)";

                SqlSelect = " SELECT transaction_id,(CAST(DATEPART(day,created_date) AS VARCHAR)+'/'+CAST(DATEPART(month,created_date) AS VARCHAR)+'/'+CAST(DATEPART(year,created_date) AS VARCHAR)) as created_date,user_id " +
                            " FROM applicationpaymenttransaction where   semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and payment_response_code ='0' ";

                if (user_id != "")
                {
                    SqlSelect = SqlSelect + " and user_id = '" + user_id + "' ";
                }

                return Get_data(SqlSelect);
            }
            catch (Exception ex)
            {

                return null;
            }
        }

        public DataTable get_online_payment_transaction_id_with_fees_data(String user_id, String sem_code, String year_code)
        {// 05072023
            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                String SqlSelect = "";

                SqlSelect = @" select trans.transaction_id,trans.user_id,trans.amount,
                        (CAST(DATEPART(day,trans.created_date) AS VARCHAR)+'/'+CAST(DATEPART(month,trans.created_date) AS VARCHAR)+'/'+CAST(DATEPART(year,trans.created_date) AS VARCHAR)) as created_date
                        ,fees_bank_dtl.account_name,fees_bank_dtl.bank_code,user_mst.user_name,fees_bank_dtl.semester_code,student_payslip_number.payslip_number
                        from applicationpaymenttransaction as trans
                        inner join user_mst on trans.user_id = user_mst.user_id
                        left join student_payslip_number on trans.user_id = student_payslip_number.user_id
                        and student_payslip_number.semester_type = trans.semester_type
                        and student_payslip_number.year_semester = trans.year_semester	
                        INNER JOIN department_mst on  user_mst.dept_code =  department_mst.dept_code  
                        INNER JOIN year_mst on user_mst.year_code = year_mst.year_code 
                        INNER JOIN fees_bank_dtl on user_mst.dept_code = fees_bank_dtl.dept_code 
                        and user_mst.prog_code = fees_bank_dtl.prog_code 
                        and   user_mst.year_code = fees_bank_dtl.year_code
                        and user_mst.gender = fees_bank_dtl.gender ";

                if (sem_code == "M" && year_code == "2023")
                {
                    SqlSelect += @" and (ISNULL(fees_bank_dtl.nationality,'') = (select  Case ISNULL(nationality,'I') 
						When 'I' Then '' when 'India' Then '' When 'Indian' Then ''  
						Else 'International'  End  as nationality from user_mst where user_type ='S' and user_id = trans.user_id)) ";
                }
                else if (Convert.ToInt32(year_code) > Convert.ToInt32("2023"))
                {
                    SqlSelect += @" and (ISNULL(fees_bank_dtl.nationality,'') = (select  Case ISNULL(nationality,'I') 
						When 'I' Then '' when 'India' Then '' When 'Indian' Then ''  
						Else 'International'  End  as nationality from user_mst where user_type ='S' and user_id = trans.user_id)) ";

                }




                SqlSelect += @" WHERE user_mst.user_status_flag = 'A'  and user_mst.cancel_flag ='N' and user_mst.status ='A'
                        and fees_bank_dtl.semester_type =@sem_code and fees_bank_dtl.year_semester =@year_code
                        and  fees_bank_dtl.cancel_flag ='N'
                        and trans.semester_type =@sem_code and trans.year_semester =@year_code 
                        and payment_response_code = 0";
                //and  student_payslip_number.semester_type =@sem_code and student_payslip_number.year_semester =@year_code ";

                if (user_id != "")
                {
                    SqlSelect = SqlSelect + " and trans.user_id = '" + user_id + "' ";
                }

                SqlSelect = SqlSelect + " order by trans.user_id";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@sem_code";
                para1.DbType = DbType.String;
                para1.Value = sem_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);

                para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@year_code";
                para1.DbType = DbType.String;
                para1.Value = year_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DataSet ds = new DataSet();
                try
                {
                    DBDataAdpterObject.Fill(ds);
                    if (ds.Tables[0].Rows.Count <= 0)
                        return null;
                    else
                        return ds.Tables[0];
                }
                catch (Exception ex)
                {
                    return null;
                }
            }
            catch (Exception ex)
            {

                return null;
            }
        }

