        public DataTable Get_mandatory_course_data_for_student_new(string dept_code, string prog_code, string sem_code, string year_code, string prog_level_code, string semester_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select *,department_wise_course_dtl.dept_code,department_wise_course_dtl.prog_code,course_mst.course_code,course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type,department_wise_course_dtl.semester_code,course_mst.course_desc,course_mst.prerequisite,department_wise_course_dtl.prog_course_id,department_wise_course_dtl.course_typology,CHARINDEX('3', course_mst.course_code, 3) AS MatchPosition " +
                        "  from course_mst INNER JOIN " +
                        " department_wise_course_dtl on course_mst.course_code = department_wise_course_dtl.course_code where course_mst.cancel_flag = 'N' " +
                        " and department_wise_course_dtl.prog_code =@prog_code and  department_wise_course_dtl.course_type ='M' " +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' ";

            if (prog_code == "1" || prog_code == "3")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.sub_category_id <> 'L4' ";
            }
            else if (prog_code == "2")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.sub_category_id not in ('1','L2','L3') ";
            }

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code = @prog_level_code ";
                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@prog_level_code";
                para3.DbType = DbType.String;
                para3.Value = prog_level_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            if (prog_code != "3")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = @dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            }

            if (semester_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.semester_code = @semester_code ";
                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@semester_code";
                para3.DbType = DbType.String;
                para3.Value = semester_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            IDataParameter para2 = DBObjectFactory.GetParameterObject();
            para2.ParameterName = "@prog_code";
            para2.DbType = DbType.String;
            para2.Value = prog_code;
            DBDataAdpterObject.SelectCommand.Parameters.Add(para2);

            SqlSelect += " union select *,codd.dept_code,codd.prog_code,course_mst.course_code,course_mst.course_name,course_mst.course_credits,codd.course_type,codd.semester_code,course_mst.course_desc,course_mst.prerequisite,codd.prog_course_id,codd.course_typology,CHARINDEX('3', course_mst.course_code, 3) AS MatchPosition " +
                        " from course_mst " +
                        " INNER JOIN course_other_dept_dtl as codd on course_mst.course_code = codd.course_code where course_mst.cancel_flag = 'N' " +
                        " and codd.prog_code = @prog_code and codd.course_type = 'M' " +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                        " and codd.semester_type = '" + sem_code + "' and codd.year_semester = '" + year_code + "' ";

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + "and codd.prog_level_code =@prog_level_code ";
            }

            if (prog_code != "3")
            {
                SqlSelect = SqlSelect + " and codd.dept_code =@dept_code ";
            }

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                {
                    return ds.Tables[0];
                }
            }
            catch (Exception ex)
            {
                return null;
            }
        }

