        public DataTable get_feedback_report_instructor_wise(string sem_code, string year_code, string dept_code, string instructor_code)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @" select intsructor_tbl.instructor_name,course_tbl.course_code,course_tbl.course_name,course_tbl.dept_code,course_tbl.semester_type,course_tbl.year_semester,overall_course_avg,overall_Instructor_avg ,course_tbl.course_type,(total_instructor - 1) as instructor_involved
                        from (select fd_dtl.course_code,fd_dtl.course_name,fd_dtl.dept_code,fd_dtl.semester_type,fd_dtl.year_semester,
                        cast(AVG(total_average)as decimal(18,1))as overall_course_avg,fd_dtl.releted_feedback,fd_dtl.course_type ,fd_dtl.total_instructor
                        from 
                        (
                            select student_feedback_dtl.course_code,course_mst.course_name,sr_no,student_feedback_dtl.semester_type,student_feedback_dtl.year_semester,a.total,department_wise_course_dtl.dept_code,student_feedback_dtl.course_type,
			                 cast(sum(case when strongly_agree = 'Y' then 5 when agree = 'Y' then 4 when neither_agree ='Y' then 3 WHEN disagree = 'Y' then 2 when strongly_disagree = 'Y' then 1 
                             when not_applicable = 'Y' then 3 end  ) / cast(a.total as decimal(18,1)) as decimal(18,1)) as total_average,student_feedback_dtl.releted_feedback,total_instructor
                             from student_feedback_dtl 
                      inner join 
                      (
							select COUNT(user_id) as total,course_code,instructor_code,semester_type,year_semester,releted_feedback from 
							(
								 SELECT user_id,course_code,instructor_code,student_feedback_dtl.semester_type,student_feedback_dtl.year_semester,releted_feedback
										FROM student_feedback_dtl where  cancel_flag = 'N' and submit_status = 'Y' 
										and releted_feedback ='course'
										group by user_id,course_code,instructor_code,student_feedback_dtl.semester_type,student_feedback_dtl.year_semester,releted_feedback) as abc
										GROUP BY course_code,instructor_code,semester_type,year_semester,releted_feedback
                        )
                         as a on student_feedback_dtl.course_code = a.course_code 
                        and student_feedback_dtl.semester_type = a.semester_type 
                        and student_feedback_dtl.year_semester = a.year_semester 
                        and student_feedback_dtl.releted_feedback = a.releted_feedback 
                        inner join course_mst on course_mst.course_code = student_feedback_dtl.course_code  
                                                 and course_mst.semester_type = student_feedback_dtl.semester_type
                                                 and course_mst.year_semester = student_feedback_dtl.year_semester
                        inner join department_wise_course_dtl on department_wise_course_dtl.course_code = student_feedback_dtl.course_code
                                   and department_wise_course_dtl.semester_type = student_feedback_dtl.semester_type
                                   and department_wise_course_dtl.year_semester = student_feedback_dtl.year_semester
                        inner join
                        (
							select count(instructor_code) as total_instructor,course_code,semester_type,year_semester from course_wise_instructor where cancel_flag ='N' group by course_code,semester_type,year_semester
							
                        ) as instructor_involved on 
                        student_feedback_dtl.course_code = instructor_involved.course_code 
                        and student_feedback_dtl.semester_type = instructor_involved.semester_type 
                        and student_feedback_dtl.year_semester = instructor_involved.year_semester 
                        where student_feedback_dtl.releted_feedback ='course' and submit_status ='Y' ";

            if (sem_code != "" && year_code != "")
            {
                SqlSelect = SqlSelect + " and student_feedback_dtl.semester_type ='" + sem_code + "' and student_feedback_dtl.year_semester ='" + year_code + "'  and course_mst.semester_type ='" + sem_code + "' and course_mst.year_semester ='" + year_code + "' and  department_wise_course_dtl.semester_type ='" + sem_code + "' and department_wise_course_dtl.year_semester ='" + year_code + "'  ";
            }

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + "   and department_wise_course_dtl.dept_code ='" + dept_code + "' ";
            }
            SqlSelect = SqlSelect + @"group by student_feedback_dtl.course_code,course_mst.course_name,
                        sr_no,student_feedback_dtl.semester_type,
                        student_feedback_dtl.year_semester,a.total,student_feedback_dtl.releted_feedback ,department_wise_course_dtl.dept_code,student_feedback_dtl.course_type,total_instructor
                       
                        ) as fd_dtl
                      
                        group by fd_dtl.course_code,fd_dtl.course_name,fd_dtl.semester_type
                        ,fd_dtl.year_semester,fd_dtl.releted_feedback,fd_dtl.dept_code,fd_dtl.course_type,fd_dtl.total_instructor
                        ) as course_tbl
                        left join
                        (
                        select fd_dtl.course_code,fd_dtl.instructor_code,fd_dtl.instructor_name,fd_dtl.semester_type,fd_dtl.year_semester,
						cast(AVG(total_average)as decimal(18,1))as overall_Instructor_avg,fd_dtl.releted_feedback
						from 
						(
						select student_feedback_dtl.course_code,student_feedback_dtl.instructor_code,instructor_mst.instructor_name,sr_no
						,student_feedback_dtl.semester_type,student_feedback_dtl.year_semester,a.total,
						cast(sum(case when strongly_agree = 'Y' then 5 when agree = 'Y' then 4 when neither_agree ='Y' then 3 WHEN disagree = 'Y' then 2 when strongly_disagree = 'Y' then 1 
                        when not_applicable = 'Y' then 3 end  ) / cast(a.total as decimal(18,1)) as decimal(18,1)) as total_average,student_feedback_dtl.releted_feedback
                        from student_feedback_dtl 
                        inner join instructor_mst on student_feedback_dtl.instructor_code = instructor_mst.instructor_code
                        inner join 
                        (
								 select COUNT(user_id) as total,course_code,instructor_code,semester_type,year_semester,releted_feedback from 
								 (
										SELECT user_id,course_code,instructor_code,student_feedback_dtl.semester_type,student_feedback_dtl.year_semester,releted_feedback
										FROM student_feedback_dtl where instructor_code != '' and instructor_code is not null and cancel_flag = 'N' and submit_status = 'Y' 
										and releted_feedback ='Instructor'
										group by user_id,course_code,instructor_code,student_feedback_dtl.semester_type,student_feedback_dtl.year_semester,releted_feedback) as abc
										GROUP BY course_code,instructor_code,semester_type,year_semester,releted_feedback
			       
                        )
                         as a on student_feedback_dtl.course_code = a.course_code 
                        and student_feedback_dtl.instructor_code = a.instructor_code
                        and student_feedback_dtl.semester_type = a.semester_type 
                        and    student_feedback_dtl.year_semester = a.year_semester 
                        and  student_feedback_dtl.releted_feedback = a.releted_feedback 
                        where student_feedback_dtl.releted_feedback ='Instructor' and submit_status ='Y' ";

            if (sem_code != "" && year_code != "")
            {
                SqlSelect = SqlSelect + " and student_feedback_dtl.semester_type ='" + sem_code + "' and student_feedback_dtl.year_semester ='" + year_code + "' ";
            }

            SqlSelect = SqlSelect + @" group by student_feedback_dtl.course_code,student_feedback_dtl.instructor_code
                        ,instructor_mst.instructor_name,sr_no,student_feedback_dtl.semester_type,
                        student_feedback_dtl.year_semester,a.total,student_feedback_dtl.releted_feedback 
                     
                        ) as fd_dtl
                         where instructor_name is not null and instructor_name != '' 
                        group by fd_dtl.course_code,fd_dtl.instructor_code,fd_dtl.instructor_name,fd_dtl.semester_type
                        ,fd_dtl.year_semester,fd_dtl.releted_feedback
                        ) as intsructor_tbl on course_tbl.course_code = intsructor_tbl.course_code  
                        and course_tbl.semester_type = intsructor_tbl.semester_type
                        and course_tbl.year_semester = intsructor_tbl.year_semester ";
            SqlSelect = SqlSelect + " where intsructor_tbl.instructor_code ='" + instructor_code + "' order by year_semester desc,semester_type ";

            return Get_data(SqlSelect);
        }

