        public DataTable get_student_sub_group_instructor(string user_id, string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @" select csgi.* from course_sub_group as csg
                            inner join course_sub_group_student as csgs on csgs.sub_group_id=csg.sub_group_id and csgs.cancel_flag='N'
			                            and csgs.semester_type=csg.semester_type and csgs.year_semester=csg.year_semester
                            inner join course_sub_group_instructor as csgi on csgi.sub_group_id=csg.sub_group_id and csgi.cancel_flag='N'
			                            and csgi.semester_type=csg.semester_type and csgi.year_semester=csg.year_semester
                            where csg.semester_type='" + sem_code + "' and csg.year_semester='" + year_code + @"' and csg.cancel_flag='N'
                            and csg.course_code='" + course_code + "' and csgs.user_id='" + user_id + "' ";

            return Get_data(SqlSelect);
        }

