        public DataTable Get_all_instructor_code_for_course_code_new(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " SELECT course_wise_instructor.course_code,course_wise_instructor.instructor_code,instructor_mst.instructor_name, " +
                        " course_wise_AA.instructor_code as instructor_AA,course_wise_AA.cancel_flag,NULL as instructor_TA,NULL as cancel_flag " +
                        " FROM course_wise_instructor " +
                        " left join course_wise_AA on course_wise_instructor.instructor_code = course_wise_AA.instructor_code " +
                        " and course_wise_instructor.course_code = course_wise_AA.course_code and course_wise_instructor.semester_type = course_wise_AA.semester_type " +
                        " and course_wise_instructor.year_semester = course_wise_AA.year_semester " +
                        " INNER JOIN instructor_mst on course_wise_instructor.instructor_code = instructor_mst.instructor_code " +
                        " where instructor_mst.cancel_flag = 'N' and course_wise_instructor.semester_type = '" + sem_code + "' " +
                        " and course_wise_instructor.year_semester = '" + year_code + "' and ( course_wise_AA.cancel_flag is null or course_wise_AA.cancel_flag = 'N') ";

            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and course_wise_instructor.course_code = '" + course_code + "' ";
            }

            SqlSelect = SqlSelect + @" 
                        union
                        select cwa.course_code,cwa.instructor_code,im.instructor_name,cwa.instructor_code as instructor_AA,cwa.cancel_flag,
                        NULL as instructor_TA,NULL as cancel_flag
                        from course_wise_AA as cwa
                        inner join instructor_mst as im on im.instructor_code=cwa.instructor_code
                        where cwa.semester_type='" + sem_code + "' and cwa.year_semester='" + year_code + "' ";

            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and cwa.course_code='" + course_code + "' ";
            }

            SqlSelect = SqlSelect + " and (cwa.cancel_flag is null or cwa.cancel_flag = 'N') ";

            SqlSelect = SqlSelect + @" 
                        union
                        select cwt.course_code,cwt.instructor_code,im.instructor_name,NULL as instructor_AA,NULL as cancel_flag,
                        cwt.instructor_code as instructor_TA,cwt.cancel_flag
                        from course_wise_TA as cwt
                        inner join instructor_mst as im on im.instructor_code=cwt.instructor_code
                        where cwt.semester_type='" + sem_code + "' and cwt.year_semester='" + year_code + "' ";

            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and cwt.course_code='" + course_code + "' ";
            }

            SqlSelect = SqlSelect + " and (cwt.cancel_flag is null or cwt.cancel_flag = 'N') ";

            return Get_data(SqlSelect);
        }

