        public DataTable Get_course_data_type_wise(string sem_code, string year_code, string course_type, string course_code, string dept_code)
        {
            String SqlSelect = "";

            SqlSelect = "SELECT COUNT(student_course_allocate_dtl.user_id) as total_allocate_user,student_course_allocate_dtl.course_code,department_wise_course_dtl.course_typology " +
                        " ,course_mst.course_name,department_wise_course_dtl.dept_code FROM student_course_allocate_dtl INNER JOIN department_wise_course_dtl on " +
                        " student_course_allocate_dtl.course_code = department_wise_course_dtl.course_code INNER JOIN course_mst  on student_course_allocate_dtl.course_code = course_mst.course_code " +
                        "where student_course_allocate_dtl.cancel_flag = 'N' and  student_course_allocate_dtl.semester_type = '" + sem_code + "' and student_course_allocate_dtl.year_semester = '" + year_code + "'  " +
                        " and  department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'  " +
                        " and  course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.cancel_flag ='N'  ";

            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and student_course_allocate_dtl.course_code = '" + course_code + "' ";
            }

            if (course_type != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.course_typology in " + course_type + " ";
            }

            //if (sem_code == "S")
            //{
            //    SqlSelect = SqlSelect + " and department_wise_course_dtl.semester_code in ('2','4','6','8','10') ";
            //}
            //else if (sem_code == "M")
            //{
            //    SqlSelect = SqlSelect + " and department_wise_course_dtl.semester_code in ('1','3','5','7','9') ";
            //}

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = '" + dept_code + "'";
            }

            SqlSelect = SqlSelect + " GROUP BY student_course_allocate_dtl.course_code,department_wise_course_dtl.course_typology,course_mst.course_name,department_wise_course_dtl.dept_code order by student_course_allocate_dtl.course_code  ";

            return Get_data(SqlSelect);
        }

