        public DataSet Get_student_wise_feedback_data(string sem_code, string year_code, string dept_code, string prog_code, string disable_courses)
        {
            cmd.Parameters.Clear();

            cmd.Connection = con;
            cmd.CommandText = "get_all_feedback_status_student_wise";
            cmd.CommandType = CommandType.StoredProcedure;

            cmd.Parameters.Add("@dept_code", SqlDbType.VarChar).Value = dept_code;
            cmd.Parameters.Add("@prog_code", SqlDbType.VarChar).Value = prog_code;
            cmd.Parameters.AddWithValue("@sem_code", sem_code);
            cmd.Parameters.Add("@year_code", SqlDbType.VarChar).Value = year_code;
            cmd.Parameters.Add("@disable_courses", SqlDbType.VarChar).Value = disable_courses;

            //cmd.Parameters.Add(new SqlParameter("@year_code", year_code));
            adp = new SqlDataAdapter(cmd);
            //adp.SelectCommand = cmd;
            //SqlParameter outputIdParam = new SqlParameter("@ID", SqlDbType.Int);

            DataSet ds = new DataSet();
            try
            {
                adp.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds;
            }
            catch (Exception ex)
            {
                return null;
            }
        }

