        public string CombinePDF(String FileName)
        {
            try
            {
                string Path = HttpContext.Current.Server.MapPath("~/FeedbackPdf");
                String[] FileArray = FileName.Split(new Char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                List<string> ExitsFile = new List<string>();
                for (int i = 0; i < FileArray.Length; i++)
                {
                    FileArray[i] = Path + "\\" + FileArray[i].ToString();
                }
                string[] filePaths = Directory.GetFiles(Path);

                foreach (var filename in FileArray)
                {
                    string file = filename.ToString();
                    if (File.Exists(file))
                    {
                        ExitsFile.Add(file);
                    }
                    else
                    {
                        BLL.Utilities1.Log.PaymentTransactionLog("PDF File Name Not Exist" + file.ToString());
                    }
                }
                string FolderPathToZip = Path + "\\" + "Feedback Report";
                string filepathname = "";
                using (ZipFile zip = new ZipFile())
                {
                    //zip.AddFiles(ExitsFile.ToArray(), "Feedback Report");
                    //zip.Save(FolderPathToZip + ".zip");
                    //filepathname = "Feedback_Report_" + DateTime.Now.ToString("yyyyMMddHHmm") + ".zip";
                    //string zipPath = Path + "\\Feedback_Report_" + DateTime.Now.ToString("yyyyMMddHHmm") + ".zip";
                    //zip.Save(zipPath);


                    zip.AddFiles(ExitsFile.ToArray(), "Feedback Report");
                    filepathname = "Feedback_Report_" + DateTime.Now.ToString("yyyyMMddHHmm") + ".zip";
                    string zipPath = Path + "\\" + filepathname;
                    zip.Save(zipPath);
                }
                return filepathname;
            }
            catch (Exception ex)
            {
                return "2";
            }

            return "2";
        }

