                        " when not_applicable = 'Y' then 3 end  as number,instructor_code ,student_feedback_dtl.course_type,department_wise_course_dtl.dept_code,  releted_feedback    FROM student_feedback_dtl INNER JOIN department_wise_course_dtl on student_feedback_dtl.course_code = department_wise_course_dtl.course_code " +
