            //                inner join course_type_mst as ctm on ctm.type_code=sfd.course_type
            //                where sfd.semester_type='" + sem_code + "' and sfd.year_semester='" + year_code + @"' and sfd.submit_status='Y' and sfd.cancel_flag='N'
            //                group by sfd.dept_code,ctm.sub_group,sfd.sr_no,sfd.releted_feedback
            //                order by sfd.dept_code,ctm.sub_group,sfd.releted_feedback,CAST(sfd.sr_no as int) ";

            SqlSelect = @" select dwc.dept_code,ctm.sub_group,sfd.releted_feedback,
                            SUM(CAST(sfd.rating as int))total_rating,ROUND(AVG(CAST(sfd.rating as float)),1)AVG_rating,COUNT(sfd.user_id)total_student
                            from student_feedback_dtl as sfd
                            inner join department_wise_course_dtl as dwc on dwc.course_code=sfd.course_code and dwc.cancel_flag='N'
			                                and dwc.semester_type=sfd.semester_type and dwc.year_semester=sfd.year_semester
                            inner join course_type_mst as ctm on ctm.type_code=sfd.course_type
                            where sfd.semester_type='" + sem_code + "' and sfd.year_semester='" + year_code + @"' and sfd.submit_status='Y' and sfd.cancel_flag='N'
                            group by dwc.dept_code,ctm.sub_group,sfd.releted_feedback
                            order by dwc.dept_code,ctm.sub_group,sfd.releted_feedback ";

            return Get_data(SqlSelect);
        }

        public DataTable Get_registered_data_priority_wise_chart(string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "SELECT * FROM student_wise_course_dtl where (status = 'A' or status = 'R') and cancel_flag = 'N'  and semester_type = '" + sem_code + "' and year_semester ='" + year_code + "' " +
                        " and (priority != '' and priority is not NULL) ";

            return Get_data(SqlSelect);
        }

