        public DataTable Get_student_saved_current_sem_data_report(string user_id, string sem_code, string year_code, string dept_code, string prog_code)
        {
            cmd.Parameters.Clear();

            cmd.Parameters.Add("@sem_code", SqlDbType.VarChar).Value = sem_code;
            cmd.Parameters.Add("@year_code", SqlDbType.VarChar).Value = year_code;
            cmd.Parameters.Add("@prog_code", SqlDbType.VarChar).Value = prog_code;
            cmd.Parameters.Add("@dept_code", SqlDbType.VarChar).Value = dept_code;
            cmd.Parameters.Add("@user_id", SqlDbType.VarChar).Value = user_id;

            adp = new SqlDataAdapter(cmd);

            return Get_data_from_SP_new("Get_student_saved_current_sem_data_report");
        }

