        public DataTable WS_Get_student_assigned_current_sem_data_report_for_drop_course(string user_id, string sem_code, string year_code)
        {

            DataTable Currentdt = Get_ws_cept_current_sem_data();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            //select 'true' as 'checkbox', (wcm.course_code + ' - ' + wcm.course_name) coursename,dm.dept_name as Faculty,
            //               CASE wcsr.course_type WHEN 'E' THEN('<p style=color:blue;>' + 'Elective Credit choice for Course  ' + wcsr.credit_combination + '  Credit : ' + wcsr.credits + ' ( Date : ' + FORMAT(wcsr.created_date, 'dd-MM-yyyy') + ' )</p>') END as new_credit,
            //               FORMAT(wcsr.last_modified_date, 'dd-MM-yyyy') as DropCourseDate, 
            //               FORMAT(wcsr.created_date, 'dd-MM-yyyy') as RegistrationDate,  *from ws_connect_student_reg_dtl as wcsr
            //               inner join ws_course_mst wcm on wcm.course_code = wcsr.course_code
            //               and wcm.semester_type = wcsr.semester_type and wcm.year_semester = wcsr.year_semester and wcm.cancel_flag = wcsr.cancel_flag
            //               inner join department_mst dm on dm.dept_code = wcm.inhabitation
            //               where wcsr.semester_type = '" + sem_code_change + @"' and wcsr.year_semester = '" + year_code + @"'  and Format(wcsr.created_date,'dd-MM-yyyy') = Format(GETDATE(), 'dd-MM-yyyy')
            //               and wcsr.cancel_flag = 'N' and wcsr.status = 'P' and wcsr.user_id = '"+ user_id + @"' and wcsr.course_drop_status IS NULL and wcsr.course_type = 'E'
            //               union

            string sem_code_change = sem_code == "M" ? "W" : "S";
            if (Currentdt != null)
            {
                sem_code_change = Currentdt.Rows[0]["sem_code"].ToString();
                year_code = Currentdt.Rows[0]["year_code"].ToString();
            }
            //SqlSelect = @"  
            //               select 'true' as 'checkbox',  (wcm.course_code +' - ' + wcm.course_name) coursename,dm.dept_name as Faculty,
            //               CASE wcsr.course_type WHEN 'E' THEN('<p style=color:blue;>' + 'Elective Credit choice for Course  ' + wcsr.credit_combination + '  Credit : ' + wcsr.credits + ' ( Date : ' + FORMAT(wcsr.created_date,'dd-MM-yyyy') + ' )</p>') END as new_credit,
            //               FORMAT(wcsr.last_modified_date,'dd-MM-yyyy') as DropCourseDate, FORMAT(wcsr.created_date,'dd-MM-yyyy') as RegistrationDate, * from ws_connect_student_reg_dtl as wcsr 
            //               inner join ws_course_mst wcm on wcm.course_code = wcsr.course_code and wcm.semester_type = wcsr.semester_type and wcm.year_semester = wcsr.year_semester and wcm.cancel_flag = wcsr.cancel_flag
            //               inner join department_mst dm on dm.dept_code = wcm.inhabitation
            //               where wcsr.semester_type='" + sem_code_change + @"' and wcsr.year_semester= '" + year_code + @"'  
            //               and wcsr.cancel_flag='N' and wcsr.status='P' and wcsr.user_id='" + user_id + @"' and wcsr.course_drop_status IS NULL and wcsr.course_type='E'
            //               
            //               union 
            //               select 'false' as 'checkbox', (wcm.course_code +' - ' + wcm.course_name) coursename,dm.dept_name as Faculty,
            //               CASE wcsr.course_type WHEN 'E' THEN('<p style=color:blue;>' + 'Elective Credit choice for Course  ' + wcsr.credit_combination + '  Credit : ' + wcsr.credits + ' ( Date : ' + FORMAT(wcsr.created_date,'dd-MM-yyyy') + ' )</p>') END as new_credit,
            //               FORMAT(wcsr.last_modified_date,'dd-MM-yyyy') as DropCourseDate, FORMAT(wcsr.created_date,'dd-MM-yyyy') as RegistrationDate,
            //               * from ws_connect_student_reg_dtl as wcsr 
            //               inner join ws_course_mst wcm on wcm.course_code = wcsr.course_code and wcm.semester_type = wcsr.semester_type and wcm.year_semester = wcsr.year_semester and wcm.cancel_flag = wcsr.cancel_flag
            //               inner join department_mst dm on dm.dept_code = wcm.inhabitation
            //               where wcsr.semester_type='" + sem_code_change + @"' and wcsr.year_semester='" + year_code + @"'  
            //               and wcsr.cancel_flag='N' and wcsr.status='P' and wcsr.user_id='" + user_id + @"' and wcsr.course_drop_status = 'Y' and wcsr.course_type='E'";


            SqlSelect = @" select t1.checkbox,t1.coursename,t1.Faculty,t1.new_credit,t1.DropCourseDate,t1.RegistrationDate,t1.dept_name,t1.course_type,t1.credit_combination,t1.priority,t1.credits,
                           t1.course_drop_status,t1.newenddatecreated,t1.last_modified_date,t1.lastmodified,t1.course_code
                           INTO #table1	from (
                           select 'true' as 'checkbox',  
                           (wcm.course_code +' - ' + wcm.course_name) coursename,dm.dept_name as Faculty,
                           CASE wcsr.course_type WHEN 'E' THEN('<p style=color:blue;>' + 'Elective Credit choice for Course  ' + wcsr.credit_combination + '  Credit : ' + wcsr.credits + ' ( Date : ' + FORMAT(wcsr.created_date,'dd-MM-yyyy') + ' )</p>') 
                           END as new_credit,
                           FORMAT(wcsr.last_modified_date,'dd-MM-yyyy') as DropCourseDate, FORMAT(wcsr.created_date,'dd-MM-yyyy') as RegistrationDate,dept_name,wcsr.course_type,credit_combination,priority,
                           credits,course_drop_status,
                           CONVERT(time, wcsr.last_modified_date) AS newenddatecreated,
                           FORMAT(wcsr.last_modified_date,'yyyy-MM-dd HH:mm:ss') AS last_modified_date,
                           FORMAT(wcsr.last_modified_date,'yyyy-MM-dd HH:mm:ss') AS lastmodified,wcm.course_code
                           from ws_connect_student_reg_dtl as wcsr 
                           inner join ws_course_mst wcm on wcm.course_code = wcsr.course_code and wcm.semester_type = wcsr.semester_type and wcm.year_semester = wcsr.year_semester and wcm.cancel_flag = wcsr.cancel_flag
                           inner join department_mst dm on dm.dept_code = wcm.inhabitation
                           where wcsr.semester_type= '" + sem_code_change + @"' and wcsr.year_semester= '" + year_code + @"'  
                           and wcsr.cancel_flag='N' and wcsr.status='P' and wcsr.user_id= '" + user_id + @"' and wcsr.course_drop_status IS NULL and wcsr.course_type='E'

                           union 
                           select 'false' as 'checkbox', (wcm.course_code +' - ' + wcm.course_name) coursename,dm.dept_name as Faculty,
                           CASE wcsr.course_type WHEN 'E' THEN('<p style=color:blue;>' + 'Elective Credit choice for Course  ' + wcsr.credit_combination + '  Credit : ' + wcsr.credits + ' ( Date : ' + FORMAT(wcsr.created_date,'dd-MM-yyyy') + ' )</p>') END as new_credit,
                           FORMAT(wcsr.last_modified_date,'dd-MM-yyyy') as DropCourseDate, FORMAT(wcsr.created_date,'dd-MM-yyyy') as RegistrationDate,dept_name,wcsr.course_type,credit_combination,priority,
                           credits,course_drop_status,
                           CONVERT(time, wcsr.last_modified_date) AS newenddatecreated,
                           FORMAT(wcsr.last_modified_date,'yyyy-MM-dd HH:mm:ss') AS last_modified_date,
                           FORMAT(wcsr.last_modified_date,'yyyy-MM-dd HH:mm:ss') AS lastmodified,wcm.course_code

                           from ws_connect_student_reg_dtl as wcsr 
                           inner join ws_course_mst wcm on wcm.course_code = wcsr.course_code and wcm.semester_type = wcsr.semester_type and wcm.year_semester = wcsr.year_semester and wcm.cancel_flag = wcsr.cancel_flag
                           inner join department_mst dm on dm.dept_code = wcm.inhabitation
                           where wcsr.semester_type= '" + sem_code_change + @"' and wcsr.year_semester = '" + year_code + @"'
                           and wcsr.cancel_flag='N' and wcsr.status='P' and wcsr.user_id= '" + user_id + @"' and wcsr.course_drop_status = 'Y' and wcsr.course_type='E') as t1
                           UPDATE #table1 
                           SET lastmodified = FORMAT(DATEADD(HOUR, (select CAST(TotalHours as int) from parameter_mst where parameter_name='sws_drop_course_rights' and parameter_value='E'), 
                           CAST(last_modified_date AS datetime)), 'yyyy-MM-dd HH:mm:ss') 
                           select * from #table1
                           WHERE GETDATE() BETWEEN CONVERT(datetime, last_modified_date) AND CONVERT(datetime, lastmodified);
                           drop Table #table1";


            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                {
                    return ds.Tables[0];
                }
            }
            catch (Exception ex)
            {
                return null;
            }
        }



