            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "update student_exam_marks_dtl set cancel_flag ='Y' where cancel_flag = 'N' and course_code = '" + course_code + "' and student_code='" + user_id + "' and semester_type='" + sem + "' and year_semester='" + year + "'";

