                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.backlog='N' ";

            SqlSelect = SqlSelect + " UNION ";

            SqlSelect = SqlSelect + " select *,department_wise_course_dtl.dept_code,department_mst.dept_name,department_wise_course_dtl.prog_code,course_mst.course_code, " +
                        " course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type,department_wise_course_dtl.semester_code, " +
