                        " on course_mst.course_code = department_wise_course_dtl.course_code and department_wise_course_dtl.course_typology in ('24') INNER JOIN department_mst " +
                        " on department_wise_course_dtl.dept_code = department_mst.dept_code where course_mst.cancel_flag = 'N' " +
                        " and  department_wise_course_dtl.dept_code=@dept_code and department_wise_course_dtl.course_type='M'and department_wise_course_dtl.prog_code <> @prog_code " +
                        " and  department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' " +
                        " and  course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.backlog='N' ";

