                            " INNER JOIN department_wise_course_dtl  on course_mst.course_code = department_wise_course_dtl.course_code and department_wise_course_dtl.course_typology in ('24') INNER JOIN department_mst  on department_wise_course_dtl.dept_code = department_mst.dept_code  " +
                            " where course_mst.cancel_flag = 'N'  and  department_wise_course_dtl.dept_code=@dept_code " +
