        public DataTable Get_selected_transaction_data(string trans_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"select applicationpaymenttransaction.transaction_id,applicationpaymenttransaction.user_id,user_mst.user_name ,applicationpaymenttransaction.amount,
                            applicationpaymenttransaction.created_date,payment_transaction_reference_id,
                            CONVERT(VARCHAR(20), applicationpaymenttransaction.created_date, 109) +' '+ RIGHT(CONVERT(VARCHAR(30), applicationpaymenttransaction.created_date, 9),2) as payment_creation_date, 
                            (case ISNULL(cash_collected_by,'') when '' then 'F' else cash_collected_by end)cash_collected_by,
                            (case ISNULL(cash_collected_by,'') when '' then 'Full Fees' else 'Installment'+cash_collected_by end)fees_type
                            from applicationpaymenttransaction 
                            INNER JOIN user_mst on applicationpaymenttransaction.user_id = user_mst.user_id " +
                           " where transaction_id = '" + trans_id + "' ";

            return Get_data(SqlSelect);
        }

        public DataTable get_transactionsdetail_for_mail_send(string trans_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select *,	CONVERT(VARCHAR(20), last_modified_date, 109) +' '+ RIGHT(CONVERT(VARCHAR(30), last_modified_date, 9),2) as payment_return_date from applicationpaymenttransaction " +
                        " where transaction_id = '" + trans_id + "' and payment_response_code = 0 ";

            return Get_data(SqlSelect);
        }

