        public DataTable get_allocate_course_data(string sem_code, string year_code, string dept_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select student_course_allocate_dtl.doc_no,student_course_allocate_dtl.user_id ,user_mst.user_name as full_name,student_course_allocate_dtl.course_code + ' - ' + course_mst.course_name as course_code ,course_mst.course_name , " +
                        " case student_course_allocate_dtl.course_type when 'M' THEN 'Mandatory' when 'E' THEN 'Elective' end as course_type,user_mst.user_id ,department_mst.dept_name,case student_course_allocate_dtl.gpa_nongpa when 'G' then 'GPA' when 'N' then 'Non GPA' else student_course_allocate_dtl.gpa_nongpa end as gpa_nongpa " +
                        " from student_course_allocate_dtl " +
                        " inner join course_mst on student_course_allocate_dtl.course_code = course_mst.course_code " +
                        " and student_course_allocate_dtl.semester_type =course_mst.semester_type and student_course_allocate_dtl.year_semester =course_mst.year_semester " +
                        " INNER JOIN user_mst on student_course_allocate_dtl.user_id = user_mst.user_id " +
                        " inner JOIN department_mst on user_mst.dept_code = department_mst.dept_code " +
                        " INNER JOIN department_wise_course_dtl on student_course_allocate_dtl.course_code = department_wise_course_dtl.course_code " +
                        " where student_course_allocate_dtl.cancel_flag ='N' and user_mst.user_status_flag ='A' " +
                        " and student_course_allocate_dtl.semester_type ='" + sem_code + "' and student_course_allocate_dtl.year_semester ='" + year_code + "' " +
                        " and department_wise_course_dtl.semester_type ='" + sem_code + "' and department_wise_course_dtl.year_semester ='" + year_code + "' ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = @dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            }

            //if (year_code != "")
            //{
            //    SqlSelect = SqlSelect + " and student_course_allocate_dtl.year_code =@year_code ";

            //    IDataParameter para2 = DBObjectFactory.GetParameterObject();
            //    para2.ParameterName = "@year_code";
            //    para2.DbType = DbType.String;
            //    para2.Value = year_code;
            //    DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            //}

            SqlSelect = SqlSelect + "order by student_course_allocate_dtl.course_code,student_course_allocate_dtl.course_type desc,user_mst.user_id ASC ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable get_assessment_details(string sem_code, string year_code, string dept_code, string prog_code, string type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select '<b>' + (course_mst.course_code + ' - '+ course_mst.course_name) + '</b>' as course_code,course_mst.course_code AS cc ,course_mst.course_name, exam_master.exam_code, exam_master.exam_title,exam_master.exam_type, "
                       + " exam_master.weightage,department_wise_course_dtl.prog_code, department_wise_course_dtl.dept_code, department_wise_course_dtl.prog_level_code,exam_master.is_submit,exam_master.last_modified_date "
                       + " from course_mst "
                       + " inner join exam_master on exam_master.course_code = course_mst.course_code and exam_master.semester_type = course_mst.semester_type and exam_master.year_semester = course_mst.year_semester "
                       + " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_mst.course_code and department_wise_course_dtl.semester_type = course_mst.semester_type and department_wise_course_dtl.year_semester = course_mst.year_semester "
                       + " where course_mst.cancel_flag = 'N' and exam_master.cancel_flag = 'N' and department_wise_course_dtl.cancel_flag = 'N' "
                       + " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' "
                       + "  ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = @dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            }

            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = @prog_code ";

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@prog_code";
                para2.DbType = DbType.String;
                para2.Value = prog_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }

            if (type != "" && type != "ALL")
            {
                SqlSelect = SqlSelect + " and exam_master.exam_type = @type ";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@type";
                para3.DbType = DbType.String;
                para3.Value = type;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            SqlSelect = SqlSelect + " order by course_mst.course_code,exam_master.exam_code ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
