        public DataTable get_allocate_course_data_new(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code, string course_code)//Ananth 25042019
        {
            //changes done prog code
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select student_course_allocate_dtl.doc_no,student_course_allocate_dtl.user_id ,user_mst.user_name as full_name,user_mst.gender,user_mst.mail,(student_course_allocate_dtl.course_code + ' - '+ course_mst.course_name) as course_code ,student_course_allocate_dtl.course_code as new_course_code,course_mst.course_name , " +
                        " case student_course_allocate_dtl.course_type when 'M' THEN 'Mandatory' when 'E' THEN 'Elective' end as course_type,user_mst.user_id ,department_mst.dept_name,case student_course_allocate_dtl.gpa_nongpa when 'G' then 'GPA' when 'N' then 'Non GPA' else student_course_allocate_dtl.gpa_nongpa end as gpa_nongpa,course_mst.course_credits,student_certificate_dtl.studio_type, " +
                        " programme_mst.prog_name, programme_level_mst.prog_level_name + ' (' + programme_level_mst.prog_level_desc +' )' prog_level_code " +
                        " from student_course_allocate_dtl " +
                        " inner join course_mst on student_course_allocate_dtl.course_code = course_mst.course_code INNER JOIN user_mst on student_course_allocate_dtl.user_id = user_mst.user_id inner JOIN department_mst on user_mst.dept_code = department_mst.dept_code " +
                        " INNER JOIN department_wise_course_dtl on student_course_allocate_dtl.course_code = department_wise_course_dtl.course_code " +
                        " LEFT JOIN student_certificate_dtl on student_certificate_dtl.user_id = student_course_allocate_dtl.user_id " +
                        " LEFT join programme_mst on programme_mst.prog_code = user_mst.prog_code " +
                        " LEFT join programme_level_mst on programme_level_mst.prog_level_code = user_mst.prog_level_code " +
                        " where student_course_allocate_dtl.cancel_flag ='N' and user_mst.user_status_flag ='A'  " +
                        " and student_course_allocate_dtl.semester_type ='" + sem_code + "' and  student_course_allocate_dtl.year_semester ='" + year_code + "'" +
                        " and department_wise_course_dtl.semester_type ='" + sem_code + "' and  department_wise_course_dtl.year_semester ='" + year_code + "'" +
                        " and course_mst.semester_type ='" + sem_code + "' and  course_mst.year_semester ='" + year_code + "'";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = @dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            }
            //// Returned By Ananth ////
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = @prog_code ";

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@prog_code";
                para2.DbType = DbType.String;
                para2.Value = prog_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code = @prog_level_code ";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@prog_level_code";
                para3.DbType = DbType.String;
                para3.Value = prog_level_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            if (course_code != "" && course_code != null && course_code != "null")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.course_code = @course_code ";

                IDataParameter para4 = DBObjectFactory.GetParameterObject();
                para4.ParameterName = "@course_code";
                para4.DbType = DbType.String;
                para4.Value = course_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para4);
            }

            SqlSelect = SqlSelect + "order by student_course_allocate_dtl.course_code,student_course_allocate_dtl.course_type desc,user_mst.user_id ASC ";

            return Get_data(SqlSelect);
        }

        public DataTable get_user_mst_data_grid(string start_index, string end_index)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = "select * from user_mst where user_status_flag ='A' and user_type ='S'";

            SqlSelect = " select * from ( " +
                        " select ((row_number() over(order by user_id) -1 )/100) + 1 as page,row_number() over(order by user_id) as number,* from user_mst " +
                        " ) as PagedTable " +
                        " where number >= '" + start_index + "' and number <= '" + end_index + "'";

            return Get_data(SqlSelect);
        }

