        public DataTable get_total_offered_course_report(string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = " select   COUNT(  course_mst.course_code) as course_code,  sum( convert(float,course_mst.course_credits)) as total_credits,course_mst.course_type from course_mst where cancel_flag  = 'N'  GROUP BY course_mst.course_type ORDER BY course_type DESC ";

            SqlSelect = "select * from (select count(cm.course_code) as total,cm.course_type,department_mst.dept_name from course_mst  as cm inner join  department_wise_course_dtl as dm on  cm.course_code = dm.course_code " +
                        " inner join department_mst on   dm.dept_code = department_mst.dept_code " +
                        " where cm.semester_type ='" + sem_code + "' and cm.year_semester ='" + year_code + "' and dm.semester_type ='" + sem_code + "' and dm.year_semester ='" + year_code + "' and cm.ugpgoffice_approved='Y' and cm.cancel_flag='N' " +
                        " group by cm.course_type,dept_name)as tbl " +
                        " pivot( " +
                        " avg(total) for [course_type] in (E,M) " +
                        " ) " +
                        " as pvt ";

            return Get_data(SqlSelect);
        }

