        public DataTable get_course_type_and_credits_offered_report()
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "  select dept_name,course_type,Count(course_code) as course_code,SUM(convert(float,course_credits)) as course_credits " +
                        " from(  select DISTINCT CASE department_mst.dept_name WHEN 'Architecture' THEN 'FA' WHEN 'Design' THEN 'FD' WHEN 'Management' THEN 'FM' WHEN 'Planning' THEN 'FP' WHEN 'Technology' THEN 'FT' " +
                        " ELSE  department_mst.dept_name end as dept_name,   CASE course_type_mst.type_name WHEN 'Lecture' THEN 'lecture' WHEN 'Lecture (Large)' THEN 'lecture' WHEN 'Theory' THEN 'lecture' when 'Design Workshop' then 'design_workshop'  WHEN 'Seminar' THEN 'seminar' WHEN 'Research Seminar' THEN 'seminar' when 'Guided Research' " +
                        " THEN 'ghuided_research' when 'Workshop' then 'workshop' when 'Studio' then 'studio'  ELSE course_type_mst.type_name end as course_type,  " +
                        " department_wise_course_dtl.course_code, course_mst.course_credits from department_wise_course_dtl  inner join course_mst " +
                        " on department_wise_course_dtl.course_code = course_mst.course_code  inner join course_type_mst on department_wise_course_dtl.course_typology = course_type_mst.type_code  inner join department_mst on department_wise_course_dtl.dept_code = department_mst.dept_code  where department_wise_course_dtl.cancel_flag ='N' and course_mst.cancel_flag ='N'  " +
                        " GROUP BY course_mst.course_credits,course_typology,department_mst.dept_name,department_wise_course_dtl.course_code,course_type_mst.type_name ) as a GROUP BY course_type,dept_name ORDER BY dept_name ";

            return Get_data(SqlSelect);
        }

