        public DataTable get_registration_report_data(string dept_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " SELECT student_wise_course_dtl.user_id,user_mst.user_name, course_type,COUNT(course_code) as course_code,sum(convert(float,credits)) as credits FROM student_wise_course_dtl " +
                        " INNER JOIN user_mst on student_wise_course_dtl.user_id = user_mst.user_id  where student_wise_course_dtl.cancel_flag = 'N' and student_wise_course_dtl.status = 'R' " +
                        " and student_wise_course_dtl.semester_type = '" + sem_code + "' and  student_wise_course_dtl.year_semester = '" + year_code + "' and user_mst.user_status_flag ='A' ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and user_mst.dept_code =@dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            }

            SqlSelect = SqlSelect + " GROUP BY student_wise_course_dtl.user_id,course_type,user_mst.user_name,user_mst.dept_code ORDER BY user_mst.dept_code,student_wise_course_dtl.user_id,student_wise_course_dtl.course_type ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

