        public DataTable get_online_payment_report_data(string dept_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect = "select op.transaction_id,op.user_id,um.user_name,dm.dept_name,pm.prog_name,CONVERT(varchar,op.created_date,106) as created_date,op.Citrus_PaymentMode,op.amount from applicationpaymenttransaction as op " +
                        " inner join user_mst as um on op.user_id = um.user_id	inner join department_mst as dm on um.dept_code = dm.dept_code inner join programme_mst as pm on  um.prog_code = pm.prog_code " +
                         " where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and payment_response_code = 0 and op.user_id not like '%admin%'  ";


            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and um.dept_code =@dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            }

            SqlSelect = SqlSelect + " order by op.created_date desc ";

            return Get_data(SqlSelect);
        }

        public DataTable get_financial_report_data_WS(string dept_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " SELECT distinct ws_student_course_allocate_dtl.user_id,user_mst.user_name, " +
                        " user_mst.gender,department_mst.dept_name,year_mst.year_desc,programme_mst.prog_name,user_mst.prof_details " +
                        " FROM ws_student_course_allocate_dtl  " +
                        " INNER JOIN user_mst on ws_student_course_allocate_dtl.user_id = user_mst.user_id " +
                        " inner join department_mst on user_mst.dept_code = department_mst.dept_code " +
                        " inner join year_mst on user_mst.year_code = year_mst.year_code " +
                        " left join programme_mst on user_mst.prog_code = programme_mst.prog_code " +
                        " where ws_student_course_allocate_dtl.cancel_flag = 'N' and  user_mst.user_status_flag = 'A'  " +
                        " and ws_student_course_allocate_dtl.semester_type = '" + sem_code + "' and ws_student_course_allocate_dtl.year_semester = '" + year_code + "' and ws_student_course_allocate_dtl.cancel_flag ='N' ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and user_mst.dept_code =@dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            }

            SqlSelect = SqlSelect + " ORDER BY department_mst.dept_name ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

