        public DataTable Sale_of_admission_form(string programme, string start_date, string end_date)
        {
            string[] start = start_date.Split('/');
            string[] end = end_date.Split('/');

            string f_startdate = "" + start[2] + "-" + start[0] + "-" + start[1];
            string f_enddate = "" + end[2] + "-" + end[0] + "-" + end[1];

            string programmeCode = "";
            switch (programme)
            {
                case "UG":
                    programmeCode = "PTM0001";
                    break;
                case "PG":
                    programmeCode = "PTM0002";
                    break;
                case "PhD":
                    programmeCode = "PTM0003";
                    break;
            }

            //DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " SELECT ApplicationMst.application_id, ApplicationMst.transaction_id, ApplicationMst.program_course_id, case ApplicationMst.program_type_id when 'PTM0001' then 'UG' when 'PTM0002' then 'PG' when 'PTM0003' then 'PhD' end as 'Program Type', " +
                        " case ApplicationMst.program_faculty_id when 'PFM0001' then 'Architecture' when 'PFM0002' then 'Planning' when 'PFM0003' then 'Technology' when 'PFM0004' then 'Design' when 'PFM0005' then 'Management' end as 'Faculty', " +
                        " ApplicationMst.user_id, ApplicationMst.year_code, ApplicationMst.status, ApplicationMst.is_admin_approved, ApplicationMst.remarks, ApplicationPaymentTransaction.payment_transaction_reference_id, " +
                        " ApplicationPaymentTransaction.payment_authorization_code, ApplicationPaymentTransaction.payment_root_transaction_reference_no, ApplicationPaymentTransaction.payment_cv_response_code, " +
                        " ApplicationPaymentTransaction.Citrus_PaymentMode, ApplicationPaymentTransaction.amount, ApplicationPaymentTransaction.status_is_payment_received, ApplicationPaymentTransaction.status_refund, " +
                        " ApplicationPaymentTransaction.status_is_active, CandidatePersonalDetails.gender,case CandidatePersonalDetails.reservation when 'C000000001' then 'SC' when 'C000000002' then 'ST' when 'C000000003' then 'OBC' when 'C000000004' then 'General' when 'C000000006' then 'SEBC' end as 'Category'," +
                        " COALESCE(UPPER(LEFT(CandidatePersonalDetails.first_name,1))+LOWER(SUBSTRING(CandidatePersonalDetails.first_name,2,LEN(CandidatePersonalDetails.first_name))), '') + ' ' + " +
                        " COALESCE(UPPER(LEFT(CandidatePersonalDetails.father_name,1))+LOWER(SUBSTRING(CandidatePersonalDetails.father_name,2,LEN(CandidatePersonalDetails.father_name))), '') + ' ' + " +
                        " COALESCE(UPPER(LEFT(CandidatePersonalDetails.surname,1))+LOWER(SUBSTRING(CandidatePersonalDetails.surname,2,LEN(CandidatePersonalDetails.surname))), '') AS candidate_display_name," +
                        " ApplicationPaymentTransaction.created_date as 'Date of Payment',ApplicationPaymentTransaction.payment_root_transaction_reference_no as 'Reference No',case ApplicationPaymentTransaction.Citrus_PaymentMode when 'NET_BANKING' then 'NET BANKING' else 'Card' end as 'Payment Mode'" +
                        " FROM ApplicationMst INNER JOIN ApplicationPaymentTransaction ON ApplicationMst.transaction_id = ApplicationPaymentTransaction.transaction_id LEFT OUTER JOIN CandidatePersonalDetails ON ApplicationMst.user_id = CandidatePersonalDetails.user_id and ApplicationMst.program_course_id = CandidatePersonalDetails.program_course_id " +
                        " WHERE (1 = 1) AND (ApplicationMst.status = 'A')  AND  (CAST(ApplicationMst.created_date AS Date) >= '" + f_startdate + "' AND CAST(ApplicationMst.created_date AS Date) <= '" + f_enddate + "') ";

            if (programmeCode != "")
            {
                SqlSelect = SqlSelect + " AND ApplicationMst.program_type_id = '" + programmeCode + "'";
            }

            SqlSelect = SqlSelect + " ORDER BY ApplicationMst.created_date ASC ";

            //DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            string connection = ConfigurationManager.ConnectionStrings["CEPT_Admission"].ToString();

            SqlConnection con = new SqlConnection(connection);

            SqlCommand cmd = con.CreateCommand();

            cmd.CommandText = SqlSelect;
            cmd.CommandType = CommandType.Text;

            SqlDataAdapter da = new SqlDataAdapter(cmd);

            DataSet ds = new DataSet();
            try
            {
                da.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable get_allocated_course_detail(string dept_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";


            //if (dept_code != "")
            //{
            //    SqlSelect = SqlSelect + " and user_mst.dept_code =@dept_code ";

            //    IDataParameter para1 = DBObjectFactory.GetParameterObject();
            //    para1.ParameterName = "@dept_code";
            //    para1.DbType = DbType.String;
            //    para1.Value = dept_code;
            //    DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            //    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            //}

            //SqlSelect = SqlSelect + " GROUP BY student_course_allocate_dtl.user_id,course_type,user_mst.user_name ORDER BY student_course_allocate_dtl.user_id ";

            SqlSelect = " SELECT sc.course_code,cm.course_name,sc.course_type,sc.priority,COUNT(sc.course_type) as TotalStudent" +
                        " FROM student_wise_course_dtl as sc" +
                        " inner join course_mst as cm on sc.course_code=cm.course_code  inner join department_wise_course_dtl  as dc on cm.course_code=dc.course_code " +
                        " where sc.cancel_flag='N'  and sc.status = 'A' and sc.semester_type = '" + sem_code + "' " + "and sc.year_semester = '" + year_code + "' and cm.semester_type ='" + sem_code + "' and cm.year_semester = '" + year_code + "' and  dc.semester_type = '" + sem_code + "' and dc.year_semester =  '" + year_code + "' and dc.cancel_flag ='N'  and cm.cancel_flag ='N' ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and dc.dept_code = '" + dept_code + "' ";
            }

            SqlSelect = SqlSelect + " group by sc.course_code,cm.course_name,sc.course_type,sc.priority order by sc.course_code,sc.course_type,sc.priority";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                {
                    ds = new DataSet();

                    SqlSelect = " SELECT sc.course_code,cm.course_name,sc.course_type,sc.priority,COUNT(sc.course_type) as TotalStudent" +
                       " FROM student_wise_course_dtl as sc" +
                       " inner join course_mst as cm on sc.course_code=cm.course_code  inner join department_wise_course_dtl  as dc on cm.course_code=dc.course_code " +
                       " where sc.cancel_flag='N'  and sc.status = 'R' and sc.semester_type = '" + sem_code + "' " + "and sc.year_semester = '" + year_code + "' and cm.semester_type ='" + sem_code + "' and cm.year_semester = '" + year_code + "' and  dc.semester_type = '" + sem_code + "' and dc.year_semester =  '" + year_code + "' and dc.cancel_flag ='N'  and cm.cancel_flag ='N' ";

                    if (dept_code != "")
                    {
                        SqlSelect = SqlSelect + " and dc.dept_code = '" + dept_code + "' ";
                    }

                    SqlSelect = SqlSelect + " group by sc.course_code,cm.course_name,sc.course_type,sc.priority order by sc.course_code,sc.course_type,sc.priority";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    DBDataAdpterObject.Fill(ds);

                    if (ds.Tables[0].Rows.Count <= 0)
                    {
                        return null;
                    }
                    else
                    {
                        return ds.Tables[0];
                    }
                }
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable get_assigned_cross_registration_faculty_report(string year_code, string sem_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select user_dept,dept_code , COUNT(course_code) as course_code , SUM(credits) as credits from " +
                        " (SELECT user_mst.dept_code as user_dept,student_course_allocate_dtl.dept_code,student_course_allocate_dtl.course_code,student_course_allocate_dtl.credits " +
                        " FROM `student_course_allocate_dtl` inner JOIN user_mst on student_course_allocate_dtl.user_id = user_mst.user_id where student_course_allocate_dtl.semester_type = '" + sem_code + "' and student_course_allocate_dtl.year_semester = '" + year_code + "' " +
                        " and   student_course_allocate_dtl.dept_code != '' HAVING user_dept != student_course_allocate_dtl.dept_code ORDER BY user_mst.dept_code )  as a group by	user_dept,dept_code ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

