        public DataTable get_assigned_cross_registration_PG_UG_report(string year_code, string sem_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select  user_dept,sum(course_code) as course_code, SUM(credits) as credits , prog_code from (select user_dept , user_prog_code , dept_code  , count(course_code) as course_code , SUM(cast(credits as int)) as credits , prog_code from " +
                        " (SELECT user_mst.dept_code as user_dept,user_mst.prog_code as user_prog_code , student_course_allocate_dtl.dept_code,student_course_allocate_dtl.course_code,student_course_allocate_dtl.credits ,department_wise_course_dtl.prog_code " +
                        " FROM student_course_allocate_dtl inner JOIN user_mst on student_course_allocate_dtl.user_id = user_mst.user_id INNER JOIN department_wise_course_dtl on student_course_allocate_dtl.course_code = department_wise_course_dtl.course_code " +
                        " where student_course_allocate_dtl.semester_type = '" + sem_code + "' and student_course_allocate_dtl.year_semester = '" + year_code + "' and   student_course_allocate_dtl.dept_code != '' and  department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' " +
                        " and user_mst.dept_code != student_course_allocate_dtl.dept_code and user_mst.prog_code != department_wise_course_dtl.prog_code  and user_mst.status = 'A' ) as a " +
                        " GROUP BY user_dept , user_prog_code , dept_code ,prog_code ) as b GROUP BY user_dept ,  prog_code ";

            return Get_data(SqlSelect);
        }

