        public DataTable get_feedback_receipt_report(string year_code, string sem_code, string dept_code, string course_code, string program_level_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select DISTINCT student_course_allocate_dtl.user_id,user_mst.user_name , user_mst.mail,user_mst.dept_code,CASE a.user_id " +
                        " when ISNULL(a.user_id,'') then 'Y' else 'N' END as status_of_feedback from student_course_allocate_dtl INNER JOIN user_mst on student_course_allocate_dtl.user_id = user_mst.user_id " +
                        " LEFT JOIN (select user_id from student_feedback_dtl where cancel_flag = 'N' and submit_status ='Y' and student_feedback_dtl.semester_type = '" + sem_code + "' and  student_feedback_dtl.year_semester = '" + year_code + "' and course_code ='" + course_code + "' GROUP BY user_id ) as a " +
                        " on student_course_allocate_dtl.user_id = a.user_id " +
                        " LEFT JOIN department_wise_course_dtl on department_wise_course_dtl.course_code = student_course_allocate_dtl.course_code " +
                        " where user_status_flag = 'A' and student_course_allocate_dtl.cancel_flag = 'N' and  student_course_allocate_dtl.course_code = '" + course_code + "' " +
                        " and user_mst.dept_code = '" + dept_code + "' and  student_course_allocate_dtl.semester_type = '" + sem_code + "' and student_course_allocate_dtl.year_semester = '" + year_code + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "'  and department_wise_course_dtl.year_semester ='" + year_code + "' ";
            if (program_level_code != "" && program_level_code != null)
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code = '" + program_level_code + "' ";
            }

            SqlSelect = SqlSelect + " order by student_course_allocate_dtl.user_id ";

            return Get_data(SqlSelect);
        }

