        public DataTable get_feedback_course_wise_report(string year_code, string sem_code, string dept_code, string course_code, string program_level_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select a.course_code,a.course_name,student_course_allocate_dtl.course_type,COUNT(student_course_allocate_dtl.course_type) as total_feedback_course,a.dept_code " +
                        " from student_course_allocate_dtl inner join (select user_id,student_feedback_dtl.course_code,course_name,department_wise_course_dtl.dept_code from student_feedback_dtl   INNER JOIN course_mst " +
                        " on student_feedback_dtl.course_code = course_mst.course_code inner join department_wise_course_dtl on student_feedback_dtl.course_code  " +
                        " = department_wise_course_dtl.course_code where student_feedback_dtl.cancel_flag = 'N' and student_feedback_dtl.submit_status = 'Y' and course_mst.cancel_flag='N' and   student_feedback_dtl.semester_type = '" + sem_code + "' and  student_feedback_dtl.year_semester = '" + year_code + "'  " +
                        " and course_mst.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester ='" + year_code + "' and department_wise_course_dtl.semester_type = '" + sem_code + "' and course_mst.year_semester ='" + year_code + "' GROUP BY user_id,student_feedback_dtl.course_code,course_name,department_wise_course_dtl.dept_code  ) as a on student_course_allocate_dtl.user_id = a.user_id and student_course_allocate_dtl.course_code = a.course_code " +
                        " where  a.dept_code = '" + dept_code + "' and student_course_allocate_dtl.cancel_flag = 'N' and student_course_allocate_dtl.semester_type = '" + sem_code + "' and student_course_allocate_dtl.year_semester ='" + year_code + "'" +
                        " GROUP BY  a.course_code,a.course_name,student_course_allocate_dtl.course_type,a.dept_code ";

            //if (program_level_code != "" && program_level_code != null)
            //{
            //    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code='" + program_level_code + "' ";
            //}
            //SqlSelect = SqlSelect + " GROUP BY  a.course_code,a.course_name,student_course_allocate_dtl.course_type,a.dept_code ";

            return Get_data(SqlSelect);
        }

        public DataTable get_feedback_course_instructor_wise_report(string year_code, string sem_code, string dept_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"select total_allocate_course.course_code,total_allocate_course.course_name,
                        total_allocate_course.dept_name ,total_allocate_course.type_name, total_allocate_course.total_course
                        ,isnull(total_feedback.total_feedback_received,0) as total_feedback,'' as faculty_name,'' as faculty_mail,feedback_remarks.remark,total_allocate_course.course_typology from
                         (
                        (select student_course_allocate_dtl.course_code,course_mst.course_name,department_wise_course_dtl.course_typology,course_type_mst.type_name,
                         count(student_course_allocate_dtl.course_code) as total_course ,department_wise_course_dtl.dept_code,department_mst.dept_name from student_course_allocate_dtl
                        inner JOIN department_wise_course_dtl on   student_course_allocate_dtl.course_code = department_wise_course_dtl.course_code  
                        INNER JOIN course_mst on student_course_allocate_dtl.course_code = course_mst.course_code  
                        inner join course_type_mst on department_wise_course_dtl.course_typology = course_type_mst.type_code
                        inner join department_mst on department_wise_course_dtl.dept_code = department_mst.dept_code
                        where student_course_allocate_dtl.cancel_flag = 'N'  
                        and student_course_allocate_dtl.semester_type = @sem_code and student_course_allocate_dtl.year_semester = @year_code
                        and department_wise_course_dtl.semester_type = @sem_code  and department_wise_course_dtl.year_semester = @year_code
                        and course_mst.semester_type = @sem_code and course_mst.year_semester =@year_code  ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code =@dept_code ";

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@dept_code";
                para2.DbType = DbType.String;
                para2.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }

            SqlSelect = SqlSelect + @"GROUP BY student_course_allocate_dtl.course_code,course_mst.course_name,department_wise_course_dtl.course_typology,course_type_mst.type_name,department_wise_course_dtl.dept_code ,department_mst.dept_name
                    ) as total_allocate_course
 
                    left join 
                    ( select distinct course_code,count(distinct user_id ) as total_feedback_received from  student_feedback_dtl  where student_feedback_dtl.cancel_flag = 'N' 
                    and student_feedback_dtl.submit_status = 'Y' and    student_feedback_dtl.semester_type = @sem_code  and  student_feedback_dtl.year_semester = @year_code   
                    group by course_code ) as total_feedback 
                    on total_allocate_course.course_code = total_feedback.course_code
                    left join
                    (
                      select course_code,remark from feedback_remark_dtl 
                      where  feedback_remark_dtl.semester_type = @sem_code and feedback_remark_dtl.year_semester = @year_code   and feedback_remark_dtl.cancel_flag ='N'
                    ) as feedback_remarks on    total_allocate_course.course_code = feedback_remarks.course_code
                    )
                    order by total_allocate_course.course_code,total_allocate_course.dept_name ";

            IDataParameter para1 = DBObjectFactory.GetParameterObject();
            para1.ParameterName = "@sem_code";
            para1.DbType = DbType.String;
            para1.Value = sem_code;
            DBDataAdpterObject.SelectCommand.Parameters.Add(para1);

            IDataParameter para = DBObjectFactory.GetParameterObject();
            para.ParameterName = "@year_code";
            para.DbType = DbType.String;
            para.Value = year_code;
            DBDataAdpterObject.SelectCommand.Parameters.Add(para);

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable get_feedback_course_instructor_wise_report_for_send_pdf(string year_code, string sem_code, string dept_code, string program_level_code, string prog_code)
        {
            cmd.Parameters.Clear();

            cmd.Parameters.Add("@sem_code", SqlDbType.VarChar).Value = sem_code;
            cmd.Parameters.Add("@year_code", SqlDbType.VarChar).Value = year_code;
            cmd.Parameters.Add("@dept_code", SqlDbType.VarChar).Value = dept_code;
            cmd.Parameters.Add("@prog_code", SqlDbType.VarChar).Value = prog_code;
            cmd.Parameters.Add("@program_level_code", SqlDbType.VarChar).Value = program_level_code;

            adp = new SqlDataAdapter(cmd);

            return Get_data_from_SP_new("get_feedback_course_instructor_wise_report_for_send_pdf");
        }

