        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"select course_wise_instructor.course_code,course_wise_instructor.instructor_code,instructor_mst.instructor_name,user_mst.user_id,user_mst.mail from course_wise_instructor
                        inner join instructor_mst on course_wise_instructor.instructor_code = instructor_mst.instructor_code
                        left join user_mst on course_wise_instructor.instructor_code = user_mst.user_id
