        public DataTable get_feedback_allocate_course_wise_report(string year_code, string sem_code, string dept_code, string course_code, string program_level_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select student_course_allocate_dtl.course_code,course_mst.course_name,student_course_allocate_dtl.course_type,count(student_course_allocate_dtl.course_type) as total_course " +
                        " ,department_wise_course_dtl.dept_code from student_course_allocate_dtl inner JOIN department_wise_course_dtl on   student_course_allocate_dtl.course_code = department_wise_course_dtl.course_code " +
                        " INNER JOIN course_mst on student_course_allocate_dtl.course_code = course_mst.course_code " +
                        " where student_course_allocate_dtl.cancel_flag = 'N'  and department_wise_course_dtl.dept_code='" + dept_code + "' and student_course_allocate_dtl.semester_type = '" + sem_code + "' " +
                        " and student_course_allocate_dtl.year_semester = '" + year_code + "' and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'  " +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' ";
            //" GROUP BY student_course_allocate_dtl.course_code,course_mst.course_name,student_course_allocate_dtl.course_type,department_wise_course_dtl.dept_code order by course_code,course_mst.course_name,course_type ,department_wise_course_dtl.dept_code ";
            if (program_level_code != "" && program_level_code != null)
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code='" + program_level_code + "' ";
            }
            SqlSelect = SqlSelect + " GROUP BY student_course_allocate_dtl.course_code,course_mst.course_name,student_course_allocate_dtl.course_type,department_wise_course_dtl.dept_code order by course_code,course_mst.course_name,course_type ,department_wise_course_dtl.dept_code ";
            return Get_data(SqlSelect);
        }

