            SqlSelect = " SELECT count(b.course),count(c.code) as total,user_mst.dept_code,user_mst.prog_code from " +
                        " (SELECT user_id,COUNT(course_code) as course FROM student_course_allocate_dtl where cancel_flag ='N' and student_course_allocate_dtl.semester_type = '" + sem_code + "' and student_course_allocate_dtl.year_semester = '" + year_code + "' " +
