        public DataTable get_not_completed_feedback_report_new(string year_code, string sem_code, string dept_code, string course_code, string allocation_year)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = " SELECT count(b.course),count(c.code) as total,user_mst.dept_code,user_mst.prog_code from " +
                        " (SELECT user_id,COUNT(course_code) as course FROM student_course_allocate_dtl where cancel_flag ='N' and student_course_allocate_dtl.semester_type = '" + sem_code + "' and student_course_allocate_dtl.year_semester = '" + year_code + "' " +
                        " and course_code not in (select fds.course_code from feedback_disable_course as fds where fds.semester_type='" + sem_code + "' and fds.year_semester='" + year_code + "' and fds.cancel_flag='N') GROUP BY user_id ) as b inner JOIN " +
                        " (select user_id,COUNT(course_code )  as code from (select user_id,course_code from student_feedback_dtl where cancel_flag = 'N' and submit_status = 'Y' and student_feedback_dtl.semester_type = '" + sem_code + "' and student_feedback_dtl.year_semester = '" + year_code + "'  GROUP BY user_id,course_code ) as a " +
