            if (allocation_year != "")
            {
                SqlSelect = SqlSelect + " and user_mst.year_code ='" + allocation_year + "'";
            }

            SqlSelect = SqlSelect + " group by user_mst.dept_code,user_mst.prog_code ";

            return Get_data(SqlSelect);
        }
