        public DataTable Get_faculty_data_with_temp()
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            // SqlSelect = " Select * from instructor_mst where cancel_flag ='N' and designation NOT IN('TA','AA','AUVF') order by instructor_name";
            SqlSelect = @" Select * from instructor_mst where cancel_flag ='N' and designation NOT IN('TA','AA','AUVF','temp') 
	                       UNION 
	                       Select * from instructor_mst where cancel_flag ='N' and designation IN('temp')
	                       and (passport_no IS NOT NULL AND passport_no != '' or 
	                       pan_card_no IS NOT NULL AND pan_card_no != ''  or 
	                       aadhaar_no IS NOT NULL AND aadhaar_no != '')
                            UNION 
                           SELECT  * 
                           FROM instructor_mst 
                          WHERE designation = 'TA' AND cancel_flag ='N'
                          AND designation_letter != 'TEA'
                          AND (
                                (highest_qualification = 'UG' AND (ISNULL(TRY_CAST(total_experiance AS INT), 0)  * 12 + ISNULL(TRY_CAST(total_experiance_months AS INT), 0)) >= 60)
                             OR (highest_qualification = 'PG' AND (ISNULL(TRY_CAST(total_experiance AS INT), 0) * 12 + ISNULL(TRY_CAST(total_experiance_months AS INT), 0)) >= 24)
                              )
	                       order by instructor_name ";

            // this changes by NItinbhai 07042025 task 3435
            return Get_data(SqlSelect);
        }
