            if (sem_code == "M" && year_code == "2022")
            {
                SqlSelect = " select * from room_detail where cancel_flag='N' and semester_type ='" + sem_code + "' and year_semester='" + year_code + "' and active_flag ='ACTIVE' ";
            }
            else if (Convert.ToInt32(year_code) > 2022)
            {
                SqlSelect = " select * from room_detail where cancel_flag='N' and semester_type ='" + sem_code + "' and year_semester='" + year_code + "' and active_flag ='ACTIVE' ";
            }
            else
            {
                SqlSelect = " select * from room_detail where cancel_flag='N' and semester_type IS NULL and year_semester IS NULL ";
