        public DataTable Get_student_data_for_report(string year_code, string dept_code, string prog_code, string semester_type, string year_semester, string stud_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect += " select ISNULL(state_mst.state_name,res.state_id) as state_name,ISNULL(state_mst.state_name,res.applicant_address_state) as applicant_state_name,* from ( " +
                        " SELECT user_mst.user_id,(case ISNULL(user_contact_dtl.applicant_address_state,'')  when '' then ISNULL(user_mst.state,'') else ISNULL(user_contact_dtl.applicant_address_state,'') end) as state_id,user_name,first_name,middle_name,last_name,department_mst.dept_name,case user_mst.prog_code when '1' then 'UG' when '2' then 'PG' end as prog_code, programme_level_mst.prog_level_name + ' (' + programme_level_mst.prog_level_desc +' )' prog_level_code," +
                        " year_mst.year_desc,mail,alternet_mail ,gender,address,local_address,case country when '1' then 'India' WHEN '2' then 'Other' else  country end as country,  convert(varchar(15),dob,103) as  dob,phone_no,mobile_no,blood_group,place_of_birth,nationality,academic_prog,year_of_Enrollment,year_of_passing,name_of_university, " +
                        " full_name_of_degree,prof_exp,address_of_university,marks,about_here,case other_county when 'undefined' then '' else other_county end as other_county,emergency_contact_name,guardian_contact_name,father_name,father_contact_no,father_email,relationship_with_emergency_contact,guardian_email " +
                        " guardian_email,applicant_landline_no, applicant_mobile_no,preferred_mailing_address_house_no,guardian_name, " +
                        " guardian_address_house_no,guardian_landline_no,guardian_mobile_no,guardian_email_id,user_mst.category, reservationCategory.category_desc,user_mst.emergency_contact_2 ";

            if (semester_type != "" && year_semester != "")
            {
                SqlSelect += " ,(case ISNULL(cte1.user_id,'') when '' then (case ISNULL(cte2.user_id,'') when '' then (case ISNULL(cte3.user_id,'') when '' then '' else 'Saved' end) else 'Registered' end) else 'Allocated' end)status ";
                SqlSelect += " ,(case ISNULL(cte1.user_id,'') when '' then (case ISNULL(cte2.user_id,'') when '' then (case ISNULL(cte3.user_id,'') when '' then '' else cte3.modified_date end) else cte2.modified_date end) else cte1.modified_date end)modified_date ";
            }
            else
            {
                SqlSelect += " ,'' as status,'' as modified_date ";
            }

            SqlSelect += " ,user_contact_dtl.applicant_address_pincode,user_contact_dtl.applicant_address_city,user_contact_dtl.applicant_address_state,user_contact_dtl.applicant_address_house_no FROM user_mst inner join department_mst on user_mst.dept_code = department_mst.dept_code  " +
                        " left join user_contact_dtl on user_mst.user_id=user_contact_dtl.user_id  " +
                        " left join reservationCategory on reservationCategory.category_id = user_mst.category " +
                        " LEFT join programme_level_mst on programme_level_mst.prog_level_code = user_mst.prog_level_code " +
                        //" left join state_mst on user_contact_dtl.applicant_address_state = state_mst.state_code " +
                        " inner join year_mst on user_mst.year_code = year_mst.year_code ";

            if (semester_type != "" && year_semester != "")
            {
                //  SqlSelect += @"inner join (select user_id from student_course_allocate_dtl 
                //			            where semester_type=@semester_type and year_semester=@year_semester and cancel_flag='N' group by user_id 
                //            ) as cte1 on cte1.user_id=user_mst.user_id ";
                // SqlSelect += @"left join (select user_id from student_wise_course_dtl 
                //			            where semester_type=@semester_type and year_semester=@year_semester and cancel_flag='N' and status='R' group by user_id 
                //            ) as cte2 on cte2.user_id=user_mst.user_id 
                //            left join (select user_id from student_wise_course_dtl 
                //			            where semester_type=@semester_type and year_semester=@year_semester and cancel_flag='N' and status='S' group by user_id 
                //            ) as cte3 on cte3.user_id=user_mst.user_id ";

                SqlSelect += @" left join (select sr_no,user_id,modified_date
							from (select ROW_NUMBER() over(partition by user_id order by ISNULL(last_modified_date,created_date) desc)sr_no,
								user_id,ISNULL(last_modified_date,created_date)modified_date
								from student_course_allocate_dtl
								where semester_type='M' and year_semester='2017' and cancel_flag='N'
							)res1 where sr_no=1
					) as cte1 on cte1.user_id=user_mst.user_id 
					left join (select sr_no,user_id,modified_date
							from (select ROW_NUMBER() over(partition by user_id order by ISNULL(last_modified_date,created_date) desc)sr_no,
								user_id,ISNULL(last_modified_date,created_date)modified_date
								from student_wise_course_dtl
								where semester_type='M' and year_semester='2017' and cancel_flag='N' and status='R'
							)res2 where sr_no=1
					) as cte2 on cte2.user_id=user_mst.user_id 
					left join (select sr_no,user_id,modified_date
							from (select ROW_NUMBER() over(partition by user_id order by ISNULL(last_modified_date,created_date) desc)sr_no,
								user_id,ISNULL(last_modified_date,created_date)modified_date
								from student_wise_course_dtl
								where semester_type='M' and year_semester='2017' and cancel_flag='N' and status='S'
							)res3 where sr_no=1
					) as cte3 on cte3.user_id=user_mst.user_id ";
                // This Change Done By Nitinbhai 11072023 Change Join Inner Join to Left Join
                // again Change Done By Nitinbhai 10072024 Change Join Left Join to Inner Join
                SqlSelect += @" Inner join (select distinct (user_id) from student_course_allocate_dtl 
                                where cancel_flag ='N' and semester_type ='" + semester_type + "' and year_semester ='" + year_semester + "' ) sca on sca.user_id = user_mst.user_id";


                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@semester_type";
                para1.DbType = DbType.String;
                para1.Value = semester_type;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@year_semester";
                para2.DbType = DbType.String;
                para2.Value = year_semester;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }

            SqlSelect += " where (user_type='S' or user_type='E' ) and user_mst.user_status_flag = 'A' and user_mst.cancel_flag = 'N' and user_mst.status = 'A' ";

            if (stud_code != "")
            {
                SqlSelect = SqlSelect + " and user_mst.user_id = @stud_code ";

                IDataParameter para0 = DBObjectFactory.GetParameterObject();
                para0.ParameterName = "@stud_code";
                para0.DbType = DbType.String;
                para0.Value = stud_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para0);
            }

            if (year_code != "")
            {
                SqlSelect = SqlSelect + " and user_mst.year_code = @year_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@year_code";
                para1.DbType = DbType.String;
                para1.Value = year_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            }

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and user_mst.dept_code = @dept_code ";

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@dept_code";
                para2.DbType = DbType.String;
                para2.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }

            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and user_mst.prog_code = @prog_code ";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@prog_code";
                para3.DbType = DbType.String;
                para3.Value = prog_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            SqlSelect = SqlSelect + ") as res left join state_mst on res.state_id = state_mst.state_code ";

            if (semester_type != "" && year_semester != "")
            {
                SqlSelect += @" LEFT JOIN StudentAddressDtl as SAD on SAD.StudentCode = res.user_id 
                                and SAD.SemesterType = '" + semester_type + @"' 
                                and SAD.YearType = '" + year_semester + @"' and SAD.cancel_flag = 'N' ";
            }
            else
            {
                SqlSelect += @" LEFT JOIN StudentAddressDtl as SAD on SAD.StudentCode = res.user_id 
                                and SAD.SemesterType = (select sem_code from cept_current_semester where type_desc = 'course'and cancel_flag = 'N') 
                                and SAD.YearType = (select year_code from cept_current_semester where type_desc = 'course'and cancel_flag = 'N') and SAD.cancel_flag = 'N' ";
            }

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            return Get_data(SqlSelect);
        }

