        public DataTable get_semester_wise_student_report(string semester, string year_code, string student_enroll_year, string dept_code, string prog_code)
        {

            cmd.Parameters.Clear();

            cmd.Parameters.Add("@semester", SqlDbType.VarChar).Value = semester;
            cmd.Parameters.Add("@year_code", SqlDbType.VarChar).Value = year_code;
            cmd.Parameters.Add("@dept_code", SqlDbType.VarChar).Value = dept_code;
            cmd.Parameters.Add("@student_enroll_year", SqlDbType.VarChar).Value = student_enroll_year;
            cmd.Parameters.Add("@prog_code", SqlDbType.VarChar).Value = prog_code;

            adp = new SqlDataAdapter(cmd);

            return Get_data_from_SP_new("get_semester_wise_student_report");


        }

        public DataTable Get_fees_reminder_mail_report_data(string user_id, string sem_code, string year_code, string installment)
        {
            String SqlSelect = "";

            string dept_code = "";
            string prog_code = "";

            DataTable dt_dept_prog_dtl = get_department_wise_user_dtl(user_id, sem_code, year_code);

            if (dt_dept_prog_dtl != null)
            {
                for (int v = 0; v < dt_dept_prog_dtl.Rows.Count; v++)
                {
                    if (v == 0)
                    {
                        dept_code += "'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                        prog_code += "'" + dt_dept_prog_dtl.Rows[v]["prog_code"] + "'";
                    }
                    else
                    {
                        dept_code += ",'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                        prog_code += ",'" + dt_dept_prog_dtl.Rows[v]["prog_code"] + "'";
                    }
                }
            }

            SqlSelect = @" select um.user_id, um.user_name, pm.prog_name, dm.dept_name, um.dept_code, um.prog_code, ufid.installment1_fine, ufid.installment2_fine, ufid.installment3_fine, ufid.fees_type, ufid.installment_status, ufid.no_of_installment, ufid.fees_amount, ufid.installment1
                            , ufid.installment2, ufid.installment3, ufid.installment4, ufid.installment5, ufid.is_installment1_paid, ufid.is_installment2_paid, ufid.is_installment3_paid
                            , ufid.is_installment4_paid, ufid.is_installment5_paid
                            from user_fees_reminder_dtl ufrd
                            inner join user_mst um on um.user_id = ufrd.user_id
                            inner join department_mst dm on dm.dept_code = um.dept_code
                            inner join programme_mst pm on pm.prog_code = um.prog_code
                            left join user_fees_installment_dtl ufid on ufid.user_id = ufrd.user_id and ufid.semester_type = ufrd.semester_type and ufid.year_semester = ufrd.year_semester
                            where ufrd.semester_type = '" + sem_code + "' and ufrd.year_semester = '" + year_code + "' and ufrd.installment_no_mail = '" + installment + "' and um.dept_code in (" + dept_code + ") and um.prog_code in (" + prog_code + ")";

            return Get_data(SqlSelect);
        }

        public DataTable GetManualCCAvenuePaymentUpdate(string user_id, string sem_code, string year_code, string installment)
        {
            String SqlSelect = "";

            SqlSelect = @" SELECT user_mst.user_name, department_mst.dept_name, applicationpaymenttransaction.* FROM applicationpaymenttransaction  
                            INNER JOIN user_mst ON user_mst.user_id = applicationpaymenttransaction.user_id
                            INNER JOIN department_mst ON department_mst.dept_code = user_mst.dept_code
                            WHERE applicationpaymenttransaction.user_id IN 
                            (SELECT user_id FROM user_fees_installment_dtl WHERE semester_type='" + sem_code + "' AND year_semester='" + year_code + "'  AND cancel_flag='N' ";

            SqlSelect = SqlSelect + " and is_installment" + installment + "_paid IS NULL OR is_installment" + installment + "_paid = '') AND cash_collected_by='" + installment + "' ";

            SqlSelect = SqlSelect + " AND payment_response_code IS NULL AND semester_type='" + sem_code + "' AND year_semester='" + year_code + "' ";

            return Get_data(SqlSelect);
        }

