        public DataTable get_all_student_data_for_modification(string dept_code, string prog_code, string year_code, string prog_lvl_code = "", string student_code = "")
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @"Select *,YM.year_desc 'Y_code',dept_name 
                            from user_mst UM WITH(NOLOCK)
                            LEFT JOIN department_mst  DM WITH(NOLOCK) ON DM.dept_code=UM.dept_code
                            LEFT JOIN year_mst YM WITH(NOLOCK) ON YM.year_code = UM.year_code
                            where user_type = 'S' AND UM.cancel_flag = 'N' ";
            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and UM.dept_code = '" + dept_code + "' ";
            }

            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and prog_code = '" + prog_code + "' ";
            }

            if (year_code != "")
            {
                SqlSelect = SqlSelect + " and UM.year_code = '" + year_code + "' ";
            }
            if (student_code != "")
            {
                SqlSelect = SqlSelect + " and user_id = '" + student_code + "' ";
            }
            if (prog_lvl_code != "")
            {
                SqlSelect = SqlSelect + " and prog_level_code = '" + prog_lvl_code + "' ";
            }

            SqlSelect = SqlSelect + " order by user_id ";

            return Get_data(SqlSelect);
        }

