        public DataTable Get_program_level_data_rights_wise(string user_type, string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (user_type == "FA")
            {
                SqlSelect = " select distinct programme_level_mst.prog_level_code,prog_level_desc from programme_level_mst " +
                            " inner join department_wise_user_dtl on programme_level_mst.prog_code = department_wise_user_dtl.prog_code " +
                            " where programme_level_mst.cancel_flag='N' and department_wise_user_dtl.cancel_flag ='N'  and department_wise_user_dtl.user_id ='" + user_id + "'";
            }
            else if (user_type == "PC")
            {
                SqlSelect = " select distinct programme_level_mst.prog_level_code,prog_level_desc from programme_level_mst " +
                            " inner join  programme_coordinator_dtl on programme_level_mst.prog_code =  programme_coordinator_dtl.prog_code " +
                            " where programme_level_mst.cancel_flag='N' and programme_coordinator_dtl.cancel_flag ='N'  and  programme_coordinator_dtl.user_id ='" + user_id + "' ";
            }
            else
            {
                SqlSelect = " selecT * from programme_level_mst where cancel_flag='N'";
            }
            ServerLog.ExceptionLog("Loding Log Excuter Get Program Data  : " + SqlSelect);
            return Get_data(SqlSelect);
        }

        public string Get_programme_level_name_data(string prog_level_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select prog_level_name from programme_level_mst where cancel_flag='N' and prog_level_code = '" + prog_level_code + "'";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return "";
                else
                    return ds.Tables[0].Rows[0]["prog_level_name"].ToString();
            }
            catch (Exception ex)
            {
                return "";
            }
        }

