            para1 = DBObjectFactory.GetParameterObject();
            para1.ParameterName = "@prog_level_code";
            para1.DbType = DbType.String;
            para1.Value = prog_level_code;
            DBDataAdpterObject.SelectCommand.Parameters.Add(para1);

            return Get_data_from_SP("get_instructor_dtl_for_faculty_report");
        }

