        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"SELECT * 
                            FROM user_mst   left join programme_level_mst on user_mst.prog_level_code = programme_level_mst.prog_level_code
                            and user_mst.dept_code= programme_level_mst.dept_code
                            WHERE (user_mst.mail = '" + mail + "') and user_mst.user_status_flag='A' and user_mst.cancel_flag = 'N' and user_mst.status='A'";

