        public string Get_user_mail(string user_id)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"SELECT * 
                            FROM user_mst   
                            WHERE (user_mst.user_id = '" + user_id + "') and user_mst.user_status_flag='A' and cancel_flag = 'N' and status='A'";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
