        public DataTable get_seats_dtl_of_course(string sem_code, string dept_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "select * from department_wise_course_dtl INNER JOIN course_mst on  department_wise_course_dtl.course_code = course_mst.course_code where department_wise_course_dtl.cancel_flag = 'N' and  course_mst.cancel_flag = 'N' ";

            SqlSelect = SqlSelect + " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester ='" + year_code + "' and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester ='" + year_code + "'   ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code =@dept_code";
                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            }

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

