        public DataTable Get_user_userfees(string dept_code, string sem_code, string year_code, string prog_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = "selecT * from user_mst u  INNER JOIN  student_current_sem_dtl on u.user_id=student_current_sem_dtl.student_id " +
            //          " where u.user_type='S' and student_current_sem_dtl.semester_code=@sem_code  ";

            SqlSelect = "selecT * from user_mst u  INNER JOIN  student_current_sem_dtl on u.user_id=student_current_sem_dtl.student_code " +
                      " where u.user_type='S' and u.user_status_flag = 'A' and student_current_sem_dtl.cancel_flag = 'N' and student_current_sem_dtl.active_flag ='Y' and   student_current_sem_dtl.semester_code=@sem_code  ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + "  and u.dept_code=@dept_code";

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@dept_code";
                para2.DbType = DbType.String;
                para2.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }
            if (year_code != "")
            {
                SqlSelect = SqlSelect + "  and u.year_code=@year_code";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@year_code";
                para3.DbType = DbType.String;
                para3.Value = year_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            if (prog_code != "")
            {
                SqlSelect = SqlSelect + "  and u.prog_code=@prog_code";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@prog_code";
                para3.DbType = DbType.String;
                para3.Value = prog_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            SqlSelect = SqlSelect + " order by u.user_id";

            IDataParameter para1 = DBObjectFactory.GetParameterObject();
            para1.ParameterName = "@sem_code";
            para1.DbType = DbType.String;
            para1.Value = sem_code;
            DBDataAdpterObject.SelectCommand.Parameters.Add(para1);

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable Get_user_userfees_new(string dept_code, string sem_code, string year_code, string prog_code, string current_fees_sem, string current_fees_year)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "selecT * from user_mst u left join (select user_id,fees_status,installment_status from user_fees_status where semester_type ='" + current_fees_sem + "' and year_semester ='" + current_fees_year + "' and cancel_flag ='N') as b on u.user_id = b.user_id " +
                      " where u.user_type='S' and u.user_status_flag = 'A' and u.cancel_flag = 'N' and u.status ='A' ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + "  and u.dept_code=@dept_code";

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@dept_code";
                para2.DbType = DbType.String;
                para2.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }
            if (year_code != "")
            {
                SqlSelect = SqlSelect + "  and u.year_code=@year_code";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@year_code";
                para3.DbType = DbType.String;
                para3.Value = year_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            if (prog_code != "")
            {
                SqlSelect = SqlSelect + "  and u.prog_code=@prog_code";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@prog_code";
                para3.DbType = DbType.String;
                para3.Value = prog_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            SqlSelect = SqlSelect + " order by u.user_id";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable Get_student_fees_with_credit_choice(string dept_code, string sem_code, string year_code, string prog_code, string current_fees_sem, string current_fees_year)
        {
            cmd.Parameters.Clear();

            cmd.Parameters.Add("@sem_code", SqlDbType.VarChar).Value = sem_code;
            cmd.Parameters.Add("@year_code", SqlDbType.VarChar).Value = year_code;
            cmd.Parameters.Add("@dept_code", SqlDbType.VarChar).Value = dept_code;
            cmd.Parameters.Add("@prog_code", SqlDbType.VarChar).Value = prog_code;
            cmd.Parameters.Add("@current_fees_sem", SqlDbType.VarChar).Value = current_fees_sem;
            cmd.Parameters.Add("@current_fees_year", SqlDbType.VarChar).Value = current_fees_year;

            adp = new SqlDataAdapter(cmd);

            return Get_data_from_SP_new("get_student_fees_with_credit_choice");
        }

