            DBConnection.Open();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "update credit_choice_combination set cancel_flag ='Y' where credit_choice_combination.cancel_flag = 'N' and credit_choice_combination.semester_type = '" + sem_code + "' and credit_choice_combination.year_semester = '" + year_code + "' ";

