            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();
                return false;
            }
        }

