            SqlSelect = " select user_fees_installment_dtl.user_id,user_mst.user_name,user_mst.mail,year_mst.year_desc, " +
                        " '' as fees_status,department_mst.dept_name,programme_level_mst.prog_level_desc,fees_bank_dtl.fees as fees_payable,res1.allocated_credits " +
                        " from user_fees_installment_dtl " +
                        " inner join user_mst on user_fees_installment_dtl.user_id = user_mst.user_id " +
                        " inner join department_mst on user_mst.dept_code = department_mst.dept_code " +
                        " inner join year_mst on user_mst.year_code = year_mst.year_code " +
                        " left join programme_level_mst on user_mst.prog_level_code = programme_level_mst.prog_level_code " +
                        " inner join fees_bank_dtl on fees_bank_dtl.semester_type=user_fees_installment_dtl.semester_type  " +
                        " and fees_bank_dtl.year_semester=user_fees_installment_dtl.year_semester " +
                        " and fees_bank_dtl.dept_code=user_mst.dept_code " +
                        " and fees_bank_dtl.prog_code=user_mst.prog_code " +
                        " and fees_bank_dtl.year_code=user_mst.year_code " +
                        " and fees_bank_dtl.gender=user_mst.gender ";


            if (sem_code == "M" && year_code == "2023")
            {
                SqlSelect += @" and (ISNULL(fees_bank_dtl.nationality,'') = (select  Case ISNULL(nationality,'I') 
			            			When 'I' Then '' when 'India' Then '' When 'Indian' Then ''  
			            			Else 'International'  End  as nationality from user_mst where user_type ='S' and user_id = user_fees_installment_dtl.user_id))";
            }
            else if (Convert.ToInt32(year_code) > Convert.ToInt32("2023"))
            {
                SqlSelect += @" and (ISNULL(fees_bank_dtl.nationality,'') = (select  Case ISNULL(nationality,'I') 
			            			When 'I' Then '' when 'India' Then '' When 'Indian' Then ''  
			            			Else 'International'  End  as nationality from user_mst where user_type ='S' and user_id = user_fees_installment_dtl.user_id))";

            }

            // " and (ISNULL(fees_bank_dtl.nationality,'') = (select  Case ISNULL(nationality,'I') " +
            // " When 'I' Then '' when 'India' Then '' WHen 'Indian' Then '' " +
            // " Else 'International'  End  as nationality from user_mst where user_type ='S' and user_id = user_fees_installment_dtl.user_id))" +

            SqlSelect += " left join (select user_id,SUM(CAST(credits as int))allocated_credits from student_course_allocate_dtl " +
                        "             where semester_type='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag ='N' " +
                        "             group by user_id " +
                        " )res1 on res1.user_id=user_mst.user_id " +
                        " where user_fees_installment_dtl.semester_type='" + sem_code + "' and user_fees_installment_dtl.year_semester ='" + year_code + "' " +
                        " and user_mst.cancel_flag ='N' and user_fees_installment_dtl.cancel_flag ='N' " +
                        " and is_installment" + installment_no + "_paid='Y' order by department_mst.dept_name,programme_level_mst.prog_level_desc ";

            return Get_data(SqlSelect);
        }

