        public DataTable Get_all_fees_payment_installment_data_installment_wise(string sem_code, string year_code, string installment_no, string user_id, string user_type)
        {
            String SqlSelect = "";
            //uffd.installment_fine,
            SqlSelect = @" select apt.created_date as fees_paid_date,apt.created_date as fees_paid_date,ufi.*,apt.*, um.user_name, um.prog_desc, um.middle_name, um.first_name, um.dept_code,
			um.prog_code,um.year_code,um.prog_level_code,plm.prog_level_name,std.name_of_the_degree,dm.dept_name
			from user_fees_installment_dtl as ufi
			inner join user_mst as um on um.user_id=ufi.user_id
			inner join ApplicationPaymentTransaction as apt on apt.user_id=ufi.user_id
						and apt.semester_type=ufi.semester_type and apt.year_semester=ufi.year_semester ";
            //left join user_fees_fine_dtl as uffd on uffd.user_id=ufi.user_id
            //and uffd.semester_type = ufi.semester_type and uffd.year_semester = ufi.year_semester and uffd.installment_no = '" + installment_no + "' and uffd.is_paid_installment_fine = 'Y' and uffd.cancel_flag = 'N'

            SqlSelect = SqlSelect + @"left join department_mst as dm on dm.dept_code = um.dept_code 
			left join programme_level_mst as plm on plm.prog_level_code = um.prog_level_code
			left join student_transcript_dtl as std on std.user_id = um.user_id
			where ufi.semester_type='" + sem_code + "' and ufi.year_semester='" + year_code + "' and ufi.cancel_flag='N' " +
            " and ufi.is_installment" + installment_no + "_paid='Y' and apt.payment_response_code='0' and apt.cash_collected_by='" + installment_no + "' ";

            if (user_type == "S")
            {
                SqlSelect = SqlSelect + " and um.user_id='" + user_id + "' ";
            }

            return Get_data(SqlSelect);
        }

        public DataTable Get_online_fees_status_installment(string sem_code, string year_code, string installment_no)
        {
            String SqlSelect = "";

            SqlSelect = " select convert(varchar(10),created_date,103) as date,* " +
                        " from applicationpaymenttransaction " +
                        " where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and payment_response_code = '0' ";

            if (installment_no != "")
            {
                SqlSelect = " and cash_collected_by = '" + installment_no + "' ";
            }

            return Get_data(SqlSelect);
        }

        public DataTable get_user_upload_payslip_data_report_installment(string sem_code, string year_code, string installment_no)
        {
            String SqlSelect = "";

            SqlSelect = " select uu.*,um.user_name,pm.prog_name + ' in ' + dm.dept_name as prog_name,bank_branch_mst.branch " +
                        " from user_installment_payslip_dtl as uu " +
                        " inner join user_mst as um on uu.user_id = um.user_id " +
                        " inner join department_mst as dm on um.dept_code = dm.dept_code " +
                        " inner join programme_mst as pm on um.prog_code = pm.prog_code " +
                        " inner join bank_branch_mst on uu.branch_name = bank_branch_mst.sol_id " +
                        " where  uu.cancel_flag = 'N' and uu.semester_type = '" + sem_code + "' and uu.year_semester ='" + year_code + "' " +
                        " and um.user_status_flag = 'A' and uu.is_admin_approved = 'A' and installment_no = '" + installment_no + "' ";

            return Get_data(SqlSelect);
        }

        public DataTable get_registered_user_dtl(string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select distinct um.user_id,um.dept_code,um.prog_code,um.year_code
                        from student_wise_course_dtl as swc
                        inner join user_mst as um on um.user_id=swc.user_id
                        where swc.semester_type='" + sem_code + "' and swc.year_semester='" + year_code + "' ";

            return Get_data(SqlSelect);
        }

