        public Boolean update_instructor_new_ta_vf(string user_id, string host_name, string instructor_code, string instructor_name, string cancel_flag, string email, string user_type, string des_letter, string instructor_first_name = "", string instructor_last_name = "")
        {

            DataTable dt_instructor_dtl = get_instructor_dtl(instructor_code);
            string vf_code = "";

            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
