            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            string designation = "";

            if (user_type == "VF")
            {
                user_type = "I2";
                designation = "VF";

                if (dt_instructor_dtl != null)
                {
                    //if (dt_instructor_dtl.Rows[0]["VF_code"].ToString() == "")
                    //{
                    DataTable dt_last_vf_code_dtl = get_last_vf_code();
                    string year = DateTime.Now.Year.ToString();

                    if (dt_last_vf_code_dtl != null)
                    {
                        vf_code = "VF" + year.Substring(2) + (Convert.ToInt32(dt_last_vf_code_dtl.Rows[0]["VF_code"].ToString().Substring(4)) + 1).ToString("000");
                    }
                    else
                    {
                        vf_code = "VF" + year.Substring(2) + "001";
                    }
                    //}
                    //else
                    //{
                    //    vf_code = dt_instructor_dtl.Rows[0]["VF_code"].ToString();
                    //}
                }
            }
