                    {
                        vf_code = "VF" + year.Substring(2) + (Convert.ToInt32(dt_last_vf_code_dtl.Rows[0]["VF_code"].ToString().Substring(4)) + 1).ToString("000");
                    }
                    else
                    {
                        vf_code = "VF" + year.Substring(2) + "001";
                    }
                }
                else if (user_type == "AA")
                {
                    DataTable dt_last_aa_code_dtl = get_last_aa_code();

                    user_type = "I2";
                    designation = "AA";

                    string year = DateTime.Now.Year.ToString();
                    if (dt_last_aa_code_dtl != null)
                    {
                        vf_code = "AA" + year.Substring(2) + (Convert.ToInt32(dt_last_aa_code_dtl.Rows[0]["VF_code"].ToString().Substring(4)) + 1).ToString("000");
                    }
                    else
                    {
                        vf_code = "AA" + year.Substring(2) + "001";
                    }
                }
                else if (user_type == "TA")
                {
                    DataTable dt_last_ta_code_dtl = get_last_ta_code();

                    user_type = "I2";
                    designation = "TA";

                    string year = DateTime.Now.Year.ToString();
                    if (dt_last_ta_code_dtl != null)
                    {
                        vf_code = "TA" + year.Substring(2) + (Convert.ToInt32(dt_last_ta_code_dtl.Rows[0]["VF_code"].ToString().Substring(4)) + 1).ToString("000");
                    }
                    else
                    {
                        vf_code = "TA" + year.Substring(2) + "001";
                    }
                }
                else if (user_type == "AUVF")
                {
                    user_type = "I2";
                    designation = "AUVF";
                }
                else
                {
                    designation = "instructor";
                }

                //Check Duplicate Data For VF Code 
                if (vf_code != "")
                {
                    DataTable dt_check_status = GetDataForVFCodeWise(vf_code);
                    if (dt_check_status != null)
                    {
                        if (DBCommand.Transaction != null)
                            DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open)
                            DBConnection.Close();

                        return false;
                    }
                }

                //SQLInsert.Append("insert into instructor_mst(doc_no,instructor_code,user_id,instructor_name,cancel_flag,created_by,created_date,created_host," +
                //    " designation,VF_code,designation_letter) " +
                //    " VALUES('" + DocNo + "' , '" + DocNo + "',  '" + DocNo + "','" + instructor_name + "' ,'N','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' , '" + host_name + "','" + designation + "','" + vf_code + "','" + des_letter + "' )");

                SQLInsert.Append("insert into instructor_mst(doc_no,instructor_code,user_id,instructor_name," +
                    (instructor_first_name != null && instructor_first_name != "" ? "first_name," : "") +
                        (instructor_last_name != null && instructor_last_name != "" ? "last_name," : "") +
                        (mail != null && mail != "" ? "mail," : "") +
                    "cancel_flag,created_by,created_date,created_host," +
                    " designation,VF_code,designation_letter) " +
                    " VALUES('" + DocNo + "' , '" + DocNo + "',  '" + DocNo + "','" + instructor_name + "', " +
                    (instructor_first_name != null && instructor_first_name != "" ? "'" + instructor_first_name + "'," : "") +
                    (instructor_last_name != null && instructor_last_name != "" ? " '" + instructor_last_name + "'," : "") +
                    (mail != null && mail != "" ? "'" + mail + "'," : "") +
                    "'N','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' , '" + host_name + "','" + designation + "','" + vf_code + "'," +
                    (des_letter != "" && des_letter != null ? "'" + des_letter + "' " : " null ") +
                    ")");


                if (mail != "")
                {
                    // SQLInsert.Append("insert into user_mst(doc_no,user_id,user_name,user_type,student_no,full_name,password,mail,start_date,pass_expiry_date,user_status_flag," +
                    // " cancel_flag,created_by,created_date,created_host,status) " +
                    // " VALUES('" + DocNo + "' , '" + DocNo + "', '" + instructor_name + "','" + user_type + "' ,'" + DocNo + "'," +
                    // " '" + instructor_name + "', 'YWRtaW4=' ,'" + mail + "' ,'" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'  ," +
                    // " '" + DateTime.Now.AddYears(5).ToString("yyyy/MM/dd HH:mm:ss") + "' ,'A','N','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + host_name + "','A' )");

                    SQLInsert.Append("insert into user_mst(doc_no,user_id,user_name," +
                              (instructor_first_name != null && instructor_first_name != "" ? "first_name," : "") +
                              (instructor_last_name != null && instructor_last_name != "" ? "last_name," : "") +
                              "user_type,student_no,full_name,password,mail,start_date,pass_expiry_date,user_status_flag," +
                          " cancel_flag,created_by,created_date,created_host,status) " +
                          " VALUES('" + DocNo + "' , '" + DocNo + "', '" + instructor_name + "'," +
                          (instructor_first_name != null && instructor_first_name != "" ? " '" + instructor_first_name + "', " : "") +
                          (instructor_last_name != null && instructor_last_name != "" ? "'" + instructor_last_name + "'," : "") +
                          "'" + user_type + "' ,'" + DocNo + "'," +
                          " '" + instructor_name + "', 'YWRtaW4=' ,'" + mail + "' ,'" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'  ," +
                          " '" + DateTime.Now.AddYears(5).ToString("yyyy/MM/dd HH:mm:ss") + "' ,'A','N','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + host_name + "','A' )");

                }
                if (designation != "AUVF")
                {
                    SqlSelect = "insert into user_group(user_id,group_id,user_type,status,created_by,created_date,created_host) VALUES('" + DocNo + "' , ";

                    if (user_type == "I2")
                    {
                        SqlSelect = SqlSelect + "'faculty', ";
                    }
                    else if (user_type == "D")
                    {
                        SqlSelect = SqlSelect + "'dean', ";
                    }
                    else if (user_type == "PC")
                    {
                        SqlSelect = SqlSelect + "'pc', ";
                    }

                    SqlSelect = SqlSelect + "'" + user_type + "' ,'A','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + host_name + "')";

                    SQLInsert.Append(SqlSelect);
                }

                DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body("Instructor", "email");
                DataTable dept_dtl = get_faculty_name_department_wise(user_id);
                if (AckDetails != null)
                {
                    EncodingDecoding encoding_decoding = new EncodingDecoding();
                    string password = encoding_decoding.DecryptData("YWRtaW4=");
                    instructor_code = DocNo;
                    Mail objmail = new Mail();


                    //status = objmail.SendEmailNewInstructor(AckDetails, instructor_name, mail, instructor_code, password, dept_dtl);
                    status = true;
                }
                if (status)
                {
                    DBCommand.CommandText = SQLInsert.ToString();
                    //Establish connecton.
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    DBConnection.Open();
                    //Begin Transaction.
                    DBCommand.Transaction = DBConnection.BeginTransaction();

                    int NoOfRowsUpdated = DBCommand.ExecuteNonQuery();
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return true;
                }
                else
                {
                    if (DBCommand.Transaction != null)
                        DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open)
                        DBConnection.Close();
                    return false;

                }
            }
            catch (Exception ex)
            {
                if (DBCommand.Transaction != null)
                    DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open)
                    DBConnection.Close();

                return false;
            }
            finally
            {
                if (DBConnection.State == ConnectionState.Open)
                    DBConnection.Close();

            }
        }

