        public Boolean insert_update_fine_dtl(string host_user_id, string host_name, string semeter_type, string year_code, string user_id, string remarks, string installmentfine, string installment_no)
        {

            String SqlSelect = "";
            Boolean status = false;
            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            StringBuilder SQLSelect = new StringBuilder();

            DBCommand = DBObjectFactory.GetCommandObject();
            DBCommand.Connection = DBConnection;

            DBCommand.Parameters.Clear();
            StringBuilder SQLInsert = new StringBuilder();
            try
            {
                DataTable dt = get_student_fine_dtl(semeter_type, year_code, user_id, installment_no);

                SQLInsert.Append("UPDATE user_fees_fine_dtl SET cancel_flag = 'Y', last_modified_by ='" + host_name + "', last_modified_date ='" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', last_modified_host = '" + host_user_id + "' " +
                                " where semester_type ='" + semeter_type + "' and year_semester ='" + year_code + "' and user_id ='" + user_id + "' and installment_no ='" + dt.Rows[0]["installment_no"] + "' and cancel_flag = 'N'");

                SqlSelect = "INSERT INTO user_fees_fine_dtl (user_id,installment_no,installment_fine,request_status, remarks,paid_installment_fine,is_paid_installment_fine,is_remains_fine_amount_paid,payslip_generated_date," +
                            " is_admin,cancel_flag,semester_type,year_semester,created_by,created_date,created_host,last_modified_by,last_modified_date,last_modified_host )" +
                            " VALUES('" + dt.Rows[0]["user_id"] + "','" + dt.Rows[0]["installment_no"] + "',";

                if (installmentfine != string.Empty && installmentfine != null)
                {
                    SqlSelect = SqlSelect + "'" + installmentfine + "',";
                }
                else
                {
                    if (dt.Rows[0]["installment_fine"].ToString() == System.DBNull.Value.ToString())
                    {
                        SqlSelect = SqlSelect + "NULL,";
                    }
                    else
                    {
                        SqlSelect = SqlSelect + "'" + dt.Rows[0]["installment_fine"] + "',";
                    }

                }
                SqlSelect = SqlSelect + "'" + dt.Rows[0]["request_status"] + "',";

                if (remarks != string.Empty && remarks != null)
                {
                    SqlSelect = SqlSelect + "'" + remarks + "',";
                }
                else
                {
                    if (dt.Rows[0]["remarks"].ToString() == System.DBNull.Value.ToString())
                    {
                        SqlSelect = SqlSelect + "NULL,";
                    }
                    else
                    {
                        SqlSelect = SqlSelect + "'" + dt.Rows[0]["remarks"] + "',";
                    }
                }

                if (dt.Rows[0]["paid_installment_fine"].ToString() == System.DBNull.Value.ToString())
                {
                    SqlSelect = SqlSelect + "NULL,";
                }
                else
                {
                    SqlSelect = SqlSelect + "'" + dt.Rows[0]["paid_installment_fine"] + "',";
                }

                if (dt.Rows[0]["is_paid_installment_fine"].ToString() == System.DBNull.Value.ToString())
                {
                    SqlSelect = SqlSelect + "NULL,";
                }
                else
                {
                    SqlSelect = SqlSelect + "'" + dt.Rows[0]["is_paid_installment_fine"] + "',";
                }

                if (dt.Rows[0]["is_remains_fine_amount_paid"].ToString() == System.DBNull.Value.ToString())
                {
                    SqlSelect = SqlSelect + "NULL,";
                }
                else
                {
                    SqlSelect = SqlSelect + "'" + dt.Rows[0]["is_remains_fine_amount_paid"] + "',";
                }

                if (dt.Rows[0]["payslip_generated_date"].ToString() == System.DBNull.Value.ToString())
                {
                    SqlSelect = SqlSelect + "NULL,";
                }
                else
                {
                    SqlSelect = SqlSelect + "'" + dt.Rows[0]["payslip_generated_date"] + "',";
                }
                SqlSelect = SqlSelect + "'Y','N','" + dt.Rows[0]["semester_type"] + "','" + dt.Rows[0]["year_semester"] + "','" + host_user_id + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "',NULL,NULL,NULL)";

                SQLInsert.Append(SqlSelect);

                DBCommand.CommandText = SQLInsert.ToString();

                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                DBConnection.Open();

                DBCommand.Transaction = DBConnection.BeginTransaction();

                int NoOfRowsUpdated = DBCommand.ExecuteNonQuery();
                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;

            }
            catch (Exception ex)
            {
                if (DBCommand.Transaction != null)
                    DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open)
                    DBConnection.Close();

                return false;
            }
            finally
            {
                if (DBConnection.State == ConnectionState.Open)
                    DBConnection.Close();

            }
        }

