            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                DS_UserFeesReminder server_user_fees_reminderr = (DS_UserFeesReminder)ds_UploadData;

                DS_UserFeesReminder user_fees_reminder = new DS_UserFeesReminder();

                user_fees_reminder.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_user_fees_reminderr.user_fees_reminder_dtl.Rows.Count; mprCnt++)
                {
                    user_fees_reminder.user_fees_reminder_dtl.ImportRow(server_user_fees_reminderr.user_fees_reminder_dtl.Rows[mprCnt]);
                }

                user_fees_reminder.EnforceConstraints = true;

                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, user_fees_reminder.user_fees_reminder_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != user_fees_reminder.user_fees_reminder_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }

            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                objBLReturnObject.ServerMessage = ex.ToString();
            }
            return objBLReturnObject;
        }

