                        " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code" +
                        " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and  dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'" +
                        " )course_det" +
                        " inner join (select course_wise_instructor.*,instructor_mst.user_id,instructor_mst.instructor_name from course_wise_instructor" +
                        " inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code" +
                        " where instructor_mst.user_id='" + user_id + "' and course_wise_instructor.semester_type = '" + sem_code + "' and year_semester ='" + year_code + "'" +
                        " )mycourse on course_det.course_code=mycourse.course_code ORDER BY course_det.course_code";

            return Get_data(SqlSelect);
        }

