        public DataTable get_my_current_course_list_new(string user_id, string sem_code, string year_code, string prog_code, string prog_level_code, string user_type, string dept_code)//Ananth 25042019
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (user_type == "I2")
            {
                SqlSelect = " select course_det.*,mycourse.user_id,mycourse.instructor_name,mycourse.designation from" +
                            " (SELECT course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                            " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                            " (case course_mst.faculty_approved when 'Y' then 'Approved' else 'Not Approved' end) as 'faculty_approval'," +
                            " (case course_mst.progcoordinate_approved when 'Y' then 'Approved' else 'Not Approved' end) as 'progcoord_approval'," +
                            " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else 'Not Approved' end) as 'ugpg_approval'," +
                            " course_mst.faculty_approved,course_mst.progcoordinate_approved,course_mst.ugpgoffice_approved,course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year, " +
                            " course_mst.week1,course_mst.week2,course_mst.week3,course_mst.week4,course_mst.week5,course_mst.week6,course_mst.week7,course_mst.week8, " +
                            " course_mst.week9,course_mst.week10,course_mst.week11,course_mst.week12,course_mst.week13,course_mst.week14,course_mst.week15,course_mst.week16,course_mst.course_structure,course_mst.eval_method1 " +
                            " ,week_reference1,week_reference2,week_reference3,week_reference4,week_reference5,week_reference6,week_reference7,week_reference8,week_reference9,week_reference10, " +
                            " week_reference11,week_reference12,week_reference13,week_reference14,week_reference15,week_reference16,course_mst.backlog,dwc.sub_category_id,course_mst.studio_mode, Case When saim.designation ='VF' Then 'True' Else 'False' ENd as  studio_per_dtl_status, " +
                            " CONCAT(COALESCE(dwc.focus_studio, ''), CASE WHEN dwc.focus_studio IS NOT NULL AND dwc.secondary_focus_studio IS NOT NULL THEN ', ' ELSE '' END, COALESCE(dwc.secondary_focus_studio, '')) As Focuse,course_mst.CouseSubTitle " +
                            " FROM course_mst " +
                            " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code" +
                            " left join Studio_Applicant_Instructor_Mst saim on saim.semester_type = course_mst.semester_type  " +
                            " and saim.year_semester = course_mst.year_semester and saim.instructor_code = '" + user_id + "' and saim.cancel_flag='N' and saim.designation ='VF' " +
                            " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.progcoordinate_approved in ('N','Y') " +//and course_mst.progcoordinate_approved = 'N'
                            " and  dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'";
            }
            else
            {
                SqlSelect = " select course_det.*,mycourse.user_id,mycourse.instructor_name,mycourse.designation from" +
                            " (SELECT course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                            " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                            " (case course_mst.faculty_approved when 'Y' then 'Approved' else 'Not Approved' end) as 'faculty_approval'," +
                            " (case course_mst.progcoordinate_approved when 'Y' then 'Approved' else 'Not Approved' end) as 'progcoord_approval'," +
                            " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else 'Not Approved' end) as 'ugpg_approval'," +
                            " course_mst.faculty_approved,course_mst.progcoordinate_approved,course_mst.ugpgoffice_approved,course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year, " +
                            " course_mst.week1,course_mst.week2,course_mst.week3,course_mst.week4,course_mst.week5,course_mst.week6,course_mst.week7,course_mst.week8, " +
                            " course_mst.week9,course_mst.week10,course_mst.week11,course_mst.week12,course_mst.week13,course_mst.week14,course_mst.week15,course_mst.week16,course_mst.course_structure,course_mst.eval_method1 " +
                            " ,week_reference1,week_reference2,week_reference3,week_reference4,week_reference5,week_reference6,week_reference7,week_reference8,week_reference9,week_reference10, " +
                            " week_reference11,week_reference12,week_reference13,week_reference14,week_reference15,week_reference16,course_mst.backlog,dwc.sub_category_id,course_mst.studio_mode, Case When saim.designation ='VF' Then 'True' Else 'False' ENd as  studio_per_dtl_status," +
                            " CONCAT(COALESCE(dwc.focus_studio, ''), CASE WHEN dwc.focus_studio IS NOT NULL AND dwc.secondary_focus_studio IS NOT NULL THEN ', ' ELSE '' END, COALESCE(dwc.secondary_focus_studio, '')) As Focuse,course_mst.CouseSubTitle " +
                            " FROM course_mst " +
                            " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code" +
                            " left join Studio_Applicant_Instructor_Mst saim on saim.semester_type = course_mst.semester_type  " +
                            " and saim.year_semester = course_mst.year_semester and saim.instructor_code = '" + user_id + "' and saim.cancel_flag='N' and saim.designation ='VF' " +
                            " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                            " and  dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'";
            }

            if (prog_code != "")
            {
                //SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
            }
            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
            }
            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and dwc.dept_code ='" + dept_code + "' ";
            }

            SqlSelect = SqlSelect + " )course_det" +
                      " inner join (select course_wise_instructor.*,instructor_mst.user_id,instructor_mst.instructor_name,instructor_mst.designation from course_wise_instructor" +
                      " inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code" +
                      " where instructor_mst.user_id='" + user_id + "' and course_wise_instructor.semester_type = '" + sem_code + "' and course_wise_instructor.year_semester ='" + year_code + "'" +
                      " )mycourse on course_det.course_code=mycourse.course_code ";

            string temp_str = SqlSelect;

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_AA");

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_TA");

            SqlSelect = SqlSelect + " ORDER BY course_det.course_code ";

            return Get_data(SqlSelect);
        }

