                            " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year, " +

                            " course_mst.week1,course_mst.week2,course_mst.week3,course_mst.week4,course_mst.week5,course_mst.week6,course_mst.week7,course_mst.week8, " +
                            " course_mst.week9,course_mst.week10,course_mst.week11,course_mst.week12,course_mst.week13,course_mst.week14,course_mst.week15,course_mst.week16,course_mst.course_structure,dwc.course_typology,course_mst.eval_method1," +
                            " CONCAT(COALESCE(dwc.focus_studio, ''), CASE WHEN dwc.focus_studio IS NOT NULL AND dwc.secondary_focus_studio IS NOT NULL THEN ', ' ELSE '' END, COALESCE(dwc.secondary_focus_studio, '')) As Focuse " +

                            " FROM course_mst " +
                            " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code" +
                            " inner join dean_dtl on dean_dtl.dept_code = dwc.dept_code " +
                            " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                            " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'" +
                            " and dean_dtl.user_id='" + uid + "' and dean_dtl.semester_type = '" + sem_code + "' and dean_dtl.year_semester = '" + year_code + "'" +
                            " ORDER BY course_mst.course_code";
            }
            else if (utype == "FA")
            {
                SqlSelect = "SELECT course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week," +
                            " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                            " course_mst.faculty_approved,course_mst.progcoordinate_approved,course_mst.ugpgoffice_approved," +
                            " (case course_mst.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval'," +
                            " (case course_mst.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoord_approval'," +
                            " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year, " +

                            " course_mst.week1,course_mst.week2,course_mst.week3,course_mst.week4,course_mst.week5,course_mst.week6,course_mst.week7,course_mst.week8, " +
                            " course_mst.week9,course_mst.week10,course_mst.week11,course_mst.week12,course_mst.week13,course_mst.week14,course_mst.week15,course_mst.week16,course_mst.course_structure,dwc.course_typology,course_mst.eval_method1," +
                            " CONCAT(COALESCE(dwc.focus_studio, ''), CASE WHEN dwc.focus_studio IS NOT NULL AND dwc.secondary_focus_studio IS NOT NULL THEN ', ' ELSE '' END, COALESCE(dwc.secondary_focus_studio, '')) As Focuse " +

                            " FROM course_mst " +
                            " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code" +
                            " inner join department_wise_user_dtl on department_wise_user_dtl.dept_code = dwc.dept_code " +
                            " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                            " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'" +
                            " and department_wise_user_dtl.user_id='" + uid + "' and department_wise_user_dtl.user_type = 'FA' and department_wise_user_dtl.semester_type = '" + sem_code + "' and department_wise_user_dtl.year_semester = '" + year_code + "'" +
                            " ORDER BY course_mst.course_code";
            }

            return Get_data(SqlSelect);
        }

