        //coordinater approve course then show the data (only A1 User Type) </Last Changes>(06012021)
        //*************Commends************************//
        public DataTable get_approved_course_list_new(string uid, string utype, string user_prog_code, string sem_code, string year_code, string prog_code, string prog_level_code, string dept_code)//Ananth 25042019
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (utype == "A1")
            {
                SqlSelect = "SELECT course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                            " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                            " course_mst.faculty_approved,course_mst.progcoordinate_approved,course_mst.ugpgoffice_approved," +
                            " (case course_mst.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval'," +
                            " (case course_mst.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoord_approval'," +
                            " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year, " +

                            " course_mst.week1,course_mst.week2,course_mst.week3,course_mst.week4,course_mst.week5,course_mst.week6,course_mst.week7,course_mst.week8, " +
                            " course_mst.week9,course_mst.week10,course_mst.week11,course_mst.week12,course_mst.week13,course_mst.week14,course_mst.week15,course_mst.week16,course_mst.course_structure,dwc.course_typology,course_mst.eval_method1 " +
                            " ,week_reference1,week_reference2,week_reference3,week_reference4,week_reference5,week_reference6,week_reference7,week_reference8,week_reference9,week_reference10, " +
                            " week_reference11,week_reference12,week_reference13,week_reference14,week_reference15,week_reference16,course_mst.backlog,dwc.sub_category_id,course_mst.studio_mode, " +
                            " CONCAT(COALESCE(dwc.focus_studio, ''), CASE WHEN dwc.focus_studio IS NOT NULL AND dwc.secondary_focus_studio IS NOT NULL THEN ', ' ELSE '' END, COALESCE(dwc.secondary_focus_studio, '')) As Focuse,course_mst.CouseSubTitle " +

