        public string inital_approve_course_I2(String d_course_code, String semester, String year, String user_id)
        {
            String SqlSelect = "";
            int result = 0;

            SqlSelect = "update course_mst set last_modified_by = '" + user_id + "', progcoordinate_approved ='N', last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where semester_type ='" + semester + "' and year_semester ='" + year + "' and course_code ='" + d_course_code + "' ";

            DBCommand.CommandText = SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();
                result = DBCommand.ExecuteNonQuery();
            }
            catch (Exception ex)
            {
                //return null;
                return "false";
            }
            DBConnection.Close();
            if (result > 0)
            {
                return "true";
            }
            else
            {
                return "false";
            }
        }

