                            " inner join department_wise_user_dtl on department_wise_user_dtl.dept_code = dwc.dept_code " +
                            " and department_wise_user_dtl.prog_code=dwc.prog_code and department_wise_user_dtl.semester_type=dwc.semester_type  and department_wise_user_dtl.year_semester = dwc.year_semester " +
                            " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                            " and (course_mst.progcoordinate_approved = 'N' or course_mst.progcoordinate_approved = 'Y') and (course_mst.faculty_approved = 'N' or course_mst.faculty_approved = 'Y') and (course_mst.ugpgoffice_approved='N' or course_mst.ugpgoffice_approved='Y') and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'" +
                            " and department_wise_user_dtl.user_id='" + uid + "' and department_wise_user_dtl.user_type = 'FA' and department_wise_user_dtl.semester_type = '" + sem_code + "' and department_wise_user_dtl.year_semester = '" + year_code + "'";
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }
                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.dept_code ='" + dept_code + "' ";
                }
                // New Development For Studio Brief Only Course Offered Tag Not Showing 
                // Course_Mst Facualty Approved (P) and instructor_studio_details(isd.studio_brief_status ='S')  Date 04062021
                DataTable dataTable_ = get_studio_course_save_mode(sem_code, year_code);
                if (dataTable_ != null)
                {

                    SqlSelect = SqlSelect + " and course_mst.course_code not in (select course_mst.course_code from course_mst inner join instructor_studio_details as isd on isd.course_code = course_mst.course_code and isd.semester_type = course_mst.semester_type" +
                        " and isd.year_semester = course_mst.year_semester " +
                        " where isd.cancel_flag='N' and (isd.studio_brief_status ='S' or isd.studio_brief_status ='Y') and course_mst.faculty_approved='P' and isd.semester_type ='" + sem_code + "' and isd.year_semester='" + year_code + "' and course_mst.cancel_flag ='Y') ";
                }
                SqlSelect = SqlSelect + " ORDER BY course_mst.course_code";
            }

            return Get_data(SqlSelect);
        }


