        public DataTable get_inital_pending_course(string uid, string utype, string user_prog_code, string sem_code, string year_code, string prog_code, string prog_level_code, string dept_code)//Ananth 25042019
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (utype == "PC")
            {
                SqlSelect = "SELECT distinct course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                            " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                            " course_mst.faculty_approved,course_mst.progcoordinate_approved as pflag,course_mst.ugpgoffice_approved,course_mst.backlog," +

                            " (case course_mst.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval'," +
                            " (case course_mst.progcoordinate_approved when 'P' then 'Approved' else '' end) as 'progcoord_approval'," +
                            " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year,course_mst.backlog,dwc.sub_category_id,course_mst.studio_mode,studio_brief_status='NULL' " +
                            " ,CONCAT(COALESCE(dwc.focus_studio, ''), CASE WHEN dwc.focus_studio IS NOT NULL AND dwc.secondary_focus_studio IS NOT NULL THEN ', ' ELSE '' END, COALESCE(dwc.secondary_focus_studio, '')) As Focuse,course_mst.CouseSubTitle " +
                            "  FROM course_mst " +
                            " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code and dwc.semester_type = course_mst.semester_type and dwc.year_semester = course_mst.year_semester " +
                            " inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code=dwc.prog_code and pcd.semester_type=dwc.semester_type and pcd.year_semester = dwc.year_semester " +

                            " where course_mst.cancel_flag='Y' and course_mst.semester_type ='" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                            " and (course_mst.ugpgoffice_approved = 'N' or course_mst.ugpgoffice_approved is null or course_mst.ugpgoffice_approved = '')" +
                            " and (course_mst.faculty_approved = 'N' or course_mst.faculty_approved is null or course_mst.faculty_approved = '' or course_mst.faculty_approved = 'Y')" +
                            " and (course_mst.progcoordinate_approved = 'P' or course_mst.progcoordinate_approved is null or course_mst.progcoordinate_approved = '')" +

                            " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'" +
                            " and pcd.prog_code=dwc.prog_code " +
                            " and pcd.semester_type = '" + sem_code + "' and pcd.year_semester = '" + year_code + "' " +
                            " and pcd.cancel_flag='N' and ISNULL(dwc.prog_level_code,'')=ISNULL(pcd.prog_level_code,'') and pcd.user_id = '" + uid + "'";


                //if (prog_code != "")
                //{
                //    SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
                //}
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }

                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.dept_code ='" + dept_code + "' ";
                }
                SqlSelect = SqlSelect + " ORDER BY course_mst.course_code";
            }
            else
            {
                //SqlSelect = "SELECT distinct course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                //                " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                //                " course_mst.faculty_approved,course_mst.progcoordinate_approved as pflag,course_mst.ugpgoffice_approved,course_mst.backlog," +
                //                " (case course_mst.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval'," +
                //                " (case course_mst.progcoordinate_approved when 'P' then 'Approved' else '' end) as 'progcoord_approval'," +
                //                " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                //                " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year" +
                //                " FROM course_mst " +
                //                " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code" +

                //                " where course_mst.cancel_flag='Y' and course_mst.created_by = '" + uid + "' and course_mst.semester_type ='" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                //                " and (course_mst.ugpgoffice_approved = 'N' or course_mst.ugpgoffice_approved is null or course_mst.ugpgoffice_approved = '')" +
                //                " and (course_mst.faculty_approved = 'N' or course_mst.faculty_approved is null or course_mst.faculty_approved = '')" +
                //                " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' and course_mst.progcoordinate_approved <> 'Y' ";

                SqlSelect = "SELECT distinct course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                                " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                                " course_mst.faculty_approved,course_mst.progcoordinate_approved as pflag,course_mst.ugpgoffice_approved,course_mst.backlog," +
                                " (case course_mst.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval'," +
                                " (case course_mst.progcoordinate_approved when 'P' then 'Approved' else '' end) as 'progcoord_approval'," +
                                " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                                " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year,course_mst.backlog,dwc.sub_category_id,course_mst.studio_mode,studio_brief_status='NULL'" +
                                " ,CONCAT(COALESCE(dwc.focus_studio, ''), CASE WHEN dwc.focus_studio IS NOT NULL AND dwc.secondary_focus_studio IS NOT NULL THEN ', ' ELSE '' END, COALESCE(dwc.secondary_focus_studio, '')) As Focuse,course_mst.CouseSubTitle " +
                                " FROM course_mst " +
                                " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code" +
                                " inner join department_wise_user_dtl as dwu on dwu.dept_code = dwc.dept_code and dwu.prog_code=dwc.prog_code and dwu.semester_type=dwc.semester_type " +
                                " and dwu.year_semester = dwc.year_semester " +

                                " where course_mst.cancel_flag='Y' and course_mst.semester_type ='" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                                " and (course_mst.ugpgoffice_approved = 'N' or course_mst.ugpgoffice_approved is null or course_mst.ugpgoffice_approved = '')" +
                                " and (course_mst.faculty_approved = 'N' or course_mst.faculty_approved is null or course_mst.faculty_approved = '' or course_mst.faculty_approved = 'Y')" +
                                " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' and (course_mst.progcoordinate_approved <> 'Y') and course_mst.ugpgoffice_approved <> 'Y' " +
                                " and dwu.prog_code=dwc.prog_code and dwu.semester_type = '" + sem_code + "' and dwu.year_semester = '" + year_code + "'" +
                                " and dwu.cancel_flag='N' and course_mst.progcoordinate_approved='P' and dwu.user_id = '" + uid + "'";//and ISNULL(dwc.prog_level_code,'')=ISNULL(dwu.prog_level_code,'')

                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }
                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.dept_code ='" + dept_code + "' ";
                }
                SqlSelect = SqlSelect + " ORDER BY course_mst.course_code";
            }

            return Get_data(SqlSelect);
        }

        public DataTable get_selected_course_list_for_insert(string uid, string utype, string user_prog_code, string sem_code, string year_code, string current_sem, string current_year)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";


            SqlSelect = @"SELECT distinct course_mst.course_code,current_sem_course.course_code,dwc.course_typology,course_mst.course_type 
                            ,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week, 
                            course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code 
                            ,dwc.available_seat,course_mst.remark, course_mst.faculty_approved,course_mst.progcoordinate_approved,course_mst.ugpgoffice_approved
                            , course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year
                            FROM course_mst  inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code 
                            inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code ";

            SqlSelect = SqlSelect + "left join (select course_code from course_mst where semester_type='" + current_sem + "' and year_semester = '" + current_year + "' ) as current_sem_course " +
                                     "  on course_mst.course_code = current_sem_course.course_code " +
                                      " where course_mst.cancel_flag='N' and course_mst.semester_type ='" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                                      " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' and current_sem_course.course_code is null " +
                                      " and pcd.prog_code=dwc.prog_code " +
                                      " and pcd.user_id='" + uid + "' and pcd.semester_type = '" + sem_code + "' and pcd.year_semester = '" + year_code + "'" +
                                      "  and (pcd.prog_level_code = dwc.prog_level_code or dwc.prog_level_code='' or dwc.prog_level_code is null) " +
                                      " ORDER BY course_mst.course_code";

            return Get_data(SqlSelect);
        }

        public DataTable Get_course_data_for_modification(string sem_code, string year_code, string course_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
            //            "course_wise_semester on course_mst.course_code = course_wise_semester.course_code where course_mst.cancel_flag = 'N'	";

            //SqlSelect = "select * from course_mst where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            SqlSelect = "select * from course_mst where semester_type='" + sem_code + "' and year_semester = '" + year_code + "' ";

            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and course_code ='" + course_code + "'";
            }

            return Get_data(SqlSelect);
        }

        public DataTable Get_course_department_data_for_modification(string sem_code, string year_code, string course_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
            //            "course_wise_semester on course_mst.course_code = course_wise_semester.course_code where course_mst.cancel_flag = 'N'	";

            //SqlSelect = "select * from department_wise_course_dtl where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            SqlSelect = "select ('Faculty of ' + dm.dept_name) as DepartmentName , * from department_wise_course_dtl " +
                " left join department_mst dm on dm.dept_code = department_wise_course_dtl.dept_code " +
                " left join course_mst cm on cm.course_code = department_wise_course_dtl.course_code and cm.semester_type = department_wise_course_dtl.semester_type " +
                " and cm.year_semester = department_wise_course_dtl.year_semester " +
                " and cm.course_code = department_wise_course_dtl.course_code " +
                " where department_wise_course_dtl.semester_type='" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' ";

            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.course_code ='" + course_code + "'";
            }

            return Get_data(SqlSelect);
        }

        public DataTable Get_course_instructor_data_for_modification(string sem_code, string year_code, string course_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = "select * from course_wise_instructor where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            if (sem_code == "" && year_code == "" && course_code == "")
            {
                SqlSelect = "select course_wise_instructor.*,instructor_mst.instructor_name,iwd.additional_hours,instructor_mst.total_experiance,iwd.rate_band,instructor_mst.highest_qualification,iwd.uso_hr_approved from course_wise_instructor" +
                            " inner join cept_current_semester on cept_current_semester.sem_code=course_wise_instructor.semester_type" +
                            " left join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code " +
                            " left join instructor_workload_detail as iwd on iwd.instructor_code = course_wise_instructor.instructor_code " +
                            " and iwd.course_code = course_wise_instructor.course_code and iwd.semester_type= course_wise_instructor.semester_type " +
                            " and iwd.year_semester = course_wise_instructor.year_semester and iwd.cancel_flag='N' " +
                            " where course_wise_instructor.semester_type = cept_current_semester.sem_code" +
                            " and cept_current_semester.type_desc='course' and course_wise_instructor.year_semester = cept_current_semester.year_code";
            }
            else
            {
                SqlSelect = "select course_wise_instructor.*,instructor_mst.instructor_name,iwd.additional_hours,instructor_mst.total_experiance,iwd.rate_band,instructor_mst.highest_qualification,iwd.uso_hr_approved from course_wise_instructor " +
                    " left join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code " +
                    " left join instructor_workload_detail as iwd on iwd.instructor_code = course_wise_instructor.instructor_code " +
                    " and iwd.course_code = course_wise_instructor.course_code and iwd.semester_type= course_wise_instructor.semester_type " +
                    " and iwd.year_semester = course_wise_instructor.year_semester and iwd.cancel_flag='N' " +
                    " where course_wise_instructor.semester_type='" + sem_code + "' and course_wise_instructor.year_semester = '" + year_code + "'  ";

                if (course_code != "")
                {
                    SqlSelect = SqlSelect + " and course_wise_instructor.course_code ='" + course_code + "'";

                    SqlSelect = SqlSelect + " Union ";
                    SqlSelect += " select doc_no =CAST( ROW_NUMBER() Over (Order by swid.instructor_code) as varchar),isd.course_code,year_code=NULL,swid.instructor_code,percent_load=NULL, " +
                        " swid.cancel_flag,swid.created_by,swid.created_date,swid.created_host,swid.last_modified_by, " +
                        " swid.last_modified_date,swid.last_modified_host,swid.semester_type,swid.year_semester, " +
                        " instructor_contact_hrs=NULL,week=NULL,tutor_description =NULL,swid.tutor_type,instructor_mst.instructor_name,additional_hours = NULL,instructor_mst.total_experiance,rate_band = NULL,instructor_mst.highest_qualification,uso_hr_approved =NULL " +
                        " from instructor_studio_details isd " +
                        " inner join studio_wise_instructor_dtl as swid on swid.studio_code = isd.studio_code and swid.semester_type = isd.semester_type " +
                        " and swid.year_semester = isd.year_semester and swid.cancel_flag= isd.cancel_flag " +
                        " left join instructor_mst on instructor_mst.instructor_code = swid.instructor_code " +
                        " where isd.semester_type='" + sem_code + "' and isd.year_semester='" + year_code + "' and (isd.course_code ='" + course_code + "'  " +
                        " or isd.new_course_code='" + course_code + "') and swid.instructor_code not like 'TBD_%' " +
                        " and swid.instructor_code not in (select instructor_code from course_wise_instructor " +
                        " where course_wise_instructor.semester_type='" + sem_code + "' and course_wise_instructor.year_semester='" + year_code + "' and course_wise_instructor.course_code='" + course_code + "' " +
                        " ) order by doc_no desc ";
                }
            }

            //SqlSelect += " order by course_wise_instructor.tutor_type asc";
            return Get_data(SqlSelect);
        }

