        public BLReturnObject deleted_Course_Data_Upload(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to Delete";
                    return objBLReturnObject;
                }

                DSC_Deleted_Course server_course_master = (DSC_Deleted_Course)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_Deleted_Course objCourseMaster_upload = new DSC_Deleted_Course();
                //DSC_Deleted_Course objCourseMaster_upload = (DSC_Deleted_Course)ds_UploadData;

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_master.deleted_course_mst.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "DCM", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objCourseMaster_upload.deleted_course_mst.ImportRow(server_course_master.deleted_course_mst.Rows[mprCnt]);
                    objCourseMaster_upload.deleted_course_mst[mprCnt].doc_no = DocNo;
                }

                for (int mprCnt = 0; mprCnt < server_course_master.deleted_course_wise_instructor.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "DCWI", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objCourseMaster_upload.deleted_course_wise_instructor.ImportRow(server_course_master.deleted_course_wise_instructor.Rows[mprCnt]);
                    objCourseMaster_upload.deleted_course_wise_instructor[mprCnt].doc_no = DocNo;
                }

                for (int mprCnt = 0; mprCnt < server_course_master.deleted_course_wise_time.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "DCWT", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objCourseMaster_upload.deleted_course_wise_time.ImportRow(server_course_master.deleted_course_wise_time.Rows[mprCnt]);
                    objCourseMaster_upload.deleted_course_wise_time[mprCnt].doc_no = DocNo;
                }

                for (int mprCnt = 0; mprCnt < server_course_master.deleted_department_wise_course_dtl.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "DDWC", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objCourseMaster_upload.deleted_department_wise_course_dtl.ImportRow(server_course_master.deleted_department_wise_course_dtl.Rows[mprCnt]);
                    objCourseMaster_upload.deleted_department_wise_course_dtl[mprCnt].doc_no = DocNo;
                }


                for (int mprCnt = 0; mprCnt < server_course_master.deleted_course_wise_area.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "DCWA", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objCourseMaster_upload.deleted_course_wise_area.ImportRow(server_course_master.deleted_course_wise_area.Rows[mprCnt]);
                    objCourseMaster_upload.deleted_course_wise_area[mprCnt].doc_no = DocNo;
                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.deleted_course_mst, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.deleted_course_mst.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.deleted_course_wise_instructor, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.deleted_course_wise_instructor.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.deleted_course_wise_time, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.deleted_course_wise_time.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.deleted_department_wise_course_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.deleted_department_wise_course_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.deleted_course_wise_area, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.deleted_course_wise_area.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

