        public DataTable Get_all_course_data_For_Modification_new(string sem_code, string year_code, string user_type, string userid)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (user_type == "FA")
            {

                SqlSelect = @"SELECT STUFF((
                SELECT '<option value=""' + course_mst.course_code + '"">' + course_mst.course_code + '-' + course_mst.course_name + '</option>' 
                FROM course_mst
                inner join department_wise_course_dtl DWU on DWU.course_code = course_mst.course_code
                AND DWU.semester_type = course_mst.semester_type
                AND DWU.year_semester = course_mst.year_semester
                WHERE course_mst.faculty_approved <> 'P' AND course_mst.semester_type = '" + sem_code + @"' and course_mst.year_semester = '" + year_code + @"'
                AND DWU.dept_code in (select dept_code from department_wise_user_dtl where semester_type = '" + sem_code + @"' and year_semester = '" + year_code + @"' and cancel_flag = 'N' and instructor_code = '" + userid + @"' )
                ORDER BY course_mst.course_code
                FOR XML PATH(''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 0, '') AS CourseCode ";


            }
            else
            {
                SqlSelect = @"SELECT STUFF(( 
            SELECT '<option value=""' + course_mst.course_code + '"">' + course_mst.course_code + '-' + course_mst.course_name + '</option>' 
            FROM course_mst 
            WHERE course_mst.faculty_approved <> 'P' 
            AND course_mst.semester_type = '" + sem_code + @"' and course_mst.year_semester = '" + year_code + @"' ORDER BY course_mst.course_code
            FOR XML PATH(''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 0, '') AS CourseCode ";
            }


            //SqlSelect = "SELECT  course_mst.course_code,course_mst.course_credits FROM   course_mst where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and  course_mst.faculty_approved <> 'P' ";
            //SqlSelect = SqlSelect + " ORDER BY course_code";

            return Get_data(SqlSelect);
        }



        public DataTable Get_all_course_data_For_Modification(string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "SELECT  course_mst.course_code,course_mst.course_credits FROM   course_mst where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and  course_mst.faculty_approved <> 'P' ";

            SqlSelect = SqlSelect + " ORDER BY course_code";

            return Get_data(SqlSelect);
        }

        public DataTable Get_Prev_Sem_course_data()
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "SELECT course_mst.course_code,course_mst.course_credits,course_mst.semester_type,course_mst.year_semester," +
                        " cept_current_semester.sem_code as cur_sem,(cept_current_semester.year_code - 1) as cur_year" +
                        " FROM course_mst inner join cept_current_semester on cept_current_semester.sem_code = course_mst.semester_type" +
                        " where course_mst.cancel_flag = 'N' and course_mst.semester_type = cept_current_semester.sem_code" +
                        " and cept_current_semester.type_desc='course' and course_mst.year_semester = (cept_current_semester.year_code - 1) ORDER BY course_mst.course_code";

            return Get_data(SqlSelect);
        }

        public DataTable Get_Prev_other_Sem_course_data(string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";


            SqlSelect = " SELECT course_mst.course_code,course_mst.course_credits,course_mst.semester_type,course_mst.year_semester" +
                        " FROM course_mst" +
                        " where course_mst.cancel_flag = 'N' and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                        " ORDER BY course_mst.course_code";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
