            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];

            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable Get_mandatory_course_data_for_student_view(string str_prog_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "select (cm.course_code + ' - ' + cm.course_name) as course from course_mst as cm " +
                        "inner join department_wise_course_dtl as dwc on cm.course_code = dwc.course_code and cm.semester_type = dwc.semester_type and cm.year_semester=dwc.year_semester  " +
                        "where " +
                        "cm.cancel_flag ='N' and dwc.cancel_flag='N' " +
                        "and cm.ugpgoffice_approved ='Y' " +
                        "and cm.semester_type = '" + sem_code + "' and cm.year_semester = '" + year_code + "' " +
                        "and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' ";

            if (str_prog_code == "1" || str_prog_code == "3")
            {
                SqlSelect = SqlSelect + " and dwc.sub_category_id in ('1','L2','L3')  ";
            }
            else if (str_prog_code == "2")
            {
                SqlSelect = SqlSelect + " and dwc.sub_category_id in ('L4') ";
            }

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                {
                    return ds.Tables[0];
                }
            }
            catch (Exception ex)
            {
                return null;
            }
        }

