        public DataTable Get_course_wise_instructor_data_for_feedback(string sem_code, string year_code, string course_code)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select * from course_wise_instructor inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code " +
                        " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and course_code='" + course_code + @"' 
                            and instructor_mst.cancel_flag ='N' and course_wise_instructor.cancel_flag ='N' 
                         union
                            select ''doc_no, cwt.course_code, ''year_code, cwt.instructor_code, ''percent_load, cwt.cancel_flag, 
		                            cwt.created_by, cwt.created_date, cwt.created_host, cwt.last_modified_by, cwt.last_modified_date, 
		                            cwt.last_modified_host, cwt.semester_type, cwt.year_semester, 
		                            ''instructor_contact_hrs,NULL,NULL,NULL,im.* 
                            from course_wise_TA as cwt
                            inner join instructor_mst as im on im.instructor_code=cwt.instructor_code 
                            where cwt.semester_type='" + sem_code + "' and cwt.year_semester='" + year_code + "' and cwt.course_code='" + course_code + "' " +
                        " and im.cancel_flag='N' and cwt.cancel_flag='N' ";

            return Get_data(SqlSelect);
        }

        public DataTable Get_course_wise_instructor(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select um.user_id,um.user_name,um.profile_photo,cwi.tutor_description,cwi.tutor_type from user_mst as um inner join course_wise_instructor as cwi on cwi.instructor_code = um.user_id " +
                        " where  cwi.course_code='" + course_code + "' and cwi.year_semester='" + year_code + "' and cwi.semester_type='" + sem_code + "' order by cwi.tutor_type desc ";

            return Get_data(SqlSelect);
        }

        public DataTable get_portfolio_link(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            if (sem_code == "S")
            {
                SqlSelect = " select semester_type,year_semester,semester_wise_link from course_portfolio_link" +
                            " where  course_code='" + course_code + "' and year_semester != '" + year_code + "' ORDER BY year_semester DESC , semester_type ASC";
            }
            else
            {
                SqlSelect = " select semester_type,year_semester,semester_wise_link from course_portfolio_link" +
                            " where  course_code='" + course_code + "' ORDER BY year_semester DESC , semester_type ASC";

            }

            return Get_data(SqlSelect);
        }

