        public DataTable get_course_data_program_coordinator_wise(string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
            //            "course_wise_semester on course_mst.course_code = course_wise_semester.course_code where course_mst.cancel_flag = 'N'	";
            //SqlSelect = "select * from course_mst where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            SqlSelect = @"select distinct course_mst.*,dwc.dept_code,dwc.course_typology,dwc.semester_code,dwc.prog_code,dwc.prog_level_code,dwc.available_seat FROM course_mst 
                             inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code
                             inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code ";

            SqlSelect = SqlSelect + " where course_mst.semester_type =  '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                                " and pcd.prog_code=dwc.prog_code " +
                                " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' " +
                                " and pcd.user_id='" + user_id + "' and pcd.semester_type = '" + sem_code + "' and pcd.year_semester = '" + year_code + "' " +
                                " and pcd.cancel_flag='N' and ISNULL(dwc.prog_level_code,'')=ISNULL(pcd.prog_level_code,'') ";

            return Get_data(SqlSelect);
        }

        public DataTable get_course_catalog_summary(string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
            //            "course_wise_semester on course_mst.course_code = course_wise_semester.course_code where course_mst.cancel_flag = 'N'	";
            //SqlSelect = "select * from course_mst where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            SqlSelect = @"select prog_level_name,course_type,prog_level_code,count(course_code) as course_code,sum(Cast(course_credits as int)) as course_credits,sum(cast(available_seat as int)) as available_seat from
                          (select distinct course_mst.*,dwc.dept_code,dwc.course_typology,dwc.semester_code,dwc.prog_code,dwc.prog_level_code,dwc.available_seat, 
                          case   isnull(programme_level_mst.prog_level_name,'') when '' then  
                          case  dwc.dept_code when '1' then 'UG in Architecture' when '2' then 'UG in Design' when '3' then 'UG in Management'  when '4' then 'UG in Planning' when '5' then 'UG in Technology' end else programme_level_mst.prog_level_name end as prog_level_name
                          FROM course_mst 
                          inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code
                          inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code  
                          left join programme_level_mst on dwc.prog_level_code = programme_level_mst.prog_level_code ";

            SqlSelect = SqlSelect + " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.ugpgoffice_approved = 'Y' and course_mst.cancel_flag='N' " +
                          " and pcd.prog_code=dwc.prog_code and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' " +
                          " and pcd.user_id='" + user_id + "' and pcd.semester_type = '" + sem_code + "' and pcd.year_semester = '" + year_code + "' " +
                          " and pcd.cancel_flag='N' and ISNULL(dwc.prog_level_code,'')=ISNULL(pcd.prog_level_code,'') ) as rpt " +
                          " group by prog_level_name,course_type,prog_level_code order by course_type ";

            return Get_data(SqlSelect);
        }

        public DataTable get_course_grading_summary_report_data(string sem_code, string year_code, string user_id, string enroll_year)
        {
            String SqlSelect = "";

            int pass_marks = 49;
            //string enroll_year = HttpContext.Current.Session["year_code"].ToString();
            enroll_year = enroll_year.Substring(1);

            if (2017 < Convert.ToInt32(enroll_year))
            {
                pass_marks = 54;
            }

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
            //            "course_wise_semester on course_mst.course_code = course_wise_semester.course_code where course_mst.cancel_flag = 'N'	";
            //SqlSelect = "select * from course_mst where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            SqlSelect = @"select distinct course_mst.course_code,course_mst.course_name,total,dwc.prog_level_code,pass_fail_dtl.total_fail,pass_fail_dtl.total_pass FROM course_mst 
                             inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code
                             inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code 
                             left join( ";

            SqlSelect = SqlSelect + "     select count(course_code) as total,course_code from student_course_allocate_dtl where semester_type='" + sem_code + "' " +
               "  and year_semester ='" + year_code + "' and cancel_flag ='N' group by course_code " +
               "  ) as SCA on course_mst.course_code = SCA.course_code " +
                " left join ( " +
               "  select course_code,isnull([Fail],0) as total_fail ,isnull([PASS],0) as total_pass  from ( " +

                " select (case when Total>" + pass_marks + " then 'PASS' else 'FAIL' end)result,count(course_code) as ab ,course_code " +
                @" from (select  
	                            ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) 
	                            +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0) 
	                            ),0) as Total ,(sca.course_type)c_type,(case sca.gpa_nongpa when '' then NULL else sca.gpa_nongpa end)gpa_nongpa,sm.*  
	                            from student_exam_marks_dtl as sm 
	                            inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code 
				                            and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester 
	                            inner join grade_submit_detail as gsd on gsd.course_code=sm.course_code 
				                            and gsd.semester_type=sm.semester_type and gsd.year_semester=sm.year_semester 
	                            where sm.cancel_flag='N'  and sca.cancel_flag='N' 
	                            and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y' ";

            SqlSelect = SqlSelect + " and sm.semester_type = '" + sem_code + "' and sm.year_semester ='" + year_code + "' " +
                    " )res group by (case when Total>" + pass_marks + " then 'PASS' else 'FAIL' end) ,course_code " +
                    @"        ) as a
                            pivot
                            (
	                            avg(ab) for [result] in (Fail , PASS)
                            )as pvt
                        ) as pass_fail_dtl  on course_mst.course_code = pass_fail_dtl.course_code ";

            SqlSelect = SqlSelect + " where course_mst.semester_type='" + sem_code + "' and course_mst.year_semester='" + year_code + "' and course_mst.ugpgoffice_approved='Y' " +
                  " and course_mst.cancel_flag='N' and pcd.prog_code=dwc.prog_code and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' " +
                  " and pcd.user_id='" + user_id + "' and pcd.semester_type = '" + sem_code + "' and pcd.year_semester = '" + year_code + "' " +
                  " and pcd.cancel_flag='N' and ISNULL(dwc.prog_level_code,'')=ISNULL(pcd.prog_level_code,'') ";

            return Get_data(SqlSelect);
        }

