        public DataTable get_students_completed_credits_report_data(string sem_code, string year_code, string user_id, string user_type, string dept_code, string prog_code, string prog_level_code, string enrollment_year)//13012020
        {
            String SqlSelect = "";

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
            //            "course_wise_semester on course_mst.course_code = course_wise_semester.course_code where course_mst.cancel_flag = 'N'	";
            //SqlSelect = "select * from course_mst where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            string ws_sem_code = sem_code;
            if (sem_code == "M") ws_sem_code = "W";

            if (user_type == "PC")
            {
                SqlSelect = @" select distinct user_mst.user_id,user_mst.user_name, user_mst.dept_code, user_mst.prog_code, user_mst.prog_level_code,isnull(mandatory_allocated,0) as  mandatory_allocated , 
                            isnull(elective_allocated,0 ) as elective_allocated ,dm.dept_name, pm.prog_name, plm.prog_level_name + ' (' + plm.prog_level_desc +' )' prog_level_code,
                            isnull(credit_pass_fail.M_Pass,0) as M_Passed,isnull(credit_pass_fail.E_Pass,0) as E_Passed,
                            isnull(credit_pass_fail.M_Fail,0) as M_Failed,isnull(credit_pass_fail.E_fail,0) as E_Failed,
                            isnull(ws_credit_pass_fail.M_Pass,0) as ws_M_Passed,isnull(ws_credit_pass_fail.E_Pass,0) as ws_E_Passed,
                            isnull(ws_credit_pass_fail.M_Fail,0) as ws_M_Failed,isnull(ws_credit_pass_fail.E_fail,0) as ws_E_Failed,
							isnull(sws_mandatory_allocated,0) as sws_mandatory_allocated,isnull(sws_elective_allocated,0) as sws_elective_allocated
                            from user_mst
                            left join department_mst dm on dm.dept_code = user_mst.dept_code
						    left join programme_mst pm on pm.prog_code = user_mst.prog_code
						    left join programme_level_mst plm on plm.prog_level_code = user_mst.prog_level_code 
							left join (select user_id,[M] as sws_mandatory_allocated, [E] as sws_elective_allocated
							from(
									select user_id,course_type,sum(CAST(credits as int)) as credits from ws_student_course_allocate_dtl ";

                if (enrollment_year == "")
                {
                    SqlSelect = SqlSelect + " where semester_type ='" + ws_sem_code + "' and year_semester ='" + year_code + "' and cancel_flag='N' group by user_id,course_type";
                }
                else
                {
                    SqlSelect = SqlSelect + " where cancel_flag='N' group by user_id,course_type";
                }

                SqlSelect = SqlSelect + @"
							)as a
							pivot
							(
							avg(credits) for [course_type] in (M , E)
							) as pvt
							) as ws_allocate_data on ws_allocate_data.user_id = user_mst.user_id
                            inner join programme_coordinator_dtl as  pcd on user_mst.dept_code = pcd.dept_code and user_mst.prog_code = pcd.prog_code 
                            left join (select user_id,[M] as mandatory_allocated,[E] as elective_allocated 
                                from(select user_id,course_type,sum(CAST(credits as int)) as credits from student_course_allocate_dtl ";
                if (enrollment_year == "")
                {
                    SqlSelect = SqlSelect + " where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag='N' group by user_id,course_type ";
                }
                else
                {
                    SqlSelect = SqlSelect + " where cancel_flag='N' group by user_id,course_type ";
                }

                SqlSelect = SqlSelect + @" 
                                )as a
	                            pivot
	                            (
		                             avg(credits) for [course_type] in (M , E)
	                            ) as pvt
                            ) as allocate_data on allocate_data.user_id = user_mst.user_id
                            left join (select user_id ,[M_Pass],[E_Pass],[M_Fail],[E_Fail] 
                                from (select sum(cast(credits as int)) as ab ,case  when (Total>(case when yc > 'Y2017' then 54 else 49 end))  then course_type +'_Pass' else course_type +'_Fail' end as course_type,user_id
                                    from (select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) 
	                                        +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)),0) as Total ,
                                            (sca.course_type)c_type,(case sca.gpa_nongpa when '' then NULL else sca.gpa_nongpa end)gpa_nongpa,sm.*  ,sca.credits,sca.course_type,sca.user_id, um.year_code as yc
	                                        from student_exam_marks_dtl as sm 
	                                        inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code 
				                                        and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester 
	                                        inner join grade_submit_detail as gsd on gsd.course_code=sm.course_code 
				                                        and gsd.semester_type=sm.semester_type and gsd.year_semester=sm.year_semester 
                                            inner join user_mst as um on um.user_id=sm.student_code 
	                                        where sm.cancel_flag='N'  and sca.cancel_flag='N' ";
                if (enrollment_year == "")
                {
                    SqlSelect = SqlSelect + " and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y'  and sm.semester_type = '" + sem_code + "' and sm.year_semester ='" + year_code + "' ";
                }
                else
                {
                    SqlSelect = SqlSelect + " and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y'  and sm.semester_type = sca.semester_type and sm.year_semester = sca.year_semester ";
                }

                SqlSelect = SqlSelect + @" )res 
                                    group by (case when (Total>(case when yc > 'Y2017' then 54 else 49 end)) then 'PASS' else 'FAIL' end) ,case  when (Total>(case when yc > 'Y2017' then 54 else 49 end))  then course_type +'_Pass' else course_type +'_Fail' end,user_id 
                                ) as a 
                                pivot 
                                ( 
                                    avg(ab) for [course_type] in ([M_Pass],[E_Pass],[M_Fail],[E_Fail]) 
                                ) 
                                as pvt 
                            ) as credit_pass_fail on credit_pass_fail.user_id = user_mst.user_id 
                            left join (select user_id ,[M_Pass],[E_Pass],[M_Fail],[E_Fail] 
                                from (select sum(cast(credits as int)) as ab ,case  when (Total>(case when yc2 > 'Y2017' then 54 else 49 end))  then course_type +'_Pass' else course_type +'_Fail' end as course_type,user_id
                                    from (select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) 
	                                        +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)),0) as Total ,
                                            (sca.course_type)c_type,(case sca.gpa_nongpa when '' then NULL else sca.gpa_nongpa end)gpa_nongpa,sm.*  ,sca.credits,sca.course_type,sca.user_id, um.year_code as yc2
	                                        from ws_student_exam_marks_dtl as sm 
	                                        inner join ws_student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code 
				                                        and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester 
	                                        inner join ws_grade_submit_detail as gsd on gsd.course_code=sm.course_code 
				                                        and gsd.semester_type=sm.semester_type and gsd.year_semester=sm.year_semester 
                                            inner join user_mst as um on um.user_id=sm.student_code 
	                                        where sm.cancel_flag='N'  and sca.cancel_flag='N' ";
                if (enrollment_year == "")
                {
                    SqlSelect = SqlSelect + " and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y'  and sm.semester_type = '" + ws_sem_code + "' and sm.year_semester ='" + year_code + "' ";
                }
                else
                {
                    SqlSelect = SqlSelect + " and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y'  and sm.semester_type = sca.semester_type and sm.year_semester = sca.year_semester ";
                }

                SqlSelect = SqlSelect + @" )res 
                                    group by (case when (Total>(case when yc2 > 'Y2017' then 54 else 49 end)) then 'PASS' else 'FAIL' end) ,case  when (Total>(case when yc2 > 'Y2017' then 54 else 49 end))  then course_type +'_Pass' else course_type +'_Fail' end,user_id 
                                ) as a 
                                pivot 
                                ( 
                                    avg(ab) for [course_type] in ([M_Pass],[E_Pass],[M_Fail],[E_Fail]) 
                                ) 
                                as pvt 
                            ) as ws_credit_pass_fail on ws_credit_pass_fail.user_id = user_mst.user_id 
                        where user_mst.user_status_flag ='A' and user_mst.status ='A' and pcd.cancel_flag ='N' and ISNULL(user_mst.prog_level_code,'')=ISNULL(pcd.prog_level_code,'') 
                        and pcd.user_id='" + user_id + "' and pcd.semester_type = '" + sem_code + "' and pcd.year_semester = '" + year_code + "' ";

                if (enrollment_year != "")
                {
                    SqlSelect = SqlSelect + " and user_mst.year_code='" + enrollment_year + "' ";
                }
                else
                {
                    SqlSelect = SqlSelect + " and user_mst.user_id in (select distinct user_id from student_course_allocate_dtl where cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' group by user_id union select distinct user_id from ws_student_course_allocate_dtl where cancel_flag='N' and semester_type = '" + ws_sem_code + "' and year_semester = '" + year_code + "' group by user_id) ";
                }

                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and user_mst.dept_code='" + dept_code + "' ";
                }

                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and user_mst.prog_code='" + prog_code + "' ";
                }

                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and user_mst.prog_level_code='" + prog_level_code + "' ";
                }
            }
            else if (user_type == "A1" || user_type == "AC" || user_type == "FA")
            {
                SqlSelect = @" select distinct user_mst.user_id,user_mst.user_name , user_mst.dept_code, user_mst.prog_code, user_mst.prog_level_code,
                        dm.dept_name, pm.prog_name, plm.prog_level_name + ' (' + plm.prog_level_desc +' )' prog_level_code,
                        isnull(mandatory_allocated,0) as  mandatory_allocated , 
                        isnull(elective_allocated,0 ) as elective_allocated ,
                        isnull(credit_pass_fail.M_Pass,0) as M_Passed,isnull(credit_pass_fail.E_Pass,0) as E_Passed,
                        isnull(credit_pass_fail.M_Fail,0) as M_Failed,isnull(credit_pass_fail.E_fail,0) as E_Failed,
                        isnull(ws_credit_pass_fail.M_Pass,0) as ws_M_Passed,isnull(ws_credit_pass_fail.E_Pass,0) as ws_E_Passed,
                        isnull(ws_credit_pass_fail.M_Fail,0) as ws_M_Failed,isnull(ws_credit_pass_fail.E_fail,0) as ws_E_Failed,
                        isnull(sws_mandatory_allocated,0) as sws_mandatory_allocated,isnull(sws_elective_allocated,0) as sws_elective_allocated
                        from user_mst
                        left join department_mst dm on dm.dept_code = user_mst.dept_code
						left join programme_mst pm on pm.prog_code = user_mst.prog_code
						left join programme_level_mst plm on plm.prog_level_code = user_mst.prog_level_code 
                        left join (select user_id,[M] as sws_mandatory_allocated, [E] as sws_elective_allocated
                        from(
		                        select user_id,course_type,sum(CAST(credits as int)) as credits from ws_student_course_allocate_dtl ";

                if (enrollment_year == "")
                {
                    SqlSelect = SqlSelect + " where semester_type = '" + ws_sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N' group by user_id,course_type";
                }
                else
                {
                    SqlSelect = SqlSelect + " where cancel_flag = 'N' group by user_id,course_type";
                }

                SqlSelect = SqlSelect + @")as a
                        pivot
                        (
                        avg(credits) for [course_type] in (M , E)
                        ) as pvt
                        ) as ws_allocate_data on ws_allocate_data.user_id = user_mst.user_id
                        left join (select user_id,[M] as mandatory_allocated,[E] as elective_allocated 
                            from(select user_id,course_type,sum(CAST(credits as int)) as credits from student_course_allocate_dtl ";


                if (enrollment_year == "")
                {
                    SqlSelect = SqlSelect + " where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag='N' group by user_id,course_type ";
                }
                else
                {
                    SqlSelect = SqlSelect + " where cancel_flag = 'N' group by user_id,course_type";
                }

                SqlSelect = SqlSelect + @" 
                            )as a
	                        pivot
	                        (
		                            avg(credits) for [course_type] in (M , E)
	                        ) as pvt
                        ) as allocate_data on allocate_data.user_id = user_mst.user_id
                        left join (select user_id ,[M_Pass],[E_Pass],[M_Fail],[E_Fail] 
                            from (select sum(cast(credits as int)) as ab ,case  when (Total>(case when yc > 'Y2017' then 54 else 49 end))  then course_type +'_Pass' else course_type +'_Fail' end as course_type,user_id
                                from (select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) 
	                                    +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)),0) as Total ,
                                        (sca.course_type)c_type,(case sca.gpa_nongpa when '' then NULL else sca.gpa_nongpa end)gpa_nongpa,sm.*  ,sca.credits,sca.course_type,sca.user_id, um.year_code as yc
	                                    from student_exam_marks_dtl as sm 
	                                    inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code 
				                                    and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester 
	                                    inner join grade_submit_detail as gsd on gsd.course_code=sm.course_code 
