        public DataTable TotalAggregetSubjectData(string sem_code, string year_code, string user_id, string user_type, string dept_code, string prog_code, string prog_level_code, string enrollment_year)
        {
            String SqlSelect = "";

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
