            SqlSelect = @" select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) 
	                                    +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)),0) as Total ,
                                        (sca.course_type)c_type,(case sca.gpa_nongpa when '' then NULL else sca.gpa_nongpa end)gpa_nongpa,sm.*  ,sca.credits,sca.course_type,sca.user_id, um.year_code as yc
	                                    from student_exam_marks_dtl as sm 
	                                    inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code 
				                                    and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester 
	                                    inner join grade_submit_detail as gsd on gsd.course_code=sm.course_code 
				                                    and gsd.semester_type=sm.semester_type and gsd.year_semester=sm.year_semester 
                                        inner join user_mst as um on um.user_id=sm.student_code 
	                                    where sm.cancel_flag='N'  and sca.cancel_flag='N'  and gsd.cancel_flag='N' 
                                        And gsd.ugpgoffice_approved='Y'  ";

            if (sem_code == "")
            {
                SqlSelect += @" And sm.semester_type = sca.semester_type ";
            }
            else { SqlSelect += @" And sm.semester_type = '" + sem_code + @"' "; }

            if (year_code == "")
            {
                SqlSelect += @" And sm.year_semester = sca.year_semester ";
            }
            else { SqlSelect += @" And sm.year_semester = '" + year_code + @"' "; }



            //if (user_id != "")
            //{
            //    SqlSelect += @" And um.user_id = '" + user_id + @"'";
            //}

            if (enrollment_year != "")
            {
                SqlSelect += @" And um.year_code = '" + enrollment_year + @"'";
            }

            if (dept_code != "")
            {
                SqlSelect += @" And um.dept_code = '" + dept_code + @"'";
            }

            if (prog_code != "")
            {
                SqlSelect += @" And um.prog_code = '" + prog_code + @"'";
            }

            if (prog_level_code != "")
            {
                SqlSelect += @" And um.prog_level_code = '" + prog_level_code + @"'";
            }


            return Get_data(SqlSelect);
        }


