        public DataTable get_studentscredits_report_data(string student_code, string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = " select course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_type,course_wise_semester.semester_code from course_mst INNER JOIN " +
            //            "course_wise_semester on course_mst.course_code = course_wise_semester.course_code where course_mst.cancel_flag = 'N'	";

            //SqlSelect = "select * from course_mst where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester = '" + year_code + "' and course_code ='" + course_code + "'";

            SqlSelect = @"select distinct user_mst.user_id,user_mst.user_name ,user_mst.prog_level_code,isnull(mandatory_applied,0) as  mandatory_applied ,
                            isnull(elective_applied,0) as  elective_applied ,isnull(mandatory_allocated,0) as  mandatory_allocated , isnull(elective_allocated,0 ) as elective_allocated ,
                            isnull(credit_pass_fail.mandatory_completed,0) as mandatory_completed,isnull(credit_pass_fail.gpa_completed,0) as gpa_completed,
                            isnull(credit_pass_fail.non_gpa_completed,0) as non_gpa_completed,pcd.semester_type,pcd.year_semester

                            from user_mst
                            inner join programme_coordinator_dtl as  pcd on user_mst.dept_code = pcd.dept_code and user_mst.prog_code = pcd.prog_code 
                            inner join (select user_id,semester_type,year_semester,[M] as mandatory_allocated,[E] as elective_allocated from(
	                            select user_id,course_type,sum(CAST(credits as int)) as credits,semester_type,year_semester from student_course_allocate_dtl  where cancel_flag='N' group by user_id,course_type,semester_type,year_semester 	)as a
	                            pivot
	                            (
		                             avg(credits) for [course_type] in (M , E)
	                            ) as pvt
                            ) as allocate_data
                            on allocate_data.user_id = user_mst.user_id and pcd.semester_type = allocate_data.semester_type and pcd.year_semester = allocate_data.year_semester
                            left join (select user_id,[M] as mandatory_applied,[E] as elective_applied,semester_type,year_semester from(
	                            select user_id,course_type,sum(CAST(credits as int)) as credits,semester_type,year_semester from student_wise_course_dtl  where cancel_flag='N' group by user_id,course_type,semester_type,year_semester 	)as a
	                            pivot
	                            (
		                             avg(credits) for [course_type] in (M , E)
	                            ) as pvt
                            ) as applied_data
                            on applied_data.user_id = user_mst.user_id and pcd.semester_type = applied_data.semester_type and  pcd.year_semester = applied_data.year_semester
                            left join (select user_id ,[M] as mandatory_completed,[G] as gpa_completed,[N] as non_gpa_completed,semester_type,year_semester 
                                from (select sum(cast(credits as int)) as ab, user_id,gpa_nongpa,semester_type,year_semester
                                    from (select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) 
	                                        +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)),0) as Total ,
                                            (sca.course_type)c_type,(case sca.gpa_nongpa when '' then 'M' else sca.gpa_nongpa end)gpa_nongpa,sm.*  ,sca.credits,sca.user_id
	                                        from student_exam_marks_dtl as sm 
	                                        inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code 
				                                        and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester 
	                                        inner join grade_submit_detail as gsd on gsd.course_code=sm.course_code 
				                                        and gsd.semester_type=sm.semester_type and gsd.year_semester=sm.year_semester 
	                                        where sm.cancel_flag='N' and sca.cancel_flag='N'  and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y'   
	                                )res group by user_id,gpa_nongpa,semester_type,year_semester
	                            ) as a 
	                            pivot  
	                            (  
	                                avg(ab) for [gpa_nongpa] in ([M],[G],[N])  
	                            ) as pvt 
	                        ) as credit_pass_fail on credit_pass_fail.user_id = user_mst.user_id 
                                                        and pcd.semester_type = credit_pass_fail.semester_type and pcd.year_semester = credit_pass_fail.year_semester ";

            SqlSelect = SqlSelect + " where user_mst.user_status_flag ='A' and status ='A'  and pcd.cancel_flag ='N' and pcd.user_id='" + user_id + "'  and user_mst.user_id ='" + student_code + "' " +
                                     " order by year_semester ,semester_type desc ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }

