        #region check student pass or fail for particuler course

        public DataTable Get_course_time_day_data_for_catalog_report(Dictionary<string, string> ObjParam)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            int pass_marks = 49;

            string enroll_year = HttpContext.Current.Session["year_code"].ToString();
            enroll_year = enroll_year.Substring(1);

            if (2017 < Convert.ToInt32(enroll_year))
            {
                pass_marks = 54;
            }

            StringBuilder SQLSelect = new StringBuilder();

            SQLSelect.Append("SELECT  (case when Total>" + pass_marks + " then 'PASS' else 'FAIL' end)result,* ");
            SQLSelect.Append("  from (select  ");
            SQLSelect.Append(" ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) ");
            SQLSelect.Append(" +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)  ");
            SQLSelect.Append(" ),0) as Total ,(sca.course_type)c_type,(case sca.gpa_nongpa when '' then NULL else sca.gpa_nongpa end)gpa_nongpa,sm.* ");
            SQLSelect.Append(" from student_exam_marks_dtl as sm ");
            SQLSelect.Append(" inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code ");
            SQLSelect.Append(" and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester ");
            SQLSelect.Append(" inner join grade_submit_detail as gsd on gsd.course_code=sm.course_code ");
            SQLSelect.Append(" and gsd.semester_type=sm.semester_type and gsd.year_semester=sm.year_semester ");
            SQLSelect.Append(" where sm.cancel_flag='N' ");

            if (ObjParam.ContainsKey("user_id") && ObjParam["user_id"] != null && ObjParam["user_id"].ToString().Trim() != String.Empty)
            {
                SQLSelect.Append(" AND (  sm.student_code = @user_id) ");
                DBDataAdpterObject.SelectCommand.Parameters.Add(DBObjectFactory.MakeParameter_new("@user_id", DbType.String, ObjParam["user_id"]));
            }
            if (ObjParam.ContainsKey("course_code") && ObjParam["course_code"] != null && ObjParam["course_code"].ToString().Trim() != String.Empty)
            {
                SQLSelect.Append(" AND (sm.course_code = @course_code) ");
                DBDataAdpterObject.SelectCommand.Parameters.Add(DBObjectFactory.MakeParameter_new("@course_code", DbType.String, ObjParam["course_code"]));
            }

            SQLSelect.Append(" and sca.cancel_flag='N' ");
            SQLSelect.Append(" and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y' ");
            SQLSelect.Append(" )res ");

            return Get_data(SQLSelect.ToString());
        }

