        public BLReturnObject save_course_AA_data(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Course_Master server_course_master = (DSC_Course_Master)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_Course_Master objCourseMaster_upload = new DSC_Course_Master();

                objCourseMaster_upload.EnforceConstraints = false;



                Dictionary<string, object> WhereCriteriaDegree = new Dictionary<string, object>();
                string Message = "";

                //  WhereCriteriaDegree["dept_code"] = server_course_master.course_wise_AA[0].dept_code;
                WhereCriteriaDegree["course_code"] = server_course_master.course_wise_AA[0].course_code;
                WhereCriteriaDegree["semester_type"] = server_course_master.course_wise_AA[0].semester_type;
                WhereCriteriaDegree["year_semester"] = server_course_master.course_wise_AA[0].year_semester;

                bool resultDegree = DeleteData(ref DBCommand, "course_wise_AA", WhereCriteriaDegree, ref Message);

                for (int mprCnt = 0; mprCnt < server_course_master.course_wise_AA.Rows.Count; mprCnt++)
                {

                    objCourseMaster_upload.course_wise_AA.ImportRow(server_course_master.course_wise_AA.Rows[mprCnt]);

                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.course_wise_AA, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.course_wise_AA.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                objBLReturnObject.ServerMessage = ex.ToString();
            }
            return objBLReturnObject;
        }

