        public DataTable get_all_course_time_data(string sem_code, string year_code)
        {
            String SqlSelect = "";

            //SqlSelect = " select CAST(from_time as float)FromTime,CAST(To_time as float)ToTime,* from course_wise_time where semester_type='" + sem_code + "' and year_semester='" + year_code + "' ";

            SqlSelect = " DECLARE @sem_code varchar(1);SET @sem_code='" + sem_code + "';DECLARE @year_code varchar(5);SET @year_code='" + year_code + @"'; 
                            select CAST(from_time as float)FromTime,CAST(To_time as float)ToTime,cwt.* 
                            from course_wise_time as cwt 
                            inner join course_mst as cm on cm.course_code=cwt.course_code and cm.semester_type=cwt.semester_type and cm.year_semester=cwt.year_semester 
			                            and (cm.faculty_approved='Y' or cm.progcoordinate_approved='Y' or cm.ugpgoffice_approved='Y') 
                            where cwt.semester_type=@sem_code and cwt.year_semester=@year_code and cwt.room_id is not null and cwt.room_id!='' 
                            union
                            select CAST(from_time as float)FromTime,CAST(To_time as float)ToTime,cwt.* 
                            from course_wise_time_tutorial as cwt 
                            inner join course_mst as cm on cm.course_code=cwt.course_code and cm.semester_type=cwt.semester_type and cm.year_semester=cwt.year_semester 
			                            and (cm.faculty_approved='Y' or cm.progcoordinate_approved='Y' or cm.ugpgoffice_approved='Y') 
                            where cwt.semester_type=@sem_code and cwt.year_semester=@year_code and cwt.room_id is not null and cwt.room_id!='' ";

            return Get_data(SqlSelect);
        }

