        public DataTable check_time_conflict_for_room(string from_time, string to_time, string sem_code, string year_code, string day_code, string course_code)
        {
            String SqlSelect = "";

            //// Add course_wise_time_tutorial Table as well in query

            SqlSelect = " DECLARE @f_time float;SET @f_time=CAST('" + from_time + "' as float);DECLARE @t_time float;SET @t_time=CAST('" + to_time + "' as float); " +
                        " DECLARE @sem_code varchar(1);SET @sem_code='" + sem_code + "';DECLARE @year_code varchar(5);SET @year_code='" + year_code + "'; " +
                        " DECLARE @day_code varchar(2);SET @day_code='" + day_code + "';DECLARE @course_code varchar(20);SET @course_code='" + course_code + @"'; 
                         select * from(select CAST(from_time as float)FromTime,CAST(To_time as float)ToTime,cwt.*
	                            from course_wise_time as cwt
	                            inner join course_mst as cm on cm.course_code=cwt.course_code and cm.semester_type=cwt.semester_type and cm.year_semester=cwt.year_semester
				                            and (cm.faculty_approved='Y' or cm.progcoordinate_approved='Y' or cm.ugpgoffice_approved='Y')
	                            where cwt.semester_type=@sem_code and cwt.year_semester=@year_code and cwt.day_code=@day_code
                                            and cwt.room_id is not null and cwt.room_id!='' and cwt.course_code=@course_code
                            )res
                            where ((FromTime <= @f_time and ToTime <= @t_time and ToTime > @f_time and FromTime < @t_time)
	                            or (FromTime <= @f_time and ToTime >= @t_time and ToTime > @f_time and FromTime < @t_time)
	                            or (FromTime >= @f_time and ToTime <= @t_time and ToTime > @f_time and FromTime < @t_time)
	                            or (FromTime >= @f_time and ToTime >= @t_time and ToTime > @f_time and FromTime < @t_time)
                            )
                            order by day_code,from_time,To_time ";

            return Get_data(SqlSelect);
        }

