                WhereCriteriaDegree["course_code"] = server_course_master.course_wise_TA[0].course_code;
                WhereCriteriaDegree["semester_type"] = server_course_master.course_wise_TA[0].semester_type;
                WhereCriteriaDegree["year_semester"] = server_course_master.course_wise_TA[0].year_semester;

                bool resultDegree = DeleteData(ref DBCommand, "course_wise_TA", WhereCriteriaDegree, ref Message);

                for (int mprCnt = 0; mprCnt < server_course_master.course_wise_TA.Rows.Count; mprCnt++)
                {

                    objCourseMaster_upload.course_wise_TA.ImportRow(server_course_master.course_wise_TA.Rows[mprCnt]);

                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.course_wise_TA, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.course_wise_TA.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                objBLReturnObject.ServerMessage = ex.ToString();
            }
            return objBLReturnObject;
