        public DataTable get_tutor_image_data(string instructor_code)
        {
            string[] instructorList = instructor_code.Split(',');

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            String OrderString = "";

            SqlSelect = " select um.profile_photo,im.instructor_code,im.instructor_name as user_name,im.mail,isnull(csm.education_description,im.edu_work_description) as education_description,im.total_experiance,im.highest_qualification " +
                " from instructor_mst as im left join user_mst as um on im.user_id = um.user_id left join cpop_superviser_mst as csm on im.user_id = csm.superviser_code where im.instructor_code in (" + instructor_code + ") ORDER BY CASE im.instructor_code ";

            for (int q = 0; q < instructorList.Length; q++)
            {
                if (q > 0)
                {
                    OrderString += " WHEN " + instructorList[q].ToString() + " THEN '" + (q + 1) + "'";
                }
                else
                {
                    OrderString = " WHEN " + instructorList[q].ToString() + " THEN '" + (q + 1) + "'";
                }
            }
            SqlSelect = SqlSelect + OrderString + " END";

            return Get_data(SqlSelect);
        }

