        /// <summary>
        /// 2 Time use this Method Outline View
        /// </summary>
        /// <param name="course_code"></param>
        /// <param name="sem_code"></param>
        /// <param name="year_code"></param>
        /// <returns></returns>
        public DataTable Get_instructor_wise_course_time(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "select iwct.doc_no, instructor_mst.instructor_name,iwct.course_code,iwct.instructor_code,iwct.from_time,iwct.to_time,iwct.day_code," +
                " iwct.room_id,iwct.cancel_flag,iwct.semester_type,iwct.year_semester,day_mst.day_name,iwct.time_sq_no ,timeslot_from_time, timeslot_to_time " +
                " from instructor_wise_course_time as iwct " +
                " inner join instructor_mst on instructor_mst.instructor_code = iwct.instructor_code  " +
                " left join day_mst on day_mst.day_code = iwct.day_code " +
                " left join (select doc_no,from_time as timeslot_from_time,To_time as timeslot_to_time, course_code,from_time,To_time,ROW_NUMBER() OVER(ORDER BY doc_no asc) AS time_sq_no from course_wise_time where course_code='" + course_code + "' " +
                " and semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag in ('N','Y')) as time_slot_seq on time_slot_seq.time_sq_no = iwct.time_sq_no " +
                " where iwct.course_code = '" + course_code + "' and iwct.semester_type='" + sem_code + "' and iwct.year_semester = '" + year_code + "' and iwct.cancel_flag = 'N' order by doc_no asc ";

            return Get_data(SqlSelect);
        }

