        public BLReturnObject save_course_data_for_other_dept(DataSet ds_UploadData, string compnyid, String UserID, String HostName, string old_course_code)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            String SqlSelect = "";

            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Course_Master server_course_master = (DSC_Course_Master)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_Course_Master objCourseMaster_upload = new DSC_Course_Master();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_master.course_other_dept_dtl.Rows.Count; mprCnt++)
                {
                    objCourseMaster_upload.course_other_dept_dtl.ImportRow(server_course_master.course_other_dept_dtl.Rows[mprCnt]);
                }

                string course_code = objCourseMaster_upload.course_other_dept_dtl[0]["course_code"].ToString();
                string semester_type = objCourseMaster_upload.course_other_dept_dtl[0]["semester_type"].ToString();
                string year_semester = objCourseMaster_upload.course_other_dept_dtl[0]["year_semester"].ToString();

                bool delete_flag = false;

                // Delete Course Other Dept Dtl
                SqlSelect = "delete from course_other_dept_dtl where course_code='" + course_code + "' and semester_type='" + semester_type + "' and year_semester='" + year_semester + "'";
                DBCommand.CommandText = SqlSelect;
                DBCommand.CommandType = CommandType.Text;
                try { DBCommand.ExecuteNonQuery(); }
                catch (Exception e) { delete_flag = true; }

                if (delete_flag)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Data.";
                    return objBLReturnObject;
                }

                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.course_other_dept_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.course_other_dept_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                objBLReturnObject.ServerMessage = ex.ToString();
            }

            return objBLReturnObject;
        }

