        #region Vertical Studio Selection
        public DataTable get_student_vertical_studio_selected_course_dtl(string user_id, string sem_code, string year_code)
        {
            String SqlSelect = "";
            SqlSelect = " select t1.*,  STUFF((select '</br> ' + ('P : ' + CAST(priority as nvarchar)  + ' S : ' + CAST(Count(status) as nvarchar))  as priority_count from vertical_studio_selection_dtl  " +
                " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'  and status='R' and course_code =t1.course_code and cancel_flag='N'  " +
                " group by priority,status FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,0,'')priority_count from (";
            SqlSelect += " Select cm.course_code,cm.course_name,cm.course_outline,cm.studio_mode,vss.priority,vss.parent_course,vss.status,vss.shortlist_student_status, " +
                        " STUFF((select ', '+im.instructor_name from course_wise_instructor as cwi " +
                        " inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N' " +
                        " where cwi.course_code=dwc.course_code and cwi.cancel_flag='N' and cwi.semester_type='" + sem_code + "' and cwi.year_semester='" + year_code + "'" +
                        " FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,2,'')instructors  from vertical_studio_selection_dtl as vss " +
                        " inner join department_wise_course_dtl as dwc on dwc.course_code = vss.course_code and dwc.year_semester = vss.year_semester " +
                        " and dwc.semester_type = vss.semester_type and dwc.cancel_flag ='N' " +
                        " inner join course_mst as cm on cm.course_code=vss.course_code and cm.cancel_flag='N' and cm.ugpgoffice_approved='Y' " +
                        " and cm.semester_type=vss.semester_type and cm.year_semester=vss.year_semester " +
                        " where vss.user_id ='" + user_id + "' and vss.year_semester ='" + year_code + "' and vss.semester_type ='" + sem_code + "') as t1 order by t1.priority ";

            return Get_data(SqlSelect);
        }

