        public DataTable get_vertical_studio_course_for_instructor_new(string user_id, string sem_code, string year_code, string user_type)
        {
            String SqlSelect = "";

            SqlSelect = " select distinct cwi.course_code,cm.course_name,cm.course_type,cm.gpa_ngpa from course_wise_instructor as cwi " +
                        " inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'";
            if (user_type != "A1")
            {
                SqlSelect = SqlSelect + "inner join vertical_studio_selection_dtl as vss on vss.course_code=cwi.course_code and vss.cancel_flag='N' " +
                    " and vss.semester_type=cwi.semester_type and vss.year_semester=cwi.year_semester ";
            }
            else
            {
                SqlSelect = SqlSelect + "left join vertical_studio_selection_dtl as vss on vss.course_code=cwi.course_code and vss.cancel_flag='N' " +
                            " and vss.semester_type=cwi.semester_type and vss.year_semester=cwi.year_semester ";
            }
            SqlSelect = SqlSelect + " inner join course_mst as cm on cm.course_code=cwi.course_code and cm.cancel_flag='N' and cm.semester_type=cwi.semester_type and cm.year_semester=cwi.year_semester";
            if (user_type != "A1")
            {
                SqlSelect = SqlSelect + " where cwi.semester_type='" + sem_code + "' and cwi.year_semester='" + year_code + "' and im.user_id='" + user_id + "' and cwi.cancel_flag='N' ";
            }
            else
            {
                SqlSelect = SqlSelect + " where cwi.semester_type='" + sem_code + "' and cwi.year_semester='" + year_code + "' and cwi.cancel_flag='N' ";
            }
            SqlSelect = SqlSelect + " union select distinct cwt.course_code,cm.course_name,cm.course_type,cm.gpa_ngpa from course_wise_TA as cwt " +
                "  inner join instructor_mst as im on im.instructor_code=cwt.instructor_code and im.cancel_flag='N'";
            if (user_type != "A1")
            {
                SqlSelect = SqlSelect + " inner join vertical_studio_selection_dtl as vss on vss.course_code=cwt.course_code and vss.cancel_flag='N'" +
                    " and vss.semester_type=cwt.semester_type and vss.year_semester=cwt.year_semester";
            }
            else
            {
                SqlSelect = SqlSelect + " left join vertical_studio_selection_dtl as vss on vss.course_code=cwt.course_code and vss.cancel_flag='N'" +
                    " and vss.semester_type=cwt.semester_type and vss.year_semester=cwt.year_semester";
            }
            SqlSelect = SqlSelect + " inner join course_mst as cm on cm.course_code=cwt.course_code and cm.cancel_flag='N' and cm.semester_type=cwt.semester_type and cm.year_semester=cwt.year_semester ";
            if (user_type != "A1")
            {
                SqlSelect = SqlSelect + "where cwt.semester_type='" + sem_code + "' and cwt.year_semester='" + year_code + "' and im.user_id='" + user_id + "' and cwt.cancel_flag='N' ";
            }
            else
            {
                SqlSelect = SqlSelect + " where cwt.semester_type='" + sem_code + "' and cwt.year_semester='" + year_code + "' and cwt.cancel_flag='N' ";
            }
            return Get_data(SqlSelect);
        }

