            SqlSelect = " DECLARE @user_id varchar(50);SET @user_id='" + user_id + "';" +
                        " DECLARE @sem varchar(1);SET @sem='" + sem_code + "';" +
                        " DECLARE @year varchar(5);SET @year='" + year_code + "'; " + @"

                            DECLARE @tbl_temp Table(course_code varchar(50));

                            insert into @tbl_temp
                            select course_code from student_course_allocate_dtl
                            where semester_type=@sem and year_semester=@year and user_id=@user_id and cancel_flag='N'
                            select t1.*,STUFF((select '</br> ' + ('P : ' + CAST(priority as nvarchar)  + ' S : ' + CAST(Count(status) as nvarchar))  as priority_count 
                            from vertical_studio_selection_dtl   where semester_type = @sem and year_semester = @year  and status='R' and course_code = t1.course_code
							and cancel_flag='N'   group by priority,status FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,0,'')priority_count  from (
                            select cm.course_code,cm.course_name,tt.course_code as parent_course,cm.course_outline,
                            STUFF((select ', '+im.instructor_name from course_wise_instructor as cwi
	                            inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'
	                            where cwi.course_code=dwc.course_code and cwi.cancel_flag='N'
	                            and cwi.semester_type=@sem and cwi.year_semester=@year
	                            FOR XML PATH(''),TYPE
                            ).value('.','NVARCHAR(MAX)'),1,2,'')instructors,vssd.user_id,vssd.priority,vssd.status,vssd.remarks,cm.studio_mode,vssd.shortlist_student_status
                            from department_wise_course_dtl as dwc
                            inner join course_mst as cm on cm.course_code=dwc.course_code and cm.cancel_flag='N' and cm.ugpgoffice_approved='Y'
		                            and cm.semester_type=dwc.semester_type and cm.year_semester=dwc.year_semester
                            inner join vertical_studio_course_mapping as vscm on vscm.course_code=dwc.course_code
		                            and vscm.semester_type=dwc.semester_type and vscm.year_semester=dwc.year_semester
                            inner join @tbl_temp as tt on tt.course_code=vscm.parent_course_code
                            left join vertical_studio_selection_dtl as vssd on vssd.user_id=@user_id and vssd.course_code=dwc.course_code
		                            and vssd.semester_type=dwc.semester_type and vssd.year_semester=dwc.year_semester and vssd.cancel_flag='N'
                            where dwc.semester_type=@sem and dwc.year_semester=@year
                            and dwc.course_code not in (select * from @tbl_temp))as t1
                            order by t1.course_code";

            return Get_data(SqlSelect);
        }

