        public DataTable get_student_data_for_vertical_course(string course_code, string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = " DECLARE @course_code varchar(50);SET @course_code='" + course_code + "';" +
                        " DECLARE @sem varchar(1);SET @sem='" + sem_code + "';" +
                        " DECLARE @year varchar(5);SET @year='" + year_code + "'; " + @" 

                        select res1.*,um.user_name,um.gender,stu.portfolio_link,scd.studio_type
                        from (select * from vertical_studio_selection_dtl
	                        where course_code=@course_code and semester_type=@sem and year_semester=@year
	                        and cancel_flag='N' and status='R'
                        )res1
                        left join (select distinct user_id,parent_course from vertical_studio_selection_dtl
	                        where semester_type=@sem and year_semester=@year and cancel_flag='N' and status='A'
                        )res2 on res2.user_id=res1.user_id and res2.parent_course=res1.parent_course
                        left join user_mst as um on um.user_id=res1.user_id
                        left join student_portfolio_link as stu on stu.student_code = res1.user_id
                        left join student_certificate_dtl as scd on scd.user_id = res1.user_id
                        where res2.user_id is null
                        order by res1.random_number,res1.priority,res1.user_id";

            return Get_data(SqlSelect);
        }

