        public DataTable get_vertical_studio_allocation_status(string sem_code, string year_code, int page_no, int limit, string course_code, string dept_code, string sub_cat_id)
        {
            String SqlSelect = "";

            SqlSelect = " DECLARE @sem varchar(1);SET @sem='" + sem_code + "';DECLARE @year varchar(5);SET @year='" + year_code + "';" +
                        " DECLARE @page_no int;SET @page_no=" + page_no + ";DECLARE @limit int;SET @limit=" + limit + ";" + @"

                        select *,(res2.available_seat-res2.allocated_seats)remaining_seats,
	                        STUFF((SELECT distinct ', ' + im.instructor_name
			                        FROM course_wise_instructor cwi
			                        inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'
			                        WHERE cwi.course_code = res2.course_code and cwi.cancel_flag = 'N'
					                        and cwi.semester_type = @sem and cwi.year_semester = @year
			                        FOR XML PATH(''), TYPE
			                        ).value('.', 'NVARCHAR(MAX)')
	                        ,1,2,'') instructor_name
                        from (select ROW_NUMBER() over(order by cm.course_code)sr_no,cm.course_code,cm.course_name,dwc.available_seat,
	                        (case ISNULL(res1.allocated_seats,'') when '' then 0 else res1.allocated_seats end)allocated_seats
	                        from (select course_code,COUNT(user_id)registered_students from vertical_studio_selection_dtl as vss
		                        where vss.semester_type=@sem and vss.year_semester=@year and vss.cancel_flag='N' and vss.status in ('R','A')
		                        group by course_code
	                        )res
	                        inner join course_mst as cm on cm.course_code=res.course_code
	                        inner join department_wise_course_dtl as dwc on dwc.course_code=cm.course_code and dwc.cancel_flag='N'
		                        and dwc.semester_type=cm.semester_type and dwc.year_semester=cm.year_semester
	                        left join (select course_code,COUNT(course_code)allocated_seats from student_course_allocate_dtl as sca
		                        where sca.semester_type=@sem and sca.year_semester=@year and sca.cancel_flag='N'
		                        group by course_code
	                        )res1 on res1.course_code=cm.course_code
	                        where cm.semester_type=@sem and cm.year_semester=@year
	                        and cm.cancel_flag='N' and cm.ugpgoffice_approved='Y' ";

            if (course_code != "")
            {
                SqlSelect += " and cm.course_code='" + course_code + "' ";
            }

            if (dept_code != "")
            {
                SqlSelect += " and dwc.dept_code='" + dept_code + "' ";
            }

            if (sub_cat_id != "")
            {
                SqlSelect += " and dwc.sub_category_id='" + sub_cat_id + "' ";
            }
            else
            {
                SqlSelect += " and dwc.sub_category_id in ('L2','L3','L4') ";
            }


            SqlSelect += @" )res2
                        where sr_no>((@page_no - 1)*@limit) and sr_no<=(@page_no*@limit)
                        order by res2.course_code ";

            return Get_data(SqlSelect);
        }

        //<summary>This method changes the point's (05012021)
        //This Method Get All Remening Register User Count and Priority Wise Allocate User and One User Allocate Course Then update Other Course Status
        //<example>For example: if student is allocated from Priority 1 course, his/her count also wiil be removed 
        //from the other priority courses so that it will show updated list on the all preferences and student number
        //</example>
        //</summary>

        public DataTable get_count_priority_studio_allocation(DataTable dt_vertical_course_dtl, string sem_code, string year_code)
        {
            String SqlSelect = "";

            dt_vertical_course_dtl.Columns.Add("count_priority", typeof(string));

            for (int i = 0; i < dt_vertical_course_dtl.Rows.Count; i++)
            {
                DataTable dt = vertical_studio_reg_allo_student_dtl(sem_code, year_code, dt_vertical_course_dtl.Rows[i]["course_code"].ToString());
                SqlSelect = "";

                if (dt != null)
                {
                    SqlSelect = "DECLARE @tbl_vertical Table(course_code varchar(50),priority varchar(10),status char(1),parent_code varchar(50),user_id varchar(50),semester_type varchar(50),year_semester varchar(50)); " +
                        " insert into @tbl_vertical " +
                        " select course_code,priority,status,parent_course,user_id,semester_type,year_semester from vertical_studio_selection_dtl " +
                        " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag ='N' and status in ('R','A') " +
                        " UPDATE @tbl_vertical SET status = 'A' " +
                        " WHERE [@tbl_vertical].user_id in (select Distinct user_id from vertical_studio_selection_dtl " +
                        " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag ='N' and status ='A')" +
                        " DECLARE @tbl_temp Table(course_code varchar(50),priority varchar(5),count_priority varchar(10)); " +
                        " insert into @tbl_temp " +
                        " select TOP 5 course_code, priority,COUNT(priority) as count_priority from @tbl_vertical " +
                        " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status = 'A'  and course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"] + "' " +
                        " group by course_code,priority order by CAST(priority AS INT) " +
                        " select TOP 5 vss.course_code, vss.priority,COUNT(vss.priority) as count_priority, " +
                        " CAST(temp.count_priority as int) as allocate_sets from  @tbl_vertical as vss " +
                        " left join @tbl_temp as temp on temp.priority = vss.priority " +
                        " where vss.semester_type='" + sem_code + "' and vss.year_semester='" + year_code + "' and vss.status ='R' " +
                        " and vss.course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"] + "' group by vss.course_code,vss.priority,temp.count_priority order by CAST(vss.priority AS INT) ";
                    DataTable priority_data = Get_data(SqlSelect);

                    if (priority_data != null)
                    {
                        dt_vertical_course_dtl.Rows[i]["count_priority"] = GetJson1(priority_data);
                    }
                    else
                    {
                        dt_vertical_course_dtl.Rows[i]["count_priority"] = "\"\"";
                    }
                }
                else
                {
                    SqlSelect = " DECLARE @tbl_temp Table(course_code varchar(50),priority varchar(5),count_priority varchar(10));" +
                            " insert into @tbl_temp " +
                            " select TOP 5 course_code, priority,COUNT(priority) as count_priority from vertical_studio_selection_dtl " +
                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status = 'A'  and course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"] + "' " +
                            " group by course_code,priority order by priority " +
                            " select TOP 5 vss.course_code, vss.priority,COUNT(vss.priority) as count_priority, CAST(temp.count_priority as int) as allocate_sets from vertical_studio_selection_dtl as vss " +
                            " left join @tbl_temp as temp on temp.priority = vss.priority " +
                            " where vss.semester_type='" + sem_code + "' and vss.year_semester='" + year_code + "' and vss.status = 'R' " +
                            " and vss.course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"] + "' group by vss.course_code,vss.priority,temp.count_priority order by CAST(vss.priority AS INT) ";
                    //SqlSelect = "select TOP 5 course_code, priority,COUNT(priority) as count_priority from vertical_studio_selection_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status='R' and course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"] + "' group by course_code,priority order by priority";

                    DataTable priority_data = Get_data(SqlSelect);

                    if (priority_data != null)
                    {
                        dt_vertical_course_dtl.Rows[i]["count_priority"] = GetJson1(priority_data);
                    }
                    else
                    {
                        dt_vertical_course_dtl.Rows[i]["count_priority"] = "\"\"";
                    }
                }

            }

            return dt_vertical_course_dtl;
        }

