        public string shortlist_student(string course_code, string student_code, string sem_code, string year_code)
        {
            int countvalue = 0;
            string status = "";
            int limit_count = 19;
            DataTable dtcount = total_student_shortlis(course_code, sem_code, year_code);
            DataTable Single_dual_count = Studio_Find_single_dual(course_code, sem_code, year_code);
            if (Single_dual_count != null)
            {
                limit_count = Convert.ToInt32(Single_dual_count.Rows[0]["count_status"].ToString());
            }

            if (dtcount != null)
            {
                countvalue = Convert.ToInt32(dtcount.Rows[0]["countrow"].ToString());
            }
            //if (countvalue <= 19)
            if (countvalue <= limit_count)
            {
                DBConnection.Open();
                //DBCommand.Transaction = DBConnection.BeginTransaction();
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                String SqlSelect = "";

                SqlSelect += "update vertical_studio_selection_dtl SET shortlist_student_status = 'Y' where course_code = '" + course_code + "'" +
                    " AND semester_type = '" + sem_code + "' AND year_semester = '" + year_code + "' and user_id = '" + student_code + "'";

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                try
                {
                    int res = DBCommand.ExecuteNonQuery();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                    if (res > 0)
                    {
                        return "Successfully ShortListed Student";
                    }
                    else
                    {
                        return "Problem in ShortList, Please try again.";
                    }
                }
                catch (Exception ex)
                {
                    //DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return "Problem in Upload, Please try again." + ex.Message;
                }

            }
            else
            {
                //return "Only 20 Student short Listed ";
                return "Only " + (limit_count + 1) + " Student short Listed ";
            }
        }

