        public BLReturnObject save_vertical_studio_selection_data(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Vertical_Studio_Selection_dtl obj_vertical_studio = (DSC_Vertical_Studio_Selection_dtl)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                obj_vertical_studio.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_vertical_studio.vertical_studio_selection_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_vertical_studio.vertical_studio_selection_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }

            return objBLReturnObject;
        }

        public BLReturnObject allocate_vertical_studio_course(DataSet ds_UploadData, DataSet ds_UploadData2, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_Vertical_Studio_Selection_dtl obj_vertical_studio = (DSC_Vertical_Studio_Selection_dtl)ds_UploadData;

                Ds_Student_Course_detail server_student_course = (Ds_Student_Course_detail)ds_UploadData2;

                Ds_Student_Course_detail obj_student_course = new Ds_Student_Course_detail();

                obj_student_course.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_student_course.student_course_allocate_dtl.Rows.Count; mprCnt++)
                {
                    obj_student_course.student_course_allocate_dtl.ImportRow(server_student_course.student_course_allocate_dtl.Rows[mprCnt]);
                    if (obj_student_course.student_course_allocate_dtl[mprCnt].doc_no == "new")
                    {
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "SA", UserID, HostName, ref DocNo, ref message))
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        obj_student_course.student_course_allocate_dtl[mprCnt].doc_no = DocNo;
                    }
                }

                obj_vertical_studio.EnforceConstraints = true;
                obj_student_course.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_vertical_studio.vertical_studio_selection_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_vertical_studio.vertical_studio_selection_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_student_course.student_course_allocate_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_student_course.student_course_allocate_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }

            return objBLReturnObject;
        }

        public DataTable get_shortlist_course_data(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code, string course_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select user_mst.user_id, user_mst.user_name as full_name,user_mst.gender," +
                         " CASE department_wise_course_dtl.sub_category_id WHEN 'L2' THEN 'Level 2 Studio' WHEN 'L3' THEN 'Level 3 Studio' ELSE 'Level 4 Studio' END AS course_code," +
                         " vertical_studio_selection_dtl.course_code as new_course_code,department_mst.dept_name , " +
                         " vertical_studio_selection_dtl.priority,user_mst.mail,user_mst.mobile_no,course_mst.course_name from vertical_studio_selection_dtl " +
                         " inner join user_mst on vertical_studio_selection_dtl.user_id = user_mst.user_id " +
                         " inner JOIN department_mst on user_mst.dept_code = department_mst.dept_code " +
                         " INNER JOIN department_wise_course_dtl on vertical_studio_selection_dtl.course_code = department_wise_course_dtl.course_code " +
                         " INNER join course_mst on course_mst.course_code = vertical_studio_selection_dtl.course_code and course_mst.semester_type = vertical_studio_selection_dtl.semester_type " +
                         " and course_mst.year_semester = vertical_studio_selection_dtl.year_semester " +
                         " where vertical_studio_selection_dtl.shortlist_student_status='Y' and vertical_studio_selection_dtl.priority='1' " +
                         " and vertical_studio_selection_dtl.semester_type='" + sem_code + "' and vertical_studio_selection_dtl.year_semester ='" + year_code + "' " +
                         " and department_wise_course_dtl.sub_category_id is not null and department_wise_course_dtl.semester_type = '" + sem_code + "' and  " +
                         " department_wise_course_dtl.year_semester = '" + year_code + "'";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = @dept_code ";

                IDataParameter para1 = DBObjectFactory.GetParameterObject();
                para1.ParameterName = "@dept_code";
                para1.DbType = DbType.String;
                para1.Value = dept_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para1);
            }
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = @prog_code ";

                IDataParameter para2 = DBObjectFactory.GetParameterObject();
                para2.ParameterName = "@prog_code";
                para2.DbType = DbType.String;
                para2.Value = prog_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para2);
            }

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code = @prog_level_code ";

                IDataParameter para3 = DBObjectFactory.GetParameterObject();
                para3.ParameterName = "@prog_level_code";
                para3.DbType = DbType.String;
                para3.Value = prog_level_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para3);
            }

            if (course_code != "" && course_code != null && course_code != "null")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.course_code = @course_code ";

                IDataParameter para4 = DBObjectFactory.GetParameterObject();
                para4.ParameterName = "@course_code";
                para4.DbType = DbType.String;
                para4.Value = course_code;
                DBDataAdpterObject.SelectCommand.Parameters.Add(para4);
            }


            // SqlSelect = SqlSelect + "order by course_code ASC ";
            SqlSelect = SqlSelect + "order by new_course_code ASC ";

            return Get_data(SqlSelect);
        }

