        public DataTable get_vertical_studio_course_for_user_type_wise(string user_id, string sem_code, string year_code, string user_type, String dep_name, String prg_name, String sub_category_id)
        {
            String SqlSelect = "";

            SqlSelect = " select distinct vsc.course_code,course_mst.course_name from vertical_studio_course_mapping as vsc " +
                         " inner join course_mst on course_mst.course_code = vsc.course_code and course_mst.semester_type = vsc.semester_type and course_mst.year_semester = vsc.year_semester and course_mst.cancel_flag ='N'" +
                        "  Inner Join department_wise_course_dtl as dep ON dep.course_code = vsc.course_code and dep.semester_type = vsc.semester_type and dep.year_semester = vsc.year_semester and dep.cancel_flag ='N'";
            if (user_type == "PC")
            {
                SqlSelect = SqlSelect + " Inner Join programme_coordinator_dtl as pro ON pro.dept_code = dep.dept_code and pro.prog_code = dep.prog_code and vsc.semester_type = pro.semester_type " +
                    " and vsc.year_semester = pro.year_semester and pro.cancel_flag = 'N' ";
                SqlSelect = SqlSelect + " where pro.user_id ='" + user_id + "'";
                if (dep_name != "")
                {
                    SqlSelect = SqlSelect + " and pro.dept_code='" + dep_name + "' ";
                }
                if (prg_name != "")
                {
                    SqlSelect = SqlSelect + " and pro.prog_code='" + prg_name + "' ";
                }
            }
            if (user_type == "D")
            {
                SqlSelect = SqlSelect + "  Inner Join dean_dtl as den ON den.dept_code = dep.dept_code and den.prog_code = dep.prog_code and vsc.semester_type = den.semester_type " +
                    " and vsc.year_semester = den.year_semester and den.cancel_flag ='N'";
                SqlSelect = SqlSelect + " where den.user_id ='" + user_id + "'";
                if (dep_name != "")
                {
                    SqlSelect = SqlSelect + " and den.dept_code='" + dep_name + "' ";
                }
                if (prg_name != "")
                {
                    SqlSelect = SqlSelect + " and den.prog_code='" + prg_name + "' ";
                }

            }
            if (user_type == "I2")
            {
                DataTable dt = get_vertical_studio_course_for_instructor_new(user_id, sem_code, year_code, user_type);
                return dt;
            }
            if (user_type == "FA")
            {
                SqlSelect = SqlSelect + "  Inner Join department_wise_user_dtl as dwu ON dwu.dept_code = dep.dept_code and dwu.prog_code = dep.prog_code and vsc.semester_type = dwu.semester_type " +
                                        " and vsc.year_semester = dwu.year_semester and dwu.cancel_flag = 'N' ";
                SqlSelect = SqlSelect + " where dwu.user_id ='" + user_id + "'";

                if (dep_name != "")
                {
                    SqlSelect = SqlSelect + " and dwu.dept_code='" + dep_name + "' ";
                }
                if (prg_name != "")
                {
                    SqlSelect = SqlSelect + " and dwu.prog_code='" + prg_name + "' ";
                }
            }

            if (user_type == "A1")
            {
                SqlSelect = SqlSelect + " where vsc.semester_type ='" + sem_code + "' and vsc.year_semester ='" + year_code + "' ";
                if (dep_name != "")
                {
                    SqlSelect = SqlSelect + " and dep.dept_code='" + dep_name + "' ";
                }
                if (prg_name != "")
                {
                    SqlSelect = SqlSelect + " and dep.prog_code='" + prg_name + "' ";
                }
            }
            else
            {
                SqlSelect = SqlSelect + " and vsc.semester_type ='" + sem_code + "' and vsc.year_semester ='" + year_code + "'";
            }
            if (sub_category_id != "")
            {
                SqlSelect = SqlSelect + " and dep.sub_category_id ='" + sub_category_id + "' ";
            }
            return Get_data(SqlSelect);
        }

        public DataTable get_semester_wise_preference_reports(String sem_code, String year_code, String Course_code, String user_type, String user_id, String user_prog_code, String dep_name, String prg_name, String sub_category_id)
        {
            String SqlSelect = "";
            SqlSelect = " select distinct user_mst.user_id,user_mst.full_name,user_mst.gender,vssd.priority,vssd.course_code as course_code ,(vssd.course_code + ' ('+ cm.course_name + ' )') as course_name_code,cm.course_name,vssd.parent_course," +
                " CASE WHEN dwc.sub_category_id ='L2' THEN 'Level 2' WHEN dwc.sub_category_id ='L3' THEN 'Level 3' WHEN dwc.sub_category_id ='L4' THEN 'Level 4' ELSE '' END sub_category_id,vssd.semester_type," +
                " vssd.year_semester,vssd.random_number,dwc.dept_code,dwc.dept_code as parent_dept_code,CASE WHEN vssd.status ='S' THEN 'Saved' WHEN vssd.status ='R' THEN '' WHEN vssd.status ='A' THEN 'Allocated' ELSE '' END status," +
                " CASE WHEN sca.course_type ='E' THEN 'Elective' WHEN sca.course_type ='M' THEN 'Mandatory' ELSE '' END course_type, " +
                " CASE WHEN sca.gpa_nongpa ='N' THEN 'Non GPA' WHEN sca.gpa_nongpa ='G' THEN 'GPA' ELSE '' END gpa_nongpa,vssd.remarks,CASE WHEN vssd.shortlist_student_status ='Y' THEN 'YES' ELSE '' END shortlist_student_status,user_mst.mobile_no,user_mst.mail " +
                " from vertical_studio_selection_dtl as vssd" +
                " inner join department_wise_course_dtl as dwc on dwc.course_code = vssd.course_code and dwc.year_semester = vssd.year_semester and dwc.semester_type = vssd.semester_type and dwc.cancel_flag ='N'" +
                " inner join course_mst as cm on cm.course_code = vssd.course_code and cm.semester_type = vssd.semester_type and cm.year_semester = vssd.year_semester and cm.cancel_flag ='N' " +
                " left join student_course_allocate_dtl as sca on sca.course_code = vssd.course_code and sca.semester_type = vssd.semester_type and sca.year_semester = vssd.year_semester and sca.user_id = vssd.user_id and sca.cancel_flag ='N' " +
                " inner join user_mst on user_mst.user_id = vssd.user_id ";

            if (user_type == "PC" && Course_code == "")
            {
                SqlSelect = SqlSelect + " Inner Join programme_coordinator_dtl as pro ON pro.dept_code = dwc.dept_code and pro.prog_code = dwc.prog_code and pro.semester_type = dwc.semester_type " +
                    " and pro.year_semester = dwc.year_semester and pro.cancel_flag = 'N' ";

                if (dep_name != "")
                {
                    SqlSelect = SqlSelect + " and pro.dept_code='" + dep_name + "' ";
                }
                if (prg_name != "")
                {
                    SqlSelect = SqlSelect + " and pro.prog_code='" + prg_name + "' ";
                }

                //SqlSelect = SqlSelect + " where pro.user_id ='" + user_id + "'";
            }
            if (user_type == "D" && Course_code == "")
            {
                SqlSelect = SqlSelect + "  Inner Join dean_dtl as den ON den.dept_code = dwc.dept_code and den.prog_code = dwc.prog_code and den.semester_type = dwc.semester_type " +
                    " and den.year_semester = dwc.year_semester and den.cancel_flag ='N'";
                //SqlSelect = SqlSelect + " where den.user_id ='" + user_id + "'";

                if (dep_name != "")
                {
                    SqlSelect = SqlSelect + " and den.dept_code='" + dep_name + "' ";
                }
                if (prg_name != "")
                {
                    SqlSelect = SqlSelect + " and den.prog_code='" + prg_name + "' ";
                }

            }
            if (user_type == "FA" && Course_code == "")
            {
                SqlSelect = SqlSelect + "  Inner Join department_wise_user_dtl as dwu ON dwu.dept_code = dwc.dept_code and dwu.prog_code = dwc.prog_code and dwu.semester_type = dwc.semester_type " +
                                        " and dwu.year_semester = dwc.year_semester and dwu.cancel_flag = 'N' ";

                if (dep_name != "")
                {
                    SqlSelect = SqlSelect + " and dwu.dept_code='" + dep_name + "' ";
                }
                if (prg_name != "")
                {
                    SqlSelect = SqlSelect + " and dwu.prog_code='" + prg_name + "' ";
                }

                // SqlSelect = SqlSelect + " where dwu.user_id ='" + user_id + "'";
            }
            SqlSelect = SqlSelect + " where vssd.semester_type ='" + sem_code + "' and vssd.year_semester = '" + year_code + "' ";

            if (user_type == "PC" && Course_code == "")
            {
                SqlSelect = SqlSelect + " and pro.user_id ='" + user_id + "' ";

            }
            if (user_type == "D" && Course_code == "")
            {

                SqlSelect = SqlSelect + " and den.user_id ='" + user_id + "' ";

            }
            if (user_type == "FA" && Course_code == "")
            {

                SqlSelect = SqlSelect + " and dwu.user_id ='" + user_id + "' ";
            }

            if (Course_code != "")
            {
                SqlSelect = SqlSelect + " and vssd.course_code ='" + Course_code + "' ";
            }
            if (dep_name != "")
            {
                SqlSelect = SqlSelect + " and dwc.dept_code='" + dep_name + "' ";
            }
            if (prg_name != "")
            {
                SqlSelect = SqlSelect + " and dwc.prog_code='" + prg_name + "' ";
            }
            if (sub_category_id != "")
            {
                SqlSelect = SqlSelect + " and dwc.sub_category_id='" + sub_category_id + "' ";
            }
            //19072021
            SqlSelect = SqlSelect + " order by vssd.course_code,vssd.priority,vssd.random_number";
            return Get_data(SqlSelect);

        }

