        public Boolean Update_vertical_studio_manul_user(string parent_course_code, string child_course_code, string user_id, string sem_code, string year_code, string users_id, string HostName)
        {
            // Vertical_Studio_User_List vertical_Studio_User_List = new Vertical_Studio_User_List();
            parent_course_code = Vertical_Studio_User_List.Parent_Course;
            child_course_code = Vertical_Studio_User_List.Child_Course;
            user_id = Vertical_Studio_User_List.User_id;
            sem_code = Vertical_Studio_User_List.semester;
            year_code = Vertical_Studio_User_List.year;

            /*************************/
            /* ESTABLISH CONNECTION */
            // DBConnection.Close();
            // DBConnection.Open();

            // DBCommand.Transaction = DBConnection.BeginTransaction();

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "Update student_course_allocate_dtl SET cancel_flag ='Y', last_modified_by='" + users_id + "', last_modified_date=GETDATE(), last_modified_host='" + HostName + "' where course_code = '" + parent_course_code + "' and user_id in (" + user_id + ") and semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag='N' ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {

                DBCommand.ExecuteNonQuery();

                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                SqlSelect = "";

                SqlSelect = "Update vertical_studio_selection_dtl SET status ='A', last_modified_by='" + users_id + "', last_modified_date=GETDATE(), last_modified_host='" + HostName + "' where course_code = '" + child_course_code + "' and user_id in (" + user_id + ") and semester_type='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag ='N' ";

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DBCommand.ExecuteNonQuery();

                // DBCommand.Transaction.Commit();

                //DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                return false;
            }
        }


