        {
            String SqlSelect = "";

            SqlSelect = " DECLARE @sem varchar(1);SET @sem='" + sem_code + "';DECLARE @year varchar(4);SET @year='" + year_code + @"';
                                select course_code,student_code,
                                (case ISNULL(CAST(exam_1 as varchar),'') when '' then (case ISNULL(absent_exam_1,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_1_eligible,
                                (case ISNULL(CAST(exam_2 as varchar),'') when '' then (case ISNULL(absent_exam_2,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_2_eligible,
                                (case ISNULL(CAST(exam_3 as varchar),'') when '' then (case ISNULL(absent_exam_3,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_3_eligible,
                                (case ISNULL(CAST(exam_4 as varchar),'') when '' then (case ISNULL(absent_exam_4,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_4_eligible,
                                (case ISNULL(CAST(exam_5 as varchar),'') when '' then (case ISNULL(absent_exam_5,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_5_eligible,
                                (case ISNULL(CAST(exam_6 as varchar),'') when '' then (case ISNULL(absent_exam_6,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_6_eligible,
                                (case ISNULL(CAST(exam_7 as varchar),'') when '' then (case ISNULL(absent_exam_7,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_7_eligible,
                                (case ISNULL(CAST(exam_8 as varchar),'') when '' then (case ISNULL(absent_exam_8,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_8_eligible,
                                (case ISNULL(CAST(exam_9 as varchar),'') when '' then (case ISNULL(absent_exam_9,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_9_eligible,
                                (case ISNULL(CAST(exam_10 as varchar),'') when '' then (case ISNULL(absent_exam_10,'') when '' then 'N' else 'Y' end) else 'Y' end)exam_10_eligible
                                from student_exam_marks_dtl
                                where semester_type=@sem and year_semester=@year and cancel_flag='N'
                                order by course_code ";

            return Get_data(SqlSelect);
        }

        public DataTable chk_publish_all_course_avlblty_in_student_marks(string user_id, string user_type, string sem_code, string year_code)
        {
            String SqlSelect = "";

            if (user_type == "A1")
            {
                //SqlSelect = "select distinct course_code from student_course_allocate_dtl" +
                //            " where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N'" +
                //            " and course_code not in" +
                //            " (" +
                //                " select distinct course_code from student_exam_marks_dtl " +
                //                " where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N'" +
                //            " )";

                SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(5);set @sem='" + sem_code + "';set @year='" + year_code + "';";

                SqlSelect = SqlSelect + @"DECLARE @tbl_exam TABLE(course_code varchar(50));

                            insert @tbl_exam 
                            select distinct course_code from student_exam_marks_dtl  
                                    where semester_type = @sem and year_semester = @year and cancel_flag = 'N' 

                            select distinct course_code from student_course_allocate_dtl 
                            where semester_type = @sem and year_semester = @year and cancel_flag = 'N' 
                            and course_code not in ( select * from @tbl_exam)";

            }

            return Get_data(SqlSelect);
        }

        public DataTable chk_publish_all_student_marks(string user_id, string user_type, string sem_code, string year_code)
        {
            String SqlSelect = "";

            if (user_type == "A1")
            {
                SqlSelect = "select distinct exams1.total_exams,sm.* from student_exam_marks_dtl as sm" +
                            " left join(select em.course_code,COUNT(em.exam_code)total_exams " +
                                        " from exam_master as em" +
                                        " where em.semester_type='" + sem_code + "' and em.year_semester='" + year_code + "' and em.cancel_flag='N' " +
                                        " group by em.course_code " +
                                    " )exams1" +
                            " on sm.course_code=exams1.course_code  " +
                            " where sm.semester_type = '" + sem_code + "' and sm.year_semester = '" + year_code + "' and sm.cancel_flag = 'N'";
            }

            return Get_data(SqlSelect);
        }

