        public BLReturnObject course_wise_exam_add(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_GradingMaster server_course_master = (DSC_GradingMaster)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_GradingMaster objCourseMaster_upload = new DSC_GradingMaster();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_master.exam_master.Rows.Count; mprCnt++)
                {
                    objCourseMaster_upload.exam_master.ImportRow(server_course_master.exam_master.Rows[mprCnt]);
                    if (objCourseMaster_upload.exam_master[mprCnt].doc_no == "")
                    {
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "EM", UserID, HostName, ref DocNo, ref message))
                        {

                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        objCourseMaster_upload.exam_master[mprCnt].doc_no = DocNo;
                    }
                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.exam_master, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.exam_master.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

        public string remove_all_exam_dtl(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            int res = 0;

            SqlSelect = "DECLARE @course varchar(10);SET @course='" + course_code + "';";
            SqlSelect += "DECLARE @sem varchar(1);SET @sem='" + sem_code + "';";
            SqlSelect += "DECLARE @year varchar(5);SET @year='" + year_code + "';";
            SqlSelect += @"
                        delete from exam_master where course_code=@course and semester_type=@sem and year_semester=@year
                        delete from student_exam_marks_dtl where course_code=@course and semester_type=@sem and year_semester=@year and cancel_flag='N' ";

            DBCommand.CommandText = SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();

                res = DBCommand.ExecuteNonQuery();

                if (res > 0)
                {
                    return "All Exams Removed Successfully";
                }
                else
                {
                    return "Problem in removing all exams, Please try again.";
                }
            }
            catch (Exception ex)
            {
                return "Problem in removing all exams, " + ex.ToString();
            }

            DBConnection.Close();
            return "";
        }

