        public DataTable get_studentwisecourse_for_marks_entry(string course_code, string sem_code, string year_code)
        {
            String SqlSelect = "";

            //SqlSelect = "SELECT * FROM student_wise_course_dtl" +
            //SqlSelect = "SELECT * FROM student_course_allocate_dtl " +
            //            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag = 'N'" +
            //            " and course_code='" + course_code + "'" +
            //            " order by user_id";

            SqlSelect = "SELECT student_course_allocate_dtl.* FROM student_course_allocate_dtl" +
                        " inner join user_mst on user_mst.user_id = student_course_allocate_dtl.user_id" +
                        " where student_course_allocate_dtl.semester_type='" + sem_code + "' and student_course_allocate_dtl.year_semester='" + year_code + "' " +
                        " and student_course_allocate_dtl.cancel_flag = 'N' and user_mst.cancel_flag = 'N' " +
                        " and user_mst.user_status_flag='A'" +
                        " and student_course_allocate_dtl.course_code='" + course_code + "'" +
                        " order by student_course_allocate_dtl.user_id";

            //SqlSelect = SqlSelect + " ORDER BY course_code";

            return Get_data(SqlSelect);
        }

