        public DataTable get_course_wise_avg_sd_range_new(string sem_code, string year_code, string courses_selected)
        {
            String SqlSelect = "";

            //------------------- Calculate Mean & SD using Query -------------------
            //-----------------------------------------------------------------------
            //START :: Latest Working and Made SP for Better Evaluation
            SqlSelect = "select *" +
                        " ,('90')A_plus_from									,('100')A_plus_to" +
                        " ,ROUND((Average + (1.74 * SD) + 1),0,1)A_from			,('89')A_to" +
                        " ,ROUND((Average + (1.07 * SD) + 1),0,1)A_minus_from	,ROUND((Average + (1.74 * SD)),0,1)A_minus_to" +
                        " ,ROUND((Average + (0.56 * SD) + 1),0,1)B_plus_from	,ROUND((Average + (1.07 * SD)),0,1)B_plus_to" +
                        " ,ROUND((Average + (0.15 * SD) + 1),0,1)B_from			,ROUND((Average + (0.56 * SD)),0,1)B_to" +
                        " ,ROUND((Average - (0.16 * SD) + 1),0,1)B_minus_from	,ROUND((Average + (0.15 * SD)),0,1)B_minus_to" +
                        " ,ROUND((Average - (0.57 * SD) + 1),0,1)C_plus_from	,ROUND((Average - (0.16 * SD)),0,1)C_plus_to" +
                        " ,ROUND((Average - (1.08 * SD) + 1),0,1)C_from			,ROUND((Average - (0.57 * SD)),0,1)C_to" +
                        " ,ROUND((Average - (1.75 * SD) + 1),0,1)C_minus_from	,ROUND((Average - (1.08 * SD)),0,1)C_minus_to" +
                        " ,('50')D_plus_from									,ROUND((Average - (1.75 * SD)),0,1)D_plus_to" +
                        " ,('0')F_from										    ,('49')F_to" +
                        " from (select course_code,SUM(subject_Marks)Course_Total_Marks,COUNT(student_code)Total_Students" +
                            " ,AVG(CAST(subject_Marks as float))Average,STDEV(subject_Marks)SD " +
                            " from (select ROUND(R1.Total,0)subject_Marks,R2.total_exams,R1.* " +
                                    " from (select " +
                                                " (ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)" +
                                                    " +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)" +
                                                " ) as Total ,sm.* " +
                                                " from student_exam_marks_dtl as sm" +
                                                " inner join student_course_allocate_dtl as sca" +
                                                " on sca.user_id=sm.student_code and sca.course_code=sm.course_code" +
                                                " where sm.cancel_flag='N' and sm.semester_type='" + sem_code + "' and sm.year_semester='" + year_code + "'" +
                                                " and sca.cancel_flag='N' and sca.semester_type='" + sem_code + "' and sca.year_semester='" + year_code + "'" +

                                                " and ((sca.course_type='M' and ISNULL(sca.gpa_nongpa,'')!='N') or (sca.course_type='E' and sca.gpa_nongpa='G')) " +
                                        " )R1" +
                                    " inner join" +
                                        " (select course_code,COUNT(course_code)total_exams from exam_master" +
                                            " where cancel_flag='N'  and semester_type='" + sem_code + "' and year_semester='" + year_code + "' " +
                                            " group by course_code" +
                                        " )R2 " +
                                    " on R1.course_code=R2.course_code" +
                                " )R3" +
                            " where R3.subject_Marks>=50 and R3.subject_Marks<90" +
                            " group by course_code" +
                        ")R4" +
                        " where R4.course_code in (" + courses_selected + ")";

            //" and (sca.course_type='M' or (sca.course_type='E' and sca.gpa_nongpa='G'))" +

            return Get_data(SqlSelect);

            //END :: Latest Working and Made SP for Better Evaluation


            //SqlCommand sqlComm = new SqlCommand("get_course_wise_avg_sd_range_new", con);
            //sqlComm.Parameters.AddWithValue("@semester_type", sem_code);
            //sqlComm.Parameters.AddWithValue("@year_semester", year_code);
            //sqlComm.Parameters.AddWithValue("@courses_selected", courses_selected_for_sp);
            //sqlComm.CommandType = CommandType.StoredProcedure;

            //return Get_data_from_SP_with_para(sqlComm);
        }

