        public Boolean CancelCourseWiseMarks(string course_code, string semester_type, string year_semester, string user_id)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            string SqlSelect = "";

            SqlSelect = @"UPDATE student_exam_marks_dtl SET cancel_flag='Y', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and course_code='" + course_code + "' ";

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBCommand.CommandText = SqlSelect;
            try
            {
                int res_update = DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }

