        public DataTable get_subject_marks_for_grade(string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = "select ROUND(R1.Total,0)subject_Marks,R2.total_exams,R1.* " +
                        " from (select " +
                                    " (ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)" +
                                    " +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)" +
                                    " ) as Total ,* from student_exam_marks_dtl " +
                                    " where cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "'" +
                            " )R1" +
                        " inner join" +
                            " (select course_code,COUNT(course_code)total_exams from exam_master" +
                                " where cancel_flag='N'  and semester_type='" + sem_code + "' and year_semester='" + year_code + "' " +
                                " group by course_code" +
                            " )R2 " +
                        " on R1.course_code=R2.course_code";

            //SqlSelect = SqlSelect + " ORDER BY course_code";

            return Get_data(SqlSelect);
        }

        public DataTable get_subject_marks_for_grade_course_wise(string sem_code, string year_code, string course_code)
        {
            String SqlSelect = "";

            SqlSelect = "select ROUND(R1.Total,0)subject_Marks,R2.total_exams,R1.* " +
                        " from (select " +
                                    " (ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)" +
                                    " +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)" +
                                    " ) as Total ,* from student_exam_marks_dtl " +
                                    " where cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "'" +
                            " )R1" +
                        " inner join" +
                            " (select course_code,COUNT(course_code)total_exams from exam_master" +
                                " where cancel_flag='N'  and semester_type='" + sem_code + "' and year_semester='" + year_code + "' " +
                                " group by course_code" +
                            " )R2 " +
                        " on R1.course_code=R2.course_code where R1.course_code ='" + course_code + "'";

            //SqlSelect = SqlSelect + " ORDER BY course_code";

            return Get_data(SqlSelect);
        }

        public DataTable get_gradereport_student_data(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code, string year_of_enrollment)
        {
            String SqlSelect = "";

            string ws_sem_code = (sem_code == "M") ? "W" : sem_code;

            SqlSelect = " Select * from ( Select distinct dm.dept_name,pm.prog_name,um.* from student_course_allocate_dtl as sca" +
                              " inner join user_mst as um on um.user_id=sca.user_id" +
                              " inner join department_mst as dm on dm.dept_code=um.dept_code" +
                              " inner join programme_mst as pm on pm.prog_code=um.prog_code";

            if (dept_code == "9")
            {
                SqlSelect = SqlSelect + " inner join student_foundation_program_dtl as sfpd on sfpd.user_id = um.user_id ";
            }

            SqlSelect = SqlSelect + " where sca.cancel_flag='N' and sca.semester_type='" + sem_code + "' and sca.year_semester='" + year_code + "'" +
                              " and um.cancel_flag='N' and um.user_status_flag='A' and um.prog_code='" + prog_code + "' ";

            if (dept_code != "9")
            {
                SqlSelect = SqlSelect + " and um.dept_code='" + dept_code + "' ";
            }

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and um.prog_level_code='" + prog_level_code + "' ";
            }
            if (year_of_enrollment != "")
            {
                SqlSelect = SqlSelect + " and um.year_code='" + year_of_enrollment + "' ";
            }

            SqlSelect = SqlSelect + " union ";

            SqlSelect = SqlSelect + "select distinct dm.dept_name,pm.prog_name,um.* from ws_student_course_allocate_dtl as sca" +
                              " inner join user_mst as um on um.user_id=sca.user_id" +
                              " inner join department_mst as dm on dm.dept_code=um.dept_code" +
                              " inner join programme_mst as pm on pm.prog_code=um.prog_code";

            if (dept_code == "9")
            {
                SqlSelect = SqlSelect + " inner join student_foundation_program_dtl as sfpd on sfpd.user_id = um.user_id ";
            }

            SqlSelect = SqlSelect + " where sca.cancel_flag='N' and sca.semester_type='" + ws_sem_code + "' and sca.year_semester='" + year_code + "'" +
                              " and um.cancel_flag='N' and um.user_status_flag='A' and um.prog_code='" + prog_code + "' ";

            if (dept_code != "9")
            {
                SqlSelect = SqlSelect + " and um.dept_code='" + dept_code + "' ";
            }

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and um.prog_level_code='" + prog_level_code + "' ";
            }
            if (year_of_enrollment != "")
            {
                SqlSelect = SqlSelect + " and um.year_code='" + year_of_enrollment + "' ";
            }
            SqlSelect = SqlSelect + " ) t1 ORDER BY t1.user_id asc";

            return Get_data(SqlSelect);
        }

