        public DataTable get_transcript_student_data(string tran_start_sem, string tran_start_year, string dept_code, string prog_code, string prog_level_code, string year_of_enrollment)
        {
            String SqlSelect = "";

            List<Dictionary<string, string>> lst_dic_tran_sem_year = new List<Dictionary<string, string>>();

            lst_dic_tran_sem_year.Add(new Dictionary<string, string>());
            lst_dic_tran_sem_year[0]["sem_code"] = tran_start_sem;
            lst_dic_tran_sem_year[0]["year_code"] = tran_start_year;

            for (int i = 0; i < 3; i++)
            {
                lst_dic_tran_sem_year.Add(new Dictionary<string, string>());

                if (lst_dic_tran_sem_year[i]["sem_code"] == "M")
                {
                    lst_dic_tran_sem_year[i + 1]["sem_code"] = "S";
                    //lst_dic_tran_sem_year[i + 1]["year_code"] = lst_dic_tran_sem_year[i]["year_code"];
                    lst_dic_tran_sem_year[i + 1]["year_code"] = (Convert.ToInt32(lst_dic_tran_sem_year[i]["year_code"]) + 1).ToString();
                }
                else if (lst_dic_tran_sem_year[i]["sem_code"] == "S")
                {
                    lst_dic_tran_sem_year[i + 1]["sem_code"] = "M";
                    //lst_dic_tran_sem_year[i + 1]["year_code"] = (Convert.ToInt32(lst_dic_tran_sem_year[i]["year_code"]) + 1).ToString();
                    lst_dic_tran_sem_year[i + 1]["year_code"] = lst_dic_tran_sem_year[i]["year_code"];
                }
            }

            SqlSelect = @" Select distinct sca.user_id,dm.dept_name,pm.prog_name,  
                            CASE
                        	When SECD.FA_Status = 'N' or SECD.FA_Status IS NULL Then 'FA Not Approved'
                        	When SECD.UGPG_Status = 'N' or SECD.UGPG_Status IS NULL Then 'UGPG Not Approved'
                        	When SECD.Examination_Status = 'N' or SECD.Examination_Status IS NULL  Then 'Examination Not Approved'
                        	Else 
                        	'Approved'
                        	End StatusForApprove,
                        
                            CASE
                        	When SECD.FA_Status = 'N' or SECD.FA_Status IS NULL Then 'N'
                        	When SECD.UGPG_Status = 'N' or SECD.UGPG_Status IS NULL Then 'N'
                        	When SECD.Examination_Status = 'N' or SECD.Examination_Status IS NULL  Then 'N'
                        	Else 
                        	'Y'
                        	End StatusFlag ";
            SqlSelect += " ,um.* " +
                       " from (select user_id from student_course_allocate_dtl" +
                               " where ((semester_type='" + lst_dic_tran_sem_year[0]["sem_code"] + "' and year_semester='" + lst_dic_tran_sem_year[0]["year_code"] + "')" +
                               " or (semester_type='" + lst_dic_tran_sem_year[1]["sem_code"] + "' and year_semester='" + lst_dic_tran_sem_year[1]["year_code"] + "')" +
                               " or (semester_type='" + lst_dic_tran_sem_year[2]["sem_code"] + "' and year_semester='" + lst_dic_tran_sem_year[2]["year_code"] + "')" +
                               " or (semester_type='" + lst_dic_tran_sem_year[3]["sem_code"] + "' and year_semester='" + lst_dic_tran_sem_year[3]["year_code"] + "'))" +
                               " and cancel_flag='N'" +
                               " group by user_id" +
                       " ) as sca " +
                       " inner join user_mst as um on um.user_id=sca.user_id " +
                       " inner join department_mst as dm on dm.dept_code=um.dept_code " +
                       " inner join programme_mst as pm on pm.prog_code=um.prog_code " +
                       " left join  Student_Eligiblity_Convocation_Details SECD ON LTRIM(RTRIM(SECD.student_id)) = sca.user_id  AND SECD.cancel_flag = 'N' " +
                       " where um.dept_code='" + dept_code + "' and um.prog_code='" + prog_code + "'";
            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and um.prog_level_code = '" + prog_level_code + "' ";
            }
            if (year_of_enrollment != "")
            {
                SqlSelect = SqlSelect + " and um.year_code = '" + year_of_enrollment + "' ";
            }

            return Get_data(SqlSelect);
        }

        public DataTable Get_course_for_student_wise_grade(string sem_code, string year_code, string user_prog_code)
        {
            String SqlSelect = "";

            SqlSelect = " SELECT  course_mst.course_code,course_mst.course_credits " +
                        " FROM   course_mst " +
                        " inner join department_wise_course_dtl as cwd on cwd.course_code = course_mst.course_code" +
                        " where course_mst.cancel_flag = 'N' and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                        " and cwd.cancel_flag = 'N' and cwd.semester_type = '" + sem_code + "' and cwd.year_semester = '" + year_code + "' ";

            //if (user_prog_code == "3")
            //{
            //    SqlSelect = SqlSelect + " and cwd.prog_code = '3' ";
            //}
            //else
            //{
            //    SqlSelect = SqlSelect + " and cwd.prog_code in ('1','2') ";
            //}

