        public DataTable get_course_wise_result(string sem_code, string year_code, string prog_level_code)
        {
            String SqlSelect = "";

            SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(5);set @sem='" + sem_code + "';set @year='" + year_code + "';";

            SqlSelect = SqlSelect + @"DECLARE @temp_table TABLE( 
                        course_code varchar(30) NOT NULL,user_id varchar(30) NOT NULL,Total float NULL,course_type char(1) NULL,
                        credits varchar(10) NULL,gpa_nongpa char(1) NULL,semester_type varchar(20) NULL,year_semester varchar(20) NULL,year_code char(5),pass_mark char(5)
                        ); 

                        INSERT @temp_table 
                        select sca.course_code,sca.user_id,
                        (ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)+ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                        ) as Total ,sca.course_type,sca.credits,sca.gpa_nongpa,sca.semester_type,sca.year_semester,SUBSTRING(um.year_code, 2, 5), 
						Case When SUBSTRING(um.year_code, 2, 5) >= '2018' Then '55' Else '50' End pass_mark 
                        from student_exam_marks_dtl as sm
                        inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code
                        inner join user_mst um on um.user_id = sca.user_id and um.user_status_flag='A'
                        where sm.cancel_flag='N' and sm.semester_type=@sem and sm.year_semester=@year 
                        and sca.cancel_flag='N' and sca.semester_type=@sem and sca.year_semester=@year

                        select res1.course_code,course_mst.course_name,res10.instructor_name,course_mst.course_type,course_mst.course_credits,res9.type_name,res9.prog_name,res9.prog_level_desc,
                        res1.students_enrolled,res8.students_passed,(res1.students_enrolled-res8.students_passed) as students_failed,res2.elective_students,res3.gpa_students,
                        res8.gpa_students_passed,res4.nongpa_students,res8.nongpa_students_passed,course_mst.semester_type,course_mst.year_semester 
                        from (select course_code,COUNT(course_code)students_enrolled from student_course_allocate_dtl as sca
                        inner join user_mst um on um.user_id = sca.user_id and um.user_status_flag='A'

                        where semester_type=@sem and year_semester=@year and sca.cancel_flag='N' group by course_code
                        )res1
                        inner join course_mst on course_mst.course_code=res1.course_code 
	                        and course_mst.semester_type=@sem and course_mst.year_semester=@year and course_mst.cancel_flag='N'
                        left join (select course_code,COUNT(course_code)elective_students from student_course_allocate_dtl as sca
                        inner join user_mst um on um.user_id = sca.user_id and um.user_status_flag='A'

                        where semester_type=@sem and year_semester=@year and sca.cancel_flag='N' and course_type='E' group by course_code
                        )res2 on res2.course_code = res1.course_code
                        left join (select course_code,COUNT(course_code)gpa_students from student_course_allocate_dtl as sca
                      inner join user_mst um on um.user_id = sca.user_id and um.user_status_flag='A'

                        where semester_type=@sem and year_semester=@year and sca.cancel_flag='N' and (course_type='M' or (course_type='E' and gpa_nongpa='G')) group by course_code
                        )res3 on res3.course_code = res1.course_code
                        left join (select course_code,COUNT(course_code)nongpa_students from student_course_allocate_dtl as sca
                        inner join user_mst um on um.user_id = sca.user_id and um.user_status_flag='A'
                        where semester_type=@sem and year_semester=@year and sca.cancel_flag='N' and course_type='E' and gpa_nongpa='N' group by course_code
                        )res4 on res4.course_code = res1.course_code
                        left join (select res5.course_code,res5.students_passed,res6.gpa_students_passed,res7.nongpa_students_passed from
	                        (select course_code,COUNT(course_code)students_passed from @temp_table where Total > pass_mark group by course_code
	                        )res5
	                        left join (select course_code,COUNT(course_code)gpa_students_passed from @temp_table where Total > pass_mark and (course_type='M' or (course_type='E' and gpa_nongpa='G')) group by course_code
	                        )res6 on res6.course_code=res5.course_code
	                        left join (select course_code,COUNT(course_code)nongpa_students_passed from @temp_table where Total > pass_mark and course_type='E' and gpa_nongpa='N' group by course_code
	                        )res7 on res7.course_code=res5.course_code
                        )res8 on res8.course_code = res1.course_code
                        left join (select dwc.course_code,dwc.course_typology,course_type_mst.type_name,programme_mst.prog_name,programme_level_mst.prog_level_desc,programme_level_mst.prog_level_code
                                from department_wise_course_dtl as dwc 
	                            inner join course_type_mst on course_type_mst.type_code=dwc.course_typology
                                left join programme_mst on programme_mst.prog_code=dwc.prog_code
                                left join programme_level_mst on programme_level_mst.prog_level_code=dwc.prog_level_code
	                            where dwc.semester_type=@sem and dwc.year_semester=@year
                        )res9 on res9.course_code=res1.course_code
                        left join (SELECT DISTINCT c1.course_code,
				                        STUFF((SELECT distinct ', ' + instructor_mst.instructor_name
						                        FROM course_wise_instructor c2
						                        inner join instructor_mst on instructor_mst.instructor_code=c2.instructor_code and instructor_mst.cancel_flag='N'
						                        WHERE c1.course_code = c2.course_code and c1.cancel_flag = 'N'
								                        and c1.semester_type = c2.semester_type and c1.year_semester = c2.year_semester
						                        FOR XML PATH(''), TYPE
					                            ).value('.', 'NVARCHAR(MAX)')
				                        ,1,2,'') instructor_name
			                        FROM course_wise_instructor c1
			                        where c1.semester_type = @sem and c1.year_semester = @year and c1.cancel_flag='N'
                        )res10 on res10.course_code = res1.course_code";

            SqlSelect = SqlSelect + " Where 1=1";

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and res9.prog_level_code ='" + prog_level_code + "'";
            }

            return Get_data(SqlSelect);
        }
        public DataSet get_student_wise_GP_Ratio_report_without_sws(string sem_code, string year_code, string dept_code, string prog_code)
        {
            String SqlSelect = "";

            SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(5);set @sem='" + sem_code + "';set @year='" + year_code + "';" +
                        "DECLARE @dept varchar(1);DECLARE @prog varchar(5);set @dept='" + dept_code + "';set @prog='" + prog_code + "';";

            SqlSelect = SqlSelect + @"DECLARE @temp_table TABLE( 
                        course_code varchar(30) NOT NULL,user_id varchar(30) NOT NULL,Total float NULL,course_type char(1) NULL,
                        credits int NULL,gpa_nongpa char(1) NULL,semester_type varchar(20) NULL,year_semester varchar(20) NULL,year_code varchar(20) NULL
                        ); 

                        INSERT @temp_table 
                        select sca.course_code,sca.user_id,
                        ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)+ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                        ),0) as Total ,sca.course_type,CAST(sca.credits as int),sca.gpa_nongpa,sca.semester_type,sca.year_semester,umm.year_code 
                        from student_exam_marks_dtl as sm
                        inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code
                        inner join user_mst as umm on umm.user_id=sm.student_code 
                        where sm.cancel_flag='N' and sm.semester_type=@sem and sm.year_semester=@year 
                        and sca.cancel_flag='N' and sca.semester_type=@sem and sca.year_semester=@year
                        order by student_code

                        select tt.user_id,um.user_name,um.year_code,
                        res1.credits_completed,res2.mandatory_credits_completed,res3.elective_credits_completed 
                        from (select user_id from @temp_table group by user_id) as tt
                        left join user_mst as um on um.user_id=tt.user_id
                        left join (select user_id,SUM(credits)credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) group by user_id
                        )res1 on res1.user_id=tt.user_id
                        left join (select user_id,SUM(credits)mandatory_credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) and course_type='M' group by user_id
                        )res2 on res2.user_id=tt.user_id
                        left join (select user_id,SUM(credits)elective_credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) and course_type='E' group by user_id
                        )res3 on res3.user_id=tt.user_id
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + "and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and prog_code=@prog ";

            //SqlSelect = SqlSelect + @"
            //            select tt.*,um.dept_code,um.prog_code from @temp_table as tt
            //            inner join user_mst as um on um.user_id=tt.user_id
            //            where 1=1 ";

            SqlSelect = SqlSelect + @"
                        select tt.*,um.dept_code,um.prog_code from @temp_table as tt
                        inner join user_mst as um on um.user_id=tt.user_id
                        inner join grade_submit_detail as gsd on gsd.course_code=tt.course_code 
			                        and gsd.semester_type=@sem and gsd.year_semester=@year and ugpgoffice_approved='Y'
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + " and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and prog_code=@prog";

            SqlSelect = SqlSelect + " order by tt.user_id,tt.course_code";

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                return ds;
            }
            catch (Exception ex)
            {
                return null;
            }

            //return Get_data(SqlSelect);
        }


