        public DataSet get_student_wise_GP_Ratio_report_new(string sem_code, string year_code, string dept_code, string prog_code, string EnrollmentYear = "")
        {
            string ws_sem = "";
            string ws_year = "";
            if (sem_code == "S")
            {
                ws_sem = "S";
                ws_year = year_code;
            }
            else if (sem_code == "M")
            {
                ws_sem = "W";
                ws_year = year_code;
            }

            String SqlSelect = "";

            SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(5);set @sem='" + sem_code + "';set @year='" + year_code + "';" +
                        "DECLARE @dept varchar(2);DECLARE @prog varchar(5);set @dept='" + dept_code + "';set @prog='" + prog_code + "';" +
                        "DECLARE @ws_sem varchar(1);DECLARE @ws_year varchar(5);set @ws_sem='" + ws_sem + "';set @ws_year='" + ws_year + "';";

            SqlSelect = SqlSelect + @"DECLARE @temp_table TABLE( 
                        course_code varchar(30) NOT NULL,user_id varchar(30) NOT NULL,Total float NULL,course_type char(1) NULL,
                        credits int NULL,gpa_nongpa char(1) NULL,semester_type varchar(20) NULL,year_semester varchar(20) NULL,year_code varchar(20) NULL,
                        course_name varchar(250) NULL,BatchYear nvarchar(10) NULL,AdmissionYear nvarchar(10) NULL
                        ); 

                        INSERT @temp_table 
                        select sca.course_code,sca.user_id,
                        ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)+ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                        ),0) as Total ,sca.course_type,CAST(sca.credits as int),sca.gpa_nongpa,sca.semester_type,sca.year_semester,umm.year_code, cm.course_name ,SUBSTRING(umm.year_code,2,10) BatchYear,SUBSTRING(umm.admission_year,2,10) AdmissionYear
                        from student_exam_marks_dtl as sm
                        inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code AND sm.year_semester =sca.year_semester AND sm.semester_type = sca.semester_type
                        inner join course_mst as cm on cm.course_code = sca.course_code AND cm.year_semester = sca.year_semester AND cm.semester_type = sca.semester_type
                        inner join user_mst as umm on umm.user_id=sm.student_code 
                        where sm.cancel_flag='N' " + (sem_code != "" && sem_code != null ? " and sm.semester_type=@sem  " : "") + (year_code != "" && year_code != null ? "  and sm.year_semester=@year " : "") + @"
                        and sca.cancel_flag='N' " + (sem_code != "" && sem_code != null ? " and sca.semester_type=@sem " : "") + (year_code != "" && year_code != null ? "  and sca.year_semester=@year " : "") + @"
                        " + (sem_code != "" && sem_code != null ? "and cm.semester_type=@sem  " : "") + (year_code != "" && year_code != null ? "  and cm.year_semester=@year " : "") + (EnrollmentYear != "" && EnrollmentYear != null ? " and umm.year_code ='" + EnrollmentYear + "'" : "") + @"
                        union
                        select sca.course_code,sca.user_id,
                        ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)+ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                        ),0) as Total ,sca.course_type,CAST(sca.credits as int),sca.gpa_nongpa,sca.semester_type,sca.year_semester,umm.year_code,cm.course_name ,SUBSTRING(umm.year_code,2,10) BatchYear,SUBSTRING(umm.admission_year,2,10) AdmissionYear
                        from ws_student_exam_marks_dtl as sm
                        inner join ws_student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code AND sm.year_semester =sca.year_semester AND sm.semester_type = sca.semester_type
                        inner join ws_course_mst as cm on cm.course_code = sca.course_code AND cm.year_semester =sca.year_semester AND cm.semester_type = sca.semester_type
                        inner join user_mst as umm on umm.user_id=sm.student_code 
                        where sm.cancel_flag='N' " + (sem_code != "" && sem_code != null ? " and sm.semester_type=@ws_sem  " : "") + (year_code != "" && year_code != null ? " and sm.year_semester=@ws_year " : "") + @"
                        and sca.cancel_flag='N' " + (sem_code != "" && sem_code != null ? " and sca.semester_type= @ws_sem  " : "") + (year_code != "" && year_code != null ? " and sca.year_semester=@ws_year " : "") + @" " + (sem_code != "" && sem_code != null ? " and cm.semester_type=@ws_sem " : "") + (year_code != "" && year_code != null ? "and cm.year_semester=@ws_year " : "") + (EnrollmentYear != "" && EnrollmentYear != null ? " and umm.year_code ='" + EnrollmentYear + "'" : "") + @"

                        select tt.user_id,um.user_name,um.year_code,SUBSTRING(year_code,2,10) BatchYear,SUBSTRING(um.admission_year,2,10) AdmissionYear,
                        res1.credits_completed,res2.mandatory_credits_completed,res3.elective_credits_completed 
                        from (select user_id from @temp_table group by user_id) as tt
                        left join user_mst as um on um.user_id=tt.user_id
                        left join (select user_id,SUM(credits)credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) group by user_id
                        )res1 on res1.user_id=tt.user_id
                        left join (select user_id,SUM(credits)mandatory_credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) and course_type='M' group by user_id
                        )res2 on res2.user_id=tt.user_id
                        left join (select user_id,SUM(credits)elective_credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) and course_type='E' group by user_id
                        )res3 on res3.user_id=tt.user_id
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + " and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and prog_code=@prog ";

            //SqlSelect = SqlSelect + @"
            //            select tt.*,um.dept_code,um.prog_code from @temp_table as tt
            //            inner join user_mst as um on um.user_id=tt.user_id
            //            where 1=1 ";

            SqlSelect = SqlSelect + @"
                        order by tt.user_id

                        select tt.*,um.dept_code,um.prog_code,dm.dept_name,ctm.type_name,'NONSWS' as swscourse,
                        pm.prog_name as prog_name ,pml.prog_level_name + ' (' + pml.prog_level_desc +' )' as prog_level_code from @temp_table as tt
                        inner join user_mst as um on um.user_id=tt.user_id
                        left join department_mst as dm on dm.dept_code = um.dept_code /*--@dept*/
                        left join department_wise_course_dtl as dwcd on dwcd.course_code=tt.course_code and dwcd.semester_type=tt.semester_type and dwcd.year_semester=tt.year_semester
                        left join course_type_mst as ctm on ctm.type_code=dwcd.course_typology
                        left join programme_mst as pm on pm.prog_code = um.prog_code
                        left join programme_level_mst as pml on pml.prog_level_code = um.prog_level_code
                        inner join grade_submit_detail as gsd on gsd.course_code=tt.course_code and gsd.semester_type=tt.semester_type and gsd.year_semester=tt.year_semester and ugpgoffice_approved='Y'
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + " and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and um.prog_code=@prog";

            SqlSelect = SqlSelect + @"
                        union
                        select tt.*,um.dept_code,um.prog_code,dm.dept_name,'NA','SWS' as swscourse,
                        pm.prog_name as prog_name ,pml.prog_level_name + ' (' + pml.prog_level_desc +' )' as prog_level_code from @temp_table as tt
                        inner join user_mst as um on um.user_id=tt.user_id
                        left join department_mst as dm on dm.dept_code =  um.dept_code /*--@dept*/
                        left join programme_mst as pm on pm.prog_code = um.prog_code
                        left join programme_level_mst as pml on pml.prog_level_code = um.prog_level_code
                        inner join ws_grade_submit_detail as gsd on gsd.course_code=tt.course_code and gsd.semester_type=tt.semester_type and gsd.year_semester=tt.year_semester and ugpgoffice_approved='Y'
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + " and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and um.prog_code=@prog";

            SqlSelect = SqlSelect + " order by tt.user_id,tt.course_code";

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                return ds;
            }
            catch (Exception ex)
            {
                return null;
            }

            //return Get_data(SqlSelect);
        }


        public DataSet get_student_wise_GP_Ratio_report(string sem_code, string year_code, string dept_code, string prog_code)
        {
            string ws_sem = "";
            string ws_year = "";
            if (sem_code == "S")
            {
                ws_sem = "S";
                ws_year = year_code;
            }
            else if (sem_code == "M")
            {
                ws_sem = "W";
                ws_year = year_code;
            }

            String SqlSelect = "";

            SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(5);set @sem='" + sem_code + "';set @year='" + year_code + "';" +
                        "DECLARE @dept varchar(2);DECLARE @prog varchar(5);set @dept='" + dept_code + "';set @prog='" + prog_code + "';" +
                        "DECLARE @ws_sem varchar(1);DECLARE @ws_year varchar(5);set @ws_sem='" + ws_sem + "';set @ws_year='" + ws_year + "';";

            SqlSelect = SqlSelect + @"DECLARE @temp_table TABLE( 
                        course_code varchar(30) NOT NULL,user_id varchar(30) NOT NULL,Total float NULL,course_type char(1) NULL,
                        credits int NULL,gpa_nongpa char(1) NULL,semester_type varchar(20) NULL,year_semester varchar(20) NULL,year_code varchar(20) NULL
                        ); 

                        INSERT @temp_table 
                        select sca.course_code,sca.user_id,
                        ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)+ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                        ),0) as Total ,sca.course_type,CAST(sca.credits as int),sca.gpa_nongpa,sca.semester_type,sca.year_semester,umm.year_code 
                        from student_exam_marks_dtl as sm
                        inner join student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code
                        inner join user_mst as umm on umm.user_id=sm.student_code 
                        where sm.cancel_flag='N' and sm.semester_type=@sem and sm.year_semester=@year 
                        and sca.cancel_flag='N' and sca.semester_type=@sem and sca.year_semester=@year
                        union
                        select sca.course_code,sca.user_id,
                        ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)+ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                        ),0) as Total ,sca.course_type,CAST(sca.credits as int),sca.gpa_nongpa,sca.semester_type,sca.year_semester,umm.year_code 
                        from ws_student_exam_marks_dtl as sm
                        inner join ws_student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code
                        inner join user_mst as umm on umm.user_id=sm.student_code 
                        where sm.cancel_flag='N' and sm.semester_type=@ws_sem and sm.year_semester=@ws_year 
                        and sca.cancel_flag='N' and sca.semester_type=@ws_sem and sca.year_semester=@ws_year

                        select tt.user_id,um.user_name,um.year_code,
                        res1.credits_completed,res2.mandatory_credits_completed,res3.elective_credits_completed,department_mst.dept_name as dept_name_1,pm.prog_name as prog_name_1 ,pml.prog_level_name + ' (' + pml.prog_level_desc +' )' as prog_level_code_1 
                        from (select user_id from @temp_table group by user_id) as tt
                        left join user_mst as um on um.user_id=tt.user_id
                        left join department_mst on department_mst.dept_code = um.dept_code
                        left join programme_mst pm on pm.prog_code = um.prog_code
                        left join programme_level_mst pml on pml.prog_level_code = um.prog_level_code
                        left join (select user_id,SUM(credits)credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) group by user_id
                        )res1 on res1.user_id=tt.user_id
                        left join (select user_id,SUM(credits)mandatory_credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) and course_type='M' group by user_id
                        )res2 on res2.user_id=tt.user_id
                        left join (select user_id,SUM(credits)elective_credits_completed from @temp_table where (Total>(case when year_code > 'Y2017' then 54 else 49 end)) and course_type='E' group by user_id
                        )res3 on res3.user_id=tt.user_id
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + " and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and um.prog_code=@prog ";

            //SqlSelect = SqlSelect + @"
            //            select tt.*,um.dept_code,um.prog_code from @temp_table as tt
            //            inner join user_mst as um on um.user_id=tt.user_id
            //            where 1=1 ";

            SqlSelect = SqlSelect + @"
                        order by tt.user_id

                        select tt.*,um.dept_code,um.prog_code,dm.dept_name,ctm.type_name from @temp_table as tt
                        inner join user_mst as um on um.user_id=tt.user_id
                        inner join department_mst as dm on dm.dept_code = @dept
                        left join department_wise_course_dtl as dwcd on dwcd.course_code=tt.course_code and dwcd.semester_type=@sem and dwcd.year_semester=@year
						left join course_type_mst as ctm on ctm.type_code=dwcd.course_typology
                        inner join grade_submit_detail as gsd on gsd.course_code=tt.course_code 
			                        and gsd.semester_type=@sem and gsd.year_semester=@year and ugpgoffice_approved='Y'
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + " and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and um.prog_code=@prog";

            SqlSelect = SqlSelect + @"
                        union
                        select tt.*,um.dept_code,um.prog_code,dm.dept_name,'NA' from @temp_table as tt
                        inner join user_mst as um on um.user_id=tt.user_id
                        inner join department_mst as dm on dm.dept_code = @dept
                        inner join ws_grade_submit_detail as gsd on gsd.course_code=tt.course_code 
			                        and gsd.semester_type=@ws_sem and gsd.year_semester=@ws_year and ugpgoffice_approved='Y'
                        where 1=1 ";

            if (dept_code != "")
                SqlSelect = SqlSelect + " and um.dept_code=@dept ";

            if (prog_code != "")
                SqlSelect = SqlSelect + " and um.prog_code=@prog";

            SqlSelect = SqlSelect + " order by tt.user_id,tt.course_code";

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                return ds;
            }
            catch (Exception ex)
            {
                return null;
            }

            //return Get_data(SqlSelect);
        }

