        public DataTable Calculate_GP_grade_for_all_students(DataTable dt_stud_detail, DataTable dt_course_detail, DataTable dt_grade_range)//, DataTable dt_ws_grade_range
        {
            if (dt_stud_detail != null && dt_stud_detail.Rows.Count > 0 && dt_course_detail != null && dt_course_detail.Rows.Count > 0)
            {
                try
                {
                    dt_course_detail.Columns.Add("grade");
                    dt_course_detail.Columns.Add("grade_point");
                    dt_course_detail.Columns.Add("remarks");

                    for (int i = 0; i < dt_course_detail.Rows.Count; i++)
                    {
                        DataRow[] dr_student = dt_stud_detail.Select("user_id='" + dt_course_detail.Rows[i]["user_id"].ToString() + "'");

                        if (dr_student.Length > 0)
                        {
                            int year = Convert.ToInt32((dr_student[0]["year_code"].ToString()).Substring(1));

                            double subject_marks = Convert.ToDouble(dt_course_detail.Rows[i]["Total"].ToString());

                            string str_course = dt_course_detail.Rows[i]["course_code"].ToString();

                            DataRow[] course_range = dt_grade_range.Select("course_code = '" + str_course + "'");

                            //DataRow[] ws_course_range = dt_ws_grade_range.Select("course_code = '" + str_course + "'");

                            bool gpa_less_9_flag = false;

                            if (course_range.Length > 0)
                            {

                                if (course_range[0]["A_plus_from"].ToString() == "87")
                                {
                                    gpa_less_9_flag = true;
                                }

                                if (dt_course_detail.Rows[i]["course_type"].ToString() == "E" && dt_course_detail.Rows[i]["gpa_nongpa"].ToString() == "N" || dt_course_detail.Rows[i]["course_type"].ToString() == "M" && dt_course_detail.Rows[i]["gpa_nongpa"].ToString() == "N")
                                {
                                    if (year >= 2018)
                                    {
                                        if (subject_marks < 55)
                                        {
                                            dt_course_detail.Rows[i]["grade"] = "NP";
                                            dt_course_detail.Rows[i]["grade_point"] = "NA";
                                            dt_course_detail.Rows[i]["remarks"] = "FAIL";
                                        }
                                        else if (subject_marks >= 55)
                                        {
                                            dt_course_detail.Rows[i]["grade"] = "P";
                                            dt_course_detail.Rows[i]["grade_point"] = "NA";
                                            dt_course_detail.Rows[i]["remarks"] = "PASS";
                                        }
                                    }
                                    else
                                    {
                                        if (subject_marks < 50)
                                        {
                                            dt_course_detail.Rows[i]["grade"] = "NP";
                                            dt_course_detail.Rows[i]["grade_point"] = "NA";
                                            dt_course_detail.Rows[i]["remarks"] = "FAIL";
                                        }
                                        else if (subject_marks >= 50)
                                        {
                                            dt_course_detail.Rows[i]["grade"] = "P";
                                            dt_course_detail.Rows[i]["grade_point"] = "NA";
                                            dt_course_detail.Rows[i]["remarks"] = "PASS";
                                        }
                                    }
                                }
                                else if (year >= 2018)
                                {
