        public DataTable get_WS_Course_Detail_New(string yearcode, string dept_code, string prog_code)
        {
            DataTable dt_course_detail = new DataTable();

            try
            {
                SqlCommand cmd = con.CreateCommand();

                string SqlQuery = @"  Select um.year_code,um.full_name
                                      ,UPPER(department_mst.dept_name)dept_name,UPPER(programme_mst.prog_name)prog_name,
                                      (sm.semester_type + ' ' + sm.year_semester) as semyear,
                                      um.user_id, ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0) +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0) ),0) as Total ,(sca.course_type)c_type,sca.gpa_nongpa,cm.* ,wcwgr.*
                                      from ws_student_exam_marks_dtl as sm 
                                      inner join ws_student_course_allocate_dtl as sca on sca.user_id=sm.student_code and sca.course_code=sm.course_code 
                                      inner join ws_course_mst as cm on cm.course_code=sm.course_code 
                                      inner join ws_grade_submit_detail as gsd on gsd.course_code=sm.course_code 
                                      INNER JOIN ws_course_wise_grade_range as wcwgr on wcwgr.course_code = sm.course_code
                                      Inner join user_mst um on um.user_id = sm.student_code
                                      inner join department_mst on department_mst.dept_code = um.dept_code and department_mst.cancel_flag='N'
                                      inner join programme_mst on programme_mst.prog_code = um.prog_code and programme_mst.cancel_flag='N'
                                      where sm.cancel_flag='N' 
                                      and sca.cancel_flag='N' 
                                      and cm.cancel_flag='N'  and gsd.cancel_flag='N' and gsd.ugpgoffice_approved='Y' and wcwgr.cancel_flag='N'
                                      and um.year_code ='" + yearcode + "'";

                if (dept_code != "")
                {
                    SqlQuery += " and um.dept_code = '" + dept_code + "'";
                }

                if (prog_code != "")
                {
                    SqlQuery += " and um.prog_code = '" + prog_code + "'";
                }

                SqlQuery += " order by um.user_id";
                cmd.CommandText = SqlQuery;

                cmd.CommandType = CommandType.Text;

                SqlDataAdapter da = new SqlDataAdapter(cmd);

                dt_course_detail = new DataTable();

                da.Fill(dt_course_detail);
            }
            catch (Exception ex)
            {
            }

            if (dt_course_detail.Rows.Count <= 0)
                return null;
            else
                return dt_course_detail;
        }

