        public DataTable FilterCourseResults(DataTable course_exam_data, string dept_code, string prog_code, string prog_level_code, string sem_code, string year_code, string course_typology, string time)
        {
            DataTable dt_filter_data = new DataTable();
            try
            {
                SqlCommand cmd = con.CreateCommand();

                cmd.CommandText = "select * from department_wise_course_dtl where ";

                if (course_exam_data != null)
                {
                    for (int i = 0; i < course_exam_data.Rows.Count; i++)
                    {
                        if (i == 0)
                        {
                            cmd.CommandText += "course_code in ('" + course_exam_data.Rows[i]["course_code"].ToString() + "'";
                        }
                        else
                        {
                            cmd.CommandText += ",'" + course_exam_data.Rows[i]["course_code"].ToString() + "'";
                        }
                    }
                }

                if (time == "SECOND")
                {
                    cmd.CommandText += ") ";
                }
                else
                {
                    cmd.CommandText += " 1=1 ";
                }

                if (dept_code != "")
                    cmd.CommandText += "and dept_code='" + dept_code + "' ";

                if (prog_code != "")
                    cmd.CommandText += "and prog_code='" + prog_code + "' ";

                if (prog_level_code != "")
                    cmd.CommandText += "and prog_level_code='" + prog_level_code + "' ";

                if (course_typology != "")
                    cmd.CommandText += "and course_typology='" + course_typology + "' ";

                cmd.CommandText += "and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N'";

                cmd.CommandType = CommandType.Text;

                SqlDataAdapter da = new SqlDataAdapter(cmd);

                dt_filter_data = new DataTable();

                da.Fill(dt_filter_data);

            }
            catch (Exception ex)
            {
            }

            if (dt_filter_data.Rows.Count <= 0)
                return null;
            else
                return dt_filter_data;
        }

