                                    total_gpa_marks = total_gpa_marks + (Convert.ToDouble(dt_course_grade_detail.Rows[i]["course_credits"].ToString()) * Convert.ToDouble(dt_course_grade_detail.Rows[i]["Total"].ToString()));
