        public DataTable get_mid_term_marks_dtl(string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            //SqlSelect = " select * from student_exam_marks_dtl where student_code='" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' ";
            SqlSelect = " select sem.*,cm.course_name,ctm.sub_group,um.prog_level_code,(sca.course_type)c_type,sca.gpa_nongpa from student_exam_marks_dtl as sem " +
                            " inner join course_mst as cm on cm.course_code=sem.course_code and cm.semester_type=sem.semester_type " +
                            " and cm.year_semester=sem.year_semester and cm.cancel_flag='N' " +
                            " inner join department_wise_course_dtl as dwcd on dwcd.course_code = sem.course_code and dwcd.semester_type = sem.semester_type and dwcd.year_semester=sem.year_semester and dwcd.cancel_flag='N' " +
                            " inner join course_type_mst as ctm on ctm.type_code = dwcd.course_typology " +
                            " inner join user_mst as um on um.user_id = sem.student_code " +
                            " inner join student_course_allocate_dtl as sca on sca.user_id = sem.student_code and sca.course_code = sem.course_code " +
                            " where sem.semester_type='" + sem_code + "' and sem.year_semester='" + year_code + "' and sem.student_code='" + user_id + "' and sem.cancel_flag='N' and sca.cancel_flag='N' and sca.semester_type='" + sem_code + "' and sca.year_semester='" + year_code + "'";

            return Get_data(SqlSelect);
        }

        public DataTable get_mid_term_exam_dtl(string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            //SqlSelect = " select * from exam_master where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' " +
            //            " and exam_type in ('MT','IN') and is_submit='Y' and course_code in (select course_code from student_exam_marks_dtl " +
            //            " where student_code='" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N') ";

            SqlSelect = " select ctm.sub_group ,em.* from exam_master em " +
                        " inner join department_wise_course_dtl dwcd on dwcd.course_code = em.course_code and dwcd.semester_type = em.semester_type and dwcd.year_semester = em.year_semester and dwcd.cancel_flag = 'N' " +
                        " inner join course_type_mst ctm on ctm.type_code = dwcd.course_typology " +
                        " where em.semester_type = '" + sem_code + "' and em.year_semester = '" + year_code + "' and em.cancel_flag = 'N'  and em.exam_type in ('MT', 'IN') and em.is_submit = 'Y' " +
                        " and em.course_code in (select course_code from student_exam_marks_dtl where student_code = '" + user_id + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N') ";

            return Get_data(SqlSelect);
        }

        public DataTable get_mid_term_student_marks(string sem_code, string year_code, string user_id, bool feedback_status)
        {
            DataTable dt_marks_dtl = get_mid_term_marks_dtl(sem_code, year_code, user_id);
            DataTable dt_exam_dtl = get_mid_term_exam_dtl(sem_code, year_code, user_id);

            if (dt_marks_dtl != null && dt_exam_dtl != null)
            {
                DataTable dt_student_marks = new DataTable();

                dt_student_marks.Columns.Add("course_code");
                dt_student_marks.Columns.Add("course_name");
                dt_student_marks.Columns.Add("mt_obtained_marks", typeof(float));
                dt_student_marks.Columns.Add("mt_total_marks", typeof(float));
                dt_student_marks.Columns.Add("mt_absent_dtl", typeof(string));
                dt_student_marks.Columns.Add("in_obtained_marks", typeof(float));
                dt_student_marks.Columns.Add("in_total_marks", typeof(float));
                dt_student_marks.Columns.Add("in_absent_dtl", typeof(string));
                dt_student_marks.Columns.Add("sub_group", typeof(string));

                if (feedback_status)
                {
                    dt_student_marks.Columns.Add("sub_group_id", typeof(string));
                    dt_student_marks.Columns.Add("prog_level_code", typeof(string));
                }

                if (dt_exam_dtl.Rows.Count > 0)
                {
                    for (int i = 0; i < dt_marks_dtl.Rows.Count; i++)
                    {
                        DataRow[] dr_exam_dtl = dt_exam_dtl.Select("course_code='" + dt_marks_dtl.Rows[i]["course_code"].ToString() + "'");

                        if (dr_exam_dtl.Length > 0)
                        {
                            DataRow dr_student_marks = dt_student_marks.NewRow();
                            dr_student_marks["course_code"] = dt_marks_dtl.Rows[i]["course_code"].ToString();
                            dr_student_marks["course_name"] = dt_marks_dtl.Rows[i]["course_name"].ToString();
                            dr_student_marks["mt_obtained_marks"] = 0;
                            dr_student_marks["mt_total_marks"] = 0;
                            dr_student_marks["mt_absent_dtl"] = "";
                            dr_student_marks["in_obtained_marks"] = 0;
                            dr_student_marks["in_total_marks"] = 0;
                            dr_student_marks["in_absent_dtl"] = "";

                            if (feedback_status)
                            {
                                dr_student_marks["sub_group_id"] = dt_marks_dtl.Rows[i]["sub_group"].ToString();
                                dr_student_marks["prog_level_code"] = dt_marks_dtl.Rows[i]["prog_level_code"].ToString();
                            }

                            for (int j = 0; j < dr_exam_dtl.Length; j++)
                            {
                                dr_student_marks["sub_group"] = dr_exam_dtl[j]["sub_group"].ToString();

                                if (dr_exam_dtl[j]["exam_type"].ToString() == "MT")
                                {
                                    if (dt_marks_dtl.Rows[i][dr_exam_dtl[j]["exam_code"].ToString() + "_w"].ToString() != "")
                                    {
                                        //dr_student_marks["mt_obtained_marks"] = float.Parse(dr_student_marks["mt_obtained_marks"].ToString()) + float.Parse(dt_marks_dtl.Rows[i][dr_exam_dtl[j]["exam_code"].ToString()].ToString());
                                        //dr_student_marks["mt_total_marks"] = float.Parse(dr_student_marks["mt_total_marks"].ToString()) + 100;
                                        dr_student_marks["mt_obtained_marks"] = float.Parse(dr_student_marks["mt_obtained_marks"].ToString()) + float.Parse(dt_marks_dtl.Rows[i][dr_exam_dtl[j]["exam_code"].ToString() + "_w"].ToString());
                                        dr_student_marks["mt_total_marks"] = float.Parse(dr_student_marks["mt_total_marks"].ToString()) + float.Parse(dr_exam_dtl[j]["weightage"].ToString());
                                    }
                                    else if (dt_marks_dtl.Rows[i]["absent_" + dr_exam_dtl[j]["exam_code"].ToString()].ToString() != "")
                                    {
                                        dr_student_marks["mt_absent_dtl"] = dt_marks_dtl.Rows[i]["absent_" + dr_exam_dtl[j]["exam_code"].ToString()].ToString();
                                        dr_student_marks["mt_total_marks"] = float.Parse(dr_student_marks["mt_total_marks"].ToString()) + float.Parse(dr_exam_dtl[j]["weightage"].ToString());
                                    }
                                }
                                //else if (dr_exam_dtl[j]["exam_type"].ToString() == "IN" && feedback_status == true)
                                else if (dr_exam_dtl[j]["exam_type"].ToString() == "IN" && dr_exam_dtl[j]["sub_group"].ToString() != "SG003")
                                {
                                    if (dt_marks_dtl.Rows[i][dr_exam_dtl[j]["exam_code"].ToString() + "_w"].ToString() != "")
                                    {
                                        dr_student_marks["in_obtained_marks"] = float.Parse(dr_student_marks["in_obtained_marks"].ToString()) + float.Parse(dt_marks_dtl.Rows[i][dr_exam_dtl[j]["exam_code"].ToString() + "_w"].ToString());
                                        dr_student_marks["in_total_marks"] = float.Parse(dr_student_marks["in_total_marks"].ToString()) + float.Parse(dr_exam_dtl[j]["weightage"].ToString());
                                    }
                                    else if (dt_marks_dtl.Rows[i]["absent_" + dr_exam_dtl[j]["exam_code"].ToString()].ToString() != "")
                                    {
                                        dr_student_marks["in_absent_dtl"] = dt_marks_dtl.Rows[i]["absent_" + dr_exam_dtl[j]["exam_code"].ToString()].ToString();
                                        dr_student_marks["in_total_marks"] = float.Parse(dr_student_marks["in_total_marks"].ToString()) + float.Parse(dr_exam_dtl[j]["weightage"].ToString());
                                    }
                                }
                            }

                            dt_student_marks.Rows.Add(dr_student_marks);

                        }
                    }
                }

                if (dt_student_marks.Rows.Count > 0)
                {
                    return dt_student_marks;
                }
                else
                {
                    return null;
                }
            }
            else
            {
                return null;
            }
        }
