        public DataTable get_Student_transcript_dtl(string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @" Select stcd.completion_date,stcd.convocation_year,COALESCE(
                          NULLIF(
                              COALESCE(NULLIF(instructor_mst.title, ''), '') + ' ' +
                              COALESCE(NULLIF(instructor_mst.first_name, ''), '') + ' ' + 
                              COALESCE(NULLIF(instructor_mst.last_name, ''), '') , '  '), instructor_name ) AS name," +
                        " std.* from student_transcript_dtl std " +
                        // + " left join student_transcript_convocation_date stcd on stcd.completion_date_code = std.completion_date_code"
                        " left join student_transcript_completion_date stcd on stcd.completion_date_code = std.completion_date_code " +
                        " left join student_wise_drp_dtl on student_wise_drp_dtl.user_id = std.user_id " +
                        " and student_wise_drp_dtl.cancel_flag = 'N' " +
                        " left join course_wise_drp_dtl on course_wise_drp_dtl.drp_code = student_wise_drp_dtl.drp_code " +
                        " and course_wise_drp_dtl.course_code = student_wise_drp_dtl.course_code and course_wise_drp_dtl.cancel_flag = 'N' " +
                        " left join instructor_mst on instructor_mst.user_id = course_wise_drp_dtl.instructor_code " +
                        " where std.user_id = '" + user_id + "'";

            return Get_data(SqlSelect);

        }


        public DataTable GetStudentDetailsPersonal(string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @" Select um.user_id,um.user_name,um.mail,Format(um.dob,'dd-MM-yyyy') DOB,dm.dept_name,programme_level_mst.prog_level_name,pm.prog_name,
                           student_apaar_id.university_register_id,student_apaar_id.apaar_id,
                           SUBSTRING(um.year_code, 2, 5) AS year_code, SUBSTRING(um.admission_year, 2, 5) AS admission_year,
                           STUFF((SELECT ', ' + cwdd.topic 
                                  FROM student_wise_drp_dtl swdd
                                  INNER JOIN course_wise_drp_dtl cwdd 
                                      ON cwdd.drp_code = swdd.drp_code 
                                      AND cwdd.cancel_flag = 'N'
                                  WHERE swdd.user_id = '" + user_id + @"' 
                                      AND swdd.cancel_flag = 'N'
                                  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS topic,

                           (Select COALESCE(
                            NULLIF(
                            COALESCE(NULLIF(instructor_mst.title, ''), '') + ' ' + 
                            COALESCE(NULLIF(instructor_mst.first_name, ''), '') + ' ' + 
                            COALESCE(NULLIF(instructor_mst.last_name, ''), ''), '  '), 
                            instructor_name
                            ) AS name from student_wise_drp_dtl swdd
						   INNER JOIN course_wise_drp_dtl cwdd on cwdd.drp_code =  swdd.drp_code and cwdd.cancel_flag ='N'
						   left join instructor_mst on instructor_mst.user_id = cwdd.instructor_code
						   where swdd.user_id = '" + user_id + @"' and swdd.cancel_flag='N')instname

                            from user_mst um
                           left
                            join programme_level_mst on programme_level_mst.prog_level_code = um.prog_level_code
                           left
                            join department_mst dm on dm.dept_code = um.dept_code
                           left
                            join programme_mst pm on pm.prog_code = um.prog_code
                            LEFT join student_id_master on student_id_master.student_id = um.user_id and student_id_master.cancel_flag='N' 
							LEFT join student_apaar_id on student_apaar_id.university_register_id = student_id_master.university_register_id and student_apaar_id.cancel_flag='N' 
                           where user_id = '" + user_id + @"'";

            return Get_data(SqlSelect);
        }

        public BLReturnObject save_Student_transcript_dtl(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Transcript_Detail server_course_master = (DSC_Transcript_Detail)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                server_course_master.EnforceConstraints = false;

                server_course_master.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, server_course_master.student_transcript_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != server_course_master.student_transcript_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

