        public DataTable ws_course_wise_entered_marks_list(string user_id, string user_type, string sem_code, string year_code, string user_prog_code)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (user_type == "I2" || user_type == "PC" || user_type == "D")
            {
                SqlSelect = "select res3.*,  (case ws_grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval',  " +
                            " (case ws_grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval',  " +
                            " (case ws_grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval',  " +
                            " (case ws_grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval'  " +
                            " from  ( select res1.* " +
                                " from (  select exams.course_code,exams.course_name,exams.total_exams,students.total_students " +
                                    " from (select ws_course_mst.course_code,ws_course_mst.course_name,exams1.total_exams " +
                                        " from ws_course_mst  " +
                                        " left join(select course_code,COUNT(exam_code)total_exams " +
                                                " from ws_exam_master where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' " +
                                                " group by course_code " +
                                        " )exams1 " +
                                        " on ws_course_mst.course_code=exams1.course_code " +
                                        " where ws_course_mst.semester_type='" + sem_code + "' and ws_course_mst.year_semester='" + year_code + "' and cancel_flag='N' " +
                                    " )exams " +
                                    " left join  (SELECT course_code,COUNT(user_id)total_students " +
                                            " FROM ws_student_course_allocate_dtl " +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag = 'N' group by course_code " +
                                    " )students " +
                                    " on exams.course_code=students.course_code " +
                                " )res1  " +
                                " inner join  ( select ws_course_wise_instructor.*,instructor_mst.user_id,instructor_mst.instructor_name  " +
                                        " from ws_course_wise_instructor " +
                                        " inner join instructor_mst on instructor_mst.instructor_code=ws_course_wise_instructor.instructor_code " +
                                        " where instructor_mst.user_id='" + user_id + "' and ws_course_wise_instructor.semester_type = '" + sem_code + "' " +
                                        " and ws_course_wise_instructor.year_semester = '" + year_code + "' " +
                                " )res2 " +
                                " on res1.course_code = res2.course_code  " +
                            " )res3  " +
                            " left join ws_grade_submit_detail on ws_grade_submit_detail.course_code = res3.course_code and ws_grade_submit_detail.semester_type='" + sem_code + "' and ws_grade_submit_detail.year_semester='" + year_code + "'  " +
                            " where total_students > 0" +
                            " order by res3.course_code";
            }
            else if (user_type == "FA")
            {
                SqlSelect = "select res1.*, " +
                            " (case ws_grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval', " +
                            " (case ws_grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval', " +
                            " (case ws_grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " (case ws_grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval' " +
                            " from " +
                            " ( select exams.course_code,exams.course_name,exams.total_exams,students.total_students from" +
                            " (select ws_course_mst.course_code,ws_course_mst.course_name,exams1.total_exams from ws_course_mst " +
                                " left join(select course_code,COUNT(exam_code)total_exams from ws_exam_master" +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'" +
                                            " group by course_code" +
                                        " )exams1" +
                                " on ws_course_mst.course_code=exams1.course_code" +
                                " where ws_course_mst.semester_type='" + sem_code + "' and ws_course_mst.year_semester='" + year_code + "' and cancel_flag='N'" +
                            " )exams" +
