                            " left join ws_grade_submit_detail on ws_grade_submit_detail.course_code = res1.course_code and ws_grade_submit_detail.semester_type='" + sem_code + "' and ws_grade_submit_detail.year_semester='" + year_code + "' " +
                            " inner join (SELECT distinct ws_course_mst.course_code" +
                                " FROM ws_course_mst  " +
                                " inner join department_wise_user_dtl on department_wise_user_dtl.dept_code = ws_course_mst.dept_code" +
                                " where ws_course_mst.cancel_flag='N' and ws_course_mst.semester_type = '" + sem_code + "' and ws_course_mst.year_semester = '" + year_code + "' " +
                                " and department_wise_user_dtl.user_id='" + user_id + "' and department_wise_user_dtl.user_type='FA' " +
                                " and department_wise_user_dtl.semester_type = '" + sem_code + "' and department_wise_user_dtl.year_semester = '" + year_code + "' " +
                            " )d on d.course_code = res1.course_code " +
                            " where total_students > 0" +
                            " order by res1.course_code";
            }
            else if (user_type == "WSA" || user_type == "A")
            {
                SqlSelect = "select res1.*, " +
                            " (case ws_grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval', " +
                            " (case ws_grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval', " +
                            " (case ws_grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " (case ws_grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval' " +
                            " from " +
                            " ( select exams.course_code,exams.course_name,exams.total_exams,students.total_students from" +
                            " (select ws_course_mst.course_code,ws_course_mst.course_name,exams1.total_exams from ws_course_mst " +
                                " left join(select course_code,COUNT(exam_code)total_exams from ws_exam_master" +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'" +
                                            " group by course_code" +
                                        " )exams1" +
                                " on ws_course_mst.course_code=exams1.course_code" +
                                " where ws_course_mst.semester_type='" + sem_code + "' and ws_course_mst.year_semester='" + year_code + "' and cancel_flag='N'" +
                            " )exams" +
                            " left join " +
                                " (SELECT course_code,COUNT(user_id)total_students" +
                                    " FROM ws_student_course_allocate_dtl" +
                                    " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag = 'N'" +
                                    " group by course_code" +
                                " )students" +
                            " on exams.course_code=students.course_code" +
                            " )res1 " +
                            " left join ws_grade_submit_detail on ws_grade_submit_detail.course_code = res1.course_code and ws_grade_submit_detail.semester_type='" + sem_code + "' and ws_grade_submit_detail.year_semester='" + year_code + "' " +
                            " where total_students > 0" +
                            " order by res1.course_code";
            }

            //SqlSelect = SqlSelect + " ORDER BY course_code";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];

            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public BLReturnObject ws_course_wise_exam_add(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_WS_GradingMaster server_course_master = (DSC_WS_GradingMaster)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_WS_GradingMaster objCourseMaster_upload = new DSC_WS_GradingMaster();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_master.ws_exam_master.Rows.Count; mprCnt++)
                {
                    objCourseMaster_upload.ws_exam_master.ImportRow(server_course_master.ws_exam_master.Rows[mprCnt]);
                    if (objCourseMaster_upload.ws_exam_master[mprCnt].doc_no == "")
                    {
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "WEM", UserID, HostName, ref DocNo, ref message))
                        {

                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        objCourseMaster_upload.ws_exam_master[mprCnt].doc_no = DocNo;
                    }
                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.ws_exam_master, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.ws_exam_master.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

