        public BLReturnObject ws_save_course_wise_avg_sd_range(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();

            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_WS_GradingMaster server_course_master = (DSC_WS_GradingMaster)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_WS_GradingMaster objCourseMaster_upload = new DSC_WS_GradingMaster();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_master.ws_course_wise_grade_range.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "GR", UserID, HostName, ref DocNo, ref message))
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objCourseMaster_upload.ws_course_wise_grade_range.ImportRow(server_course_master.ws_course_wise_grade_range.Rows[mprCnt]);
                    objCourseMaster_upload.ws_course_wise_grade_range[mprCnt].doc_no = DocNo;
                }

                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.ws_course_wise_grade_range, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.ws_course_wise_grade_range.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }

            return objBLReturnObject;
        }

