        public DataTable WS_Course_Wise_TA_Details(string sem_code, string year_code)
        {
            String SqlSelect = "";


            SqlSelect = @" Select t1.course_code,(select  STUFF((select distinct ', ' +  im.instructor_name from ws_course_proposal_TA wcw
                          inner join instructor_mst im on im.instructor_code = wcw.instructor_code
                          where wcw.semester_type='" + sem_code + @"' and wcw.year_semester='" + year_code + @"' and wcw.course_code=t1.course_code and wcw.cancel_flag='N'
                          FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,2,'')instructor_name )TA_instructor_name  from 
                          (
                          select distinct wcwt.course_code from ws_course_proposal_TA wcwt
                          inner join instructor_mst im on im.instructor_code = wcwt.instructor_code
                          where wcwt.cancel_flag='N' and wcwt.semester_type= '" + sem_code + @"' and wcwt.year_semester='" + year_code + @"') t1";

            return Get_data(SqlSelect);
        }

