        public Dictionary<string, string> ws_send_for_review_published_courses(string course_list, string semester_type, string year_semester, string user_id, string type)
        {
            String SqlSelect = "";
            int res = 0;
            Dictionary<string, string> dic_response = new Dictionary<string, string>();

            if (type == "Review")
            {
                //SqlSelect = " update ws_course_proposal set instructor_approved='N', dean_approved='N', is_publish='N', cancel_flag='N',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now + "' " +
                SqlSelect = " update ws_course_proposal set dean_approved='N', is_publish='N', cancel_flag='N',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now + "' " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and course_code in (" + course_list + ") ";

                SqlSelect += " delete from ws_course_mst " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and course_code in (select ws_course_code from ws_course_proposal where course_code in (" + course_list + ")) ";

                SqlSelect += " delete from ws_course_wise_instructor " +
                            " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                            " and course_code in (select ws_course_code from ws_course_proposal where course_code in (" + course_list + ")) ";

                SqlSelect += " delete from ws_course_wise_workplan " +
                            " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                            " and course_code in (select ws_course_code from ws_course_proposal where course_code in (" + course_list + ")) ";

                SqlSelect += " delete from ws_course_wise_TA " +
                            " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                            " and course_code in (select ws_course_code from ws_course_proposal where course_code in (" + course_list + ")) ";
            }
            else if (type == "Cancel")
            {
                SqlSelect = " update ws_course_proposal set is_cancel='Y', dean_approved='N', is_publish='N', cancel_flag='N', last_modified_by='" + user_id + "', last_modified_date='" + DateTime.Now + "', last_modified_host='" + HttpContext.Current.Request.UserHostName + "' " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and ws_course_code in (" + course_list + ") ";

                SqlSelect += " update ws_student_wise_course_dtl set cancel_flag='Y', is_cancel='Y',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now + "', last_modified_host='" + HttpContext.Current.Request.UserHostName + "' " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and (status='R' or status='A') and cancel_flag='N' " +
                        " and course_code in (" + course_list + ") ";

                SqlSelect += " delete from ws_course_mst " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and course_code in (select ws_course_code from ws_course_proposal where ws_course_code in (" + course_list + ")) ";

                SqlSelect += " delete from ws_course_wise_instructor " +
                            " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                            " and course_code in (select ws_course_code from ws_course_proposal where ws_course_code in (" + course_list + ")) ";

                SqlSelect += " delete from ws_course_wise_workplan " +
                            " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                            " and course_code in (select ws_course_code from ws_course_proposal where ws_course_code in (" + course_list + ")) ";

                SqlSelect += " delete from ws_course_wise_TA " +
                            " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                            " and course_code in (select ws_course_code from ws_course_proposal where course_code in (" + course_list + ")) ";
            }

            DBCommand.CommandText = SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();
                //DBCommand.Transaction = DBConnection.BeginTransaction();
                res = DBCommand.ExecuteNonQuery();
                //DBCommand.Transaction.Commit();
            }
            catch (Exception ex)
            {
                dic_response["status"] = "False";
                dic_response["message"] = ex.ToString();
            }

            DBConnection.Close();

            if (res > 0)
            {
                dic_response["status"] = "True";
                dic_response["message"] = "All Courses are Sent for Review Successfully";
            }
            else
            {
                dic_response["status"] = "False";
                dic_response["message"] = "There are some problems in sent for review , No Courses are Sent for Review";
            }

            return dic_response;
        }

