        public DataTable get_credit_detail_year_wise()
        {
            String SqlSelect = "";

            SqlSelect = @" select cdyw.*,dm.dept_name,pm.prog_name,plm.prog_level_desc
                            from credits_detail_year_wise as cdyw
                            left join department_mst as dm on dm.dept_code=cdyw.dept_code
                            left join programme_mst as pm on pm.prog_code=cdyw.prog_code
                            left join programme_level_mst as plm on plm.prog_level_code=cdyw.prog_level_code
                            where cdyw.cancel_flag='N' ";

            return Get_data(SqlSelect);
        }

        public DataTable get_credit_detail_year_wise_edit(string year_code, string prog_code, string dept_code, string prog_level_code)
        {
            String SqlSelect = "";

            SqlSelect = " select * from credits_detail_year_wise " +
                        " where cancel_flag='N' and year_code='" + year_code + "' and prog_code='" + prog_code + "' and dept_code='" + dept_code + "' ";

            if (prog_level_code != "")
            {
                SqlSelect += " and prog_level_code='" + prog_level_code + "' ";
            }

            return Get_data(SqlSelect);
        }

        public DataTable get_earned_credits_dtl(string user_id, string current_ws_sem, string current_ws_year)
        {
            String SqlSelect = "";

            int pass_marks = 50;

            string enroll_year = HttpContext.Current.Session["year_code"].ToString();
            enroll_year = enroll_year.Substring(1);

            if (2017 < Convert.ToInt32(enroll_year))
            {
                pass_marks = 55;
            }

            string ws_cur_sem = "";

            if (current_ws_sem == "M")
            {
                ws_cur_sem = "W";
            }
            else
            {
                ws_cur_sem = "S";
            }

            SqlSelect = "DECLARE @user_id varchar(20);SET @user_id='" + user_id + "';";
            SqlSelect += "DECLARE @cur_sem varchar(20);SET @cur_sem='" + current_ws_sem + "';";
            SqlSelect += "DECLARE @year_sem varchar(20);SET @year_sem='" + current_ws_year + "';";
            SqlSelect += "DECLARE @ws_cur_sem varchar(20);SET @ws_cur_sem='" + ws_cur_sem + "';";
            SqlSelect += "DECLARE @pass_marks int;SET @pass_marks=" + pass_marks + ";";

            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            //// Without Alloted Credits
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            //SqlSelect += @" with res as (select *
            //	                from(select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
