            //		                ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
            //		                from student_exam_marks_dtl as sm
            //		                inner join student_course_allocate_dtl as sca
            //		                on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
            //			                and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
            //		                inner join course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
            //			                and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
            //                        inner join grade_submit_detail as gsd on gsd.course_code=sm.course_code and gsd.cancel_flag='N'
            //                            and gsd.semester_type=sm.semester_type and gsd.year_semester=sm.year_semester and gsd.ugpgoffice_approved='Y'
            //		                where sm.cancel_flag='N' and sm.student_code=@user_id
            //	                )res1
            //                where Total>=50)
            //
            //                select um.user_id,um.year_code,um.prog_code,crd_dtl.total_credits,crd_dtl.mandatory_credits,crd_dtl.elective_credits,crd_dtl.sws_credits,
            //                (ISNULL(res2.earned_credits,0)+ISNULL(res5.earned_sws_credits,0))earned_credits,res3.earned_mandatory_credits,
            //                res4.earned_elective_credits,res5.earned_sws_credits
            //                from user_mst as um
            //                left join credits_detail_year_wise as crd_dtl on crd_dtl.year_code=um.year_code and crd_dtl.prog_code=um.prog_code
            //                            and crd_dtl.dept_code=um.dept_code and ISNULL(crd_dtl.prog_level_code,'')=ISNULL(um.prog_level_code,'')
            //                left join (
            //	                select @user_id as user_id,SUM(CAST(course_credits as int))earned_credits from res
            //                )res2 on res2.user_id=um.user_id
            //                left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_mandatory_credits from res 
            //	                where res.course_type='M'
            //                )res3 on res3.user_id=um.user_id
            //                left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_elective_credits from res 
            //	                where res.course_type='E'
            //                )res4 on res4.user_id=um.user_id
            //                left join (
            //	                select res1.user_id,SUM(CAST(res1.course_credits as int))earned_sws_credits from(
            //		                select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
            //			                +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
            //		                ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
            //		                from ws_student_exam_marks_dtl as sm
            //		                inner join ws_student_course_allocate_dtl as sca
            //		                on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
            //			                and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
            //		                inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
            //			                and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
            //		                where sm.cancel_flag='N' and sm.student_code=@user_id
            //	                )res1
            //	                where Total>=50
            //	                group by res1.user_id
            //                )res5 on res5.user_id=um.user_id
            //                where um.user_id=@user_id and um.cancel_flag='N' ";

            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

            SqlSelect += @" with res as (select *
	                        from(select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                        +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                        ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
		                        from student_course_allocate_dtl as sca
		                        inner join course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
				                        and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
		                        left join student_exam_marks_dtl as sm
			                        on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sm.cancel_flag='N' 
				                        and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                        left join grade_submit_detail as gsd on gsd.course_code=sca.course_code and gsd.cancel_flag='N'
				                        and gsd.semester_type=sca.semester_type and gsd.year_semester=sca.year_semester and gsd.ugpgoffice_approved='Y'
		                        where sca.cancel_flag='N' and sca.user_id=@user_id and sca.course_code not in ('CFP001','CFP002','CFP003','CFP004','CFP005','CFP006','CFP007','CFP008','CFP009','CFP010')
                                      and (sca.semester_type != @cur_sem or sca.year_semester != @year_sem)
	                        )res1
                        )

                        select um.user_id,um.year_code,um.prog_code,crd_dtl.total_credits,crd_dtl.mandatory_credits,crd_dtl.elective_credits,crd_dtl.sws_credits,
                        (ISNULL(res21.alloted_credits,0)+ISNULL(res51.alloted_sws_credits,0))alloted_credits,ISNULL(res31.alloted_mandatory_credits,0)alloted_mandatory_credits,
                        ISNULL(res41.alloted_elective_credits,0)alloted_elective_credits,ISNULL(res51.alloted_sws_credits,0)alloted_sws_credits,
                        (ISNULL(res2.earned_credits,0)+ISNULL(res5.earned_sws_credits,0))earned_credits,ISNULL(res3.earned_mandatory_credits,0)earned_mandatory_credits,
                        ISNULL(res4.earned_elective_credits,0)earned_elective_credits,ISNULL(res5.earned_sws_credits,0)earned_sws_credits
                        from user_mst as um
                        left join credits_detail_year_wise as crd_dtl on crd_dtl.year_code=um.year_code and crd_dtl.prog_code=um.prog_code
			                        and crd_dtl.dept_code=um.dept_code and ISNULL(crd_dtl.prog_level_code,'')=ISNULL(um.prog_level_code,'')
			
                        left join (
	                        select @user_id as user_id,SUM(CAST(course_credits as int))alloted_credits from res
                        )res21 on res21.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))alloted_mandatory_credits from res 
	                        where res.course_type='M'
                        )res31 on res31.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))alloted_elective_credits from res 
	                        where res.course_type='E'
                        )res41 on res41.user_id=um.user_id
                        left join (select sca.user_id,SUM(CAST(cm.course_credits as int))alloted_sws_credits
	                        from ws_student_course_allocate_dtl as sca
	                        inner join ws_course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
			                        and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
	                        where sca.cancel_flag='N' and sca.user_id=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
	                        group by sca.user_id
                        )res51 on res51.user_id=um.user_id

                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_credits from res
	                        where Total>=@pass_marks
                        )res2 on res2.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_mandatory_credits from res 
	                        where res.course_type='M' and Total>=@pass_marks
                        )res3 on res3.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_elective_credits from res 
	                        where res.course_type='E' and Total>=@pass_marks
                        )res4 on res4.user_id=um.user_id
                        left join (
	                        select res1.user_id,SUM(CAST(res1.course_credits as int))earned_sws_credits from(
		                        select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                        +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                        ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
		                        from ws_student_exam_marks_dtl as sm
		                        inner join ws_student_course_allocate_dtl as sca
		                        on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
			                        and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                        inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
			                        and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
		                        where sm.cancel_flag='N' and sm.student_code=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
	                        )res1
	                        where Total>=@pass_marks
	                        group by res1.user_id
                        )res5 on res5.user_id=um.user_id
                        where um.user_id=@user_id and um.cancel_flag='N' ";

            return Get_data(SqlSelect);
        }


        public DataTable get_earned_credits_dtl_new(string user_id, string current_ws_sem, string current_ws_year)
        {
            String SqlSelect = "";

            int pass_marks = 50;

            string enroll_year = HttpContext.Current.Session["year_code"].ToString();
            enroll_year = enroll_year.Substring(1);

            if (2017 < Convert.ToInt32(enroll_year))
            {
                pass_marks = 55;
            }

            string ws_cur_sem = "";

            if (current_ws_sem == "M")
            {
                ws_cur_sem = "W";
            }
            else
            {
                ws_cur_sem = "S";
            }

            SqlSelect = "DECLARE @user_id varchar(20);SET @user_id='" + user_id + "';";
            SqlSelect += "DECLARE @cur_sem varchar(20);SET @cur_sem='" + current_ws_sem + "';";
            SqlSelect += "DECLARE @year_sem varchar(20);SET @year_sem='" + current_ws_year + "';";
            SqlSelect += "DECLARE @ws_cur_sem varchar(20);SET @ws_cur_sem='" + ws_cur_sem + "';";
            SqlSelect += "DECLARE @pass_marks int;SET @pass_marks=" + pass_marks + ";";

            SqlSelect += @" with res as (select *
	                        from(select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                        +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                        ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
		                        from student_course_allocate_dtl as sca
		                        inner join course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
				                        and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
		                        left join student_exam_marks_dtl as sm
			                        on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sm.cancel_flag='N' 
				                        and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                        left join grade_submit_detail as gsd on gsd.course_code=sca.course_code and gsd.cancel_flag='N'
				                        and gsd.semester_type=sca.semester_type and gsd.year_semester=sca.year_semester and gsd.ugpgoffice_approved='Y'
		                        where sca.cancel_flag='N' and sca.user_id=@user_id 
                                  and sca.course_code not in ('CFP001','CFP002','CFP003','CFP004','CFP005','CFP006','CFP007','CFP008','CFP009','CFP010')
                                      and (sca.semester_type != @cur_sem or sca.year_semester != @year_sem)
	                        )res1
                        )

                        select um.user_id,um.year_code,um.prog_code,crd_dtl.total_credits,crd_dtl.mandatory_credits,crd_dtl.elective_credits,crd_dtl.sws_credits,
                        (ISNULL(res21.alloted_credits,0))alloted_credits,ISNULL(res31.alloted_mandatory_credits,0)alloted_mandatory_credits,
                        ISNULL(res41.alloted_elective_credits,0)alloted_elective_credits,ISNULL(res51.alloted_sws_credits,0)alloted_sws_credits,
                        (ISNULL(res2.earned_credits,0))earned_credits,ISNULL(res3.earned_mandatory_credits,0)earned_mandatory_credits,
                        ISNULL(res4.earned_elective_credits,0)earned_elective_credits,ISNULL(res5.earned_sws_credits,0)earned_sws_credits,
                        ISNULL(res81.sws_alloted_elective_credits,0) sws_alloted_elective_credits,ISNULL(res91.sws_alloted_mandatory_credits,0) sws_alloted_mandatory_credits,
                        ISNULL(res99.sws_earned_mandatory_credits,0) sws_earned_mandatory_credits,ISNULL(res199.sws_earned_elactive_credits,0) sws_earned_elactive_credits
                        from user_mst as um
                        left join credits_detail_year_wise as crd_dtl on crd_dtl.year_code=um.year_code and crd_dtl.prog_code=um.prog_code
			                        and crd_dtl.dept_code=um.dept_code and ISNULL(crd_dtl.prog_level_code,'')=ISNULL(um.prog_level_code,'')
			
                        left join (
	                        select @user_id as user_id,SUM(CAST(course_credits as int))alloted_credits from res
                        )res21 on res21.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))alloted_mandatory_credits from res 
	                        where res.course_type='M'
                        )res31 on res31.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))alloted_elective_credits from res 
	                        where res.course_type='E'
                        )res41 on res41.user_id=um.user_id
                        left join (select sca.user_id,SUM(CAST(cm.course_credits as int))alloted_sws_credits
	                        from ws_student_course_allocate_dtl as sca
	                        inner join ws_course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
			                        and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
	                        where sca.cancel_flag='N' and sca.user_id=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
	                        group by sca.user_id
                        )res51 on res51.user_id=um.user_id


                        left join (select sca.user_id,SUM(CAST(cm.course_credits as int))sws_alloted_mandatory_credits
                            from ws_student_course_allocate_dtl as sca
                            inner join ws_course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
                                    and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
                            where sca.cancel_flag='N' and sca.user_id=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
                        	and sca.course_type='M'
                            group by sca.user_id
                        )res91 on res91.user_id=um.user_id
                        
                        left join (select sca.user_id,SUM(CAST(cm.course_credits as int))sws_alloted_elective_credits
                            from ws_student_course_allocate_dtl as sca
                            inner join ws_course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
                                    and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
                            where sca.cancel_flag='N' and sca.user_id=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
                        	and sca.course_type='E'
                            group by sca.user_id
                        )res81 on res81.user_id=um.user_id



                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_credits from res
	                        where Total>=@pass_marks
                        )res2 on res2.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_mandatory_credits from res 
	                        where res.course_type='M' and Total>=@pass_marks
                        )res3 on res3.user_id=um.user_id
                        left join (select @user_id as user_id,SUM(CAST(course_credits as int))earned_elective_credits from res 
	                        where res.course_type='E' and Total>=@pass_marks
                        )res4 on res4.user_id=um.user_id
                        left join (
	                        select res1.user_id,SUM(CAST(res1.course_credits as int))earned_sws_credits from(
		                        select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                        +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                        ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
		                        from ws_student_exam_marks_dtl as sm
		                        inner join ws_student_course_allocate_dtl as sca
		                        on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
			                        and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                        inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
			                        and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
		                        where sm.cancel_flag='N' and sm.student_code=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
	                        )res1
	                        where Total>=@pass_marks
	                        group by res1.user_id
                        )res5 on res5.user_id=um.user_id

                        left join (
                            select res1.user_id,SUM(CAST(res1.course_credits as int))sws_earned_mandatory_credits 
                        	from(
                                select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
                                    +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                                ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
                                from ws_student_exam_marks_dtl as sm
                                inner join ws_student_course_allocate_dtl as sca
                                on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
                                    and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
                                inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
                                    and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
                                where sm.cancel_flag='N' and sca.course_type='M' and sm.student_code=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
                            )res1
                            where Total>=@pass_marks
                            group by res1.user_id
                        )res99 on res99.user_id=um.user_id
                        
                        
                        left join (
                            select res1.user_id,SUM(CAST(res1.course_credits as int))sws_earned_elactive_credits 
                        	from(
                                select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
                                    +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
                                ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
                                from ws_student_exam_marks_dtl as sm
                                inner join ws_student_course_allocate_dtl as sca
                                on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
                                    and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
                                inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
                                    and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
                                where sm.cancel_flag='N' and sca.course_type='E' and sm.student_code=@user_id and (sca.semester_type != @ws_cur_sem or sca.year_semester != @year_sem)
                            )res1
                            where Total>=@pass_marks
                            group by res1.user_id
                        )res199 on res199.user_id=um.user_id


                        where um.user_id=@user_id and um.cancel_flag='N' ";

            return Get_data(SqlSelect);
        }


