        public DataTable dt_earned_credits_dtl_foundation_fail_student(string user_id)
        {
            int per_value = 50;
            int per_value2 = 60;

            string year_code = HttpContext.Current.Session["year_code"].ToString();
            year_code = year_code.Substring(1);

            int one_year_incress = Convert.ToInt32(year_code) + 1;


            int year_code_incres = Convert.ToInt32(one_year_incress) + 1;

            int pass_marks = 60;
            int pass_marks2 = 60;

            //if (Convert.ToInt32(year_code) < Convert.ToInt32("2020"))
            //{
            //    per_value = 50;
            //}
            //else
            //{
            //    per_value = 60;
            //}

            //if (Convert.ToInt32(year_code) == 2019)
            //{
            //    per_value2 = 65;
            //}

            if (Convert.ToInt32(year_code) == 2019)
            {
                pass_marks = 50;
            }

            String SqlSelect = "";

            if (Convert.ToInt32(year_code) >= 2019)
            {
                SqlSelect = "DECLARE @user_id varchar(20);SET @user_id='" + user_id + "';" +
                    "DECLARE @year_code varchar(20);SET @year_code='" + one_year_incress + "';" +
                    "DECLARE @year_code_sem varchar(20);SET @year_code_sem='" + year_code_incres + "';" +
                    "DECLARE @per_value int;SET @per_value=" + per_value + ";" +
                    "DECLARE @per_value2 int;SET @per_value2=" + per_value2 + ";" +
                    "DECLARE @pass_marks int;SET @pass_marks=" + pass_marks + ";" +
                    "DECLARE @pass_marks2 int;SET @pass_marks2=" + pass_marks2 + ";";

                SqlSelect += @"select --sum(bc),
	                            case when sum(bc)=3 then sum(cast(b as float)) else 0 end total_earned_foundation
                            from (
                            select 
                            case when exam_1 >= @pass_marks  then 1 else 0 end  bc,
                            case when exam_1 >= @pass_marks  then exam_1 * (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='M' and a.year_semester = @year_code) else 0 end  a,
                            (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='M' and a.year_semester = @year_code)b from student_exam_marks_dtl 
                            where student_code = @user_id and course_code in ('CFP001','CFP002','CFP003','CFP007') and student_exam_marks_dtl.cancel_flag='N' and student_exam_marks_dtl.semester_type = 'M' and student_exam_marks_dtl.year_semester = @year_code
                            )a

                            union all

                            select --sum(bc),
	                            case when sum(bc)=3 then sum(cast(b as float)) else 0 end total_earned_foundation
                            from (
                            select 
                            case when exam_1 >= @pass_marks2  then 1 else 0 end  bc,
                            case when exam_1 >= @pass_marks2  then exam_1 * (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='S' and a.year_semester = @year_code_sem) else 0 end  a,
                            (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='S' and a.year_semester = @year_code_sem)b from student_exam_marks_dtl 
                            where student_code = @user_id and course_code in ('CFP004','CFP005','CFP006','CFP008','CFP009','CFP010') and student_exam_marks_dtl.cancel_flag='N' and student_exam_marks_dtl.semester_type = 'S' and student_exam_marks_dtl.year_semester = @year_code_sem
                            )a";
            }
            else
            {
                SqlSelect = "DECLARE @user_id varchar(20);SET @user_id='" + user_id + "';" +
                        "DECLARE @year_code varchar(20);SET @year_code='" + one_year_incress + "';" +
                        "DECLARE @year_code_sem varchar(20);SET @year_code_sem='" + year_code_incres + "';" +
                        "DECLARE @per_value int;SET @per_value=" + per_value + ";" +
                        "DECLARE @per_value2 int;SET @per_value2=" + per_value2 + ";";

                SqlSelect += @"select --sum(bc),
	                            case when ((sum(cast(a as float))/sum(cast(b as float))) >= @per_value) and sum(bc)=3 then sum(cast(b as float)) else 0 end total_earned_foundation
                            from (
                            select 
                            case when exam_1 >= 45  then 1 else 0 end  bc,
                            case when exam_1 >= 45  then exam_1 * (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='M' and a.year_semester = @year_code) else 0 end  a,
                            (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='M' and a.year_semester = @year_code)b from student_exam_marks_dtl 
                            where student_code = @user_id and course_code in ('CFP001','CFP002','CFP003','CFP007') and student_exam_marks_dtl.cancel_flag='N' and student_exam_marks_dtl.semester_type = 'M' and student_exam_marks_dtl.year_semester = @year_code
                            )a

                            union all

                            select --sum(bc),
	                            case when ((sum(cast(a as float))/sum(cast(b as float))) >= @per_value2) and sum(bc)=3 then sum(cast(b as float)) else 0 end total_earned_foundation
                            from (
                            select 
                            case when exam_1 >= 45  then 1 else 0 end  bc,
                            case when exam_1 >= 45  then exam_1 * (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='S' and a.year_semester = @year_code_sem) else 0 end  a,
                            (select course_credits from course_mst a where a.course_code = student_exam_marks_dtl.course_code and a.semester_type ='S' and a.year_semester = @year_code_sem)b from student_exam_marks_dtl 
                            where student_code = @user_id and course_code in ('CFP004','CFP005','CFP006','CFP008','CFP009','CFP010') and student_exam_marks_dtl.cancel_flag='N' and student_exam_marks_dtl.semester_type = 'S' and student_exam_marks_dtl.year_semester = @year_code_sem
                            )a";
            }

            return Get_data(SqlSelect);
        }

