        public DataSet get_feedback_logic(string user_id, string current_ws_sem, string current_ws_year, string course_code)
        {
            String SqlSelect = "";

            SqlSelect = "IF EXISTS(select * from student_feedback_dtl where user_id='" + user_id + "' and semester_type='" + current_ws_sem + "' and year_semester='" + current_ws_year + "' and cancel_flag='N' and submit_status='Y' and instructor_code='' and course_code='" + course_code + "')";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Feedback_Avaiable END ELSE BEGIN select 'N' as Feedback_Avaiable END ";

            SqlSelect = SqlSelect + "IF EXISTS(select * from grade_submit_detail where course_code='" + course_code + "' and semester_type='" + current_ws_sem + "' and year_semester='" + current_ws_year + "' and ugpgoffice_approved='Y')";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Result_Published END ELSE BEGIN select 'N' as Result_Published END ";

            SqlSelect = SqlSelect + "IF EXISTS(select * from feedback_disable_course where cancel_flag ='N' and semester_type = '" + current_ws_sem + "' and year_semester = '" + current_ws_year + "' and course_code='" + course_code + "')";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Course_Disabled END ELSE BEGIN select 'N' as Course_Disabled END ";

            DBDataAdpterObject.SelectCommand.CommandType = CommandType.Text;
            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);

                return ds;
            }
            catch (Exception ex)
            {
                ServerLog.ExceptionLog("2. Get_data : " + ex.ToString());
                return null;
            }
        }

