        public DataTable get_credit_bifurcation_old(string user_id)
        {
            String SqlSelect = "";
            int pass_marks = 50;

            string enroll_year = HttpContext.Current.Session["year_code"].ToString();
            enroll_year = enroll_year.Substring(1);

            if (2017 < Convert.ToInt32(enroll_year))
            {
                pass_marks = 55;
            }

            SqlSelect = "DECLARE @user_id varchar(20);SET @user_id='" + user_id + "';";
            SqlSelect += "DECLARE @pass_marks int;SET @pass_marks=" + pass_marks + ";";

            SqlSelect += @" with res as (select *
	                            from(select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                            +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                            ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
		                            from student_course_allocate_dtl as sca
		                            inner join course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
				                            and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
		                            left join student_exam_marks_dtl as sm
			                            on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sm.cancel_flag='N' 
				                            and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                            left join grade_submit_detail as gsd on gsd.course_code=sca.course_code and gsd.cancel_flag='N'
				                            and gsd.semester_type=sca.semester_type and gsd.year_semester=sca.year_semester and gsd.ugpgoffice_approved='Y'
		                            where sca.cancel_flag='N' and sca.user_id=@user_id
	                            )res1
                            )

                            select um.user_id,um.year_code,um.prog_code,res21.semester_type,res21.year_semester,
                            (ISNULL(res21.alloted_credits,0)+ISNULL(res51.alloted_sws_credits,0))alloted_credits,res31.alloted_mandatory_credits,
                            res41.alloted_elective_credits,res51.alloted_sws_credits,
                            (ISNULL(res2.earned_credits,0)+ISNULL(res5.earned_sws_credits,0))earned_credits,res3.earned_mandatory_credits,
                            res4.earned_elective_credits,res5.earned_sws_credits
                            from user_mst as um

                            left join (
	                            select @user_id as user_id,semester_type,year_semester,SUM(CAST(course_credits as int))alloted_credits 
	                            from res group by user_id,semester_type,year_semester
                            )res21 on res21.user_id=um.user_id
                            left join (select @user_id as user_id,semester_type,year_semester,SUM(CAST(course_credits as int))alloted_mandatory_credits from res 
	                            where res.course_type='M' group by user_id,semester_type,year_semester
                            )res31 on res31.user_id=um.user_id and res31.semester_type=res21.semester_type and res31.year_semester=res21.year_semester
                            left join (select @user_id as user_id,semester_type,year_semester,SUM(CAST(course_credits as int))alloted_elective_credits from res 
	                            where res.course_type='E' group by user_id,semester_type,year_semester
                            )res41 on res41.user_id=um.user_id and res41.semester_type=res21.semester_type and res41.year_semester=res21.year_semester
                            left join (select sca.user_id,sca.semester_type,sca.year_semester,SUM(CAST(cm.course_credits as int))alloted_sws_credits
	                            from ws_student_course_allocate_dtl as sca
	                            inner join ws_course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
			                            and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
	                            where sca.cancel_flag='N' and sca.user_id=@user_id
	                            group by sca.user_id,sca.semester_type,sca.year_semester
                            )res51 on res51.user_id=um.user_id and (case res51.semester_type when 'W' then 'M' else res51.semester_type end)=res21.semester_type and res51.year_semester=res21.year_semester

                            left join (select @user_id as user_id,semester_type,year_semester,SUM(CAST(course_credits as int))earned_credits from res
	                            where Total>=@pass_marks group by user_id,semester_type,year_semester
                            )res2 on res2.user_id=um.user_id and res2.semester_type=res21.semester_type and res2.year_semester=res21.year_semester
                            left join (select @user_id as user_id,semester_type,year_semester,SUM(CAST(course_credits as int))earned_mandatory_credits from res 
	                            where res.course_type='M' and Total>=@pass_marks group by user_id,semester_type,year_semester
                            )res3 on res3.user_id=um.user_id and res3.semester_type=res21.semester_type and res3.year_semester=res21.year_semester
                            left join (select @user_id as user_id,semester_type,year_semester,SUM(CAST(course_credits as int))earned_elective_credits from res 
	                            where res.course_type='E' and Total>=@pass_marks group by user_id,semester_type,year_semester
                            )res4 on res4.user_id=um.user_id and res4.semester_type=res21.semester_type and res4.year_semester=res21.year_semester
                            left join (
	                            select res1.user_id,res1.semester_type,res1.year_semester,SUM(CAST(res1.course_credits as int))earned_sws_credits from(
		                            select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                            +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                            ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.semester_type,sca.year_semester 
		                            from ws_student_exam_marks_dtl as sm
		                            inner join ws_student_course_allocate_dtl as sca
		                            on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
			                            and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                            inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
			                            and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
		                            where sm.cancel_flag='N' and sm.student_code=@user_id
	                            )res1
	                            where Total>=@pass_marks
	                            group by res1.user_id,res1.semester_type,res1.year_semester
                            )res5 on res5.user_id=um.user_id and (case res5.semester_type when 'W' then 'M' else res5.semester_type end)=res21.semester_type and res5.year_semester=res21.year_semester

                            where um.user_id=@user_id and um.cancel_flag='N'
                            order by year_semester,semester_type desc ";

            return Get_data(SqlSelect);
        }

        public DataTable get_credit_bifurcation(string user_id)
        {
            String SqlSelect = "";
            int pass_marks = 50;

            string enroll_year = HttpContext.Current.Session["year_code"].ToString();
            enroll_year = enroll_year.Substring(1);

            if (2017 < Convert.ToInt32(enroll_year))
            {
                pass_marks = 55;
            }

            SqlSelect = "DECLARE @user_id varchar(20);SET @user_id='" + user_id + "';";
            SqlSelect += "DECLARE @pass_marks int;SET @pass_marks=" + pass_marks + ";";

            SqlSelect += @" with res as (select *
	                            from(select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                            +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                            ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.course_type,sca.gpa_nongpa,sca.semester_type,sca.year_semester 
		                            from student_course_allocate_dtl as sca
		                            inner join course_mst as cm on cm.course_code=sca.course_code and cm.cancel_flag='N'
				                            and cm.semester_type=sca.semester_type and cm.year_semester=sca.year_semester
		                            left join student_exam_marks_dtl as sm
			                            on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sm.cancel_flag='N' 
				                            and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                            left join grade_submit_detail as gsd on gsd.course_code=sca.course_code and gsd.cancel_flag='N'
				                            and gsd.semester_type=sca.semester_type and gsd.year_semester=sca.year_semester and gsd.ugpgoffice_approved='Y'
		                            where sca.cancel_flag='N' and sca.user_id=@user_id
	                            )res1
                            )

                            select um.user_id,um.year_code,um.prog_code,res21.semester_type,res21.year_semester,
                            (ISNULL(res21.alloted_credits,0)+ISNULL(res51.alloted_sws_credits,0))alloted_credits,res31.alloted_mandatory_credits,
