	                            where Total>=@pass_marks
	                            group by res1.user_id,res1.semester_type,res1.year_semester
                            )res57 on res57.user_id=um.user_id and (case res57.semester_type when 'W' then 'M' else res57.semester_type end)=res21.semester_type and res57.year_semester=res21.year_semester
                            ------------------
                            left join (
	                            select res1.user_id,res1.semester_type,res1.year_semester,SUM(CAST(res1.course_credits as int))earned_gpa_elective_sws_credits from(
		                            select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                            +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                            ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.gpa_nongpa,sca.course_type,sca.semester_type,sca.year_semester 
		                            from ws_student_exam_marks_dtl as sm
		                            inner join ws_student_course_allocate_dtl as sca
		                            on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
			                            and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                            inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
			                            and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
		                            where sm.cancel_flag='N' and sm.student_code=@user_id and sca.course_type='E' and sca.gpa_nongpa='G'
	                            )res1
	                            where Total>=@pass_marks
	                            group by res1.user_id,res1.semester_type,res1.year_semester
                            )res58 on res58.user_id=um.user_id and (case res58.semester_type when 'W' then 'M' else res58.semester_type end)=res21.semester_type and res58.year_semester=res21.year_semester
                            left join (
	                            select res1.user_id,res1.semester_type,res1.year_semester,SUM(CAST(res1.course_credits as int))earned_nongpa_elective_sws_credits from(
		                            select ROUND((ISNULL(exam_1_w,0)+ISNULL(exam_2_w,0)+ISNULL(exam_3_w,0)+ISNULL(exam_4_w,0)+ISNULL(exam_5_w,0)
			                            +ISNULL(exam_6_w,0)+ISNULL(exam_7_w,0)+ISNULL(exam_8_w,0)+ISNULL(exam_9_w,0)+ISNULL(exam_10_w,0)
		                            ),0) as Total,cm.course_credits,sca.user_id,sca.course_code,sca.gpa_nongpa,sca.course_type,sca.semester_type,sca.year_semester 
		                            from ws_student_exam_marks_dtl as sm
		                            inner join ws_student_course_allocate_dtl as sca
		                            on sca.user_id=sm.student_code and sca.course_code=sm.course_code and sca.cancel_flag='N' 
			                            and sca.semester_type=sm.semester_type and sca.year_semester=sm.year_semester
		                            inner join ws_course_mst as cm on cm.course_code=sm.course_code and cm.cancel_flag='N'
			                            and cm.semester_type=sm.semester_type and cm.year_semester=sm.year_semester
		                            where sm.cancel_flag='N' and sm.student_code=@user_id and sca.course_type='E' and sca.gpa_nongpa='N'
	                            )res1
	                            where Total>=@pass_marks
	                            group by res1.user_id,res1.semester_type,res1.year_semester
                            )res59 on res59.user_id=um.user_id and (case res59.semester_type when 'W' then 'M' else res59.semester_type end)=res21.semester_type and res59.year_semester=res21.year_semester
                            ------------------
                            where um.user_id=@user_id and um.cancel_flag='N'
                            order by year_semester,semester_type desc  ";

            return Get_data(SqlSelect);
        }

        public BLReturnObject save_credit_detail_year_wise(DataSet ds_UploadData, string compnyid, String UserID, String HostName, Dictionary<string, object> dict_credit_data)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();

            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_CreditsDetail objCourseMaster_upload = (DSC_CreditsDetail)ds_UploadData;

                objCourseMaster_upload.EnforceConstraints = false;

                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                // Delete Credits Detail Year Wise
                bool delete_flag = false;
                String SqlSelect = "delete from credits_detail_year_wise where year_code='" + dict_credit_data["old_year_code"].ToString() + "' and prog_code='" + dict_credit_data["old_prog_code"].ToString() + "' and dept_code='" + dict_credit_data["old_dept_code"].ToString() + "' and prog_level_code='" + dict_credit_data["old_prog_level_code"].ToString() + "'";
                DBCommand.CommandText = SqlSelect;
                DBCommand.CommandType = CommandType.Text;
                try { DBCommand.ExecuteNonQuery(); }
                catch (Exception e) { delete_flag = true; }

                if (delete_flag)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Data.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.credits_detail_year_wise, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.credits_detail_year_wise.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";

                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }

            return objBLReturnObject;
        }

