        public DataSet get_course_reg_dtl(string user_id, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "select um.mail,um.dept_code,um.user_name,ufcf.user_id,ufcf.mandatory_credits,ufcf.elective_credits,ufcf.sws_credits,ufcf.semester_type," +
                         " ufcf.year_semester, std.dissertation_supervisor,plm.prog_level_name,uf.fees_type,uf.installment_status,uf.no_of_installment,uf.fees_amount,uf.installment1,uf.installment2,uf.installment3, " +
                         " uf.installment1_fine,uf.installment2_fine,uf.installment3_fine,uf.is_installment1_paid,uf.is_installment2_paid,uf.is_installment3_paid " +
                         " from user_fees_choice_bifurcation ufcf inner join user_mst um on um.user_id = ufcf.user_id " +
                         " inner join programme_level_mst plm on plm.prog_level_code = um.prog_level_code " +
                         " left join user_fees_installment_dtl uf on uf.user_id = ufcf.user_id and uf.semester_type = ufcf.semester_type and uf.year_semester = ufcf.year_semester " +
                         " left join student_transcript_dtl std on std.user_id = ufcf.user_id ";

            SqlSelect = SqlSelect + " where ufcf.semester_type = '" + sem_code + "' and ufcf.year_semester = '" + year_code + "' and ufcf.user_id = '" + user_id + "'";

            SqlSelect = SqlSelect + " select swcd.semester_code, swcd.course_code, cm.course_name, cm.course_credits, cm.course_type, cm.gpa_ngpa, swcd.priority, dm.dept_name " +
                           " from student_wise_course_dtl swcd " +
                           " inner join course_mst cm on cm.course_code = swcd.course_code and cm.semester_type = swcd.semester_type and cm.year_semester = swcd.year_semester " +
                           " inner join department_wise_course_dtl dwcd on cm.course_code = dwcd.course_code and cm.semester_type = dwcd.semester_type and cm.year_semester = dwcd.year_semester " +
                           " inner join department_mst dm on dm.dept_code = dwcd.dept_code " +
                           " where swcd.user_id = '" + user_id + "' and swcd.semester_type = '" + sem_code + "' and swcd.year_semester = '" + year_code + "' and swcd.cancel_flag = 'N' and swcd.status = 'S' order by swcd.priority asc ";//swcd.status = 'R'

            DBDataAdpterObject.SelectCommand.CommandType = CommandType.Text;
            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);

                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds;
            }
            catch (Exception ex)
            {
                ServerLog.ExceptionLog("2. Get_data : " + ex.ToString());
                return null;
            }
        }

