                                    and instructor_mst.cancel_flag='N' and instructor_mst.designation IN ('VF','TA','AA') ";

                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code='" + prog_level_code + "' ";
                }

                if (Convert.ToInt32(year_code) >= 2023)
                {
                    SqlSelect = SqlSelect + " and instructor_workload_detail.uso_hr_approved ='Y' ";
                }
                string temp_str = SqlSelect;

                SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(4);set @sem='" + sem_code + "';set @year='" + year_code + "'";

                if (instructor_type != "-") SqlSelect = SqlSelect + "select * from ( ";

                SqlSelect = SqlSelect + temp_str;

                SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_AA");

                SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_TA");

                if (instructor_type == "TEA")
                    SqlSelect = SqlSelect + " ) as res where res.designation_letter = '" + instructor_type + "'";
                else if (instructor_type != "-")
                    SqlSelect = SqlSelect + " ) as res where res.designation = '" + instructor_type + "'";
                if (instructor_type == "TA")
                    SqlSelect = SqlSelect + " and res.designation_letter is null ";
            }

            return Get_data(SqlSelect);
        }


