        //Publish Letter
        public DataTable get_vf_rate_band_detail(string sem_code, string year_code, string user_id, string prog_code, string prog_level_code, string dept_code)
        {
            String SqlSelect = "";

            SqlSelect = " select distinct instructor_mst.instructor_code,instructor_mst.VF_code,instructor_mst.instructor_name,instructor_mst.designation as des_type,instructor_mst.rate_wise_designation," + //course_wise_instructor.course_code,
                        " department_wise_course_dtl.dept_code,department_mst.dept_name," +
                        " department_wise_course_dtl.prog_code,department_wise_course_dtl.course_code, " + //programme_mst.prog_name," 
                        " instructor_mst.mail,instructor_mst.total_experiance,instructor_mst.highest_qualification," +
                        " instructor_mst.rate_band,instructor_mst.alternate_band,instructor_mst.justification,instructor_mst.designation_letter," +
                        " (case instructor_mst.admin_approved when 'Y' then 'Approved' else '' end)admin_approved, " +
                        " (case rateband_approved when 'Y' then 'Approved' else '' end)rateband_approved, " +
                        " (case instructor_workload_detail.admin_approved when 'Y' then 'Approved' else '' end)workload_approved, " +
                        " (case instructor_workload_detail.hr_approved when 'Y' then 'Approved' else '' end)hr_approved, " +
                        " (case instructor_workload_detail.uso_hr_approved when 'Y' then 'Approved' else '' end)uso_hr_approved " +
                        //" ,instructor_workload_detail.is_tutorial " +
                        " from course_wise_instructor " +
                        " left join instructor_mst on instructor_mst.instructor_code = course_wise_instructor.instructor_code" +
                        " left join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_instructor.course_code" +
                        " left join department_mst on department_mst.dept_code = department_wise_course_dtl.dept_code" +
                        " left join programme_mst on programme_mst.prog_code = department_wise_course_dtl.prog_code" +
                        " left join instructor_workload_detail on instructor_workload_detail.instructor_code = course_wise_instructor.instructor_code" +
                        " and instructor_workload_detail.course_code = course_wise_instructor.course_code and instructor_workload_detail.cancel_flag = 'N'" +
                        " and instructor_workload_detail.semester_type = course_wise_instructor.semester_type" +
                        " and instructor_workload_detail.year_semester = course_wise_instructor.year_semester" +

                        " inner join department_wise_user_dtl on department_wise_user_dtl.dept_code = department_wise_course_dtl.dept_code" +
                        " where instructor_mst.designation IN ('VF','TA','AA') " +
                        " and course_wise_instructor.semester_type = '" + sem_code + "' and course_wise_instructor.year_semester = '" + year_code + "' " +
                        " and course_wise_instructor.cancel_flag = 'N'" +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' " +
                        " and department_wise_course_dtl.cancel_flag = 'N'";
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = '" + prog_code + "' ";
            }

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = '" + dept_code + "' ";
            }
            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code = '" + prog_level_code + "' ";
            }
            SqlSelect = SqlSelect + " and course_wise_instructor.semester_type = '" + sem_code + "' and course_wise_instructor.year_semester='" + year_code + "'" +
                        " and department_wise_user_dtl.semester_type = '" + sem_code + "' and department_wise_user_dtl.year_semester = '" + year_code + "' " +
                        " and department_wise_user_dtl.cancel_flag = 'N' and department_wise_user_dtl.user_id = '" + user_id + "' ";

            string temp_str = SqlSelect;

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_AA");

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_TA");

            SqlSelect = SqlSelect + " order by instructor_mst.instructor_code ";

            //SqlSelect = SqlSelect + " ORDER BY course_code";

            return Get_data(SqlSelect);
        }

