        public DataTable get_vf_rate_band_for_edit_rate(string sem_code, string year_code, string user_id, string prog_code, string prog_level_code)
        {
            String SqlSelect = "";

            //SqlSelect = "select instructor_code,instructor_name,designation,rate_wise_designation,instructor_mst.mail,total_experiance,highest_qualification," +
            //            " rate_band,alternate_band,justification," +
