            //            " where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N' ) " +
            //            " order by instructor_code";

            SqlSelect = "select instructor_code,VF_code,instructor_name,designation,rate_wise_designation,instructor_mst.mail,total_experiance,highest_qualification," +
                        " rate_band,alternate_band,justification," +
                        " (case admin_approved when 'Y' then 'Approved' else '' end)admin_approved, " +
                        " (case rateband_approved when 'Y' then 'Approved' else '' end)rateband_approved " +
                        " from instructor_mst " +
                        " where designation = 'VF' " +
                        " and instructor_code in (select distinct course_wise_instructor.instructor_code from course_wise_instructor " +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_instructor.course_code " +
                        " inner join department_wise_user_dtl on department_wise_user_dtl.dept_code = department_wise_course_dtl.dept_code" +
                        " where course_wise_instructor.semester_type = '" + sem_code + "' and course_wise_instructor.year_semester = '" + year_code + "' and course_wise_instructor.cancel_flag = 'N' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' and department_wise_course_dtl.cancel_flag = 'N'";
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = '" + prog_code + "' ";
            }
            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code = '" + prog_level_code + "' ";
            }
            SqlSelect = SqlSelect + " and department_wise_user_dtl.semester_type = '" + sem_code + "' and department_wise_user_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_user_dtl.cancel_flag = 'N' and department_wise_user_dtl.user_id = '" + user_id + "') " +
                        " order by instructor_code";

            return Get_data(SqlSelect);
        }

        public DataTable get_instructor_data(string instructor_code)
        {
            String SqlSelect = "";

            SqlSelect = @"select im.*,um.profile_photo from instructor_mst as im inner join user_mst as um on um.user_id=im.user_id
                            where im.cancel_flag = 'N' and im.instructor_code = '" + instructor_code + "'";

            return Get_data(SqlSelect);
        }

        public DataTable get_TA_instructor_data(string instructor_code, string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = @"select im.*,um.profile_photo from TA_Applicant_Instructor_Mst as im inner join user_mst as um on um.user_id=im.user_id
                            where im.cancel_flag = 'N' and im.instructor_code = '" + instructor_code + "' and im.semester_type='" + sem_code + "' and im.year_semester='" + year_code + "'";

            return Get_data(SqlSelect);
        }

