        public BLReturnObject save_instructor_data(DataSet ds_UploadData, string compnyid, String UserID, String HostName, string str_img_update)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                //DSC_VF_Mgmt server_course_master = (DSC_VF_Mgmt)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                //DSC_VF_Mgmt objCourseMaster_upload = new DSC_VF_Mgmt();
                DSC_VF_Mgmt objInstructorMaster_upload = (DSC_VF_Mgmt)ds_UploadData;

                objInstructorMaster_upload.EnforceConstraints = false;

                if (str_img_update != "")
                {
                    DBDataAdpterObject.SelectCommand.Parameters.Clear();

                    DBDataAdpterObject.SelectCommand.CommandText = str_img_update;

                    DBCommand.ExecuteNonQuery();
                }

                //for (int mprCnt = 0; mprCnt < server_course_master.grade_submit_detail.Rows.Count; mprCnt++)
                //{
                //    objCourseMaster_upload.grade_submit_detail.ImportRow(server_course_master.grade_submit_detail.Rows[mprCnt]);
                //    if (objCourseMaster_upload.grade_submit_detail[mprCnt].doc_no == "")
                //    {
                //        objDocument = new Document();
                //        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "SG", UserID, HostName, ref DocNo, ref message))
                //        {

                //            DBCommand.Transaction.Rollback();
                //            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                //            objBLReturnObject.ExecutionStatus = 2;
                //            return objBLReturnObject;
                //        }
                //        objCourseMaster_upload.grade_submit_detail[mprCnt].doc_no = DocNo;
                //    }
                //}

                objInstructorMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objInstructorMaster_upload.instructor_mst, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objInstructorMaster_upload.instructor_mst.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                // Delete Course Sub Group
                string SqlSelect = "delete from instructor_academic_work_dtl where instructor_code='" + UserID + "'";
                DBCommand.CommandText = SqlSelect;
                DBCommand.CommandType = CommandType.Text;
                try { DBCommand.ExecuteNonQuery(); }
                catch (Exception e) { bool delete_flag = true; }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objInstructorMaster_upload.instructor_academic_work_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objInstructorMaster_upload.instructor_academic_work_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

        public DataTable get_vf_workload_detail(string sem_code, string year_code, string user_id, string prog_code, string prog_level_code, string user_type)
        {
            String SqlSelect = "";

            SqlSelect = "select distinct course_wise_instructor.course_code,course_mst.course_name," +
                        " instructor_mst.instructor_code, instructor_mst.VF_code, instructor_mst.instructor_name" +
                        " from course_wise_instructor" +
                        " inner join course_mst on course_mst.course_code = course_wise_instructor.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_instructor.course_code" +
                        " inner join instructor_mst on instructor_mst.instructor_code = course_wise_instructor.instructor_code" +
                        " inner join department_wise_user_dtl on department_wise_user_dtl.dept_code = department_wise_course_dtl.dept_code" +
                        " where course_wise_instructor.semester_type = '" + sem_code + "' and course_wise_instructor.year_semester = '" + year_code + "' and course_wise_instructor.cancel_flag = 'N' " +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.cancel_flag = 'N' " +
                        " and instructor_mst.cancel_flag = 'N' and instructor_mst.designation IN ('VF','TA','AA') " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' and department_wise_course_dtl.cancel_flag = 'N'" +
                        " and department_wise_user_dtl.semester_type = '" + sem_code + "' and department_wise_user_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_user_dtl.cancel_flag = 'N' ";

            if (user_type != "A1")
            {
                SqlSelect = SqlSelect + " and department_wise_user_dtl.user_id = '" + user_id + "' ";
            }
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = '" + prog_code + "' ";
            }
            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code = '" + prog_level_code + "' ";
            }

            string temp_str = SqlSelect;

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_AA");

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_TA");

            SqlSelect = SqlSelect + " order by course_code";

            return Get_data(SqlSelect);
        }

