        public DataTable Get_CourseWiseInstructor_data(string course_code, string sem_code, string year_code)//Mayur 01052019
        {
            String SqlSelect = "";

            SqlSelect = "select course_wise_instructor.*,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name,course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'N' as is_tutorial,'VF' as rate_band_designation " +
                        " from course_wise_instructor" +
                        " inner join course_mst on course_mst.course_code = course_wise_instructor.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_instructor.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_instructor.course_code = '" + course_code + "' and course_wise_instructor.cancel_flag = 'N'" +
                        " and course_wise_instructor.semester_type = '" + sem_code + "' and course_wise_instructor.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = 'N' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = 'N' " +

                        " union " +

                        " select NULL,course_wise_AA.course_code,NULL,course_wise_AA.instructor_code,NULL,course_wise_AA.cancel_flag,course_wise_AA.created_by,course_wise_AA.created_date,course_wise_AA.created_host,course_wise_AA.last_modified_by,course_wise_AA.last_modified_date,course_wise_AA.last_modified_host,course_wise_AA.semester_type,course_wise_AA.year_semester,NULL,NULL,NULL,NULL,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name,course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'N' as is_tutorial,'AA' as rate_band_designation " +
                        " from course_wise_AA" +
                        " inner join course_mst on course_mst.course_code = course_wise_AA.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_AA.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_AA.course_code = '" + course_code + "' and course_wise_AA.cancel_flag = 'N'" +
                        " and course_wise_AA.semester_type = '" + sem_code + "' and course_wise_AA.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = 'N' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = 'N' " +

                        " union " +

                        " select NULL,course_wise_TA.course_code,NULL,course_wise_TA.instructor_code,NULL,course_wise_TA.cancel_flag,course_wise_TA.created_by, " +
                        " course_wise_TA.created_date,course_wise_TA.created_host,course_wise_TA.last_modified_by,course_wise_TA.last_modified_date,course_wise_TA.last_modified_host, " +
                        " course_wise_TA.semester_type,course_wise_TA.year_semester,NULL,NULL,NULL,NULL,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name, " +
                        " course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'N' as is_tutorial,'TA' as rate_band_designation " +
                        " from course_wise_TA" +
                        " inner join course_mst on course_mst.course_code = course_wise_TA.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_TA.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_TA.course_code = '" + course_code + "' and course_wise_TA.cancel_flag = 'N'" +
                        " and course_wise_TA.semester_type = '" + sem_code + "' and course_wise_TA.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = 'N' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = 'N' " +

                        " union " +

                        " select course_wise_instructor_tutorial.*,NULL,NULL,NULL,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name,course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'Y' as is_tutorial,'VFT' as rate_band_designation " +
                        " from course_wise_instructor_tutorial" +
                        " inner join course_mst on course_mst.course_code = course_wise_instructor_tutorial.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_instructor_tutorial.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_instructor_tutorial.course_code = '" + course_code + "' and course_wise_instructor_tutorial.cancel_flag = 'N'" +
                        " and course_wise_instructor_tutorial.semester_type = '" + sem_code + "' and course_wise_instructor_tutorial.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = 'N' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = 'N' " +
                        " order by is_tutorial,instructor_code";

            return Get_data(SqlSelect);
        }


        public DataTable Get_CourseWiseInstructor_data_v2(string course_code, string sem_code, string year_code, string cancel_flag)//Mayur 01052019
        {
            String SqlSelect = "";

            SqlSelect = "select course_wise_instructor.*,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name,course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'N' as is_tutorial,'VF' as rate_band_designation " +
                        " from course_wise_instructor" +
                        " inner join course_mst on course_mst.course_code = course_wise_instructor.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_instructor.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_instructor.course_code = '" + course_code + "' and course_wise_instructor.cancel_flag = '" + cancel_flag + "'" +
                        " and course_wise_instructor.semester_type = '" + sem_code + "' and course_wise_instructor.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = '" + cancel_flag + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = '" + cancel_flag + "' " +

                        " union " +

                        " select NULL,course_wise_AA.course_code,NULL,course_wise_AA.instructor_code,NULL,course_wise_AA.cancel_flag,course_wise_AA.created_by,course_wise_AA.created_date,course_wise_AA.created_host,course_wise_AA.last_modified_by,course_wise_AA.last_modified_date,course_wise_AA.last_modified_host,course_wise_AA.semester_type,course_wise_AA.year_semester,NULL,NULL,NULL,NULL,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name,course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'N' as is_tutorial,'AA' as rate_band_designation " +
                        " from course_wise_AA" +
                        " inner join course_mst on course_mst.course_code = course_wise_AA.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_AA.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_AA.course_code = '" + course_code + "' and course_wise_AA.cancel_flag = 'N'" +
                        " and course_wise_AA.semester_type = '" + sem_code + "' and course_wise_AA.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = '" + cancel_flag + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = '" + cancel_flag + "' " +

                        " union " +

                        " select NULL,course_wise_TA.course_code,NULL,course_wise_TA.instructor_code,NULL,course_wise_TA.cancel_flag,course_wise_TA.created_by, " +
                        " course_wise_TA.created_date,course_wise_TA.created_host,course_wise_TA.last_modified_by,course_wise_TA.last_modified_date,course_wise_TA.last_modified_host, " +
                        " course_wise_TA.semester_type,course_wise_TA.year_semester,NULL,NULL,NULL,NULL,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name, " +
                        " course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'N' as is_tutorial,'TA' as rate_band_designation " +
                        " from course_wise_TA" +
                        " inner join course_mst on course_mst.course_code = course_wise_TA.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_TA.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_TA.course_code = '" + course_code + "' and course_wise_TA.cancel_flag = 'N'" +
                        " and course_wise_TA.semester_type = '" + sem_code + "' and course_wise_TA.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = '" + cancel_flag + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = '" + cancel_flag + "' " +

                        " union " +

                        " select course_wise_instructor_tutorial.*,NULL,NULL,NULL,course_mst.course_credits,course_mst.instructor_contact_hrs,course_type_mst.type_name,course_type_mst.contact_hr_credit,course_type_mst.prep_hr_per_week,'Y' as is_tutorial,'VFT' as rate_band_designation " +
                        " from course_wise_instructor_tutorial" +
                        " inner join course_mst on course_mst.course_code = course_wise_instructor_tutorial.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_instructor_tutorial.course_code" +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology " +
                        " where course_wise_instructor_tutorial.course_code = '" + course_code + "' and course_wise_instructor_tutorial.cancel_flag = '" + cancel_flag + "'" +
                        " and course_wise_instructor_tutorial.semester_type = '" + sem_code + "' and course_wise_instructor_tutorial.year_semester = '" + year_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                        " and course_mst.cancel_flag = '" + cancel_flag + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and department_wise_course_dtl.cancel_flag = '" + cancel_flag + "' " +
                        " order by is_tutorial,instructor_code";

            return Get_data(SqlSelect);
        }

