        public DataTable Get_Workload_to_authorize(string sem_code, string year_code, string user_id, string user_type)
        {
            String SqlSelect = "";

            if (user_type == "D")
            {
                SqlSelect = @"select instructor_workload_detail.*,(instructor_mst.admin_approved)personal_dtl_approved,instructor_mst.rateband_approved,
                                department_wise_course_dtl.dept_code,department_wise_course_dtl.course_typology 
                                from instructor_workload_detail 
                                inner join instructor_mst on instructor_mst.instructor_code=instructor_workload_detail.instructor_code
                                inner join department_wise_course_dtl on department_wise_course_dtl.course_code=instructor_workload_detail.course_code
		                                and department_wise_course_dtl.semester_type=instructor_workload_detail.semester_type
		                                and department_wise_course_dtl.year_semester=instructor_workload_detail.year_semester
                                        and department_wise_course_dtl.cancel_flag='N'
                                inner join dean_dtl on dean_dtl.dept_code=department_wise_course_dtl.dept_code
		                                and dean_dtl.semester_type=instructor_workload_detail.semester_type
		                                and dean_dtl.year_semester=instructor_workload_detail.year_semester
                                where instructor_workload_detail.cancel_flag='N' ";
                SqlSelect = SqlSelect + "and instructor_workload_detail.semester_type = '" + sem_code + "' and instructor_workload_detail.year_semester = '" + year_code + "' and dean_dtl.user_id='" + user_id + "'";
            }
            else if (user_type == "PC")
            {
                SqlSelect = @"select distinct instructor_workload_detail.*,(instructor_mst.admin_approved)personal_dtl_approved,instructor_mst.rateband_approved,
                                department_wise_course_dtl.dept_code,department_wise_course_dtl.prog_code,department_wise_course_dtl.course_typology
                                from instructor_workload_detail 
                                inner join instructor_mst on instructor_mst.instructor_code=instructor_workload_detail.instructor_code
                                inner join department_wise_course_dtl on department_wise_course_dtl.course_code=instructor_workload_detail.course_code
		                                and department_wise_course_dtl.semester_type=instructor_workload_detail.semester_type
		                                and department_wise_course_dtl.year_semester=instructor_workload_detail.year_semester
                                        and department_wise_course_dtl.cancel_flag='N'
                                inner join programme_coordinator_dtl as pcd on pcd.dept_code = department_wise_course_dtl.dept_code
		                                and pcd.prog_code = department_wise_course_dtl.prog_code
		                                and pcd.semester_type=instructor_workload_detail.semester_type
		                                and pcd.year_semester=instructor_workload_detail.year_semester
                                where instructor_workload_detail.cancel_flag='N' ";
                SqlSelect = SqlSelect + "and instructor_workload_detail.semester_type = '" + sem_code + "' and instructor_workload_detail.year_semester = '" + year_code + "' " +
                                " and pcd.user_id='" + user_id + "' and (department_wise_course_dtl.prog_level_code = pcd.prog_level_code " +
                                " or department_wise_course_dtl.prog_level_code = '' or department_wise_course_dtl.prog_level_code is null)";
            }
            //else
            //{
            //    //SqlSelect = "select * from instructor_workload_detail where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag='N'";
            //    SqlSelect = "select instructor_workload_detail.*,(instructor_mst.admin_approved)personal_dtl_approved,instructor_mst.rateband_approved " +
            //                " from instructor_workload_detail " +
            //                " inner join instructor_mst on instructor_mst.instructor_code=instructor_workload_detail.instructor_code" +
            //                " where instructor_workload_detail.semester_type = '" + sem_code + "' and instructor_workload_detail.year_semester = '" + year_code + "' and instructor_workload_detail.cancel_flag='N'";
            //}

            return Get_data(SqlSelect);
        }

