        public DataTable get_vf_course_wise_workload_detail(string course_code, string sem_code, string year_code)
        {
#if RateBand
          String SqlSelect = "";
            SqlSelect = " select instructor_workload_detail.instructor_code,instructor_mst.VF_code,instructor_mst.instructor_name,instructor_mst.designation, instructor_workload_detail.total_weeks, " +
                        " instructor_workload_detail.total_contact_hrs, instructor_workload_detail.total_preparation_hrs,  instructor_workload_detail.total_hrs, " +
                        " instructor_workload_detail.total_hrs_in_semester,instructor_mst.total_experiance, instructor_mst.highest_qualification," +
                        " rate_band_range.rate_band as rate_band,rbr2.rate_band as upper_rate_band,instructor_workload_detail.alternate_band," +
                        " instructor_workload_detail.justification, course_mst.course_code,course_mst.course_name,course_mst.course_credits, " +
                        " (case instructor_workload_detail.admin_approved when 'Y' then 'Approved' end)admin_approved," +
                        " department_wise_course_dtl.course_typology,course_type_mst.type_name,course_type_mst.sub_group,course_type_mst.prep_hr_per_week, " +
                        " (case ISNULL(instructor_mst.alternate_band,'') when '' then instructor_mst.rate_band else instructor_mst.alternate_band end)instructor_mst_rate_band, " +
                        " instructor_workload_detail.is_tutorial,instructor_workload_detail.hours_bifurcation,instructor_workload_detail.additional_hours " +
                     
                        " from instructor_workload_detail " +
                        " inner join course_mst on course_mst.course_code = instructor_workload_detail.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = instructor_workload_detail.course_code" +
                        " inner join instructor_mst on instructor_mst.instructor_code = instructor_workload_detail.instructor_code " +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology" +
                     
                        " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(instructor_mst.highest_qualification,'')" +
                                    " and CAST(rate_band_range.from_experiance as INT) <= CAST(ISNULL(instructor_mst.total_experiance,0) as INT)" +
                                    " and CAST(rate_band_range.to_experiance as INT) >= CAST(ISNULL(instructor_mst.total_experiance,0) as INT)" +
                                  
                                    " and ISNULL(rate_band_range.typology_sub_group,'')=CASE instructor_workload_detail.is_tutorial when 'Y' then 'SG002' else ISNULL(course_type_mst.sub_group,'') end " +
                                    " and ISNULL(rate_band_range.designation,'') = case ISNULL(instructor_mst.designation,'') when 'instructor' then 'VF' else ISNULL(instructor_mst.designation,'') end " +
                        " left join rate_band_range as rbr2 on ISNULL(rbr2.degree,'') = ISNULL(instructor_mst.highest_qualification,'') " +
                                    " and CAST(rbr2.from_experiance as INT) <= CAST(ISNULL(rate_band_range.to_experiance+1,0) as INT) " +
                                    " and CAST(rbr2.to_experiance as INT) >= CAST(ISNULL(rate_band_range.to_experiance+1,0) as INT) " +
                                  
                                    " and ISNULL(rbr2.typology_sub_group,'')=CASE instructor_workload_detail.is_tutorial when 'Y' then 'SG002' else ISNULL(course_type_mst.sub_group,'') end " +
                                    " and ISNULL(rbr2.designation,'') = case ISNULL(instructor_mst.designation,'') when 'instructor' then 'VF' else ISNULL(instructor_mst.designation,'') end " +
                        " where instructor_workload_detail.semester_type = '" + sem_code + "' and instructor_workload_detail.year_semester = '" + year_code + "' " +
                        " and instructor_workload_detail.course_code = '" + course_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' " +
                        " and instructor_workload_detail.cancel_flag = 'N'  and instructor_mst.cancel_flag = 'N' " +
                        " order by instructor_workload_detail.instructor_code";
                         return Get_data(SqlSelect);
      
#endif

#if SemesterWiseRateBand
            //CHANGES 17052022 month wise calculate rateband 
            DataTable dt = Get_Semester_Wise_RateBand(sem_code, year_code);
            String SqlSelect = "";
            SqlSelect = " select instructor_workload_detail.instructor_code,instructor_mst.VF_code,instructor_mst.instructor_name,instructor_mst.designation, instructor_workload_detail.total_weeks, " +
                        " instructor_workload_detail.total_contact_hrs, instructor_workload_detail.total_preparation_hrs,  instructor_workload_detail.total_hrs, ";

            if (sem_code == "M" && year_code == "2022")
            {
                SqlSelect += " instructor_workload_detail.total_hrs_in_semester,(CAST(instructor_mst.total_experiance as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT)) as total_experiance,";
            }
            else if (Convert.ToInt32(year_code) > Convert.ToInt32("2022"))
            {
                SqlSelect += " instructor_workload_detail.total_hrs_in_semester,(CAST(instructor_mst.total_experiance as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT)) as total_experiance,";
            }
            else { SqlSelect += " instructor_workload_detail.total_hrs_in_semester,instructor_mst.total_experiance,"; }



            SqlSelect += " instructor_mst.highest_qualification," +
                        " rate_band_range.rate_band as rate_band,rbr2.rate_band as upper_rate_band,instructor_workload_detail.alternate_band," +
                        " instructor_workload_detail.justification, course_mst.course_code,course_mst.course_name,course_mst.course_credits,course_mst.cancel_flag as course_cancel_flag, " +
                        " (case instructor_workload_detail.admin_approved when 'Y' then 'Approved' end)admin_approved," +
                        " department_wise_course_dtl.course_typology,course_type_mst.type_name,course_type_mst.sub_group,course_type_mst.prep_hr_per_week, " +
                        " (case ISNULL(instructor_mst.alternate_band,'') when '' then instructor_mst.rate_band else instructor_mst.alternate_band end)instructor_mst_rate_band, " +
                        " instructor_workload_detail.is_tutorial,instructor_workload_detail.hours_bifurcation,instructor_workload_detail.additional_hours " +
                        " from instructor_workload_detail " +
                        " inner join course_mst on course_mst.course_code = instructor_workload_detail.course_code" +
                        " inner join department_wise_course_dtl on department_wise_course_dtl.course_code = instructor_workload_detail.course_code" +
                        " inner join instructor_mst on instructor_mst.instructor_code = instructor_workload_detail.instructor_code " +
                        " left join course_type_mst on course_type_mst.type_code = department_wise_course_dtl.course_typology";



            SqlSelect = SqlSelect + " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(instructor_mst.highest_qualification,'')";

            if (sem_code == "M" && year_code == "2022")
            {
                SqlSelect = SqlSelect + " and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(instructor_mst.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT)) " +
                                     " and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(instructor_mst.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT)) ";
            }
            else if (Convert.ToInt32(year_code) > Convert.ToInt32("2022"))
            {
                SqlSelect = SqlSelect + " and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(instructor_mst.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT)) " +
                                    " and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(instructor_mst.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT)) ";
            }
            else
            {
                SqlSelect += " and CAST(rate_band_range.from_experiance as INT) <= CAST(ISNULL(instructor_mst.total_experiance,0) as INT) " +
                 " and CAST(rate_band_range.to_experiance as INT) >= CAST(ISNULL(instructor_mst.total_experiance,0) as INT) ";
            }
            SqlSelect = SqlSelect + " and ISNULL(rate_band_range.typology_sub_group,'')=CASE instructor_workload_detail.is_tutorial when 'Y' then 'SG002' else ISNULL(course_type_mst.sub_group,'') end " +
            " and ISNULL(rate_band_range.designation,'') = case when ISNULL(instructor_mst.designation,'') = 'instructor' then 'VF' When (instructor_mst.designation_letter = 'TEA') then 'TEA' else ISNULL(instructor_mst.designation,'') end ";
            if (dt != null)
            {
                SqlSelect = SqlSelect + "and rate_band_range.semester_type='" + sem_code + "' and rate_band_range.year_semester='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rate_band_range.semester_type IS NULL and rate_band_range.year_semester IS NULL "; }


            SqlSelect = SqlSelect + " left join rate_band_range as rbr2 on ISNULL(rbr2.degree,'') = ISNULL(instructor_mst.highest_qualification,'') " +
                                     " and CAST(rbr2.from_experiance as INT) <= CAST(ISNULL(rate_band_range.to_experiance+1,0) as INT) " +
                                     " and CAST(rbr2.to_experiance as INT) >= CAST(ISNULL(rate_band_range.to_experiance+1,0) as INT) " +
                                     //" and rbr2.typology_sub_group=course_type_mst.sub_group" +
                                     " and ISNULL(rbr2.typology_sub_group,'')=CASE instructor_workload_detail.is_tutorial when 'Y' then 'SG002' else ISNULL(course_type_mst.sub_group,'') end " +
                                     //" and ISNULL(rbr2.designation,'') = case ISNULL(instructor_mst.designation,'') when 'instructor' then 'VF' else ISNULL(instructor_mst.designation,'') end ";
                                     " and ISNULL(rbr2.designation,'') = case when ISNULL(instructor_mst.designation,'') = 'instructor' then 'VF' When (instructor_mst.designation_letter = 'TEA') then 'TEA' else ISNULL(instructor_mst.designation,'') end ";
            if (dt != null)
            {
                SqlSelect = SqlSelect + "and rbr2.semester_type='" + sem_code + "' and rbr2.year_semester='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rbr2.semester_type IS NULL and rbr2.year_semester IS NULL "; }
            SqlSelect = SqlSelect + " where instructor_workload_detail.semester_type = '" + sem_code + "' and instructor_workload_detail.year_semester = '" + year_code + "' " +
