           " and ISNULL(rate_band_range.designation,'') = case when ISNULL(instructor_mst.designation,'') = 'instructor' then 'VF' WHEN instructor_mst.designation IN ('temp') THEN 'TA' When (instructor_mst.designation_letter = 'TEA') then 'TEA' else ISNULL(instructor_mst.designation,'') end ";
            if (dt != null)
            {
                SqlSelect = SqlSelect + "and rate_band_range.semester_type='" + sem_code + "' and rate_band_range.year_semester='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rate_band_range.semester_type IS NULL and rate_band_range.year_semester IS NULL "; }


            SqlSelect = SqlSelect + " left join rate_band_range as rbr2 on ISNULL(rbr2.degree,'') = ISNULL(instructor_mst.highest_qualification,'') " +
                                     " and CAST(rbr2.from_experiance as INT) <= CAST(ISNULL(rate_band_range.to_experiance+1,0) as INT) " +
                                     " and CAST(rbr2.to_experiance as INT) >= CAST(ISNULL(rate_band_range.to_experiance+1,0) as INT) " +
                                     //" and rbr2.typology_sub_group=course_type_mst.sub_group" +
                                     " and ISNULL(rbr2.typology_sub_group,'')=CASE instructor_workload_detail.is_tutorial when 'Y' then 'SG002' else ISNULL(course_type_mst.sub_group,'') end " +
                                     //" and ISNULL(rbr2.designation,'') = case ISNULL(instructor_mst.designation,'') when 'instructor' then 'VF' else ISNULL(instructor_mst.designation,'') end ";
                                     " and ISNULL(rbr2.designation,'') = case when ISNULL(instructor_mst.designation,'') = 'instructor' then 'VF' WHEN instructor_mst.designation IN ('temp') THEN 'TA'   When (instructor_mst.designation_letter = 'TEA') then 'TEA' else ISNULL(instructor_mst.designation,'') end ";
            if (dt != null)
            {
                SqlSelect = SqlSelect + "and rbr2.semester_type='" + sem_code + "' and rbr2.year_semester='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rbr2.semester_type IS NULL and rbr2.year_semester IS NULL "; }


            SqlSelect = SqlSelect + " LEFT JOIN semester_wise_applicant_rateband_approve SWA on SWA.instructor_code = instructor_mst.instructor_code ";
            SqlSelect = SqlSelect + " AND SWA.semester_type = instructor_workload_detail.semester_type AND SWA.year_semester = instructor_workload_detail.year_semester ";
            SqlSelect = SqlSelect + " AND SWA.ApproveRateBand = 'A' AND SWA.cancel_flag = 'N'";



            SqlSelect = SqlSelect + " where instructor_workload_detail.semester_type = '" + sem_code + "' and instructor_workload_detail.year_semester = '" + year_code + "' " +
                        " and instructor_workload_detail.course_code = '" + course_code + "'" +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' " +
                        " and instructor_workload_detail.cancel_flag = 'N'  and instructor_mst.cancel_flag = 'N' " +
                        " order by instructor_workload_detail.instructor_code";

            return Get_data(SqlSelect);
#endif

        }

        public DataTable get_vf_additional_rates(string sem_code, string year_code)
        {
            String SqlSelect = "";


            SqlSelect = "IF EXISTS(select * from rate_band_range where semester_type='" + sem_code + "' and year_semester='" + year_code + "') "
                       + " BEGIN "
                       + " select rate_band_range.*,tsgd.sub_group_desc from rate_band_range "
                       + " inner join typology_sub_group_dtl as tsgd on tsgd.sub_group_id=rate_band_range.typology_sub_group "
                       + " where designation in ('VF2','AA2','TA2') and rate_band_range.semester_type = '" + sem_code + "' and rate_band_range.year_semester ='" + year_code + "' "
                       + " order by degree,typology_sub_group,CAST(from_experiance as int) "
                       + " END "
                   + " ELSE "
                       + " BEGIN "
                       + " select rate_band_range.*,tsgd.sub_group_desc from rate_band_range "
                       + " inner join typology_sub_group_dtl as tsgd on tsgd.sub_group_id=rate_band_range.typology_sub_group "
                       + " where designation in ('VF2','AA2','TA2') and rate_band_range.semester_type IS NULL and rate_band_range.year_semester IS NULL "
                       + " order by degree,typology_sub_group,CAST(from_experiance as int) "
                       + " END ";


            //SqlSelect = @" select rate_band_range.*,tsgd.sub_group_desc from rate_band_range
            //                inner join typology_sub_group_dtl as tsgd on tsgd.sub_group_id=rate_band_range.typology_sub_group
            //                where designation in ('VF2','AA2','TA2')
            //                order by degree,typology_sub_group,CAST(from_experiance as int) ";

            return Get_data(SqlSelect);
        }

        public DataTable calculate_rate_band(string degree, string total_experiance)
        {
            String SqlSelect = "";

            SqlSelect = " select * from rate_band_range" +
                        " where ISNULL(degree,'') = '" + degree + "'" +
                        " and CAST(from_experiance as INT) <= CAST(ISNULL('" + total_experiance + "',0) as INT)" +
                        " and CAST(to_experiance as INT) >= CAST(ISNULL('" + total_experiance + "',0) as INT)" +
                        " and semester_type IS NULL and year_semester IS NULL ";

