                }



                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";
                int res = 0;
                bool statutrack = false;
                DSC_VF_Mgmt objInstructorMaster_upload = new DSC_VF_Mgmt();

                objInstructorMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_instructor_master.instructor_workload_detail.Rows.Count; mprCnt++)
                {
                    objInstructorMaster_upload.instructor_workload_detail.ImportRow(server_instructor_master.instructor_workload_detail.Rows[mprCnt]);
                    //if (objInstructorMaster_upload.instructor_workload_detail[mprCnt].doc_no == "new")
                    if (objInstructorMaster_upload.instructor_workload_detail[mprCnt].doc_no.Contains("new"))
                    {
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "IWD", UserID, HostName, ref DocNo, ref message))
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        objInstructorMaster_upload.instructor_workload_detail[mprCnt].doc_no = DocNo;
                    }
                    else
                    {

                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "IWD", UserID, HostName, ref DocNo, ref message))
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        objInstructorMaster_upload.instructor_workload_detail[mprCnt].doc_no = DocNo;

                    }
                }
                objInstructorMaster_upload.instructor_workload_detail.AcceptChanges();
                objInstructorMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                foreach (DataTable table in objInstructorMaster_upload.Tables)
                {
                    string tableName = table.TableName;
                    if (tableName == "instructor_workload_detail")
                    {
                        foreach (DataRow rows in table.Rows)
                        {
                            // Construct an INSERT statement
                            string columns = string.Join(",", table.Columns.Cast<DataColumn>().Select(col => col.ColumnName));

                            string values = string.Join(",", table.Columns.Cast<DataColumn>().Select(col =>
                            {
                                object value = rows[col];
                                if (value == DBNull.Value || string.IsNullOrEmpty(value.ToString()))
                                {
                                    return "NULL"; // Treat empty strings or DBNull as NULL
                                }
                                else
                                {
                                    return $"'{value.ToString().Replace("'", "''")}'"; // Escape single quotes
                                }
                            }));



                            string sqlQuery = "INSERT INTO " + tableName + "(" + columns + ") VALUES " + "(" + values + ")";
                            DBDataAdpterObject.SelectCommand.Parameters.Clear();

                            // Set the command text
                            DBDataAdpterObject.SelectCommand.CommandText = sqlQuery;
                            res = DBCommand.ExecuteNonQuery();
                            if (res == 0)
                            {
                                statutrack = true;
                            }
                        }
                    }

                }
                //objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objInstructorMaster_upload.instructor_workload_detail, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);

                // if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objInstructorMaster_upload.instructor_workload_detail.Rows.Count)
                if (statutrack)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    bool status = UpdteWorkloadData(list_doc_no, "Y", UserID);
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";

                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }


        public Boolean UpdteWorkloadData(string doc_no, string type, string user_id)
        {
            DBConnection.Open();

            string SqlSelect = "";

            if (type == "Y")
            {
                SqlSelect = @"UPDATE instructor_workload_detail 
                  SET cancel_flag = 'N', 
                      last_modified_by = '" + user_id + @"', 
                      last_modified_date = GETDATE(), 
                      last_modified_host = '" + HttpContext.Current.Request.UserHostName + @"'
                  WHERE cancel_flag = 'Y' 
                  AND doc_no IN (" + doc_no + @")";
            }
            else
            {
                SqlSelect = @"UPDATE instructor_workload_detail 
                  SET cancel_flag = 'Y', 
                      last_modified_by = '" + user_id + @"', 
                      last_modified_date = GETDATE(), 
                      last_modified_host = '" + HttpContext.Current.Request.UserHostName + @"'
                  WHERE cancel_flag = 'N' 
                  AND doc_no IN (" + doc_no + @")";
            }

            // Clear any existing parameters
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            // Set the command text
            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            // Add parameters to prevent SQL injection

            //DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@user_id", DbType.String, user_id));
            //DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@last_modified_host", DbType.String, HttpContext.Current.Request.UserHostName));
            //DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@doc_no", DbType.String, doc_no));

            try
            {
                int res = DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();
                // Optionally log the exception here
                return false;
            }

        }

