        public DataTable get_VF_Finance_Report_data(string sem_code, string year_code, string dept_code, string prog_code)
        {
            String SqlSelect = "";
            //ISNULL(instructor_workload_detail.additional_hours,0) as additional_hours 
            SqlSelect = @"select course_wise_instructor.course_code,instructor_mst.*,
                            (case ISNULL(instructor_workload_detail.rate_band,'') 
	                            when '' then instructor_workload_detail.rate_band
	                            else instructor_workload_detail.rate_band end)final_rate_band,                 
                            instructor_workload_detail.total_contact_hrs,instructor_workload_detail.total_hrs,
                            instructor_workload_detail.total_hrs_in_semester,instructor_workload_detail.total_preparation_hrs,
                            instructor_workload_detail.total_weeks,instructor_mst.justification,
                            instructor_workload_detail.hr_approved,(instructor_mst.admin_approved)personal_dtl_approved,
                            instructor_mst.rateband_approved,(instructor_workload_detail.admin_approved)workload_approved,
                            instructor_workload_detail.acceptance,instructor_workload_detail.acceptance_type,instructor_workload_detail.acceptance_justification,
                            instructor_workload_detail.acceptance_date,department_mst.dept_name,department_wise_course_dtl.dept_code,
                            department_wise_course_dtl.prog_code,programme_level_mst.prog_level_desc,instructor_workload_detail.is_tutorial,
                            
                            ISNULL(TRY_CAST(instructor_workload_detail.additional_hours AS DECIMAL(10,2)), 0) AS additional_hours
                            from course_wise_instructor
                            inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code
                            left join instructor_workload_detail on instructor_workload_detail.instructor_code=course_wise_instructor.instructor_code
                                    and instructor_workload_detail.course_code=course_wise_instructor.course_code
                                    and instructor_workload_detail.semester_type=course_wise_instructor.semester_type 
                                    and instructor_workload_detail.year_semester=course_wise_instructor.year_semester 
                                    and instructor_workload_detail.cancel_flag='N'
                            left join department_wise_course_dtl on department_wise_course_dtl.course_code=course_wise_instructor.course_code
                                    and department_wise_course_dtl.semester_type=course_wise_instructor.semester_type
                                    and department_wise_course_dtl.year_semester=course_wise_instructor.year_semester
                                    and department_wise_course_dtl.cancel_flag='N'
                            left join department_mst on department_mst.dept_code=department_wise_course_dtl.dept_code
		                            and department_mst.cancel_flag='N'
                            left join programme_level_mst on programme_level_mst.prog_level_code=department_wise_course_dtl.prog_level_code
		                            and programme_level_mst.cancel_flag='N'
                            where course_wise_instructor.cancel_flag='N' and instructor_mst.cancel_flag='N' 
                            and instructor_mst.designation in ('VF','AA','TA') and instructor_workload_detail.acceptance='Y' ";

            if (Convert.ToInt32(year_code) >= 2023)
            {
                SqlSelect = SqlSelect + " and instructor_workload_detail.uso_hr_approved ='Y'  ";
            }
            SqlSelect = SqlSelect + " and course_wise_instructor.semester_type='" + sem_code + "' and course_wise_instructor.year_semester='" + year_code + "'  ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code='" + dept_code + "' ";
            }

            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code='" + prog_code + "' ";
            }

            string temp_str = SqlSelect;

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_AA");

            SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_TA");

            SqlSelect = SqlSelect + " order by instructor_code";

            return Get_data(SqlSelect);
        }

