        public void send_Appointment_mail_to_visiting_faculty(ref Dictionary<string, object>[] dic_instructor_list, DataTable dt_instructor_mst_data, string directory_path, string str_path, out int PDF_status)
        {
            PDF_status = 0;

            try
            {
                string[] delete_filenames = Directory.GetFiles(directory_path);

                for (int i = 0; i < delete_filenames.Length; i++)
                {
                    FileInfo file = new FileInfo(delete_filenames[i]);
                    file.Delete();
                }

                for (int i = 0; i < dic_instructor_list.Length; i++)
                {
                    DataRow[] dr = dt_instructor_mst_data.Select("instructor_code = '" + dic_instructor_list[i]["instructor_code"] + "'");

                    if (dr.Length > 0)
                    {
                        if (dr[0]["mail"].ToString() != "")
                        {
                            dic_instructor_list[i]["status"] = "False";
                            dic_instructor_list[i]["destination_mail"] = dr[0]["mail"].ToString();
                            dic_instructor_list[i]["instructor_name"] = dr[0]["instructor_name"].ToString();

                            ReportPrinter obReportPrinter = new ReportPrinter();

                            obReportPrinter.PageFile = "https://" + str_path + "Admin/Master/HR_PrintLetter.aspx?iid=" + dic_instructor_list[i]["instructor_code"] + "&idept=" + dic_instructor_list[i]["dept_name"] + "&sc=" + dic_instructor_list[i]["sem_code"] + "&yc=" + dic_instructor_list[i]["year_code"];

                            obReportPrinter.HeaderFile = "https://" + str_path + "Admin/Master/Header_print_letter.htm";
                            //obReportPrinter.HeaderFile = Server.MapPath("~/Admin/Master/Header_print_letter.htm");
                            //obReportPrinter.FooterFile = root + "HeaderFooter/Footer.html";
                            obReportPrinter.FooterFile = "https://" + str_path + "Admin/Master/Footer_print_letter.htm";
                            //obReportPrinter.FooterFile = Server.MapPath("~/Admin/Master/Footer_print_letter.htm");

                            obReportPrinter.MarginTop = "25";
                            obReportPrinter.MarginBottom = "17";

                            obReportPrinter.GetPdf();

                            if (obReportPrinter.FileContent != null && obReportPrinter.FileContent.Length > 0)
                            {
                                FileStream fs = new FileStream(directory_path + "" + dic_instructor_list[i]["instructor_code"] + "_" + dr[0]["first_name"].ToString() + "_" + dic_instructor_list[i]["dept_name"] + ".pdf", FileMode.Create);
                                fs.Write(obReportPrinter.FileContent, 0, obReportPrinter.FileContent.Length);
                                fs.Dispose();

                                dic_instructor_list[i]["attachment_path"] = directory_path + "" + dic_instructor_list[i]["instructor_code"] + "_" + dr[0]["first_name"].ToString() + "_" + dic_instructor_list[i]["dept_name"] + ".pdf";
                                dic_instructor_list[i]["attachment_name"] = "" + dic_instructor_list[i]["instructor_code"] + "_" + dr[0]["first_name"].ToString() + "_" + dic_instructor_list[i]["dept_name"] + ".pdf";

                                dic_instructor_list[i]["status"] = "True";
                            }
                            else
                            {
                                PDF_status++;
                                dic_instructor_list[i]["message"] = "Unable to Create PDF";
                            }
                        }
                        else
                        {
                            dic_instructor_list[i]["status"] = "False";
                            dic_instructor_list[i]["message"] = "Email ID not Found";
                        }
                    }
                    else
                    {
                        dic_instructor_list[i]["status"] = "False";
                        dic_instructor_list[i]["message"] = "Instructor not Found";
                    }
                }
            }
            catch (Exception ex)
            {
                //return ex.ToString();
            }
        }

        public DataTable get_VF_doctoral_detail(string sem_code, string year_code, string instructor_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select * from instructor_workload_detail as iwd
                            inner join department_wise_course_dtl as dwc on dwc.course_code=iwd.course_code and dwc.cancel_flag='N'
		                            and dwc.semester_type=iwd.semester_type and dwc.year_semester=iwd.year_semester
                            where iwd.semester_type='" + sem_code + "' and iwd.year_semester='" + year_code + @"' and iwd.cancel_flag='N'
