            return Get_data(SqlSelect);
        }

        public string get_user_type_for_letter_TA_AA(string sem_code, string year_code, string instructor_code)
        {
            String SqlSelect = "";

            SqlSelect = @"select * from course_wise_TA where instructor_code='" + instructor_code + "'  and semester_type='" + sem_code + "' and year_semester='" + year_code + "'";

            DataTable dt_count_TA = Get_data(SqlSelect);

            SqlSelect = "";

            SqlSelect = @"select * from course_wise_AA where instructor_code='" + instructor_code + "'  and semester_type='" + sem_code + "' and year_semester='" + year_code + "'";

            DataTable dt_count_AA = Get_data(SqlSelect);

            if (dt_count_TA != null)
            {
                if (dt_count_TA.Rows.Count > 0) return "TA";
            }
            else if (dt_count_AA != null)
            {
                if (dt_count_AA.Rows.Count > 0) return "AA";
            }

            return "";
        }

