        public Boolean Uso_Hr_Update_RateBand(string instructor_code, string sem_code, string year_code, string course_code, string user_id, string user_type_ta, string rate_band)
        {

            DataTable dt_typology_dtl = get_department_wise_get_typology(course_code, sem_code, year_code);
            DataTable dt_data = new DataTable();
            DataTable check_ta_details = new DataTable();
            if (dt_typology_dtl == null)
            {
                check_ta_details = GET_inst_wise_TA_details(sem_code, year_code, course_code, instructor_code);
                if (check_ta_details == null)
                {
                    dt_data = get_vf_course_wise_workload_detail_v2(course_code, sem_code, year_code, "N");
                }
                else { dt_data = get_vf_course_wise_workload_detail_v2_TA(course_code, sem_code, year_code, "N"); }

            }
            else
            {
                dt_data = get_vf_course_wise_workload_detail_v2_TA(course_code, sem_code, year_code, "N");
            }

            dt_data = dt_data.Select("instructor_code = '" + instructor_code + "'").CopyToDataTable();




            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            string SqlSelect = "";

            SqlSelect = @"UPDATE instructor_workload_detail SET rate_band ='" + dt_data.Rows[0]["rate_band"] + "',total_exp = '" + dt_data.Rows[0]["total_experiance"] + "', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and instructor_code='" + instructor_code + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and course_code='" + course_code + "' ";

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }








        public Boolean UpdateInstructorWorkloadFlagChangeCourseCode(DataTable dt, string new_course_code)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            string SqlSelect = "";

            for (int i = 0; i < dt.Rows.Count; i++)
            {

                SqlSelect += @" UPDATE instructor_workload_detail SET ";
                if (dt.Rows[i]["admin_approved"].ToString() == "" || dt.Rows[i]["admin_approved"].ToString() == null)
                {
                    SqlSelect += @" admin_approved = null ,";
                }
                else
                {
                    SqlSelect += @" admin_approved ='" + dt.Rows[i]["admin_approved"].ToString() + "' ,";

                }

                if (dt.Rows[i]["hr_approved"].ToString() == "" || dt.Rows[i]["hr_approved"].ToString() == null)
                {
                    SqlSelect += @" hr_approved = null ,";
                }
                else
                {
                    SqlSelect += @" hr_approved ='" + dt.Rows[i]["hr_approved"].ToString() + "',";

                }

                if (dt.Rows[i]["uso_hr_approved"].ToString() == "" || dt.Rows[i]["uso_hr_approved"].ToString() == null)
                {
                    SqlSelect += @" uso_hr_approved = null ";
                }
                else
                {
                    SqlSelect += @" uso_hr_approved ='" + dt.Rows[i]["uso_hr_approved"].ToString() + "'";

                }

                SqlSelect += " where cancel_flag = 'N' and instructor_code = '" + dt.Rows[i]["instructor_code"].ToString() + "' and semester_type = '" + dt.Rows[i]["semester_type"].ToString() + "' and year_semester = '" + dt.Rows[i]["year_semester"].ToString() + "' and course_code = '" + new_course_code + "' ";

            }
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }




        public DataTable Get_instructor_workload(string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = "select instructor_mst.instructor_code,instructor_mst.VF_code,instructor_mst.instructor_name,instructor_mst.designation,instructor_mst.designation_letter,instructor_workload_detail.course_code " +
