        public Boolean update_workload_dtl(string instructor_list, string course_list, string semester, string year_code, string user_id, string host_name)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            //DBConnection.Open();

            //string SqlSelect = "";
            //SqlSelect = @" UPDATE instructor_workload_detail SET cancel_flag ='Y', last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'" +
            //    " WHERE ( semester_type = '" + semester + "' and year_semester = '" + year_code + "' and instructor_code in (" + instructor_list + ") and  course_code in (" + course_list + ") and cancel_flag ='N' )";


            ///*************************/
            //DBDataAdpterObject.SelectCommand.Parameters.Clear();

            //DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            //try
            //{
            //    DBCommand.ExecuteNonQuery();

            //    DBConnection.Close();

            //    return true;
            //}
            //catch (Exception)
            //{
            //    DBConnection.Close();

            //    return false;
            //}

            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                string Date = DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss");
                string Qry = "";
                bool SuccessOfTask = false;

                Qry = @"SELECT * INTO #UpdatedRecords FROM instructor_workload_detail WITH(NOLOCK)
                        WHERE 
                        (   semester_type = '" + semester + @"' AND 
                            year_semester = '" + year_code + @"' AND 
                            instructor_code IN (" + instructor_list + @") AND 
                            course_code IN (" + course_list + @") AND 
                            cancel_flag ='N' 
                        );";
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                DBDataAdpterObject.SelectCommand.CommandText = Qry;
                int NoOfRecords = DBCommand.ExecuteNonQuery();
                if (NoOfRecords > 0)
                {
                    Qry = @"UPDATE 
                                instructor_workload_detail 
                            SET 
                                cancel_flag = 'Y',
                                last_modified_by = '" + user_id + @"',
                                last_modified_host = '" + host_name + @"',
                                last_modified_date = '" + Date + @"'
                            WHERE 
                            (   
                                semester_type = '" + semester + @"' AND 
                                year_semester = '" + year_code + @"' AND 
                                instructor_code IN (" + instructor_list + @") AND  
                                course_code IN (" + course_list + @") AND 
                                cancel_flag ='N' 
                            );
                            
                            UPDATE  
                                #UpdatedRecords
                            SET
                                admin_approved = 'N',
                                last_modified_by = '" + user_id + @"',
                                last_modified_host = '" + host_name + @"',
                                last_modified_date = '" + Date + @"';";

                    DBDataAdpterObject.SelectCommand.Parameters.Clear();
                    DBDataAdpterObject.SelectCommand.CommandText = Qry;
                    if (DBCommand.ExecuteNonQuery() < 1)
                    {
                        DBCommand.Transaction.Rollback();
                        return false;
                    }
                    String message = "";
                    String DocNo = "";
                    for (int i = 1; i <= NoOfRecords; i++)
                    {
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "01", "IWD", user_id, host_name, ref DocNo, ref message))
                        {
                            SuccessOfTask = false;
                            break;
                        }

                        Qry = @"DECLARE @CurrentDocNo NVARCHAR(20)='" + DocNo + @"';
                                INSERT INTO instructor_workload_detail 	
                          	    SELECT TOP 1
                                    @CurrentDocNo,instructor_code,course_code,total_weeks,total_contact_hrs,total_preparation_hrs,total_hrs,total_hrs_in_semester,total_exp,
                                    rate_band,alternate_band,justification,admin_approved,hr_approved,acceptance,acceptance_type,acceptance_justification,acceptance_date,
                                    cancel_flag,created_by,created_date,created_host,last_modified_by,last_modified_date,last_modified_host,semester_type,year_semester,
                                    is_tutorial,hours_bifurcation,additional_hours,uso_hr_approved
                          	    FROM (SELECT ROW_NUMBER() OVER(ORDER BY doc_no) AS RowNum,* FROM #UpdatedRecords WITH(NOLOCK)) AS T  WHERE T.RowNum = " + i + ";";
                        DBDataAdpterObject.SelectCommand.Parameters.Clear();
                        DBDataAdpterObject.SelectCommand.CommandText = Qry;
                        if (DBCommand.ExecuteNonQuery() > 0)
                        {
                            SuccessOfTask = true;
                        }
                        else
                        {
                            SuccessOfTask = false;
                            break;
                        }
                    }
                }
                else
                    SuccessOfTask = false;

                if (SuccessOfTask)
                    DBCommand.Transaction.Commit();
                else
                    DBCommand.Transaction.Rollback();

                return SuccessOfTask;
            }
            catch (Exception)
            {
                DBCommand.Transaction.Rollback();
                return false;
            }
            finally
            {
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
            }
        }

