        public DataTable Get_VF_TA_AA_Letter_Email_Body_data(string Instructor_type_email, string tea_email, string userType)
        {
            DataSet dsapplications = new DataSet();
            //Dictionary<String, Object> ObjParam = receive_obj.requestObjectInfo.OpArgs;
            StringBuilder SQLSelect = new StringBuilder();
            DataTable dt = new DataTable();

            if (tea_email == "TEA")
            {
                SQLSelect.Append(@" select * from email_content_details where email_type = '" + tea_email + "' and type_content = 'email' ");
            }
            else if (Instructor_type_email == "VF")
            {
                SQLSelect.Append(@" select * from email_content_details where email_type = '" + Instructor_type_email + "' and type_content = 'email' ");
            }
            else if (userType == "TA" || userType == "AA")
            {
                SQLSelect.Append(@" select * from email_content_details where email_type = '" + userType + "' and type_content = 'email' ");
            }
            else if (Instructor_type_email == "Feedback")
            {
                SQLSelect.Append(@" select * from email_content_details where email_type = '" + Instructor_type_email + "' and type_content = 'email' ");
            }
            else if (Instructor_type_email == "FeedbackReport")
            {
                SQLSelect.Append(@" select * from email_content_details where email_type = '" + Instructor_type_email + "' and type_content = 'email' ");
            }


            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SQLSelect.ToString();
            DBDataAdpterObject.TableMappings.Clear();
            DBDataAdpterObject.Fill(dsapplications);

            if (dsapplications.Tables.Count > 0 && dsapplications.Tables[0].Rows.Count > 0)
            {

                dt = dsapplications.Tables[0].Copy();
            }
            else
            {
                dt = null;
            }

            return dt;

        }

