        public DataTable get_news_announcement_dtl_userwise(string user_type)
        {
            String SqlSelect = "";

            SqlSelect = ";WITH news_announcement_dtlCTE(doc_no,cancel_flag, created_date, expiry_date, date, title, view_type, user_type,news_image) AS " +
                         "( SELECT doc_no, cancel_flag, created_date, expiry_date, STUFF(STUFF(CONVERT(char(12), date, 113),3,1, '-'),7,1,'-'), title, CAST(LEFT(user_type, CHARINDEX(',', user_type + ',') - 1) AS varchar(50)), " +
                         "STUFF(user_type, 1, CHARINDEX(',', user_type + ','), ''),news_image " +
                         "FROM news_announcement_dtl " +
                         "UNION all " +
                         "SELECT  " +
                         "doc_no, cancel_flag, created_date, expiry_date, STUFF(STUFF(CONVERT(char(12), date, 113),3,1, '-'),7,1,'-')," +
                         "title,  " +
                         "CAST(LEFT(user_type, CHARINDEX(',', user_type + ',') - 1) AS varchar(50)),  " +
                         "STUFF(user_type, 1, CHARINDEX(',', user_type + ','), ''),news_image  " +
                         "FROM news_announcement_dtlCTE  " +
                         "WHERE user_type > '' )";

            if (user_type != "") SqlSelect = SqlSelect + "SELECT doc_no, cancel_flag, created_date, expiry_date, date, title, view_type,news_image FROM news_announcement_dtlCTE WHERE expiry_date > GETDATE()-1 AND view_type='" + user_type + "' AND cancel_flag = 'N' order by created_date desc";

            return Get_data(SqlSelect);
        }

