        public BLReturnObject save_attendance(DataSet ds_UploadData, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {

                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                server_attendance = (DS_Attendance)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                //To generate next doc number

                String message = "";
                String DocNo = "";
                String DocNo1 = "";
                //Ds_Workflow obj_workflow = new Ds_Workflow();
                DS_Attendance obj_attendance = new DS_Attendance();

                obj_attendance.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_attendance.attendance_mst.Rows.Count; mprCnt++)
                {

                    obj_attendance.attendance_mst.ImportRow(server_attendance.attendance_mst.Rows[mprCnt]);

                }



                obj_attendance.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_attendance.attendance_mst, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);

                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_attendance.attendance_mst.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";

                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {

            }
            return objBLReturnObject;
        }

        public DataTable get_attendance_data(string user_id)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";


            SqlSelect = "select *,SUBSTRING( convert(varchar, entry_time,108),1,5) as entrytime , SUBSTRING( convert(varchar,exit_time,108),1,5) as exittime from attendance_mst where convert(varchar,date_of_attendance,105)  = convert(varchar,GETDATE(),105) and user_id='" + user_id + "'";

            return Get_data(SqlSelect);
        }

        public DataTable get_attendance_report_data(string start_date, string end_date)
        {
            string[] start = start_date.Split('/');
            string[] end = end_date.Split('/');

            string f_startdate = "" + start[2] + "-" + start[1] + "-" + start[0];
            string f_enddate = "" + end[2] + "-" + end[1] + "-" + end[0];

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "select um.user_id,um.user_name,CONVERT(varchar(15),am.date_of_attendance,103) as punch_date,right(convert(varchar(32),am.entry_time,100),8) as entrytime , right(convert(varchar(32),am.exit_time,100),8) as exittime " +
                        ",SUBSTRING(CONVERT(VARCHAR(20),(exit_time - entry_time),120),12,5) as total_time,entry_ip,exit_ip,entry_com_name,exit_com_name " +
                        " from attendance_mst as am inner join user_mst as um on am.user_id = um.user_id " +

                        " where  CAST(date_of_attendance AS Date) >= '" + f_startdate + "' AND CAST(date_of_attendance AS Date) <= '" + f_enddate + "'  order by user_id";


            return Get_data(SqlSelect);
        }


        public DataTable course_wise_session_submit_list(string user_id, string user_type, string sem_code, string year_code, string user_prog_code, string prog_code, string prog_level_code)
        {
            String SqlSelect = "";

            if (user_type == "I2" || user_type == "PC" || user_type == "D")
            {
                SqlSelect = " select res3.*, " +
                            " (case grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval', " +
                            " (case grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval', " +
                            " (case grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval', " +
                            " (case grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval'," +
                            " (case cws.is_submit when 'Y' then 'Submitted' when 'N' then 'Saved' else 'Not submitted' end) as 'attendance_status',cws.doc_pdf " +
                            " from " +
                            " ( select res1.* from ( " +
                            " select exams.course_code,exams.course_name,exams.total_exams,students.total_students from" +
                            " (select course_mst.course_code,course_mst.course_name,exams1.total_exams from course_mst " +
                                " left join(select course_code,COUNT(exam_code)total_exams from exam_master" +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'   " +
                                            " group by course_code" +
                                        " )exams1" +
                                " on course_mst.course_code=exams1.course_code" +
                                "  inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code " +
                                " where course_mst.semester_type='" + sem_code + "' and course_mst.year_semester='" + year_code + "' and course_mst.cancel_flag='N' and dwc.semester_type='" + sem_code + "' and dwc.year_semester='" + year_code + "'";
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }
                SqlSelect = SqlSelect + " )exams" +
                             " left join " +
                                 " (SELECT course_code,COUNT(user_id)total_students" +
                                     " FROM student_course_allocate_dtl" +
                                     " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag = 'N'" +
                                     " group by course_code" +
                                 " )students" +
                             " on exams.course_code=students.course_code" +
                             " )res1 " +
                             " inner join " +
                             " (" +
                                 " select course_wise_instructor.*,instructor_mst.user_id,instructor_mst.instructor_name " +
                                 " from course_wise_instructor" +
                                 " inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code" +
                                 " where instructor_mst.user_id='" + user_id + "' and course_wise_instructor.semester_type = '" + sem_code + "'" +
                                 " and course_wise_instructor.year_semester = '" + year_code + "'" +
                             " )res2" +
                             " on res1.course_code = res2.course_code " +
                             " )res3 " +
                             " left join grade_submit_detail on grade_submit_detail.course_code = res3.course_code and grade_submit_detail.semester_type='" + sem_code + "' and grade_submit_detail.year_semester='" + year_code + "'" +
                             " left join course_wise_session_mst as cws on cws.course_code = res3.course_code and cws.semester_type= '" + sem_code + "' and cws.year_semester='" + year_code + "' and cws.cancel_flag='N' ";

                string temp_str = SqlSelect;

                SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_AA");

                SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_TA");

                SqlSelect = SqlSelect + " order by res3.course_code";
            }
            else if (user_type == "FA")
            {
                SqlSelect = "select res1.*, " +
                            " (case grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval', " +
                            " (case grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval', " +
                            " (case grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " (case grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval'," +
                            " (case cws.is_submit when 'Y' then 'Submitted' when 'N' then 'Saved' else 'Not submitted' end) as 'attendance_status',cws.doc_pdf " +
                            " from " +
                            " ( select exams.course_code,exams.course_name,exams.total_exams,students.total_students from" +
                            " (select course_mst.course_code,course_mst.course_name,exams1.total_exams from course_mst " +
                                " left join(select course_code,COUNT(exam_code)total_exams from exam_master" +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'" +
                                            " group by course_code" +
                                        " )exams1" +
                                " on course_mst.course_code=exams1.course_code" +
                                " where course_mst.semester_type='" + sem_code + "' and course_mst.year_semester='" + year_code + "' and cancel_flag='N'" +
                            " )exams" +
                            " left join " +
                                " (SELECT course_code,COUNT(user_id)total_students" +
                                    //" FROM student_wise_course_dtl" +
                                    " FROM student_course_allocate_dtl" +
                                    " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag = 'N'" +
                                    " group by course_code" +
                                " )students" +
                            " on exams.course_code=students.course_code" +
                            " )res1 " +
                            " left join grade_submit_detail on grade_submit_detail.course_code = res1.course_code and grade_submit_detail.semester_type='" + sem_code + "' and grade_submit_detail.year_semester='" + year_code + "' " +
                            " inner join (SELECT distinct course_mst.course_code" +
                                " FROM course_mst  " +
                                " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code " +
                                " inner join department_wise_user_dtl on department_wise_user_dtl.dept_code = dwc.dept_code" +
                                " where course_mst.cancel_flag='N' and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' " +
                                " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'  ";
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }
                SqlSelect = SqlSelect + " and department_wise_user_dtl.user_id='" + user_id + "' and department_wise_user_dtl.user_type='FA' and department_wise_user_dtl.semester_type = '" + sem_code + "' and department_wise_user_dtl.year_semester = '" + year_code + "' " +
             " )d on d.course_code = res1.course_code " +
             " left join course_wise_session_mst as cws on cws.course_code = res1.course_code and cws.semester_type= '" + sem_code + "' and cws.year_semester='" + year_code + "' and cws.cancel_flag='N' " +
             " order by res1.course_code";
            }
            else
            {
                SqlSelect = "select res1.*, " +
                            " (case grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval', " +
                            " (case grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval', " +
                            " (case grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " (case grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval'," +
                            " (case cws.is_submit when 'Y' then 'Submitted' when 'N' then 'Saved' else 'Not submitted' end) as 'attendance_status',cws.doc_pdf " +
                            " from " +
                            " ( select exams.course_code,exams.course_name,exams.total_exams,students.total_students from" +
                            " (select course_mst.course_code,course_mst.course_name,exams1.total_exams from course_mst " +
                                " left join(select course_code,COUNT(exam_code)total_exams from exam_master" +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'" +
                                            " group by course_code" +
                                        " )exams1" +
                                " on course_mst.course_code=exams1.course_code" +
                                    "  inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code " +
                                 " where course_mst.semester_type='" + sem_code + "' and course_mst.year_semester='" + year_code + "' and course_mst.cancel_flag='N' and dwc.semester_type='" + sem_code + "' and dwc.year_semester='" + year_code + "'";
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }
                SqlSelect = SqlSelect + " )exams" +
                            " left join " +
                                " (SELECT course_code,COUNT(user_id)total_students" +
                                    " FROM student_course_allocate_dtl" +
                                    " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag = 'N'" +
                                    " group by course_code" +
                                " )students" +
                            " on exams.course_code=students.course_code" +
                            " )res1 ";

                SqlSelect = SqlSelect + " inner join (select distinct course_code from student_course_allocate_dtl " +
                                            " where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N' )a on res1.course_code=a.course_code" +
                                        " left join grade_submit_detail on grade_submit_detail.course_code = res1.course_code and grade_submit_detail.semester_type='" + sem_code + "' and grade_submit_detail.year_semester='" + year_code + "' " +
                                        " left join course_wise_session_mst as cws on cws.course_code = res1.course_code and cws.semester_type= '" + sem_code + "' and cws.year_semester='" + year_code + "' " +
                                        " and cws.cancel_flag='N' " +
                                        " order by res1.course_code";
            }

            return Get_data(SqlSelect);
        }

