        public BLReturnObject excel_fee_collection_upload_branch(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {

                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Upload_Fee_Collection server_studcourse_upload = (DSC_Upload_Fee_Collection)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_Upload_Fee_Collection objstudcourse_upload = new DSC_Upload_Fee_Collection();

                objstudcourse_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_studcourse_upload.upload_direct_icici_branch.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "UB", UserID, HostName, ref DocNo, ref message))
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objstudcourse_upload.upload_direct_icici_branch.ImportRow(server_studcourse_upload.upload_direct_icici_branch.Rows[mprCnt]);
                    objstudcourse_upload.upload_direct_icici_branch[mprCnt].doc_no = DocNo;
                }

                for (int mprCnt = 0; mprCnt < server_studcourse_upload.user_fees_status.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    string document = server_studcourse_upload.user_fees_status[mprCnt].doc_no;
                    string strSplitArr = document.Substring(0, 1);
                    objstudcourse_upload.user_fees_status.ImportRow(server_studcourse_upload.user_fees_status.Rows[mprCnt]);
                    if (strSplitArr == "U" || strSplitArr == "A")
                    { }
                    else
                    {
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "UF", UserID, HostName, ref DocNo, ref message))
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        objstudcourse_upload.user_fees_status[mprCnt].doc_no = DocNo;
                    }
                }

                objstudcourse_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objstudcourse_upload.upload_direct_icici_branch, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objstudcourse_upload.upload_direct_icici_branch.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objstudcourse_upload.user_fees_status, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objstudcourse_upload.user_fees_status.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }


                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

