        public DataTable get_icici_citrus_data(string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = @"select * from applicationpaymenttransaction as apt 
                            left join user_fees_installment_dtl as ufi on ufi.user_id=apt.user_id and cancel_flag='N' 
			                and ufi.semester_type=apt.semester_type and ufi.year_semester=apt.year_semester 
                            where apt.semester_type='" + sem_code + "' and apt.year_semester='" + year_code + "'";

            return Get_data(SqlSelect);
        }

        public DataTable get_icici_cash_dd(string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = @"select substring(dd_no, patindex('%[^0]%',dd_no), LEN(dd_no)) as dd_no2,* from user_installment_payslip_dtl as uip 
                            left join user_fees_installment_dtl as ufi on ufi.user_id=uip.user_id and ufi.cancel_flag='N'
                            and ufi.semester_type=uip.semester_type and ufi.year_semester=uip.year_semester 
                            where uip.semester_type='" + sem_code + "' and uip.year_semester='" + year_code + "' and uip.cancel_flag='N' " +
                        " order by uip.user_id,uip.dd_no,case ISNULL(uip.last_modified_date,'') when '' then uip.created_date else uip.last_modified_date end desc";

            return Get_data(SqlSelect);
        }

