        #region Timetable

        public DataTable get_timetableData(string sem_code, string year_code, string prog_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect = "SELECT cwt.course_code,cm.course_name,dwc.dept_code,cwt.from_time,cwt.year_code,cwt.To_time,cwt.day_code,cwt.room_id " +
                        " ,cwt.cancel_flag,cwt.semester_type,cwt.year_semester,REPLACE(cwt.from_time,'.','')Replaced " +
                        " ,(case cwt.from_time when ISNULL(cwt.from_time,'0') then (CAST(cwt.To_time as float) - CAST(cwt.from_time as float)) else 0 end)total_hours,dwc.prog_code " +
                        " FROM course_wise_time as cwt " +
                        " inner join course_mst as cm on cm.course_code = cwt.course_code " +
                        " inner join department_wise_course_dtl as dwc on dwc.course_code = cwt.course_code " +
                        " where cwt.semester_type='" + sem_code + "' and cwt.year_semester='" + year_code + "' and cwt.cancel_flag='N' " +
                        " and cm.semester_type='" + sem_code + "' and cm.year_semester='" + year_code + "' and cm.cancel_flag='N' " +
                        " and dwc.semester_type='" + sem_code + "' and dwc.year_semester='" + year_code + "' and dwc.cancel_flag='N' and dwc.prog_code ='" + prog_code + "' ";

            return Get_data(SqlSelect);
        }

