                     " inner join calendar_event_mst on calendar_event.event_code = calendar_event_mst.event_code " +
                     " where calendar_event.cancel_flag ='N' and calendar_event_mst.cancel_flag ='N' and user_id in(" + user_id + ")  " +
                // " and (from_date >='" + start_date + "' or to_date <= '" + end_date + "')  " ;
                " and ((calendar_event.from_date >= '" + start_date + "' and  calendar_event.from_date <= '" + end_date + "') " +
                                         "or (calendar_event.to_date >= '" + start_date + "' and  calendar_event.to_date <= '" + end_date + "') " +
                                         "or (calendar_event.from_date <= '" + start_date + "' and  calendar_event.to_date >= '" + start_date + "')" +
                                         "or (calendar_event.from_date <= '" + end_date + "' and  calendar_event.to_date >= '" + end_date + "')" +
                                         "or (calendar_event.from_date = '" + start_date + "' or  calendar_event.to_date = '" + end_date + "'))";

            return Get_data(SqlSelect);
        }

