        public DataTable get_google_calendar_event_data(string start_date, string end_date, string user_id)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";


            SqlSelect = "select case frequency when 'Weekly' then DATEADD(week,cast(occurrences_count as int) * CAST( interval as int),to_date) when 'Monthly' then DATEADD(MONTH,cast(occurrences_count as int) * CAST( interval as int),to_date) when 'Daily' then DATEADD(DAY,cast(occurrences_count as int) * CAST( interval as int),to_date) when 'Yearly' then DATEADD(YEAR,cast(occurrences_count as int) * CAST( interval as int),to_date)   " +
                        " else to_date  end as todate,* from calendar_google_data  " +
                                 " where calendar_google_data.cancel_flag ='N'  and user_id in(" + user_id + ")  ";

            // " and (from_date >='" + start_date + "' or to_date <= '" + end_date + "')  " ;
            if (start_date != "" && end_date != "")
            {


                SqlSelect = SqlSelect + " and ((calendar_google_data.from_date >= '" + start_date + "' and  calendar_google_data.from_date <= '" + end_date + "') " +
                                             "or (calendar_google_data.to_date >= '" + start_date + "' and  calendar_google_data.to_date <= '" + end_date + "') " +
                                             "or (calendar_google_data.from_date <= '" + start_date + "' and  calendar_google_data.to_date >= '" + start_date + "')" +
                                             "or (calendar_google_data.from_date <= '" + end_date + "' and  calendar_google_data.to_date >= '" + end_date + "')" +
                                             "or (calendar_google_data.from_date = '" + start_date + "' or  calendar_google_data.to_date = '" + end_date + "'))";
            }

            return Get_data(SqlSelect);
        }

