        public DataTable Get_time_table_data_for_mycalander(string sem_code, string year_code, string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "declare @sem_code varchar(1);declare @year_code varchar(5); set @sem_code='" + sem_code + "';set @year_code='" + year_code + "';";

            SqlSelect = SqlSelect + @";with xmlnamespaces('http://schemas.myself.com/someschema' as ns), course_wise_time_table as 
                        (
                        select distinct course_mst.course_code,course_mst.course_name,course_wise_time.from_time,course_wise_time.to_time,course_wise_time.day_code
                        ,'2015-07-24'  as from_date, '2015-12-30' as to_date,course_wise_instructor.instructor_code 
                        from course_mst  inner join course_wise_instructor on course_mst.course_code = course_wise_instructor.course_code  
                        inner join course_wise_time on course_mst.course_code = course_wise_time.course_code 
                        inner join day_mst on course_wise_time.day_code = day_mst.day_code ";

            SqlSelect = SqlSelect + "where course_mst.semester_type = @sem_code and course_mst.year_semester =@year_code " +
                       " and course_wise_time.semester_type = @sem_code and course_wise_time.year_semester =@year_code " +
                       " and course_mst.cancel_flag ='n' and course_mst.ugpgoffice_approved ='y'  " +
                       " and course_wise_instructor.semester_type =  @sem_code and course_wise_instructor.year_semester = @year_code " +
                       " and course_wise_instructor.cancel_flag ='n' and course_wise_instructor.instructor_code in(" + user_id + ") " +
                       " ), " +
                      "  total_allocate_course as " +
                      " ( ";

            SqlSelect = SqlSelect + "select student_course_allocate_dtl.course_code,count(student_course_allocate_dtl.course_code) as  total_allocate,instructor_code as ins_code  from " +
                    " course_wise_instructor inner join student_course_allocate_dtl on course_wise_instructor.course_code = student_course_allocate_dtl.course_code " +
                    " where " +
                    " course_wise_instructor.semester_type =@sem_code and course_wise_instructor.year_semester =@year_code " +
                    " and instructor_code in (" + user_id + ") and course_wise_instructor.cancel_flag ='n' and " +
                    " student_course_allocate_dtl.semester_type =@sem_code and student_course_allocate_dtl.year_semester =@year_code and student_course_allocate_dtl.cancel_flag ='n' " +
                    "  group by student_course_allocate_dtl.course_code,instructor_code " +
                    " ) " +
                    " select * from course_wise_time_table inner join total_allocate_course on course_wise_time_table.course_code = total_allocate_course.course_code     and course_wise_time_table.instructor_code = total_allocate_course.ins_code ";


            //SqlSelect = "select distinct course_mst.course_code,course_mst.course_name,course_wise_time.from_time,course_wise_time.to_time,course_wise_time.day_code,'2015-07-24'  as from_date, '2015-12-30' as to_date,course_wise_instructor.instructor_code from course_mst " +
            //           " inner join course_wise_instructor on course_mst.course_code = course_wise_instructor.course_code " +
            //           " INNER JOIN course_wise_time on course_mst.course_code = course_wise_time.course_code " +
            //           " INNER JOIN day_mst on course_wise_time.day_code = day_mst.day_code     " +
            //           " where course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester ='" + year_code + "' and course_wise_time.semester_type = '" + sem_code + "' and course_wise_time.year_semester ='" + year_code + "' and course_mst.cancel_flag ='N' and course_mst.ugpgoffice_approved ='Y' " +
            //           " and course_wise_instructor.semester_type =  '" + sem_code + "' and course_wise_instructor.year_semester = '" + year_code + "' and course_wise_instructor.cancel_flag ='N' and course_wise_instructor.instructor_code in(" + user_id + ") ";

            return Get_data(SqlSelect);

            //cmd.Parameters.Clear();

            //cmd.Parameters.AddWithValue("@sem_code", sem_code);
            //cmd.Parameters.Add("@year_code", SqlDbType.VarChar).Value = year_code;
