        public DataTable get_instructor_course_data_all_semester(string user_id, string semester_type, string year_semester)
        {
            string spring_year = "";
            string monsoon_year = "";

            if (semester_type == "S")
            {
                spring_year = (Convert.ToInt32(year_semester) - 1).ToString();
                monsoon_year = (Convert.ToInt32(year_semester) - 1).ToString();
            }
            else
            {
                //  spring_year = (Convert.ToInt32(year_semester) - 1).ToString();
                spring_year = year_semester;
                monsoon_year = (Convert.ToInt32(year_semester) - 1).ToString();
            }

            String SqlSelect = "";
            SqlSelect = "select cm.course_name,cm.semester_type +'-' + cm.year_semester as semester_year from course_wise_instructor as cwi inner join course_mst as cm on cwi.course_code = cm.course_code " +
                        " where cwi.cancel_flag ='N' and cm.cancel_flag ='N' and cwi.instructor_code='" + user_id + "' " +
                       "  and ((cwi.semester_type ='S' and cwi.year_semester ='" + spring_year + "') or (cwi.semester_type ='M' and cwi.year_semester ='" + monsoon_year + "')) " +
                       "  and ((cm.semester_type ='S' and cm.year_semester ='" + spring_year + "') or (cm.semester_type ='M' and cm.year_semester ='" + monsoon_year + "'))  order by cm.year_semester desc,cm.semester_type , cm.course_name";
            //order by course_name";

            return Get_data(SqlSelect);
        }

