        public BLReturnObject save_profile_data(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();

            try
            {

                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                server_personal_details = (DS_Personal_Details)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                //To generate next doc number
                //Document Doc = new Document();
                String message = "";

                DS_Personal_Details objpersonaldetails = new DS_Personal_Details();


                objpersonaldetails.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_personal_details.cpop_superviser_mst.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();

                    // string document = server_personal_details.cpop_superviser_mst[mprCnt].doc_no.ToString();
                    //     string strSplitArr = document.Substring(0, 1);
                    objpersonaldetails.cpop_superviser_mst.ImportRow(server_personal_details.cpop_superviser_mst.Rows[mprCnt]);

                    //if (document == "112233")
                    //{
                    //    objpersonaldetails.cpop_superviser_mst.Columns.Remove("doc_no");
                    //}
                }

                objpersonaldetails.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objpersonaldetails.cpop_superviser_mst, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.Update);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objpersonaldetails.cpop_superviser_mst.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

        public DataTable get_instructor_available_personal_details()
        {

            String SqlSelect = "";

            SqlSelect = @"select instructor_mst.user_id,instructor_mst.instructor_name,user_mst.mail
                        ,user_mst.user_type,cpop_superviser_mst.publish_flag,
                        cpop_superviser_mst.designation,cpop_superviser_mst.department,cpop_superviser_mst.public_service
                        from user_mst 
                        inner join instructor_mst on user_mst.user_id = instructor_mst.instructor_code
                        left join cpop_superviser_mst on cpop_superviser_mst.superviser_code = user_mst.user_id
                        where user_status_flag ='A' and user_mst.user_type in ('I2','PC','D') 
                        and instructor_mst.cancel_flag ='N' and instructor_mst.designation != 'VF' 
                        and instructor_mst.designation != 'AA' and  instructor_mst.designation != 'AUVF' 
                        and instructor_mst.user_id not in ('I1617000688','I1617000689','temp_student')
                        ORDER BY (CASE
                        WHEN cpop_superviser_mst.designation IS NULL THEN 1 
                        ELSE 0 
                        END), 
                        cpop_superviser_mst.designation asc";

            return Get_data(SqlSelect);

        }

        public DataTable get_instructor_personal_details(string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @"Select cpop_superviser_mst.*,user_mst.user_id,user_mst.mail,user_mst.user_name from cpop_superviser_mst 
                        inner join user_mst on cpop_superviser_mst.superviser_code = user_mst.user_id
                        where  approval_flag ='Y' and cpop_superviser_mst.cancel_flag ='N' ";
            if (user_id != "")
            {
                SqlSelect = SqlSelect + " and user_mst.user_id ='" + user_id + "' ";
            }

            return Get_data(SqlSelect);
        }

