        public string save_instructor_profile_photo(string user_id, string file_name)
        {
            DBConnection.Open();
            //DBCommand.Transaction = DBConnection.BeginTransaction();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect += " update user_mst set profile_photo='" + file_name + "',last_midified_date='" + DateTime.Now + "' where user_id='" + user_id + "' " +
                            " update cpop_superviser_mst set image_path='" + file_name + "',last_modified_date='" + DateTime.Now + "' where superviser_code='" + user_id + "' ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            try
            {
                int res = DBCommand.ExecuteNonQuery();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                if (res > 0)
                {
                    return "Photo Uploaded Successfully";
                }
                else
                {
                    return "Problem in Upload, Please try again.";
                }
            }
            catch (Exception ex)
            {
                //DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return "Problem in Upload, Please try again." + ex.Message;
            }

            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
        }

