        public DataTable Get_data_Feedback_disable_course(string sem_code, string year_code, string feedback_disable_type)
        {
            String SqlSelect = "";

            if (feedback_disable_type == "FCD")
            {
                SqlSelect = "select  fdc.course_code,fdc.semester_type,fdc.year_semester,fdc.cancel_flag,cm.course_name,dm.dept_name,pm.prog_name from feedback_disable_course as fdc " +
                         "left outer join course_mst as cm on fdc.course_code = cm.course_code  and fdc.semester_type = cm.semester_type and fdc.year_semester = cm.year_semester " +
                         "left outer join department_wise_course_dtl as dw on dw.course_code = cm.course_code and dw.semester_type = fdc.semester_type and dw.year_semester = fdc.year_semester " +
                         "left outer join department_mst as dm on dm.dept_code = dw.dept_code " +
                         "left outer join programme_mst as pm on dw.prog_code = pm.prog_code " +
                         "where fdc.semester_type='" + sem_code + "' and fdc.year_semester='" + year_code + "' order by fdc.course_code desc";
            }
            else
            {
                SqlSelect = "select tfd.course_code,cm.course_name,tfd.user_id,tfd.instructor_code,tfd.cancel_flag from temp_feedback_instructor_disable as tfd " +
                          "left outer join course_mst as cm on cm.course_code = tfd.course_code and tfd.year_semester = cm.year_semester and tfd.semester_type=cm.semester_type " +
                          "where tfd.semester_type='" + sem_code + "' and tfd.year_semester='" + year_code + "'";
            }


            return Get_data(SqlSelect);
        }

