        public DataTable get_all_fees_bank_detail(string semester, string year_code, string dept_code, string prog_code)
        {
            String SqlSelect = "";

            SqlSelect = " select * from (select fees_bank_dtl.dept_code,fees_bank_dtl.prog_code,fees_bank_dtl.account_name,fees_bank_dtl.bank_code,fees_bank_dtl.year, " +
                        " fees_bank_dtl.year_code,fees_bank_dtl.gender,fees_bank_dtl.semester_code,fees_bank_dtl.semester_type,fees_bank_dtl.year_semester, " +
                        " fees_bank_dtl.fees,fees_bank_dtl.start_date,fees_bank_dtl.end_date,fees_bank_dtl.fine,fees_bank_dtl.fine2,department_mst.dept_name,programme_mst.prog_name,fees_bank_dtl.installment1,fees_bank_dtl.installment2,fees_bank_dtl.installment3,fees_bank_dtl.installment4,fees_bank_dtl.end_date2,fees_bank_dtl.end_date3,fees_bank_dtl.nationality from fees_bank_dtl " +
                        " left join department_mst on department_mst.dept_code = fees_bank_dtl.dept_code " +
                        " left join programme_mst on programme_mst.prog_code = fees_bank_dtl.prog_code " +
                        " where fees_bank_dtl.semester_type = '" + semester + "' and fees_bank_dtl.year_semester = '" + year_code + "' ";

            if (dept_code != "") SqlSelect += " and fees_bank_dtl.dept_code='" + dept_code + "' ";

            if (prog_code != "") SqlSelect += " and fees_bank_dtl.prog_code='" + prog_code + "' ";

            SqlSelect += " )res1 " +
                        " PIVOT(MAX(fees) for gender in (M,F))pivot1 " +
                        " ORDER BY dept_code, prog_code, year_code ";

            return Get_data(SqlSelect);
        }

        public DataTable get_fees_bank_dtl(Dictionary<string, object> obj_fees_dtl)
        {
            String SqlSelect = "";

            SqlSelect = " select * from fees_bank_dtl " +
                            " where semester_type = '" + obj_fees_dtl["semester_type"].ToString() + "' and year_semester = '" + obj_fees_dtl["year_semester"].ToString() + "' " +
                            " and dept_code='" + obj_fees_dtl["dept_code"].ToString() + "' and prog_code='" + obj_fees_dtl["prog_code"].ToString() + "' and year_code='" + obj_fees_dtl["year_code"].ToString() + "' ";
            if (obj_fees_dtl["nationality"].ToString() != "")
            {
                SqlSelect += " and nationality ='International'";

            }
            else { SqlSelect += " and nationality is Null "; }

            SqlSelect += " ORDER BY dept_code, prog_code, year_code";

            return Get_data(SqlSelect);
        }

