                obj_fees_installment_upload.EnforceConstraints = false;

                if (server_fees_installment.fees_bank_dtl.Rows[0]["doc_no"].ToString().Contains("new"))
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "FBD", UserID, HostName, ref DocNo, ref message))
