                    {
                        obj_fees_installment_upload.fees_bank_dtl.ImportRow(server_fees_installment.fees_bank_dtl.Rows[mprCnt]);

                        obj_fees_installment_upload.fees_bank_dtl[mprCnt].doc_no = DocNo + (mprCnt + 1).ToString();
                    }
                }
                else
                {
                    for (int mprCnt = 0; mprCnt < server_fees_installment.fees_bank_dtl.Rows.Count; mprCnt++)
                    {
                        obj_fees_installment_upload.fees_bank_dtl.ImportRow(server_fees_installment.fees_bank_dtl.Rows[mprCnt]);
