        public DataTable get_slab_wise_fine_dtl_for_fees(string installment_no, string user_id, string sem_code, string year_code, string student_type)
        {
            String SqlSelect = "";

            SqlSelect = "IF EXISTS(select * from slab_wise_fees_fine_dtl where installment_no='" + installment_no + "' and user_id='" + user_id + "' and cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and student_type = '" + student_type + "') " //and slab_start_date <= GETDATE() and GETDATE() <= slab_end_date 
                        + " BEGIN "
                        + " select * from slab_wise_fees_fine_dtl where installment_no='" + installment_no + "' and user_id= '" + user_id + "' and cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and student_type = '" + student_type + "'" //and slab_start_date <= GETDATE() and GETDATE() <= slab_end_date 
                        + " END "
                    + " ELSE "
                        + " BEGIN "
                        + " select * from slab_wise_fees_fine_dtl where installment_no='" + installment_no + "' and user_id='all' and slab_start_date <= GETDATE() and GETDATE() <= slab_end_date  and cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and student_type = '" + student_type + "'"
                        + " END ";

            return Get_data(SqlSelect);
        }

        public DataTable get_fine_dtl_for_fees(string user_id, string sem_code, string year_code)
        {
            DataTable dt_get_user_type = get_student_dtl(user_id);
            String SqlSelect = "";

            SqlSelect = @"select fees_bank_dtl.*,user_mst.* from user_mst
                        inner join fees_bank_dtl on fees_bank_dtl.dept_code = user_mst.dept_code 
						            and fees_bank_dtl.prog_code = user_mst.prog_code 
						            and fees_bank_dtl.gender = user_mst.gender 
						            and fees_bank_dtl.year_code = user_mst.year_code
                        where user_id='" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' ";

            if (dt_get_user_type != null)
            {
                if (dt_get_user_type.Rows[0]["nationality"].ToString().ToLower() != "i" && dt_get_user_type.Rows[0]["nationality"].ToString().ToLower() != "india" && dt_get_user_type.Rows[0]["nationality"].ToString() != string.Empty)
                {
                    if (sem_code == "M" && year_code == "2023")
                    {
                        SqlSelect += " and fees_bank_dtl.nationality ='International'";
                    }
                    else if (Convert.ToInt32(year_code) > Convert.ToInt32("2023"))
                    {
                        SqlSelect += " and fees_bank_dtl.nationality ='International'";

                    }
                }
                else
                {
                    SqlSelect += " and fees_bank_dtl.nationality is Null ";
                }
            }
            else
            {
                SqlSelect += " and fees_bank_dtl.nationality is Null ";
            }



            return Get_data(SqlSelect);
        }

