        public Boolean save_user_wise_fees_dtl(string user_id, string sem_code, string year_code, int installment_no, decimal fine_amount, string payment_type)
        {
            String SqlSelect = "";
            int res = 0;

            SqlSelect = "insert into user_fees_fine_dtl(user_id, installment_no, installment_fine, request_status, remarks, paid_installment_fine, remains_fine_amount, payslip_generated_date, is_admin, cancel_flag, semester_type, year_semester, created_by, created_date, created_host, last_modified_by, last_modified_date, last_modified_host, is_paid_installment_fine, is_remains_fine_amount_paid)" +
                        " Values('" + user_id + "'" +
                        " ,'" + installment_no + "'" +
                        " ,'" + fine_amount + "'" +
                        " ,'A'";
            //, is_paid_installment_fine, is_remains_fine_amount_paid
            if (payment_type == "OFF")
            {
                SqlSelect = SqlSelect + " ,NULL" +
                                        " ,0" +
                                        " ,'" + fine_amount + "'" +
                                        " ,NULL";
            }
            else
            {
                SqlSelect = SqlSelect + " ,NULL" +
                                        " ,NULL" +
                                        " ,NULL";
            }

            if (payment_type == "Online")
            {
                SqlSelect = SqlSelect + " ,NULL";
            }
            else if (payment_type == "Offline")
            {
                SqlSelect = SqlSelect + " ,'" + DateTime.Now + "'";
            }

            SqlSelect = SqlSelect + " ,'N'" +
                        " ,'N'" +
                        " ,'" + sem_code + "'" +
                        " ,'" + year_code + "'" +
                        " ,'" + user_id + "'" +
                        " ,'" + DateTime.Now + "'" +
                        " ,'" + HttpContext.Current.Request.UserHostName + "'" +
                        " ,NULL" +
                        " ,NULL" +
                        " ,NULL,'N','N')";

            //,'N','N'

            DBCommand.CommandText = SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();

                res = DBCommand.ExecuteNonQuery();

                DBConnection.Close();
                if (res > 0)
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }
            catch (Exception ex)
            {
                return false;
            }
        }

