        public DataTable get_carry_frwd_credits(string user_id, string sem_code, string year_code)
        {
            int cur_carry = 0;
            string prev_sem_code = "", prev_year_code = "", ws_prev_sem_code = "", ws_prev_year_code = "";

            if (sem_code == "M")
            {
                prev_sem_code = "S"; prev_year_code = year_code;
                ws_prev_sem_code = "S"; ws_prev_year_code = year_code;
            }
            else if (sem_code == "S")
            {
                prev_sem_code = "M"; prev_year_code = (Int32.Parse(year_code) - 1).ToString();
                ws_prev_sem_code = "W"; ws_prev_year_code = (Int32.Parse(year_code) - 1).ToString();
            }

            String SqlSelect = "";

            DataTable dt_prev_allocated_credits = get_student_allocated_credits_dtl(user_id, prev_sem_code, prev_year_code);

            if (dt_prev_allocated_credits == null)
            {
                SqlSelect = "";

                SqlSelect = @"select res.*,ISNULL(res2.SWS,0)SWS,(res.M+res.E)Total_ME,(res.M+res.E+ISNULL(res2.SWS,0))Total_credits,ISNULL(ufcw.sws_credits,0) as sws_parked_credits 
                                from (select user_id,ISNULL([M],0)M,ISNULL([E],0)E 
                                    from (select user_id,course_type,SUM(CAST(ISNULL(credits,0) as int))credits 
		                                from student_course_allocate_dtl 
		                                where semester_type='" + prev_sem_code + "' and year_semester='" + prev_year_code + "' and cancel_flag='N' and user_id='" + user_id + @"' 
		                                group by user_id,course_type 
	                                )res1 
	                                PIVOT( 
		                                max(credits) for course_type in ([M],[E]) 
	                                )P1 
                                )res 
                                left join (select user_id,SUM(CAST(ISNULL(credits,0) as int))SWS from ws_student_course_allocate_dtl 
	                                where semester_type='" + ws_prev_sem_code + "' and year_semester='" + ws_prev_year_code + "' and cancel_flag='N' and user_id='" + user_id + @"' 
	                                group by user_id 
                                )res2 on res2.user_id=res.user_id ";

                //For Full Fees paid only. For Eligible Dept, Prog and Allocation Year only.

                SqlSelect += @"
                                inner join user_mst as um on um.user_id=res.user_id 
                                inner join user_fees_status as ufs on ufs.user_id=res.user_id and ufs.cancel_flag='N' 
			                                and ufs.semester_type='" + prev_sem_code + "' and ufs.year_semester='" + prev_year_code + @"' and ufs.fees_status='F' 
                                inner join student_credit_selection_limit as scsl on scsl.dept_code=um.dept_code and scsl.prog_code=um.prog_code 
			                                and scsl.year_code=um.year_code and scsl.is_carry_forward_credit='Y' 
                                left join user_fees_choice_bifurcation as ufcw on ufcw.user_id=res.user_id and ufcw.cancel_flag='N' 
			                                and ufcw.semester_type=ufs.semester_type and ufcw.year_semester=ufs.year_semester ";

                DataTable dt_carry_frwd_credits = Get_data(SqlSelect);

                if (dt_carry_frwd_credits != null)
                {
                    int fees_credits = 20;
                    if (Int32.Parse(dt_carry_frwd_credits.Rows[0]["Total_ME"].ToString()) < fees_credits)
                    {
                        int ME_diff = fees_credits - Int32.Parse(dt_carry_frwd_credits.Rows[0]["Total_ME"].ToString());

                        ///////////////////////////////////////////////////////////////////////////////
                        //Apply below logic here and remove current logic given below
                        ///////////////////////////////////////////////////////////////////////////////
                        if (Int32.Parse(dt_carry_frwd_credits.Rows[0]["SWS"].ToString()) > Int32.Parse(dt_carry_frwd_credits.Rows[0]["sws_parked_credits"].ToString()))
                        {
                            if ((ME_diff - Int32.Parse(dt_carry_frwd_credits.Rows[0]["sws_parked_credits"].ToString())) > 0)
                                cur_carry = ME_diff - Int32.Parse(dt_carry_frwd_credits.Rows[0]["sws_parked_credits"].ToString());
                        }
                        else if (Int32.Parse(dt_carry_frwd_credits.Rows[0]["SWS"].ToString()) < ME_diff)
                        {
                            if ((ME_diff - Int32.Parse(dt_carry_frwd_credits.Rows[0]["SWS"].ToString())) > 0)
                                cur_carry = ME_diff - Int32.Parse(dt_carry_frwd_credits.Rows[0]["SWS"].ToString());
                        }

                        //if (Int32.Parse(dt_carry_frwd_credits.Rows[0]["SWS"].ToString()) < ME_diff)
                        //    cur_carry = ME_diff - Int32.Parse(dt_carry_frwd_credits.Rows[0]["SWS"].ToString());
                    }

                    DataTable dt_prev_carry_credits = get_student_allocated_credits_dtl(user_id, sem_code, (Int32.Parse(year_code) - 1).ToString());

                    if (dt_prev_carry_credits != null)
                    {
                        int prev_carry = Int32.Parse(dt_prev_carry_credits.Rows[0]["carry_forwarded_credit"].ToString()) - Int32.Parse(dt_prev_carry_credits.Rows[0]["used_forwarded_credit"].ToString());
                        cur_carry = cur_carry + prev_carry;
                    }

                    DSC_allocated_credits obj_allocated_credits_upload = new DSC_allocated_credits();

                    DSC_allocated_credits.student_allocated_credits_dtlRow row = obj_allocated_credits_upload.student_allocated_credits_dtl.Newstudent_allocated_credits_dtlRow();

                    row.user_id = user_id;
                    row.mandatory_allocated = dt_carry_frwd_credits.Rows[0]["M"].ToString();
                    row.elective_allocated = dt_carry_frwd_credits.Rows[0]["E"].ToString();
                    row.sws_allocated = dt_carry_frwd_credits.Rows[0]["SWS"].ToString();
                    row.carry_forwarded_credit = cur_carry;
                    row.used_forwarded_credit = 0;
                    row.cancel_flag = "N";
                    row.created_by = user_id;
                    row.created_date = DateTime.Now;
                    row.created_host = HttpContext.Current.Request.UserHostName;
                    row.semester_type = prev_sem_code;
                    row.year_semester = prev_year_code;

                    obj_allocated_credits_upload.student_allocated_credits_dtl.Addstudent_allocated_credits_dtlRow(row);

                    BLReturnObject objBLReturnObject = save_allocated_credits_dtl(obj_allocated_credits_upload, "2000", user_id, HttpContext.Current.Request.UserHostName);

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                    else if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        dt_prev_allocated_credits = get_student_allocated_credits_dtl(user_id, prev_sem_code, prev_year_code);
                    }
                }
            }

            return dt_prev_allocated_credits;
        }

        public BLReturnObject save_allocated_credits_dtl(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_allocated_credits obj_allocated_credits_upload = (DSC_allocated_credits)ds_UploadData;

                obj_allocated_credits_upload.EnforceConstraints = false;

                obj_allocated_credits_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_allocated_credits_upload.student_allocated_credits_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_allocated_credits_upload.student_allocated_credits_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = ex.ToString();
            }

            return objBLReturnObject;
        }
