        public DataTable get_user_installment_payslip_data(string user_id, string sem_code, string year_code, string installment_no)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "  select uu.*,um.user_name, case pm.prog_name when 'PG' then programme_level_mst.prog_level_name else  ' Faculty of '+dm.dept_name end as prog_name from  user_installment_payslip_dtl as uu   inner join user_mst as um on uu.user_id = um.user_id  inner join department_mst as dm on um.dept_code = dm.dept_code inner join programme_mst as pm on um.prog_code = pm.prog_code left join programme_level_mst on um.prog_level_code = programme_level_mst.prog_level_code  " +
                      " where  uu.cancel_flag = 'N' and uu.semester_type = '" + sem_code + "' and uu.year_semester ='" + year_code + "' and um.user_status_flag = 'A' and uu.is_admin_approved != 'R' ";

            if (user_id != "")
            {
                SqlSelect = SqlSelect + " and uu.user_id ='" + user_id + "'  ";
            }

            if (installment_no != "")
            {
                SqlSelect = SqlSelect + " and uu.installment_no ='" + installment_no + "'  ";
            }

            return Get_data(SqlSelect);
        }

