                    return objBLReturnObject;
                }

                //DSC_Fees_Installment server_fees_installment = (DSC_Fees_Installment)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";
                String SqlSelect = "";
                bool delete_flag = false;

                //DSC_Fees_Installment obj_fees_installment_upload = new DSC_Fees_Installment();
                DSC_Fees_Installment obj_fees_installment_upload = (DSC_Fees_Installment)ds_UploadData;

                obj_fees_installment_upload.EnforceConstraints = false;

                //for (int mprCnt = 0; mprCnt < server_fees_installment.user_fees_installment_dtl.Rows.Count; mprCnt++)
                //{
                //    obj_fees_installment_upload.user_fees_installment_dtl.ImportRow(server_fees_installment.user_fees_installment_dtl.Rows[mprCnt]);
                //}

                if (obj_fees_installment_upload.user_installment_payslip_dtl.Rows.Count > 0)
                {
                    if (obj_fees_installment_upload.user_installment_payslip_dtl.Rows[0]["is_admin_approved"].ToString() == "R")
                    {
                        // Delete Old Rejected Row
                        SqlSelect = "delete from user_installment_payslip_dtl where user_id='" + UserID + "' and is_admin_approved='R'";
                        DBCommand.CommandText = SqlSelect;
                        DBCommand.CommandType = CommandType.Text;
                        try { DBCommand.ExecuteNonQuery(); }
                        catch (Exception e) { delete_flag = true; }

                        if (delete_flag)
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            objBLReturnObject.ServerMessage = "Fail to Save Data.";
                            return objBLReturnObject;
                        }
                    }
                }

                obj_fees_installment_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_fees_installment_upload.user_fees_installment_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_fees_installment_upload.user_fees_installment_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_fees_installment_upload.user_installment_payslip_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_fees_installment_upload.user_installment_payslip_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = ex.ToString();
            }
            return objBLReturnObject;
        }

        public DataTable get_admin_installment_payslip_dtl(string dept_code, string prog_code, string allocation_year, string sem_code, string year_code, string installment_no)
        {
            String SqlSelect = "";

            SqlSelect = @"select uu.installment_no,um.user_id,um.user_name,um.mail,um.dept_code,um.year_code,uu.uploadpayslippath,uu.mode_of_payment,uu.branch_name,
                            bb.branch,uu.bank_name, uu.dd_no,uu.amount,uu.is_admin_approved,uu.remarks, CONVERT(varchar,uu.date_of_dd,103) as date_of_dd, apt.Citrus_TxGateway, uu.semester_type, uu.year_semester 
                            from user_mst as um
                            inner join user_installment_payslip_dtl as uu on um.user_id = uu.user_id 
                            inner join bank_branch_mst bb on uu.branch_name = bb.sol_id
                            left join applicationpaymenttransaction apt on apt.semester_type = uu.semester_type and apt.year_semester = uu.year_semester 
                            and apt.user_id = uu.user_id and apt.Citrus_TxGateway = 'Yes Bank' and apt.payment_response_code='0' 
                                and apt.cash_collected_by = '" + installment_no + "' where um.user_status_flag = 'A' and um.status ='A' and uu.is_admin_approved != 'R' ";

            SqlSelect = SqlSelect + " and uu.semester_type = '" + sem_code + "' and uu.year_semester = '" + year_code + "' " +
                                    " and um.dept_code = '" + dept_code + "' and uu.installment_no = '" + installment_no + "' ";

            if (allocation_year != "") SqlSelect = SqlSelect + " and  (um.year_code = '" + allocation_year + "')";

            if (prog_code != "") SqlSelect = SqlSelect + " and  (um.prog_code = '" + prog_code + "')";

            return Get_data(SqlSelect);
        }

        public DataTable get_installment_dtl_for_reminder_mail(string sem_code, string year_code, string installment_no, string dept_code, string prog_code)
        {
            String SqlSelect = "";

            SqlSelect = " DECLARE @sem varchar(1);SET @sem='" + sem_code + "'; " +
                        " DECLARE @year varchar(4);SET @year='" + year_code + "'; " +
                        " DECLARE @installment_no varchar(1);SET @installment_no='" + installment_no + "'; ";

            SqlSelect += @"
                            select ufi.*,um.user_name,um.dept_code,um.prog_code,um.mail,res1.*,res2.*,ufs.fees_status
                            from user_fees_installment_dtl as ufi
                            inner join user_mst as um on um.user_id=ufi.user_id and um.status='A' and um.user_status_flag='A' and um.cancel_flag='N' and um.dept_code in (" + dept_code + ") and um.prog_code in (" + prog_code + ")";

            SqlSelect += @"left join (
	                            select user_id,CONVERT(VARCHAR(10),[1],110)online1,CONVERT(VARCHAR(10),[2],110)online2,CONVERT(VARCHAR(10),[3],110)online3 
	                            from (select user_id,cash_collected_by,last_modified_date from applicationpaymenttransaction 
		                            where semester_type=@sem and year_semester=@year and payment_response_code='0'
		                            and cash_collected_by in ('1','2','3')
	                            )res1_1
	                            PIVOT(
		                            MAX(last_modified_date) for cash_collected_by in ([1],[2],[3])
	                            )pivot1
                            )res1 on res1.user_id=ufi.user_id
                            left join (
	                            select user_id,CONVERT(VARCHAR(10),[1],110)offline1,CONVERT(VARCHAR(10),[2],110)offline2,CONVERT(VARCHAR(10),[3],110)offline3 
	                            from (select user_id,installment_no,(case ISNULL(date_of_dd,'') when '' then created_date else date_of_dd end)date_of_dd
		                            from user_installment_payslip_dtl
		                            where semester_type=@sem and year_semester=@year and is_admin_approved='A'
		                            and installment_no in ('1','2','3')
	                            )res2_1
	                            PIVOT(
		                            MAX(date_of_dd) for installment_no in ([1],[2],[3])
	                            )pivot2
                            )res2 on res2.user_id=ufi.user_id
                            left join user_fees_status as ufs on ufs.user_id=ufi.user_id and ufs.cancel_flag='N'
	                            and ufs.semester_type=ufi.semester_type and ufs.year_semester=ufi.year_semester
                            inner join (select distinct user_id from student_course_allocate_dtl
	                            where semester_type=@sem and year_semester=@year and cancel_flag='N'
                            )res3 on res3.user_id=ufi.user_id
                            where ufi.semester_type=@sem and ufi.year_semester=@year and ufi.cancel_flag='N'
                            and ufi.no_of_installment>=@installment_no ";

            if (installment_no == "1") SqlSelect += @" and (ISNULL(ufi.is_installment1_paid,'')!='Y' and ISNULL(ufs.fees_status,'') not in ('F','H')) ";

            if (installment_no == "2") SqlSelect += @" and ((ISNULL(ufi.is_installment1_paid,'')!='Y' and ISNULL(ufs.fees_status,'') not in ('F','H')) 
                                        or (ISNULL(ufi.is_installment1_paid,'')='Y' and ISNULL(ufi.is_installment2_paid,'')!='Y')) ";

            if (installment_no == "3") SqlSelect += @" and ((ISNULL(ufi.is_installment1_paid,'')!='Y' and ISNULL(ufs.fees_status,'') not in ('F','H')) 
                                        or (ISNULL(ufi.is_installment1_paid,'')='Y' and ISNULL(ufi.is_installment2_paid,'')!='Y') 
                                        or (ISNULL(ufi.is_installment1_paid,'')='Y' and ISNULL(ufi.is_installment2_paid,'')='Y' and ISNULL(ufi.is_installment3_paid,'')!='Y')) ";

            SqlSelect += " order by ufi.user_id ";

            return Get_data(SqlSelect);
        }

