                            else if ((text.ToString().Contains(str_course3) || text.ToString().Contains(str_course3.Replace("-", ""))) && text.ToString().Contains(str_instructor3))
                            {
                                lst_Valid.Add(str_course3 + " :: " + str_instructor3);

                                DataRow dr_PDF_status = dt_PDF_status.NewRow();

                                dr_PDF_status["pdf_name"] = pdf_name;
                                dr_PDF_status["pdf_detail"] = str_course3 + " :: " + str_instructor3;
                                dr_PDF_status["status"] = "SUCCESS";

                                dt_PDF_status.Rows.Add(dr_PDF_status);
                            }
                            else if ((text.ToString().Contains(str_course3) || text.ToString().Contains(str_course3.Replace("-", ""))) && text.ToString().Contains(str_AA_instructor3))
                            {
                                lst_Valid.Add(str_course3 + " :: " + str_instructor3);

                                DataRow dr_PDF_status = dt_PDF_status.NewRow();

                                dr_PDF_status["pdf_name"] = pdf_name;
                                dr_PDF_status["pdf_detail"] = str_course3 + " :: " + str_instructor3;
                                dr_PDF_status["status"] = "SUCCESS";

                                dt_PDF_status.Rows.Add(dr_PDF_status);
                            }
                            else if ((text.ToString().Contains(str_course3) || text.ToString().Contains(str_course3.Replace("-", ""))) && text.ToString().Contains(str_TA_instructor3))
                            {
                                lst_Valid.Add(str_course3 + " :: " + str_instructor3);

                                DataRow dr_PDF_status = dt_PDF_status.NewRow();

                                dr_PDF_status["pdf_name"] = pdf_name;
                                dr_PDF_status["pdf_detail"] = str_course3 + " :: " + str_instructor3;
                                dr_PDF_status["status"] = "SUCCESS";

                                dt_PDF_status.Rows.Add(dr_PDF_status);
                            }
                            else
                            {
                                lst_Invalid.Add(str_course3 + " :: " + str_instructor3);

                                DataRow dr_PDF_status = dt_PDF_status.NewRow();

                                dr_PDF_status["pdf_name"] = pdf_name;
                                dr_PDF_status["pdf_detail"] = str_course3 + " :: " + str_instructor3;
                                dr_PDF_status["status"] = "FAIL";

                                dt_PDF_status.Rows.Add(dr_PDF_status);
                            }

                            reader.Close();
                            //}
                        }
                        else
                        {
                            pdf_status = false;
                        }
                    }
                    else
                    {
                        pdf_status = false;
                    }

                    if (!pdf_status)
                    {
                        string pdf_name = file_info.Name;

                        DataRow[] dr = dt_pdf_name.Select("pdf_name = '" + pdf_name + "'");

                        if (dr.Length > 0)
                        {
                            string str_course = "COURSE" + (char)160 + "CODE" + (char)160 + ":" + (char)160 + dr[0]["course_code"].ToString().Trim();
                            string str_instructor = "INSTRUCTOR" + (char)160 + "NAME:" + (char)160 + dr[0]["instructor_name"].ToString().Trim();

                            lst_Invalid.Add(str_course + " :: " + str_instructor);

                            DataRow dr_PDF_status = dt_PDF_status.NewRow();

                            dr_PDF_status["pdf_name"] = pdf_name;
                            dr_PDF_status["pdf_detail"] = str_course + " :: " + str_instructor;
                            dr_PDF_status["status"] = "FAIL";

                            dt_PDF_status.Rows.Add(dr_PDF_status);
                        }
                        else
                        {
                            lst_Invalid.Add(pdf_name);

                            DataRow dr_PDF_status = dt_PDF_status.NewRow();

                            dr_PDF_status["pdf_name"] = pdf_name;
                            dr_PDF_status["pdf_detail"] = "";
                            dr_PDF_status["status"] = "FAIL";

                            dt_PDF_status.Rows.Add(dr_PDF_status);
                        }

                        pdf_status = true;
                    }
                }

                List<string> filenames_success = new List<string>();
                List<string> filenames_fail = new List<string>();

                for (int i = 0; i < dt_PDF_status.Rows.Count; i++)
                {
                    if (dt_PDF_status.Rows[i]["status"].ToString() == "SUCCESS")
                    {
                        filenames_success.Add(directory_path + dt_PDF_status.Rows[i]["pdf_name"].ToString());

                        if (File.Exists(directory_path + dt_PDF_status.Rows[i]["pdf_name"].ToString()))
                        {
                            File.Copy(directory_path + dt_PDF_status.Rows[i]["pdf_name"].ToString(), feedback_PDF_path + dt_PDF_status.Rows[i]["pdf_name"].ToString(), true);
                        }
                    }
                    else if (dt_PDF_status.Rows[i]["status"].ToString() == "FAIL")
                    {
                        filenames_fail.Add(directory_path + dt_PDF_status.Rows[i]["pdf_name"].ToString());
                    }
                }

                using (ZipFile zip = new ZipFile())
                {
                    zip.AddFiles(filenames, dept_name + "_All");
                    zip.Save(directory_path + dept_name + "_All.zip");
                }

                using (ZipFile zip = new ZipFile())
                {
                    zip.AddFiles(filenames_success.ToArray(), dept_name + "_Success");
                    zip.Save(directory_path + dept_name + "_Success.zip");
                }

                using (ZipFile zip = new ZipFile())
                {
                    zip.AddFiles(filenames_fail.ToArray(), dept_name + "_Fail");
                    zip.Save(directory_path + dept_name + "_Fail.zip");
                }
            }
            catch (Exception ex)
            {
                DataRow dr = dt_PDF_status.NewRow();

                dr["pdf_name"] = "";
                dr["pdf_detail"] = ex.ToString();
                dr["status"] = "FAIL";

                dt_PDF_status.Rows.Add(dr);
            }
        }

