        public DataTable get_studio_course_data_for_group_entry(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select distinct course_mst.course_code,course_mst.course_name,department_wise_course_dtl.course_typology,department_wise_course_dtl.dept_code,department_wise_course_dtl.prog_code,department_wise_course_dtl.prog_level_code from course_mst " +
                        " inner join department_wise_course_dtl on course_mst.course_code = department_wise_course_dtl.course_code " +
                        " inner join student_course_allocate_dtl on course_mst.course_code = student_course_allocate_dtl.course_code " +
                        " where course_mst.semester_type ='" + sem_code + "' " +
                        " and course_mst.year_semester ='" + year_code + "'  " +
                        " and department_wise_course_dtl.semester_type ='" + sem_code + "'  " +
                        " and department_wise_course_dtl.year_semester ='" + year_code + "'" +
                        " and student_course_allocate_dtl.semester_type ='" + sem_code + "' " +
                        " and student_course_allocate_dtl.year_semester ='" + year_code + "' " +
                        // " and department_wise_course_dtl.course_typology in ('7','14') ";
                        " and course_mst.project ='Y' ";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code ='" + dept_code + "' ";
            }
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code ='" + prog_code + "' ";
            }
            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code ='" + prog_level_code + "' ";
            }

            // long A = GC.GetTotalMemory(true);
            return Get_data(SqlSelect);
        }

