        public BLReturnObject Save_course_studio_wise_group_data(DataSet ds_UploadData, String UserID, String current_sem_code, String HostName, string course_code, string sem_code, string year_code, string sub_studio)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                server_course_group = (DSC_Course_Group)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                //To generate next doc number
                Document Doc = new Document();
                String message = "";
                String DocNo = "";
                String DocNo1 = "";
                //Ds_Workflow obj_workflow = new Ds_Workflow();
                DSC_Course_Group obj_student_course = new DSC_Course_Group();

                obj_student_course.EnforceConstraints = false;
                //objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "VD", sessionInfo.GetUserID(), sessionInfo.GetHostID(), ref DocNo, ref message);

                for (int mprCnt = 0; mprCnt < server_course_group.course_group_details.Rows.Count; mprCnt++)
                {
                    obj_student_course.course_group_details.ImportRow(server_course_group.course_group_details.Rows[mprCnt]);
                }

                for (int mprCnt = 0; mprCnt < server_course_group.course_group_instructor_details.Rows.Count; mprCnt++)
                {
                    obj_student_course.course_group_instructor_details.ImportRow(server_course_group.course_group_instructor_details.Rows[mprCnt]);
                }

                for (int mprCnt = 0; mprCnt < server_course_group.student_course_group_details.Rows.Count; mprCnt++)
                {
                    obj_student_course.student_course_group_details.ImportRow(server_course_group.student_course_group_details.Rows[mprCnt]);
                }

                Boolean flag;
                obj_student_course.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                flag = delete_course_group(course_code, sem_code, year_code, sub_studio, "Y");

                if (flag == false)
                {
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                flag = delete_instructor_group_data(course_code, sem_code, year_code, sub_studio, "Y");

                if (flag == false)
                {
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                flag = delete_student_course_group(course_code, sem_code, year_code, sub_studio, "Y");

                if (flag == false)
                {
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_student_course.course_group_details, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_student_course.course_group_details.Rows.Count)
                {

                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_student_course.course_group_instructor_details, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_student_course.course_group_instructor_details.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_student_course.student_course_group_details, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_student_course.student_course_group_details.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {

            }

            return objBLReturnObject;
        }

