        public DataTable Get_project_training(string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @"  select project_training.*,user_mst.user_name, CONVERT(varchar, Project_training.project_start_date, 103)
                      AS project_start_date1, CONVERT(varchar, Project_training.project_complate_date_contract, 103) AS project_complate_date_contract1, 
                      CONVERT(varchar, Project_training.project_complate_date_status, 103) AS project_complate_date_status1
                
                      FROM         Project_training INNER JOIN
                      user_mst ON Project_training.user_id = user_mst.user_id
                      WHERE     (Project_training.user_id = '" + user_id + "') AND (Project_training.semester_type = '" + sem_code + "') AND (Project_training.year_semester = '" + year_code + "') AND " +
                      "(Project_training.cancel_flag = 'N')";

            return Get_data(SqlSelect);
        }

        public DataTable Get_praposal_data_for_pdf(string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @" SELECT     Project_training.user_id, Project_training.project_site_name, Project_training.project_Category, Project_training.project_category_other, 
                      Project_training.project_objective, Project_training.location, Project_training.client_name, Project_training.principle_consultant, Project_training.architech, 
                      Project_training.structural_consultant, Project_training.project_managment_consultant, Project_training.mep_consultant, Project_training.proof_consultant, 
                      Project_training.traffic_consultant, Project_training.contractor, Project_training.main_subcontractor, Project_training.scope_work, Project_training.cost_work_pakage, 
                      Project_training.physical_aspect_project, Project_training.project_start_date, Project_training.project_complate_date_contract, Project_training.project_current_status, 
                      Project_training.project_complate_date_status, Project_training.project_activity, Project_training.consult_participation, Project_training.state_response, 
                      Project_training.conform_email, Project_training.cancel_flag, Project_training.is_submit, Project_training.project_training_under, Project_training.email_letter, 
                      Project_training.train_stud_activity, Project_training.train_stud_name, Project_training.is_approved, Project_training.semester_type, Project_training.year_semester, 
                      Project_training.file_path, Project_training.created_by, Project_training.created_date, Project_training.created_host, Project_training.last_modified_by, 
                      Project_training.last_modified_date, Project_training.last_modified_host, user_mst.user_name, CONVERT(varchar, Project_training.project_start_date, 103) 
                      AS project_start_date1, CONVERT(varchar, Project_training.project_complate_date_contract, 103) AS project_complate_date_contract1, CONVERT(varchar, 
                      Project_training.project_complate_date_status, 103) AS project_complate_date_status1, project_project_category_mst.code, project_project_category_mst.name
                        FROM         Project_training INNER JOIN
                      user_mst ON Project_training.user_id = user_mst.user_id INNER JOIN
                      project_project_category_mst ON Project_training.project_Category = project_project_category_mst.code
                      WHERE     (Project_training.user_id = '" + user_id + "') AND (Project_training.semester_type = '" + sem_code + "') AND (Project_training.year_semester = '" + year_code + "') AND (Project_training.cancel_flag = 'N')";

            return Get_data(SqlSelect);
        }

        public DataTable Get_project_training_for_accept(string sem_code, string year_code, string instructor_code, string course_code)
        {
            String SqlSelect = "";

            SqlSelect = @"SELECT     student_course_allocate_dtl.user_id, LOWER(user_mst.user_name) AS user_name, 
			              CASE Project_training.is_submit WHEN 'Y' THEN 'Yes' WHEN 'N' THEN 'No' ELSE 'NA' END AS PT_submit, 
			              CASE Project_training.is_approved WHEN 'R' THEN 'Rejected' WHEN 'Y' THEN 'Accepted' ELSE 'NA' END AS is_approved, 
			              CASE project_site_join_report.is_submit WHEN 'Y' THEN 'Yes' WHEN 'N' THEN 'No' ELSE 'NA' END AS SJR_submit, 
			              CASE WHEN pro_paln.user_id != '' THEN pro_paln.user_id ELSE 'NA' END AS user_id_for_planned, 
			              CASE WHEN pro_actual.user_id != '' THEN pro_actual.user_id ELSE 'NA' END AS user_id_for_actual, 
			              CASE WHEN pro_actual.user_id != '' AND pro_paln.user_id != '' THEN pro_actual.user_id ELSE 'NA' END AS user_id_for_actual_vs_planned, 
			              user_mst.mail, 
			              CASE WHEN pro_car.user_id != '' THEN pro_car.user_id ELSE 'NA' END AS user_id_for_car, 
			              CASE WHEN proj_weekly_timesheet.user_id != '' THEN proj_weekly_timesheet.user_id ELSE 'NA' END AS user_id_for_weekly_timesheet,
			              CASE WHEN pro_psr.user_id != '' THEN pro_psr.user_id ELSE 'NA' END AS pro_psr,
			              CASE WHEN pro_final_report.user_id != '' THEN pro_final_report.user_id ELSE 'NA' END AS pro_final_report
                        FROM         student_course_allocate_dtl LEFT OUTER JOIN
				        Project_training ON student_course_allocate_dtl.user_id = Project_training.user_id AND Project_training.semester_type = Project_training.semester_type AND 
				        Project_training.year_semester = Project_training.year_semester LEFT OUTER JOIN
				        (SELECT DISTINCT user_id
				        FROM project_planned"

                    + " WHERE      (semester_type = '" + sem_code + "') AND (year_semester =  '" + year_code + "')) AS pro_paln ON pro_paln.user_id = student_course_allocate_dtl.user_id LEFT OUTER JOIN "
                    + " (SELECT DISTINCT user_id "
                    + " FROM          project_actual "
                    + " WHERE      (semester_type = '" + sem_code + "') AND (year_semester =  '" + year_code + "')) AS pro_actual ON pro_actual.user_id = student_course_allocate_dtl.user_id LEFT OUTER JOIN "
                    + " (SELECT DISTINCT user_id "
                    + " FROM          project_car_upload "
                    + " WHERE      (semester_type = '" + sem_code + "') AND (year_semester =  '" + year_code + "')) AS pro_car ON pro_car.user_id = student_course_allocate_dtl.user_id LEFT OUTER JOIN "
                    + " (SELECT DISTINCT user_id "
                    + " FROM          psr "
                    + " WHERE      (semester_type = '" + sem_code + "') AND (year_semester =  '" + year_code + "')) AS pro_psr ON pro_psr.user_id = student_course_allocate_dtl.user_id LEFT OUTER JOIN "
                    + " (SELECT DISTINCT user_id "
                    + " FROM          project_final_report_upload "
                    + " WHERE      (semester_type = '" + sem_code + "') AND (year_semester =  '" + year_code + "')) AS pro_final_report ON pro_final_report.user_id = student_course_allocate_dtl.user_id LEFT OUTER JOIN                             "
                    + " (SELECT DISTINCT user_id "
                    + " FROM          project_week_time_sheet_upload "
                    + " WHERE      (semester_type = '" + sem_code + "') AND (year_semester =  '" + year_code + "')) AS proj_weekly_timesheet ON  "
                    + " proj_weekly_timesheet.user_id = student_course_allocate_dtl.user_id LEFT OUTER JOIN "
                    + " user_mst ON student_course_allocate_dtl.user_id = user_mst.user_id LEFT OUTER JOIN "
                    + " project_site_join_report ON student_course_allocate_dtl.user_id = project_site_join_report.user_id AND  "
                    + " student_course_allocate_dtl.semester_type = project_site_join_report.semester_type AND  "
                    + " student_course_allocate_dtl.year_semester = project_site_join_report.year_semester "
                    + " WHERE     (student_course_allocate_dtl.semester_type = '" + sem_code + "') AND (student_course_allocate_dtl.year_semester =  '" + year_code + "') AND (user_mst.user_status_flag = 'A') AND  "
                    + " (student_course_allocate_dtl.cancel_flag = 'N') AND (student_course_allocate_dtl.course_code = '" + course_code + "') "
                    + " ORDER BY student_course_allocate_dtl.user_id";

            return Get_data(SqlSelect);
        }

