        public DataTable Get_site_join_report(string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @"SELECT     Project_training.user_id AS Expr1, CONVERT(varchar, Project_training.project_start_date, 103) AS date_of_join_project_proposal, project_site_join_report.user_id, 
                      Project_training.project_site_name, Project_training.project_objective, CONVERT(varchar, project_site_join_report.date_of_join, 103) AS date_of_join_sjr, 
                      project_site_join_report.name_of_org_join, project_site_join_report.project_name, project_site_join_report.plan_entry_deadline, project_site_join_report.reporting_to, 
                      project_site_join_report.address_from_communication, project_site_join_report.site_address, project_site_join_report.site_email, 
                      project_site_join_report.site_mobile, project_site_join_report.landline, project_site_join_report.stud_mobile, project_site_join_report.communication_add_stud, 
                      project_site_join_report.from_working_hour, project_site_join_report.to_working_hour, project_site_join_report.to_lunch_hour, 
                      project_site_join_report.from_lunch_hour, project_site_join_report.remark, project_site_join_report.cancel_flag, project_site_join_report.is_submit, 
                      project_site_join_report.file_path, project_site_join_report.semester_type, project_site_join_report.year_semester, project_site_join_report.state_site, 
                      project_site_join_report.city_site, project_site_join_report.state_student, project_site_join_report.city_student, 
                      (CASE Project_training.project_training_under WHEN 'Client' THEN Project_training.client_name WHEN 'Consultant' THEN Project_training.principle_consultant WHEN 'contractors'
                       THEN Project_training.contractor ELSE '' END) AS reporting_to, Project_training.location, Project_training.client_name, user_mst.user_name, user_mst.mail
FROM         Project_training INNER JOIN
                      user_mst ON Project_training.user_id = user_mst.user_id LEFT OUTER JOIN
                      project_site_join_report ON Project_training.user_id = project_site_join_report.user_id AND 
                      Project_training.semester_type = project_site_join_report.semester_type AND Project_training.year_semester = project_site_join_report.year_semester
                    WHERE     (Project_training.user_id = '" + user_id + "') AND (Project_training.semester_type = '" + sem_code + "') AND (Project_training.year_semester = '" + year_code + "')";

            return Get_data(SqlSelect);
        }

