        public DataTable Get_student_details(string course_code, string semester_type, string year_semester)
        {
            String SqlSelect = "";

            //SqlSelect = @"SELECT student_course_allocate_dtl.user_id, user_mst.user_name, student_course_allocate_dtl.year_code, 
            //            user_mst.dept_code, user_mst.prog_code, 
            //            student_course_allocate_dtl.course_code, student_course_allocate_dtl.course_type, 
            //            student_course_allocate_dtl.semester_type, student_course_allocate_dtl.year_semester
            //            FROM student_course_allocate_dtl 
            //            INNER JOIN user_mst ON student_course_allocate_dtl.user_id = user_mst.user_id"+
            //            " WHERE (student_course_allocate_dtl.course_code = '" + course_code + "') AND (student_course_allocate_dtl.semester_type = '" + semester_type + "') " +
            //            "AND (student_course_allocate_dtl.year_semester = '"+year_semester+"') "+
            //            "AND (student_course_allocate_dtl.cancel_flag = 'N')";

            SqlSelect = @"SELECT     student_course_allocate_dtl.user_id, user_mst.user_name, student_course_allocate_dtl.year_code, user_mst.dept_code, user_mst.prog_code, 
                      student_course_allocate_dtl.course_code, student_course_allocate_dtl.course_type, student_course_allocate_dtl.semester_type, 
                      student_course_allocate_dtl.year_semester,pmt.user_id as pmt_user_id,pmt.instructor_code as pmt_instructor_code
                      FROM student_course_allocate_dtl INNER JOIN
                      user_mst ON student_course_allocate_dtl.user_id = user_mst.user_id 
                      LEFT OUTER JOIN(
                      select * from project_mapping_stud_instructor where 
                        project_mapping_stud_instructor.cancel_flag ='N'
                        and project_mapping_stud_instructor.semester_type ='M'
                        and project_mapping_stud_instructor.year_semester ='2015'
                        and project_mapping_stud_instructor.course_code = '5083'
                      ) as pmt ON 
                      student_course_allocate_dtl.course_code COLLATE SQL_Latin1_General_CP1_CI_AS = pmt.course_code AND 
                      student_course_allocate_dtl.user_id COLLATE SQL_Latin1_General_CP1_CI_AS = pmt.user_id " +
                    "WHERE (student_course_allocate_dtl.course_code = '" + course_code + "') AND (student_course_allocate_dtl.semester_type ='" + semester_type + "') " +
                     " AND (student_course_allocate_dtl.year_semester = '" + year_semester + "') AND (student_course_allocate_dtl.cancel_flag = 'N')";

            return Get_data(SqlSelect);
        }

