        public Boolean accept_reject_proposal(string user_id, string flag)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            string SqlSelect = "";

            if (flag == "A")
            {
                flag = "Y";

                SqlSelect = @"UPDATE Project_training SET is_approved = '" + flag + "' WHERE (user_id = '" + user_id + "')";
            }
            else if (flag == "R")
            {
                flag = "R";

                SqlSelect = @"UPDATE Project_training SET is_approved = '" + flag + "' , is_submit='N'  WHERE (user_id = '" + user_id + "')";
            }

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception)
            {
                DBConnection.Close();

                return false;
            }
        }

