        public DataTable get_psr_fcr_report(string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = @"SELECT ROW_NUMBER() OVER (order by Project_training.user_id) AS row,Project_training.user_id,user_mst.user_name,
					project_site_join_report.project_name,PSR.comment as psr_comment,project_final_report_upload.comment as fcr_comment
					FROM Project_training
					LEFT OUTER JOIN user_mst ON Project_training.user_id = user_mst.user_id
					LEFT OUTER JOIN project_site_join_report ON Project_training.user_id = project_site_join_report.user_id
					LEFT OUTER JOIN PSR ON Project_training.user_id = PSR.user_id
					LEFT OUTER JOIN project_final_report_upload ON Project_training.user_id = project_final_report_upload.user_id
					WHERE Project_training.semester_type='" + sem_code + "'  AND Project_training.year_semester='" + year_code + "'";

            return Get_data(SqlSelect);
        }

