        public BLReturnObject save_alumini_registration_data(DataSet ds_UploadData, string compnyid, String UserID, String HostName, string other_prog)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Alumini_Registration server_alumini = (DSC_Alumini_Registration)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_Alumini_Registration objAlumini_upload = new DSC_Alumini_Registration();

                objAlumini_upload.EnforceConstraints = false;

                String SqlSelect = "";

                for (int mprCnt = 0; mprCnt < server_alumini.alumini_registration_mst.Rows.Count; mprCnt++)
                {
                    if (server_alumini.alumini_registration_mst.Rows[mprCnt]["prog_level_code"].ToString() == "O")
                    {
                        SqlSelect = @" insert into alumini_programme_level_mst(doc_no, prog_level_code, prog_level_desc, prog_level_name, cancel_flag, dept_code, prog_code)
                                values((select (COUNT(prog_level_code) + 1)as total from alumini_programme_level_mst),
                                'O'+(select CAST(COUNT(prog_level_code) + 1 as varchar)as total from alumini_programme_level_mst),'','" +
                              other_prog + "','N','','')";


                        DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                        int res_insert = DBCommand.ExecuteNonQuery();

                        if (res_insert <= 0)
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            objBLReturnObject.ServerMessage = "Fail to Save Details.";
                            return objBLReturnObject;
                        }

                        SqlSelect = "select CAST(COUNT(prog_level_code) as varchar)as total from alumini_programme_level_mst";

                        DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                        int prog_code = Convert.ToInt32(DBCommand.ExecuteScalar().ToString());

                        if (res_insert <= 0)
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            objBLReturnObject.ServerMessage = "Fail to Save Details.";
                            return objBLReturnObject;
                        }

                        server_alumini.alumini_registration_mst.Rows[mprCnt]["prog_level_code"] = "O" + prog_code;
                    }



                    objAlumini_upload.alumini_registration_mst.ImportRow(server_alumini.alumini_registration_mst.Rows[mprCnt]);

                }

                objAlumini_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objAlumini_upload.alumini_registration_mst, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objAlumini_upload.alumini_registration_mst.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

