        public DataTable get_alumni_data_for_report(string year_code, string dept_code, string prog_code, string reg_by, string id_card_req, string ver_status)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //            SqlSelect = @"select ALR.*,alumini_programme_level_mst.prog_level_name,alumini_year_mst.year_desc
            //                        ,convert(varchar(10),ALR.dob,103) as date_of_birth,alumini_programme_level_mst.dept_code,alumini_programme_level_mst.prog_code 
            //                        ,a.name as workcountry,b.name as homecountry,case when c.state_name is null then ALR.work_state else c.state_name end as workstate,
            //                        case when d.state_name is null then ALR.home_state else d.state_name end as homestate
            //                        from alumini_registration_mst  as ALR
            //                        inner join alumini_programme_level_mst on ALR.prog_level_code = alumini_programme_level_mst.prog_level_code
            //                        inner join alumini_year_mst on ALR.year_code = alumini_year_mst.year_code
            //                        left join country_mst as a on ALR.work_country = a.id
            //                        left join country_mst as b on ALR.home_country = b.id
            //					     left join state_mst as c on ALR.work_state = c.state_code
            //                        left join state_mst as d on ALR.home_state = d.state_code
            //                         where ALR.cancel_flag ='N' and is_verified= 'Y'";

            SqlSelect = @"select * from
                         ( select (case ISNULL(ALR.last_modified_date,'') when '' then ALR.created_date else ALR.last_modified_date end)sort_date, ALR.*,alumini_programme_level_mst.prog_level_name,alumini_year_mst.year_desc
                        ,convert(varchar(10),ALR.dob,103) as date_of_birth,alumini_programme_level_mst.dept_code,alumini_programme_level_mst.prog_code 
                        ,a.name as workcountry,b.name as homecountry,case when c.state_name is null then ALR.work_state else c.state_name end as workstate,
                        case when d.state_name is null then ALR.home_state else d.state_name end as homestate
                        from alumini_registration_mst  as ALR
                        left join alumini_programme_level_mst on ALR.prog_level_code = alumini_programme_level_mst.prog_level_code
                        left join alumini_year_mst on ALR.year_code = alumini_year_mst.year_code
                        left join country_mst as a on ALR.work_country = a.id
                        left join country_mst as b on ALR.home_country = b.id
					    left join state_mst as c on ALR.work_state = c.state_code
                        left join state_mst as d on ALR.home_state = d.state_code
                         where ALR.cancel_flag ='N' ";


            if (year_code != null && year_code != "")
            {
                SqlSelect += "and alumini_year_mst.year_code='" + year_code + "' ";
            }
            if (dept_code != null && dept_code != "")
            {
                SqlSelect += "and alumini_programme_level_mst.dept_code='" + dept_code + "' ";
            }

            if (prog_code != null && prog_code != "")
            {
                SqlSelect += "and alumini_programme_level_mst.prog_code='" + prog_code + "' ";
            }
            if (reg_by != null && reg_by != "")
            {
                SqlSelect += "and alumini_programme_level_mst. is_registr='" + reg_by + "' ";
            }
            if (id_card_req != null && id_card_req != "")
            {
                if (id_card_req == "Y")
                {
                    SqlSelect += "and ALR.is_id_card in('Y') ";
                }
                else
                {
                    SqlSelect += "and ALR.is_id_card    in  ('N') or   ALR.is_id_card is null ";
                }
            }
            if (ver_status != null && ver_status != "")
            {
                if (ver_status == "Y")
                {
                    SqlSelect += "and  ALR.is_verified    in  ('Y')  ";
                }
                else
                {
                    SqlSelect += "and ALR.is_verified    in  ('N') or   ALR.is_verified is null ";
                }
            }

            SqlSelect += " )res order by sort_date desc";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }


