        public BLReturnObject update_alumini_verify_user(Dictionary<string, object> verify_data, String host_name, string UserID)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";

                try
                {
                    SqlSelect = "update alumini_registration_mst set user_id = '" + verify_data["user_id"].ToString() + "', is_verified = 'Y' , last_modified_by = '" + UserID + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where mail = '" + verify_data["email"].ToString() + "' ";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    int res_insert = DBCommand.ExecuteNonQuery();

                    if (res_insert <= 0)
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        objBLReturnObject.ServerMessage = "Problem in verification details.Please try again";
                        return objBLReturnObject;
                    }

                    DBDataAdpterObject.SelectCommand.Parameters.Clear();
                    SqlSelect = "";

                    SqlSelect = "select * from user_mst where user_id ='" + verify_data["user_id"].ToString() + "'";
                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    DataSet ds = new DataSet();
                    try
                    {
                        DBDataAdpterObject.Fill(ds);

                        string birthdate = verify_data["dob"].ToString().Trim();
                        String expiry2 = "";
                        if (birthdate.ToString().Trim() != "")
                        {
                            String dst21 = birthdate.ToString();

                            string[] sdg21 = dst21.ToString().Split('/');
                            string gh21 = sdg21[2].ToString() + "/" + sdg21[1].ToString() + "/" + sdg21[0].ToString();

                            DateTime expiryto = Convert.ToDateTime(gh21);
                            expiry2 = expiryto.ToString();
                        }

                        if (ds.Tables[0].Rows.Count <= 0)
                        {
                            DBDataAdpterObject.SelectCommand.Parameters.Clear();

                            SqlSelect = "";

                            SqlSelect = "insert into user_mst(doc_no,user_id,user_name,user_type,student_no,mail,dob,year_code,prog_level_code,dept_code,prog_code,start_date,pass_expiry_date,user_status_flag,cancel_flag,created_by,created_date,created_host,status) " +
                                         " VALUES('" + verify_data["user_id"].ToString() + "' , '" + verify_data["user_id"].ToString() + "', " +
                                         " '" + verify_data["user_name"].ToString() + "','S' ,'" + verify_data["user_id"].ToString() + "'," +
                                         "'" + verify_data["email"].ToString() + "' ,'" + Convert.ToDateTime(expiry2) + "' ,'" + verify_data["year_code"].ToString() + "','" + verify_data["prog_level_code"].ToString() + "' ," +
                                         "'" + verify_data["dept_code"].ToString() + "' ,'" + verify_data["prog_code"].ToString() + "'," +
                                         "'" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'  ," +
                                         "'" + DateTime.Now.AddYears(10).ToString("yyyy/MM/dd HH:mm:ss") + "' ,'A','N','" + UserID + "'," +
                                         " '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + host_name + "' ,'A')";

                            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                            int res_insert1 = DBCommand.ExecuteNonQuery();

                            if (res_insert1 <= 0)
                            {
                                DBCommand.Transaction.Rollback();
                                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
