        public DataTable Get_serach_data(string keyword, string city)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"  with ct as(
                        select  count(job_id)as count_job,job_id from alumni_job_visit_log  where job_id is not null and job_id <> ''
                        group by (job_id)
                        )
                        select  Doc_no,job_title,city,state,experience,organization,convert(varchar(10), due_date, 120)as due_date,image_path,
                        is_immediately, case when ajvl.count_job is null then 0 else ajvl.count_job end jobview 
                        from  dbo.alumni_job_post  
                        left join ct as ajvl on  alumni_job_post.Doc_no=ajvl.job_id   
                        where is_publish='Y' and cancel_flag='N'  ";

            if (keyword != "")
            {
                SqlSelect = SqlSelect + "and  description like '%" + keyword + "%' ";
            }

            if (city != "")
            {
                SqlSelect = SqlSelect + " or city like '%" + city + "%' ";
            }

            SqlSelect = SqlSelect + "order by  alumni_job_post.created_date desc  ";

            return Get_data(SqlSelect);
        }

