        public void save_refund_application(ref Dictionary<string, string> dic_req_data)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();


                if (dic_req_data["doc_no"] == null || dic_req_data["doc_no"].ToString().Trim() == "")
                {
                    SqlSelect = @" insert into refund_application values('" + dic_req_data["user_id"].ToString() + "','" + dic_req_data["user_id"].ToString() +
                        "','" + dic_req_data["transaction_id"].ToString() + "','" + dic_req_data["prog_level_code"].ToString() + "','" + dic_req_data["refund_amount"].ToString() + "','" + dic_req_data["reson"].ToString() +
                        "','" + dic_req_data["accoun_holder_name"].ToString() + "','" + dic_req_data["bank_address"].ToString() + "','" + dic_req_data["account_type"].ToString() +
                        "','" + dic_req_data["ifsc_code"].ToString() + "','" + dic_req_data["account_number"] + "','" + dic_req_data["is_submit"].ToString() +
                        "','N','" + dic_req_data["user_id"].ToString() + "','" + System.DateTime.Now + "','" + dic_req_data["host"].ToString() + "',NULL,NULL,NULL)";
                }
                else
                {
                    SqlSelect = @" Update refund_application set reason_for_dropwithdrawal='" + dic_req_data["reson"].ToString() + "',name_of_account_holder='" + dic_req_data["accoun_holder_name"].ToString() +
                        "',name_of_bank_address='" + dic_req_data["bank_address"].ToString() + "',account_type='" + dic_req_data["account_type"].ToString() + "',IFSC_code='" + dic_req_data["ifsc_code"].ToString() +
                        "',account_number='" + dic_req_data["account_number"] + "',is_submit='" + dic_req_data["is_submit"].ToString() + "', last_modified_by='" + dic_req_data["user_id"].ToString() + "',last_midified_date='" + System.DateTime.Now +
                        "',last_modified_host='" + dic_req_data["host"].ToString() + "' where doc_no='" + dic_req_data["doc_no"].ToString() + "' ";

                }

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                int res_insert = DBCommand.ExecuteNonQuery();

                if (res_insert > 0)
                {
                    dic_req_data["status"] = "True";
                    dic_req_data["message"] = "Data Saved Successfully";

                    //Mail objmail = new Mail();
                    //String[] mail_res = objmail.Send_Alumni_Invite_friend_Mail(dic_req_data);
                }
                else
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                    dic_req_data["status"] = "False";
                    dic_req_data["message"] = "Problem in Save Data. Please Try Again.";
                    return;
                }
                DBCommand.Transaction.Commit();
                DBConnection.Close();
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                dic_req_data["status"] = "False";
                //dic_req_data["message"] = ex.ToString();
                dic_req_data["message"] = "Problem in Save Data. Please Try Again.";
            }
        }

