        public BLReturnObject save_student_data(DataSet ds_UploadData, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }
                server_Mast = (DS_Masters)ds_UploadData;
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                //To generate next doc number
                Document Doc = new Document();
                String message = "";
                String DocNo = "";
                String DocNo1 = "";
                //Ds_Workflow obj_workflow = new Ds_Workflow();

                DS_Masters obj_user_mst = new DS_Masters();

                obj_user_mst.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_Mast.user_mst.Rows.Count; mprCnt++)
                {
                    obj_user_mst.user_mst.ImportRow(server_Mast.user_mst.Rows[mprCnt]);
                }

                obj_user_mst.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_user_mst.user_mst, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_user_mst.user_mst.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Saved Successfully";

                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
            }

            return objBLReturnObject;
        }

