        }

        public BLReturnObject save_student_thesis_drp_dtl(DataSet ds_UploadData, string compnyid, String UserID, String HostName, Dictionary<string, object> thesis_drp_data)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Course_Master obj_thesis_drp = (DSC_Course_Master)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                obj_thesis_drp.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_thesis_drp.student_thesis_drp_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_thesis_drp.student_thesis_drp_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    Mail objmail = new Mail();
                    bool mail_sent = false;
                    string send_mail = thesis_drp_data["is_submit"].ToString();
                    string mail_type = thesis_drp_data["type"].ToString();

                    if (send_mail == "Y")
                    {
                        DataTable AckDetails = new DataTable();
                        DataTable MailDetails = new DataTable();

                        if (mail_type == "25")
                        {
                            AckDetails = Get_VF_TA_AA_Letter_Email_Body("Thesis", "email");
                            MailDetails = get_maild_data_Thesis_drp_student(thesis_drp_data["user_id"].ToString());
                        }
                        else if (mail_type == "29")
                        {
                            AckDetails = Get_VF_TA_AA_Letter_Email_Body("DRP", "email");
                            MailDetails = get_maild_data_Thesis_drp_student(thesis_drp_data["student_code"].ToString());
                        }

                        DataTable MailDetailsInst = get_maild_data_Thesis_drp_instrctor(thesis_drp_data["instructor_code"].ToString());

                        mail_sent = objmail.SendThesisDrpMail(thesis_drp_data, AckDetails, MailDetails, MailDetailsInst);
                    }
                    else
                    {
                        DBCommand.Transaction.Commit();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 1;
                        objBLReturnObject.ServerMessage = "Data Saved Successfully.";
                        return objBLReturnObject;
                    }

                    if (mail_sent)
                    {
                        DBCommand.Transaction.Commit();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 1;
                        objBLReturnObject.ServerMessage = "Data Saved and Mail Sent Successfully.";
                        return objBLReturnObject;
                    }
                    else
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        objBLReturnObject.ServerMessage = "Fail to Save Details or Sending Mail.";
                        return objBLReturnObject;
                    }
                }
            }
            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }

            return objBLReturnObject;
        }

        public BLReturnObject save_course_wise_drp_data(DataSet ds_UploadData, string compnyid, String UserID, String HostName, Dictionary<string, object> thesis_drp_data)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Course_Master obj_thesis_drp = (DSC_Course_Master)ds_UploadData;
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_Course_Master objCourseMaster_upload = new DSC_Course_Master();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < obj_thesis_drp.course_wise_drp_dtl.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "DRP", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objCourseMaster_upload.course_wise_drp_dtl.ImportRow(obj_thesis_drp.course_wise_drp_dtl.Rows[mprCnt]);
                    objCourseMaster_upload.course_wise_drp_dtl[mprCnt].doc_no = DocNo;
                    objCourseMaster_upload.course_wise_drp_dtl[mprCnt].drp_code = DocNo;
                }

                string Savepath = HttpContext.Current.Server.MapPath("~/DRPTopicBriefDocs");

                string fileDirectory = Savepath + "\\" + objCourseMaster_upload.course_wise_drp_dtl[0].doc_path;

                if (File.Exists(fileDirectory))
                {
                    //Rename Here
                    objCourseMaster_upload.course_wise_drp_dtl[0].doc_path = DocNo + "_" + objCourseMaster_upload.course_wise_drp_dtl[0].doc_path;
                    File.Move(fileDirectory, Savepath + "\\" + objCourseMaster_upload.course_wise_drp_dtl[0].doc_path);
                }

                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.course_wise_drp_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.course_wise_drp_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully.";
                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }

            return objBLReturnObject;
        }

        public DataTable get_maild_data_Thesis_drp_student(string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @"select um.user_id, um.mail, um.user_name, pm.prog_name, plm.prog_level_desc, dm.dept_name, um.dept_code, um.prog_code, um.prog_level_code
                            from user_mst um
                            left join programme_mst pm on pm.prog_code = um.prog_code 
                            left join programme_level_mst plm on plm.prog_level_code = um.prog_level_code 
                            left join department_mst dm on dm.dept_code = um.dept_code 
                            where um.user_id = '" + user_id + "'";

            return Get_data(SqlSelect);
        }

        public DataTable get_maild_data_Thesis_drp_instrctor(string instructor_code)
        {
            String SqlSelect = "";

            SqlSelect = @"select um.user_id, um.mail, im.instructor_name
                            from instructor_mst im
                            left join user_mst um on um.user_id = im.instructor_code
                            where im.instructor_code = '" + instructor_code + "'";

            return Get_data(SqlSelect);
        }

        public DataTable Get_all_course_data_For_Thesis_DRP(string sem_code, string year_code, string course_type, string prog_code, string dept_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            if (course_type == "Thesis")
            {
                SqlSelect = @"SELECT cm.course_code, dwcl.course_typology
                        FROM course_mst cm
                        Inner join department_wise_course_dtl dwcl on dwcl.course_code = cm.course_code and dwcl.semester_type = cm.semester_type and dwcl.year_semester = cm.year_semester ";
                SqlSelect = SqlSelect + " and dwcl.dept_code = '" + dept_code + "' and dwcl.prog_code = '" + prog_code + "' where cm.semester_type = '" + sem_code + "' and cm.year_semester = '" + year_code + "' and cm.ugpgoffice_approved = 'Y' ";

                if (course_type == "Thesis")
                    SqlSelect = SqlSelect + " and dwcl.course_typology = '25'";
                else
                    SqlSelect = SqlSelect + " and dwcl.course_typology = '29'";

                if (prog_code == "3")
                {
                    SqlSelect = SqlSelect + " union ";

                    SqlSelect = SqlSelect + @"SELECT cm.course_code, dwcl.course_typology
                        FROM course_mst cm
                        Inner join department_wise_course_dtl dwcl on dwcl.course_code = cm.course_code and dwcl.semester_type = cm.semester_type and dwcl.year_semester = cm.year_semester ";
                    SqlSelect = SqlSelect + " and dwcl.dept_code = '10' and dwcl.prog_code = '" + prog_code + "' where cm.semester_type = '" + sem_code + "' and cm.year_semester = '" + year_code + "' and cm.ugpgoffice_approved = 'Y' ";

                    if (course_type == "Thesis")
                        SqlSelect = SqlSelect + " and dwcl.course_typology = '25'";
                    else
                        SqlSelect = SqlSelect + " and dwcl.course_typology = '29'";
                }

                SqlSelect = SqlSelect + " ORDER BY course_code";
            }
            else
            {
                SqlSelect = @"SELECT cm.course_code, dwcl.course_typology
                        FROM course_mst cm
                        Inner join department_wise_course_dtl dwcl on dwcl.course_code = cm.course_code and dwcl.semester_type = cm.semester_type and dwcl.year_semester = cm.year_semester ";
                SqlSelect = SqlSelect + " where cm.semester_type = '" + sem_code + "' and cm.year_semester = '" + year_code + "' and cm.ugpgoffice_approved = 'Y' and cm.cancel_flag='N' and dwcl.cancel_flag='N' ";

                SqlSelect = SqlSelect + " and dwcl.course_typology = '29'";

                SqlSelect = SqlSelect + " ORDER BY course_code";
            }

            return Get_data(SqlSelect);
        }

