        public DataTable get_course_wise_drp_student(String semester, String year, String course_code, String drp_code, String student_year_code, String prog_level)
        //public DataTable get_course_wise_drp_student(String semester, String year, String course_code, String drp_code)
        {
            //Changes By 19072021
            String SqlSelect = "";

            if (student_year_code == "")
            {
                SqlSelect = " select * from student_course_allocate_dtl " +
                    " inner join user_mst on user_mst.user_id  = student_course_allocate_dtl.user_id " +
                    " left join student_thesis_drp_dtl on student_thesis_drp_dtl.student_code = student_course_allocate_dtl.user_id " +
                    " and student_thesis_drp_dtl.cancel_flag ='N' and student_thesis_drp_dtl.semester_type ='" + semester + "' " +
                    " and student_thesis_drp_dtl.year_semester ='" + year + "' " +
                    " inner join student_wise_drp_dtl on student_wise_drp_dtl.user_id = student_course_allocate_dtl.user_id " +
                    " and student_wise_drp_dtl.semester_type='" + semester + "' and  student_wise_drp_dtl.year_semester = '" + year + "' " +
                    " and student_wise_drp_dtl.cancel_flag ='N' " +
                    " where student_course_allocate_dtl.semester_type='" + semester + "' and " +
                    " student_course_allocate_dtl.year_semester = '" + year + "' and student_course_allocate_dtl.cancel_flag ='N'" +
                    " and student_course_allocate_dtl.course_code ='" + course_code + "' and student_wise_drp_dtl.drp_code = '" + drp_code + "'";
                if (prog_level != "")
                {
                    SqlSelect = SqlSelect + " and user_mst.prog_level_code = '" + prog_level + "'";
                }


                SqlSelect = SqlSelect + "Union";

                SqlSelect = SqlSelect + " select * from student_course_allocate_dtl " +
