                    " inner join department_wise_course_dtl as dwc on dwc.dept_code = user_mst.dept_code and dwc.prog_code = user_mst.prog_code " +
                    " left join student_thesis_drp_dtl on student_thesis_drp_dtl.student_code = user_mst.user_id " +
                    " and student_thesis_drp_dtl.cancel_flag ='N' and student_thesis_drp_dtl.semester_type ='" + semester + "' and student_thesis_drp_dtl.year_semester ='" + year + "'" +
