                SqlSelect += " select user_mst.user_id,user_mst.full_name,student_wise_drp_dtl.course_code,student_wise_drp_dtl.drp_code,student_wise_drp_dtl.seat_type, " +
                     " student_thesis_drp_dtl.form_type,student_thesis_drp_dtl.instructor_code,student_thesis_drp_dtl.is_submit,student_thesis_drp_dtl.status as status1, " +
                     " student_thesis_drp_dtl.thesis_abstract,student_thesis_drp_dtl.thesis_references,student_thesis_drp_dtl.topic " +
                     " from user_mst " +
                     " inner join department_wise_course_dtl as dwc on dwc.dept_code = user_mst.dept_code and dwc.prog_code = user_mst.prog_code " +
                     " left join student_thesis_drp_dtl on student_thesis_drp_dtl.student_code = user_mst.user_id " +
                     " and student_thesis_drp_dtl.cancel_flag ='N' and student_thesis_drp_dtl.semester_type ='" + semester + "' and student_thesis_drp_dtl.year_semester ='" + year + "'" +
                     " left join student_wise_drp_dtl on student_wise_drp_dtl.user_id = user_mst.user_id " +
                     " and student_wise_drp_dtl.semester_type='" + semester + "' and  student_wise_drp_dtl.year_semester = '" + year + "' and student_wise_drp_dtl.cancel_flag ='N' " +
