        public BLReturnObject update_drp_dtl(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_Course_Master dSC_DRP = (DSC_Course_Master)ds_UploadData;
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";

                DSC_Course_Master objCourseMaster_upload = new DSC_Course_Master();
                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < dSC_DRP.course_wise_drp_dtl.Rows.Count; mprCnt++)
                {

                    objCourseMaster_upload.course_wise_drp_dtl.ImportRow(dSC_DRP.course_wise_drp_dtl.Rows[mprCnt]);

                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.course_wise_drp_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.course_wise_drp_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

        public DataTable get_student_wise_drp_rept(String course_code, String semester, String year, String drp_code, String dept_code, String prog_code)
        {
            String SqlSelect = "";

            SqlSelect = "select distinct user_mst.user_id as student_id,user_mst.full_name,student_wise_drp_dtl.course_code,course_wise_drp_dtl.topic," +
                " CASE WHEN student_wise_drp_dtl.seat_type = 'F'  THEN 'Funded' WHEN student_wise_drp_dtl.seat_type = 'UF' THEN 'Un-Funded' END As seat," +
                " course_wise_drp_dtl.instructor_code,us.full_name as faculty_name,us.mail,course_wise_drp_dtl.doc_path" +
                " from student_wise_drp_dtl " +
                " inner join user_mst on user_mst.user_id = student_wise_drp_dtl.user_id " +
                " inner join course_wise_drp_dtl on course_wise_drp_dtl.drp_code = student_wise_drp_dtl.drp_code " +
                " inner join user_mst as us on us.user_id = course_wise_drp_dtl.instructor_code " +
                " left join department_wise_course_dtl on department_wise_course_dtl.course_code = student_wise_drp_dtl.course_code " +
                " where student_wise_drp_dtl.year_semester ='" + year + "' and student_wise_drp_dtl.semester_type ='" + semester + "' " +
                " and student_wise_drp_dtl.cancel_flag ='N' and course_wise_drp_dtl.semester_type ='" + semester + "' " +
                " and course_wise_drp_dtl.year_semester ='" + year + "' and course_wise_drp_dtl.cancel_flag ='N'";

            if (dept_code != "")
            {
                SqlSelect = SqlSelect + "and department_wise_course_dtl.dept_code = '" + dept_code + "'";
            }
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + "and department_wise_course_dtl.prog_code = '" + prog_code + "'";
            }

            return Get_data(SqlSelect);

        }

        public DataTable get_drp_wise_inst_dtl(String semester, String year)
        {
            String SqlSelect = "";

            //SqlSelect = " select um.user_type,im.instructor_code, im.instructor_name from instructor_mst im " +
            //    " inner join user_mst um on um.user_id = im.instructor_code " +
            //    " where um.user_type in ('PC', 'I2', 'D') and um.user_status_flag = 'A' and um.status = 'A' " +
            //    " and im.designation <> 'temp' and um.cancel_flag = 'N' and im.cancel_flag = 'N'" +
            //    " and im.instructor_code Not In (select distinct instructor_code from course_wise_drp_dtl where year_semester ='" + year + "'" +
            //    " and semester_type = '" + semester + "' and cancel_flag = 'N') order by um.user_type,im.instructor_name ";


            SqlSelect = @"SELECT STUFF(( 
                          Select 
                          '<option value=""' + im.instructor_code + '"">' + im.instructor_name + ' ('+im.designation+')</option>' 
                          from instructor_mst im  
                          inner join user_mst um on um.user_id = im.instructor_code  where um.user_type in ('PC', 'I2', 'D') 
                          and um.user_status_flag = 'A' and um.status = 'A' 
                          and im.designation <> 'temp' and um.cancel_flag = 'N' 
                          and im.cancel_flag = 'N' 
                          and im.instructor_code Not In (select distinct instructor_code from course_wise_drp_dtl where year_semester ='" + year + @"' 
                          and semester_type = '" + semester + @"' and cancel_flag = 'N' and instructor_code is not null)  
                          ORDER BY im.instructor_name FOR XML PATH(''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 0, '') AS options";

            return Get_data(SqlSelect);

        }

        public DataTable get_drp_topic_dtl(String semester, String year, String user_type, String user_id)
        {
            String SqlSelect = "";

            SqlSelect = " Select distinct course_wise_drp_dtl.course_code,course_wise_drp_dtl.topic,drp_code,course_wise_drp_dtl.instructor_code,user_mst.full_name," +
                        " course_wise_drp_dtl.doc_no,course_wise_drp_dtl.doc_path " +
                        " from course_wise_drp_dtl left join user_mst on user_mst.user_id = course_wise_drp_dtl.instructor_code " +
                        " LEFT JOIN department_wise_course_dtl dwc on dwc.course_code = course_wise_drp_dtl.course_code " +
                        " and dwc.semester_type = course_wise_drp_dtl.semester_type and dwc.year_semester = course_wise_drp_dtl.year_semester " +
                        " and dwc.cancel_flag='N' " +
                        " where course_wise_drp_dtl.year_semester = '" + year + "' and course_wise_drp_dtl.semester_type = '" + semester + "'" +
                        " and course_wise_drp_dtl.cancel_flag ='N'";
            if (user_type == "FA")
            {
                SqlSelect += " And dwc.dept_code IN (Select distinct dept_code from department_wise_user_dtl " +
                    " where semester_type='" + semester + @"' and year_semester='" + year + @"' and cancel_flag='N' and instructor_code='" + user_id + @"')";
            }


            return Get_data(SqlSelect);

        }

        public Boolean update_drp_student(String doc_no, String user_id, String host_name)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
