            String SqlSelect = "";

            SqlSelect = "Update student_wise_drp_dtl SET cancel_flag ='Y',last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where doc_no in (" + doc_no + ") ";



