        public DataTable Get_course_list_for_subgroup(string sem_code, string year_code, string dept_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select cm.course_code,cm.course_name from course_mst as cm 
                            inner join department_wise_course_dtl as dwc on dwc.course_code=cm.course_code and dwc.cancel_flag='N' 
		                            and dwc.semester_type=cm.semester_type and dwc.year_semester=cm.year_semester 
                            inner join (select distinct course_code from student_course_allocate_dtl as sca 
		                            where sca.semester_type='" + sem_code + "' and sca.year_semester='" + year_code + @"' and sca.cancel_flag='N' 
                            )res1 on res1.course_code=cm.course_code 
                            where cm.semester_type='" + sem_code + "' and cm.year_semester='" + year_code + "' and cm.cancel_flag='N' ";

            if (dept_code != "")
            {
                SqlSelect += " and dwc.dept_code='" + dept_code + "' ";
            }

            SqlSelect += " order by cm.course_code ";

            return Get_data(SqlSelect);
        }

        public DataTable Get_instructor_list_for_subgroup(string sem_code, string year_code, string course_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select '1' as sr_no,im.instructor_code,'Instructor' as instructor_type,im.instructor_name,res.sub_group_id from course_mst as cm 
                            inner join course_wise_instructor as cwi on cwi.course_code=cm.course_code and cwi.cancel_flag='N'
		                            and cwi.semester_type=cm.semester_type and cwi.year_semester=cm.year_semester
                            inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'
                            left join (select * from course_sub_group_instructor where semester_type='" + sem_code + "' and year_semester='" + year_code + @"' and cancel_flag='N' 
                                        and sub_group_id in (select sub_group_id from course_sub_group where course_code='" + course_code + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + @"')
                            )res on res.instructor_code=cwi.instructor_code
                            where cm.semester_type='" + sem_code + "' and cm.year_semester='" + year_code + "' and cm.cancel_flag='N' and cm.course_code='" + course_code + @"' 

                            union 

                            select '2' as sr_no,im.instructor_code,'AA' as instructor_type,im.instructor_name,res.sub_group_id from course_mst as cm 
                            inner join course_wise_AA as cwi on cwi.course_code=cm.course_code and cwi.cancel_flag='N'
		                            and cwi.semester_type=cm.semester_type and cwi.year_semester=cm.year_semester
                            inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'
                            left join (select * from course_sub_group_instructor where semester_type='" + sem_code + "' and year_semester='" + year_code + @"' and cancel_flag='N' 
                                        and sub_group_id in (select sub_group_id from course_sub_group where course_code='" + course_code + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + @"')
                            )res on res.instructor_code=cwi.instructor_code
                            where cm.semester_type='" + sem_code + "' and cm.year_semester='" + year_code + "' and cm.cancel_flag='N' and cm.course_code='" + course_code + @"' 

                            union 

                            select '3' as sr_no,im.instructor_code,'TA' as instructor_type,im.instructor_name,res.sub_group_id from course_mst as cm 
                            inner join course_wise_TA as cwi on cwi.course_code=cm.course_code and cwi.cancel_flag='N'
		                            and cwi.semester_type=cm.semester_type and cwi.year_semester=cm.year_semester
                            inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'
                            left join (select * from course_sub_group_instructor where semester_type='" + sem_code + "' and year_semester='" + year_code + @"' and cancel_flag='N' 
                                        and sub_group_id in (select sub_group_id from course_sub_group where course_code='" + course_code + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + @"')
                            )res on res.instructor_code=cwi.instructor_code
                            where cm.semester_type='" + sem_code + "' and cm.year_semester='" + year_code + "' and cm.cancel_flag='N' and cm.course_code='" + course_code + @"'
                            order by sr_no,im.instructor_code ";

            return Get_data(SqlSelect);
        }

