        public BLReturnObject save_course_subgroup_dtl(DataSet ds_UploadData, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            String SqlSelect = "";

            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                //DSC_StudentFoundationDtl temp_server_Mast = (DSC_StudentFoundationDtl)ds_UploadData;
                DSC_StudentFoundationDtl obj_user_mst = (DSC_StudentFoundationDtl)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                //To generate next doc number
                Document Doc = new Document();
                String message = "";
                String DocNo = "";
                String DocNo1 = "";
                //Ds_Workflow obj_workflow = new Ds_Workflow();

                obj_user_mst.EnforceConstraints = false;

                string course_code = obj_user_mst.course_sub_group[0]["course_code"].ToString();
                string semester_type = obj_user_mst.course_sub_group[0]["semester_type"].ToString();
                string year_semester = obj_user_mst.course_sub_group[0]["year_semester"].ToString();

                bool delete_flag = false;

                // Delete Course Sub Group Instructor
                SqlSelect = "delete from course_sub_group_instructor where semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and sub_group_id in (select sub_group_id from course_sub_group where course_code='" + course_code + "' and semester_type='" + semester_type + "' and year_semester='" + year_semester + "')";
                DBCommand.CommandText = SqlSelect;
                DBCommand.CommandType = CommandType.Text;
                try { DBCommand.ExecuteNonQuery(); }
                catch (Exception e) { delete_flag = true; }

                // Delete Course Sub Group Student
                SqlSelect = "delete from course_sub_group_student where semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and sub_group_id in (select sub_group_id from course_sub_group where course_code='" + course_code + "' and semester_type='" + semester_type + "' and year_semester='" + year_semester + "')";
                DBCommand.CommandText = SqlSelect;
                DBCommand.CommandType = CommandType.Text;
                try { DBCommand.ExecuteNonQuery(); }
                catch (Exception e) { delete_flag = true; }

                // Delete Course Sub Group
                SqlSelect = "delete from course_sub_group where course_code='" + course_code + "' and semester_type='" + semester_type + "' and year_semester='" + year_semester + "'";
                DBCommand.CommandText = SqlSelect;
                DBCommand.CommandType = CommandType.Text;
                try { DBCommand.ExecuteNonQuery(); }
                catch (Exception e) { delete_flag = true; }

                if (delete_flag)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Data.";
                    return objBLReturnObject;
                }

                obj_user_mst.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_user_mst.course_sub_group, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_user_mst.course_sub_group.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_user_mst.course_sub_group_instructor, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_user_mst.course_sub_group_instructor.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_user_mst.course_sub_group_student, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_user_mst.course_sub_group_student.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Saved Successfully";
                    return objBLReturnObject;
                }
            }
            catch (Exception ex)
            {
            }

            return objBLReturnObject;
        }

