        public DataTable get_course_outline_for_PDF(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "select *,department_wise_course_dtl.dept_code,department_wise_course_dtl.prog_code,department_wise_course_dtl.prog_level_code,course_mst.course_code,course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type,department_wise_course_dtl.semester_code,course_mst.course_desc,course_mst.prerequisite,department_wise_course_dtl.prog_course_id,department_wise_course_dtl.sub_category_id,cwi.tutor_type,course_mst.CouseSubTitle " +
                       " from course_mst " +
                       " INNER JOIN department_wise_course_dtl on course_mst.course_code = department_wise_course_dtl.course_code " +
                       " left join department_mst as dm on department_wise_course_dtl.dept_code=dm.dept_code " +
                       " left join course_wise_instructor as cwi on course_mst.course_code=cwi.course_code  " +
                       " and cwi.year_semester=course_mst.year_semester and cwi.semester_type=course_mst.semester_type " +
                       " left join instructor_mst as im on im.instructor_code=cwi.instructor_code " +
                       " where " + //course_mst.cancel_flag = 'N'
                       " course_mst.year_semester = '" + year_code + "'  " +
                       " AND course_mst.semester_type = '" + sem_code + "' " +
                       " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                       " and course_mst.course_code='" + course_code + "' order by cwi.tutor_type desc";

            return Get_data(SqlSelect);
        }

