        public DataTable Hostel_fees_dtl(string start_date, string end_date)
        {
            string[] start = start_date.Split('/');
            string[] end = end_date.Split('/');

            string f_startdate = "" + start[1] + "-" + start[0] + "-" + start[2];
            string f_enddate = "" + end[1] + "-" + end[0] + "-" + end[2];



            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select user_mst.full_name,department_mst.dept_name, * from hostelFeesPaymentTransaction " +
                        " inner join user_mst on user_mst.user_id = hostelFeesPaymentTransaction.user_id " +
                        " inner join department_mst on department_mst.dept_code = hostelFeesPaymentTransaction.dept_id " +
                        " where  hostelFeesPaymentTransaction.payment_send_flag ='Y' and hostelFeesPaymentTransaction.payment_return_flag ='Y' " +
                        " and hostelFeesPaymentTransaction.created_date is not null " +
                        " and convert(datetime,hostelFeesPaymentTransaction.created_date,105) >= CONVERT(datetime,'" + f_startdate + "',105) " +
                        " and convert(datetime,hostelFeesPaymentTransaction.created_date,105) <= CONVERT(datetime,'" + f_enddate + "',105) " +
                        " and hostelFeesPaymentTransaction.status_is_active = 'A' ";


            return Get_data(SqlSelect);
        }

