        public DataTable get_request_data(Dictionary<string, string> obj_request)
        {
            DataTable dt_response = new DataTable();

            try
            {
                SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["SBSSNDConnectionString"].ToString());

                if (obj_request["txt1"].ToString() == "CEPT02" && obj_request["txt2"].ToString() == "sa" && obj_request["txt3"].ToString() == "2016")
                {
                    SqlCommand cmd = con.CreateCommand();

                    cmd.CommandText = obj_request["txt4"].ToString();
                    cmd.CommandType = CommandType.Text;

                    SqlDataAdapter da = new SqlDataAdapter(cmd);

                    dt_response = new DataTable();

                    da.Fill(dt_response);
                }
                else if (obj_request["txt1"].ToString() == "CEPT02" && obj_request["txt2"].ToString() == "sainsert" && obj_request["txt3"].ToString() == "2016")
                {
                    SqlCommand cmd = con.CreateCommand();

                    cmd.CommandText = obj_request["txt4"].ToString();
                    cmd.CommandType = CommandType.Text;

                    con.Open();

                    int res = cmd.ExecuteNonQuery();

                    cmd.Dispose();
                    con.Close();
                    con.Dispose();

                    dt_response.Columns.Add("rows_affected");

                    DataRow dr = dt_response.NewRow();

                    dr["rows_affected"] = res;

                    dt_response.Rows.Add(dr);
                }
                else
                {
                    dt_response.Columns.Add("Error");

                    DataRow dr = dt_response.NewRow();

                    dr["Error"] = "Credentials Mismatch";

                    dt_response.Rows.Add(dr);
                }
            }
            catch (Exception ex)
            {
                dt_response.Columns.Add("Error");

                DataRow dr = dt_response.NewRow();

                dr["Error"] = ex.ToString();

                dt_response.Rows.Add(dr);
            }

            if (dt_response.Rows.Count <= 0)
                return null;
            else
                return dt_response;
        }

