        #region Kapil
        public BLReturnObject save_drp_dtl_upload(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }
                string DocNo = "";
                string message = "";

                DSC_Course_Master server_drp_installment = (DSC_Course_Master)ds_UploadData;
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                DSC_Course_Master obj_drp_installment_upload = new DSC_Course_Master();
                obj_drp_installment_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_drp_installment.course_wise_drp_dtl.Rows.Count; mprCnt++)
                {
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "DRP", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    obj_drp_installment_upload.course_wise_drp_dtl.ImportRow(server_drp_installment.course_wise_drp_dtl.Rows[mprCnt]);
                    obj_drp_installment_upload.course_wise_drp_dtl[mprCnt].doc_no = DocNo;
                    obj_drp_installment_upload.course_wise_drp_dtl[mprCnt].drp_code = DocNo;
                }

                obj_drp_installment_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, obj_drp_installment_upload.course_wise_drp_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != obj_drp_installment_upload.course_wise_drp_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }
            }

            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = ex.ToString();
                return objBLReturnObject;
            }
            return objBLReturnObject;
        }

