        public DataTable get_department_for_student_clearance(string prog_code)//Kapil Changed
        {
            String SqlSelect = "";

            SqlSelect = @" select department_for_clearance_form.*, user_mst.mail,CONCAT(user_mst.first_name, user_mst.last_name) as name from department_for_clearance_form 
                            left join user_mst on user_mst.user_id = department_for_clearance_form.user_id
                            inner join cept_current_semester on cept_current_semester.sem_code = department_for_clearance_form.semester_type
                            and cept_current_semester.year_code = department_for_clearance_form.year_semester and cept_current_semester.type_desc = 'clearance_form'
                            where department_for_clearance_form.cancel_flag = 'N' ";

            if (prog_code == "1")
            {
                SqlSelect += " and department_for_clearance_form.user_id <> 'pg'";
            }
            else if (prog_code == "2")
            {
                SqlSelect += " and department_for_clearance_form.user_id <> 'ug'";
            }
            else
            {
                SqlSelect += " and department_for_clearance_form.user_id <> 'pg' and department_for_clearance_form.user_id <> 'ug' ";
            }

            SqlSelect += " order by department_for_clearance_form.department_id ";

            return Get_data(SqlSelect);
        }

        public DataTable get_submitted_student_clearance_form(string sem_code, string year_code, string user_id, string user_type_student_id)
        {
            String SqlSelect = "";

            string[] parts = user_type_student_id.Split('#');

            string user_type = parts[0].Trim();
            string student_id = parts[1].Trim();

            if (user_type == "CD" || user_type == "O" || user_type == "I2" || user_type == "FA" || user_type == "SS" || user_type == "AC" || user_type == "A1")
            {
                if (user_type == "O" || user_type == "I2" || user_type == "FA" || user_type == "SS" || user_type == "AC" || user_type == "A1")
                {
                    DataTable dt_name = get_dept_id_from_user_id(sem_code, year_code, user_id, user_type);
                    if (dt_name != null)
                    {
                        SqlSelect = " select distinct student_clearance_form.status, user_mst.user_name, user_mst.mail, user_mst.dept_code, student_clearance_form.*, user_mst.alternet_mail, user_contact_dtl.applicant_mobile_no from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id left join user_contact_dtl on user_mst.enrollment_no = user_contact_dtl.application_id WHERE student_clearance_form.department_id = '" + dt_name.Rows[0]["department_id"].ToString() + "' and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' ";

                        if (user_type == "AC")
                        {
                            SqlSelect = "";
                            SqlSelect = " select distinct student_clearance_form.status, user_mst.user_name, user_mst.mail, user_mst.dept_code, student_clearance_form.*, user_mst.alternet_mail, user_contact_dtl.applicant_mobile_no, (select value from student_clearance_form where user_id=user_mst.user_id and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and department_id='D8' and status='Pending') as account_details from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id left join user_contact_dtl on user_mst.enrollment_no = user_contact_dtl.application_id WHERE student_clearance_form.department_id = '" + dt_name.Rows[0]["department_id"].ToString() + "' and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' ";

                            if (user_id == "AC001")
                            {
                                SqlSelect += " and user_mst.dept_code='5' ";
                            }
                            else if (user_id == "AC002")
                            {
                                SqlSelect += " and user_mst.dept_code='1' ";
                            }
                            else if (user_id == "AC004")
                            {
                                // SqlSelect += " and user_mst.dept_code='4' ";
                                SqlSelect += " and user_mst.dept_code in(select dept_code from department_mst where cancel_flag='N') ";
                            }
                            else if (user_id == "AC005")
                            {
                                SqlSelect += " and user_mst.dept_code in ('2','3') ";
                            }
                        }
                        else if (user_type == "FA" && user_id != "FA011")
                        {
                            SqlSelect = "";
                            DataTable dt_name_FA = get_dept_id_from_user_id(sem_code, year_code, user_id, user_type);
                            if (dt_name_FA != null)
                            {
                                SqlSelect = " select distinct student_clearance_form.status, user_mst.user_name, user_mst.mail, user_mst.dept_code, student_clearance_form.*, user_mst.alternet_mail, user_contact_dtl.applicant_mobile_no from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id left join user_contact_dtl on user_mst.enrollment_no = user_contact_dtl.application_id WHERE student_clearance_form.department_id = '" + dt_name_FA.Rows[0]["department_id"].ToString() + "' and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' ";
                                //WIP
                                string dept_code = "";

                                DataTable dt_dept_prog_dtl = get_department_wise_user_dtl(user_id, sem_code, year_code);

                                if (dt_dept_prog_dtl != null)
                                {
                                    for (int v = 0; v < dt_dept_prog_dtl.Rows.Count; v++)
                                    {
                                        if (v == 0)
                                        {
                                            dept_code += "'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                                        }
                                        else
                                        {
                                            dept_code += ",'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                                        }
                                    }
                                }

                                SqlSelect += " and user_mst.dept_code in (" + dept_code + ") ";
                            }
                        }
                        else if (user_type == "FA" && user_id == "FA011")
                        {
                            SqlSelect = "";
                            SqlSelect += " select distinct student_clearance_form.status, user_mst.user_name, user_mst.mail, user_mst.dept_code, student_clearance_form.*, user_mst.alternet_mail, user_contact_dtl.applicant_mobile_no from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id left join user_contact_dtl on user_mst.enrollment_no = user_contact_dtl.application_id WHERE student_clearance_form.department_id = (select department_id from department_for_clearance_form where user_id='" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "') and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' and user_mst.gender='M' ";
