                }

                if (student_id != "-")
                {
                    SqlSelect += " and student_clearance_form.user_id='" + student_id + "'";
                }

                SqlSelect += " order by student_clearance_form.created_date desc ";
            }
            else if (user_type == "CD-" || user_type == "O-" || user_type == "I2-" || user_type == "FA-" || user_type == "SS-" || user_type == "AC-" || user_type == "A1-")
            {
                if (user_type == "CD-" || user_type == "O-" || user_type == "I2-" || user_type == "FA-" || user_type == "SS-" || user_type == "AC-" || user_type == "A1-")
                {
                    DataTable dt_name = get_dept_id_from_user_id(sem_code, year_code, user_id, user_type);

                    if (dt_name != null)
                    {
                        if (user_type == "FA-" && user_id == "FA011")
                        {
                            SqlSelect = "";
                            SqlSelect += " select * from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id WHERE student_clearance_form.department_id = (select department_id from department_for_clearance_form where user_id='" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "') and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' and student_clearance_form.user_id='" + student_id + "' and student_clearance_form.status='Pending'";
                        }
                        else
                        {

                            SqlSelect = " select * from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id WHERE student_clearance_form.department_id = '" + dt_name.Rows[0]["department_id"].ToString() + "' and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' and student_clearance_form.user_id='" + student_id + "' and student_clearance_form.status='Pending'";
                        }
                    }
                }
                else
                {
                    SqlSelect = " select * from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id WHERE student_clearance_form.department_id = '" + user_id + "' and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' and student_clearance_form.user_id='" + student_id + "' and student_clearance_form.status='Pending'";
