            SqlSelect = @" select '', user_mst.user_name, user_mst.mail, user_mst.dept_code, student_clearance_form.*, user_mst.alternet_mail, user_contact_dtl.applicant_mobile_no "
                + " from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id left join user_contact_dtl on user_mst.enrollment_no = user_contact_dtl.application_id "
                + " WHERE student_clearance_form.department_id = 'D5'  and student_clearance_form.semester_type='" + sem_code + "' "
                + " and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' ";

            SqlSelect += "  and student_clearance_form.cancel_flag='N' and user_mst.gender = 'F' ";

            if (student_id != "-")
            {
                SqlSelect += " and student_clearance_form.user_id='" + student_id + "'";
            }

            SqlSelect += " order by student_clearance_form.created_date desc ";

            return Get_data(SqlSelect);
        }

        public DataTable get_student_id_submitted_clearance_form(string sem_code, string year_code, string user_id, string user_type)
        {
            String SqlSelect = "";

            if (user_type == "CD")
            {
                SqlSelect = " select user_id from student_clearance_form WHERE department_id = '" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' group by user_id";
            }
            else if (user_type == "AC")
            {
                DataTable dt_name = get_dept_id_from_user_id(sem_code, year_code, user_id, user_type);
                if (dt_name != null)
                {
                    SqlSelect = " select student_clearance_form.user_id from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id WHERE student_clearance_form.department_id = '" + dt_name.Rows[0]["department_id"].ToString() + "' and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' ";

                    if (user_id == "AC001")
                    {
                        SqlSelect += " and user_mst.dept_code='5' ";
                    }
                    else if (user_id == "AC002")
                    {
                        SqlSelect += " and user_mst.dept_code='1' ";
                    }
                    else if (user_id == "AC004")
                    {
                        //SqlSelect += " and user_mst.dept_code='4' ";
                        SqlSelect += " and user_mst.dept_code in(select dept_code from department_mst where cancel_flag='N') ";
                    }
                    else if (user_id == "AC005")
                    {
                        SqlSelect += " and user_mst.dept_code in ('2','3') ";
                    }

                    SqlSelect += " group by student_clearance_form.user_id ";
                }
            }
            else if (user_type == "FA" && user_id != "FA011")
            {
                DataTable dt_name = get_dept_id_from_user_id(sem_code, year_code, user_id, user_type);
                if (dt_name != null)
                {
                    SqlSelect = " select student_clearance_form.user_id from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id WHERE student_clearance_form.department_id = '" + dt_name.Rows[0]["department_id"].ToString() + "' and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' ";

                    string dept_code = "";

                    DataTable dt_dept_prog_dtl = get_department_wise_user_dtl(user_id, sem_code, year_code);

                    if (dt_dept_prog_dtl != null)
                    {
                        for (int v = 0; v < dt_dept_prog_dtl.Rows.Count; v++)
                        {
                            if (v == 0)
                            {
                                dept_code += "'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                            }
                            else
                            {
                                dept_code += ",'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                            }
                        }
                    }

                    SqlSelect += " and user_mst.dept_code in (" + dept_code + ") ";

                    SqlSelect += " group by student_clearance_form.user_id ";
                }
            }
            else if (user_type == "FA" && user_id == "FA011")
            {
                SqlSelect = " select student_clearance_form.user_id from student_clearance_form inner join user_mst on user_mst.user_id = student_clearance_form.user_id WHERE student_clearance_form.department_id = (select department_id from department_for_clearance_form where user_id = '" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "') and student_clearance_form.semester_type='" + sem_code + "' and student_clearance_form.year_semester='" + year_code + "' and student_clearance_form.cancel_flag='N' and user_mst.gender='M' group by student_clearance_form.user_id";
            }
            else
            {
                DataTable dt_name = get_dept_id_from_user_id(sem_code, year_code, user_id, user_type);
                if (dt_name != null)
                {
                    SqlSelect = " select user_id from student_clearance_form WHERE department_id = '" + dt_name.Rows[0]["department_id"].ToString() + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' group by user_id";
                }
            }

            return Get_data(SqlSelect);
        }

