        public bool process_for_clearance_form(Dictionary<string, object> obj_action_request, string user_id)
        {
            DBConnection.Open();
            //DBCommand.Transaction = DBConnection.BeginTransaction();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            StringBuilder SqlSelect = new StringBuilder();

            SqlSelect.Append(@"update student_clearance_form set refund_processed='Y', refund_remarks='" + obj_action_request["refund_remarks"].ToString() + "', last_modified_by = '" + user_id + "', last_modified_date = GETDATE(), last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' where user_id='" + obj_action_request["student_id"].ToString() + "' and semester_type='" + obj_action_request["sem"].ToString() + "' and year_semester='" + obj_action_request["year"].ToString() + "' and department_name = 'Account Details' and status='Pending' and cancel_flag='N' ");

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect.ToString();

            try
            {
                int res = DBCommand.ExecuteNonQuery();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                if (res > 0)
                {
                    //DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return true;
                }
                else
                {
                    //DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }
            }
            catch (Exception ex)
            {
                //DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
        }


