        public string formatewisedoc_no(string doc_no)
        {

            string formate_doc_no = FormatDocumentNo_new("IS", Convert.ToDecimal(doc_no));
            return formate_doc_no;


        }
        public String FormatDocumentNo_new(String DocumentType, Decimal doc_no)
        {
            int DOCUMENTNOPORTIONLENGTH = 6;
            String FormattedNo = "";
            FormattedNo = DocumentType.Substring(0, 1);


            String year = System.DateTime.Today.Year.ToString();
            FormattedNo += year.Substring(2);
            year = System.DateTime.Today.AddYears(1).Year.ToString().Substring(2);
            //next year 2 chars
            FormattedNo += year;

            int LengthOfCurrentDocNo = doc_no.ToString().Length;
            for (int i = 1; i <= DOCUMENTNOPORTIONLENGTH - LengthOfCurrentDocNo; i++)
                FormattedNo += "0";
            FormattedNo += doc_no.ToString();

            return FormattedNo;
        }

