        public DataTable get_program_list_for_interested_program()
        {
            String SqlSelect = "";

            SqlSelect = @"select dm.dept_name,pm.prog_name,plm.* from programme_level_mst plm
                            inner join department_mst dm on dm.dept_code = plm.dept_code
                            inner join programme_mst pm on pm.prog_code = plm.prog_code
                            where plm.cancel_flag='N'
                            order by plm.dept_code, plm.prog_code asc";

            return Get_data(SqlSelect);
        }

