        public BLReturnObject save_instructor_teaching_intrest_data(DataSet ds_UploadData, DataSet ds_UploadData_inst, string compnyid, String UserID, DataTable dt_call_for_studio_current_sem_data)
        {
            string doc_number = "";
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }
                //15022022

                if (ds_UploadData_inst == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }


                DSC_VF_Mgmt server_instructor_master = (DSC_VF_Mgmt)ds_UploadData;
                //DSC_Vertical_Studio_Selection_dtl dsc_studio_inst_master = (DSC_Vertical_Studio_Selection_dtl)ds_UploadData_inst;
                DSC_Parameter dsc_studio_inst_master = (DSC_Parameter)ds_UploadData_inst;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";
                String saved_studio_code = "";

                DSC_VF_Mgmt objInstructorMaster_upload = new DSC_VF_Mgmt();
                // DSC_Vertical_Studio_Selection_dtl objstudioMaster_upload = new DSC_Vertical_Studio_Selection_dtl();
                DSC_Parameter objstudioMaster_upload = new DSC_Parameter();

                objInstructorMaster_upload.EnforceConstraints = false;
                //15022022
                objstudioMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_instructor_master.instructor_teaching_interest.Rows.Count; mprCnt++)
                {
                    objInstructorMaster_upload.instructor_teaching_interest.ImportRow(server_instructor_master.instructor_teaching_interest.Rows[mprCnt]);
                    objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "CFS", UserID, HttpContext.Current.Request.UserHostName, ref DocNo, ref message))
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }

                    saved_studio_code = "CFS" + DocNo;
                    //saved_studio_code = "P" + dt_call_for_studio_current_sem_data.Rows[0]["sem_code"].ToString() + dt_call_for_studio_current_sem_data.Rows[0]["year_code"].ToString() + DocNo;

                    objInstructorMaster_upload.instructor_teaching_interest[mprCnt].doc_no = "CFS" + DocNo;
                    objInstructorMaster_upload.instructor_teaching_interest[mprCnt].studio_code = "CFS" + DocNo;
                    //objInstructorMaster_upload.instructor_teaching_interest[mprCnt].doc_no = "P" + dt_call_for_studio_current_sem_data.Rows[0]["sem_code"].ToString() + dt_call_for_studio_current_sem_data.Rows[0]["year_code"].ToString().Substring(2, 3) + DocNo;
                    //objInstructorMaster_upload.instructor_teaching_interest[mprCnt].studio_code = "P" + dt_call_for_studio_current_sem_data.Rows[0]["sem_code"].ToString() + dt_call_for_studio_current_sem_data.Rows[0]["year_code"].ToString().Substring(2,3) + DocNo;
                }

                //15022022
                for (int mprCnt = 0; mprCnt < dsc_studio_inst_master.studio_wise_instructor_dtl.Rows.Count; mprCnt++)
                {
                    objstudioMaster_upload.studio_wise_instructor_dtl.ImportRow(dsc_studio_inst_master.studio_wise_instructor_dtl.Rows[mprCnt]);

                    // saved_studio_code = "CFS" + DocNo;
                    objstudioMaster_upload.studio_wise_instructor_dtl[mprCnt].studio_code = saved_studio_code;
                }

                //// Delete course_weekly_percent_criteria
                //string SqlSelect = "delete from instructor_teaching_interest where user_id='" + UserID + "' and semester_type='" + dt_call_for_studio_current_sem_data.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_call_for_studio_current_sem_data.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";
                //DBCommand.CommandText = SqlSelect;
                //DBCommand.CommandType = CommandType.Text;
                //try { DBCommand.ExecuteNonQuery(); }
                //catch (Exception e) { }

                objInstructorMaster_upload.EnforceConstraints = true;
                //15022022
                objstudioMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo_inst;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objInstructorMaster_upload.instructor_teaching_interest, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                //15022022
                objUpdateTableInfo_inst = BLGeneralUtil.UpdateTable(ref DBCommand, objstudioMaster_upload.studio_wise_instructor_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);

                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objInstructorMaster_upload.instructor_teaching_interest.Rows.Count
                    && objUpdateTableInfo_inst.Status == true && objUpdateTableInfo_inst.TotalRowsAffected != objstudioMaster_upload.studio_wise_instructor_dtl.Rows.Count
                    )
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = saved_studio_code;

                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

