            //Personal Details 0
            SqlSelect = " IF EXISTS(select * from instructor_mst where instructor_code='" + user_id + "' and cancel_flag='N' and is_submit='Y' ) ";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Personal_Details END ELSE BEGIN select 'N' as Personal_Details END ";
            //Teaching Interest 1
            SqlSelect = SqlSelect + " IF EXISTS(select TOP 1 * from instructor_teaching_interest where user_id='" + user_id + "' and cancel_flag='N' and studio_code='" + studio_code + "') ";//semester_type='" + sem_code + "' and year_semester='" + year_code + "' and 
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Teaching_Interest END ELSE BEGIN select 'N' as Teaching_Interest END ";
            //Not Used 2
            SqlSelect = SqlSelect + " IF EXISTS(select * from instructor_studio_details where user_id='" + user_id + "' and cancel_flag='N' and studio_code='" + studio_code + "') ";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Studio_Details END ELSE BEGIN select 'N' as Studio_Details END ";

            //SqlSelect = SqlSelect + " IF EXISTS(select * from instructor_studio_details where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and user_id='" + user_id + "' and cancel_flag='N' and approved='Y') ";
            //SqlSelect = SqlSelect + " BEGIN select 'Y' as Bank_Details END ELSE BEGIN select 'N' as Bank_Details END ";
            //3
            SqlSelect = SqlSelect + " select case (select ISNULL((select bank_account_number from instructor_mst where user_id='" + user_id + "'), 'N')) WHEN '' THEN 'N' WHEN NULL THEN 'N' WHEN 'N' THEN 'N' else 'Y' END as Bank_Details ";
            //4
            SqlSelect = SqlSelect + " IF EXISTS(select * from cpop_superviser_mst where superviser_code='" + user_id + "')";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Core_Faculty END ELSE BEGIN select 'N' as Core_Faculty END ";
            //Check Proposal Uploaded 5
            SqlSelect = SqlSelect + " IF EXISTS(select * from instructor_studio_details where user_id='" + user_id + "' and cancel_flag='N' and studio_code='" + studio_code + "' and (ppt_video IS NOT NULL OR ppt_video <> '')) ";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Studio_Details_Filled END ELSE BEGIN select 'N' as Studio_Details_Filled END ";
            //Check Proposal Submitted 6
            SqlSelect = SqlSelect + " IF EXISTS(select * from instructor_studio_details where user_id='" + user_id + "' and cancel_flag='N' and studio_code='" + studio_code + "' and (ppt_video IS NOT NULL OR ppt_video <> '') and is_submit='Y') ";
            SqlSelect = SqlSelect + " BEGIN select 'Y' as Submitted END ELSE BEGIN select 'N' as Submitted END ";

            DBDataAdpterObject.SelectCommand.CommandType = CommandType.Text;
            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);

                return ds;
            }
            catch (Exception ex)
            {
                ServerLog.ExceptionLog("2. Get_data : " + ex.ToString());
                return null;
            }
        }

