        public DataTable get_studio_tutor_dtl(String semester, String year)//Kapil 06112020
        {
            String SqlSelect = "";

            SqlSelect = "Select instructor_mst.VF_code,instructor_mst.instructor_code,instructor_mst.instructor_name,instructor_mst.mobile_no,instructor_mst.mail," +
                " instructor_mst.cv_file_name, instructor_mst.portfolio_file_name, isd.ppt_video,isd.studio_brief,instructor_mst.is_submit,isd.approved, " +
                " STUFF((select distinct ', ' +  iti.studio_level from instructor_teaching_interest as iti where iti.user_id=instructor_mst.user_id " +
                " FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,2,'')studio_level " +
                " from instructor_mst inner join instructor_teaching_interest as iti on iti.user_id = instructor_mst.user_id " +
                " inner join instructor_studio_details as isd on isd.user_id = instructor_mst.user_id " +
                " where iti.semester_type ='" + semester + "' and iti.year_semester ='" + year + "' and iti.cancel_flag = 'N' and instructor_mst.cancel_flag ='N' " +
                " GROUP BY instructor_mst.VF_code,instructor_mst.instructor_code,instructor_mst.instructor_name," +
                " instructor_mst.mobile_no,instructor_mst.mail, instructor_mst.cv_file_name, " +
                " instructor_mst.portfolio_file_name,instructor_mst.is_submit, " +
                " isd.ppt_video,isd.studio_brief,instructor_mst.is_submit,isd.approved,instructor_mst.user_id " +
                " order by CASE WHEN isd.approved = 'Y' THEN isd.approved END asc, " +
                " CASE WHEN isd.approved = 'N' THEN isd.approved END asc," +
                " CASE WHEN instructor_mst.is_submit = 'N' THEN instructor_mst.is_submit END asc," +
                " CASE WHEN isd.studio_brief Is Null Then 1 Else 0 End asc, " +
                " CASE WHEN isd.ppt_video Is Null THEN 1 Else 0 End asc ";


            return Get_data(SqlSelect);
        }

