        public DataTable get_studio_dtl(String semester, String year, String dept_code, String prog_code, String level_code, String focus_code, String type, String user_id, String user_type)//Kapil 06112020 03032021
        {
            String SqlSelect = "";
            SqlSelect = "Select * from ( ";
            SqlSelect += " Select instructor_mst.VF_code,instructor_mst.instructor_code,instructor_mst.instructor_name,iti.created_date,iti.last_modified_date," +
                " instructor_mst.mobile_no, instructor_mst.cv_file_name, instructor_mst.portfolio_file_name," +
                " isd.ppt_video,isd.studio_brief,instructor_mst.is_submit,isd.approved,instructor_mst.highest_qualification,instructor_mst.mail," +
                " instructor_mst.total_experiance,iti.studio_title,iti.studio_subtitle,iti.studio_level," +
                " isd.studio_code,isd.course_code,isd.new_course_code,iti.no_of_tutor, STUFF((select distinct ', ' +  um.full_name,cm.studio_mode " +
                " from course_wise_instructor as cwi " +
                " inner join user_mst as um on um.user_id = cwi.instructor_code and um.cancel_flag = 'N' " +
                " inner join course_mst as cm on cm.course_code = cwi.course_code and cm.cancel_flag ='N' and cm.semester_type ='" + semester + "' and cm.year_semester ='" + year + "'" +
                " where cwi.tutor_type ='CT'and cwi.instructor_code=instructor_mst.user_id  FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,2,'')co_tutor_type, " +
                " iti.teaching_mode as mode," +
                " (select top(1)  work_institute from instructor_academic_work_dtl where detail_type='work' and instructor_code =instructor_mst.instructor_code  order by work_end_date desc) work_institute," +
                " (select top(1)  work_designation from instructor_academic_work_dtl where detail_type='work' and instructor_code =instructor_mst.instructor_code  order by work_end_date desc) work_designation, " +
                " dwcd.focus_studio,dwcd.secondary_focus_studio,iti.dept_code,iti.prog_code,iti.prog_level_code,dm.dept_name,plm.prog_level_name,instructor_mst.city, " +
                " iti.previous_sem_code,iti.previous_year_code,iti.previous_sem_course_code,iti.studio_description, " +
                " iwd.admin_approved as iwd_admin_approved,iwd.hr_approved as iwd_hr_approved , " +
                " iwd.uso_hr_approved as iwd_uso_hr_approved,instructor_mst.admin_approved as im_admin_approved ,instructor_mst.rateband_approved as im_rateband_approved, " +
                " instructor_mst.hr_approved as im_hr_approved,iwss.status as iwss_Status,cm_n.weekly_excercises_path," +
                " studio_inst.tutor_type as new_tutor_type,studio_inst.to_be_later,studio_inst.shortlist " +
                " ,studio_inst.hr_remark,studio_inst.hr_status,studio_inst.pc_remark,studio_inst.pc_status,Case when StudioMailStatus.mailsendstatus = 'Y' Then 'Mail Send Successfully' Else 'N' End as mailstatus" +
                " from instructor_mst " +
                " inner join instructor_teaching_interest as iti on iti.user_id = instructor_mst.user_id and iti.semester_type ='" + semester + "' and iti.year_semester='" + year + "' " +
                " left join instructor_studio_details as isd on isd.user_id = instructor_mst.user_id and (isd.studio_code = iti.studio_code or isd.studio_code = 'temp' or isd.studio_code Is Null) and isd.cancel_flag ='N' " +
                " and isd.semester_type = iti.semester_type and isd.year_semester = iti.year_semester " +
                " left join department_wise_course_dtl as dwcd on dwcd.course_code = CASE WHEN (isd.new_course_code IS NOT NULL AND isd.new_course_code != '') THEN isd.new_course_code ELSE isd.course_code END " +
                " and dwcd.semester_type = iti.semester_type and dwcd.year_semester = iti.year_semester " +
                " left join department_mst as dm on dm.dept_code = iti.dept_code " +
                " left join programme_level_mst as plm on plm.prog_level_code = iti.prog_level_code " +
                " left join instructor_workload_detail iwd on iwd.instructor_code = isd.user_id " +
                " and iwd.course_code = isd.course_code and iwd.semester_type = isd.semester_type " +
                " and iwd.year_semester = isd.year_semester and iwd.cancel_flag='N' " +
                " LEFT join course_mst cm_n on cm_n.course_code = isd.new_course_code and cm_n.semester_type = isd.semester_type and cm_n.year_semester = isd.year_semester " +
                " left join instructor_wise_shortlist_studio_proposal_dtl iwss on iwss.user_id = iti.user_id " +
                " and iwss.studio_code = iti.studio_code and iwss.semester_type = iti.semester_type and iwss.year_semester = iti.year_semester and iwss.cancel_flag='N' and iwss.status='A' ";
            if (user_type == "PC")
            {
                SqlSelect = SqlSelect + " inner join programme_coordinator_dtl pc on pc.dept_code = iti.dept_code and pc.prog_code = iti.prog_code " +
                    " and pc.semester_type = iti.semester_type and pc.year_semester = iti.year_semester and pc.cancel_flag ='N' and pc.user_id ='" + user_id + "'" +
                    " and ISNULL(iti.prog_level_code,'')=ISNULL(pc.prog_level_code,'') ";
            }
            if (user_type == "D")
            {
                SqlSelect = SqlSelect + " inner join dean_dtl dean on dean.dept_code = iti.dept_code and dean.prog_code = iti.prog_code " +
                    " and dean.semester_type = iti.semester_type and dean.year_semester = iti.year_semester and dean.cancel_flag ='N' and dean.user_id ='" + user_id + "' ";
            }

            SqlSelect += " left join studio_wise_instructor_dtl as studio_inst on studio_inst.studio_code = iti.studio_code " +
                " and studio_inst.instructor_code = instructor_mst.instructor_code ";

            SqlSelect += @" LEFT JOIN StudioMailStatus on StudioMailStatus.studio_code = iti.studio_code 
                            and StudioMailStatus.instructor_code = instructor_mst.instructor_code  and StudioMailStatus.cancel_flag='N' 
                            and StudioMailStatus.email_desc = 
                            Case When studio_inst.tutor_type = 'T' Then 'HR Studio Proposal Authorized'
                            When studio_inst.tutor_type = 'CT' Then 'StudioProposalAuthorized_CT' Else '' End
                            and StudioMailStatus.mailsendstatus='Y' ";

            SqlSelect += " where iti.semester_type ='" + semester + "' and iti.year_semester ='" + year + "' and iti.cancel_flag = 'N' and instructor_mst.cancel_flag ='N'";
            if (dept_code != "")
            {
                SqlSelect += " and iti.dept_code='" + dept_code + "'";
            }
            if (prog_code != "")
            {
                SqlSelect += " and iti.prog_code='" + prog_code + "'";
            }

            if (type == "P")
            {
                SqlSelect += " and isd.is_submit='Y' ";

            }
            if (type == "S")
            {
                SqlSelect += " and isd.is_submit='Y' and ( isd.ppt_video Is Null and isd.studio_brief_status = 'Y' or isd.studio_brief_status = 'S') ";
            }

            if (type == "Y")
            {
                SqlSelect += " and isd.is_submit='Y' and ( isd.ppt_video Is Null and isd.studio_brief_status = 'A') ";
            }
            if (type == "PC")
            {
                SqlSelect += " and studio_inst.pc_status ='R' ";
            }
            if (type == "SPC")
            {
                SqlSelect += " and studio_inst.pc_status ='A' ";
            }
            if (type == "HR")
            {
                SqlSelect += " and studio_inst.hr_status ='R' ";
            }
            if (level_code != "")
            {
                SqlSelect += " and iti.studio_level='" + level_code + "'";
            }
            if (focus_code != "" && focus_code != null && focus_code != "null")
            {
                SqlSelect += " and ( dwcd.focus_studio = '" + focus_code + "' or dwcd.secondary_focus_studio ='" + focus_code + "')";
            }

            SqlSelect += " UNION ";

            SqlSelect += " Select  instructor_mst.VF_code,instructor_mst.instructor_code,instructor_mst.instructor_name, " +
                " iti.created_date,iti.last_modified_date, instructor_mst.mobile_no, instructor_mst.cv_file_name,  " +
                " instructor_mst.portfolio_file_name, isd.ppt_video,isd.studio_brief,instructor_mst.is_submit,swid.approved , " +
                " instructor_mst.highest_qualification,instructor_mst.mail, instructor_mst.total_experiance,iti.studio_title,iti.studio_subtitle, " +
                " iti.studio_level, isd.studio_code,isd.course_code,isd.new_course_code,iti.no_of_tutor, STUFF((select distinct ', ' +  um.full_name,cm.studio_mode  " +
                " from course_wise_instructor as cwi " +
                " inner join user_mst as um on um.user_id = cwi.instructor_code and um.cancel_flag = 'N'  " +
                " inner join course_mst as cm on cm.course_code = cwi.course_code and cm.cancel_flag ='N'  " +
                " and cm.semester_type ='" + semester + "' and cm.year_semester ='" + year + "' where cwi.tutor_type ='CT' " +
                " and cwi.instructor_code=instructor_mst.user_id  FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,2,'')co_tutor_type, iti.teaching_mode as mode, " +
                " (select top(1)  work_institute from instructor_academic_work_dtl where detail_type='work' and instructor_code =instructor_mst.instructor_code  order by work_end_date desc) work_institute, " +
                " (select top(1)  work_designation from instructor_academic_work_dtl where detail_type='work' and instructor_code =instructor_mst.instructor_code  order by work_end_date desc) work_designation, " +
                " dwcd.focus_studio,dwcd.secondary_focus_studio,iti.dept_code,iti.prog_code,iti.prog_level_code,dm.dept_name,plm.prog_level_name,instructor_mst.city,  iti.previous_sem_code,iti.previous_year_code, " +
                " iti.previous_sem_course_code,iti.studio_description, iwd.admin_approved as iwd_admin_approved,iwd.hr_approved as iwd_hr_approved , " +
                " iwd.uso_hr_approved as iwd_uso_hr_approved,instructor_mst.admin_approved as im_admin_approved,instructor_mst.rateband_approved as im_rateband_approved, " +
                " instructor_mst.hr_approved as im_hr_approved,iwss.status as iwss_Status,cm_n.weekly_excercises_path," +
                " swid.tutor_type as new_tutor_type,swid.to_be_later,swid.shortlist" +
                " ,swid.hr_remark,swid.hr_status,swid.pc_remark,swid.pc_status,Case when StudioMailStatus.mailsendstatus = 'Y' Then 'Mail Send Successfully' Else 'N' End as mailstatus " +
                " from studio_wise_instructor_dtl  swid " +
                " inner join instructor_mst on instructor_mst.instructor_code = swid.instructor_code and swid.cancel_flag='N'  " +
                " inner join instructor_teaching_interest as iti on iti.studio_code = swid.studio_code and iti.semester_type ='" + semester + "' and iti.year_semester='" + year + "' " +
                " left join instructor_studio_details as isd on isd.studio_code = iti.studio_code " +
                " and isd.cancel_flag ='N'  and isd.semester_type = iti.semester_type and isd.year_semester = iti.year_semester " +
                " left join department_wise_course_dtl as dwcd on dwcd.course_code = CASE WHEN (isd.new_course_code IS NOT NULL AND isd.new_course_code != '') THEN isd.new_course_code ELSE isd.course_code END " +
                " and dwcd.semester_type = iti.semester_type " +
                " and dwcd.year_semester = iti.year_semester " +
                " left join department_mst as dm on dm.dept_code = iti.dept_code " +
                " left join programme_level_mst as plm on plm.prog_level_code = iti.prog_level_code " +
                " left join instructor_workload_detail iwd on iwd.instructor_code = swid.instructor_code " +
                " and iwd.course_code = isd.course_code and iwd.semester_type = swid.semester_type " +
                " and iwd.year_semester = swid.year_semester and iwd.cancel_flag='N' " +
                " left join course_mst cm_n on cm_n.course_code = isd.new_course_code and cm_n.semester_type = isd.semester_type  " +
                " and cm_n.year_semester = isd.year_semester " +
                " left join instructor_wise_shortlist_studio_proposal_dtl iwss on iwss.studio_code = iti.studio_code and iwss.semester_type = iti.semester_type " +
                " and iwss.year_semester = iti.year_semester and iwss.cancel_flag='N' and iwss.status='A' ";

            if (user_type == "PC")
            {
                SqlSelect = SqlSelect + " inner join programme_coordinator_dtl pc on pc.dept_code = iti.dept_code and pc.prog_code = iti.prog_code " +
                    " and pc.semester_type = iti.semester_type and pc.year_semester = iti.year_semester and pc.cancel_flag ='N' and pc.user_id ='" + user_id + "'" +
                    " and ISNULL(iti.prog_level_code,'')=ISNULL(pc.prog_level_code,'') ";
            }
            if (user_type == "D")
            {
                SqlSelect = SqlSelect + " inner join dean_dtl dean on dean.dept_code = iti.dept_code and dean.prog_code = iti.prog_code " +
                    " and dean.semester_type = iti.semester_type and dean.year_semester = iti.year_semester and dean.cancel_flag ='N' and dean.user_id ='" + user_id + "' ";
            }

            SqlSelect = SqlSelect + @" left join StudioMailStatus on StudioMailStatus.studio_code = iti.studio_code 
                                       And StudioMailStatus.instructor_code = instructor_mst.instructor_code  and StudioMailStatus.cancel_flag='N' 
                                       and StudioMailStatus.email_desc = 
                                       Case When swid.tutor_type = 'T' Then 'HR Studio Proposal Authorized'
                                       When swid.tutor_type = 'CT' Then 'StudioProposalAuthorized_CT' Else '' End
                                       and StudioMailStatus.mailsendstatus='Y' ";


            SqlSelect = SqlSelect + " where iti.semester_type ='" + semester + "' and iti.year_semester ='" + year + "' and iti.cancel_flag = 'N' and instructor_mst.cancel_flag ='N' " +
                " and swid.semester_type ='" + semester + "' and swid.year_semester ='" + year + "' and swid.cancel_flag ='N' ";

            if (dept_code != "")
            {
                SqlSelect += " and iti.dept_code='" + dept_code + "'";
            }
            if (prog_code != "")
            {
                SqlSelect += " and iti.prog_code='" + prog_code + "'";
            }

            //if (type == "Y")
            //{
            //
            //    SqlSelect += " and isd.is_submit='Y' and ( isd.ppt_video Is Null and isd.studio_brief_status = 'Y' or isd.studio_brief_status = 'A') ";
            //
            //}
            if (type == "P")
            {
                SqlSelect += " and isd.is_submit='Y' ";

            }
            if (type == "S")
            {
                SqlSelect += " and isd.is_submit='Y' and ( isd.ppt_video Is Null and isd.studio_brief_status = 'Y' or isd.studio_brief_status = 'S') ";
            }

            if (type == "Y")
            {
                SqlSelect += " and isd.is_submit='Y' and ( isd.ppt_video Is Null and isd.studio_brief_status = 'A') ";
            }
            if (type == "PC")
            {
                SqlSelect += " and swid.pc_status ='R' ";
            }
            if (type == "SPC")
            {
                SqlSelect += " and swid.pc_status ='A' ";
            }
            if (type == "HR")
            {
                SqlSelect += " and swid.hr_status ='R' ";
            }

            if (level_code != "")
            {
                SqlSelect += " and iti.studio_level='" + level_code + "'";
            }
            if (focus_code != "" && focus_code != null && focus_code != "null")
            {
                SqlSelect += " and ( dwcd.focus_studio = '" + focus_code + "' or dwcd.secondary_focus_studio ='" + focus_code + "')";
            }
            SqlSelect = SqlSelect + " ) as t1  order by t1.studio_code desc ";
            //order by CASE WHEN t1.created_date Is Null  THEN 1 Else 0 End asc, CASE WHEN t1.approved = 'Y' THEN t1.approved END asc
            return Get_data(SqlSelect);
        }

