        public string Download_Document(String instructor_code, string cv_file_name, string portfolio_file_name, string ppt_video, string studio_brief, string weekly_excercises_path)
        {
            try
            {
                string CVPath = HttpContext.Current.Server.MapPath("~/InstructorCVUpload");
                string PortfolioPath = HttpContext.Current.Server.MapPath("~/InstructorPortfolioUpload");
                string StudioPath = HttpContext.Current.Server.MapPath("~/StudioDetails");
                string course_code = HttpContext.Current.Server.MapPath("~/ExercisesPDF");
                List<string> ExitsFile = new List<string>();
                string CV_file = CVPath + "\\" + cv_file_name;
                if (File.Exists(CV_file))
                {
                    ExitsFile.Add(CV_file);
                }
                string Portfolio_file = PortfolioPath + "\\" + portfolio_file_name;
                if (File.Exists(Portfolio_file))
                {
                    ExitsFile.Add(Portfolio_file);
                }
                string Studio_file = StudioPath + "\\" + ppt_video;
                if (File.Exists(Studio_file))
                {
                    ExitsFile.Add(Studio_file);
                }

                string Studio_file_1 = StudioPath + "\\" + studio_brief;
                if (File.Exists(Studio_file_1))
                {
                    ExitsFile.Add(Studio_file_1);
                }

                string course_code_path = course_code + "\\" + weekly_excercises_path;
                if (File.Exists(course_code_path))
                {
                    ExitsFile.Add(course_code_path);
                }

                string FolderPathToZip = CVPath + "\\" + "Document";
                if (File.Exists(FolderPathToZip))
                {
                    File.Delete(FolderPathToZip);
                }
                if (ExitsFile.Count > 0)
                {
                    using (ZipFile zip = new ZipFile())
                    {
                        zip.AddFiles(ExitsFile.ToArray(), "Document");
                        zip.Save(FolderPathToZip + ".zip");
                    }
                }
                else
                {
                    return "2";
                }
            }
            catch (Exception ex)
            {
                return "2";
            }

            return "1";
        }


