        public DataTable Export_Excel_File(String instructor_code, String semester, String year)
        {
            String SqlSelect = "";

            SqlSelect = "Select distinct instructor_mst.VF_code as 'VF Code',instructor_mst.instructor_code as 'Instructor Code'," +
                " instructor_mst.instructor_name as Name,instructor_mst.mobile_no as 'Mobile Number',instructor_mst.mail as 'Email Id', " +
                " instructor_mst.highest_qualification as Qualification,instructor_mst.total_experiance as 'Total Experiance',instructor_mst.address as Address" +
                " from instructor_mst inner join instructor_teaching_interest as iti on iti.user_id = instructor_mst.user_id " +
                " left join instructor_studio_details as isd on isd.user_id = instructor_mst.user_id " +
                " where iti.semester_type ='" + semester + "' and iti.year_semester ='" + year + "' and iti.cancel_flag = 'N' and instructor_mst.cancel_flag ='N'" +
                " and instructor_mst.instructor_code ='" + instructor_code + "'";

            return Get_data(SqlSelect);
        }

        public string approve_call_for_studio_dtl(string instructor_code, string semester, string year_code, string user_id, string host_name)
        {
            /*************************/
            /* ESTABLISH CONNECTION */

            /*************************/
            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "update instructor_studio_details set approved ='Y',last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where semester_type = '" + semester + "' and year_semester = '" + year_code + "'and user_id ='" + instructor_code + "' and cancel_flag='N'";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return "1";
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return "2";
            }
        }

        public DataTable GetProgramsByStudioLevels()
        {
            String SqlSelect = @" SELECT programme_level_mst.prog_level_name,studio_teaching_interest_mst.* FROM studio_teaching_interest_mst
                            LEFT JOIN programme_level_mst ON programme_level_mst.prog_level_code = studio_teaching_interest_mst.prog_level_code
                            where studio_teaching_interest_mst.temp_user = 'N' AND studio_teaching_interest_mst.cancel_flag ='N' ORDER BY prog_level_code ";//studio_lvel

            return Get_data(SqlSelect);
        }

