        public Boolean update_interested_program(string user_id, Dictionary<string, object> data)
        {
            string dd = data["studio_title"].ToString().Replace("&#39;", "''");
            dd = dd.Replace("&#34;", "\"");
            dd = dd.Replace("&#40;", "(");
            dd = dd.Replace("&#41;", "(");
            dd = dd.Replace("&#60;", "<");
            dd = dd.Replace("&#62;", ">");
            dd = dd.Replace("&#64;", "@");
            dd = dd.Replace("&#38;", "&");
            dd = dd.Replace("&#47;", "/");


            string studio_description = data["studio_description"].ToString().Replace("&#39;", "''");
            studio_description = studio_description.Replace("&#34;", "\"");
            studio_description = studio_description.Replace("&#40;", "(");
            studio_description = studio_description.Replace("&#41;", "(");
            studio_description = studio_description.Replace("&#60;", "<");
            studio_description = studio_description.Replace("&#62;", ">");
            studio_description = studio_description.Replace("&#64;", "@");
            studio_description = studio_description.Replace("&#38;", "&");
            studio_description = studio_description.Replace("&#47;", "/");


            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            //dept_code,prog_code,prog_level_code,studio_level
            SqlSelect = "update instructor_teaching_interest set studio_title ='" + dd + "' , " +
                        " no_of_tutor = '" + data["no_of_tutor"] + "' , " +
                        " dept_code = '" + data["dept_code"] + "' , " +
                        " prog_code = '" + data["prog_code"] + "' , " +
                        " prog_level_code = '" + data["prog_level_code"] + "' , " +
                        " studio_level = '" + data["studio_level"] + "' , " +
                        " teaching_mode = '" + data["teaching_mode"] + "' , " +
                        " last_modified_by = '" + user_id + "' , " +
                        " last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , " +
                        " last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ," +
                        " studio_description = '" + studio_description + "', " +
                        " previous_sem_course_code = '" + data["previous_sem_course_code"] + "', " +
                        " previous_sem_code = '" + data["previous_sem_code"] + "', " +
                        " previous_type = '" + data["previous_type"] + "', " +
                        " Portfolio_change_type= '" + data["Portfolio_change_type"] + "', " +
                        " previous_year_code = '" + data["previous_year_code"] + "' " +
                        " where user_id = '" + user_id + "' and studio_code = '" + data["studio_code"] + "' ";

            SqlSelect += " Delete studio_wise_instructor_dtl where studio_code = '" + data["studio_code"] + "' and cancel_flag ='N' ";

            string[] inst_data = data["inst_code"].ToString().Split(',');
            string[] tutor_data = data["tutor_type"].ToString().Split(',');
            string[] brief_edit_status = data["brief_edit_status"].ToString().Split(',');
            string[] to_be_later = data["to_be_later"].ToString().Split(',');
            for (int i = 0; i < inst_data.Length; i++)
            {
                SqlSelect += "insert into studio_wise_instructor_dtl (studio_code,instructor_code,approved,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,brief_edit_status,to_be_later,shortlist,tutor_type) " +
                                     " VALUES('" + data["studio_code"] + "' , '" + inst_data[i].ToString() + "', 'N' ,'" + data["sem"] + "','" + data["year"] + "', 'N' ,'" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + HttpContext.Current.Request.UserHostName + "', '" + brief_edit_status[i].ToString() + "'";
                if (to_be_later[i].ToString() == "Y")
                {
                    SqlSelect += " , 'Y',NULL,NULL)";
                }
                else
                {
                    SqlSelect += " , NULL,NULL,'" + tutor_data[i].ToString() + "')";
                }

            }


            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception)
            {
                DBConnection.Close();
                return false;
            }
        }

        public DataTable Get_studio_proposal_dtls(String semester, String year, String user_id, String user_type, String dept_code, String prog_level, String studio_level, String type, String prog_code)
        {

            String SqlSelect = "";
            if (user_type == "A1")
            {
                SqlSelect = "";
                SqlSelect = " Select *,iwd.admin_approved as iwd_admin_approved,iwd.hr_approved as iwd_hr_approved ," +
                            " iwd.uso_hr_approved as iwd_uso_hr_approved,im.admin_approved as im_admin_approved ,im.rateband_approved as im_rateband_approved," +
                            " im.hr_approved as im_hr_approved,iwss.status as iwss_Status " +
                            " from instructor_teaching_interest as iti " +
                            " inner join user_mst as usm on usm.user_id = iti.user_id " +
                            " inner join programme_level_mst as plm on plm.prog_level_code = iti.prog_level_code and plm.cancel_flag ='N' " +
                            " left join instructor_studio_details as isd on isd.user_id = iti.user_id " +
                            " and isd.semester_type = iti.semester_type and isd.year_semester = iti.year_semester and isd.studio_code = iti.studio_code and isd.cancel_flag ='N' " +
                            " inner join department_mst as dm on dm.dept_code = iti.dept_code and dm.cancel_flag ='N' " +
                            " left join instructor_workload_detail iwd on iwd.instructor_code = isd.user_id " +
                            " and iwd.course_code = isd.course_code and iwd.semester_type = isd.semester_type " +
                            " and iwd.year_semester = isd.year_semester and iwd.cancel_flag='N' " +
                            " left join instructor_wise_shortlist_studio_proposal_dtl iwss on iwss.user_id = iti.user_id " +
                            " and iwss.studio_code = iti.studio_code " +
                            " and iwss.semester_type = iti.semester_type and iwss.year_semester = iti.year_semester and iwss.cancel_flag='N' and iwss.status='A' " +
                            " inner join instructor_mst im on im.user_id = iti.user_id " +
                            " where iti.cancel_flag ='N' and iti.semester_type ='" + semester + "' and iti.year_semester ='" + year + "'";

                if (dept_code != "")
                {
                    SqlSelect += " and iti.dept_code ='" + dept_code + "'";
                }
                if (prog_level != "")
                {
                    SqlSelect += " and iti.prog_level_code ='" + prog_level + "'";
                }
                if (prog_code != "")
                {
                    SqlSelect += " and iti.prog_code ='" + prog_code + "'";
                }
                if (studio_level != "")
                {
                    SqlSelect += " and iti.studio_level ='" + studio_level + "'";
                }

                if (user_type == "I2")
                {
                    SqlSelect += " and iti.user_id ='" + user_id + "'";
                }
                else
                {
                    if (type == "Y")
                    {
                        SqlSelect += " and isd.is_submit = 'Y' and (isd.studio_brief_status = 'Y' or isd.studio_brief_status ='A')";
                    }
                    else if (type == "S")
                    {
                        //SqlSelect += " and isd.is_submit = 'Y' and isd.approved = 'Y' and (isd.studio_brief_status ='N' or isd.studio_brief_status ='S')";
                        SqlSelect += " and isd.is_submit = 'S' and (isd.studio_brief_status ='N' or isd.studio_brief_status ='S')";
                    }
                    else
                    {
                        // SqlSelect += " and isd.is_submit = 'Y' and isd.approved = 'N' and isd.studio_brief_status ='N'";

                    }

                }

            }
            else if (user_type == "PC")
            {
                SqlSelect = "";
                SqlSelect = " Select *,iwd.admin_approved as iwd_admin_approved,iwd.hr_approved as iwd_hr_approved ," +
                            " iwd.uso_hr_approved as iwd_uso_hr_approved,im.admin_approved as im_admin_approved ,im.rateband_approved as im_rateband_approved," +
                            " im.hr_approved as im_hr_approved,iwss.status as iwss_Status " +
                            " from instructor_teaching_interest as iti " +
                            " inner join user_mst as usm on usm.user_id = iti.user_id " +
                            " inner join programme_level_mst as plm on plm.prog_level_code = iti.prog_level_code and plm.cancel_flag ='N' " +
                            " left join instructor_studio_details as isd on isd.user_id = iti.user_id  and isd.semester_type = iti.semester_type " +
                            " and isd.year_semester = iti.year_semester and isd.studio_code = iti.studio_code and isd.cancel_flag ='N' " +
                            " left join course_mst as cm on cm.course_code = isd.course_code  and cm.semester_type = isd.semester_type  and cm.year_semester = isd.year_semester and isd.cancel_flag ='N' " +
                            " inner join department_mst as dm on dm.dept_code = iti.dept_code and dm.cancel_flag ='N' " +
                            " inner join programme_coordinator_dtl as pcd on pcd.dept_code = iti.dept_code and pcd.prog_code = iti.prog_code " +
                            " and pcd.semester_type = iti.semester_type and pcd.year_semester = iti.year_semester " +
                            " left join instructor_workload_detail iwd on iwd.instructor_code = isd.user_id " +
                            " and iwd.course_code = isd.course_code and iwd.semester_type = isd.semester_type " +
                            " and iwd.year_semester = isd.year_semester and iwd.cancel_flag='N' " +
                            " left join instructor_wise_shortlist_studio_proposal_dtl iwss on iwss.user_id = iti.user_id " +
                            " and iwss.studio_code = iti.studio_code " +
                            " and iwss.semester_type = iti.semester_type and iwss.year_semester = iti.year_semester and iwss.cancel_flag='N' and iwss.status='A' " +
                            " inner join instructor_mst im on im.user_id = iti.user_id " +
                            " where iti.cancel_flag ='N' and iti.semester_type ='" + semester + "' and iti.year_semester ='" + year + "' and isd.is_submit = 'Y'" +
                            " and pcd.prog_code = iti.prog_code and pcd.semester_type ='" + semester + "' and pcd.year_semester ='" + year + "' and pcd.cancel_flag ='N'" +
                            " and ISNULL(iti.prog_level_code,'') = ISNULL(pcd.prog_level_code,'') and pcd.user_id ='" + user_id + "'";
                if (dept_code != "")
                {
                    SqlSelect += " and iti.dept_code ='" + dept_code + "'";
                }
                if (prog_level != "")
                {
                    SqlSelect += " and iti.prog_level_code ='" + prog_level + "'";
                }
                if (prog_code != "")
                {
                    SqlSelect += " and iti.prog_code ='" + prog_code + "'";
                }
                if (studio_level != "")
                {
                    SqlSelect += " and iti.studio_level ='" + studio_level + "'";
                }
            }
            else
            {
                SqlSelect = "";
                SqlSelect = " Select swid.studio_code, iti.semester_type,iti.year_semester,iti.studio_title,iti.no_of_tutor,iti.studio_level,iti.teaching_mode,iti.studio_description,iti.previous_sem_course_code," +
                    " iti.previous_sem_code,iti.previous_year_code,usm.user_id,usm.user_name,usm.user_type, " +
                    " plm.prog_level_code,plm.prog_level_desc,plm.prog_level_name,isd.approved,isd.is_submit,isd.studio_brief_status, " +
                    " isd.course_code,isd.new_course_code,dm.dept_name,dm.dept_code,iwss.status as iwss_Status, ";
                SqlSelect += " iwd.admin_approved as iwd_admin_approved,iwd.hr_approved as iwd_hr_approved ," +
                            " iwd.uso_hr_approved as iwd_uso_hr_approved,im.admin_approved as im_admin_approved ,im.rateband_approved as im_rateband_approved," +
                            " im.hr_approved as im_hr_approved,iwss.status as iwss_Status,swid.tutor_type,swid.brief_edit_status,swid.to_be_later,swid.shortlist " +
                            " from studio_wise_instructor_dtl as swid " +
                            " inner join instructor_teaching_interest as iti on iti.studio_code = swid.studio_code " +
                            " inner join user_mst as usm on usm.user_id = swid.instructor_code " +
                            " inner join programme_level_mst as plm on plm.prog_level_code = iti.prog_level_code and plm.cancel_flag ='N' " +
                            " left join instructor_studio_details as isd on isd.user_id = iti.user_id " +
                            " and isd.semester_type = iti.semester_type and isd.year_semester = iti.year_semester and isd.studio_code = iti.studio_code and isd.cancel_flag ='N' " +
                            " inner join department_mst as dm on dm.dept_code = iti.dept_code and dm.cancel_flag ='N' " +
                            " left join instructor_workload_detail iwd on iwd.instructor_code = swid.instructor_code " +
                            " and iwd.course_code = isd.course_code and iwd.semester_type = isd.semester_type " +
                            " and iwd.year_semester = isd.year_semester and iwd.cancel_flag='N' " +
                            " left join instructor_wise_shortlist_studio_proposal_dtl iwss on iwss.user_id = iti.user_id " +
                            " and iwss.studio_code = iti.studio_code " +
                            " and iwss.semester_type = iti.semester_type and iwss.year_semester = iti.year_semester and iwss.cancel_flag='N' and iwss.status='A' " +
                            " inner join instructor_mst im on im.user_id = swid.instructor_code " +
                            " where iti.cancel_flag ='N' and iti.semester_type ='" + semester + "' and iti.year_semester ='" + year + "'" +
                            " and swid.cancel_flag='N' and swid.semester_type='" + semester + "' and swid.year_semester='" + year + "' ";

                if (user_type == "I2")
                {
                    SqlSelect += " and swid.instructor_code ='" + user_id + "'";
                }
                else
                {
                    SqlSelect += " and isd.is_submit = 'Y' ";
                }
                if (dept_code != "")
                {
                    SqlSelect += " and iti.dept_code ='" + dept_code + "'";
                }
                if (prog_code != "")
                {
                    SqlSelect += " and iti.prog_code ='" + prog_code + "'";
                }
                if (prog_level != "")
                {
                    SqlSelect += " and iti.prog_level_code ='" + prog_level + "'";
                }
                if (studio_level != "")
                {
                    SqlSelect += " and iti.studio_level ='" + studio_level + "'";
                }
                SqlSelect += " order by swid.studio_code desc ";
            }
            return Get_data(SqlSelect);
        }

