        public DataTable Get_pending_course_details(string sem_code, string year_code, string user_id)    //changes by Aashitha 10262023
        {
            String SqlSelect = "";
            SqlSelect += @" select  cm.course_code,im.designation,um.user_type,iwd.instructor_code,iwd.remark,cm.course_name,iwd.uso_hr_approved,
							 iwd.hr_approved,iwd.admin_approved  from instructor_workload_detail iwd
                            inner join course_mst cm on cm.course_code = iwd.course_code
                            and cm.semester_type= iwd.semester_type and cm.year_semester= iwd.year_semester
                            inner join instructor_mst im on im.instructor_code = iwd.instructor_code
							inner join user_mst um on um.user_id = iwd.instructor_code
                            where iwd.semester_type='" + sem_code + "' and iwd.year_semester ='" + year_code + "' and iwd.cancel_flag='N' and iwd.instructor_code='" + user_id + "' and iwd.course_code in (select course_code from department_wise_course_dtl where semester_type='" + sem_code + "' and year_semester ='" + year_code + "'  and cancel_flag IN('N','Y') and course_typology in ('24'))";

            SqlSelect += @" Union ";

            SqlSelect += @" select  cm.course_code,im.designation,um.user_type,iwd.instructor_code,iwd.remark,cm.course_name,iwd.uso_hr_approved,
							 iwd.hr_approved,iwd.admin_approved  from instructor_workload_detail iwd
                            inner join course_mst cm on cm.course_code = iwd.course_code
                            and cm.semester_type= iwd.semester_type and cm.year_semester= iwd.year_semester
                            inner join instructor_mst im on im.instructor_code = iwd.instructor_code
							inner join user_mst um on um.user_id = iwd.instructor_code
                            where iwd.semester_type='" + sem_code + "' and iwd.year_semester ='" + year_code + "' and iwd.cancel_flag='N' and iwd.instructor_code='" + user_id + @"' 
							and iwd.course_code in (select course_code from department_wise_course_dtl where semester_type='" + sem_code + @"' and year_semester ='" + year_code + @"' and dept_code='9'  and cancel_flag IN('N','Y') and course_typology='23') ";


            return Get_data(SqlSelect);
        }




