        public Boolean studio_user_deletes(string detalis, string user_id, string user_type)
        {
            string[] details_value = detalis.Split('_');
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            string SqlSelect = "";

            SqlSelect = @"UPDATE instructor_studio_details SET cancel_flag='Y', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and user_id='" + details_value[2].ToString() + "' and semester_type='" + details_value[0].ToString() + "' and year_semester='" + details_value[1].ToString() + "' and studio_code ='" + details_value[3].ToString() + "'";

            SqlSelect = SqlSelect + @"UPDATE instructor_teaching_interest SET cancel_flag='Y', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and user_id='" + details_value[2].ToString() + "' and semester_type='" + details_value[0].ToString() + "' and year_semester='" + details_value[1].ToString() + "'and studio_code ='" + details_value[3].ToString() + "'";
            //17022022
            SqlSelect = SqlSelect + @"UPDATE studio_wise_instructor_dtl SET cancel_flag='Y', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and semester_type='" + details_value[0].ToString() + "' and year_semester='" + details_value[1].ToString() + "'and studio_code ='" + details_value[3].ToString() + "'";

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }


        public DataTable tutor_wise_brief_right(string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = @" Select swid.instructor_code user_id,swid.approved,isd.semester_type,
                        isd.year_semester,isd.studio_brief, isd.is_submit,isd.studio_code,isd.studio_brief_status,isd.course_code, 
                        iti.dept_code,iti.prog_code,iti.prog_level_code,iti.studio_level,  iti.studio_title,iti.no_of_tutor,
                        iti.teaching_mode,iti.studio_description,iti.previous_sem_course_code,  
                        iti.previous_sem_code,iti.previous_year_code,department_mst.dept_name ,iwssp.status as shortlist_status ,
                        im.total_experiance,um.full_name,pm.prog_name,  im.highest_qualification,im.designation as inst_designation,im.mail, 
                        im.cv_file_name, im.portfolio_file_name,isd.ppt_video,  im.admin_approved,im.rateband_approved,
                        im.hr_approved,iwd.admin_approved instructor_workload_admin_approved, iwd.hr_approved instructor_workload_hr_approved,
                        iwd.uso_hr_approved instructor_workload_uso_hr_approved,ISNULL(cpop.cancel_flag,'Y') as cpop_user_status,
                        cm.name as country_name,iwssp.hr_status,iwssp.hr_remark,swid.brief_edit_status,swid.tutor_type   
                        from instructor_studio_details as isd 
                        inner join instructor_teaching_interest as iti on iti.semester_type = isd.semester_type  
                        and iti.year_semester = isd.year_semester and iti.cancel_flag = isd.cancel_flag  
                        and isd.studio_code = iti.studio_code 
                        inner join studio_wise_instructor_dtl as swid on swid.studio_code = isd.studio_code and swid.cancel_flag ='N'  
                        inner join department_mst on department_mst.dept_code = iti.dept_code  
                        inner join instructor_mst as im on im.instructor_code = swid.instructor_code  
                        left join user_mst as um on um.user_id = swid.instructor_code 
                        inner join programme_mst as pm on pm.prog_code = iti.prog_code  
                        inner join instructor_wise_shortlist_studio_proposal_dtl as iwssp on iwssp.studio_code = isd.studio_code  
                        and iwssp.semester_type = isd.semester_type  and iwssp.year_semester = isd.year_semester and iwssp.cancel_flag ='N' 
                        left join instructor_workload_detail iwd on iwd.course_code = isd.course_code  and iwd.instructor_code = swid.instructor_code 
                        and iwd.semester_type = isd.semester_type and iwd.year_semester = isd.year_semester  and iwd.cancel_flag ='N' 
                        left join cpop_superviser_mst cpop on cpop.superviser_code = swid.instructor_code and cpop.cancel_flag = 'N' 
                        left join country_mst cm on cm.id = im.indian_citizen  
                        where isd.is_submit ='Y' and swid.approved ='Y' and swid.tutor_type  ='CT'
                        and  iwssp.status ='A'  and isd.semester_type ='" + sem_code + "' and isd.year_semester='" + year_code + "'";
            return Get_data(SqlSelect);
        }




        public Boolean Give_rights_for_temp_vf_user(string user_id, string host_name, string instructor_code, string instructor_name, string cancel_flag, string email, string user_type, string des_letter)
        {

            DataTable dt_instructor_dtl = get_instructor_dtl(instructor_code);
            string vf_code = "";

            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            string designation = "";

            if (user_type == "VF")
            {
                user_type = "I2";
                designation = "VF";

                if (dt_instructor_dtl != null)
                {
                    if (dt_instructor_dtl.Rows[0]["VF_code"].ToString() == "")
                    {
                        DataTable dt_last_vf_code_dtl = get_last_vf_code();
                        string year = DateTime.Now.Year.ToString();

                        if (dt_last_vf_code_dtl != null)
                        {
                            vf_code = "VF" + year.Substring(2) + (Convert.ToInt32(dt_last_vf_code_dtl.Rows[0]["VF_code"].ToString().Substring(4)) + 1).ToString("000");
                        }
                        else
                        {
                            vf_code = "VF" + year.Substring(2) + "001";
                        }
                    }
                    else
                    {
                        vf_code = dt_instructor_dtl.Rows[0]["VF_code"].ToString();
                    }
                }
            }
            else if (user_type == "AA")
            {
                user_type = "I2";
                designation = "AA";

                if (dt_instructor_dtl != null)
                {
                    if (dt_instructor_dtl.Rows[0]["VF_code"].ToString() == "")
                    {
                        DataTable dt_last_aa_code_dtl = get_last_aa_code();
                        string year = DateTime.Now.Year.ToString();

                        if (dt_last_aa_code_dtl != null)
                        {
                            vf_code = "AA" + year.Substring(2) + (Convert.ToInt32(dt_last_aa_code_dtl.Rows[0]["VF_code"].ToString().Substring(4)) + 1).ToString("000");
                        }
                        else
                        {
                            vf_code = "AA" + year.Substring(2) + "001";
                        }
                    }
                    else
                    {
                        vf_code = dt_instructor_dtl.Rows[0]["VF_code"].ToString();
                    }
                }
            }
            else if (user_type == "AUVF")
            {
                user_type = "I2";
                designation = "AUVF";
            }
            else if (user_type == "TA")
            {
                user_type = "I2";
                designation = "TA";

                if (dt_instructor_dtl != null)
                {
                    if (dt_instructor_dtl.Rows[0]["VF_code"].ToString() == "")
                    {
                        DataTable dt_last_ta_code_dtl = get_last_ta_code();
                        string year = DateTime.Now.Year.ToString();

                        if (dt_last_ta_code_dtl != null)
                        {
                            vf_code = "TA" + year.Substring(2) + (Convert.ToInt32(dt_last_ta_code_dtl.Rows[0]["VF_code"].ToString().Substring(4)) + 1).ToString("000");
                        }
                        else
                        {
                            vf_code = "TA" + year.Substring(2) + "001";
                        }
                    }
                    else
                    {
                        vf_code = dt_instructor_dtl.Rows[0]["VF_code"].ToString();
                    }
                }
            }
            else
            {
                designation = "instructor";
            }



            SqlSelect = "update instructor_mst set cancel_flag = '" + cancel_flag + "', last_modified_by = '" + user_id + "', last_modified_host = '" + host_name + "', last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', designation = '" + designation + "', VF_code = '" + vf_code + "', ";

            if (des_letter == "")
            {
                SqlSelect = SqlSelect + " designation_letter = null";
            }
            else
            {
                SqlSelect = SqlSelect + " designation_letter = '" + des_letter + "'";
            }

            if (instructor_name != "")
            {
                SqlSelect = SqlSelect + ", instructor_name= '" + instructor_name + "' ";
            }

            SqlSelect = SqlSelect + " where instructor_code = '" + instructor_code + "' ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            try
            {
                DBCommand.ExecuteNonQuery();

                if (designation == "VF")
                {
                    SqlSelect = "update cpop_superviser_mst set user_type ='" + user_type + "',cancel_flag = 'Y' , last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where superviser_code ='" + instructor_code + "' ";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

