                                SqlSelect = "insert into user_mst(doc_no,user_id,user_name,user_type,student_no,full_name,password,mail,start_date,pass_expiry_date,user_status_flag,cancel_flag,created_by,created_date,created_host,status) " +
                                     " VALUES('" + instructor_code + "' , '" + instructor_code + "', '" + instructor_name + "','" + user_type + "' ,'" + instructor_code + "','" + instructor_name + "', 'YWRtaW4=' ,'" + email + "' ,'" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'  ,'" + DateTime.Now.AddYears(5).ToString("yyyy/MM/dd HH:mm:ss") + "' ,'A','N','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + host_name + "' ,'A')";

                                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

