                                else if (user_type == "PC")
                                {
                                    SqlSelect = SqlSelect + "'pc', ";
                                }

                                SqlSelect = SqlSelect + "'" + user_type + "' ,'A','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + host_name + "')";

                                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                                DBCommand.ExecuteNonQuery();
                            }
                        }
                        else
                        {
                            SqlSelect = "";

                            SqlSelect = "update user_group set last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ";

                            if (cancel_flag == "Y")
                            {
                                SqlSelect = SqlSelect + " , status = 'N' ";
                            }
                            else
                            {
                                SqlSelect = SqlSelect + " , status = 'A' ";
                            }

                            if (user_type == "I2")
                            {
                                SqlSelect = SqlSelect + ", group_id = 'faculty' , user_type ='I2' ";
                            }
                            else if (user_type == "D")
                            {
                                SqlSelect = SqlSelect + ", group_id = 'dean', user_type ='D' ";
                            }
                            else if (user_type == "PC")
                            {
                                SqlSelect = SqlSelect + ", group_id = 'pc', user_type ='PC' ";
                            }

                            SqlSelect = SqlSelect + " where user_id = '" + instructor_code + "' ";

                            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                            DBCommand.ExecuteNonQuery();
                        }
                    }
                    catch (Exception ex)
                    {
                        DBConnection.Close();
                        return false;
                    }
                }

                DBConnection.Close();
                return true;
            }
            catch (Exception)
            {
                DBConnection.Close();
                return false;
            }
        }


