        public DataTable get_course_wise_session_dtl(String Course_Code, String semester, String year)
        {
            String SqlSelect = "";

           // SqlSelect = " select distinct cws.session_id,convert(varchar(15),cws.session_date,105)  as  session_date,cws.session_name,sws.is_submit,cws.semester_type,cws.year_semester from course_wise_session_dtl as cws " +
           //     " left join student_wise_session_attendence as sws on sws.course_code = cws.course_code and sws.cancel_flag = 'N' and sws.semester_type = cws.semester_type and sws.year_semester= cws.year_semester " +
           //     " AND sws.session_id = cws.session_id  where cws.semester_type = '" + semester + "' and cws.year_semester = '" + year + "' and cws.course_code = '" + Course_Code + "' and cws.cancel_flag = 'N' and cws.is_cancelled = 'N' ";

            SqlSelect = @" SELECT 
                        cws.session_id,
                        CONVERT(VARCHAR(15), cws.session_date, 105) AS session_date,
                        cws.session_name,
                        MAX(sws.is_submit) AS is_submit,
                        cws.semester_type,
                        cws.year_semester
                    FROM course_wise_session_dtl AS cws
                    LEFT JOIN student_wise_session_attendence AS sws
                        ON sws.course_code = cws.course_code
                        AND sws.cancel_flag = 'N'
                        AND sws.semester_type = cws.semester_type
                        AND sws.year_semester = cws.year_semester
                        AND sws.session_id = cws.session_id
                    WHERE cws.semester_type = '"+ semester + @"'
                      AND cws.year_semester = '" + year + @"'
                      AND cws.course_code = '" + Course_Code + @"'
                      AND cws.cancel_flag = 'N'
                      AND cws.is_cancelled = 'N'
                    GROUP BY
                        cws.session_id,
                        cws.session_date,
                        cws.session_name,
                        cws.semester_type,
                        cws.year_semester;";
            //SqlSelect = "select * from course_wise_session_dtl where semester_type ='" + semester + "' and year_semester='" + year + "' and course_code ='" + Course_Code + "' and cancel_flag ='N' and is_cancelled ='N'";

            return Get_data(SqlSelect);
        }

        public Boolean cancel_session_dtl(string session_id, String Course_Code, String semester, String year, string user_id, string host_name)
        {
            /*************************/
