            DBConnection.Open();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "update course_wise_session_dtl set is_cancelled ='Y',cancel_flag='Y',last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'" +
                        " where cancel_flag = 'N' and is_cancelled ='N' and session_id = '" + session_id + "'";

            SqlSelect = SqlSelect + "update course_wise_session_mst set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', no_of_session_held =(select COUNT(session_id) as session_count from course_wise_session_dtl where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and is_cancelled ='N') where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N'";
            SqlSelect = SqlSelect + "update student_wise_session_attendence set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', cancel_flag ='Y' where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and session_id = '" + session_id + "'";


            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return false;
            }
        }

        public dynamic manully_save_session_dtl(String Course_Code, String Session_Name, String Session_Date, String semester, String year, String user_id, String HostName)
        {
            string[] arr = Session_Date.Split('/');
            String DocNo = "";
            String message = "";
            BLReturnObject objBLReturnObject = new BLReturnObject();
            DBConnection.Open();
            if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "UF", user_id, HostName, ref DocNo, ref message))
            {

                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                objBLReturnObject.ExecutionStatus = 2;
                return objBLReturnObject;
            }


            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Close();
            DBConnection.Open();
            // DBCommand.Transaction = DBConnection.BeginTransaction();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            try
            {
                string new_date = arr[2] + "-" + arr[1] + "-" + arr[0];
                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                SqlSelect = "INSERT INTO course_wise_session_dtl (course_code,session_id,session_name,session_date,is_cancelled,cancel_flag,semester_type,year_semester, created_by, created_date, created_host) "
                          + " VALUES('" + Course_Code + "', '" + DocNo + "','" + Session_Name + "','" + Convert.ToDateTime(new_date).ToString("yyyy/MM/dd HH:mm:ss") + "', 'N', 'N', '" + semester + "', '" + year + "','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "'); ";

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DBCommand.ExecuteNonQuery();

                DBConnection.Close();
                string status = update_course_wise_session_mst(Course_Code, semester, year, user_id);
                return status;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();
                return "false";
            }

            // }
            return false;

        }


