        public DataTable get_session_date_wise_dtl(String Course_Code, String semester, String year)
        {
            string column_name = "";
            string select_column_name = "";

            DataTable dt_ = get_student_session_dtl(Course_Code, semester, year);
            DataTable dt = get_course_wise_session_dtl(Course_Code, semester, year);
            if (dt != null)
            {
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    if (i == 0)
                    {
                        column_name += dt.Rows[i]["session_id"].ToString();
                        select_column_name += "(p." + dt.Rows[i]["session_id"].ToString() + ") as '" + dt.Rows[i]["session_name"] + " (" + dt.Rows[i]["session_date"].ToString() + ")'";
                    }
                    else
                    {
                        column_name += "," + dt.Rows[i]["session_id"].ToString();
                        select_column_name += ",(p." + dt.Rows[i]["session_id"].ToString() + ") as '" + dt.Rows[i]["session_name"] + " (" + dt.Rows[i]["session_date"].ToString() + ")'";
                    }

                }

            }

            String SqlSelect = "";
            SqlSelect = " Select  p.session_is_submit, p.user_id, p.course_code, p.full_name,p.sca_user_id, " + select_column_name + " from (" +
                " select student_wise_session_attendence.is_submit as session_is_submit,course_wise_session_dtl.session_id as course_session_id," +
                " student_course_allocate_dtl.user_id as sca_user_id, " +
                " student_wise_session_attendence.user_id,student_wise_session_attendence.course_code,session_attended, " +
                " user_mst.full_name,student_wise_course_attendence.no_of_session_attended, student_wise_course_attendence.attendance_percentage,student_wise_course_attendence.is_submit " +
                " from student_course_allocate_dtl " +
                " inner join user_mst on user_mst.user_id = student_course_allocate_dtl.user_id " +
                " left join student_wise_course_attendence on student_wise_course_attendence.user_id = student_course_allocate_dtl.user_id " +
                " and student_wise_course_attendence.year_semester = student_course_allocate_dtl.year_semester " +
                " and student_wise_course_attendence.semester_type = student_course_allocate_dtl.semester_type " +
                " and student_wise_course_attendence.course_code = student_course_allocate_dtl.course_code " +
                " and student_wise_course_attendence.cancel_flag ='N' " +
                " inner join course_wise_session_dtl on course_wise_session_dtl.course_code =  student_course_allocate_dtl.course_code " +
                " and course_wise_session_dtl.cancel_flag ='N' and course_wise_session_dtl.is_cancelled ='N'  " +
                " and course_wise_session_dtl.semester_type =  student_course_allocate_dtl.semester_type " +
                " and course_wise_session_dtl.year_semester =  student_course_allocate_dtl.year_semester " +
                " left join student_wise_session_attendence on student_wise_session_attendence.session_id = course_wise_session_dtl.session_id " +
                " and student_wise_session_attendence.course_code = course_wise_session_dtl.course_code " +
                " and student_wise_session_attendence.semester_type = course_wise_session_dtl.semester_type " +
                " and student_wise_session_attendence.year_semester = course_wise_session_dtl.year_semester " +
                " and student_wise_session_attendence.user_id = user_mst.user_id and student_wise_session_attendence.cancel_flag ='N' " +
                " where student_course_allocate_dtl.course_code='" + Course_Code + "'  and student_course_allocate_dtl.semester_type='" + semester + "' " +
                " and student_course_allocate_dtl.year_semester='" + year + "' and student_course_allocate_dtl.cancel_flag='N'  ";

            if (dt_ != null)
            {
                SqlSelect = SqlSelect + " and student_wise_session_attendence.user_id is NOT NULL ) as t ";
            }
            else
            {
                SqlSelect = SqlSelect + " ) as t";
            }

            SqlSelect = SqlSelect + " pivot ( " +
                " MAX(session_attended) for Course_session_id in (" + column_name + ") ) As P ";
            SqlSelect = SqlSelect + " order by p.full_name asc ";
            return Get_data(SqlSelect);
        }


        public BLReturnObject save_student_session_att_dtl(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_GradingMaster server_course_att_master = (DSC_GradingMaster)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_GradingMaster objCourseMaster_upload = new DSC_GradingMaster();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_att_master.student_wise_session_attendence.Rows.Count; mprCnt++)
                {

                    objCourseMaster_upload.student_wise_session_attendence.ImportRow(server_course_att_master.student_wise_session_attendence.Rows[mprCnt]);
                    //objCourseMaster_upload.exam_master[mprCnt].doc_no = DocNo;
                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.student_wise_session_attendence, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.student_wise_session_attendence.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

