        public dynamic update_course_wise_session_mst(string Course_Code, string semester, string year, string user_id)
        {
            /*************************/
            /* ESTABLISH CONNECTION */

            /*************************/


            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();


            String SqlSelect = "";


            SqlSelect = "IF EXISTS(select * from course_wise_session_mst where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N') "
                      + " BEGIN "
                      + " update course_wise_session_mst set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', no_of_session_held =(select COUNT(session_id) as session_count from course_wise_session_dtl where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and is_cancelled ='N') where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N'"
                      + " END "
                  + " ELSE "
                      + " BEGIN "
                      + " INSERT INTO course_wise_session_mst (course_code,no_of_session_held,is_submit,cancel_flag, semester_type, year_semester, created_by, created_date, created_host) "
                      + " VALUES('" + Course_Code + "',(select COUNT(session_id) as session_count from course_wise_session_dtl where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and is_cancelled ='N' ),'N','N', '" + semester + "', '" + year + "', '" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "')"
                      + " END ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return "true";
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return "false";
            }
        }

        public DataTable get_student_wise_absend_present_dtl(String Course_Code, String semester, String year)
        {
            String SqlSelect = "";
            SqlSelect = " select CASE WHEN (t1.user_id IS NULL) THEN t2.user_id ELSE t1.user_id END AS user_id, isnull(t1.absent,0) as absent, isnull(t2.present,0) as present from (" +
                " (select user_id, COUNT(session_attended) as absent from student_wise_session_attendence where course_code ='" + Course_Code + "' and session_attended ='A' and cancel_flag ='N' " +
                " and semester_type ='" + semester + "' and year_semester ='" + year + "' group by user_id, session_attended) as t1 " +
                " full join " +
                " (select user_id, COUNT(session_attended) as present from student_wise_session_attendence where course_code ='" + Course_Code + "' and session_attended ='P' and cancel_flag ='N' " +
                " and semester_type ='" + semester + "' and year_semester ='" + year + "' group by user_id, session_attended) as t2  on t1.user_id=t2.user_id) ";
            return Get_data(SqlSelect);
        }

        public DataTable get_stubmit_attendance_dtl(String Course_Code, String semester, String year, String user_type, String user_id)
        {
            String SqlSelect = "";

            SqlSelect = " select swca.user_id,swca.course_code,cws.no_of_session_held, swca.no_of_session_attended,swca.attendance_percentage, user_mst.full_name," +
                " swca.course_code +' - ( Total Session Held - '+ CAST(cws.no_of_session_held AS nvarchar(50)) + ' )' as held,cws.doc_pdf from student_wise_course_attendence as swca " +
                " inner join user_mst on user_mst.user_id = swca.user_id " +
                " inner join course_wise_session_mst as cws on cws.course_code = swca.course_code and cws.semester_type = swca.semester_type " +
                " and cws.year_semester = swca.year_semester and cws.is_submit = swca.is_submit and cws.cancel_flag = swca.cancel_flag " +
                " inner join department_wise_course_dtl as dwc on dwc.course_code = swca.course_code and " +
                " dwc.semester_type= swca.semester_type and dwc.year_semester = swca.year_semester and dwc.cancel_flag='N' ";

            if (user_type == "I2" || user_type == "PC")
            {
                SqlSelect += " inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code = dwc.prog_code " +
                 " and pcd.semester_type = swca.semester_type and pcd.year_semester = swca.year_semester and pcd.cancel_flag='N' and " +
                 " ISNULL(pcd.prog_level_code,'') = ISNULL(dwc.prog_level_code,'') ";
            }
            if (user_type == "FA")
            {
                SqlSelect += " inner join department_wise_user_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code = dwc.prog_code " +
                    " and pcd.semester_type = swca.semester_type and pcd.year_semester = swca.year_semester and pcd.cancel_flag='N' and " +
                    " ISNULL(pcd.prog_level_code,'') = ISNULL(dwc.prog_level_code,'') ";
            }
            if (user_type == "D")
            {
                SqlSelect += " inner join dean_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code = dwc.prog_code " +
                    " and pcd.semester_type = swca.semester_type and pcd.year_semester = swca.year_semester and pcd.cancel_flag='N' ";
            }
            SqlSelect += " where swca.semester_type='" + semester + "' and swca.year_semester ='" + year + "' and swca.cancel_flag='N' and swca.is_submit ='Y' ";

            if (Course_Code != "")
            {
                SqlSelect += " and swca.course_code = '" + Course_Code + "'";
            }
            if (user_type == "I2" || user_type == "PC" || user_type == "FA")
            {
                SqlSelect += " and pcd.user_id = '" + user_id + "'";
            }
            SqlSelect += " order by swca.course_code ";

            return Get_data(SqlSelect);
        }


        public DataTable get_course_wise_attendance_dtl(String Course_Code, String semester, String year, String user_type, String user_id)
        {
            String SqlSelect = "";

            SqlSelect = " select cw.course_code,cm.course_name,cw.no_of_session_held,cw.doc_pdf from course_wise_session_mst cw " +
                " inner join course_mst cm on cm.course_code = cw.course_code and cm.semester_type = cw.semester_type and cm.year_semester = cw.year_semester " +
                " inner join department_wise_course_dtl as dwc on dwc.course_code = cw.course_code and " +
                " dwc.semester_type= cw.semester_type and dwc.year_semester = cw.year_semester and dwc.cancel_flag='N' ";

            if (user_type == "I2" || user_type == "PC")
            {
                SqlSelect += " inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code = dwc.prog_code " +
                 " and pcd.semester_type = cw.semester_type and pcd.year_semester = cw.year_semester and pcd.cancel_flag='N' and " +
                 " ISNULL(pcd.prog_level_code,'') = ISNULL(dwc.prog_level_code,'') ";
            }
            if (user_type == "FA")
            {
                SqlSelect += " inner join department_wise_user_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code = dwc.prog_code " +
                    " and pcd.semester_type = cw.semester_type and pcd.year_semester = cw.year_semester and pcd.cancel_flag='N'  " +
                    //" and ISNULL(pcd.prog_level_code,'') = ISNULL(dwc.prog_level_code,'') ";
                    " and (pcd.prog_level_code is null OR ISNULL(pcd.prog_level_code,'') = ISNULL(dwc.prog_level_code,'')) ";
            }
            if (user_type == "D")
            {
                SqlSelect += " inner join dean_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code = dwc.prog_code " +
                    " and pcd.semester_type = cw.semester_type and pcd.year_semester = cw.year_semester and pcd.cancel_flag='N' ";
            }
            SqlSelect += " where cw.semester_type='" + semester + "' and cw.year_semester ='" + year + "' and cw.cancel_flag='N' and cw.is_submit ='Y' ";

            if (Course_Code != "")
            {
                SqlSelect += " and cw.course_code = '" + Course_Code + "'";
            }
            if (user_type == "I2" || user_type == "PC" || user_type == "FA")
            {
                SqlSelect += " and pcd.user_id = '" + user_id + "'";
            }
            SqlSelect += " order by cw.course_code ";

            return Get_data(SqlSelect);
        }

