        public string CombinePDF_TE_Letter(String FileName)
        {
            try
            {
                string Path = HttpContext.Current.Server.MapPath("~/LetterPDF");
                String[] FileArray = FileName.Split(new Char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                List<string> ExitsFile_new = new List<string>();
                for (int i = 0; i < FileArray.Length; i++)
                {
                    FileArray[i] = Path + "\\" + FileArray[i].ToString();
                }
                string[] filePaths = Directory.GetFiles(Path);

                foreach (var filename in FileArray)
                {
                    string file = filename.ToString();
                    if (File.Exists(file))
                    {
                        ExitsFile_new.Add(file);
                    }
                }
                string FolderPathToZip = Path + "\\" + "Letter Pdf";
                using (ZipFile zip_file = new ZipFile())
                {
                    zip_file.AddFiles(ExitsFile_new.Distinct().ToArray(), "Letter Pdf");

                    zip_file.Save(FolderPathToZip + ".zip");
                }
            }
            catch (Exception ex)
            {
                return "2";
            }

            return "1";
        }


