        public DataTable get_bonafide_student_dtl(string student_code, string type, string save_status)
        {
            String SqlSelect = "";
            //SqlSelect = " select * from bonafide_certificate_dtl where student_code = '" + student_code + "' and cancel_flag ='N' ORDER BY created_date DESC";

            SqlSelect = " select * from bonafide_certificate_dtl as bcd inner join user_mst on user_mst.user_id =bcd.student_code " +
                        " Inner join bonafide_purpose_mst as bpm on bpm.purpose_code = bcd.purpose_value and bpm.cancel_flag ='N' where bcd.cancel_flag ='N'";
            if (student_code != "")
            {
                SqlSelect = SqlSelect + " and bcd.student_code = '" + student_code + "'";
            }
            if (type == "A")
            { SqlSelect = SqlSelect + " and bcd.status = 'A'"; }
            else if (type == "S")
            { SqlSelect = SqlSelect + " and bcd.status = 'S'"; }
            else if (type == "R")
            { SqlSelect = SqlSelect + " and bcd.status = 'R'"; }
            else if (save_status == "N")
            { SqlSelect = SqlSelect + " and bcd.status <> 'N'"; }
            SqlSelect = SqlSelect + " ORDER BY bcd.sr_no DESC ";
            return Get_data(SqlSelect);
        }
        public void save_bonafide_data(ref Dictionary<string, string> bonafide_data)
        {
            /*************************/
            /* ESTABLISH CONNECTION */

            if (bonafide_data["student_code"] != null || bonafide_data["student_code"].ToString().Trim() != "")
            {
                DBConnection.Open();
                // DBCommand.Transaction = DBConnection.BeginTransaction();
                /*************************/
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                String SqlSelect = "";

                try
                {
                    DBDataAdpterObject.SelectCommand.Parameters.Clear();
                    SqlSelect = "";

                    if (bonafide_data["sr_no"] != "")
                    {
                        SqlSelect = "update bonafide_certificate_dtl set purpose_value = '" + bonafide_data["purpose"] + "',remarks = '" + bonafide_data["remark"] + "',other_remarks = '" + bonafide_data["other_remarks"] + "',id_proof_path = '" + bonafide_data["id_proof_pat"] + "',fees_slip_path = '" + bonafide_data["fees_slip_path"] + "'" +
                            ",status ='" + bonafide_data["action"] + "',last_modified_by = '" + bonafide_data["user_id"] + "',last_modified_host = '" + bonafide_data["host_name"] + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where sr_no = '" + bonafide_data["sr_no"] + "' and student_code = '" + bonafide_data["user_id"] + "' ";

                    }
                    else
                    {
