        public DataTable Get_student_bonafide_template_data(string sr_no)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"select user_mst.*,bonafide_certificate_dtl.*,bonafide_purpose_mst.*,bonafide_purpose_mst.purpose_dec,department_mst.dept_name,programme_mst.prog_name,cept_current_semester.sem_code as cur_sem,
                                cept_current_semester.year_code as cur_year,
                                programme_level_mst.prog_level_name,student_transcript_dtl.name_of_the_degree 
                                from user_mst
                                inner join department_mst on department_mst.dept_code = user_mst.dept_code
                                inner join programme_mst on programme_mst.prog_code = user_mst.prog_code
                                inner join cept_current_semester on type_desc='all' 
                                left join student_transcript_dtl on student_transcript_dtl.user_id=user_mst.user_id
                                left join programme_level_mst on user_mst.prog_level_code=programme_level_mst.prog_level_code
                                inner join bonafide_certificate_dtl on bonafide_certificate_dtl.student_code = user_mst.user_id
                                inner join bonafide_purpose_mst on bonafide_purpose_mst.purpose_code = bonafide_certificate_dtl.purpose_value
                                where bonafide_certificate_dtl.sr_no ='" + sr_no + "' and bonafide_certificate_dtl.cancel_flag ='N'";

            return Get_data(SqlSelect);
        }

        public string Download_Bonafide_Document(string student_code, string sr_no)
        {
            try
            {
                DataTable dt = Get_student_bonafide_template_data(sr_no);
                string id_proof = HttpContext.Current.Server.MapPath("~/BonafideIdProof");
                string Bona_cert = HttpContext.Current.Server.MapPath("~/BonafideCertificate");
                string student_id = HttpContext.Current.Server.MapPath("~/Student_ID_Card");
                string fees_slip = HttpContext.Current.Server.MapPath("~/FeesSlip");
                List<string> ExitsFile = new List<string>();
                string id_proof_file = id_proof + "\\" + dt.Rows[0]["id_proof_path"].ToString();
                string bonafied_file_name = student_code + "_" + sr_no + ".pdf";
                string idcard = student_code + ".pdf";
                string fees_slip_file = fees_slip + "\\" + dt.Rows[0]["fees_slip_path"].ToString();
                if (File.Exists(id_proof_file))
                {
                    ExitsFile.Add(id_proof_file);
                }
                string Bonafied_cert_file = Bona_cert + "\\" + bonafied_file_name;
                if (File.Exists(Bonafied_cert_file))
                {
                    ExitsFile.Add(Bonafied_cert_file);
                }
                string idcard_file = student_id + "\\" + idcard;
                if (File.Exists(idcard_file))
                {
                    ExitsFile.Add(idcard_file);
                }

                if (File.Exists(fees_slip_file))
                {
                    ExitsFile.Add(fees_slip_file);
                }
                string FolderPathToZip = id_proof + "\\" + "Document";
                if (File.Exists(FolderPathToZip))
                {
                    File.Delete(FolderPathToZip);
                }
                if (ExitsFile.Count > 0)
                {
                    using (ZipFile zip = new ZipFile())
                    {
                        zip.AddFiles(ExitsFile.ToArray(), "Document");
                        zip.Save(FolderPathToZip + ".zip");
                    }
                }
                else
                {
                    return "2";
                }
            }
            catch (Exception ex)
            {
                return "2";
            }

            return "1";
        }


