        public DataTable Get_fees_Slip_dtl(string user_id, string sem_code, string year_code)
        {
            String SqlSelect = "";

            //SqlSelect = " SELECT distinct ApplicationPaymentTransaction.user_id,is_paid as amount, Right(installment,1) as installment_no, " +
            //    " ApplicationPaymentTransaction.semester_type , ApplicationPaymentTransaction.year_semester,cast('Online' as varchar) as Payment_Mode,cast('fees_slip_path' as varchar) as Fees_Slip_Path " +
            //    " FROM user_fees_installment_dtl " +
            //    " UNPIVOT ( is_paid FOR installment in (installment1,installment2,installment3,installment4,installment5) )" +
            //    " AS feesUnpivot " +
            //    " inner join ApplicationPaymentTransaction on ApplicationPaymentTransaction.user_id = feesUnpivot.user_id and ApplicationPaymentTransaction.semester_type = feesUnpivot.semester_type " +
            //    " and ApplicationPaymentTransaction.year_semester = feesUnpivot.year_semester and  ApplicationPaymentTransaction.payment_return_flag ='Y' and ApplicationPaymentTransaction. payment_response_code='0' " +
            //    " where feesUnpivot.semester_type ='" + sem_code + "' and feesUnpivot.year_semester ='" + year_code + "' and feesUnpivot.user_id ='" + user_id + "' and feesUnpivot.cancel_flag ='N'";

            SqlSelect = " Select t1.user_id,t1.amount,t1.installment_no,t1.semester_type,t1.year_semester,t1.Payment_Mode,t1.Fees_Slip_Path,t2.installment_fine, t2.paid_installment_fine from ( " +
                " SELECT distinct ApplicationPaymentTransaction.user_id,is_paid as amount, Right(installment,1) as installment_no, " +
                " ApplicationPaymentTransaction.semester_type , ApplicationPaymentTransaction.year_semester,cast('Online' as varchar) as Payment_Mode,cast('fees_slip_path' as varchar) as Fees_Slip_Path " +
                " FROM user_fees_installment_dtl " +
                " UNPIVOT ( is_paid FOR installment in (installment1,installment2,installment3,installment4,installment5) )" +
                " AS feesUnpivot " +
                " inner join ApplicationPaymentTransaction on ApplicationPaymentTransaction.user_id = feesUnpivot.user_id and ApplicationPaymentTransaction.semester_type = feesUnpivot.semester_type " +
                " and ApplicationPaymentTransaction.year_semester = feesUnpivot.year_semester and  ApplicationPaymentTransaction.payment_return_flag ='Y' and ApplicationPaymentTransaction. payment_response_code='0' " +
                " where feesUnpivot.semester_type ='" + sem_code + "' and feesUnpivot.year_semester ='" + year_code + "' and feesUnpivot.user_id ='" + user_id + "' and feesUnpivot.cancel_flag ='N') t1 " +
                " left join " +
                " (select installment_no, installment_fine,paid_installment_fine, semester_type,year_semester " +
                " from user_fees_fine_dtl as uffd where uffd.user_id ='" + user_id + "' and uffd.semester_type ='" + sem_code + "' and uffd.year_semester ='" + year_code + "' and uffd.is_paid_installment_fine ='Y' " +
                " and uffd.cancel_flag ='N') as t2 on t2.installment_no  = t1.installment_no and t2.semester_type = t1.semester_type " +
                " and t2.year_semester = t1.year_semester ";

            return Get_data(SqlSelect);

        }


