        public DataTable Get_reg_feedback_course_dtl(String sem_code, String year_code, String dept_code, String prog_code, String prog_level_code, String staus_flage)
        {
            String SqlSelect = "";

            SqlSelect = " select distinct scad.course_code,cm.course_name,dwcd.dept_code,dm.dept_name from student_course_allocate_dtl as scad " +
                " inner join course_mst as cm on cm.course_code = scad.course_code and cm.semester_type = scad.semester_type and cm.year_semester = scad.year_semester " +
                " inner join department_wise_course_dtl as dwcd on dwcd.course_code = scad.course_code and dwcd.cancel_flag ='N' and dwcd.semester_type = scad.semester_type  " +
                " and dwcd.year_semester = scad.year_semester " +
                " inner join department_mst as dm on dm.dept_code = dwcd.dept_code and dm.cancel_flag ='N' " +
                " where scad.semester_type ='" + sem_code + "' and scad.year_semester ='" + year_code + "' and scad.cancel_flag ='N' and cm.cancel_flag ='N' ";
            if (dept_code != "")
            {
                SqlSelect += " and dwcd.dept_code ='" + dept_code + "' ";
            }
            if (prog_code != "")
            {
                SqlSelect += " and dwcd.prog_code ='" + prog_code + "' ";
            }
            if (prog_level_code != "")
            {
                SqlSelect += " and dwcd.prog_level_code ='" + prog_level_code + "' ";
            }
            if (staus_flage == "E")
            {
                SqlSelect += " and scad.course_code Not in (select course_code from feedback_disable_course where semester_type ='" + sem_code + " ' and year_semester ='" + year_code + "' and cancel_flag ='N')";
            }
            if (staus_flage == "D")
            {
                SqlSelect += " and scad.course_code in (select course_code from feedback_disable_course where semester_type ='" + sem_code + " ' and year_semester ='" + year_code + "' and cancel_flag ='N')";
            }

            return Get_data(SqlSelect);

        }

