        public DataTable Get_instrctor_disable_for_feedback(String sem_code, String year_code, String course_code)
        {
            String SqlSelect = "";

            SqlSelect = " select t4.course_code, t4.user_id, ISNULL(t4.instructor_code,t5.instructor_code) as Disable_instructor_code,t4.full_name,t4.mail," +
                " (select COUNT(instructor_code) from course_wise_instructor where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag ='N' and course_code ='" + course_code + "' ) as inst_count," +
                " (SELECT Enable_instructor_code=STUFF  (( SELECT DISTINCT ', ' + CAST(user_mst.full_name AS VARCHAR(MAX)), ' (' + CAST(user_mst.mail AS VARCHAR(MAX)) + ')' " +
                " FROM course_wise_instructor as cw " +
                " left join user_mst on user_mst.user_id = cw.instructor_code where cw.semester_type ='" + sem_code + "' and cw.year_semester = '" + year_code + "' and cw.cancel_flag ='N' and cw.course_code ='" + course_code + "'" +
                " and cw.instructor_code Not in (select instructor_code from temp_feedback_instructor_disable where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and course_code ='" + course_code + "' " +
                " and user_id =t4.user_id and cancel_flag ='N') FOR XML PATH('') ),1,1,'' )) as Enable_instructor_code  from ( " +
                " (select course_code,scad.user_id,user_mst.full_name,user_mst.mail, Null as instructor_code from  student_course_allocate_dtl as scad " +
                " inner join user_mst on user_mst.user_id = scad.user_id where scad.semester_type ='" + sem_code + "' and scad.year_semester ='" + year_code + "' and scad.course_code ='" + course_code + "' and scad.cancel_flag ='N') as t4 " +
                " left join (SELECT t1.course_code,t1.user_id, instructor_code=STUFF (( " +
                " SELECT DISTINCT ', ' + CAST(user_mst.full_name AS VARCHAR(MAX)), ' (' + CAST(user_mst.mail AS VARCHAR(MAX)) + ')' " +
                " FROM temp_feedback_instructor_disable t2  left join user_mst on user_mst.user_id = t2.instructor_code " +
                " WHERE t2.user_id = t1.user_id  and t2.course_code = t1.course_code  and t2.semester_type =t1.semester_type and t2.year_semester =t1.year_semester and t2.cancel_flag ='N' " +
                " FOR XML PATH('') ),1,1,'') FROM temp_feedback_instructor_disable t1 left join user_mst as t3 on t3.user_id = t1.instructor_code " +
                " where t1.course_code = '" + course_code + "' and t1.semester_type ='" + sem_code + "' and t1.year_semester ='" + year_code + "' and t1.cancel_flag ='N' " +
                " GROUP BY t1.user_id ,t1.course_code,t1.semester_type,t1.year_semester ) as t5 on t5.user_id = t4.user_id and t5.course_code = t4.course_code ) ";

            return Get_data(SqlSelect);

        }


