        public DataTable get_fine_fees_installment_dtl(string sem_code, string year_code, string installment_no, string user_id, string user_type)
        {
            String SqlSelect = "";
            //uffd.installment_fine,
            SqlSelect = @" select uffd.installment_fine,uffd.paid_installment_fine,apt.created_date as fees_paid_date,ufi.*,apt.*, um.user_name, um.prog_desc, um.middle_name, um.first_name, um.dept_code,
			um.prog_code,um.year_code,um.prog_level_code,plm.prog_level_name,std.name_of_the_degree,dm.dept_name
			from user_fees_installment_dtl as ufi
			inner join user_mst as um on um.user_id=ufi.user_id
			inner join ApplicationPaymentTransaction as apt on apt.user_id=ufi.user_id
			and apt.semester_type=ufi.semester_type and apt.year_semester=ufi.year_semester 
            left join user_fees_fine_dtl as uffd on uffd.user_id=ufi.user_id
            and uffd.semester_type = ufi.semester_type and uffd.year_semester = ufi.year_semester and uffd.installment_no = '" + installment_no + "' and uffd.is_paid_installment_fine = 'Y' and uffd.cancel_flag = 'N' ";

            SqlSelect = SqlSelect + @"left join department_mst as dm on dm.dept_code = um.dept_code 
			left join programme_level_mst as plm on plm.prog_level_code = um.prog_level_code
			left join student_transcript_dtl as std on std.user_id = um.user_id
			where ufi.semester_type='" + sem_code + "' and ufi.year_semester='" + year_code + "' and ufi.cancel_flag='N' " +
            " and ufi.is_installment" + installment_no + "_paid='Y' and apt.payment_response_code='0' and apt.cash_collected_by='" + installment_no + "' ";

            if (user_type == "S")
            {
                SqlSelect = SqlSelect + " and um.user_id='" + user_id + "' ";
            }

            return Get_data(SqlSelect);
        }


