			left join programme_level_mst as plm on plm.prog_level_code = um.prog_level_code
			left join student_transcript_dtl as std on std.user_id = um.user_id
			where ufi.semester_type='" + sem_code + "' and ufi.year_semester='" + year_code + "' and ufi.cancel_flag='N' " +
            " and ufi.is_installment" + installment_no + "_paid='Y' and apt.installment_no = '" + installment_no + "' and apt.is_admin_approved='A' and apt.cancel_flag ='N' ";

            if (user_type == "S")
            {
                SqlSelect = SqlSelect + " and um.user_id='" + user_id + "' ";
            }

            return Get_data(SqlSelect);
        }
        #endregion

        #region Installment Fees Dtl 

        public DataTable Get_Fees_installment_details(String user_id, String installment_no, String sem_code, String year_code)
        {
            String SqlSelect = "";

            SqlSelect = " SELECT feesunpivot.user_id,user_mst.full_name, fees_amount, no_of_installment,semester_type,year_semester,installment_no," +
                " is_installment1_paid,is_installment2_paid,is_installment3_paid,is_installment4_paid,is_installment5_paid, " +
                " installmentfess FROM user_fees_installment_dtl UNPIVOT ( " +
                " installmentfess FOR installment_no in (installment1, installment2, installment3, installment4,installment5)) AS feesunpivot " +
                " inner join user_mst on user_mst.user_id = feesunpivot.user_id " +
                " where feesunpivot.semester_type ='" + sem_code + "' and feesunpivot.year_semester ='" + year_code + "' and feesunpivot.cancel_flag ='N'";
            if (user_id != "")
            {
                SqlSelect += " and feesunpivot.user_id = '" + user_id + "'";
            }
            if (installment_no != "")
            {
                SqlSelect += " and installment_no = 'installment" + installment_no + "'";
            }
            SqlSelect += " order by feesunpivot.user_id asc ";
            return Get_data(SqlSelect);
        }



