        public Boolean save_scholarship_detail(Dictionary<string, string> obj_schol_dtl, string host_name, string user_id)
        {

            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            // DBCommand.Transaction = DBConnection.BeginTransaction();

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            String approvedate = obj_schol_dtl["approve_date"].ToString();
            if (approvedate != null && approvedate != string.Empty)
            {
                string[] sttime = approvedate.ToString().Split('-');
                string gh21 = sttime[2].ToString() + "/" + sttime[1].ToString() + "/" + sttime[0].ToString();
                DateTime dt = Convert.ToDateTime(gh21);
                approvedate = dt.ToString();

            }

            try
            {
                string doc_no = Get_next_doc_number("UF");
                doc_no = "S" + obj_schol_dtl["year_semester"].ToString() + doc_no;
                DBConnection.Close();
                DBConnection.Open();


