        public DataTable get_current_semester_dtl(string user_id, string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = " select ufi.user_id,scs.semester_code,user_mst.dept_code,ufi.fees_type,ufi.installment_status,user_mst.year_code from user_fees_installment_dtl as ufi " +
                        " left join user_mst on user_mst.user_id = ufi.user_id " +
                        " left join student_current_sem_dtl as scs on scs.student_code = ufi.user_id and scs.cancel_flag = 'N' and scs.active_flag ='Y' " +
                        " where ufi.user_id='" + user_id + "'and ufi.semester_type ='" + sem_code + "' and ufi.year_semester ='" + year_code + "' and ufi.cancel_flag ='N' ";

            return Get_data(SqlSelect);
        }
        //new 12072021 ,ssd.scholarship_type
        public DataTable Get_scholship_dtl(String user_id, String sem_code, String year_code)
        {
            String SqlSelect = "";

            SqlSelect = " select um.user_id,um.full_name,ufi.fees_amount,ssd.scholarship_percentage,ssd.apprve_scholarship_amount,ssd.approve_date,ssd.ref_no,ssd.remark,ssd.scholarship_type," +
                " ufi.installment1,ufi.installment2,ufi.installment3,ufi.installment4,ufi.installment5,ufi.is_installment1_paid,ufi.is_installment2_paid,ufi.is_installment3_paid, " +
                " ufi.is_installment4_paid,ufi.is_installment5_paid,ufi.no_of_installment,ssd.carry_forward_amount from user_mst as um  " +
                " inner join user_fees_installment_dtl as ufi on ufi.user_id = um.user_id and ufi.cancel_flag ='N' " +
                " left join student_scholarship_dtl as ssd on ssd.user_id = um.user_id and ssd.cancel_flag ='N' and ssd.semester_type = ufi.semester_type  and ssd.year_semester = ufi.year_semester " +
                " where ufi.semester_type ='" + sem_code + "' and ufi.year_semester ='" + year_code + "' ";
            if (user_id != "")
            {
                SqlSelect += " and ufi.user_id ='" + user_id + "'";
            }

            return Get_data(SqlSelect);
        }

