        public DataTable get_medical_antiragging_dtl(string student_code, string type, string prog_code, string dept_code, string year_code)
        {
            String SqlSelect = "";
            //SqlSelect = " select * from bonafide_certificate_dtl where student_code = '" + student_code + "' and cancel_flag ='N' ORDER BY created_date DESC";

            SqlSelect = " select * from student_medical_certificate as bcd inner join user_mst on user_mst.user_id =bcd.user_id " +
                        " where bcd.cancel_flag ='N'";
            if (student_code != "")
            {
                SqlSelect = SqlSelect + " and bcd.user_id = '" + student_code + "'";
            }
            if (type == "A")
            { SqlSelect = SqlSelect + " and bcd.is_submit = 'A'"; }
            else if (type == "S")
            { SqlSelect = SqlSelect + " and bcd.is_submit = 'S'"; }
            else if (type == "R")
            { SqlSelect = SqlSelect + " and bcd.is_submit = 'R'"; }
