            if (year_code != "")
            {
                SqlSelect = SqlSelect + " and bcd.year_code = '" + year_code + "'";
            }
            SqlSelect = SqlSelect + " ORDER BY bcd.doc_no DESC ";
            return Get_data(SqlSelect);
        }


