        public string CombinePDF_Medical_Antiragging(String FileName, String type)
        {
            try
            {
                string Path = "";
                if (type == "M")
                {
                    Path = HttpContext.Current.Server.MapPath("~/MedicalCertificate");
                }
                else { Path = HttpContext.Current.Server.MapPath("~/Antiragging"); }

                String[] FileArray = FileName.Split(new Char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                List<string> ExitsFile = new List<string>();
                for (int i = 0; i < FileArray.Length; i++)
                {
                    FileArray[i] = Path + "\\" + FileArray[i].ToString();
                }
                string[] filePaths = Directory.GetFiles(Path);

                foreach (var filename in FileArray)
                {
                    string file = filename.ToString();
                    if (File.Exists(file))
                    {
                        ExitsFile.Add(file);
                    }
                }
                string FolderPathToZip = "";
                if (type == "M")
                {
                    FolderPathToZip = Path + "\\" + "MedicalCertificate";
                }
                else { FolderPathToZip = Path + "\\" + "Antiragging"; }

                using (ZipFile zip = new ZipFile())
                {
                    if (type == "M") { zip.AddFiles(ExitsFile.ToArray(), "MedicalCertificate"); } else { zip.AddFiles(ExitsFile.ToArray(), "Antiragging"); }

                    zip.Save(FolderPathToZip + ".zip");
                }
            }
            catch (Exception ex)
            {
                return "2";
            }

            return "1";
        }
