        public DataTable Get_Studio_Submit_Course_Dtl(string uid, string utype, string user_prog_code, string sem_code, string year_code, string prog_code, string prog_level_code)//Ananth 25042019
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (utype == "PC")
            {
                SqlSelect = "SELECT distinct course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                            " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                            " course_mst.faculty_approved,course_mst.progcoordinate_approved as pflag,course_mst.ugpgoffice_approved,course_mst.backlog," +

                            " (case course_mst.faculty_approved when 'Y' then 'Approved' when 'P' then 'Pending' else '' end) as 'faculty_approval'," +
                            " (case course_mst.progcoordinate_approved when 'P' then 'Approved' else '' end) as 'progcoord_approval'," +
                            " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year,course_mst.backlog,dwc.sub_category_id,course_mst.studio_mode,isd.studio_brief_status " +
                            " FROM course_mst " +
                            " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code and dwc.semester_type = course_mst.semester_type and dwc.year_semester = course_mst.year_semester " +
                            " inner join instructor_studio_details as isd on isd.course_code = course_mst.course_code and isd.cancel_flag ='N' " +
                            " inner join programme_coordinator_dtl as pcd on pcd.dept_code = dwc.dept_code and pcd.prog_code=dwc.prog_code and pcd.semester_type=dwc.semester_type and pcd.year_semester = dwc.year_semester " +

                            " where course_mst.cancel_flag='Y' and course_mst.semester_type ='" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                            " and (course_mst.ugpgoffice_approved = 'N' or course_mst.ugpgoffice_approved is null or course_mst.ugpgoffice_approved = '')" +
                            " and (course_mst.faculty_approved = 'N' or course_mst.faculty_approved is null or course_mst.faculty_approved = '')" +
                            " and (course_mst.progcoordinate_approved = 'P' or course_mst.progcoordinate_approved is null or course_mst.progcoordinate_approved = '')" +

                            " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "'" +
                            " and pcd.prog_code=dwc.prog_code " +
                            " and pcd.semester_type = '" + sem_code + "' and pcd.year_semester = '" + year_code + "' " +
                            " and pcd.cancel_flag='N' and isd.studio_brief_status='A' and ISNULL(dwc.prog_level_code,'')=ISNULL(pcd.prog_level_code,'') and pcd.user_id = '" + uid + "'";



                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }

                SqlSelect = SqlSelect + " ORDER BY course_mst.course_code";
            }
            else
            {
                SqlSelect = "SELECT distinct course_mst.course_code,dwc.course_typology,course_mst.course_type,course_mst.course_name,course_mst.course_credits,course_mst.occurrence_week,case when course_mst.gpa_ngpa='G'Then 'GPA' when course_mst.gpa_ngpa='N' Then 'Non GPA' else 'GPA' End as gpa_ngpa," +
                                " course_mst.course_outline,course_mst.course_desc,course_mst.prerequisite,dwc.dept_code,dwc.prog_code,dwc.prog_level_code,dwc.semester_code,dwc.available_seat,course_mst.remark," +
                                " course_mst.faculty_approved,course_mst.progcoordinate_approved as pflag,course_mst.ugpgoffice_approved,course_mst.backlog," +
                                " (case course_mst.faculty_approved when 'Y' then 'Approved' when 'P' then 'Pending' else '' end) as 'faculty_approval'," +
                                " (case course_mst.progcoordinate_approved when 'P' then 'Approved' else '' end) as 'progcoord_approval'," +
                                " (case course_mst.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                                " course_mst.semester_type,course_mst.year_semester,course_mst.semester_type as cur_sem,(course_mst.year_semester) as cur_year,course_mst.backlog,dwc.sub_category_id,course_mst.studio_mode,isd.studio_brief_status" +
                                " FROM course_mst " +
                                " inner join department_wise_course_dtl as dwc on dwc.course_code = course_mst.course_code " +
                                " inner join instructor_studio_details as isd on isd.course_code = course_mst.course_code and isd.cancel_flag ='N' " +
                                " inner join department_wise_user_dtl as dwu on dwu.dept_code = dwc.dept_code and dwu.prog_code=dwc.prog_code and dwu.semester_type=dwc.semester_type " +
                                " and dwu.year_semester = dwc.year_semester " +

                                " where course_mst.cancel_flag='Y' and course_mst.semester_type ='" + sem_code + "' and course_mst.year_semester = '" + year_code + "'" +
                                " and (course_mst.ugpgoffice_approved = 'N' or course_mst.ugpgoffice_approved is null or course_mst.ugpgoffice_approved = '')" +
                                " and (course_mst.faculty_approved = 'N' or course_mst.faculty_approved is null or course_mst.faculty_approved = '')" +
                                " and dwc.semester_type = '" + sem_code + "' and dwc.year_semester = '" + year_code + "' and course_mst.progcoordinate_approved <> 'Y' and course_mst.ugpgoffice_approved <> 'Y' " +
                                " and dwu.prog_code=dwc.prog_code and dwu.semester_type = '" + sem_code + "' and dwu.year_semester = '" + year_code + "'" +
                                " and dwu.cancel_flag='N' and isd.studio_brief_status='A' and course_mst.progcoordinate_approved='N'  and dwu.user_id = '" + uid + "'";//and ISNULL(dwc.prog_level_code,'')=ISNULL(dwu.prog_level_code,'')

                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_code ='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dwc.prog_level_code ='" + prog_level_code + "' ";
                }

                SqlSelect = SqlSelect + " ORDER BY course_mst.course_code";
            }

            return Get_data(SqlSelect);
        }



        #endregion


        #region Enter Marks List 
        public DataTable course_wise_entered_marks_list_Pending_Approve(string sem_code, string year_code, string dept_code, string prog_code, string user_type, string status)
        {
            String SqlSelect = "";

            if (user_type == "AD" || user_type == "A1")
            {
                SqlSelect = "select res1.*, cwgr.course_code as grade_range_submit, " +
                            " (case grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval', " +
                            " (case grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval', " +
                            " (case grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval'," +
                            " (case grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval',grade_submit_detail.last_modified_date" +
                            " from " +
                            " ( select exams.course_code,exams.course_name,exams.total_exams,students.total_students from" +
                            " (select course_mst.course_code,course_mst.course_name,exams1.total_exams from course_mst " +
                                " left join(select course_code,COUNT(exam_code)total_exams from exam_master" +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'" +
                                            " group by course_code" +
                                        " )exams1" +
                                " on course_mst.course_code=exams1.course_code" +
                                " where course_mst.semester_type='" + sem_code + "' and course_mst.year_semester='" + year_code + "' and cancel_flag='N'" +
                            " )exams" +
                            " left join " +
                                " (SELECT course_code,COUNT(user_id)total_students" +
                                    //" FROM student_wise_course_dtl" +
                                    " FROM student_course_allocate_dtl" +
                                    " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag = 'N'" +
                                    " group by course_code" +
                                " )students" +
                            " on exams.course_code=students.course_code" +
                            " )res1 ";

                SqlSelect = SqlSelect + " inner join (select distinct course_code from student_course_allocate_dtl " +
                                        " where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N' )a on res1.course_code=a.course_code" +
                                        " left join grade_submit_detail on grade_submit_detail.course_code = res1.course_code and grade_submit_detail.semester_type='" + sem_code + "' and grade_submit_detail.year_semester='" + year_code + "' " +
                                        " left join department_wise_course_dtl as dwc on dwc.course_code=res1.course_code" +
                                        "   and dwc.semester_type='" + sem_code + "' and dwc.year_semester='" + year_code + "' and dwc.cancel_flag='N' " +
                                        " left join course_wise_grade_range cwgr on cwgr.course_code = res1.course_code and cwgr.semester_type = '" + sem_code + "' and cwgr.year_semester = '" + year_code + "' and cwgr.cancel_flag='N' ";

                if (status == "P")
                {
                    SqlSelect = SqlSelect + " where a.course_code Not In(select course_code from grade_submit_detail where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' " +
                        "and ugpgoffice_approved ='Y' and cancel_flag ='N')";
                }
                else
                {
                    SqlSelect = SqlSelect + " where a.course_code In(select course_code from grade_submit_detail where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' " +
                    "and ugpgoffice_approved ='Y' and cancel_flag ='N')";
                }

                if (dept_code != "" && prog_code != "")
                    SqlSelect = SqlSelect + " and dwc.dept_code = '" + dept_code + "' and dwc.prog_code = '" + prog_code + "'";
                else if (dept_code != "")
                    SqlSelect = SqlSelect + " and dwc.dept_code = '" + dept_code + "'";
                else if (prog_code != "")
                    SqlSelect = SqlSelect + " and dwc.prog_code = '" + prog_code + "'";

                SqlSelect = SqlSelect + " order by res1.course_code";
            }

            return Get_data(SqlSelect);
        }

        #endregion



        public DataTable course_wise_entered_marks_list_Pending_Approve_midterm(string sem_code, string year_code, string dept_code, string prog_code, string user_type, string status, string prog_level_code, string course_typology)
        {
            String SqlSelect = "";

            if (user_type == "AD" || user_type == "A1")
            {
                SqlSelect = @"select distinct em.course_code, cm.course_name, (case mt.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval',
                    (case mt.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval',  
                    (case mt.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval', 
                    (case mt.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval',mt.last_modified_date
                    from exam_master em
                    left join midterm_grade_submit_detail mt on mt.course_code = em.course_code and mt.semester_type = em.semester_type and mt.year_semester = em.year_semester
                    inner join course_mst cm on cm.course_code = em.course_code and cm.semester_type = em.semester_type and cm.year_semester = em.year_semester
                    inner join department_wise_course_dtl dw on dw.course_code = em.course_code and dw.semester_type = em.semester_type and dw.year_semester = em.year_semester
                    inner join midterm_course_wise_grade_range mc on mc.course_code = em.course_code and mc.semester_type = em.semester_type and mc.year_semester = em.year_semester
                    where em.semester_type ='" + sem_code + "'  and em.year_semester ='" + year_code + "' and em.cancel_flag = 'N' and em.exam_type = 'MT' and cm.cancel_flag = 'N' and dw.cancel_flag = 'N' and mc.cancel_flag='N' ";

                if (status == "P")
                {
                    SqlSelect = SqlSelect + " and em.course_code Not In(select course_code from midterm_grade_submit_detail where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' " +
                        "and ugpgoffice_approved ='Y' and cancel_flag ='N')";
                }
                else if (status == "A")
                {
                    SqlSelect = SqlSelect + " and em.course_code In(select course_code from midterm_grade_submit_detail where semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' " +
                    "and ugpgoffice_approved ='Y' and cancel_flag ='N')";
                }

                if (dept_code != "" && prog_code != "")
                    SqlSelect = SqlSelect + " and dw.dept_code = '" + dept_code + "' and dw.prog_code = '" + prog_code + "'";
                else if (dept_code != "")
                    SqlSelect = SqlSelect + " and dw.dept_code = '" + dept_code + "'";
                else if (prog_code != "")
                    SqlSelect = SqlSelect + " and dw.prog_code = '" + prog_code + "'";

                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and dw.prog_level_code = '" + prog_level_code + "'";
                }

                if (course_typology != "")
                {
                    SqlSelect = SqlSelect + " and dw.course_typology = '" + course_typology + "'";
                }

                SqlSelect = SqlSelect + " order by em.course_code";
            }

            return Get_data(SqlSelect);
        }


        #region Faculty Information


        public DataTable Faculty_information_dtl_list(string sem_code, string year_code, string dept_code, string prog_code, string program_level_code, string type)
        {
            String SqlSelect = "";

            SqlSelect = " Select dwud.user_id,user_mst.full_name,dm.dept_name,plm.prog_level_name,user_mst.mail,user_mst.gender," +
                 " (case dwud.prog_code when '1' then 'Undergraduate' when '2' then 'Postgraduate' when '3' then 'Doctoral' else '' end) ProgramName ";
            if (type == "F")
            {
                SqlSelect += " from department_wise_user_dtl as dwud ";
            }
            if (type == "P")
            {
                SqlSelect += " from programme_coordinator_dtl as dwud ";
            }
            if (type == "D")
            {
                SqlSelect += " from dean_dtl as dwud ";
            }
            SqlSelect += " inner join user_mst on user_mst.user_id = dwud.user_id " +
                 " left join department_mst as dm on dm.dept_code = dwud.dept_code  and  dm.cancel_flag='N' " +
                 " left join programme_level_mst as plm on plm.prog_level_code = dwud.prog_level_code and plm.cancel_flag ='N' " +
                 " where dwud.semester_type ='" + sem_code + "' and dwud.year_semester='" + year_code + "' and dwud.cancel_flag='N'";
            if (dept_code != "")
            {
                SqlSelect += " and dwud.dept_code = '" + dept_code + "'";
            }
            if (program_level_code != "")
            {
                SqlSelect += " and dwud.prog_level_code = '" + program_level_code + "'";
            }
            if (prog_code != "")
            {
                SqlSelect += " and dwud.prog_code = '" + prog_code + "'";
            }

            return Get_data(SqlSelect);
        }

