        public Boolean create_user_new_account(Dictionary<string, object> obj_user_data, string next_doc_no, string password, string reg_user_id)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            // DBCommand.Transaction = DBConnection.BeginTransaction();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                SqlSelect = " IF EXISTS(select * from user_mst where user_id = '" + next_doc_no + "') ";
                SqlSelect += " BEGIN ";
                SqlSelect += " Update user_mst set last_modified_by = '" + reg_user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_midified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',";
                SqlSelect += " doc_no ='" + next_doc_no + "',user_id ='" + next_doc_no + "',user_name ='" + obj_user_data["first_name"].ToString() + " " + obj_user_data["last_name"].ToString() + "',";
                SqlSelect += " user_type = '" + obj_user_data["user_type"].ToString() + "',student_no='" + next_doc_no + "',enrollment_no='" + next_doc_no + "',";

                if (obj_user_data["dept_code"].ToString() != "")
                {
                    SqlSelect += " dept_code ='" + obj_user_data["dept_code"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "dept_code = NULL,";
                }
                if (obj_user_data["prog_code"].ToString() != "")
                {
                    SqlSelect += " prog_code = '" + obj_user_data["prog_code"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "prog_code = NULL,";
                }

                if (obj_user_data["prog_level_code"].ToString() != "")
                {
                    SqlSelect += " prog_level_code = '" + obj_user_data["prog_level_code"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "prog_level_code = NULL,";
                }

                SqlSelect += "first_name = '" + obj_user_data["first_name"].ToString() + "',last_name = '" + obj_user_data["last_name"].ToString() + "',full_name = '" + obj_user_data["first_name"].ToString() + " " + obj_user_data["last_name"].ToString() + "',";

                if (obj_user_data["gender"].ToString() != "")
                {
                    SqlSelect += " gender = '" + obj_user_data["gender"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "gender = NULL,";
                }

                if (obj_user_data["blood_group"].ToString() != "")
                {
                    SqlSelect += " blood_group = '" + obj_user_data["blood_group"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "blood_group = NULL,";
                }

                SqlSelect += "user_status_flag = '" + obj_user_data["user_status_flag"].ToString() + "',status = '" + obj_user_data["status"].ToString() + "',cancel_flag ='" + obj_user_data["cancel_flag"].ToString() + "',mail ='" + obj_user_data["mail"].ToString() + "',mobile_no='" + obj_user_data["mobile_no"].ToString() + "', dob='" + obj_user_data["dob"].ToString() + "'  where user_id ='" + next_doc_no + "'";

                SqlSelect += " END";
                SqlSelect += " ELSE";
                SqlSelect += " BEGIN ";

                SqlSelect += " INSERT INTO user_mst (doc_no,user_id,user_name,user_type,student_no,enrollment_no,dept_code,prog_code,prog_level_code, " +
                            " first_name,last_name,full_name,password,gender,blood_group,start_date,pass_expiry_date,user_status_flag,status,cancel_flag, " +
                            " created_by,created_date,created_host,mail,mobile_no,dob) ";

                SqlSelect += " VALUES('" + next_doc_no + "', '" + next_doc_no + "','" + obj_user_data["first_name"].ToString() + " " + obj_user_data["last_name"].ToString() + "'," +
                              "'" + obj_user_data["user_type"].ToString() + "','" + next_doc_no + "','" + next_doc_no + "',";

                if (obj_user_data["dept_code"].ToString() != "")
                {
                    SqlSelect += " '" + obj_user_data["dept_code"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "NULL,";
                }
                if (obj_user_data["prog_code"].ToString() != "")
                {
                    SqlSelect += " '" + obj_user_data["prog_code"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "NULL,";
                }

                if (obj_user_data["prog_level_code"].ToString() != "")
                {
                    SqlSelect += " '" + obj_user_data["prog_level_code"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "NULL,";
                }

                SqlSelect += "'" + obj_user_data["first_name"].ToString() + "','" + obj_user_data["last_name"].ToString() + "','" + obj_user_data["first_name"].ToString() + " " + obj_user_data["last_name"].ToString() + "','" + password + "',";

                if (obj_user_data["gender"].ToString() != "")
                {
                    SqlSelect += " '" + obj_user_data["gender"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "NULL,";
                }

                if (obj_user_data["blood_group"].ToString() != "")
                {
                    SqlSelect += " '" + obj_user_data["blood_group"].ToString() + "', ";
                }
                else
                {
                    SqlSelect += "NULL,";
                }

                SqlSelect += " GETDATE(), GETDATE() + 2190, '" + obj_user_data["user_status_flag"].ToString() + "', '" + obj_user_data["status"].ToString() + "', '" + obj_user_data["cancel_flag"].ToString() + "', '" + reg_user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "','" + obj_user_data["mail"].ToString() + "','" + obj_user_data["mobile_no"].ToString() + "','" + obj_user_data["dob"].ToString() + "')";

                SqlSelect += " END ";


                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DBCommand.ExecuteNonQuery();

                //  DBCommand.Transaction.Commit();

                DBConnection.Close();
                return true;
            }
            catch (Exception Ex)
            {
                //  DBCommand.Transaction.Rollback();
                DBConnection.Close();
                return false;
            }
        }



