        #region Block User Fees and other Services 
        public DataTable Get_Block_user_list(string sem_code, string year_code, string year_allocation, string block_type, string report_type)
        {
            String SqlSelect = "";

            SqlSelect = " select user_mst.user_id, (case  when user_name = '' then (case when first_name = '' then (case when full_name = '' then NULL else full_name end)" +
                        " else first_name end) else user_name end) as name, (Case when mail ='' then Null else mail end) mail,stb.cancel_flag as block_cancel_flag,stb.semester_type,stb.year_semester,stb.course_code,stb.remark from user_mst " +
                        " left join student_marksheet_blocklist as stb on stb.user_id = user_mst.user_id and stb.cancel_flag in('N','M') and  stb.block_type='" + block_type + "' " +
                        " and stb.semester_type='" + sem_code + "' and stb.year_semester ='" + year_code + "' " +
                        " where  user_mst.user_type='S' and user_mst.cancel_flag='N' and user_mst.year_code ='" + year_allocation + "' and user_mst.user_status_flag='A' and user_mst.status='A' ";
            if (report_type == "E")
            {
                if (block_type == "feesnotpaid")
                {
                    SqlSelect += " and user_mst.user_id NOT IN (select user_id from student_marksheet_blocklist where semester_type ='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='M' and block_type='" + block_type + "')";
                }
                else
                {
                    SqlSelect += " and user_mst.user_id NOT IN (select user_id from student_marksheet_blocklist where semester_type ='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' and block_type='" + block_type + "')";
                }
            }
            else
            {
                string cancel_flag = "N";
                if (block_type == "feesnotpaid")
                {
                    cancel_flag = "M";
                }
                SqlSelect += " and user_mst.user_id IN (select user_id from student_marksheet_blocklist where semester_type ='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='" + cancel_flag + "' and block_type='" + block_type + "')";
            }
            return Get_data(SqlSelect);
        }


