            SqlSelect = " select pc.doc_no,pc.dept_code,pc.prog_code,pc.prog_level_code,pc.user_id,pc.semester_type,pc.year_semester,pc.letter_label, " +
                        " (case  when user_name = '' then (case when first_name = '' then (case when full_name = '' then NULL else full_name end) else first_name end) else user_name end) as full_name, " +
                        " dm.dept_name,pm.prog_name,plm.prog_level_desc,plm.prog_level_name,(select MAX(doc_no) from programme_coordinator_dtl where semester_type ='S' and year_semester ='2021') as number,pc.cancel_flag  " +
                        " from programme_coordinator_dtl as pc " +
