        public bool previous_semester_data_pcs(String UserID, DataTable dataTable, String new_sem_code, String new_year_code)
        {


            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = " Insert into programme_coordinator_dtl (doc_no,dept_code,prog_code,prog_level_code,user_id,cancel_flag,created_by,created_date,created_host,semester_type,year_semester,letter_label) Values";
            for (int i = 0; i < dataTable.Rows.Count; i++)
            {
                string doc = new_sem_code + new_year_code + (101 + i);
                SqlSelect += "('" + doc + "','" + dataTable.Rows[i]["dept_code"].ToString() + "','" + dataTable.Rows[i]["prog_code"].ToString() + "',";
                if (dataTable.Rows[i]["prog_level_code"].ToString() != "")
                {
                    SqlSelect += " '" + dataTable.Rows[i]["prog_level_code"].ToString() + "',";
                }
                else { SqlSelect += "NULL,"; }
                SqlSelect += " '" + dataTable.Rows[i]["user_id"].ToString() + "','" + dataTable.Rows[i]["cancel_flag"].ToString() + "',";
                SqlSelect += " '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + HttpContext.Current.Request.UserHostName + "',";
                SqlSelect += " '" + new_sem_code + "','" + new_year_code + "',";

                if (dataTable.Rows[i]["letter_label"].ToString() != "")
                {
                    SqlSelect += " '" + dataTable.Rows[i]["letter_label"].ToString() + "')";
                }
                else { SqlSelect += "NULL)"; }
                if (i < dataTable.Rows.Count - 1)
                {
                    SqlSelect += ',';
                }
            }

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return false;
            }
            return true;
        }


