        public DataTable Max_number_doc_pc(String sem_code, String year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " Select t1.doc + 01 as doc  " +
