        public string ws_remove_all_exam_dtl(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            int res = 0;

            SqlSelect = "DECLARE @course varchar(10);SET @course='" + course_code + "';";
            SqlSelect += "DECLARE @sem varchar(1);SET @sem='" + sem_code + "';";
            SqlSelect += "DECLARE @year varchar(5);SET @year='" + year_code + "';";
            SqlSelect += @"
                        delete from ws_exam_master where course_code=@course and semester_type=@sem and year_semester=@year
                        delete from ws_student_exam_marks_dtl where course_code=@course and semester_type=@sem and year_semester=@year";

            DBCommand.CommandText = SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();

                res = DBCommand.ExecuteNonQuery();

                if (res > 0)
                {
                    return "All Exams Removed Successfully";
                }
                else
                {
                    return "Problem in removing all exams, Please try again.";
                }
            }
            catch (Exception ex)
            {
                return "Problem in removing all exams, " + ex.ToString();
            }

            DBConnection.Close();
            return "";
        }
