                     + " BEGIN "
                     + " update student_wise_registration_timer_dtl set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', remaining_milisecond ='" + milisecond + "' where user_id = '" + user_id + "' and cancel_flag='N'" +
                       " and semester_type ='" + sem_code + "' and year_semester = '" + year_code + "'"
