            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "IF EXISTS(select * from student_wise_course_timer_dtl where user_id='" + user_id + "' and semester_type='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag='N' and course_code='" + course_code + "' and course_type='E') "
                    + " BEGIN "
                    + " UPDATE student_wise_course_timer_dtl set cancel_flag ='Y',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where course_code ='" + course_code + "' and course_type ='E' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag ='N'  "
                    + " END "
                + " ELSE "
                    + " BEGIN "
                    + " Insert into student_wise_course_timer_dtl (user_id,course_code,course_type,credits,gpa_nongpa,status,cancel_flag,semester_type,year_semester,created_by,created_host,created_date) "
                    + " values('" + user_id + "', '" + course_code + "','E','" + credits + "','" + gpa_ngpa + "','R', 'N','" + sem_code + "','" + year_code + "', '" + user_id + "', '" + host_name + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "')"
                    + " END ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return false;
            }
            return true;
        }

        //Mayur 09072021
        public string save_student_course_timer_dtl(String user_id, String host_name, String sem_code, String year_code, String course_code, String credits, String checkbox_status, String gpa_ngpa)
        {
            string status = "";
            try
            {
                if (checkbox_status == "true")
                {
                    DataSet ds_check_seat = get_count_for_course_registration(course_code, sem_code, year_code, user_id);

                    if (ds_check_seat.Tables[0].Rows.Count > 0)
                    {
                        int available_seats = Convert.ToInt32(ds_check_seat.Tables[0].Rows[0]["Available_Seat"].ToString());
                        int waiting_seats = Convert.ToInt32(available_seats * 0.5);
                        int registered_seats = Convert.ToInt32(ds_check_seat.Tables[1].Rows[0]["Registered_Seat"].ToString());
                        int waited_seats = Convert.ToInt32(ds_check_seat.Tables[2].Rows[0]["Waited_Seat"].ToString());

                        if (available_seats > registered_seats)
                        {
                            status = "R";
                        }
                        else if (waiting_seats > waited_seats)
                        {
                            status = "W";
                        }
                        else
                        {
                            return "This course has no seats available and the waiting list is full. Please choose another course.";
                        }

                        DataTable dt_stud_dtl = get_student_course_registered_dtl(course_code, sem_code, year_code, user_id);

                        if (dt_stud_dtl == null)
                        {
                            DBConnection.Open();
                            DBDataAdpterObject.SelectCommand.Parameters.Clear();

                            String DocNo = "";
                            String message = "";

                            if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "CT", user_id, host_name, ref DocNo, ref message))
                            {
                                DBCommand.Transaction.Rollback();
                                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                                return "Problem in getting NextDocNo. Please try again.";
                            }

                            String SqlSelect = "";
                            SqlSelect = "Insert into student_wise_course_timer_dtl (doc_no, user_id,course_code,course_type,credits,gpa_nongpa,status,cancel_flag,semester_type,year_semester,created_by,created_host,created_date) "
                                    + " values('" + DocNo + "', '" + user_id + "', '" + course_code + "','E','" + credits + "','" + gpa_ngpa + "','" + status + "', 'N','" + sem_code + "','" + year_code + "', '" + user_id + "', '" + host_name + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "')";
                            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                            try
                            {
                                DBCommand.ExecuteNonQuery();
                                DBConnection.Close();
                                return "True";
                            }
                            catch (Exception ex)
                            {
                                DBConnection.Close();
                                return "Problem in Course Selection, Please try again.";
                            }
                        }
                        else
                        {
                            //return "You have already choosed this course. Please select another course.";
                        }
                    }
                    else
                    {
                        return "Availble Seat is not , Please try again.";
                    }
                }
                else if (checkbox_status == "false")
                {
                    DBConnection.Open();
                    DBDataAdpterObject.SelectCommand.Parameters.Clear();
                    String SqlSelect = "";
                    SqlSelect = "IF EXISTS(select * from student_wise_course_timer_dtl where user_id='" + user_id + "' and semester_type='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag='N' and course_code='" + course_code + "' and course_type='E') "
                            + " BEGIN "
                            + " UPDATE student_wise_course_timer_dtl set cancel_flag ='Y',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where course_code ='" + course_code + "' and course_type ='E' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag ='N' and user_id='" + user_id + "'"
                            + " END ";
                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                    try
                    {
                        DBCommand.ExecuteNonQuery();
                        DBConnection.Close();
                        return "True";
                    }
                    catch (Exception Ex)
                    {
                        DBConnection.Close();
                        return "Problem in Remove Course Selection, Please try again.";
                    }
                }
            }
            catch (Exception Ex)
            {
                return "Problem in Course Selection, Please try again.";
            }

            return "True";
        }

        public DataSet get_count_for_course_registration(string course_code, string sem_code, string year_code, string user_id)
        {
            String SqlSelect = "";

            if (user_id == "")
            {
                SqlSelect = "select available_seat as Available_Seat from department_wise_course_dtl where course_code = '" + course_code + "' and cancel_flag = 'N' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "'";

                SqlSelect = SqlSelect + "select COUNT(*) as Registered_Seat from student_wise_course_timer_dtl where course_code = '" + course_code + "' and status in ('R', 'A') and cancel_flag = 'N' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "'";

                SqlSelect = SqlSelect + "select COUNT(*) as Waited_Seat from student_wise_course_timer_dtl where course_code = '" + course_code + "' and status in ('W') and cancel_flag = 'N' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "'";
            }
            else if (user_id != "")
            {
                SqlSelect = "select available_seat as Available_Seat from department_wise_course_dtl where course_code = '" + course_code + "' and cancel_flag = 'N' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "'";

                SqlSelect = SqlSelect + " select COUNT(*) as Registered_Seat from student_wise_course_timer_dtl where course_code = '" + course_code + "' and status in ('R', 'A') and cancel_flag = 'N' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and user_id <> '" + user_id + "'";

                SqlSelect = SqlSelect + " select COUNT(*) as Waited_Seat from student_wise_course_timer_dtl where course_code = '" + course_code + "' and status in ('W') and cancel_flag = 'N' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and user_id <> '" + user_id + "'";
            }

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                return ds;
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public DataTable get_student_course_registered_dtl(string course_code, string sem_code, string year_code, string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select * from student_wise_course_timer_dtl where course_code = '" + course_code + "' and cancel_flag = 'N' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and user_id='" + user_id + "' order by priority, created_date";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                {
                    return ds.Tables[0];
                }
            }
            catch (Exception ex)
            {
                return null;
            }
        }

