        public DataTable Get_course_wise_allocated_remaining_sets_dtl(string dept_code, string prog_code, string sem_code, string year_code, string prog_level_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select distinct t1.course_code,t1.available_seat,Count (swct.course_code) as allocated_sets,(t1.available_seat - Count (swct.course_code) ) as remaining_sets,t1.course_credits,t1.course_type,t1.semester_type,t1.year_semester " +
                        " from " +
                        " (select department_wise_course_dtl.dept_code,department_mst.dept_name,department_wise_course_dtl.prog_code,course_mst.course_code, course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type,department_wise_course_dtl.semester_code, " +
                        " course_mst.course_desc,course_mst.prerequisite,department_wise_course_dtl.available_seat,course_mst.semester_type,course_mst.year_semester from course_mst " +
                        " INNER JOIN  department_wise_course_dtl on course_mst.course_code = department_wise_course_dtl.course_code and department_wise_course_dtl.course_typology in ('24') " +
                        " INNER JOIN department_mst on department_wise_course_dtl.dept_code = department_mst.dept_code " +
                        " where course_mst.cancel_flag = 'N'  and department_wise_course_dtl.dept_code=@dept_code and department_wise_course_dtl.course_type='E' " +
                        " and department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "' " +
                        " and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.backlog='N'";

            SqlSelect = SqlSelect + " UNION ";

            SqlSelect = SqlSelect + " select department_wise_course_dtl.dept_code,department_mst.dept_name,department_wise_course_dtl.prog_code,course_mst.course_code, course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type,department_wise_course_dtl.semester_code," +
                        " course_mst.course_desc,course_mst.prerequisite,department_wise_course_dtl.available_seat,course_mst.semester_type,course_mst.year_semester " +
                        " from course_mst " +
                        " INNER JOIN department_wise_course_dtl  on course_mst.course_code = department_wise_course_dtl.course_code and department_wise_course_dtl.course_typology in ('24') " +
                        " INNER JOIN department_mst  on department_wise_course_dtl.dept_code = department_mst.dept_code " +
                        " where course_mst.cancel_flag = 'N'  and  department_wise_course_dtl.dept_code=@dept_code and department_wise_course_dtl.course_type='M' " +
                        " and department_wise_course_dtl.prog_code <>@prog_code  and  department_wise_course_dtl.semester_type = '" + sem_code + "' and department_wise_course_dtl.year_semester = '" + year_code + "'" +
                        " and  course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.backlog='N' ";

            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " UNION " +
                            " select department_wise_course_dtl.dept_code,department_mst.dept_name,department_wise_course_dtl.prog_code, course_mst.course_code,course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type,  department_wise_course_dtl.semester_code," +
                            " course_mst.course_desc,course_mst.prerequisite,department_wise_course_dtl.available_seat,course_mst.semester_type,course_mst.year_semester from course_mst " +
                            " INNER JOIN department_wise_course_dtl  on course_mst.course_code = department_wise_course_dtl.course_code and department_wise_course_dtl.course_typology in ('24') " +
                            " INNER JOIN department_mst  on department_wise_course_dtl.dept_code = department_mst.dept_code " +
                            " where course_mst.cancel_flag = 'N'  and  department_wise_course_dtl.dept_code=@dept_code  and department_wise_course_dtl.course_type='M' " +
                            " and department_wise_course_dtl.prog_code =@prog_code and department_wise_course_dtl.prog_level_code <> @prog_level_code  and department_wise_course_dtl.semester_type = '" + sem_code + "' " +
                            " and department_wise_course_dtl.year_semester = '" + year_code + "'  and course_mst.semester_type = '" + sem_code + "' and course_mst.year_semester = '" + year_code + "' and course_mst.backlog='N' ";

                if (prog_level_code == "PA1" || prog_level_code == "PP" || prog_level_code == "PM")
                {
                    SqlSelect = SqlSelect + " UNION " +

                         " select department_wise_course_dtl.dept_code,department_mst.dept_name,department_wise_course_dtl.prog_code, course_mst.course_code,course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type,  department_wise_course_dtl.semester_code," +
                            " course_mst.course_desc,course_mst.prerequisite,department_wise_course_dtl.available_seat,course_mst.semester_type,course_mst.year_semester from course_mst " +
                            " INNER JOIN department_wise_course_dtl  on course_mst.course_code = department_wise_course_dtl.course_code and department_wise_course_dtl.course_typology in ('24') " +
                            " INNER JOIN department_mst  on department_wise_course_dtl.dept_code = department_mst.dept_code " +
                            " where course_mst.cancel_flag = 'N'  and  department_wise_course_dtl.dept_code=@dept_code  and department_wise_course_dtl.course_type='M' " +
                            " and department_wise_course_dtl.prog_code =@prog_code and department_wise_course_dtl.prog_level_code <> @prog_level_code  and department_wise_course_dtl.semester_type = '" + sem_code + "' " +
