                    SqlSelect = SqlSelect + " select *,department_wise_course_dtl.dept_code,department_mst.dept_name,department_wise_course_dtl.prog_code, course_mst.course_code,  course_mst.course_name,course_mst.course_credits,department_wise_course_dtl.course_type, " +
                            " department_wise_course_dtl.semester_code,  course_mst.course_desc,course_mst.prerequisite from course_mst " +
                            " INNER JOIN department_wise_course_dtl  on course_mst.course_code = department_wise_course_dtl.course_code and department_wise_course_dtl.course_typology in ('24') " +
                            " INNER JOIN department_mst  on department_wise_course_dtl.dept_code = department_mst.dept_code  " +
