                        " left join student_wise_course_dtl as swct on swct.course_code = t1.course_code and swct.semester_type = t1.semester_type and swct.status='A' and swct.cancel_flag='N' " +
                        " and swct.year_semester = t1.year_semester " +
                        " Group by t1.dept_code,t1.dept_name,t1.prog_code,t1.course_code, t1.course_name,t1.course_credits,t1.course_type,t1.semester_code, t1.course_desc,t1.prerequisite,t1.available_seat,t1.semester_type,t1.year_semester ";

            IDataParameter para1 = DBObjectFactory.GetParameterObject();
