            //            " and student_wise_course_dtl.cancel_flag = dwcd.cancel_flag and student_wise_course_dtl.course_type ='M' " +
            //            " where dwcd.cancel_flag='N' and dwcd.semester_type = '"+ sem_code + "' and dwcd.year_semester='"+ year_code + "'  ";

            SqlSelect = " select t1.course_code,t1.available_seat,t1.allocated_seat,t1.mandatory_seats_count,t1.semester_type,t1.year_semester, " +
                " Count(waiting.course_code) as total_wating_seats,CAST(ROUND(0.5*CAST(t1.available_seat as decimal(18,2)),0) as decimal(18,0)) as round_value from ( " +
                " select distinct dwcd.course_code, COUNT(swct.course_code) as allocated_seat,dwcd.available_seat, " +
                " COUNT(student_wise_course_dtl.course_code) as mandatory_seats_count,MAX(dwcd.semester_type) as semester_type ,MAX(dwcd.year_semester) as year_semester " +
                " from department_wise_course_dtl as dwcd " +
                " left join student_wise_course_timer_dtl as swct on swct.course_code = dwcd.course_code and swct.semester_type = dwcd.semester_type " +
                " and swct.year_semester = dwcd.year_semester and swct.status ='R' and swct.cancel_flag = dwcd.cancel_flag " +
                " left join student_wise_course_dtl on student_wise_course_dtl.course_code = dwcd.course_code and student_wise_course_dtl.semester_type = dwcd.semester_type " +
                " and  student_wise_course_dtl.year_semester = dwcd.year_semester and student_wise_course_dtl.status in ('S','R','A') " +
                " and student_wise_course_dtl.cancel_flag = dwcd.cancel_flag and student_wise_course_dtl.course_type ='M' " +
                " where dwcd.cancel_flag='N' and dwcd.semester_type = '" + sem_code + "' and dwcd.year_semester='" + year_code + "' ";

            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and dwcd.course_code ='" + course_code + "' ";
            }
            SqlSelect = SqlSelect + " GROUP By swct.course_code,dwcd.available_seat,dwcd.course_code ) t1 " +
                " left join student_wise_course_timer_dtl as waiting on waiting.course_code = t1.course_code and waiting.semester_type = t1.semester_type " +
                " and waiting.year_semester = t1.year_semester and waiting.cancel_flag ='N' and waiting.status='W' " +
                " Group by t1.course_code,t1.available_seat,t1.allocated_seat,t1.mandatory_seats_count,t1.semester_type,t1.year_semester,waiting.course_code ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                {
                    return ds.Tables[0];
                }
            }
            catch (Exception ex)
            {
                return null;
            }
        }

