        #region drp changes
        public DataTable Student_wise_drp_dtl(String user_id, String sem_code, String year_code, String status, String dept_code, String prog_code)
        {    //
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (status == "S")
            {
                SqlSelect = " Select distinct course_wise_drp_dtl.drp_code,course_wise_drp_dtl.course_code,course_wise_drp_dtl.topic,course_wise_drp_dtl.abstracts, " +
                            " course_wise_drp_dtl.reference,course_wise_drp_dtl.doc_path,user_mst.full_name from course_wise_drp_dtl " +
                            " left join user_mst on user_mst.user_id = course_wise_drp_dtl.instructor_code " +
                            " left join department_wise_course_dtl on department_wise_course_dtl.course_code = course_wise_drp_dtl.course_code  and department_wise_course_dtl.semester_type = course_wise_drp_dtl.semester_type and " +
                            " department_wise_course_dtl.year_semester = course_wise_drp_dtl.year_semester and department_wise_course_dtl.cancel_flag='N' " +
                            " where course_wise_drp_dtl.cancel_flag='N' and course_wise_drp_dtl.semester_type='" + sem_code + "' and course_wise_drp_dtl.year_semester='" + year_code + "'";
                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = '" + dept_code + "'";
                }
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = '" + prog_code + "'";
                }
            }
            else
            {
                SqlSelect = "";
                SqlSelect = " select t1.user_id,t1.course_code,t1.drp_code,t1.seat_type,t1.topic,t1.abstracts,t1.reference,t1.doc_path,t1.instructor_code,user_mst.full_name as instructor_name,t1.full_name from( " +
                            " select swd.user_id,user_mst.full_name,swd.course_code,swd.drp_code,  " +
                            " CASE When swd.seat_type = 'F' THEN 'FUNDED' else 'UN-FUNDED' END seat_type, " +
                            " cwd.topic,cwd.abstracts,cwd.reference, cwd.doc_path,cwd.instructor_code from student_wise_drp_dtl as swd" +
                            " inner join user_mst on user_mst.user_id = swd.user_id " +
                            " inner join course_wise_drp_dtl as cwd on cwd.drp_code = swd.drp_code  and cwd.semester_type = swd.semester_type and cwd.year_semester = swd.year_semester and cwd.cancel_flag='N' " +
                            " left join department_wise_course_dtl on department_wise_course_dtl.course_code = swd.course_code  and department_wise_course_dtl.semester_type = swd.semester_type and " +
                            " department_wise_course_dtl.year_semester = swd.year_semester and department_wise_course_dtl.cancel_flag='N' " +
                            " where swd.semester_type ='" + sem_code + "' and swd.year_semester ='" + year_code + "' and swd.cancel_flag='N' and swd.user_id='" + user_id + "'";
                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = '" + dept_code + "'";
                }
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code = '" + prog_code + "'";
                }

                SqlSelect = SqlSelect + ") t1";

                SqlSelect = SqlSelect + " left join user_mst on user_mst.user_id = t1.instructor_code  ";
            }



            return Get_data(SqlSelect);
        }

