        public Boolean insert_birth_school_leaving_certificate_dtl(string user_id, string host_name, string birth_filename, string school_leaving_filename, string status, string dob)
        {
            String FileType = "";


            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            // DBCommand.Transaction = DBConnection.BeginTransaction();

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";


            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                SqlSelect = "";

                SqlSelect = "IF EXISTS(select * from student_certificate_dtl where user_id = '" + user_id + "' and cancel_flag='N') "
                     + " BEGIN "
                     + " update student_certificate_dtl set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', is_submit ='" + status + "'";
                if (birth_filename != "")
                {
                    SqlSelect += ",birth_certificate ='" + birth_filename + "'";
                }
                else
                {
                    SqlSelect += ",birth_certificate =NULL";
                }
                if (school_leaving_filename != "")
                {
                    SqlSelect += ",school_leaving_certificate ='" + school_leaving_filename + "'";
                }
                else
                {
                    SqlSelect += ",school_leaving_certificate =NULL";
                }
                SqlSelect += " where user_id = '" + user_id + "' and cancel_flag='N'";

                SqlSelect += " update user_mst set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_midified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', dob = Convert(datetime2, '" + dob + "', 104) where user_id = '" + user_id + "' and cancel_flag='N'";

                SqlSelect += " END ELSE BEGIN ";

                SqlSelect += " Insert into student_certificate_dtl(user_id, birth_certificate,school_leaving_certificate,is_submit, cancel_flag, created_by, created_host, created_date) values('" + user_id + "' ";

                if (birth_filename != "")
                {
                    SqlSelect += ",'" + birth_filename + "'";
                }
                else
                {
                    SqlSelect += ",NULL";
                }
                if (school_leaving_filename != "")
                {

                    SqlSelect += ",'" + school_leaving_filename + "'";
                }
                else
                {
                    SqlSelect += ",NULL";
                }
                SqlSelect += " , '" + status + "', 'N', '" + user_id + "', '" + host_name + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "') "
                    + " update user_mst set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_midified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', dob = Convert(datetime2, '" + dob + "', 104) where user_id = '" + user_id + "' and cancel_flag='N'"
                     + " END ";



                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception)
            {
                DBConnection.Close();
                return false;
            }
        }



        public DataTable Get_mandatory_certificate_dtl(string user_id)
        {
            DataTable dt = Get_cept_current_sem_data("all");
            DataTable dt_parameter = get_parameter_value("antiragging_certificate");
            String SqlSelect = "";
            SqlSelect = " select user_mst.user_id,SUBSTRING(user_mst.year_code,2,4) as year_code,user_mst.profile_photo, user_mst.dob,user_mst.blood_group,sac.file_path as antiragging_certificate,smc.file_path as medical_certificate, " +
                " scd.birth_certificate,scd.school_leaving_certificate,scd.covid_vaccine_1_certificate,scd.covid_vaccine_2_certificate,scd.vaccination_status,scd.consent_status," +
                " SAID.apaar_id,CASE When SAID.apaar_id IS NULL Then CASE When SMB.cancel_flag = 'N' Then 'Y' Else 'N' END Else 'Y' END  apaaridStatus ,SMB.cancel_flag as apaaridbypass," +
                " CASE When SAID.apaar_id IS NULL Then 'N' Else 'Y' END  apaaridsaveornot " +//spcd.consent_status,
                " from user_mst " +
                " left join student_antiragging_certificate as sac on sac.user_id = user_mst.user_id and sac.cancel_flag='N' and sac.year_code='" + dt_parameter.Rows[0]["parameter_value"].ToString().Trim() + "' " +
                " left join student_medical_certificate as smc on smc.user_id = user_mst.user_id and smc.cancel_flag='N' and smc.year_code='" + dt_parameter.Rows[0]["parameter_value"].ToString().Trim() + "' " +
                " left join student_certificate_dtl as scd on scd.user_id = user_mst.user_id and scd.cancel_flag ='N' " +
                " left join STUDENT_ID_MASTER as SAIDM on SAIDM.student_id = user_mst.user_id and SAIDM.cancel_flag ='N' " +
                " left join STUDENT_APAAR_ID as SAID on SAID.university_register_id = SAIDM.university_register_id and SAID.cancel_flag ='N' " +
                " LEFT JOIN student_marksheet_blocklist SMB on SMB.user_id = user_mst.user_id " +
                " AND SMB.semester_type='" + dt.Rows[0]["sem_code"].ToString() + "' AND SMB.year_semester='" + dt.Rows[0]["year_code"].ToString() + "' AND SMB.cancel_flag='N' AND SMB.block_type='apaar_disable'" +
                //" left join student_parental_consent_dtl spcd on spcd.user_id = user_mst.user_id and " +
                //" spcd.semester_type ='" + dt.Rows[0]["sem_code"].ToString() + "' and spcd.year_semester ='" + dt.Rows[0]["year_code"].ToString() + "' " +
                " where user_mst.user_id='" + user_id + "' ";
            if (user_id.Substring(0, 2).ToString() == "EX")
            {
                SqlSelect = "";
            }

            return Get_data(SqlSelect);
        }


