        public DataTable Get_Certificate_dtl_with_sr_no(string sr_no)
        {
            int to_sr_no = Convert.ToInt32(sr_no) + 200;
            String SqlSelect = "";
            SqlSelect = " select * from (select ROW_NUMBER( )Over (Order by user_mst.user_id asc) As sr_no,smc.user_id,user_mst.full_name, smc.file_path as medical_file_path,sac.file_path as antirigging_file_path,scd.birth_certificate," +
                " scd.school_leaving_certificate," +
                " scd.covid_vaccine_1_certificate,scd.covid_vaccine_2_certificate,scd.consent_form_path, scd.consent_status, scd.is_submit as dob, scd.vaccination_status,user_mst.profile_photo,user_mst.blood_group,convert(varchar(20),user_mst.dob,105) as user_dob  " +
                " from student_medical_certificate as smc " +
                " inner join user_mst on user_mst.user_id = smc.user_id " +
                " left join  student_antiragging_certificate as sac on sac.user_id = smc.user_id and sac.cancel_flag='N' " +
                " left join student_certificate_dtl as scd on scd.user_id = smc.user_id and scd.cancel_flag='N' " +
                " where smc.cancel_flag='N') t1 where t1.sr_no BETWEEN '" + sr_no + "' AND '" + Convert.ToString(to_sr_no) + "'";

            return Get_data(SqlSelect);
        }

        public DataTable Get_Certificate_dtl(string year_code, string dept_code, string prog_code, string sem_code)
        {

            String SqlSelect = "";
            //SqlSelect = " select ROW_NUMBER( )Over (Order by user_mst.user_id asc) As sr_no,smc.user_id,user_mst.full_name, smc.file_path as medical_file_path,sac.file_path as antirigging_file_path,scd.birth_certificate," +
            //    " scd.school_leaving_certificate," +
            //    " scd.covid_vaccine_1_certificate,scd.covid_vaccine_2_certificate,scd.consent_form_path, scd.consent_status, scd.is_submit as dob, scd.vaccination_status,user_mst.profile_photo,user_mst.blood_group,convert(varchar(20),user_mst.dob,105) as user_dob," +
            //    " convert(varchar(20),smc.created_date,105) as created_date,convert(varchar(20),smc.last_modified_date,105) as last_modified_date " +
            //    " from student_medical_certificate as smc " +
            //    " inner join user_mst on user_mst.user_id = smc.user_id " +
            //    " left join  student_antiragging_certificate as sac on sac.user_id = smc.user_id and sac.cancel_flag='N' " +
            //    " left join student_certificate_dtl as scd on scd.user_id = smc.user_id and scd.cancel_flag='N' " +
            //    " where smc.cancel_flag='N' order by smc.created_date asc ";


            SqlSelect = @" select ROW_NUMBER( )Over (Order by user_mst.user_id asc) As sr_no,user_mst.user_id,user_mst.full_name, smc.file_path as medical_file_path,
                          sac.file_path as antirigging_file_path,scd.birth_certificate,
                          scd.school_leaving_certificate,
                          scd.covid_vaccine_1_certificate,scd.covid_vaccine_2_certificate,scd.consent_form_path, scd.consent_status, scd.is_submit as dob,
                          scd.vaccination_status,user_mst.profile_photo,user_mst.blood_group,convert(varchar(20),user_mst.dob,105) as user_dob,
                          convert(varchar(20),smc.created_date,105) as created_date,convert(varchar(20),smc.last_modified_date,105) as last_modified_date,scd.studio_type,user_mst.enrollment_no 
                          from student_certificate_dtl as scd
                          left join student_medical_certificate as smc on smc.user_id = scd.user_id and smc.cancel_flag ='N'";
            if (sem_code != "")
            {
                SqlSelect += " and smc.year_code = '" + sem_code + "'";
            }
            SqlSelect += @"left join  student_antiragging_certificate as sac on sac.user_id = smc.user_id and sac.cancel_flag='N'";
            if (sem_code != "")
            {
                SqlSelect += " and sac.year_code = '" + sem_code + "'";
            }
            SqlSelect += @"inner join user_mst on user_mst.user_id = scd.user_id and user_mst.cancel_flag ='N' 
                          where scd.cancel_flag='N' ";

            if (year_code != "")
            {
                SqlSelect += " and user_mst.year_code = '" + year_code + "'";
            }
            if (dept_code != "")
            {
                SqlSelect += " and user_mst.dept_code = '" + dept_code + "'";
            }
            if (prog_code != "")
            {
                SqlSelect += " and user_mst.prog_code = '" + prog_code + "'";
            }
            SqlSelect += " order by smc.created_date asc";



            return Get_data(SqlSelect);
        }

        public DataTable Get_Certificate_dtl_datewise(string year_code, string dept_code, string prog_code)
        {
            StringBuilder SqlSelect = new StringBuilder();

            SqlSelect.Append(" select dd.user_id,MAX(convert(varchar(20),dd.created_date,105)) as create_date,MAX(convert(varchar(20),dd.last_modified_date,105)) as last_modified_date from");
            SqlSelect.Append(" (select user_id, created_date,last_modified_date from student_certificate_dtl where cancel_flag ='N'");
            SqlSelect.Append(" union  select user_id,created_date,last_modified_date from student_medical_certificate where cancel_flag ='N'");
            SqlSelect.Append(" union  select  user_id,created_date,last_modified_date from student_antiragging_certificate where cancel_flag ='N' ) as dd ");
            SqlSelect.Append(" inner join user_mst on user_mst.user_id = dd.user_id  where 1=1");
            if (year_code != "")
            {
                SqlSelect.Append(" and user_mst.year_code = '" + year_code + "'");
            }
            if (dept_code != "")
            {
                SqlSelect.Append(" and user_mst.dept_code = '" + dept_code + "'");
            }
            if (prog_code != "")
            {
                SqlSelect.Append(" and user_mst.prog_code = '" + prog_code + "'");
            }
            SqlSelect.Append(" GROUP BY dd.user_id ");

            return Get_data(Convert.ToString(SqlSelect));
        }


