        public string CombinePDF_Student_Certificate(String type, string year_code, string dept_code, string prog_code, string sem_code)
        {
            try
            {
                string Path = "";
                string FileName = "";

                if (type == "m")
                {
                    Path = HttpContext.Current.Server.MapPath("~/MedicalCertificate");
                }
                else if (type == "a")
                {
                    Path = HttpContext.Current.Server.MapPath("~/Antiragging");
                }
                else if (type == "d")
                {
                    Path = HttpContext.Current.Server.MapPath("~/BirthCertificate");


                }
                else if (type == "sc")
                {
                    Path = HttpContext.Current.Server.MapPath("~/SchoolLeavingCertificate");


                }
                else if (type == "co")
                {
                    Path = HttpContext.Current.Server.MapPath("~/CovidVaccineCertificate");

                }
                else if (type == "c")
                {
                    Path = HttpContext.Current.Server.MapPath("~/ConsentForm");
                }
                else if (type == "image")
                {
                    Path = HttpContext.Current.Server.MapPath("~/UserProfilePhoto");
                }
                List<string> ExitsFile = new List<string>();
                string[] filePaths = Directory.GetFiles(Path);
                if (type != "image")
                {
                    foreach (var filename in filePaths)
                    {
                        string file = filename.ToString();
                        if (File.Exists(file))
                        {
                            ExitsFile.Add(file);
                        }
                    }
                }
                else
                {
                    //DataTable dt = Get_Certificate_dtl("", "", "", "");
                    DataTable dt = Get_Certificate_dtl(year_code, dept_code, prog_code, sem_code);
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        if (dt.Rows[i]["profile_photo"].ToString() != "")
                        {
                            string file = Path + "\\" + dt.Rows[i]["profile_photo"].ToString();
                            if (File.Exists(file))
                            {
                                ExitsFile.Add(file);
                            }
                        }

                    }
                }

                string FolderPathToZip = "";

                if (type == "m")
                {

                    FolderPathToZip = Path + "\\" + "MedicalCertificate";
                }
                else if (type == "a")
                {

                    FolderPathToZip = Path + "\\" + "Antiragging";
                }
                else if (type == "d")
                {

                    FolderPathToZip = Path + "\\" + "BirthCertificate";


                }
                else if (type == "sc")
                {

                    FolderPathToZip = Path + "\\" + "SchoolLeavingCertificate";


                }
                else if (type == "co")
                {

                    FolderPathToZip = Path + "\\" + "CovidVaccineCertificate";

                }
                else if (type == "c")
                {
                    FolderPathToZip = Path + "\\" + "ConsentForm";
                }
                else if (type == "image")
                {
                    FolderPathToZip = Path + "\\" + "UserProfilePhoto";
                }


                using (ZipFile zip = new ZipFile())
                {

                    if (type == "m")
                    {
                        FileName = "MedicalCertificate";
                        zip.AddFiles(ExitsFile.ToArray(), "/MedicalCertificate");
                    }
                    else if (type == "a")
                    {
                        FileName = "Antiragging";
                        zip.AddFiles(ExitsFile.ToArray(), "/Antiragging");
                    }
                    else if (type == "d")
                    {
                        FileName = "BirthCertificate";
                        zip.AddFiles(ExitsFile.ToArray(), "/BirthCertificate");


                    }
                    else if (type == "sc")
                    {
                        FileName = "SchoolLeavingCertificate";
                        zip.AddFiles(ExitsFile.ToArray(), "/SchoolLeavingCertificate");


                    }
                    else if (type == "co")
                    {
                        FileName = "CovidVaccineCertificate";
                        zip.AddFiles(ExitsFile.ToArray(), "/CovidVaccineCertificate");

                    }
                    else if (type == "c")
                    {
                        FileName = "ConsentForm";
                        zip.AddFiles(ExitsFile.ToArray(), "/ConsentForm");
                    }
                    else if (type == "image")
                    {
                        FileName = "UserProfilePhoto";
                        zip.AddFiles(ExitsFile.ToArray(), "/UserProfilePhoto");
                    }

                    string timestamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
                    string filename_new = FileName + "_" + timestamp ;
                    string zipFileName = FolderPathToZip + "_" + timestamp + ".zip";
                    zip.Save(zipFileName);
                    return filename_new;
                    //zip.Save(FolderPathToZip + ".zip");
                    return filename_new;

                }
            }
            catch (Exception ex)
            {
                return "2";
            }

            return "2";
        }

        public Boolean reject_certificate_dtl(string student_id, string user_id, string host_name, string column_name)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "update student_certificate_dtl set last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'";

            if (column_name == "consent_status")
            {
                SqlSelect += " ," + column_name + " = NULL,studio_type=NULL,consent_form_path=NULL";
            }
            else if (column_name == "is_submit")
            {
                SqlSelect += " ," + column_name + " = NULL,birth_certificate=NULL,school_leaving_certificate=NULL";
            }
            else
            {
                SqlSelect += " ," + column_name + " = NULL,covid_vaccine_1_certificate=NULL,covid_vaccine_2_certificate=NULL";
            }


            SqlSelect += " where cancel_flag = 'N' and user_id = '" + student_id + "'";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return false;
            }
        }
