        public string Download_User_Profile_Image(String sem_code, String year_code, String user_id, String prog_code, String prog_level_code)
        {
            try
            {
                string Path = "";
                Path = HttpContext.Current.Server.MapPath("~/UserPersonalPhoto");
                List<string> ExitsFile = new List<string>();
                string[] filePaths = Directory.GetFiles(Path);

                DataTable dt = get_vf_personal_detail(sem_code, year_code, user_id, prog_code, prog_level_code);
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    if (dt.Rows[i]["instructor_code"].ToString() != "")
                    {
                        string file_jpg = Path + "\\" + "profile_" + dt.Rows[i]["instructor_code"].ToString() + ".jpg";
                        string file_jPeg = Path + "\\" + "profile_" + dt.Rows[i]["instructor_code"].ToString() + ".jpeg";
                        string file_JPG = Path + "\\" + "profile_" + dt.Rows[i]["instructor_code"].ToString() + ".JPG";
                        string file_JPEG = Path + "\\" + "profile_" + dt.Rows[i]["instructor_code"].ToString() + ".JPEG";
                        string file_png = Path + "\\" + "profile_" + dt.Rows[i]["instructor_code"].ToString() + ".png";
                        string file_PNG = Path + "\\" + "profile_" + dt.Rows[i]["instructor_code"].ToString() + ".PNG";
                        if (File.Exists(file_jpg))
                        {
                            ExitsFile.Add(file_jpg);
                        }
                        else if (File.Exists(file_jPeg))
                        {
                            ExitsFile.Add(file_jPeg);
                        }
                        else if (File.Exists(file_JPG))
                        {
                            ExitsFile.Add(file_JPG);
                        }
                        else if (File.Exists(file_JPEG))
                        {
                            ExitsFile.Add(file_JPEG);
                        }
                        else if (File.Exists(file_png))
                        {
                            ExitsFile.Add(file_png);
                        }
                        else if (File.Exists(file_PNG))
                        {
                            ExitsFile.Add(file_PNG);
                        }
                    }

                }
                string FolderPathToZip = "";
                FolderPathToZip = Path + "\\" + "UserPersonalPhoto";

                using (ZipFile zip = new ZipFile())
                {
                    zip.AddFiles(ExitsFile.ToArray(), "/UserPersonalPhoto");
                    zip.Save(FolderPathToZip + ".zip");

                }
            }
            catch (Exception ex)
            {
                return "2";
            }

            return "1";
        }
