        #region Authorize Report Details
        public DataTable get_authorize_detail_new(string sem_code, string year_code, string user_id, string user_typee, string dept_code = "", string prog_code = "", string prog_level_code = "", string type = "", string course_type = "")
        {
            String SqlSelect = "";
            string instructor_type = "";

            string user_type = user_typee.Split('|')[0];
            instructor_type = user_typee.Split('|')[1];

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            //SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(4);set @sem='" + sem_code + "';set @year='" + year_code + "'";

            if (user_type == "D")
            {
                //(case ISNULL(instructor_mst.alternate_band,'') when '' then instructor_mst.rate_band else instructor_mst.alternate_band end)rate_band,

                SqlSelect = SqlSelect + @" select course_wise_instructor.course_code,course_wise_instructor.instructor_code,instructor_mst.VF_code,um.user_type,instructor_mst.instructor_name,instructor_mst.designation,instructor_mst.designation_letter,
                                    
                                    (case ISNULL(instructor_workload_detail.rate_band,'') when '' then instructor_workload_detail.rate_band else instructor_workload_detail.rate_band end)rate_band, 
                                    instructor_workload_detail.total_contact_hrs,instructor_workload_detail.total_hrs,
                                    (CAST(instructor_workload_detail.total_hrs_in_semester AS float) + CAST(ISNULL(instructor_workload_detail.additional_hours,0) AS float)) as total_hrs_in_semester,instructor_workload_detail.total_preparation_hrs,
                                    instructor_workload_detail.total_weeks,instructor_workload_detail.justification,
                                    instructor_workload_detail.hr_approved,instructor_workload_detail.uso_hr_approved,(instructor_mst.admin_approved)personal_dtl_approved,
                                    instructor_mst.rateband_approved,(instructor_workload_detail.admin_approved)workload_approved,
                                    instructor_mst.highest_qualification,instructor_mst.total_experiance,instructor_mst.cv_file_name,instructor_mst.portfolio_file_name,MAX(instructor_education_dtl.year_of_completion) AS year_of_completion,
                                    instructor_workload_detail.acceptance,instructor_workload_detail.acceptance_type,instructor_workload_detail.acceptance_justification,
                                    instructor_workload_detail.acceptance_date,instructor_workload_detail.is_tutorial,instructor_workload_detail.additional_hours,instructor_mst.country,
                                    instructor_mst.blood_group,instructor_mst.address,instructor_mst.permanent_address,instructor_mst.mobile_no,instructor_mst.emergency_contact_number,instructor_mst.dob,instructor_mst.total_experiance_months 
                                    ,instructor_mst.aadhaar_no,instructor_mst.passport_no,instructor_mst.pan_card_no,um.profile_photo,department_wise_course_dtl.course_typology,instructor_workload_detail.remark,instructor_workload_detail.edit_workload,um.mail,
                                    CASE When (tai.admin_approved = 'Y' or sai.admin_approved ='Y') Then 'true' else 'false' END as personal_details_status,  sai.doc_no as per_doc
                                    from course_wise_instructor
                                    inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code
                                    left join instructor_workload_detail on instructor_workload_detail.instructor_code=course_wise_instructor.instructor_code
                                            and instructor_workload_detail.course_code=course_wise_instructor.course_code
                                            and instructor_workload_detail.semester_type=course_wise_instructor.semester_type 
                                            and instructor_workload_detail.year_semester=course_wise_instructor.year_semester 
                                            and instructor_workload_detail.cancel_flag='N'

                                    left join Studio_Applicant_Instructor_Mst sai on sai.instructor_code = instructor_mst.instructor_code 
									and sai.semester_type = course_wise_instructor.semester_type and sai.year_semester = course_wise_instructor.year_semester
									and sai.cancel_flag='N'

                                    left join TA_Applicant_Instructor_Mst tai on tai.instructor_code = instructor_mst.instructor_code 
									and tai.semester_type = course_wise_instructor.semester_type and tai.year_semester = course_wise_instructor.year_semester
									and tai.cancel_flag='N'

