                " and rate_band_range.typology_sub_group ='SG003' and rate_band_range.semester_type=@sem and rate_band_range.year_semester=@year and rate_band_range.cancel_flag='N'";
                }
                else if (Convert.ToInt32(year_code) == Convert.ToInt32("2023") && type == "course")
                {
                    SqlSelect = SqlSelect + @" inner join TA_department_wise_apply as tdw on tdw.user_id = course_wise_TA.instructor_code
									and tdw.semester_type = course_wise_TA.semester_type and 
									tdw.year_semester = course_wise_TA.year_semester and tdw.cancel_flag='N' and apply_type ='24'

                                    inner join instructor_workload_detail on instructor_workload_detail.instructor_code=course_wise_TA.instructor_code
		                            and instructor_workload_detail.course_code=course_wise_TA.course_code
		                            and instructor_workload_detail.semester_type=course_wise_TA.semester_type 
		                            and instructor_workload_detail.year_semester=course_wise_TA.year_semester 
		                            and instructor_workload_detail.cancel_flag='N'";
                    SqlSelect = SqlSelect + " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(instructor_mst.highest_qualification,'') " +
                "  and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(instructor_mst.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT))  " +
                "  and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(instructor_mst.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(instructor_mst.total_experiance_months,'') as INT)) " +
                "  and ISNULL(rate_band_range.designation,'') = CASE WHEN (instructor_mst.designation IS NULL OR instructor_mst.designation = '') THEN ''  " +
                "  WHEN instructor_mst.designation IN ('instructor') THEN 'VF' WHEN instructor_mst.designation IN ('temp') THEN 'TA' WHEN instructor_mst.designation_letter = 'TEA' THEN 'TEA' ELSE instructor_mst.designation END " +
                " and rate_band_range.typology_sub_group ='SG003' and rate_band_range.semester_type=@sem and rate_band_range.year_semester=@year and rate_band_range.cancel_flag='N'";
                }
                else
                {
                    SqlSelect = SqlSelect + @" left join instructor_workload_detail on instructor_workload_detail.instructor_code=course_wise_TA.instructor_code
		                                    and instructor_workload_detail.course_code=course_wise_TA.course_code
		                                    and instructor_workload_detail.semester_type=course_wise_TA.semester_type 
		                                    and instructor_workload_detail.year_semester=course_wise_TA.year_semester 
		                                    and instructor_workload_detail.cancel_flag='N'";
                }

                SqlSelect = SqlSelect + @" where course_wise_TA.semester_type=@sem and course_wise_TA.year_semester=@year 
                                    and course_wise_TA.cancel_flag='N'
                                    and instructor_mst.cancel_flag='N'  ";
                if (sem_code == "M" && year_code == "2023" && type == "course")
                {
                    SqlSelect = SqlSelect + " and instructor_mst.designation IN ('VF','TA','AA','temp') ";
                }
                else if (Convert.ToInt32(year_code) == Convert.ToInt32("2023") && type == "course")
                {
                    SqlSelect = SqlSelect + " and instructor_mst.designation IN ('VF','TA','AA','temp') ";
                }
                else
                {
                    SqlSelect = SqlSelect + " and instructor_mst.designation IN ('VF','TA','AA','temp') ";
                }

                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = '" + dept_code + "' ";
                }
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code='" + prog_level_code + "' ";
                }

                SqlSelect = SqlSelect + @" GRoup by course_wise_TA.course_code,course_wise_TA.instructor_code,instructor_mst.VF_code,um.user_type,instructor_mst.instructor_name,instructor_mst.designation,instructor_mst.designation_letter,
                                    instructor_workload_detail.total_contact_hrs,instructor_workload_detail.total_hrs,total_hrs_in_semester,instructor_workload_detail.total_preparation_hrs,
									instructor_workload_detail.total_weeks,instructor_workload_detail.justification,
                                    instructor_workload_detail.hr_approved,instructor_workload_detail.uso_hr_approved,instructor_mst.admin_approved,
                                    instructor_mst.rateband_approved,instructor_workload_detail.admin_approved,
