            else if (user_type == "CD" || user_type == "O")
            {
                //(case ISNULL(instructor_mst.alternate_band,'') when '' then instructor_mst.rate_band else instructor_mst.alternate_band end)rate_band,
                // (case ISNULL(instructor_workload_detail.alternate_band,'') when '' then instructor_workload_detail.rate_band else instructor_workload_detail.alternate_band end)rate_band,
                SqlSelect = SqlSelect + @"select course_wise_instructor.course_code,course_wise_instructor.instructor_code,instructor_mst.VF_code,um.user_type,instructor_mst.instructor_name,instructor_mst.designation,instructor_mst.designation_letter,
                                    (case ISNULL(instructor_workload_detail.rate_band,'') when '' then instructor_workload_detail.rate_band else instructor_workload_detail.rate_band end)rate_band, 
                                    instructor_workload_detail.total_contact_hrs,instructor_workload_detail.total_hrs,
                                    (CAST(instructor_workload_detail.total_hrs_in_semester AS float) + CAST(ISNULL(instructor_workload_detail.additional_hours,0) AS float)) as total_hrs_in_semester,instructor_workload_detail.total_preparation_hrs,
                                    instructor_workload_detail.total_weeks,instructor_workload_detail.justification,
                                    instructor_workload_detail.hr_approved,instructor_workload_detail.uso_hr_approved,(instructor_mst.admin_approved)personal_dtl_approved,
                                    instructor_mst.rateband_approved,(instructor_workload_detail.admin_approved)workload_approved,
                                    instructor_mst.highest_qualification,instructor_mst.total_experiance,instructor_mst.cv_file_name,instructor_mst.portfolio_file_name,MAX(instructor_education_dtl.year_of_completion) AS year_of_completion,
                                    instructor_workload_detail.acceptance,instructor_workload_detail.acceptance_type,instructor_workload_detail.acceptance_justification,
                                    instructor_workload_detail.acceptance_date,department_mst.dept_name,instructor_workload_detail.is_tutorial,instructor_workload_detail.additional_hours,instructor_mst.country,
                                    instructor_mst.blood_group,instructor_mst.address,instructor_mst.permanent_address,instructor_mst.mobile_no,instructor_mst.emergency_contact_number,FORMAT(instructor_mst.dob,'dd-MM-yyyy')dob, 
                                    instructor_mst.total_experiance_months,instructor_mst.aadhaar_no,instructor_mst.passport_no,instructor_mst.pan_card_no,um.profile_photo,department_wise_course_dtl.course_typology,instructor_workload_detail.remark,instructor_workload_detail.edit_workload,um.mail,
                                    CASE When (tai.admin_approved = 'Y' or sai.admin_approved ='Y') Then 'true' else 'false' END as personal_details_status,sai.doc_no as per_doc
                                    from course_wise_instructor
                                    inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code
                                    left join instructor_workload_detail on instructor_workload_detail.instructor_code=course_wise_instructor.instructor_code
		                                    and instructor_workload_detail.course_code=course_wise_instructor.course_code
		                                    and instructor_workload_detail.semester_type=course_wise_instructor.semester_type 
		                                    and instructor_workload_detail.year_semester=course_wise_instructor.year_semester 
		                                    and instructor_workload_detail.cancel_flag='N'

                                    left join Studio_Applicant_Instructor_Mst sai on sai.instructor_code = instructor_mst.instructor_code 
									and sai.semester_type = course_wise_instructor.semester_type and sai.year_semester = course_wise_instructor.year_semester
									and sai.cancel_flag='N'


                                    left join TA_Applicant_Instructor_Mst tai on tai.instructor_code = instructor_mst.instructor_code 
									and tai.semester_type = course_wise_instructor.semester_type and tai.year_semester = course_wise_instructor.year_semester
									and tai.cancel_flag='N'

                                    left join department_wise_course_dtl on department_wise_course_dtl.course_code=course_wise_instructor.course_code
                                            and department_wise_course_dtl.semester_type=course_wise_instructor.semester_type
                                            and department_wise_course_dtl.year_semester=course_wise_instructor.year_semester
                                            ";

                if (course_type == "N")
                {
                    SqlSelect = SqlSelect + @" and department_wise_course_dtl.cancel_flag='Y' ";
                }
                else
                {
                    SqlSelect = SqlSelect + @" and department_wise_course_dtl.cancel_flag='N' ";
                }

                SqlSelect = SqlSelect + @" left join department_mst on department_mst.dept_code=department_wise_course_dtl.dept_code
		                                    and department_mst.cancel_flag='N'
                                    left join instructor_education_dtl on instructor_education_dtl.instructor_code = instructor_mst.instructor_code 
                                            and instructor_education_dtl.cancel_flag='N'
                                    left join user_mst um on um.user_id = instructor_mst.instructor_code
                                    where course_wise_instructor.semester_type=@sem and course_wise_instructor.year_semester=@year 
                                    
                                    and instructor_mst.cancel_flag='N' and instructor_mst.designation IN ('VF','TA','AA') and instructor_workload_detail.uso_hr_approved ='Y' ";

                if (course_type == "N")
                {
                    SqlSelect = SqlSelect + " and course_wise_instructor.cancel_flag='Y' ";
                }
                else { SqlSelect = SqlSelect + " and course_wise_instructor.cancel_flag='N' "; }

                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.dept_code = '" + dept_code + "' ";
                }
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_code='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and department_wise_course_dtl.prog_level_code='" + prog_level_code + "' ";
                }

                SqlSelect = SqlSelect + @" GRoup by course_wise_instructor.course_code,course_wise_instructor.instructor_code,instructor_mst.VF_code,um.user_type,instructor_mst.instructor_name,instructor_mst.designation,instructor_mst.designation_letter,
                                    instructor_workload_detail.total_contact_hrs,instructor_workload_detail.total_hrs,total_hrs_in_semester,instructor_workload_detail.total_preparation_hrs,
									instructor_workload_detail.total_weeks,instructor_workload_detail.justification,
                                    instructor_workload_detail.hr_approved,instructor_workload_detail.uso_hr_approved,instructor_mst.admin_approved,
                                    instructor_mst.rateband_approved,instructor_workload_detail.admin_approved,
                                    instructor_mst.highest_qualification,instructor_mst.total_experiance,instructor_mst.cv_file_name,instructor_mst.portfolio_file_name,
                                    instructor_workload_detail.acceptance,instructor_workload_detail.acceptance_type,instructor_workload_detail.acceptance_justification,
                                    instructor_workload_detail.acceptance_date,department_mst.dept_name,instructor_workload_detail.is_tutorial,instructor_workload_detail.additional_hours,instructor_workload_detail.rate_band,
                                    instructor_workload_detail.alternate_band,instructor_mst.country,
                                    instructor_mst.blood_group,instructor_mst.address,instructor_mst.permanent_address,instructor_mst.mobile_no,instructor_mst.emergency_contact_number,instructor_mst.dob,instructor_mst.total_experiance_months
                                    ,instructor_mst.aadhaar_no,instructor_mst.passport_no,instructor_mst.pan_card_no,um.profile_photo ,department_wise_course_dtl.course_typology,instructor_workload_detail.remark,instructor_workload_detail.edit_workload,um.mail,sai.doc_no,tai.admin_approved,sai.admin_approved  ";


                string temp_str = SqlSelect;

                SqlSelect = "DECLARE @sem varchar(1);DECLARE @year varchar(4);set @sem='" + sem_code + "';set @year='" + year_code + "'";

                //if (instructor_type != "-") 
                SqlSelect = SqlSelect + "select * from ( ";

                SqlSelect = SqlSelect + temp_str;

                SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_AA");

                SqlSelect = SqlSelect + " union " + temp_str.Replace("course_wise_instructor", "course_wise_TA");

                SqlSelect = SqlSelect + " ) as res where 1=1 ";

                if (instructor_type == "TEA")
                    SqlSelect = SqlSelect + " and res.designation_letter = '" + instructor_type + "'";
