        #region Vertical Studio Calculate Seats Details Report

        public DataTable Get_Calculate_Vertical_Studio_Seats(string sem_code, string year_code)
        {

            String SqlSelect = "";

            SqlSelect = " select total_register_seats.course_code,total_register_seats.course_name,total_register_seats.available_seat,total_register_seats.total_allocated_seats, " +
                " reg.total_register_seats,total_register_seats.priority_1_allocate_seats,total_register_seats.priority_2_allocate_seats,total_register_seats.priority_3_allocate_seats," +
                " total_register_seats.priority_4_allocate_seats , (total_register_seats.available_seat - total_register_seats.total_allocated_seats) as remaining_seats, " +
                " ROUND(CAST((total_register_seats.priority_1_allocate_seats * 100.0 / total_register_seats.available_seat) AS FLOAT), 2) AS Percentage_priority1, " +
                " ROUND(CAST((total_register_seats.priority_2_allocate_seats * 100.0 / total_register_seats.available_seat) AS FLOAT), 2) AS Percentage_priority2, " +
                " ROUND(CAST((total_register_seats.priority_3_allocate_seats * 100.0 / total_register_seats.available_seat) AS FLOAT), 2) AS Percentage_priority3, " +
                " ROUND(CAST((total_register_seats.priority_4_allocate_seats * 100.0 / total_register_seats.available_seat) AS FLOAT), 2) AS Percentage_priority4 " +
                " from ( " +
                " select check_allocated_seats.course_code,check_allocated_seats.course_name,check_allocated_seats.available_seat,avaliables_seats_dtl.total_allocated_seats, " +
                " check_allocated_seats.priority_1_allocate_seats,check_allocated_seats.priority_2_allocate_seats,check_allocated_seats.priority_3_allocate_seats,check_allocated_seats.priority_4_allocate_seats " +
                " from ( " +
                " select ISNULL(course_name.course_code,course_name.course_code) as course_code,course_mst.course_name,dwc.available_seat, course_name.priority_1_allocate_seats,course_name.priority_2_allocate_seats, " +
                " course_name.priority_3_allocate_seats, course_name.priority_4_allocate_seats " +
                " from ( " +
                " select ISNULL(final_t5.course_code,final_t6.course_code) as course_code, final_t5.priority_1_sets as priority_1_allocate_seats , " +
                " final_t5.priority_2_sets as priority_2_allocate_seats,final_t6.priority_3_sets as priority_3_allocate_seats,final_t6.priority_4_sets as priority_4_allocate_seats " +
                " from ( " +
                " select ISNULL(t1.course_code,t2.course_code) as course_code,t1.priority_1_sets,t2.priority_2_sets  " +
                " from ( " +
                " select course_code,  COUNT(course_code) as priority_1_sets  From vertical_studio_selection_dtl " +
                " where priority ='1' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status='A' and  cancel_flag='N' group by course_code) as t1  " +
                " full join " +
                " (select course_code,  COUNT(course_code) as priority_2_sets  From vertical_studio_selection_dtl " +
                " where priority ='2' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status='A' and  cancel_flag='N' group by course_code) as t2 " +
                " on t1.course_code=t2.course_code) as final_t5 " +
                " full join (select ISNULL(t3.course_code,t4.course_code) as course_code,t3.priority_3_sets,t4.priority_4_sets from " +
                " (select course_code,  COUNT(course_code) as priority_3_sets  From vertical_studio_selection_dtl " +
                " where priority ='3' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status='A' and  cancel_flag='N' group by course_code) as t3 " +
                " full join " +
                " (select course_code,  COUNT(course_code) as priority_4_sets  From vertical_studio_selection_dtl " +
                " where priority ='4' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status='A' and  cancel_flag='N' " +
                " group by course_code) as t4 on t3.course_code=t4.course_code ) as final_t6 on final_t5.course_code = final_t6.course_code) as course_name " +
                " left join department_wise_course_dtl as dwc on dwc.course_code = course_name.course_code " +
                " left join course_mst on course_mst.course_code = course_name.course_code and course_mst.semester_type = dwc.semester_type " +
                " and course_mst.year_semester = dwc.year_semester where dwc.semester_type ='" + sem_code + "' and dwc.year_semester='" + year_code + "' and dwc.cancel_flag='N') as check_allocated_seats " +
                " full join  " +
                " (select course_code,  COUNT(course_code) as total_allocated_seats  From vertical_studio_selection_dtl " +
                " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status='A' and  cancel_flag='N' " +
                " group by course_code) as avaliables_seats_dtl on check_allocated_seats.course_code = avaliables_seats_dtl.course_code ) as total_register_seats " +
                " inner Join ( select course_code,  COUNT(course_code) as total_register_seats  From vertical_studio_selection_dtl " +
                " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and  cancel_flag='N'  " +
                " group by course_code ) as reg on reg.course_code = total_register_seats.course_code ";


            return Get_data(SqlSelect);
        }

        #endregion

