        #region ws course inst personal details

        public DataTable Get_ws_course_wise_instructor_personal_dtl(string sem_code, string year_code, string course_code)
        {
            String SqlSelect = "";
            SqlSelect = " select wcwi.course_code, im.instructor_code,im.VF_code,im.title,im.first_name,im.last_name,im.gender,im.mail,im.mobile_no,im.blood_group, " +
                " im.emergency_contact_number,im.pan_card_no,im.indian_citizen,im.passport_no,im.aadhaar_no,im.gst_number,im.bank_account_number, " +
                " im.account_type,im.name_of_Bank,im.branch_name,im.ifsc_code,im.benificiary_name,im.dob,im.highest_qualification,im.total_experiance,im.total_teaching_experiance, " +
                " im.associated_with_cept_since,im.emergency_contact_name,im.coa_registration_no,im.city,im.state,im.country,im.address,im.portfolio_file_name,im.cv_file_name " +
                " from ws_course_wise_instructor as wcwi " +
                " inner join instructor_mst as im on im.instructor_code = wcwi.instructor_code " +
                " where wcwi.semester_type ='" + sem_code + "'  and wcwi.year_semester ='" + year_code + "' and wcwi.cancel_flag ='N'  ";
            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and wcwi.course_code = '" + course_code + "'";
            }
            SqlSelect = SqlSelect + " order by wcwi.created_date desc ";
            return Get_data(SqlSelect);
        }


        public DataTable Get_ws_course_praposal_wise_instructor_personal_dtl(string sem_code, string year_code, string course_code)
        {
            String SqlSelect = "";
            SqlSelect = " select wcwi.course_code, im.instructor_code,im.VF_code,im.title,im.first_name,im.last_name,im.gender,im.mail,im.mobile_no,im.blood_group, " +
                " im.emergency_contact_number,im.pan_card_no,im.indian_citizen,im.passport_no,im.aadhaar_no,im.gst_number,im.bank_account_number, " +
                " im.account_type,im.name_of_Bank,im.branch_name,im.ifsc_code,im.benificiary_name,im.dob,im.highest_qualification,im.total_experiance,im.total_teaching_experiance, " +
                " im.associated_with_cept_since,im.emergency_contact_name,im.coa_registration_no,im.city,im.state,im.country,im.address,im.portfolio_file_name,im.cv_file_name " +
                " from ws_course_proposal_instructor as wcwi " +
                " inner join instructor_mst as im on im.instructor_code = wcwi.instructor_code" +
                " inner join ws_course_proposal wcp on wcp.course_code = wcwi.course_code and wcp.semester_type= wcwi.semester_type and wcp.year_semester = wcwi.year_semester and wcp.cancel_flag='N'" +
                " where wcwi.semester_type ='" + sem_code + "'  and wcwi.year_semester ='" + year_code + "' and wcwi.cancel_flag ='N'  ";
            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and wcwi.course_code = '" + course_code + "'";
            }
