                " iwd.admin_approved as iwd_admin_approved,iwd.hr_approved as iwd_hr_approved , iwd.uso_hr_approved as iwd_uso_hr_approved,im.admin_approved as im_admin_approved, " +
                " im.rateband_approved as im_rateband_approved,  im.hr_approved as im_hr_approved,cm.weekly_excercises_path,iwssp.remark,im.total_experiance_months" +
                " ,im.designation as inst_designation  " +
                " from instructor_studio_details as isd " +
                " inner join instructor_teaching_interest as iti on iti.semester_type = isd.semester_type " +
                " and iti.year_semester = isd.year_semester and iti.cancel_flag = isd.cancel_flag " +
                " and isd.studio_code = iti.studio_code " +
                " inner join department_mst on department_mst.dept_code = iti.dept_code " +
                " inner join instructor_mst as im on im.instructor_code = isd.user_id  " +
                " inner join user_mst as um on um.user_id = isd.user_id  " +
                " inner join programme_mst as pm on pm.prog_code = iti.prog_code " +
                " left join course_mst cm on cm.course_code = isd.course_code and cm.semester_type = isd.semester_type and cm.year_semester = isd.year_semester " +
                " left join programme_level_mst as plm on plm.prog_level_code = iti.prog_level_code " +
                " left join instructor_wise_shortlist_studio_proposal_dtl as iwssp on iwssp.studio_code = isd.studio_code " +
                " and iwssp.semester_type = isd.semester_type  and iwssp.year_semester = isd.year_semester and iwssp.cancel_flag ='N' ";
            if (user_type == "PC")
            {
                SqlSelect = SqlSelect + " inner join programme_coordinator_dtl pc on pc.dept_code = iti.dept_code and pc.prog_code = iti.prog_code " +
                    " and pc.semester_type = iti.semester_type and pc.year_semester = iti.year_semester and pc.cancel_flag ='N' and pc.user_id ='" + user_id + "'" +
                    " and ISNULL(iti.prog_level_code,'')=ISNULL(pc.prog_level_code,'')  ";
            }
            if (user_type == "D")
            {
                SqlSelect = SqlSelect + " inner join dean_dtl dean on dean.dept_code = iti.dept_code and dean.prog_code = iti.prog_code " +
                    " and dean.semester_type = iti.semester_type and dean.year_semester = iti.year_semester and dean.cancel_flag ='N' and dean.user_id ='" + user_id + "' ";
            }

            SqlSelect = SqlSelect + " left join instructor_workload_detail iwd on iwd.instructor_code = isd.user_id  and iwd.course_code = isd.course_code " +
                " and iwd.semester_type = isd.semester_type  and iwd.year_semester = isd.year_semester and iwd.cancel_flag='N' ";
            //changes by nitinbhai 22102021
            SqlSelect = SqlSelect + " where isd.is_submit ='Y' and (isd.approved ='N' or isd.approved ='Y') " +
                " and isd.semester_type ='" + sem_code + "' and isd.year_semester='" + year_code + "' and isd.cancel_flag='N'";
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and iti.prog_code = '" + prog_code + "'";
            }
            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and iti.dept_code = '" + dept_code + "'";
            }

            SqlSelect = SqlSelect + "  and isd.studio_code in ( select distinct studio_code from studio_wise_instructor_dtl " +
                " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' and to_be_later IN('Y','W')) ";

            SqlSelect = SqlSelect + " ) as t1 ";

            //SqlSelect = SqlSelect + " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(t1.highest_qualification,'') " +
            //    "  and CAST(rate_band_range.from_experiance as INT) <= CAST(ISNULL(t1.total_experiance,0) as INT)  " +
            //    "  and CAST(rate_band_range.to_experiance as INT) >= CAST(ISNULL(t1.total_experiance,0) as INT) " +
            //    "  and ISNULL(rate_band_range.designation,'') = case ISNULL(t1.designation,'')  " +
            //    "  when 'instructor' then 'VF' when 'temp' then 'VF'  else ISNULL(t1.designation,'') end  " +
            //    " and rate_band_range.typology_sub_group ='SG003' ";

            SqlSelect = SqlSelect + " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(t1.highest_qualification,'') " +
                "  and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT))  " +
                "  and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT)) " +
                "  and ISNULL(rate_band_range.designation,'') = case ISNULL(t1.inst_designation,'')  " +
                "  when 'instructor' then 'VF' when 'temp' then 'VF'  else ISNULL(t1.inst_designation,'') end  " +
                " and rate_band_range.typology_sub_group ='SG003' ";

            if (dt != null)
            {
                SqlSelect = SqlSelect + " and rate_band_range.semester_type='" + sem_code + "' and rate_band_range.year_semester ='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rate_band_range.semester_type IS NULL and rate_band_range.year_semester IS NULL "; }
            SqlSelect += " order by t1.studio_code desc";
            return Get_data(SqlSelect);
        }


