                " ,im.designation as inst_designation " +
                " from instructor_studio_details as isd " +
                 // " INNER JOIN studio_wise_instructor_dtl SWID WITH(NOLOCK) ON SWID.studio_code = isd.studio_code AND SWID.instructor_code = '" + user_id + "' " +
                 (user_type != "A1" && user_type != "A" && user_type != "PC" && user_type != "D" ? " INNER JOIN studio_wise_instructor_dtl SWID WITH(NOLOCK) ON SWID.studio_code = isd.studio_code AND SWID.instructor_code = '" + user_id + "' " : "") +
