            SqlSelect = "IF EXISTS(select * from instructor_wise_shortlist_studio_proposal_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and studio_code='" + details_value[1].ToString() + "' and user_id ='" + bindUserId + "') "
                       + " BEGIN "
                       + " update instructor_wise_shortlist_studio_proposal_dtl set remark ='" + remark + "', status='" + status + "',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', "
                       + " last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' where studio_code = '" + details_value[1].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and user_id = '" + bindUserId + "' " + " END "
                   + " ELSE "
                       + " BEGIN "
                       + " INSERT INTO instructor_wise_shortlist_studio_proposal_dtl (user_id,studio_code,status,semester_type,year_semester,cancel_flag, created_by, created_date, created_host,remark)  "
                       + " VALUES('" + bindUserId + "','" + details_value[1].ToString() + "','" + status + "', '" + sem_code + "', '" + year_code + "','N', '" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "','" + remark + "') "
                       + " END ";
            ServerLog.ExceptionLog("PC Reject Studio Query 1: " + SqlSelect);
            if (status == "A")
            {//changes 25012023
                if (dt_inst != null)
                {
                    for (int i = 0; i < dt_inst.Rows.Count; i++)
                    {
