                                {
                                    SqlSelect = SqlSelect + " Update instructor_studio_details set approved ='Y' , last_modified_by = '" + user_id + "' , last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' " +
                                        " where studio_code = '" + dtRatebandStatus.Rows[k]["studio_code"].ToString() + "' and user_id = '" + dtRatebandStatus.Rows[k]["instructor_code"].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag ='N' ";

                                    SqlSelect = SqlSelect + " Update studio_wise_instructor_dtl set approved ='Y',hr_status ='A',pc_status ='A' , last_modified_by = '" + user_id + "' , last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'  ";
                                    SqlSelect = SqlSelect + " where studio_code = '" + dtRatebandStatus.Rows[k]["studio_code"].ToString() + "' and instructor_code = '" + dtRatebandStatus.Rows[k]["instructor_code"].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag ='N' ";
                                }
                            }
                            else
                            {

                                if (dt.Rows[0]["designation"].ToString() == "instructor")
                                {
                                    SqlSelect = SqlSelect + " Update instructor_studio_details set approved ='Y' , last_modified_by = '" + user_id + "' , last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where studio_code = '" + details_value[1].ToString() + "' and user_id = '" + dt.Rows[0]["instructor_code"].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' ";
                                    SqlSelect = SqlSelect + " Update studio_wise_instructor_dtl set approved ='Y',hr_status ='A' , last_modified_by = '" + user_id + "' , last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'  ";

                                    if (remark != "" && remark != "undefine")
                                    {
                                        SqlSelect = SqlSelect + ", pc_remark='" + remark + "'";
                                    }
                                    if (status != "" && status != "undefine")
                                    {
                                        SqlSelect = SqlSelect + ", pc_status='" + status + "'";
                                    }
                                    SqlSelect = SqlSelect + " where studio_code = '" + details_value[1].ToString() + "' and instructor_code = '" + dt.Rows[0]["instructor_code"].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' ";

                                    //To Be decided User Update Before Shortlist User 

                                    SqlSelect = SqlSelect + " Update studio_wise_instructor_dtl set shortlist = 'Y'  where to_be_later='Y' and cancel_flag='N' and instructor_code Not Like 'TBD_%' " +
                                        " and (shortlist = '' or shortlist is Null) and studio_code='" + details_value[1].ToString() + "' and instructor_code ='" + dt.Rows[0]["instructor_code"].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' ";


                                }
                                else
                                {
                                    SqlSelect = SqlSelect + " Update studio_wise_instructor_dtl set last_modified_by = '" + user_id + "' , last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'  ";

                                    if (remark != "" && remark != "undefine")
                                    {
                                        SqlSelect = SqlSelect + ", pc_remark='" + remark + "'";
                                    }
                                    if (status != "" && status != "undefine")
                                    {
                                        SqlSelect = SqlSelect + ", pc_status='" + status + "'";
                                    }
                                    SqlSelect = SqlSelect + " where studio_code = '" + details_value[1].ToString() + "' and instructor_code = '" + dt.Rows[0]["instructor_code"].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' ";

                                    //To Be decided User Update Before Shortlist User 
                                    SqlSelect = SqlSelect + " Update studio_wise_instructor_dtl set shortlist = 'Y'  where to_be_later='Y' and cancel_flag='N' and instructor_code Not Like 'TBD_%' " +
                                    " and (shortlist = '' or shortlist is Null) and studio_code='" + details_value[1].ToString() + "' and instructor_code ='" + dt.Rows[0]["instructor_code"].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' ";

                                }
                            }
                        }

                    }
                }

            }
            if (status == "R")
            {
                //Reject //09032022
                ServerLog.ExceptionLog("PC Reject Studio : " + status);
                ServerLog.ExceptionLog("PC Reject Studio Date : " + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss"));
                ServerLog.ExceptionLog("PC Reject Studio USerHostName : " + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost"));
                SqlSelect = "IF EXISTS(select * from instructor_studio_details where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and studio_code='" + details_value[1].ToString() + "' and user_id ='" + bindUserId + "') "
                       + " BEGIN "
                       + " update instructor_studio_details set cancel_flag ='Y',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', "
                       + " last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' where studio_code = '" + details_value[1].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and user_id = '" + bindUserId + "' "
                       + " Update studio_wise_instructor_dtl set cancel_flag = 'Y', pc_status = 'R', pc_remark = '" + remark + "', last_modified_by = '" + user_id + "', last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "', last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where studio_code = '" + details_value[1].ToString() + "'  and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag = 'N'"
                       + " END "
                       + " ELSE "
                       + " BEGIN "
                       + " Update studio_wise_instructor_dtl set cancel_flag ='Y', pc_status ='R',pc_remark='" + remark + "'  , last_modified_by = '" + user_id + "' , last_modified_host = '" + (HttpContext.Current?.Request?.UserHostName ?? "UnknownHost") + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where studio_code = '" + details_value[1].ToString() + "' and instructor_code = '" + bindUserId + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag='N'   "
                       + " END ";


            }

            ServerLog.ExceptionLog("PC Reject Studio Query : " + SqlSelect);
            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {

                DBCommand.ExecuteNonQuery();
                ServerLog.ExceptionLog("PC Reject After ExecuteNonQuery : " + SqlSelect);
                DBConnection.Close();
                if (status == "R")
                {
                    DataTable dt = getStudioProposalsDetails_studio_wise(details_value[1].ToString());
                    if (dt != null)
                    {
                        DataTable pc_dtl = pc_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                        DataTable dean_dtl = dean_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                        DataTable faculty_admin = fa_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                        DataTable mail_from_id_password = check_frommail_id_password("StudioProposalReject");
                        DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body("StudioProposalReject", "email");
                        DataTable user_dtl = check_user_by_user_id(bindUserId);
                        Mail mail = new Mail();
                        bool mail_status = mail.StudioproposalAuthorized(bindUserId, pc_dtl, dean_dtl, faculty_admin, mail_from_id_password, AckDetails, user_dtl, remark);
                        if (mail_status)
                        {
                            return "true";

                        }
                        else { return "true"; }
                    }
                }
                else if (status == "A")
                {
                    DataTable dt = SendMailForUser(details_value[1].ToString(), sem_code, year_code);
                    DataTable dt_CT_User = SendMailForUserOnlyCTUser(details_value[1].ToString(), sem_code, year_code);
                    if (dt != null)
                    {
                        bool statusdata = Send_Mail_for_Instr(details_value[1].ToString(), bindUserId, "StudioProposalAuthorized", "");
                    }
                    //Developby nitinbhai 08042025
                    if (dt_CT_User != null)
                    {
                        for (int i = 0; i < dt_CT_User.Rows.Count; i++)
                        {
                            bool SendMailForCTUser = Send_Mail_for_Instr_CT(details_value[1].ToString(), dt_CT_User.Rows[i]["instructor_code"].ToString(), "StudioProposalAuthorized_CT", "");
                        }

                    }

                }

                return "true";
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return "false";
            }
        }



        public DataTable shortlist_instructor_authorize(string sem_code, string year_code, string prog_code, string dept_code, string tutor_type)
        {
            DataTable dt = Get_Semester_Wise_RateBand(sem_code, year_code);
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = " Select Distinct * from ( ";

            SqlSelect += @" select t1.user_id,t1.approved,t1.semester_type,t1.year_semester,t1.studio_brief, t1.is_submit,t1.studio_code,
                            t1.studio_brief_status,t1.course_code,  t1.dept_code,t1.prog_code,t1.prog_level_code,t1.studio_level, 
                            t1.studio_title,t1.no_of_tutor,t1.teaching_mode,t1.studio_description,t1.previous_sem_course_code, 
                            t1.previous_sem_code,t1.previous_year_code,t1.dept_name ,t1.shortlist_status ,
                            t1.total_experiance,t1.full_name,t1.prog_name,  t1.highest_qualification,t1.inst_designation,t1.mail,
                            t1.cv_file_name, t1.portfolio_file_name,t1.ppt_video,  t1.admin_approved,t1.rateband_approved,
                            t1.hr_approved,t1.instructor_workload_admin_approved, 
	                        t1.instructor_workload_hr_approved,t1.instructor_workload_uso_hr_approved,
	                        t1.cpop_user_status,t1.country_name,t1.hr_status,t1.hr_remark,t1.hr_status_new,t1.hr_remark_new,t1.hr_cancel_flag, t1.dob,t1.VF_code,t1.blood_group,t1.mobile_no,
                            t1.emergency_contact_number,t1.permanent_address,t1.address,t1.total_experiance_months,TA_user = NULL, ";


            SqlSelect += " rate_band_range.rate_band,t1.edit_workload,t1.inst_designation_letter  from (select isd.user_id,isd.approved,isd.semester_type,isd.year_semester,isd.studio_brief," +
                " isd.is_submit,isd.studio_code,isd.studio_brief_status,isd.course_code, " +
                " iti.dept_code,iti.prog_code,iti.prog_level_code,iti.studio_level, " +
                " iti.studio_title,iti.no_of_tutor,iti.teaching_mode,iti.studio_description,iti.previous_sem_course_code, " +
                " iti.previous_sem_code,iti.previous_year_code,department_mst.dept_name ,iwssp.status as shortlist_status ,im.total_experiance,um.full_name,pm.prog_name," +
                " im.highest_qualification,im.designation as inst_designation,im.designation_letter as inst_designation_letter," +

                " im.mail, im.cv_file_name, im.portfolio_file_name,isd.ppt_video, " +
                " im.admin_approved,im.rateband_approved,im.hr_approved,iwd.admin_approved instructor_workload_admin_approved," +
                " iwd.hr_approved instructor_workload_hr_approved,iwd.uso_hr_approved instructor_workload_uso_hr_approved ,ISNULL(cpop.cancel_flag,'Y') as cpop_user_status,cm.name as country_name,iwssp.hr_status,iwssp.hr_remark, tutor_type_inst ='',sww.hr_status as hr_status_new ,sww.hr_remark as hr_remark_new ," +
                " sww.cancel_flag as hr_cancel_flag,im.dob,im.VF_code,im.blood_group,im.mobile_no,im.emergency_contact_number,im.permanent_address,im.address,im.total_experiance_months,iwd.edit_workload  " +
                " from instructor_studio_details as isd " +
                " inner join instructor_teaching_interest as iti on iti.semester_type = isd.semester_type " +
                " and iti.year_semester = isd.year_semester and iti.cancel_flag = isd.cancel_flag " +
                " and isd.studio_code = iti.studio_code " +
                " inner join department_mst on department_mst.dept_code = iti.dept_code " +
                " inner join instructor_mst as im on im.instructor_code = isd.user_id " +
                " left join user_mst as um on um.user_id = isd.user_id " +
                " inner join programme_mst as pm on pm.prog_code = iti.prog_code " +
                " left join studio_wise_instructor_dtl as sww on sww.studio_code = isd.studio_code " +
                " and sww.instructor_code = isd.user_id and sww.cancel_flag='N' " +
                " inner join instructor_wise_shortlist_studio_proposal_dtl as iwssp on iwssp.studio_code = isd.studio_code " +
                " and iwssp.semester_type = isd.semester_type  and iwssp.year_semester = isd.year_semester and iwssp.cancel_flag ='N' " +
                " left join instructor_workload_detail iwd on iwd.course_code = isd.new_course_code " +
                " and iwd.instructor_code = isd.user_id and iwd.semester_type = isd.semester_type and iwd.year_semester = isd.year_semester " +
                " and iwd.cancel_flag ='N' " +
                " left join cpop_superviser_mst cpop on cpop.superviser_code = isd.user_id and cpop.cancel_flag = 'N' " +
                " left join country_mst cm on cm.id = im.indian_citizen " +
                " where isd.is_submit ='Y' and isd.approved ='N' and isd.studio_brief_status='N' and  iwssp.status ='A' " +
                " and isd.semester_type ='" + sem_code + "' and isd.year_semester='" + year_code + "'";
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and iti.prog_code = '" + prog_code + "'";
            }
            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and iti.dept_code = '" + dept_code + "'";
            }
            if (tutor_type != "" && tutor_type == "TEA")
            {
                SqlSelect = SqlSelect + " and im.designation_letter = '" + tutor_type + "'";
            }

            if (tutor_type != "" && tutor_type != "TEA")
            {
                if (tutor_type == "core")
                {
                    SqlSelect = SqlSelect + " and  cpop.cancel_flag = 'N'";
                }
                else { SqlSelect = SqlSelect + " and im.designation = '" + tutor_type + "'"; }

            }

            SqlSelect = SqlSelect + " ) as t1";
            SqlSelect = SqlSelect + " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(t1.highest_qualification,'') " +
                "  and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT))  " +
                "  and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT)) " +
                "  and ISNULL(rate_band_range.designation,'') = CASE WHEN (t1.inst_designation IS NULL OR t1.inst_designation = '') THEN '' " +
                "  WHEN t1.inst_designation IN ('instructor','temp') THEN 'VF' " +
                "  WHEN t1.inst_designation_letter = 'TEA' THEN 'TEA'" +
                "  ELSE t1.inst_designation END " +
                " and rate_band_range.typology_sub_group ='SG003' ";


            //"  and ISNULL(rate_band_range.designation,'') = case ISNULL(t1.inst_designation,'')  " +
            //"  when 'instructor' then 'VF' when 'temp' then 'VF'  else ISNULL(t1.inst_designation,'') end  " +
            //" and rate_band_range.typology_sub_group ='SG003' ";

            if (dt != null)
            {
                SqlSelect = SqlSelect + " and rate_band_range.semester_type='" + sem_code + "' and rate_band_range.year_semester ='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rate_band_range.semester_type IS NULL and rate_band_range.year_semester IS NULL "; }


            SqlSelect = SqlSelect + @" AND rate_band_range.DegreeID =
                                CASE
                            WHEN t1.highest_qualification = 'UG' THEN 'UG003'
                            WHEN t1.highest_qualification = 'PG' THEN 'PG001'
                            WHEN t1.highest_qualification = 'PHD' THEN 'PHD001'
                            ELSE 'UG000' END";




            SqlSelect += " UNION ";

            SqlSelect += @" Select t1.user_id,t1.approved,t1.semester_type,t1.year_semester,t1.studio_brief, t1.is_submit,t1.studio_code,
                            t1.studio_brief_status,t1.course_code,  t1.dept_code,t1.prog_code,t1.prog_level_code,t1.studio_level, 
                            t1.studio_title,t1.no_of_tutor,t1.teaching_mode,t1.studio_description,t1.previous_sem_course_code, 
                            t1.previous_sem_code,t1.previous_year_code,t1.dept_name ,t1.shortlist_status ,
                            t1.total_experiance,t1.full_name,t1.prog_name,  t1.highest_qualification,t1.inst_designation,t1.mail,
                            t1.cv_file_name, t1.portfolio_file_name,t1.ppt_video,  t1.admin_approved,t1.rateband_approved,
                            t1.hr_approved,t1.instructor_workload_admin_approved, 
	                        t1.instructor_workload_hr_approved,t1.instructor_workload_uso_hr_approved,
	                        t1.cpop_user_status,t1.country_name,t1.hr_status,t1.hr_remark,t1.hr_status_new,t1.hr_remark_new,t1.hr_cancel_flag,
                            t1.dob,t1.VF_code,t1.blood_group,t1.mobile_no,t1.emergency_contact_number,t1.permanent_address,t1.address,t1.total_experiance_months,TA_user = NULL,";

            SqlSelect += " rate_band_range.rate_band,t1.edit_workload,t1.inst_designation_letter   from (select swid.instructor_code as user_id,swid.approved,isd.semester_type,isd.year_semester,isd.studio_brief," +
