        public dynamic to_be_later_inst_shortlist(string sem_code, string year_code, string user_id, string detalis, string remark, string status)
        {
            string[] details_value = detalis.Split('_');
            /*************************/
            /* ESTABLISH CONNECTION */

            /*************************/


            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            //DataTable dt_inst = getStudiowiseinst(details_value[1].ToString());
            String SqlSelect = "";

            DataTable dt = get_instructor_dtl(details_value[0].ToString());
            if (dt != null)
            {
                if (dt.Rows[0]["designation"].ToString() == "instructor")
                {
                    SqlSelect = " Update studio_wise_instructor_dtl set shortlist ='Y',approved ='Y' , last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where studio_code = '" + details_value[1].ToString() + "' and instructor_code = '" + details_value[0].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag ='N' ";

                }
                else
                {
                    SqlSelect = " Update studio_wise_instructor_dtl set shortlist ='Y' , last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where studio_code = '" + details_value[1].ToString() + "' and instructor_code = '" + details_value[0].ToString() + "' and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "' and cancel_flag ='N' ";
                }
            }



            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return "true";
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return "false";
            }
        }


