            }

            SqlSelect = SqlSelect + " ) as t1";
            SqlSelect = SqlSelect + " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(t1.highest_qualification,'') " +
                "  and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT))  " +
                "  and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT)) " +
                "  and ISNULL(rate_band_range.designation,'') = case ISNULL(t1.inst_designation,'')  " +
                "  when 'instructor' then 'VF' when 'temp' then 'VF'  else ISNULL(t1.inst_designation,'') end  " +
                " and rate_band_range.typology_sub_group ='SG003' ";

            if (dt != null)
            {
                SqlSelect = SqlSelect + " and rate_band_range.semester_type='" + sem_code + "' and rate_band_range.year_semester ='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rate_band_range.semester_type IS NULL and rate_band_range.year_semester IS NULL "; }
            SqlSelect += " Union ";

            SqlSelect += @" Select t1.user_id,t1.approved,t1.semester_type,t1.year_semester,t1.studio_brief, t1.is_submit,t1.studio_code,
                          studio_brief_status =NULL,t1.course_code,  t1.dept_code,t1.prog_code,t1.prog_level_code,t1.studio_level, 
                          t1.studio_title,t1.no_of_tutor,t1.teaching_mode,t1.studio_description,t1.previous_sem_course_code, 
                          t1.previous_sem_code,t1.previous_year_code,t1.dept_name ,t1.shortlist_status ,
                          t1.total_experiance,t1.full_name,t1.prog_name,  t1.highest_qualification,t1.inst_designation,t1.mail,
                          t1.cv_file_name, t1.portfolio_file_name,t1.ppt_video,  t1.admin_approved,t1.rateband_approved,
                          t1.hr_approved,t1.instructor_workload_admin_approved, 
                          t1.instructor_workload_hr_approved,t1.instructor_workload_uso_hr_approved,
                          t1.cpop_user_status,t1.country_name,t1.hr_status,t1.hr_remark,t1.hr_status_new,t1.hr_remark_new,
                          t1.dob,t1.VF_code,t1.blood_group,t1.mobile_no,t1.emergency_contact_number,t1.permanent_address,t1.address,
                          t1.total_experiance_months,TA_user = 'TA', rate_band_range.rate_band 
                          from (
						  select tad.user_id,approved ='N',tad.semester_type,tad.year_semester,studio_brief=NULL,tad.is_submit,tad.course_code,
                          iti.dept_code,iti.prog_code,iti.prog_level_code,iti.studio_level,  
                          iti.studio_title,iti.no_of_tutor,iti.teaching_mode,iti.studio_description,iti.previous_sem_course_code,  iti.previous_sem_code,iti.previous_year_code
                          ,department_mst.dept_name,iwssp.status as shortlist_status 
                          ,im.total_experiance,um.full_name,prog_name =NULL, im.highest_qualification,im.designation as inst_designation,im.mail, im.cv_file_name,
                          im.portfolio_file_name,ppt_video =NULL,  im.admin_approved,im.rateband_approved,im.hr_approved
                          ,iwd.admin_approved instructor_workload_admin_approved, 
                          iwd.hr_approved instructor_workload_hr_approved,iwd.uso_hr_approved instructor_workload_uso_hr_approved
                          ,ISNULL(cpop.cancel_flag,'Y') as cpop_user_status,cm.name as country_name,iwssp.hr_status,tad.remark as hr_remark
                          ,tutor_type_inst =NULL,hr_status_new=NULL,tad.remark as hr_remark_new,hr_cancel_flag ='N'
                          ,im.dob,im.VF_code,im.blood_group,im.mobile_no,im.emergency_contact_number,im.permanent_address,im.address,im.total_experiance_months,tad.studio_code 
                          from TA_department_wise_apply as tad
                          inner join instructor_teaching_interest as iti on iti.studio_code = tad.studio_code
                          inner join department_mst on department_mst.dept_code = iti.dept_code 
                          inner join instructor_wise_shortlist_studio_proposal_dtl as iwssp on iwssp.studio_code = iti.studio_code
                          inner join instructor_mst as im on im.instructor_code = tad.user_id
                          inner join user_mst um on um.user_id = tad.user_id
                          left join instructor_workload_detail iwd on iwd.course_code = tad.course_code  and iwd.instructor_code = tad.user_id and iwd.semester_type = tad.semester_type 
                          and iwd.year_semester = tad.year_semester  and tad.cancel_flag ='N' 
                          left join cpop_superviser_mst cpop on cpop.superviser_code = tad.user_id 
                          and cpop.cancel_flag = 'N'
                          left join country_mst cm on cm.id = im.indian_citizen";

            SqlSelect += " where " +
               " tad.semester_type ='" + sem_code + "' and tad.year_semester='" + year_code + "' and tad.cancel_flag='Y' and tad.hr_approved='R' ";
            if (prog_code != "")
            {
                SqlSelect = SqlSelect + " and iti.prog_code = '" + prog_code + "'";
            }
            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and iti.dept_code = '" + dept_code + "'";
            }
            if (tutor_type != "" && tutor_type == "TEA")
            {
                SqlSelect = SqlSelect + " and im.designation_letter = '" + tutor_type + "'";
            }

            if (tutor_type != "" && tutor_type != "TEA")
            {
                if (tutor_type == "core")
                {
                    SqlSelect = SqlSelect + " and  cpop.cancel_flag = 'N'";
                }
                else { SqlSelect = SqlSelect + " and im.designation = '" + tutor_type + "'"; }

            }

            SqlSelect = SqlSelect + " ) as t1";
            SqlSelect = SqlSelect + " left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(t1.highest_qualification,'') " +
                "  and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT))  " +
                "  and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT)) " +
                "  and ISNULL(rate_band_range.designation,'') = case ISNULL(t1.inst_designation,'')  " +
                "  when 'instructor' then 'VF' when 'temp' then 'VF'  else ISNULL(t1.inst_designation,'') end  " +
                " and rate_band_range.typology_sub_group ='SG003' ";

            if (dt != null)
            {
                SqlSelect = SqlSelect + " and rate_band_range.semester_type='" + sem_code + "' and rate_band_range.year_semester ='" + year_code + "'";
            }
            else { SqlSelect = SqlSelect + " and rate_band_range.semester_type IS NULL and rate_band_range.year_semester IS NULL "; }



            SqlSelect += " ) as t1 order by t1.studio_code desc ";

            return Get_data(SqlSelect);
        }



