        public DataTable Get_Ws_Reg_student_dtl(string sem_code, string year_code, string dept_code, string prog_code, string type, string student_code, string course_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select wsw.user_id,wsw.course_code,wsw.year_code,wsw.semester_code,wsw.current_sem_code,wsw.course_type,wsw.fees,wsw.credits, " +
                " wsw.gpa_nongpa,wsw.dept_code,wsw.priority,wsw.status,wsw.cancel_flag,wsw.course_drop,wsw.remark,wsw.semester_type,wsw.year_semester,wsw.round,wsw.course_number,um.prog_code,um.full_name,um.dept_code," +
                "  CASE WHEN (wsw.status = 'R' and wsw.cancel_flag='Y' and wsw.is_cancel='Y' and wsw.priority ='0' ) THEN 'Course Cancelled' " +
                "  WHEN (wsw.status = 'A' and wsw.cancel_flag='N' ) THEN 'Allocated' WHEN (wsw.status = 'A' and wsw.cancel_flag='Y' ) THEN 'Drop' WHEN wsw.status = 'R' THEN 'Registered' WHEN wsw.status = 'W' THEN 'Waiting' WHEN wsw.status = 'C' THEN 'Cancelled' ELSE wsw.status END as status_name " +
                " from ws_student_wise_course_dtl wsw " +
                " inner join user_mst um on um.user_id = wsw.user_id " +
                " where wsw.semester_type = '" + sem_code + "' and wsw.year_semester = '" + year_code + "'  ";
            if (type != "CC")
            {
                if (type == "D")
                {
                    SqlSelect = SqlSelect + " and wsw.cancel_flag ='Y'";
                }
                else { SqlSelect = SqlSelect + " and wsw.cancel_flag ='N'"; }

            }

            if (dept_code != "")
            {

                SqlSelect = SqlSelect + " and um.dept_code = '" + dept_code + "' ";

            }

            if (prog_code != "")
            {

                SqlSelect = SqlSelect + " and um.prog_code = '" + prog_code + "' ";

            }

            if (type != "")
            {
                if (type == "CC")
                {
                    SqlSelect = SqlSelect + " and wsw.cancel_flag ='Y' and wsw.status = 'R' and priority='0' and is_cancel ='Y'  ";
                }
                else if (type == "D")
                {
                    SqlSelect = SqlSelect + " and wsw.status = 'A' ";
                }
                else { SqlSelect = SqlSelect + " and wsw.status = '" + type + "' "; }

            }

            if (student_code != "")
            {
                SqlSelect = SqlSelect + " and wsw.user_id = '" + student_code + "' ";
            }
            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and wsw.course_code = '" + course_code + "' ";
            }

            SqlSelect = SqlSelect + " order by um.user_id ";

            int yearcode = Convert.ToInt32(year_code);
            if ((sem_code == "W" && year_code == "2023") || yearcode >= Convert.ToInt32("2024"))
            {
                SqlSelect = "";


                SqlSelect = @" select wsw.user_id,wsw.course_code,wsw.course_type,wsw.credits,  
                               ws.gpa_status as gpa_nongpa,ws.dept_code,wsw.priority,wsw.status,wsw.cancel_flag,wsw.course_drop_status as course_drop,wsw.semester_type,wsw.year_semester,
                               um.prog_code,um.full_name,um.dept_code, 
                               CASE WHEN (wsw.status = 'R' and wsw.cancel_flag='Y' ) THEN 'Expire'
                               WHEN (wsw.status = 'E' and wsw.cancel_flag='Y' ) THEN 'Expire'
                               WHEN (wsw.status = 'P' and wsw.cancel_flag='N' and wsw.course_drop_status ='Y') THEN 'Course Drop'                               
                               WHEN (wsw.status = 'P' and wsw.cancel_flag='N' ) THEN 'Provisionally Allocated'
                                  
                               WHEN (wsw.status = 'A' and wsw.cancel_flag='N' ) THEN 'Allocated' WHEN (wsw.status = 'A' and wsw.cancel_flag='Y' ) THEN 'Drop' WHEN wsw.status = 'R' THEN 'Registered' WHEN wsw.status = 'W' 
                               THEN 'Waiting' WHEN wsw.status = 'C' THEN 'Cancelled' ELSE wsw.status END as status_name 
                               from ws_connect_student_reg_dtl wsw 
                               inner join user_mst um on um.user_id = wsw.user_id 
                               inner join ws_course_mst ws on ws.course_code = wsw.course_code
                               and ws.semester_type= wsw.semester_type and ws.year_semester = wsw.year_semester
                               and ws.cancel_flag = 'N'
                               where wsw.semester_type = '" + sem_code + "' and wsw.year_semester = '" + year_code + "'  ";
                if (type != "CC")
                {
                    if (type == "D")
                    {
                        SqlSelect = SqlSelect + " and wsw.cancel_flag ='N'";
                    }
                    if (type == "E")
                    {
                        SqlSelect = SqlSelect + " and wsw.cancel_flag ='Y'";
                    }
                    else { SqlSelect = SqlSelect + " and wsw.cancel_flag ='N'"; }

                }

                if (dept_code != "")
                {

                    SqlSelect = SqlSelect + " and um.dept_code = '" + dept_code + "' ";

                }

                if (prog_code != "")
                {

                    SqlSelect = SqlSelect + " and um.prog_code = '" + prog_code + "' ";

                }

                if (type != "")
                {
                    if (type == "CC")
                    {
                        SqlSelect = SqlSelect + " and wsw.cancel_flag ='Y' and wsw.status = 'R' and priority='0' and is_cancel ='Y'  ";
                    }
                    else if (type == "D")
                    {
                        SqlSelect = SqlSelect + " and wsw.course_drop_status = 'Y' ";
                    }
                    else if (type == "E")
                    {
                        SqlSelect = SqlSelect + " and (wsw.status = 'E' or wsw.status = 'R') ";
                    }
                    else { SqlSelect = SqlSelect + " and wsw.status = '" + type + "' "; }

                }
                if (student_code != "")
                {
                    SqlSelect = SqlSelect + " and wsw.user_id = '" + student_code + "' ";
                }
                if (course_code != "")
                {
                    SqlSelect = SqlSelect + " and wsw.course_code = '" + course_code + "' ";
                }

                SqlSelect = SqlSelect + " order by um.user_id ";
            }


            return Get_data(SqlSelect);
        }




