        #region DRP Deallocated 
        public Boolean Deallocate_drp_dtl(string user_id, string sem_code, string year_code, string student_id, string drp_code, string flag_status)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            string SqlSelect = "";

            SqlSelect = @"UPDATE student_wise_drp_dtl SET cancel_flag='" + flag_status + "', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and user_id in (" + student_id + ") ";
            if (drp_code != "")
            {
                SqlSelect = SqlSelect + " and drp_code ='" + drp_code + "'";
            }
            if (flag_status == "Y")
            {
                SqlSelect = SqlSelect + " and cancel_flag ='N'";
            }
            else if (flag_status == "N")
            {
                SqlSelect = SqlSelect + " and cancel_flag ='Y'";
            }

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }

        public DataTable get_drp_student_dtl(string sem_code, string year_code, string drp_code, string course_code, string student_year_code, string prog_level)
