                " case swd.seat_type WHEN 'F' THEN 'Funded' when 'UF' THEN 'Unfunded' END as seat_type from student_wise_drp_dtl swd " +
                " inner join user_mst um on um.user_id = swd.user_id " +
                " inner join course_wise_drp_dtl cwd on cwd.drp_code = swd.drp_code and cwd.semester_type = swd.semester_type " +
                " and cwd.year_semester = swd.year_semester and cwd.cancel_flag ='N' " +
                " where swd.semester_type='" + sem_code + "' and swd.year_semester='" + year_code + "' and swd.cancel_flag ='N' ";
            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and swd.course_code ='" + course_code + "'";
            }

            if (drp_code != "")
            {
                SqlSelect = SqlSelect + " and swd.drp_code ='" + drp_code + "'";
            }
            if (prog_level != "")
            {
                SqlSelect = SqlSelect + " and um.prog_level_code ='" + prog_level + "'";
            }
            if (student_year_code != "")
            {
                SqlSelect = SqlSelect + " and um.year_code ='" + student_year_code + "'";
            }

            return Get_data(SqlSelect);
