        public Dictionary<string, string> update_DRP_dtl(Dictionary<string, object> dic_req_data)
        {
            String SqlSelect = "";
            int res = 0;
            Dictionary<string, string> dic_response = new Dictionary<string, string>();


            SqlSelect = " update course_wise_drp_dtl set instructor_code = '" + dic_req_data["instructor_code"].ToString() + "',topic ='" + dic_req_data["topic"].ToString() + "',abstracts = '" + dic_req_data["abstract"].ToString() + "'," +
                 " reference = '" + dic_req_data["reference"].ToString() + "', doc_path = '" + dic_req_data["doc_path"].ToString() + "', vacant_seats = '" + dic_req_data["vacant_seats"].ToString() + "', " +
                 " funded_seats = '" + dic_req_data["funded_seats"].ToString() + "',unfunded_seats = '" + dic_req_data["unfunded_seats"].ToString() + "', " +
                 " last_modified_by = '" + dic_req_data["last_modified_by"].ToString() + "', last_modified_date ='" + DateTime.Now + "', last_modified_host = '" + dic_req_data["last_modified_host"].ToString() + "'" +
                 " where semester_type = '" + dic_req_data["sem_code"].ToString() + "' and year_semester = '" + dic_req_data["year_code"].ToString() + "' and cancel_flag = 'N' and course_code = '" + dic_req_data["course_code"].ToString() + "' and drp_code = '" + dic_req_data["drp_code"].ToString() + "' ";


            DBCommand.CommandText = SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();
                res = DBCommand.ExecuteNonQuery();

                if (res > 0)
                {
                    dic_response["status"] = "0";
                    dic_response["message"] = "Data Updated Successfully";
                }
                else
                {
                    dic_response["status"] = "1";
                    dic_response["message"] = "Problem in Update Data , Please Try Again";
                }
            }
            catch (Exception ex)
            {
                dic_response["status"] = "1";
                dic_response["message"] = ex.ToString();
            }

            DBConnection.Close();

            return dic_response;
        }


