        /// <summary>
        /// Update and Delete Studio Details
        /// </summary>
        /// <param name="array"></param>
        /// <param name="sem_code"></param>
        /// <param name="year_code"></param>
        /// <param name="studio_code"></param>
        /// <param name="user_id"></param>
        /// <returns></returns>

        public Boolean update_delete_studio_instr(ArrayList array, string sem_code, string year_code, string studio_code, string user_id)
        {
            DataTable dt = Get_Studio_instructor_dtl_with_cours_code(studio_code, sem_code, year_code);

            if (dt != null)
            {
                string duplicate_inst = MakeInQueryString(dt, "instructor_code");

                string SqlSelect_update = "";
                string SqlSelect_new = "";
                for (int i = 0; i < array.Count; i++)
                {
                    string inst_code = ((Dictionary<string, object>)array[i])["instructor_code"].ToString().Trim();
                    string tutor_code = ((Dictionary<string, object>)array[i])["tutor_type"].ToString().Trim();
                    string tutor_type_status = ((Dictionary<string, object>)array[i])["tbd_status"].ToString().Trim();

                    DataRow[] dr = dt.Select("instructor_code = '" + inst_code + "' and tutor_type = '" + tutor_code.Trim() + "'");
                    if (dr.Length == 0)
                    {
                        DataRow[] dr_new = dt.Select("instructor_code = '" + inst_code + "'");
                        if (dr_new.Length > 0)
                        {
                            SqlSelect_update += " update studio_wise_instructor_dtl set tutor_type='" + tutor_code.Trim() + "', last_modified_by='" + user_id + "', " +
                                " last_modified_date=GETDATE(),last_modified_host='" + HttpContext.Current.Request.UserHostName + "'" +
                                " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' " +
                                " and studio_code='" + dt.Rows[0]["studio_code"].ToString() + "' and instructor_code='" + dr_new[0]["instructor_code"].ToString() + "'";
                        }
                        else
