                                    SqlSelect_new += " Insert into studio_wise_instructor_dtl (studio_code,instructor_code,approved,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,brief_edit_status,to_be_later,shortlist,tutor_type) " +
