        /// <summary>
        /// Make A Query Data Table String 
        /// </summary>
        /// <param name="table"></param>
        /// <param name="column_name"></param>
        /// <returns></returns>

        public static String MakeInQueryString(DataTable table, String column_name)
        {
            string in_query = "", column_value = "";

            if (table != null)
            {
                for (int i = 0; i < table.Rows.Count; i++)
                {
                    column_value = table.Rows[i][column_name].ToString();
                    if (!in_query.Contains("'" + column_value + "',"))
                        in_query += "'" + column_value + "',";
                }
            }

            if (in_query.Length > 0)
                in_query = in_query.Substring(0, in_query.Length - 1);
            if (in_query == String.Empty)
                in_query = "''";
            return in_query;
        }
        /// <summary>
        /// Delete Duplicat Value in Studio 
        /// </summary>
        /// <param name="inst_code"></param>
        /// <param name="studio_code"></param>
        /// <param name="sem_code"></param>
        /// <param name="year_code"></param>
        /// <returns></returns>

        public Boolean DeleteDuplicat_value_v2(string inst_code, string studio_code, string sem_code, string year_code)
        {
            DataTable dt = Get_Studio_instructor_dtl_with_cours_code(studio_code, sem_code, year_code);
            string inst_code_new = "";
            bool status_string = true;
            if (dt != null)
            {
                DataRow[] dr = dt.Select("instructor_code Not IN(" + inst_code + ")");
                if (dr.Length > 0)
                {
                    for (int k = 0; k < dr.Length; k++)
                    {
                        string tbd_inst = dr[k]["instructor_code"].ToString();
                        if (tbd_inst.Substring(0, 2).ToString() != "TB")
                        {
                            if (status_string)
                            {
                                inst_code_new += "'" + dr[k]["instructor_code"].ToString() + "'";
                                status_string = false;
                            }
                            else
                            {
                                inst_code_new += ",'" + dr[k]["instructor_code"].ToString() + "'";
                            }
                        }

                    }

                }
            }

            if (inst_code_new != "")
            {
                /*************************/
                /* ESTABLISH CONNECTION */
                DBConnection.Open();
                /*************************/
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                String SqlSelect = "";

                SqlSelect = "Update studio_wise_instructor_dtl set cancel_flag ='Y' WHERE instructor_code IN (" + inst_code_new + ") and semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and cancel_flag ='N' and studio_code ='" + dt.Rows[0]["studio_code"] + "'";

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                try
                {
                    DBCommand.ExecuteNonQuery();
                    DBConnection.Close();
                    return true;
                }
                catch (Exception)
                {
                    DBConnection.Close();
                    return false;
                }
            }
            return false;
        }
