        public Boolean update_tobe_later_inst(string instr_code_string, string instr_tbd_string, string instr_tbd_tutor_type, string studio_code, string sem_code, string year_code, string User_id)
        {
            String SqlSelect = "";
            String update_SqlSelect = "";
            int res = 0;
            string update_tbd = "";
            bool status = true;

            string[] inst_code = instr_code_string.Split(',');
            string[] tbd_code = instr_tbd_string.Split(',');
            string[] tbd_type = instr_tbd_tutor_type.Split(',');

            for (int i = 0; i < inst_code.Length; i++)
            {
                if (inst_code[i] != "")
                {
                    if (status)
                    {
                        update_tbd += "'" + tbd_code[i] + "'";
                        status = false;
                    }
                    else { update_tbd += ",'" + tbd_code[i] + "'"; }

                    SqlSelect += "insert into studio_wise_instructor_dtl (studio_code,instructor_code,approved,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,brief_edit_status,to_be_later,shortlist,tutor_type) " +
                                    " VALUES('" + studio_code + "' , '" + inst_code[i] + "', 'N' ,'" + sem_code + "','" + year_code + "', 'N' ,'" + User_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' ,'" + HttpContext.Current.Request.UserHostName + "', 'N'";

                    SqlSelect += " , 'Y',NULL,'" + tbd_type[i] + "')";
                }

            }
            update_SqlSelect = @"UPDATE studio_wise_instructor_dtl SET cancel_flag='Y', last_modified_by='" + User_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "'and studio_code ='" + studio_code + "' and instructor_code in(" + update_tbd + ") ";


            DBCommand.CommandText = update_SqlSelect + SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();
                res = DBCommand.ExecuteNonQuery();
                return true;

            }
            catch (Exception ex)
            {
                return false;
            }

            DBConnection.Close();

            return false;
        }
