        public Boolean Send_Mail_for_Instr(string studio_code, string inst_code, string parameter, string remark)
        {
            DataTable dt = getStudioProposalsDetails_studio_wise(studio_code);
            if (dt != null)
            {
                DataTable pc_dtl = pc_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable dean_dtl = dean_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable faculty_admin = fa_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable ta_user_exits = get_ta_status_studio(inst_code, studio_code);
                DataTable dt_studio_code_dtl = getStudioProposalsDetails_studio_wise(studio_code);
                if (parameter == "StudioProposalAuthorized" && ta_user_exits != null)
                {
                    parameter = "TAAuthorization";
                }
                DataTable mail_from_id_password = check_frommail_id_password(parameter);
                DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body(parameter, "email");
                DataTable user_dtl = new DataTable();
                //if (parameter == "StudioAuthorizationRemark" || parameter == "StudioProposalAuthorized")
                //{
                //    user_dtl = Get_studio_tutor_cotutor(studio_code); 
                //}
                //else 
                //{ 
                user_dtl = check_user_by_user_id(inst_code);
                //}

                Mail mail = new Mail();
                // Chnage 18092023 By Nitin Add Dean FA PC And Other Faculty
                //if (parameter == "StudioAuthorizationRemark" || parameter == "CourseAuthorizationRemark" )
                //{
                //pc_dtl = null;
                //dean_dtl = null;
                //}
                bool mail_status = mail.StudioproposalAuthorized_new(inst_code, pc_dtl, dean_dtl, faculty_admin, mail_from_id_password, AckDetails, user_dtl, remark, dt_studio_code_dtl);
                if (mail_status == true && (parameter == "StudioProposalAuthorized" || parameter == "TAAuthorization" || parameter == "StudioAuthorizationReject"))
                {
                    bool send_mail_status = AuthorizationMailStatus(studio_code, inst_code, dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString(), AckDetails.Rows[0]["email_desc"].ToString());
                    return send_mail_status;
                }

            }
            return false;
        }


        public Boolean Send_Mail_for_Instr_CT(string studio_code, string inst_code, string parameter, string remark)
        {
            DataTable dt = getStudioProposalsDetails_studio_wise(studio_code);
            if (dt != null)
            {
                DataTable pc_dtl = pc_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable dean_dtl = dean_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable faculty_admin = fa_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable ta_user_exits = get_ta_status_studio(inst_code, studio_code);
                DataTable dt_studio_code_dtl = getStudioProposalsDetails_studio_wise(studio_code);
                if (parameter == "StudioProposalAuthorized_CT" && ta_user_exits != null)
                {
                    //parameter = "TAAuthorization";
                    parameter = "StudioProposalAuthorized_CT";
                }
                DataTable mail_from_id_password = check_frommail_id_password(parameter);
                DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body(parameter, "email");
                DataTable user_dtl = new DataTable();
                user_dtl = check_user_by_user_id(inst_code);
                Mail mail = new Mail();
                bool mail_status = mail.StudioproposalAuthorized_new(inst_code, pc_dtl, dean_dtl, faculty_admin, mail_from_id_password, AckDetails, user_dtl, remark, dt_studio_code_dtl);
                if (mail_status == true && (parameter == "StudioProposalAuthorized_CT" || parameter == "TAAuthorization" || parameter == "StudioAuthorizationReject"))
                {
                    bool send_mail_status = AuthorizationMailStatus(studio_code, inst_code, dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString(), AckDetails.Rows[0]["email_desc"].ToString());
                    if (send_mail_status)
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        /// <summary>
        /// Studio Wise Get Studio Proposal Details 
        /// </summary>
        /// <param name="studio_code"></param>
        /// <returns></returns>
        public DataTable getStudioProposalsDetails_studio_wise(string studio_code)
        {
            String SqlSelect = "";

            SqlSelect = "select isd.new_course_code, dm.dept_name,iti.* from instructor_teaching_interest iti " +
                " left join department_mst dm on dm.dept_code = iti.dept_code " +
                " left join instructor_studio_details isd on isd.studio_code = iti.studio_code " +
                " where iti.studio_code='" + studio_code + "' and iti.cancel_flag='N'";

            return Get_data(SqlSelect);
        }

