        public DataTable pc_dtl_dept_wise(string dept_code, string prog_code, string prog_level_code, string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = " select STUFF((select distinct ', ' + user_mst.mail from programme_coordinator_dtl pc" +
                " inner join user_mst on user_mst.user_id = pc.user_id " +
                " where pc.semester_type='" + sem_code + "' and pc.year_semester='" + year_code + "' " +
                " and pc.dept_code='" + dept_code + "' and pc.prog_code='" + prog_code + "' and pc.prog_level_code='" + prog_level_code + "' " +
                " and pc.cancel_flag='N' FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'),1,2,'') mail_id ";

            return Get_data(SqlSelect);
        }

