                inner join user_mst on user_mst.user_id = dean.user_id 
                inner join instructor_mst im on im.instructor_code = dean.instructor_code                
                where dean.semester_type in (select sem_code from cept_current_semester where active_flag='Y' and type_desc='all')  
				and dean.year_semester in (select year_code from cept_current_semester where active_flag='Y' and type_desc='all') 
                and dean.dept_code in 
				(select dept_code from dean_dtl where cancel_flag='N'  
                and semester_type in (select sem_code from cept_current_semester where active_flag='Y' and type_desc='all') 
                and year_semester in (select year_code from cept_current_semester where active_flag='Y' and type_desc='all')
                and dept_code in (select dm.dept_code from cpop_superviser_mst ss 
                left join department_mst dm on LOWER(dm.dept_name) = LOWER(ss.department)
                where ss.cancel_flag='N' and ss.publish_flag='Y' and ss.superviser_code ='" + inst_code + @"'))  ";

            return Get_data(SqlSelect);
        }


        public DataTable fa_dtl_dept_wise(string dept_code, string prog_code, string prog_level_code, string sem_code, string year_code)
        {
            String SqlSelect = "";

            SqlSelect = "select STUFF(( select distinct ', ' + user_mst.mail from department_wise_user_dtl as Fa_dtl" +
                " inner join user_mst on user_mst.user_id = Fa_dtl.user_id " +
                " where Fa_dtl.semester_type='" + sem_code + "' and Fa_dtl.year_semester='" + year_code + "' " +
                " and Fa_dtl.dept_code='" + dept_code + "'";
            if (prog_code != "")
            {
                SqlSelect += " and Fa_dtl.prog_code='" + prog_code + "' ";
            }
            SqlSelect += " and Fa_dtl.cancel_flag='N' and Fa_dtl.user_type='FA' FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'),1,2,'') mail_id ";

            return Get_data(SqlSelect);
        }

