        /// <summary>
        /// Send Mail For CAC Course Inst Wise
        /// </summary>
        /// <param name="course_code"></param>
        /// <param name="sem_code"></param>
        /// <param name="year_code"></param>
        /// <returns></returns>
        public Boolean Send_Mail_for_CAC_Inst(string course_code, string sem_code, string year_code)
        {
            DataTable dt = Get_course_department_data_for_modification(sem_code, year_code, course_code);
            DataTable dataTable = get_course_wise_inst_with_mail_id(sem_code, year_code, course_code);
            if (dt != null)
            {
                DataTable pc_dtl = pc_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable dean_dtl = dean_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable faculty_admin = fa_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable mail_from_id_password = check_frommail_id_password("CourseCAC");
                DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body("CourseCAC", "email");
                DataTable AckDetails_Core = Get_VF_TA_AA_Letter_Email_Body("CourseCACCore", "email");

                Mail mail = new Mail();
                bool mail_status = mail.SendCACMail(dataTable, pc_dtl, dean_dtl, mail_from_id_password, AckDetails, dt, faculty_admin, AckDetails_Core);
            }
            return false;
        }
