        /// <summary>
        /// User Bank Details Check 
        /// </summary>
        /// <param name="course_code"></param>
        /// <param name="sem_code"></param>
        /// <param name="year_code"></param>
        /// <returns></returns>
        public DataTable Get_instrctor_bank_detl_status(string course_code, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @" select * from (
                           SELECT user_id,bank_account_number,account_type,name_of_Bank,branch_name,ifsc_code,benificiary_name,designation,
                           CASE
                               WHEN (bank_account_number = '' or bank_account_number IS NULL) THEN 'false'
                               WHEN (account_type = '' or account_type IS NULL) THEN 'false'
                               WHEN (name_of_Bank = '' or name_of_Bank IS NULL) THEN 'false'
	                           WHEN (branch_name = '' or branch_name IS NULL) THEN 'false'
	                           WHEN (ifsc_code  = ''  or ifsc_code IS NULL) THEN 'false'
	                           WHEN (benificiary_name = '' or benificiary_name IS NULL) THEN 'false'
                               ELSE 'true'
                           END as status
                           FROM instructor_mst WHERE user_id in(select instructor_code from studio_wise_instructor_dtl as swid
                           inner join instructor_studio_details as isd on isd.studio_code = swid.studio_code";
            SqlSelect += " where (isd.course_code ='" + course_code + "' or isd.studio_code='" + course_code + "' or isd.new_course_code='" + course_code + "') " +
                         " and swid.cancel_flag='N' and swid.semester_type='M' and swid.year_semester='2022' and swid.approved='Y') and designation !='instructor') as t1 " +
                         " where t1.status ='false'";

            return Get_data(SqlSelect);
        }
