        /// <summary>
        /// 
        /// </summary>
        /// <param name="degree"></param>
        /// <param name="total_experiance"></param>
        /// <param name="typology_sub_group"></param>
        /// <returns></returns>
        public DataTable calculate_rate_band_typology_wise(string degree, string total_experiance, string typology_sub_group)
        {
            String SqlSelect = "";
            SqlSelect = " select * from rate_band_range " +
                        " where ISNULL(degree,'') = '" + degree + "'" +
                        " and CAST(from_experiance as INT) <= CAST(ISNULL('" + total_experiance + "',0) as INT)" +
                        " and CAST(to_experiance as INT) >= CAST(ISNULL('" + total_experiance + "',0) as INT)" +
                        " and semester_type IS NULL and year_semester IS NULL and designation='VF' and typology_sub_group ='" + typology_sub_group + "'";

            return Get_data(SqlSelect);
        }

        /// <summary>
        /// 
        /// </summary>
        /// <param name="group_id"></param>
        /// <param name="semester_type"></param>
        /// <param name="year_semester"></param>
        /// <param name="intake_capacity"></param>
        /// <param name="course_credits"></param>
        /// <param name="designation"></param>
        /// <param name="course_typology"></param>
        /// <returns></returns>
        public DataTable typology_wise_get_contact_hrs(string group_id, string semester_type, string year_semester, string intake_capacity, string course_credits, string designation, string course_typology)
        {
            if (designation != "")
            {
                String[] FileArray = designation.Split(new Char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                for (int i = 0; i < FileArray.Length; i++)
                {
                    if (i == 0)
                    {
                        designation = "'" + FileArray[i].ToString() + "'";

                    }
                    else
                    {
                        designation += ",'" + FileArray[i].ToString() + "'";
                    }
                }

            }
            String SqlSelect = "";
            SqlSelect = " select * from typology_wise_contact_hrs_mst where semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and cancel_flag='N' " +
                        " and group_id='" + group_id + "' " +
                        " and CAST(intake_capacity_min as INT) <= ('" + intake_capacity + "') and CAST(intake_capacity_max as INT) >= ('" + intake_capacity + "') " +
                        " and course_typology ='" + course_typology + "' ";
            if (course_typology == "23")
            {
                SqlSelect = SqlSelect + " and course_credits = '" + course_credits + "'";
            }
            if (designation != "")
            {
                SqlSelect = SqlSelect + " and designation in(" + designation + ")";
            }

            return Get_data(SqlSelect);
        }

        public DataTable get_course_week_details(string course_code, string sem_code, string year_code)
        {
            string Sqlselect = "";
            Sqlselect = " select course_code,from_time,To_time,cwt.room_id,cm.day_name from course_wise_time cwt " +
                " inner join day_mst as cm on cm.day_code = cwt.day_code where cwt.semester_type='" + sem_code + "' and cwt.year_semester='" + year_code + "' and cwt.course_code ='" + course_code + "' ";
            return Get_data(Sqlselect);
        }

        public DataTable dept_wise_get_time_table_dtl(string prog_code, string dept_code, string prog_level_code, string sub_category_id, string course_typology, string semester_type, string year_semester)
        {
            String SqlSelect = "";
            SqlSelect = " select dwt.dept_code,dwt.prog_code,dwt.prog_level_code,dwt.course_typology, dwtd.from_time,dwtd.to_time,dwtd.room_id,dwtd.day_code, day_mst.day_name,dwtd.seq_no,dwt.sub_category_id " +
                " from department_wise_time_table_mst dwt " +
                " inner join department_wise_time_table_dtl dwtd on dwtd.course_hrs_group_id = dwt.course_hrs_group_id and dwtd.semester_type = dwt.semester_type and dwtd.year_semester = dwt.year_semester and dwtd.cancel_flag = dwt.cancel_flag " +
                " inner join day_mst on day_mst.day_code = dwtd.day_code " +
                " where dwt.prog_code='" + prog_code + "' and dwt.dept_code='" + dept_code + "' and dwt.semester_type='" + semester_type + "' and dwt.year_semester='" + year_semester + "' and dwt.cancel_flag ='N' ";
            if (prog_code == "1")
            {
                SqlSelect += " and dwt.prog_level_code = '" + prog_level_code + "' and dwt.sub_category_id = '" + sub_category_id + "' ";
            }
            SqlSelect += " and dwt.course_typology = '" + course_typology + "'";
            SqlSelect += " order by dwtd.seq_no asc ";
            return Get_data(SqlSelect);
        }

        public Boolean course_wise_update_workload(string instructor_list, string course_list, string semester, string year_code, string user_id, string host_name, string total_weeks, string total_contact_hrs, string total_hrs, string total_hrs_in_semester, string add_hrs)
        {
            DataTable dt = get_vf_course_wise_workload_detail_v2(course_list, semester, year_code, "N");
            if (dt != null)
            {
                DataRow[] dr = dt.Select("instructor_code = '" + instructor_list + "'");
