                                Qry = Qry + @"   is_tutorial,hours_bifurcation,additional_hours,uso_hr_approved,remark,edit_workload
                          	    FROM (SELECT ROW_NUMBER() OVER(ORDER BY doc_no) AS RowNum,@CurrentDocNo as doc_no,instructor_code,course_code,total_weeks,total_contact_hrs,total_preparation_hrs,total_hrs,total_hrs_in_semester,total_exp,
                                    rate_band,alternate_band,justification,admin_approved,hr_approved,acceptance,acceptance_type,acceptance_justification,acceptance_date,
