                                Qry = Qry + @" is_tutorial,hours_bifurcation,additional_hours,uso_hr_approved,remark,edit_workload FROM #UpdatedRecords WITH(NOLOCK)) AS T  WHERE T.RowNum = " + i + ";";

                                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                                DBDataAdpterObject.SelectCommand.CommandText = Qry;
                                if (DBCommand.ExecuteNonQuery() > 0)
