                    Path = HttpContext.Current.Server.MapPath("~/UserPersonalPhoto");
                    Path1 = HttpContext.Current.Server.MapPath("~/UserProfilePhoto");
                    Path2 = HttpContext.Current.Server.MapPath("~/Image_Rename");
                }
                List<string> ExitsFile = new List<string>();
                string[] filePaths = Directory.GetFiles(Path);
                string zipFileName = System.IO.Path.Combine(Image_Rename, "UserPersonalPhoto.zip");

                using (ZipFile zip = new ZipFile())
                {
                    for (int i = 0; i < instructor.Count; i++)
                    {
                        string file = Path + "\\" + instructor[i];
                        string file1 = Path1 + "\\" + instructor[i];
                        string file2 = Image_Rename + "\\" + instructor_pic_name[i];

                        if (File.Exists(file2))
                        {
                            File.Delete(file2);
                        }
                        if (File.Exists(file))
                        {
                            string sourceFile = file;
                            System.IO.FileInfo fi = new System.IO.FileInfo(sourceFile);
                            if (fi.Exists)
                            {
                                fi.CopyTo(file2);
                                zip.AddFile(file2, "Image_Rename");
                            }

                            ExitsFile.Add(file);
                            status = true;
                        }
                        else if (File.Exists(file1))
                        {
                            ExitsFile.Add(file1);
                            status = true;
                        }
                    }
                    if (status)
                    {
                        zip.Save(zipFileName);
                    }
                }

                if (status == false)
                {
                    return "2";
                }
            }
            catch (Exception ex)
            {
                ServerLog.ExceptionLog("image exp" + ex.Message);
                return "2";
            }

            return "1";

        }

        public Boolean ws_CancelCourseWiseGradeRange(string semester_type, string year_semester, string courses_selected, string user_id, DataSet ds_UploadData)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();

            string SqlSelect = "";

            if (courses_selected == "ALL")
            {
                SqlSelect = @"UPDATE ws_course_wise_grade_range SET cancel_flag='Y', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and semester_type='" + semester_type + "' and year_semester='" + year_semester + "' ";
            }
            else
            {
                courses_selected = "";

                DSC_WS_GradingMaster server_course_master = (DSC_WS_GradingMaster)ds_UploadData;

                for (int mprCnt = 0; mprCnt < server_course_master.ws_course_wise_grade_range.Rows.Count; mprCnt++)
                {
                    if (mprCnt == 0)
                    {
                        courses_selected = "'" + server_course_master.ws_course_wise_grade_range.Rows[mprCnt]["course_code"].ToString() + "'";
                    }
                    else
                    {
                        courses_selected += ", '" + server_course_master.ws_course_wise_grade_range.Rows[mprCnt]["course_code"].ToString() + "'";
                    }
                }

                SqlSelect = @"UPDATE ws_course_wise_grade_range SET cancel_flag='Y', last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and course_code in (" + courses_selected + ")";
            }

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBCommand.CommandText = SqlSelect;
            try
            {
                int res_update = DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }

