        public DataTable get_course_outline_for_PDF_download_year_wise(string course_code, string from_code, string to_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "select distinct course_mst.doc_no,course_mst.course_code, course_mst.course_name,course_mst.course_credits,course_mst.course_desc,course_mst.prerequisite," +
                       " course_mst.course_outline,course_mst.week1,course_mst.week2,course_mst.week3,course_mst.week4, " +
                       " course_mst.week5,course_mst.week6,course_mst.week7,course_mst.week8,course_mst.week9,course_mst.week10,course_mst.week11,course_mst.week12,course_mst.week13,course_mst.week14,course_mst.week15,course_mst.week16," +
                       " course_mst.studio_mode,department_wise_course_dtl.dept_code,department_wise_course_dtl.prog_code, " +
                       " department_wise_course_dtl.course_typology,department_wise_course_dtl.semester_code ,department_wise_course_dtl.prog_course_id,course_mst.course_structure" +
                       " ,course_mst.remark,course_mst.eval_method1,course_mst.eval_method4,course_mst.eval_method5 " +
                       " ,course_mst.problem_statement,department_wise_course_dtl.sub_category_id,department_wise_course_dtl.prog_level_code " +
                       " ,course_mst.semester_type,course_mst.year_semester,department_wise_course_dtl.dept_code,course_mst.course_expense,course_mst.course_assessment,dm.dept_name " +
                       " from course_mst " +
                       " INNER JOIN department_wise_course_dtl on course_mst.course_code = department_wise_course_dtl.course_code " +
                       " left join department_mst as dm on department_wise_course_dtl.dept_code=dm.dept_code " +
                       " left join course_wise_instructor as cwi on course_mst.course_code=cwi.course_code  " +
                       " and cwi.year_semester=course_mst.year_semester and cwi.semester_type=course_mst.semester_type " +
                       " left join instructor_mst as im on im.instructor_code=cwi.instructor_code " +
                       " where " + //course_mst.cancel_flag = 'N'
                       " course_mst.year_semester between '" + from_code + "' AND '" + to_code + "'  " +
                       " and department_wise_course_dtl.year_semester between '" + from_code + "' AND '" + to_code + "' " +
                       " and course_mst.course_code in(" + course_code + ") ";

            return Get_data(SqlSelect);
        }
