        public DataTable Get_dynamic_fees_installment_date(string sem_code, string year_code, string student_type, string user_id)
        {


            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "IF EXISTS(select * from slab_wise_fees_fine_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag = 'N' and user_id = '" + user_id + "') "
                      + " BEGIN "
                      + " select dd.user_id,dd.student_type, "

                      + " CASE ISNULL(dd.installment_1_date,'') When '' THen "
                      + " (select UPPER(CONCAT(FORMAT( slab_end_date, 'dd-MM-yyyy'), FORMAT(slab_end_date, ' (dddd)'))) as installment_1_date from slab_wise_fees_fine_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and slab_no='1' and user_id='all'"
                      + " and installment_no='1' and student_type ='" + student_type + "' and cancel_flag='N') Else dd.installment_1_date End  installment_1_date, "

                      + " CASE ISNULL(dd.installment_2_date,'') When '' THen "
                      + " (select UPPER(CONCAT(FORMAT( slab_end_date, 'dd-MM-yyyy'), FORMAT(slab_end_date, ' (dddd)'))) as installment_2_date from slab_wise_fees_fine_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and slab_no='1' and user_id='all'"
                      + " and installment_no='2' and student_type ='" + student_type + "' and cancel_flag='N') Else dd.installment_2_date End  installment_2_date, "


                      + " CASE ISNULL(dd.installment_3_date,'') When '' THen "
                      + " (select UPPER(CONCAT(FORMAT( slab_end_date, 'dd-MM-yyyy'), FORMAT(slab_end_date, ' (dddd)'))) as installment_3_date from slab_wise_fees_fine_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and slab_no='1' and user_id='all'"
                      + " and installment_no='3' and student_type ='" + student_type + "' and cancel_flag='N') Else dd.installment_3_date End  installment_3_date, "


                      + " CASE ISNULL(dd.installment_4_date,'') When '' THen "
                      + " (select UPPER(CONCAT(FORMAT( slab_end_date, 'dd-MM-yyyy'), FORMAT(slab_end_date, ' (dddd)'))) as installment_4_date from slab_wise_fees_fine_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and slab_no='1' and user_id='all'"
                      + " and installment_no='4' and student_type ='" + student_type + "' and cancel_flag='N') Else dd.installment_4_date End  installment_4_date "
                      + " from ( "
                      + " select user_id,PivotTable.student_type,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[1], 'dd-MM-yyyy'), FORMAT(PivotTable.[1], ' (dddd)'))) as installment_1_date,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[2], 'dd-MM-yyyy'), FORMAT(PivotTable.[2], ' (dddd)'))) as installment_2_date,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[3], 'dd-MM-yyyy'), FORMAT(PivotTable.[3], ' (dddd)'))) as installment_3_date,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[4], 'dd-MM-yyyy'), FORMAT(PivotTable.[4], ' (dddd)'))) as installment_4_date "
                      + " FROM ( SELECT user_id, student_type, installment_no,slab_end_date FROM slab_wise_fees_fine_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag = 'N' and slab_no='1' and user_id = '" + user_id + "' and student_type ='" + student_type + "'"
                      + " ) StudentResults PIVOT ( MAX(slab_end_date) FOR installment_no IN ([1],[2],[3],[4])) AS PivotTable) as dd END "
                  + " ELSE "
                      + " BEGIN "
                      + " Select user_id,PivotTable.student_type,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[1], 'dd-MM-yyyy'), FORMAT(PivotTable.[1], ' (dddd)'))) as installment_1_date,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[2], 'dd-MM-yyyy'), FORMAT(PivotTable.[2], ' (dddd)'))) as installment_2_date,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[3], 'dd-MM-yyyy'), FORMAT(PivotTable.[3], ' (dddd)'))) as installment_3_date,"
                      + " UPPER(CONCAT(FORMAT( PivotTable.[4], 'dd-MM-yyyy'), FORMAT(PivotTable.[4], ' (dddd)'))) as installment_4_date "
                      + " FROM ( SELECT user_id, student_type, installment_no,slab_end_date FROM slab_wise_fees_fine_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag = 'N' and slab_no='1' and user_id = 'all' and student_type ='" + student_type + "'"
                      + " ) StudentResults PIVOT ( MAX(slab_end_date) FOR installment_no IN ([1],[2],[3],[4])) AS PivotTable"
                      + " END ";

            return Get_data(SqlSelect);
        }



