        public DataTable Get_course_wise_contact_hrs(string sem_code, string year_code, string course_code)
        {
            String SqlSelect = "";
            SqlSelect = " select * from typology_wise_contact_hrs_mst as tw inner join course_mst cm on cm.hrs_group_id= tw.group_id and cm.semester_type= tw.semester_type and cm.year_semester= tw.year_semester " +
                "  inner join department_wise_course_dtl dw on dw.course_code= cm.course_code and dw.semester_type= tw.semester_type and dw.year_semester= tw.year_semester " +
                "  where tw.semester_type='" + sem_code + "' and tw.year_semester='" + year_code + "'  and tw.cancel_flag='N' and CAST(tw.intake_capacity_min as INT) <= (dw.available_seat) " +
                "  and CAST(tw.intake_capacity_max as INT) >= (dw.available_seat) and tw.course_typology = dw.course_typology  and tw.course_credits = cm.course_credits " +
                "  and tw.designation='TA' and cm.course_code='" + course_code + "'";
            return Get_data(SqlSelect);
        }



