        public BLReturnObject save_smartcard_fees_payment(DataSet ds_UploadData, string compnyid, String UserID, String HostName, ref DSC_HostelFeesPayment ref_objCourseMaster_upload)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_HostelFeesPayment server_course_master = (DSC_HostelFeesPayment)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_HostelFeesPayment objCourseMaster_upload = new DSC_HostelFeesPayment();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_master.smartcardPaymentTransaction.Rows.Count; mprCnt++)
                {
                    objCourseMaster_upload.smartcardPaymentTransaction.ImportRow(server_course_master.smartcardPaymentTransaction.Rows[mprCnt]);
                    if (objCourseMaster_upload.smartcardPaymentTransaction[mprCnt].transaction_id == "1")
                    {
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "SPT", UserID, HostName, ref DocNo, ref message))
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        objCourseMaster_upload.smartcardPaymentTransaction[mprCnt].transaction_id = "TRNSID" + DocNo;
                        DocNo1 = "TRNSID" + DocNo;
                    }
                }

                for (int mprCnt = 0; mprCnt < server_course_master.student_smartcard_reissue_dtl.Rows.Count; mprCnt++)
                {
                    objCourseMaster_upload.student_smartcard_reissue_dtl.ImportRow(server_course_master.student_smartcard_reissue_dtl.Rows[mprCnt]);
                    objCourseMaster_upload.student_smartcard_reissue_dtl[mprCnt].doc_no = DocNo1;
                }

                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.smartcardPaymentTransaction, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.smartcardPaymentTransaction.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.student_smartcard_reissue_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.student_smartcard_reissue_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";

                    ref_objCourseMaster_upload = objCourseMaster_upload;

                    return objBLReturnObject;
                }
            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

        public DataTable get_smartcardTransactionsDetail_for_mail_send(string trans_id)
