        public DataTable Get_smart_card_dtl(string user_id, string semester_type, string year_semester, string dept_code, string prog_code, string status)
        {
            String SqlSelect = "";

            SqlSelect = " select ssr.doc_no,ssr.user_id,user_mst.full_name,dm.dept_name,pm.prog_name,FORMAT(user_mst.dob,'dd-MM-yyyy')dob,user_mst.blood_group, " +
                " user_mst.address,user_mst.emergency_contact_2,spt.amount,spt.transaction_id, " +
                " case when spt.payment_response_code = '0' then 'Payment Received' else NULL END as payment_status, " +
                " Case when ssr.status = 'A' Then 'Accepted' when ssr.status ='R' Then 'Rejected' Else 'In-Progress' END as smart_card_status, " +
                " ssr.status,user_mst.mail,spt.amount, " +
                " ssr.semester_type,ssr.year_semester " +
                " from student_smartcard_reissue_dtl ssr " +
                " left join user_mst on user_mst.user_id = ssr.user_id " +
                " inner join smartcardPaymentTransaction spt on spt.transaction_id = ssr.doc_no  " +
                " left join department_mst dm on dm.dept_code= spt.dept_id " +
                " left join programme_mst pm on pm.prog_code = user_mst.prog_code " +
                " where ssr.cancel_flag='N' and spt.payment_response_code = '0' ";
            if (semester_type != "")
            {
                SqlSelect += " and ssr.semester_type ='" + semester_type + "'";
            }

            if (year_semester != "")
            {
                SqlSelect += " and ssr.year_semester ='" + year_semester + "'";
            }
            if (dept_code != "")
            {
                SqlSelect += " and user_mst.dept_code ='" + dept_code + "'";
            }
            if (prog_code != "")
            {
                SqlSelect += " and user_mst.prog_code ='" + prog_code + "'";
            }
            if (user_id != "")
            {
                SqlSelect += " and ssr.user_id ='" + user_id + "'";
            }
            if (status != "")
            {
                SqlSelect += " and ssr.status ='" + status + "'";
            }
            return Get_data(SqlSelect);
        }

