        public DataTable get_rights_dtl(string user_id)
        {

            String SqlSelect = "";

            SqlSelect = "IF EXISTS (select * from user_group where group_id='Sel_Tutor' and status='A' and user_id='" + user_id + "')";
            SqlSelect += " BEGIN select * from user_group where group_id='Sel_Tutor' and status='A' and user_id='" + user_id + "' END ";
            SqlSelect += " ELSE BEGIN IF EXISTS(select * from user_group where group_id='Tutor' and status='A' and user_id='" + user_id + "') ";
            SqlSelect += "  BEGIN   select * from user_group where group_id='Tutor' and status='A' and user_id='" + user_id + "' END";
            SqlSelect += " ELSE BEGIN select * from user_group where group_id='TA_Tutor' and status='A' and user_id='" + user_id + "' END END";
            return Get_data(SqlSelect);

        }

