                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                if (dt_personal == null)
                {


                    string doc_no = dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString();
                    SqlSelect += "update TA_department_wise_apply set cancel_flag ='Y' where cancel_flag='N' and user_id = '" + user_id + "' and semester_type = '" + semester + "' and year_semester = '" + year + "'";
                    for (int i = 0; i < dic_req.Count; i++)
                    {
                        string remark_text = string.Empty;
                        string dept_code = ((Dictionary<string, object>)dic_req[i])["dept_code"].ToString().Trim();
                        string prev_text = ((Dictionary<string, object>)dic_req[i])["prev_text"].ToString().Trim();
                        string apply_type_course = ((Dictionary<string, object>)dic_req[i])["apply_type"].ToString().Trim();
                        if (dt_personal != null)
                        {
                            DataRow[] dr = dt_personal.Select("dept_code='" + dept_code + "' and apply_type='" + apply_type_course + "'");
                            if (dr.Length > 0)
                            {
                                remark_text = dr[0]["remark"].ToString();
                            }
                        }

                        if (prev_text == "")
                        {
                            prev_text = string.Empty;
                        }
                        else
                        {
                            prev_text = prev_text.Replace("'", "''");
                        }
                        string refrence_path = ((Dictionary<string, object>)dic_req[i])["refrence_path"].ToString().Trim();



                        SqlSelect += "INSERT INTO TA_department_wise_apply (doc_no,user_id,dept_code,is_submit,faculty_selected,hr_approved,refrence_letter_path,past_studio_ta_txt,semester_type,year_semester,cancel_flag,created_by, " +
                                    " created_date,created_host,total_experiance,apply_type,remark ) "
                                  + " VALUES('" + doc_no + "','" + user_id + "'," +
                                  "'" + (dept_code == "" ? null : dept_code) + "'," +
                                  "'" + is_submit.Trim() + "','N','N'," +
                                  "'" + (((Dictionary<string, object>)dic_req[i])["refrence_path"].ToString().Trim() != string.Empty
                                  && ((Dictionary<string, object>)dic_req[i])["refrence_path"].ToString().Trim() != "" ? ((Dictionary<string, object>)dic_req[i])["refrence_path"].ToString().Trim() : DBNull.Value.ToString()) + "'," +
                                  "'" + (prev_text == "" ? DBNull.Value.ToString() : prev_text) + "'," +
                                  "'" + semester + "','" + year + "','N','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "' , '" + ((Dictionary<string, object>)dic_req[i])["total_experiance_months"].ToString().Trim() + "', '" + ((Dictionary<string, object>)dic_req[i])["apply_type"].ToString().Trim() + "','" + remark_text + "'); ";

                        SqlSelect += "update next_doc_no set next_doc_no ='" + (Convert.ToInt32(doc_no.ToString()) + 1) + "' where doc_type = 'TA_Apply'";
                        int doc_no_ = Convert.ToInt32(doc_no.ToString()) + 1;
                        doc_no = Convert.ToString(doc_no_);
                    }

                }
                else
                {
                    SqlSelect = "";
                    SqlSelect += "update TA_department_wise_apply set is_submit = '" + is_submit + "', total_experiance ='" + ((Dictionary<string, object>)dic_req[0])["total_experiance_months"].ToString().Trim() + "',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host='" + HttpContext.Current.Request.UserHostName + "' where cancel_flag='N' and user_id = '" + user_id + "' and semester_type = '" + semester + "' and year_semester = '" + year + "'";
                }


                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DBCommand.ExecuteNonQuery();

                DBConnection.Close();
                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();
                return false;
            }


            return false;

        }


        public DataTable get_apply_ta_dtl_department_wise(string semester, string year, string user_id, string studio_code, string dept_code, string type)
        {

            String SqlSelect = "";

            SqlSelect = " Select us.full_name as faculty_selected_name,t1.* from ( ";
            SqlSelect += @" Select um.user_id, um.user_name, um.full_name,um.mail, um.profile_photo, um.mobile_no,  iti.studio_level,iti.semester_type, iti.year_semester, iti.no_of_tutor,
                            iti.teaching_mode, iti.previous_sem_course_code, iti.previous_sem_code, iti.previous_year_code, 
                            tdw.doc_no, tdw.dept_code, tdw.prog_code, tdw.prog_level_code, tdw.is_submit, tdw.faculty_selected, tdw.faculty_selected_by, tdw.hr_approved,
                            tdw.refrence_letter_path, tdw.past_studio_ta_txt,tdw.total_experiance, tdw.rate_band, tdw.remark, tdw.course_code, tdw.new_course_code,tdw.apply_type,
                           (CASE When tdw.faculty_selected ='Y' Then isNULL(iti.studio_code, cm.course_code) END) studio_code,
                           (CASE When tdw.faculty_selected ='Y' Then isNULL(iti.studio_title, cm.course_name) END) studio_title,
                           (CASE When tdw.faculty_selected ='N' Then 'Pending' When  tdw.faculty_selected ='Y' Then 'Approved' Else faculty_selected END) faculty_status,dp.dept_name,tdw.doc_no as new_doc_no,
                           instructor_mst.cv_file_name,instructor_mst.portfolio_file_name,iti.dept_code as deptcode,iti.prog_code as progcode,iti.prog_level_code as proglevelcode
                           from TA_department_wise_apply tdw
                           left join instructor_teaching_interest iti on iti.studio_code= tdw.studio_code and iti.semester_type= tdw.semester_type and iti.year_semester= tdw.year_semester
                           and iti.cancel_flag='N' 
                           left join instructor_mst on instructor_mst.instructor_code = tdw.user_id
                           inner join department_mst dp on dp.dept_code = tdw.dept_code
                           inner join user_mst um on um.user_id = tdw.user_id
                           left join course_mst cm on cm.course_code = tdw.studio_code and cm.semester_type='" + semester + @"' and cm.year_semester='" + year + @"'
                           where tdw.semester_type='" + semester + "' and tdw.year_semester='" + year + "' and tdw.dept_code='" + dept_code + "' and tdw.is_submit='Y' and tdw.cancel_flag='N' and tdw.faculty_selected in ('N','Y')  ";

            if (semester == "M" && year == "2023")
            {
                SqlSelect += "and tdw.apply_type='" + type + "'";
            }
            if (Convert.ToInt32(year) > 2023)
            {
                SqlSelect += "and tdw.apply_type='" + type + "'";
            }

            SqlSelect += " ) t1 left join user_mst us on us.user_id = t1.faculty_selected_by";

            return Get_data(SqlSelect);

        }


        public DataTable get_user_wise_department(string semester, string year, string user_id, string user_type)
        {
            String SqlSelect = "";

            SqlSelect = @" select distinct dm.dept_code,dm.dept_name 
						   from studio_wise_instructor_dtl  swi
						   inner join instructor_wise_shortlist_studio_proposal_dtl as iws on iws.studio_code = swi.studio_code 
						   inner join instructor_teaching_interest iti on iti.studio_code= swi.studio_code
						   inner join department_mst dm on dm.dept_code = iti.dept_code
						   where swi.semester_type='" + semester + "' and swi.year_semester='" + year + "' and swi.cancel_flag='N' and iws.status='A'";
            if (user_type != "A1" && user_type != "FA")
            {
                SqlSelect = SqlSelect + " and swi.instructor_code='" + user_id + "' ";
            }
            if (user_type == "FA")
            {
                SqlSelect = SqlSelect + " and iti.dept_code in (select dept_code from department_wise_user_dtl where semester_type='" + semester + "' and year_semester ='" + year + "' and user_type='FA' and cancel_flag='N' and instructor_code ='" + user_id + "')";
                SqlSelect = SqlSelect + " and iti.prog_code in (select prog_code from department_wise_user_dtl where semester_type='" + semester + "' and year_semester ='" + year + "' and user_type='FA' and cancel_flag='N' and instructor_code ='" + user_id + "')";
            }

            return Get_data(SqlSelect);
        }


        public DataTable get_user_wise_studio_code(string semester, string year, string user_id, string action, string dept_code, string user_type)
        {
            String SqlSelect = "";

            SqlSelect = @" select swi.studio_code,swi.instructor_code,swi.approved,swi.tutor_type,swi.semester_type,swi.year_semester,swi.brief_edit_status,swi.to_be_later,swi.shortlist ,
						   iti.dept_code,iti.prog_code,iti.prog_level_code,dm.dept_name,iti.studio_title 
						   from studio_wise_instructor_dtl  swi
						   inner join instructor_wise_shortlist_studio_proposal_dtl as iws on iws.studio_code = swi.studio_code 
						   inner join instructor_teaching_interest iti on iti.studio_code= swi.studio_code
                           inner join instructor_studio_details sbs on sbs.studio_code= swi.studio_code and sbs.studio_brief_status != 'N'
						   inner join department_mst dm on dm.dept_code = iti.dept_code
						   where swi.instructor_code='" + user_id + "' and swi.semester_type='" + semester + "' and swi.year_semester='" + year + "' and swi.cancel_flag='N' and iws.status='A'";
            if (dept_code != "")
            {
                SqlSelect += " and dm.dept_code='" + dept_code + "'";
            }

            if (action == "24")
            {
                SqlSelect = "";
                SqlSelect = @" select (cm.course_code + ' - ' + cm.course_name) course_name,cm.course_code  from department_wise_course_dtl dwc 
						   inner join course_mst cm on cm.course_code = dwc.course_code and cm.semester_type = dwc.semester_type
						   and cm.year_semester = dwc.year_semester 
                           inner join course_wise_instructor cwi on cwi.course_code = dwc.course_code
						   and cwi.semester_type = dwc.semester_type and cwi.year_semester= dwc.year_semester
						   where dwc.semester_type='" + semester + @"' and dwc.year_semester='" + year + @"'
                           and dwc.course_typology='" + action + @"'  and dwc.cancel_flag in ('N','Y')";
                if (dept_code != "")
                {
                    SqlSelect += " and dwc.dept_code='" + dept_code + "'";
                }
                if (user_type == "I2")
                {
                    SqlSelect += " and cwi.instructor_code='" + user_id + "'";
                }
                if (user_type == "FA")
                {
                    SqlSelect = SqlSelect + " and dwc.dept_code='" + dept_code + "' and dwc.prog_code in (select prog_code from department_wise_user_dtl where semester_type='" + semester + "' and year_semester ='" + year + "' and user_type='FA' and cancel_flag='N' and instructor_code ='" + user_id + "') ";
                }

            }




            return Get_data(SqlSelect);
        }


        public DataTable get_ugpg_studio_code(string semester, string year, string dept_code, string user_type, string user_id, string type)
        {
            String SqlSelect = "";

            if (type == "23")
            {
                SqlSelect = @" select distinct swi.studio_code,swi.semester_type,swi.year_semester,
						   iti.dept_code,iti.prog_code,iti.prog_level_code,dm.dept_name,iti.studio_title,isd.course_code,isd.new_course_code 
						   from studio_wise_instructor_dtl  swi
						   inner join instructor_wise_shortlist_studio_proposal_dtl as iws on iws.studio_code = swi.studio_code 
						   inner join instructor_teaching_interest iti on iti.studio_code= swi.studio_code
						   inner join department_mst dm on dm.dept_code = iti.dept_code
						   inner join instructor_studio_details as isd on isd.studio_code = swi.studio_code and isd.cancel_flag='N'
                           left join course_mst cm on cm.course_code = isd.new_course_code and cm.semester_type = isd.semester_type and cm.year_semester = isd.year_semester
						   where swi.semester_type='" + semester + "' and swi.year_semester='" + year + "' and swi.cancel_flag='N' and iws.status='A' and isd.course_code IS Not NULL ";

                if (user_type == "A1")
                {
                    SqlSelect = SqlSelect + " and iti.dept_code='" + dept_code + "'";
                }
                if (user_type == "FA")
                {
                    SqlSelect = SqlSelect + " and iti.dept_code='" + dept_code + "' and iti.prog_code in (select prog_code from department_wise_user_dtl where semester_type='" + semester + "' and year_semester ='" + year + "' and user_type='FA' and cancel_flag='N' and instructor_code ='" + user_id + "') and cm.ugpgoffice_approved in ('N','Y')";
                }
            }

            if (type == "24")
            {
                SqlSelect = "";
                SqlSelect = @" select cm.course_code as studio_code ,cm.course_name as studio_title  from department_wise_course_dtl dwc 
						   inner join course_mst cm on cm.course_code = dwc.course_code and cm.semester_type = dwc.semester_type
						   and cm.year_semester = dwc.year_semester 
						   where dwc.semester_type='" + semester + @"' and dwc.year_semester='" + year + @"'
                           and dwc.course_typology='" + type + @"'  and dwc.cancel_flag in ('N','Y')";
                if (dept_code != "" && user_type == "A1")
                {
                    SqlSelect += " and dwc.dept_code='" + dept_code + "'";
                }
                if (user_type == "FA")
                {
                    SqlSelect = SqlSelect + " and dwc.dept_code='" + dept_code + "' and dwc.prog_code in (select prog_code from department_wise_user_dtl where semester_type='" + semester + "' and year_semester ='" + year + "' and user_type='FA' and cancel_flag='N' and instructor_code ='" + user_id + "') ";
                }


            }

            return Get_data(SqlSelect);
        }


