                " where cancel_flag = 'N' and doc_no='" + doc_no + "' and user_id ='" + instructor_code + "' ";
            // This Changes By Nitinbhai 17072023
            SqlSelect += @" UPDATE instructor_mst set admin_approved='Y',rateband_approved='Y' ,last_modified_by='" + user_id + "',last_modified_date =GETDATE(),last_modified_host='" + HttpContext.Current.Request.UserHostName + "' where instructor_code='" + instructor_code + "'";

            if (type == "23")
            {
                SqlSelect += @"UPDATE TA_department_wise_apply SET faculty_selected ='D'," +
                " last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  " +
                " where cancel_flag = 'N' and doc_no !='" + doc_no + "' and user_id ='" + instructor_code + "' " +
                " and semester_type = '" + semester_type + "' and year_semester ='" + year_semester + "' and apply_type ='23' ";
            }

            if (existing_data != null && type == "24")
            {
                SqlSelect = "";
                DataTable dt_next_doc_no = GetNextDocNobyDocType("TA_Apply");
                next_doc_no = Convert.ToInt32(dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString()) + 1;

