                //             refrence_letter_path,past_studio_ta_txt,total_experiance,rate_band,studio_code,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,apply_type,hr_approved)";
                //SqlSelect += " Values ('" + dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString() + "','" + existing_data.Rows[0]["user_id"].ToString() + "','" + existing_data.Rows[0]["dept_code"].ToString() + "','" + existing_data.Rows[0]["prog_code"].ToString() + "',";
                //SqlSelect += "'" + existing_data.Rows[0]["prog_level_code"].ToString() + "','" + existing_data.Rows[0]["is_submit"].ToString() + "','" + existing_data.Rows[0]["faculty_selected"].ToString() + "','" + user_id + "',";
                //SqlSelect += "'" + existing_data.Rows[0]["refrence_letter_path"].ToString() + "','" + existing_data.Rows[0]["past_studio_ta_txt"].ToString() + "','" + existing_data.Rows[0]["total_experiance"].ToString() + "','" + existing_data.Rows[0]["rate_band"].ToString() + "',";
                //SqlSelect += "'" + studio_code + "','" + existing_data.Rows[0]["semester_type"].ToString() + "','" + existing_data.Rows[0]["year_semester"].ToString() + "','N',";
                //SqlSelect += "'" + user_id + "',GETDATE(),'" + HttpContext.Current.Request.UserHostName + "','24','N')";


                SqlSelect += @" INSERT INTO TA_department_wise_apply (doc_no,user_id,dept_code,prog_code,prog_level_code,is_submit,faculty_selected,faculty_selected_by,
                             refrence_letter_path,past_studio_ta_txt,total_experiance,rate_band,studio_code,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,apply_type,hr_approved)";
                SqlSelect += " Values (@doc_no,@user_id,@dept_code,@prog_code,@prog_level_code,";
                SqlSelect += "@is_submit,@faculty_selected,@faculty_selected_by,";
                SqlSelect += "@refrence_letter_path,@past_studio_ta_txt,@total_experiance,@rate_band,@studio_code,";
                SqlSelect += "@semester_type,@year_semester,@cancel_flag,";
                SqlSelect += "@created_by,GETDATE(),@created_host,@apply_type,@hr_approved)";

                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@doc_no", DbType.String, dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@user_id", DbType.String, existing_data.Rows[0]["user_id"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@dept_code", DbType.String, existing_data.Rows[0]["dept_code"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@prog_code", DbType.String, existing_data.Rows[0]["prog_code"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@prog_level_code", DbType.String, existing_data.Rows[0]["prog_level_code"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@is_submit", DbType.String, existing_data.Rows[0]["is_submit"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@faculty_selected", DbType.String, existing_data.Rows[0]["faculty_selected"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@faculty_selected_by", DbType.String, user_id));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@refrence_letter_path", DbType.String, existing_data.Rows[0]["refrence_letter_path"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@past_studio_ta_txt", DbType.String, existing_data.Rows[0]["past_studio_ta_txt"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@total_experiance", DbType.String, existing_data.Rows[0]["total_experiance"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@rate_band", DbType.String, existing_data.Rows[0]["rate_band"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@studio_code", DbType.String, studio_code));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semester_type", DbType.String, existing_data.Rows[0]["semester_type"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@year_semester", DbType.String, existing_data.Rows[0]["year_semester"].ToString()));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@cancel_flag", DbType.String, "N"));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@created_by", DbType.String, user_id));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@created_host", DbType.String, HttpContext.Current.Request.UserHostName));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@apply_type", DbType.String, "24"));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@hr_approved", DbType.String, "N"));

            }
            /*************************/

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                if (existing_data != null && type == "24")
                { bool update_no = UpdateNextDocNo(next_doc_no, "TA_Apply"); }

                //DataTable pc_dtl = pc_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                //DataTable dean_dtl = dean_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable mail_from_id_password = check_frommail_id_password("TAApplication");
                DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body("TAApplication", "email");
                DataTable dt_inst_email = check_user_by_user_id(instructor_code);
                DataTable accept_ta = check_user_by_user_id(user_id);
                Mail mail = new Mail();
                bool mail_status = mail.SentTAApplicatioAccept(get_prog_code, dt_inst_email, accept_ta, mail_from_id_password, AckDetails, type);


                return true;
            }
            catch (Exception Ex)
