        public DataTable get_ta_personal_dtl_dept_sem_wise(string user_id, string sem_code, string year_code)
        {
            DataTable dt = getCurrentSemYearCallForStudio();
            String SqlSelect = "";

            SqlSelect = " select dm.dept_name, * from TA_department_wise_apply " +
                " inner join department_mst dm on dm.dept_code = TA_department_wise_apply.dept_code and dm.cancel_flag='N' " +
