        public DataTable get_student_clearance_form_table_dtl(string sem_code, string year_code, string status)
        {
            String SqlSelect = "";

            SqlSelect = " ;WITH cte AS ( ";
            SqlSelect += @" select  distinct student_clearance_form.status, user_mst.user_id,user_mst.user_name, user_mst.mail, user_mst.dept_code,
	                        student_clearance_form.department_id,
	                        student_clearance_form.department_name,
	                        student_clearance_form.value,
	                        student_clearance_form.remarks,
                            student_clearance_form.semester_type,
	                        CASE When student_clearance_form.semester_type = 'S' Then 'Spring' When student_clearance_form.semester_type = 'M' Then 'Monsoon' End sem_code,
	                        student_clearance_form.year_semester,
	                        student_clearance_form.created_by,
	                        student_clearance_form.created_date,
	                        student_clearance_form.created_host,
	                        student_clearance_form.last_modified_by,
	                        student_clearance_form.last_modified_date,
	                        student_clearance_form.last_modified_host,
	                        student_clearance_form.refund_processed,
	                        student_clearance_form.refund_remarks,	
	                        user_mst.alternet_mail, user_contact_dtl.applicant_mobile_no, 
	                        ROW_NUMBER() OVER(PARTITION BY student_clearance_form.user_id,student_clearance_form.department_id
	                        ORDER BY student_clearance_form.created_date desc ) rn
	                        from student_clearance_form 
                            inner join user_mst on user_mst.user_id = student_clearance_form.user_id 
	                        left join user_contact_dtl on user_mst.enrollment_no = user_contact_dtl.application_id
	                        WHERE 
	                        student_clearance_form.cancel_flag='N')";


            SqlSelect += @"select * from ( select Case 

                            When t2.Library = 'On Hold' Then 'On Hold' When t2.Workshops = 'On Hold' Then 'On Hold' When t2.[CEPT LAB] = 'On Hold' Then 'On Hold' When t2.[IT Office] = 'On Hold' Then 'On Hold'

                            When t2.Hostel = 'On Hold' Then 'On Hold' When t2.[StudentServicesoffice(Id, etc)] = 'On Hold' Then 'On Hold' When t2.[Campus Office] = 'On Hold' Then 'On Hold' When t2.[Account Office] = 'On Hold' Then 'On Hold'

                            When t2.[Account Details] = 'On Hold' Then 'On Hold' When t2.[Faculty Admin] = 'On Hold' Then 'On Hold' When t2.PGUGoffice = 'On Hold' Then 'On Hold' When t2.Registrar = 'On Hold' Then 'On Hold' else NULL End onhold,
							
							Case
                            When t2.Library = 'Pending' Then 'Pending' When t2.Workshops = 'Pending' Then 'Pending' When t2.[CEPT LAB] = 'Pending' Then 'Pending' When t2.[IT Office] = 'Pending' Then 'Pending'

                            When t2.Hostel = 'Pending' Then 'Pending' When t2.[StudentServicesoffice(Id, etc)] = 'Pending' Then 'Pending' When t2.[Campus Office] = 'Pending' Then 'Pending' When t2.[Account Office] = 'Pending' Then 'Pending'

                            When t2.[Account Details] = 'Pending' Then 'Pending' When t2.[Faculty Admin] = 'Pending' Then 'Pending' When t2.PGUGoffice = 'Pending' Then 'Pending' When t2.Registrar = 'Pending' Then 'Pending' else NULL End Pending, * from (";

            SqlSelect += @" select user_id,MAX(user_name) as user_name,semester_type, year_semester,MAX(mail) as mail, MAX(D1) as 'Library' ,MAX(D2) as 'Workshops' ,MAX(D3) as 'CEPT LAB' ,MAX(D4) as 'IT Office',MAX(D5) as 'Hostel',MAX(D6) as 'StudentServicesoffice(Id, etc)',
                            MAX(D7) as 'Campus Office',MAX(D8) as 'Account Details',MAX(D9) as 'Account Office',MAX(D10) as 'Faculty Admin',MAX(D11) as 'PGUGoffice',MAX(R) as 'Registrar',
							MAX(D1_Remarks) AS D1_Remarks,MAX(D2_Remarks) AS D2_Remarks,MAX(D3_Remarks) AS D3_Remarks,MAX(D4_Remarks) AS D4_Remarks,
							MAX(D5_Remarks) AS D5_Remarks,MAX(D6_Remarks) AS D6_Remarks,MAX(D7_Remarks) AS D7_Remarks,MAX(D8_Remarks) AS D8_Remarks,
							MAX(D9_Remarks) AS D9_Remarks,MAX(D10_Remarks) AS D10_Remarks,MAX(D11_Remarks) AS D11_Remarks,MAX(R_Remarks) AS R_Remarks from (  
	                        SELECT status,user_id,department_id,user_name,mail,dept_code,Case When semester_type = 'S' Then 'Spring' When semester_type = 'M' Then 'Monsoon' End semester_type,year_semester,remarks,department_id+'_Remarks' AS department_id_remarks 
                            FROM cte
                            WHERE rn = 1 ";
            if (sem_code != "" && year_code != "")
            {
                SqlSelect += " and semester_type = '" + sem_code + "' and year_semester = '" + year_code + "'";
            }
            //if (status != "")
            //{
            //    SqlSelect += " and status = '" + status + "' ";
            //}
            SqlSelect += " ) t1";
            SqlSelect += @" PIVOT(MAX(status) FOR department_id IN ([D1], [D2], [D3], [D4], [D5], [D6], [D7],[D8],[D9],[D10],[D11],[R])) AS pivot_table
							PIVOT(MAX(remarks) FOR department_id_remarks IN ([D1_Remarks], [D2_Remarks], [D3_Remarks], [D4_Remarks], [D5_Remarks], [D6_Remarks], [D7_Remarks],[D8_Remarks],[D9_Remarks],[D10_Remarks],[D11_Remarks],[R_Remarks])) AS pivot_table_remarks
							group by user_id,semester_type,year_semester ";


            SqlSelect += " ) as t2 ) as t3";

            if (status == "Approved")
            {
                SqlSelect += "  where t3.Registrar ='approved' ";
            }
            else if (status == "Pending") { SqlSelect += "  where t3.Pending ='Pending' "; }
            else if (status == "On Hold") { SqlSelect += "  where t3.onhold ='on hold' "; }
            return Get_data(SqlSelect);

        }


