        public DataTable get_semester_wise_studio_dept(string sem_code, string year_code, string user_id, string action)
        {
            string SqlSelect = "";
            if (action == "true")
            {
                SqlSelect = " select distinct dp.dept_code,dp.dept_name from studio_wise_instructor_dtl as swi ";
            }
            else { SqlSelect = " select * from studio_wise_instructor_dtl as swi "; }
            SqlSelect += @" inner join instructor_teaching_interest as iti on iti.semester_type = swi.semester_type and iti.year_semester= swi.year_semester
                          and iti.cancel_flag='N' and iti.studio_code= swi.studio_code
                           left join instructor_wise_shortlist_studio_proposal_dtl as iws on iws.studio_code = swi.studio_code and iws.cancel_flag='N'
                           inner join department_mst dp on dp.dept_code = iti.dept_code
                           left join TA_department_wise_apply as tdw on tdw.studio_code = iti.studio_code and faculty_selected in ('Y','N')
                          where swi.instructor_code='" + user_id + "' and swi.semester_type='" + sem_code + "' and swi.year_semester='" + year_code + "' and  iws.status ='A' and swi.cancel_flag ='N'";

            return Get_data(SqlSelect);
        }


        public DataTable Get_Save_Ta_Application_dtl(string user_id)
        {
            DataTable dt = Get_cept_current_sem_data("TA Application");
            string SqlSelect = @" select um.full_name,us.full_name as inst_name,dm.dept_name,tdw.*,iti.* from TA_department_wise_apply tdw
                                left join instructor_teaching_interest iti on iti.studio_code = tdw.studio_code and iti.semester_type = tdw.semester_type 
                                and iti.year_semester=tdw.year_semester and iti.cancel_flag='N'
                                left join user_mst um on um.user_id = tdw.faculty_selected_by
                                left join user_mst us on us.user_id = tdw.user_id
                                left join department_mst dm on dm.dept_code = tdw.dept_code
                                where tdw.cancel_flag='N' and tdw.semester_type='" + dt.Rows[0]["sem_code"].ToString() + "' and tdw.year_semester='" + dt.Rows[0]["year_code"].ToString() + "' and faculty_selected in ('N','Y') and tdw.user_id ='" + user_id + "'";

            return Get_data(SqlSelect);
        }


