            DBConnection.Open();

            string SqlSelect = "";

            SqlSelect = @"UPDATE TA_department_wise_apply SET course_code ='" + studio_dtl.Rows[0]["course_code"].ToString() + "'," +
                " last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  " +
                " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and studio_code='" + studio_dtl.Rows[0]["studio_code"].ToString() + "'and cancel_flag='N' and is_submit='Y' and faculty_selected='Y' and hr_approved='Y'  ";


            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }

        public Boolean New_Course_code_Update(string course_code, string semester_type, string year_semester, string new_course_code, string user_id)
        {
            DataTable studio_dtl = Get_Studio_instructor_dtl_with_cours_code(course_code, semester_type, year_semester);
            string SqlSelect = "";
            if (studio_dtl != null)
            {
                SqlSelect = @"UPDATE TA_department_wise_apply SET new_course_code ='" + studio_dtl.Rows[0]["new_course_code"].ToString() + "',course_code ='" + studio_dtl.Rows[0]["course_code"].ToString() + "'," +
                " last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  " +
                " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and (course_code='" + course_code + "' or new_course_code ='" + course_code + "'or studio_code ='" + course_code + "')and cancel_flag='N' and is_submit='Y' and faculty_selected='Y' and hr_approved='Y'  ";
            }
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            SqlSelect += @"UPDATE TA_department_wise_apply SET studio_code ='" + new_course_code.Trim().ToString() + "'," +
               " last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  " +
               " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "' and studio_code ='" + course_code + "' and apply_type ='24' and cancel_flag='N' and is_submit='Y' and faculty_selected='Y'   ";



            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }

        public DataTable GetTaApplicationData(string sem, string year, string dept_code, string UserId = "", string UserType = "")
        {
            String Qry = "";
            Qry = @"SELECT 
                    	ISNULL(UM.user_name,UM.full_name) as user_name,
                    	UM.mail,
                    	DM.dept_name,	
                    	PM.prog_name,	
                    	PLM.prog_level_name,
                        mobile_no = (select Top(1) mobile_no from TA_Applicant_Instructor_Mst where cancel_flag='N' and 
						semester_type='" + sem + @"' and year_semester='" + year + @"'
						and user_id = UM.user_id
						),
                    	CASE is_submit WHEN 'Y' THEN 'Submitted' ELSE 'Saved' END is_submit,	
                    	faculty_selected,ISNULL(UMF.user_name,UMF.full_name) as faculty_selected_by,
                    	CASE hr_approved WHEN 'Y' THEN 'Approved' ELSE 'Pending' END hr_approved,
                    	refrence_letter_path,
                    	past_studio_ta_txt,	
                    	total_experiance,
                    	rate_band,	
                    	remark,
                    	TDWA.studio_code,
                    	ITI.studio_title,
                        Case TDWA.apply_type When '23' THen 'Studio' When '24' Then 'Course' End apply_type,
                        
                        cv_file_name = (select Top(1) cv_file_name from TA_Applicant_Instructor_Mst where cancel_flag='N' and 
						semester_type='" + sem + @"' and year_semester='" + year + @"'
						and user_id = UM.user_id
						),  
                        portfolio_file_name = (select Top(1) portfolio_file_name from TA_Applicant_Instructor_Mst where cancel_flag='N' and 
						semester_type='" + sem + @"' and year_semester='" + year + @"'
						and user_id = UM.user_id
						)

                    FROM TA_department_wise_apply TDWA 
                    LEFT JOIN department_mst DM ON TDWA.dept_code = DM.dept_code
                    LEFT JOIN programme_mst PM ON TDWA.prog_code = PM.prog_code
                    LEFT JOIN programme_level_mst PLM ON 
                        TDWA.prog_level_code = PLM.prog_level_code AND 
                        PLM.dept_code = TDWA.dept_code AND 
                        PLM.prog_code = TDWA.prog_code
                    LEFT JOIN user_mst UM ON UM.user_id = TDWA.user_id
                    LEFT JOIN user_mst UMF ON TDWA.faculty_selected_by = UMF.user_id
                    LEFT JOIN instructor_teaching_interest ITI ON ITI.studio_code = TDWA.studio_code 
                    	-- ITI.dept_code = TDWA.dept_code AND 
                    	-- ITI.prog_code = TDWA.prog_code AND 
                    	-- ITI.prog_level_code = TDWA.prog_level_code AND 
                    	-- ITI.user_id = TDWA.user_id AND 
                    	-- ITI.semester_type = TDWA.semester_type AND
                    	-- ITI.year_semester = TDWA.year_semester

                        --LEFT JOIN TA_Applicant_Instructor_Mst AIM ON 
						--AIM.user_id = TDWA.user_id AND 
						--AIM.cancel_flag = 'N' AND 
						--AIM.semester_type = TDWA.semester_type AND 
						--AIM.year_semester = TDWA.year_semester
                    WHERE 
                        TDWA.cancel_flag = 'N' AND 
                        faculty_selected !='D' "
                         + (sem != null && sem != "" ? @"AND TDWA.semester_type = '" + sem + "'" : "")
                         + (year != null && year != "" ? @"AND TDWA.year_semester = '" + year + "'" : "")
                         + (dept_code != null && dept_code != "" ? @"AND TDWA.dept_code = '" + dept_code + "'" : "")
                         + (UserType != "" && UserType != null && UserType == "FA" ? "AND TDWA.dept_code IN ((SELECT DISTINCT dept_code FROM department_wise_user_dtl WHERE user_id = '" + UserId + "' AND  year_semester = '" + year + "' AND semester_type =  '" + sem + "' AND cancel_flag='N')) " : "")
                         + (UserType != "" && UserType != null && UserType == "PC" ? "AND TDWA.dept_code IN ((SELECT DISTINCT dept_code FROM programme_coordinator_dtl WHERE user_id='" + UserId + "' AND  year_semester = '" + year + "' AND semester_type =  '" + sem + "' AND cancel_flag='N')) " : "")
                         + (UserType != "" && UserType != null && UserType == "I2" ? "AND TDWA.user_id ='" + UserId + "' " : "");
            return Get_data(Qry);
        }

        public DataTable Get_MidTerm_Grade_Submission_dtl(string semester_type, string year_semester)
        {
            string Sqlselect = "";
            Sqlselect = @"Select cm.course_name,
                         CASE When mgs.faculty_approved = 'Y' Then 'Approved' Else 'Pending' End faculty_approved,
                         CASE When mgs.progcoordinate_approved = 'Y' Then 'Approved' Else 'Pending' End progcoordinate_approved,
                         CASE When mgs.ugpgoffice_approved = 'Y' Then 'Approved' Else 'Pending' End ugpgoffice_approved,
                         CASE When mgs.dean_approved = 'Y' Then 'Approved' Else 'Pending' End dean_approved,
                         mgs. * from midterm_grade_submit_detail mgs
                         inner join course_mst cm on cm.course_code = mgs.course_code
                         and cm.semester_type = mgs.semester_type and cm.year_semester= mgs.year_semester
                         where mgs.semester_type='" + semester_type + "' and mgs.year_semester ='" + year_semester + "' and mgs.cancel_flag='N'";
            return Get_data(Sqlselect);
        }

