        public Boolean update_student_contact_dtl(string user_id, string mobile_no, string emergency_contact_2, string passport_no, string name_passport, Dictionary<string, object> data, Dictionary<string, object> address_data)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DataTable dt = getCurrentSemYearforwsorall();
            string sem = dt.Rows[0]["sem_code"].ToString();
            string year = dt.Rows[0]["year_code"].ToString();
            DBConnection.Open();

            string SqlSelect = "";
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
