            address = address.Replace("&#40;", "(");
            address = address.Replace("&#41;", "(");
            address = address.Replace("&#60;", "<");
            address = address.Replace("&#62;", ">");
            address = address.Replace("&#64;", "@");
            address = address.Replace("&#38;", "&");
            address = address.Replace("&#47;", "/");


            SqlSelect = @"UPDATE user_mst SET father_contact_no = '" + data["emergency_contact_1"] + "',mobile_no ='" + mobile_no + "',emergency_contact_2 ='" + emergency_contact_2 + "',passport_no ='" + passport_no + "',name_as_passport ='" + name_passport + "',address ='" + address + "',city ='" + data["city"] + "',state ='" + data["state"] + "'  where user_id='" + user_id + "'";
            SqlSelect += @" UPDATE StudentAddressDtl Set cancel_flag ='Y',last_modified_by='" + user_id + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' where StudentCode ='" + user_id + "' and cancel_flag ='N' And SemesterType ='" + sem + "' AND YearType ='" + year + "'";
            SqlSelect += @" UPDATE StudentRFIDData Set CancelFlag ='Y',last_modified_by='" + user_id + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' where StudentCode ='" + user_id + "' and CancelFlag ='N' And SemesterType ='" + sem + "' AND YearCode ='" + year + "'";

            SqlSelect += "IF EXISTS(select * from user_contact_dtl where user_id='" + user_id + "') "
                     + " BEGIN "
                     + @"UPDATE user_contact_dtl SET applicant_mobile_no ='" + mobile_no + "',applicant_address_city ='" + data["city"] + "',guardian_mobile_no ='" + data["emergency_contact_1"] + "',applicant_address_house_no ='" + address + "',applicant_address_state='" + data["state"] + "',applicant_address_pincode='" + data["pincode"] + "'  where user_id='" + user_id + "'"
                     + " END "
                 + " ELSE "
                     + " BEGIN "
                     + " INSERT INTO user_contact_dtl (user_id,application_id,applicant_address_house_no,applicant_address_city,applicant_address_state,applicant_address_pincode,applicant_mobile_no,applicant_email_id,guardian_mobile_no,created_by,created_date,created_host) "
                     + " VALUES('" + user_id + "','" + user_id + "','" + address + "','" + data["city"] + "', '" + data["state"] + "', '" + data["pincode"] + "','" + mobile_no + "','" + data["email_id"] + "','" + data["emergency_contact_1"] + "', '" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "')"
                     + " END ";
            if (data["RFID"].ToString() != "")
            {
                SqlSelect += " INSERT INTO StudentRFIDData (StudentCode, RFIDCode, SemesterType, YearCode, CancelFlag, created_by, created_date, created_host) ";
                SqlSelect += " Values('" + user_id + "','" + data["RFID"] + "','" + sem + "','" + year + "','N','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "') ";
            }


            if (address_data.Count > 0 && address_data.ContainsKey("living_situation"))
            {
                string AddressField1 = address_data["AddressField1"].ToString().Replace("&#39;", "''");
                AddressField1 = AddressField1.Replace("&#34;", "\"");
                AddressField1 = AddressField1.Replace("&#40;", "(");
                AddressField1 = AddressField1.Replace("&#41;", "(");
                AddressField1 = AddressField1.Replace("&#60;", "<");
                AddressField1 = AddressField1.Replace("&#62;", ">");
                AddressField1 = AddressField1.Replace("&#64;", "@");
                AddressField1 = AddressField1.Replace("&#38;", "&");
                AddressField1 = AddressField1.Replace("&#47;", "/");

                string AddressField2 = address_data["AddressField2"].ToString().Replace("&#39;", "''");
                AddressField2 = AddressField2.Replace("&#34;", "\"");
                AddressField2 = AddressField2.Replace("&#40;", "(");
                AddressField2 = AddressField2.Replace("&#41;", "(");
                AddressField2 = AddressField2.Replace("&#60;", "<");
                AddressField2 = AddressField2.Replace("&#62;", ">");
                AddressField2 = AddressField2.Replace("&#64;", "@");
                AddressField2 = AddressField2.Replace("&#38;", "&");
                AddressField2 = AddressField2.Replace("&#47;", "/");



                string AddressField_1 = address_data["AddressField_1"].ToString().Replace("&#39;", "''");
                AddressField_1 = AddressField_1.Replace("&#34;", "\"");
                AddressField_1 = AddressField_1.Replace("&#40;", "(");
                AddressField_1 = AddressField_1.Replace("&#41;", "(");
                AddressField_1 = AddressField_1.Replace("&#60;", "<");
                AddressField_1 = AddressField_1.Replace("&#62;", ">");
                AddressField_1 = AddressField_1.Replace("&#64;", "@");
                AddressField_1 = AddressField_1.Replace("&#38;", "&");
                AddressField_1 = AddressField_1.Replace("&#47;", "/");

                string AddressField_2 = address_data["AddressField_2"].ToString().Replace("&#39;", "''");
