                AddressField_2 = AddressField_2.Replace("&#40;", "(");
                AddressField_2 = AddressField_2.Replace("&#41;", "(");
                AddressField_2 = AddressField_2.Replace("&#60;", "<");
                AddressField_2 = AddressField_2.Replace("&#62;", ">");
                AddressField_2 = AddressField_2.Replace("&#64;", "@");
                AddressField_2 = AddressField_2.Replace("&#38;", "&");
                AddressField_2 = AddressField_2.Replace("&#47;", "/");

                SqlSelect += @" INSERT INTO StudentAddressDtl 
                                (StudentCode, Type, NameOfAddress, WardenName, WardenNumber, RoomNumber, AddressField1, AddressField2, Area, City, PinCode, Relationship, ContactNo, cancel_flag, created_by, created_date, created_host,YearType,SemesterType)
                                VALUES (@StudentCode, @Type, @NameOfAddress, @WardenName, @WardenNumber, @RoomNumber, @AddressField1, @AddressField2, @Area, @City, @PinCode, @Relationship, @ContactNo, @CancelFlag, @CreatedBy, @CreatedDate, @CreatedHost,@YearType,@SemesterType)";


                object GetDbValue(string value)
                {
                    return string.IsNullOrEmpty(value) ? (object)DBNull.Value : value;
                }

                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@StudentCode", DbType.String, GetDbValue(user_id)));
                DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Type", DbType.String, address_data["living_situation"]));
