                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@City", DbType.String, GetDbValue(address_data["City"].ToString())));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@PinCode", DbType.String, GetDbValue(address_data["PinCode"].ToString())));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Relationship", DbType.String, GetDbValue(address_data["nameofrelationship"].ToString())));
