                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@AddressField1", DbType.String, GetDbValue(AddressField_1)));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@AddressField2", DbType.String, GetDbValue(AddressField_2)));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Area", DbType.String, GetDbValue(address_data["Area_2"].ToString())));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@City", DbType.String, GetDbValue(address_data["City_2"].ToString())));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@PinCode", DbType.String, GetDbValue(address_data["PinCode_2"].ToString())));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Relationship", DbType.String, GetDbValue(address_data["nameofrelationship"].ToString())));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@ContactNo", DbType.String, GetDbValue(address_data["OwnerNumber"].ToString())));
                }

            }
            /*************************/


            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return false;
            }
        }

        public DataTable Get_studio_proposal_excel_formate(string semester_type, string year_semester, string dept_code, string prog_code, string type)
        {
            string Sqlselect = "";
            Sqlselect = @"Select isd.studio_code,um.full_name as Name ,um.mail,um.mobile_no,dm.dept_name,pm.prog_name,
                          (CAST(im.total_experiance as INT) * CAST('12' as INT) + CAST(ISNULL(im.total_experiance_months,'') as INT)) as total_experiance,
                          im.highest_qualification,im.designation,iti.studio_title,iti.no_of_tutor,iti.teaching_mode,iti.studio_description,iti.studio_level from instructor_studio_details as isd
                          left join studio_wise_instructor_dtl as swid on swid.studio_code = isd.studio_code
                          left join user_mst um on um.user_id = swid.instructor_code
                          left join instructor_teaching_interest iti on iti.studio_code = isd.studio_code
                          left join department_mst dm on dm.dept_code= iti.dept_code 
                          left join programme_mst pm on pm.prog_code = iti.prog_code
                          left join instructor_mst im on im.instructor_code = swid.instructor_code
                          where isd.semester_type='" + semester_type + "' and isd.year_semester='" + year_semester + "' and isd.cancel_flag='N'";
            if (dept_code != "")
            {
                Sqlselect += " and iti.dept_code='" + dept_code + "' ";
            }

            if (prog_code != "")
            {
                Sqlselect += " and iti.prog_code='" + prog_code + "' ";
            }

            if (type != "")
            {
                Sqlselect += " and isd.is_submit ='" + type + "' ";
            }
            Sqlselect += " order by isd.studio_code desc";
            return Get_data(Sqlselect);
        }

        public DataTable GetWSCourseWiseInstructorData(string sem_code, string year_code, string department, string course_status)
        {
            String Qry = "";
            if (course_status == "")
            {


                Qry = @"SELECT 
                    	MAX(course_code) course_code,
                    	MAX(course_name) course_name,
                    	STUFF(
                    	(
                    		(	
                    			ISNULL((
                    				SELECT 
                    					', ' + WSCWI2.instructor_code  
                    				FROM ws_course_wise_instructor WSCWI2 
                    				WHERE 
                    					WSCWI2.course_code =  MAX(T.course_code) AND 
                    					WSCWI2.year_semester =MAX(T.year_semester) AND 
                    					WSCWI2.semester_type =MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    			+
                    			ISNULL((
                    				SELECT 
                    					', ' + WSCWT2.instructor_code  
                    				FROM ws_course_wise_TA WSCWT2 
                    				WHERE 
                    					WSCWT2.course_code =   MAX(T.course_code) AND 
                    					WSCWT2.year_semester = MAX(T.year_semester) AND 
                    					WSCWT2.semester_type = MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    		)
                    	),1,1,'') instructor_code
                    	,
                    	STUFF(
                    	(
                    		(
                    			ISNULL((
                    				SELECT 
                    					', ' + (SELECT user_name FROM user_mst UM WHERE UM.user_id = WSCWI2.instructor_code)  
                    				FROM ws_course_wise_instructor WSCWI2 
                    				WHERE 
                    					WSCWI2.course_code = MAX(T.course_code) AND
                    					WSCWI2.year_semester = MAX(T.year_semester) AND 
                    					WSCWI2.semester_type = MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    			+
                    			ISNULL((
                    				SELECT 
                    					', ' + (SELECT user_name FROM user_mst UM WHERE UM.user_id = WSCWT2.instructor_code)  
                    				FROM ws_course_wise_TA WSCWT2 
                    				WHERE 
                    					WSCWT2.course_code = MAX(T.course_code) AND 
                    					WSCWT2.year_semester = MAX(T.year_semester) AND
                    					WSCWT2.semester_type = MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    		)
                    	),1,1,'') instructor_name	
                    FROM
                    (
                    	SELECT 
                    		WSCWI.course_code,
                    		WSCM.course_name,
                    		WSCWI.instructor_code,
                    		WSCWI.year_semester,
                    		WSCWI.semester_type
                    	FROM ws_course_mst WSCM 
                    	INNER JOIN ws_course_wise_instructor WSCWI ON 
                    		WSCWI.course_code = WSCM.course_code AND
                    		WSCM.semester_type = WSCWI.semester_type AND
                    		WSCM.year_semester = WSCWI.year_semester
                    	WHERE 
                    		WSCM.cancel_flag='N' AND 
                    		WSCWI.cancel_flag='N' " +
                                (year_code != null && year_code != "" ? " AND WSCM.year_semester = '" + year_code + "' " : "") +
                                (sem_code != null && sem_code != "" ? " AND WSCM.semester_type = '" + sem_code + "' " : "") +
                                (department != null && department != "" ? " AND WSCM.dept_code = '" + department + "' " : "") + @"
                        UNION
                    	SELECT 
                    		WSCWT.course_code,
                    		WSCM.course_name,
                    		WSCWT.instructor_code,
                    		WSCWT.year_semester,
                    		WSCWT.semester_type
                    	FROM ws_course_mst WSCM 
                    	INNER JOIN ws_course_wise_TA WSCWT ON 
                    		WSCWT.course_code = WSCM.course_code AND
                    		WSCM.semester_type = WSCWT.semester_type AND
                    		WSCM.year_semester = WSCWT.year_semester
                    	WHERE 
                    		WSCM.cancel_flag='N' 
                    		AND WSCWT.cancel_flag='N' " +
                                (year_code != null && year_code != "" ? " AND WSCM.year_semester = '" + year_code + "' " : "") +
                                (sem_code != null && sem_code != "" ? " AND WSCM.semester_type = '" + sem_code + "' " : "") +
                                (department != null && department != "" ? " AND WSCM.dept_code = '" + department + "' " : "") + @"
                    ) T
                    GROUP BY course_code
                    ORDER BY MAX(course_name)";
            }

            else
            {
                Qry = @" SELECT 
                    	MAX(course_code) course_code,
                    	MAX(course_name) course_name,
                    	STUFF(
                    	(
                    		(	
                    			ISNULL((
                    				SELECT 
                    					', ' + WSCWI2.instructor_code  
                    				FROM ws_course_proposal_instructor WSCWI2 
                    				WHERE 
                    					WSCWI2.course_code =  MAX(T.course_code) AND 
                    					WSCWI2.year_semester =MAX(T.year_semester) AND 
                    					WSCWI2.semester_type =MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    			+
                    			ISNULL((
                    				SELECT 
                    					', ' + WSCWT2.instructor_code  
                    				FROM ws_course_proposal_TA WSCWT2 
                    				WHERE 
                    					WSCWT2.course_code =   MAX(T.course_code) AND 
                    					WSCWT2.year_semester = MAX(T.year_semester) AND 
                    					WSCWT2.semester_type = MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    		)
                    	),1,1,'') instructor_code
                    	,
                    	STUFF(
                    	(
                    		(
                    			ISNULL((
                    				SELECT 
                    					', ' + (SELECT user_name FROM user_mst UM WHERE UM.user_id = WSCWI2.instructor_code)  
                    				FROM ws_course_proposal_instructor WSCWI2 
                    				WHERE 
                    					WSCWI2.course_code = MAX(T.course_code) AND
                    					WSCWI2.year_semester = MAX(T.year_semester) AND 
                    					WSCWI2.semester_type = MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    			+
                    			ISNULL((
                    				SELECT 
                    					', ' + (SELECT user_name FROM user_mst UM WHERE UM.user_id = WSCWT2.instructor_code)  
                    				FROM ws_course_proposal_TA WSCWT2 
                    				WHERE 
                    					WSCWT2.course_code = MAX(T.course_code) AND 
                    					WSCWT2.year_semester = MAX(T.year_semester) AND
                    					WSCWT2.semester_type = MAX(T.semester_type)
                    				FOR XML PATH('')
                    			),'')
                    		)
                    	),1,1,'') instructor_name	
                    FROM
                    (
                    	SELECT 
                    		WSCWI.course_code,
                    		WSCM.course_name,
                    		WSCWI.instructor_code,
                    		WSCWI.year_semester,
                    		WSCWI.semester_type
                    	FROM ws_course_proposal WSCM 
                    	INNER JOIN ws_course_proposal_instructor WSCWI ON 
                    		WSCWI.course_code = WSCM.course_code AND
                    		WSCM.semester_type = WSCWI.semester_type AND
                    		WSCM.year_semester = WSCWI.year_semester
                    	WHERE 
                    		WSCM.cancel_flag='N' AND WSCM.instructor_approved='Y' AND WSCM.dean_approved='A' AND (WSCM.is_publish IS NULL or WSCM.is_publish ='N') 
                            AND
                    		WSCWI.cancel_flag='N' " +
                            (year_code != null && year_code != "" ? " AND WSCM.year_semester = '" + year_code + "' " : "") +
                            (sem_code != null && sem_code != "" ? " AND WSCM.semester_type = '" + sem_code + "' " : "") +
                            (department != null && department != "" ? " AND WSCM.inhabitation = '" + department + "' " : "") + @"
                        UNION
                    	SELECT 
                    		WSCWT.course_code,
                    		WSCM.course_name,
                    		WSCWT.instructor_code,
                    		WSCWT.year_semester,
                    		WSCWT.semester_type
                    	FROM ws_course_proposal WSCM 
                    	INNER JOIN ws_course_proposal_TA WSCWT ON 
                    		WSCWT.course_code = WSCM.course_code AND
                    		WSCM.semester_type = WSCWT.semester_type AND
                    		WSCM.year_semester = WSCWT.year_semester
                    	WHERE 
                    		WSCM.cancel_flag='N' AND WSCM.instructor_approved='Y' AND WSCM.dean_approved='A' AND (WSCM.is_publish IS NULL or WSCM.is_publish ='N') 
                    		AND WSCWT.cancel_flag='N' " +
                            (year_code != null && year_code != "" ? " AND WSCM.year_semester = '" + year_code + "' " : "") +
                            (sem_code != null && sem_code != "" ? " AND WSCM.semester_type = '" + sem_code + "' " : "") +
                            (department != null && department != "" ? " AND WSCM.inhabitation = '" + department + "' " : "") + @" 
                    ) T
                    GROUP BY course_code
                    ORDER BY MAX(course_name) ";
            }



            return Get_data(Qry);
        }

        public DataTable get_department_user_dtl_wise(string user_id, string sem_code, string year_code, string user_type)
        {
            String SqlSelect = "";

            SqlSelect = @"SELECT 
                              *
                          FROM department_mst
                          WHERE
                              dept_code IN
                              (
                                  select
                                      dept_code
                                  from @@deptTable
                                  where
                                      user_id = '" + user_id + @"' AND
                                      semester_type = '" + sem_code + @"' AND
                                      year_semester =  '" + year_code + @"' AND
                                      cancel_flag = 'N'
                              )";

            if (user_type == "D")
            {
                SqlSelect = SqlSelect.Replace("@@deptTable", "dean_dtl");
            }
            else { SqlSelect = SqlSelect.Replace("@@deptTable", "department_wise_user_dtl"); }
            return Get_data(SqlSelect);
        }

        public DataTable GetInstructorDataForWSCourse(string sem_code, string year_code, string course, string type)
        {
            String Qry = "";


            if (type == "Y")
            {
                Qry = @" SELECT *
                            INTO #rate_band_range
                            FROM rate_band_range;
                            UPDATE #rate_band_range
                            SET DegreeID = '4520'
                            WHERE DegreeID IS NULL; ";
                Qry += @"SELECT 
                    	*,	
                        ISNULL((
                        	SELECT TOP 1 
                        		ISNULL(hr_approved,'N') 
                        	FROM ws_instructor_workload_detail WSIWD WHERE 	 
                        		WSIWD.course_code = T.course_code AND
                        		WSIWD.semester_type = T.semester_type AND
                        		WSIWD.year_semester = T.year_semester AND
                        		cancel_flag='N'
                        	ORDER BY hr_approved
                        ),'N')  All_hr_approved
                    FROM
                    (
                    	SELECT 
                    		WSCM.course_code,
                    		WSCM.course_name,
                    		VF_code,
                    		WSCWI.contact_hrs Contact_Hrs,
                    		WSCWI.AdditionalHours additional_hours,
                    		WSCWI.TotalHours total_contact_hrs,
                    		designation,
                    		highest_qualification,
                    		(ISNULL(total_experiance,0)*12) + ISNULL(total_experiance_months,0) total_experiance,
                    		course_credits,  
                    		ISNULL(WSIWD.hr_approved,'N') hr_approved,
                            ISNULL(WSIWD.admin_approved,'N') admin_approved,
