            Qry += " DROP TABLE #rate_band_range ";
            return Get_data(Qry);
        }

        public Boolean SaveWSInstructorDetails(string ws_instructor_list, string user_id, string user_type)
        {
            try
            {
                string Host = HttpContext.Current.Request.UserHostName;
                // string strmsg = "[{\"weeks\":\"" + dr[0]["total_weeks"].ToString() + "\",\"contact_hrs\":\"" + dr[0]["total_contact_hrs"].ToString() + "\"}]";
                // DBConnection.Close();
                // HttpContext.Current.Request.UserHostName
                JavaScriptSerializer serializer = new JavaScriptSerializer();
                List<Dictionary<string, string>> InstructorData = new List<Dictionary<string, string>>();
                InstructorData = serializer.Deserialize<List<Dictionary<string, string>>>(ws_instructor_list);

                if (DBConnection.State == ConnectionState.Closed) DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                string Date = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                string Qry = "";
                bool SuccessOfTask = false;

                if (InstructorData != null)
                {
                    DataTable dt_rateband_dtl = new DataTable();
                    String message = "";
                    String DocNo = "";
                    for (int i = 0; i < InstructorData.Count; i++)
                    {
                        dt_rateband_dtl = get_ws_workload_dtl(InstructorData[i]["InstructorCode"].ToString(), InstructorData[i]["Semester"].ToString(), InstructorData[i]["YearCode"].ToString(), InstructorData[i]["Course"].ToString());
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "01", "WSI", user_id, Host, ref DocNo, ref message))
                        {
                            SuccessOfTask = false;
                            break;
                        }

                        Qry = @"UPDATE 
                                    ws_instructor_workload_detail 
                                SET 
                                    cancel_flag = 'Y',
                                    last_modified_by = '" + user_id + @"',
                                    last_modified_date = '" + Date + @"',
                                    last_modified_host = '" + Host + @"'
                                WHERE
                                   cancel_flag = 'N'
                                   AND instructor_code = '" + InstructorData[i]["InstructorCode"].ToString() + @"'
                                   AND course_code = '" + InstructorData[i]["Course"].ToString() + @"'
                                   AND semester_type = '" + InstructorData[i]["Semester"].ToString() + @"'
                                   AND year_semester = '" + InstructorData[i]["YearCode"].ToString() + @"'";
                        DBDataAdpterObject.SelectCommand.Parameters.Clear();
                        DBDataAdpterObject.SelectCommand.CommandText = Qry;
                        DBCommand.ExecuteNonQuery();
                        bool rateband_status = false;
                        if (dt_rateband_dtl != null)
                        {
                            rateband_status = true;

                        }
                        if (rateband_status)
                        {
                            if (InstructorData[i]["Type"].ToString() == "TA")
                            {
                                Qry = @"UPDATE 
                                        ws_course_proposal_TA
                                    SET 
                                        ContactHrs = '" + InstructorData[i]["ContactHours"].ToString() + @"',
                                        AdditionalHrs = '" + InstructorData[i]["AdditionalHours"].ToString() + @"',
                                        TotalHrs = '" + InstructorData[i]["TotalHours"].ToString() + @"',
                                        last_modified_by = '" + user_id + @"',
                                        last_modified_date = '" + Date + @"',
                                        last_modified_host = '" + Host + @"'
                                    WHERE  
                                       cancel_flag = 'N'
                                       AND instructor_code = '" + InstructorData[i]["InstructorCode"].ToString() + @"'
                                       AND course_code = 
                                       (";
                                if (InstructorData[i]["courseselecttype"].ToString() == "Y")
                                {
                                    Qry += @" SELECT 
                                                TOP 1 doc_no 
                                           FROM ws_course_mst 
                                           WHERE 
                                           	    course_code='" + InstructorData[i]["Course"].ToString() + @"' AND 
                                           	    year_semester='" + InstructorData[i]["YearCode"].ToString() + @"' AND
                                           	    semester_type = '" + InstructorData[i]["Semester"].ToString() + @"' ";
                                }
                                else
                                {
                                    Qry += @"    SELECT 
                                                TOP 1 course_code 
                                           FROM ws_course_proposal 
                                           WHERE 
                                                course_code='" + InstructorData[i]["Course"].ToString() + @"' AND 
                                                year_semester='" + InstructorData[i]["YearCode"].ToString() + @"' AND
                                                semester_type = '" + InstructorData[i]["Semester"].ToString() + @"'";
                                }


