        public Boolean SWSCancelCourse(string ws_instructor_list, string user_id, string sem_code, string year_code)
        {
            try
            {
                string semester_code = sem_code == "M" ? "W" : "S";
                string Host = HttpContext.Current.Request.UserHostName;
                JavaScriptSerializer serializer = new JavaScriptSerializer();
                List<Dictionary<string, string>> InstructorData = new List<Dictionary<string, string>>();
                InstructorData = serializer.Deserialize<List<Dictionary<string, string>>>(ws_instructor_list);

                DataTable dt_current_sem = Get_ws_cept_current_sem_data();
                semester_code = dt_current_sem.Rows[0]["sem_code"].ToString();
                year_code = dt_current_sem.Rows[0]["year_code"].ToString();
                DataTable dt_swsCreditCount = SWSCreditCalculation(user_id, dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString());
                DataTable WavierCredit = GetStudentWavierCreditdata(dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString(), user_id);


                if (DBConnection.State == ConnectionState.Closed) DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                string Date = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                string Qry = "";
                bool SuccessOfTask = false;
                int totalcredit = 0;

                if (InstructorData != null)
                {


                    for (int i = 0; i < InstructorData.Count; i++)
                    {
                        if (InstructorData[i]["cancel_flag"].ToString() == "Y")
                        {
                            Qry += @"UPDATE 
                                    ws_connect_student_reg_dtl 
                                SET 
                                    course_drop_status = 'Y',
                                    last_modified_by = '" + user_id + @"',
                                    last_modified_date = '" + Date + @"',
                                    last_modified_host = '" + Host + @"'
                                WHERE
                                   cancel_flag = 'N' AND status ='P'
                                   AND user_id = '" + user_id + @"'
                                   AND course_code = '" + InstructorData[i]["course_code"].ToString() + @"'
                                   AND semester_type = '" + semester_code + @"'
                                   AND year_semester = '" + year_code + @"'";

                            totalcredit = totalcredit + Convert.ToInt32(InstructorData[i]["credits"].ToString());


                        }
                    }

                    if (dt_swsCreditCount != null)
                    {
                        Qry += " update ws_SWSCreditCalculation set cancel_flag='Y',last_modified_by='" + user_id + @"',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + Host + "' where UserID='" + user_id + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";

                        int ProvisionallyAllocatedCredits = Convert.ToInt32(dt_swsCreditCount.Rows[0]["ProvisionallyAllocatedCredits"].ToString());
                        int ProvisionallyAllocatedCreditsRemaning = 0;
                        if (ProvisionallyAllocatedCredits > totalcredit)
                        {
                            ProvisionallyAllocatedCreditsRemaning = ProvisionallyAllocatedCredits - totalcredit;
                        }
                        else { ProvisionallyAllocatedCreditsRemaning = totalcredit - ProvisionallyAllocatedCredits; }



                        int DropCourseCredit = Convert.ToInt32(dt_swsCreditCount.Rows[0]["DropCredits"].ToString());
                        //int DropCourseCreditAdd = DropCourseCredit + totalcredit;
                        //changes by nitinbhai 03102024
                        int DropCourseCreditAdd = totalcredit;

                        int TotalRemainingCredits = Convert.ToInt32(dt_swsCreditCount.Rows[0]["TotalRemainingCredits"].ToString());
                        int TotalRemainingCreditsRemaning = 0;
                        if (TotalRemainingCredits > totalcredit)
                        {
                            TotalRemainingCreditsRemaning = TotalRemainingCredits + totalcredit;
                        }
                        else { TotalRemainingCreditsRemaning = totalcredit + TotalRemainingCredits; }


                        Qry += " INSERT INTO ws_SWSCreditCalculation (SrNo, UserID, TotalAppliedCredit, WaiverCredit, PaidFeesCredit, ProvisionallyAllocatedCredits, DropCredits, " +
                               " TotalRemainingCredits, RegisteredCredits, RequiredToPay, semester_type, year_semester, cancel_flag,created_by, created_date, created_host) " +
                               " VALUES (" +
                                 FormatValue(dt_swsCreditCount.Rows[0]["SrNo"]) + "," +
                                 FormatValue(user_id) + "," +
                                 FormatValue(dt_swsCreditCount.Rows[0]["TotalAppliedCredit"]) + "," +
                                 FormatValue(dt_swsCreditCount.Rows[0]["WaiverCredit"]) + "," +
                                 FormatValue(dt_swsCreditCount.Rows[0]["PaidFeesCredit"]) + "," +
                                 FormatValue(ProvisionallyAllocatedCreditsRemaning) + "," +
                                 FormatValue(DropCourseCreditAdd) + "," +
                                 FormatValue(TotalRemainingCreditsRemaning) + "," +
                                 FormatValue(dt_swsCreditCount.Rows[0]["RegisteredCredits"]) + "," +
                                 FormatValue(dt_swsCreditCount.Rows[0]["RequiredToPay"]) + "," +
                                 FormatValue(dt_current_sem.Rows[0]["sem_code"].ToString()) + "," +
                                 FormatValue(dt_current_sem.Rows[0]["year_code"].ToString()) + ",'N'," +
                                 FormatValue(user_id) + "," +
                                 FormatValue(Date) + "," +
                                 FormatValue(Host) +
                                 ")";
                    }


                    DBDataAdpterObject.SelectCommand.Parameters.Clear();
                    DBDataAdpterObject.SelectCommand.CommandText = Qry;
                    if (DBCommand.ExecuteNonQuery() > 0)
                    {
                        SuccessOfTask = true;
                    }
                    else
                    {
                        SuccessOfTask = false;

                    }
                }
                else
                    SuccessOfTask = false;

                if (SuccessOfTask)
                    DBCommand.Transaction.Commit();
                else
                    DBCommand.Transaction.Rollback();

                return SuccessOfTask;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                return false;
            }
            finally
            {
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
            }

            //return false;
        }

        string FormatValue(object value)
        {
            return value == null || string.IsNullOrEmpty(value.ToString()) ? "NULL" : "'" + value.ToString() + "'";
        }
