        public DataTable Get_Course_Wise_Student_dtl(string semester_type, string year_semester, string course_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select 
							STUFF((select ', '+ ISNULL(im.title, CASE WHEN im.gender = 'M' THEN 'Mr.' WHEN im.gender = 'F' THEN 'Ms.' END) + im.instructor_name from ws_course_wise_instructor as cwi
	                            inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'
	                            where cwi.course_code=t1.course_code and cwi.cancel_flag='N'
	                            and cwi.semester_type=t1.semester_type and cwi.year_semester=t1.year_semester
	                            FOR XML PATH(''),TYPE
                            ).value('.','NVARCHAR(MAX)'),1,2,'')instructors,

							STUFF((select ', '+ ISNULL(im.title, CASE WHEN im.gender = 'M' THEN 'Mr.' WHEN im.gender = 'F' THEN 'Ms.' END) + im.instructor_name from ws_course_wise_TA as cwi
	                            inner join instructor_mst as im on im.instructor_code=cwi.instructor_code and im.cancel_flag='N'
	                            where cwi.course_code=t1.course_code and cwi.cancel_flag='N'
	                            and cwi.semester_type=t1.semester_type and cwi.year_semester=t1.year_semester
	                            FOR XML PATH(''),TYPE
                            ).value('.','NVARCHAR(MAX)'),1,2,'')TAinstructors,dm.dept_name as student_dept_name ,pm.prog_name as student_prog_name,FORMAT( t1.TravelStartDate,'dd-MM-yyyy') TravelStartDate,FORMAT(t1.TravelEndDate,'dd-MM-yyyy') TravelEndDate,t1. * from ( 
							select wsca.user_id,ISNULL(um.full_name, um.first_name) full_name,visa_file_name='false',FORMAT(cm.start_date,'dd-MMM-yyyy') as start_date_new,FORMAT(cm.end_date,'dd-MMM-yyyy') as end_date_new,um.gender,
                            um.user_type,um.prog_desc as student_prog_code,um.dept_code as student_dept_code,um.name_as_passport,um.passport_no as student_passport_no,um.country as student_country,um.nationality as student_nationality, cm.* from ws_student_course_allocate_dtl wsca
							inner join ws_course_mst cm on cm.course_code = wsca.course_code and cm.semester_type=wsca.semester_type and cm.year_semester = wsca.year_semester
							and cm.cancel_flag='N'
							inner join user_mst um on um.user_id = wsca.user_id  ";
            SqlSelect += " where wsca.semester_type='" + semester_type + "' and wsca.year_semester='" + year_semester + "' and wsca.cancel_flag='N' and wsca.course_code='" + course_code + "') t1" +
                " left join department_mst dm on dm.dept_code = t1.student_dept_code " +
                " left join programme_mst pm on pm.prog_code = t1.student_prog_code ";
            return Get_data(SqlSelect);

        }


