                DataTable user_dtl = sws_get_all_ws_course_proposal_instructor_data(sem_code, year_code, course_code);
                Mail mail = new Mail();
                bool mail_status = mail.SWSCourseApprovedMail(user_dtl.Rows[0]["mail"].ToString(), mail_from_id_password, AckDetails, user_dtl);


                return mail_status;
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return false;
            }
        }
        public DataTable sws_get_all_ws_course_proposal_instructor_data(string sem_code, string year_code, string course_code)
        {
            String SqlSelect = "";

            //SqlSelect = "SELECT * FROM ws_course_proposal_instructor " +
            //            " where semester_type = '" + sem_code + "' and year_semester = '" + year_code + "'";

            SqlSelect = @"SELECT ws_course_proposal_instructor.*,wcp.*,instructor_mst.instructor_name,um.mail FROM ws_course_proposal_instructor  
                            left join instructor_mst on instructor_mst.instructor_code=ws_course_proposal_instructor.instructor_code
                            left join ws_course_proposal wcp on wcp.course_code = ws_course_proposal_instructor.course_code 
                            left join user_mst um on um.user_id = ws_course_proposal_instructor.instructor_code
                            where ws_course_proposal_instructor.semester_type = '" + sem_code + "' and ws_course_proposal_instructor.year_semester = '" + year_code + "' " +
                            " and  ws_course_proposal_instructor.course_code = '" + course_code + "' and ws_course_proposal_instructor.cancel_flag ='N'";

            return Get_data(SqlSelect);
        }


        public DataTable ws_publish_letter_genrate_course_dtl(string sem_code, string year_code, string user_typ, string user_id)
        {
            String SqlSelect = "";
            SqlSelect = @" Select STUFF((select ', '+cwi.course_code  from ws_instructor_workload_detail as cwi
                           where cwi.instructor_code=t1.instructor_code and cwi.cancel_flag='N'
                           and cwi.semester_type=t1.semester_type and cwi.year_semester=t1.year_semester ";

            SqlSelect += @" FOR XML PATH(''),TYPE ).value('.','NVARCHAR(MAX)'),1,2,'')course_code,t1.* from 
                           (select wiwd.instructor_code,im.instructor_name,im.VF_code,MAX(im.designation) des_type,MAX(wiwd.semester_type) semester_type,MAX(wiwd.year_semester) year_semester,
                            MAX(im.mail) mail ,MAX(Case When gender = 'M' Then 'Mr.' when gender ='F' Then 'Ms.' End) as tilte,MAX(wiwd.uso_hr_approved) as uso_hr_approved
                           from ws_instructor_workload_detail wiwd
                           inner join instructor_mst as im on im.instructor_code=wiwd.instructor_code and im.cancel_flag='N'
                           inner join ws_course_mst wcm on wcm.course_code = wiwd.course_code
                           and wcm.semester_type = wiwd.semester_type and wcm.year_semester= wiwd.year_semester and wcm.cancel_flag='N'";

            SqlSelect += " Where wiwd.semester_type ='" + sem_code + "' and wiwd.year_semester='" + year_code + "' and wiwd.cancel_flag ='N' and wiwd.admin_approved='Y' and wiwd.hr_approved='Y'";
            if (user_typ == "FA")
            {
                SqlSelect += " and wcm.dept_code in (select distinct dept_code from department_wise_user_dtl where  semester_type='" + sem_code + "' and year_semester='" + year_code + "' and user_id='" + user_id + "' and cancel_flag ='N')";
            }
            SqlSelect += " Group by wiwd.instructor_code,im.instructor_name,im.VF_code) t1 ";
            return Get_data(SqlSelect);
        }


