            SqlSelect = @"  Select ws_instructor_workload_detail.instructor_code,instructor_mst.title,instructor_mst.instructor_name,
                            instructor_mst.designation,instructor_mst.designation_letter, instructor_mst.rate_wise_designation, ws_instructor_workload_detail.total_weeks,  
                            ws_instructor_workload_detail.total_contact_hrs, ws_instructor_workload_detail.total_preparation_hrs,  ws_instructor_workload_detail.total_hrs,  
                            ws_instructor_workload_detail.total_hrs_in_semester,instructor_mst.total_experiance, instructor_mst.highest_qualification,
                            (case ISNULL(ws_instructor_workload_detail.rate_band,'') when '' then ws_instructor_workload_detail.rate_band else ws_instructor_workload_detail.rate_band end )rate_band, 
                            instructor_mst.address,ws_instructor_workload_detail.justification, ws_course_mst.course_code,ws_course_mst.course_name,ws_course_mst.course_credits, 
                            ws_course_mst.dept_code,department_mst.dept_name,prog_code = NULL,prog_name = NULL,
                            course_typology = NULL,type_name = NULL,prep_hr_per_week = NULL,prog_level_code = NULL, 
                            prog_level_desc = NULL,ws_instructor_workload_detail.is_tutorial,ws_instructor_workload_detail.hours_bifurcation,ws_instructor_workload_detail.additional_hours,
                            ws_course_mst.category_location_wise,Format (ws_course_mst.start_date,'dd-MMM-yyyy')start_date,Format (ws_course_mst.end_date,'dd-MMM-yyyy')end_date,instructor_mst.country,ws_instructor_workload_detail.Contact_Hrs
                            from ws_instructor_workload_detail 
                            inner join ws_course_mst on ws_course_mst.course_code = ws_instructor_workload_detail.course_code
                            inner join instructor_mst on instructor_mst.instructor_code = ws_instructor_workload_detail.instructor_code 
                            left join department_mst on department_mst.dept_code = ws_course_mst.dept_code ";
            SqlSelect += " where ws_instructor_workload_detail.semester_type = '" + sem_code + "' and ws_instructor_workload_detail.year_semester = '" + year_code + "'" +
                         " and ws_instructor_workload_detail.instructor_code = '" + instructor_code + "' and ws_course_mst.semester_type = '" + sem_code + "' and ws_course_mst.year_semester = '" + year_code + "' " +
