        public DataTable Get_ws_authorization_report(string sem_code, string year_code, string dept_code, string authtype)
        {


            String SqlSelect = "";
            SqlSelect = " select wci.course_code,ISNULL(wiw.admin_approved,'N') as inst_admin_approved,ISNULL(wiw.hr_approved,'N') as inst_dean_approved,ISNULL(wiw.uso_hr_approved,'N') as inst_uso_hr_approved,im.*, " +
                " CAST(ISNULL(im.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(im.total_experiance_months,'') as INT) as total_experiance_months,coursestatus ='Published',wcm.inhabitation,dm.dept_name,cm.name as countryname, " +
                " wiw.* from ws_course_wise_instructor wci " +
                " left join instructor_mst im on im.instructor_code = wci.instructor_code " +
                " inner join ws_course_mst wcm on wcm.course_code = wci.course_code and wcm.semester_type = wci.semester_type and wcm.year_semester = wci.year_semester and wcm.cancel_flag='N' " +
                " left join ws_instructor_workload_detail wiw on  wiw.course_code = wci.course_code and wiw.semester_type= wci.semester_type and wiw.year_semester= wci.year_semester and wiw.instructor_code = wci.instructor_code " +
                " and wiw.cancel_flag = 'N'  left join department_mst dm on dm.dept_code = wcm.inhabitation  left join country_mst cm on cm.id = im.indian_citizen " +
                " where wci.semester_type='" + sem_code + "'  and wci.year_semester='" + year_code + "'  and wci.cancel_flag='N' ";
            if (dept_code != "")
            {
                SqlSelect += " and wcm.dept_code='" + dept_code + "'";
            }
            string temp_str = SqlSelect;
            SqlSelect = SqlSelect + " UNION " + temp_str.Replace("ws_course_wise_instructor", "ws_course_wise_TA");

            SqlSelect += @"  UNION 
   
                                    Select wci.course_code,ISNULL(wiw.admin_approved,'N') as inst_admin_approved,ISNULL(wiw.hr_approved,'N') as inst_dean_approved,ISNULL(wiw.uso_hr_approved,'N') as inst_uso_hr_approved,im.*,  
                                    CAST(ISNULL(im.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(im.total_experiance_months,'') as INT) as total_experiance_months,coursestatus ='Proposed',wcm.inhabitation,dm.dept_name,cm.name as countryname,  wiw.* 
                                    from ws_course_proposal_instructor wci  
                                    left join instructor_mst im on im.instructor_code = wci.instructor_code  
                                    inner join ws_course_proposal wcm on wcm.course_code = wci.course_code and wcm.semester_type = wci.semester_type 
                                    and wcm.year_semester = wci.year_semester and wcm.cancel_flag='N'  
                                    left join ws_instructor_workload_detail wiw on wiw.course_code = wci.course_code and wiw.semester_type= wci.semester_type 
                                    and wiw.year_semester= wci.year_semester and wiw.instructor_code = wci.instructor_code  and wiw.cancel_flag = 'N'
                                    left join department_mst dm on dm.dept_code = wcm.inhabitation
                                    left join country_mst cm on cm.id = im.indian_citizen
                                    where wci.semester_type='" + sem_code + @"'  and wci.year_semester='" + year_code + @"'  and wci.cancel_flag='N' ";
            if (dept_code != "")
            {
                SqlSelect += " and wcm.inhabitation ='" + dept_code + "'";
            }
            if (authtype == "R")
            {
                SqlSelect += " And wcm.instructor_approved='Y' And wcm.dean_approved='A'";
            }

            SqlSelect += @"       UNION  
                                    
                                    Select wci.course_code,ISNULL(wiw.admin_approved,'N') as inst_admin_approved,ISNULL(wiw.hr_approved,'N') as inst_dean_approved,ISNULL(wiw.uso_hr_approved,'N') as inst_uso_hr_approved,im.*,  
                                    CAST(ISNULL(im.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(im.total_experiance_months,'') as INT) as total_experiance_months,coursestatus ='Proposed',wcm.inhabitation,dm.dept_name,cm.name as countryname,  wiw.* 
                                    from ws_course_proposal_TA wci  
                                    left join instructor_mst im on im.instructor_code = wci.instructor_code  
                                    inner join ws_course_proposal wcm on wcm.course_code = wci.course_code and wcm.semester_type = wci.semester_type
                                    and wcm.year_semester = wci.year_semester and wcm.cancel_flag='N'  
                                    left join ws_instructor_workload_detail wiw on wiw.course_code = wci.course_code and wiw.semester_type= wci.semester_type 
                                    and wiw.year_semester= wci.year_semester and wiw.instructor_code = wci.instructor_code  and wiw.cancel_flag = 'N'  
                                    left join department_mst dm on dm.dept_code = wcm.inhabitation
                                    left join country_mst cm on cm.id = im.indian_citizen
                                    where wci.semester_type='" + sem_code + @"'  and wci.year_semester='" + year_code + @"'  And wci.cancel_flag='N'  ";
            if (dept_code != "")
            {
                SqlSelect += " and wcm.inhabitation ='" + dept_code + "'";
            }
            if (authtype == "R")
            {
                SqlSelect += " And wcm.instructor_approved='Y' And wcm.dean_approved='A'";
            }
            SqlSelect += " order by wci.course_code asc ";

            return Get_data(SqlSelect);
        }


        public DataTable Get_Course_Wise_instructor_dtl(string semester_type, string year_semester, string course_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select im.instructor_name,im.instructor_code,im.passport_no,im.country,cm.course_code,cm.course_name,cm.course_desc,cm.category_location_wise,cm.location,cm.dept_code,visa_file_name='false',FORMAT(cm.start_date,'dd-MMM-yyyy') start_date_new ,FORMAT(cm.end_date,'dd-MMM-yyyy') end_date_new,im.gender,im.designation,im.title 
                            ,FORMAT( cm.TravelStartDate,'dd-MM-yyyy') TravelStartDate,FORMAT(cm.TravelEndDate,'dd-MM-yyyy') TravelEndDate from ws_course_wise_instructor as wcw 
