        public DataTable Get_student_course_allocated_count(string semester_type, string year_semester, string user_id)
        {
            String SqlSelect = "";
            string ws_semester_type = "";
            if (semester_type == "M")
            {
                ws_semester_type = "W";
            }
            else { ws_semester_type = "S"; }

            SqlSelect = @" select t1.user_id,sum(cast(t1.Total_credits as int)) Total_credits from ( select user_id, sum(cast(credits as int)) Total_credits from student_course_allocate_dtl
						where semester_type ='" + semester_type + "' and year_semester='" + year_semester + "' and cancel_flag='N' and user_id='" + user_id + "' Group By user_id ";

            SqlSelect += @" Union select user_id, sum(cast(credits as int)) Total_credits from WS_student_course_allocate_dtl
						where semester_type ='" + ws_semester_type + "' and year_semester='" + year_semester + "' and cancel_flag='N' and user_id='" + user_id + "' Group By user_id ) as t1 Group By t1.user_id ";
            return Get_data(SqlSelect);

        }


        public Dictionary<string, string> after_publish_course_data_save(string course_code, DataTable publish_course_data, string semester_type, string year_semester, string user_id)
        {
            String SqlSelect = "";
            int res = 0, res_update = 0, res_course_mst = 0, res_temp = 0;
            Dictionary<string, string> dic_response = new Dictionary<string, string>();
            SqlSelect += " delete from ws_course_mst " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and course_code in (select ws_course_code from ws_course_proposal where course_code in ('" + course_code + "')) ";

            SqlSelect += " delete from ws_course_wise_instructor " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and course_code in (select ws_course_code from ws_course_proposal where course_code in ('" + course_code + "')) ";

            SqlSelect += " delete from ws_course_wise_workplan " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and course_code in (select ws_course_code from ws_course_proposal where course_code in ('" + course_code + "')) ";

            SqlSelect += " delete from ws_course_wise_TA " +
                        " where semester_type='" + semester_type + "' and year_semester='" + year_semester + "'" +
                        " and course_code in (select ws_course_code from ws_course_proposal where course_code in ('" + course_code + "')) ";

            DBCommand.CommandText = SqlSelect;
            DBCommand.CommandType = CommandType.Text;

            try
            {
                DBConnection.Open();
                res_update = DBCommand.ExecuteNonQuery();

                if (res_update > 0)
                {
                    DBCommand.CommandText = "";
                    SqlSelect = "";

                    // ======== Course Mst ========

                    SqlSelect = @" insert into ws_course_mst(doc_no ,course_code ,course_desc ,category_location_wise ,location ,course_outline ,total_instructors_involved 
                                      ,prerequisite ,is_open_for_professional ,prerequisite_for_prof ,course_name ,course_credits ,start_date ,end_date ,dept_code ,fees 
