                                select course_code ,ws_course_code ,course_desc ,category_location_wise ,location ,course_outline ,total_instructors_involved ,prerequisite 
                                      ,is_open_for_professional ,prerequisite_for_prof ,course_name ,course_credits ,start_date ,end_date ,inhabitation ,fees ,prof_fees ,prof_course 
                                      ,round ,course_type ,course_output1 ,course_output2 ,occurrence_week ,image_name ,image_source ,inhabitation ,methodology ,material_cost ,food_stay 
                                      ,local_travel ,approx_expense ,travel_expense ,total_expense ,material_for_workshop ,outside_service_rent ,travel_arrangement_needed 
                                      ,travel_arrangement_needed_from ,travel_arrangement_needed_to ,based_in_ahmedabad ,is_travel_based_course ,is_travel_based_course_from 
