                        from ws_course_proposal_instructor
                        inner join ws_course_proposal on ws_course_proposal.course_code=ws_course_proposal_instructor.course_code" +
                        " where ws_course_proposal_instructor.semester_type='" + semester_type + "' and ws_course_proposal_instructor.year_semester='" + year_semester + "'" +
                        " and ws_course_proposal_instructor.course_code in ('" + course_code + "') and ws_course_proposal.is_publish='Y' and ws_course_proposal.cancel_flag='Y'";

                        DBCommand.CommandText = SqlSelect;
                        DBCommand.CommandType = CommandType.Text;

                        res_temp = DBCommand.ExecuteNonQuery();
                    }

                    if (res_course_mst > 0)
                    {
                        DBCommand.CommandText = "";
                        SqlSelect = "";

                        // ======== Course Wise TA ========

                        SqlSelect = @"INSERT INTO ws_course_wise_TA
                                      (
                                            course_code
                                            ,instructor_code
                                            ,semester_type
                                            ,year_semester
                                            ,cancel_flag
                                            ,created_by
                                            ,created_date
                                            ,created_host
                                            ,last_modified_by
                                            ,last_modified_date
                                            ,last_modified_host
                                            ,ContactHrs
                                            ,AdditionalHrs
                                            ,TotalHrs
                                            ,instructor_type
                                      )
                                      SELECT 
                                      	    ws_course_proposal.ws_course_code
                                      	    ,ws_course_proposal_TA.instructor_code
                                      	    ,ws_course_proposal_TA.semester_type
                                      	    ,ws_course_proposal_TA.year_semester
                                      	    ,ws_course_proposal_TA.cancel_flag
                                      	    ,ws_course_proposal_TA.created_by
                                      	    ,ws_course_proposal_TA.created_date
                                      	    ,ws_course_proposal_TA.created_host
                                      	    ,ws_course_proposal_TA.last_modified_by
                                      	    ,ws_course_proposal_TA.last_modified_date
                                      	    ,ws_course_proposal_TA.last_modified_host
                                      	    ,ws_course_proposal_TA.ContactHrs
                                      	    ,ws_course_proposal_TA.AdditionalHrs
                                      	    ,ws_course_proposal_TA.TotalHrs
                                      	    ,ws_course_proposal_TA.instructor_type
                                      FROM ws_course_proposal_TA
                                      INNER JOIN ws_course_proposal ON ws_course_proposal.course_code=ws_course_proposal_TA.course_code
                                      WHERE
                                      	    ws_course_proposal_TA.semester_type = '" + semester_type + @"'
                                            AND ws_course_proposal_TA.year_semester = '" + year_semester + @"'
                                            AND ws_course_proposal_TA.course_code IN('" + course_code + @"')
                                            AND ws_course_proposal.is_publish = 'Y' 
                                            AND ws_course_proposal.cancel_flag = 'Y'";

                        DBCommand.CommandText = SqlSelect;
                        DBCommand.CommandType = CommandType.Text;
                        res_temp = DBCommand.ExecuteNonQuery();
                    }

                    if (res_course_mst > 0)
                    {
                        DBCommand.CommandText = "";
                        SqlSelect = "";

                        //// ======== Course Wise Workplan ========

                        SqlSelect = @"insert into ws_course_wise_workplan(doc_no ,course_code ,workplan_date ,from_date ,to_date ,from_time ,year_code ,To_time ,topic_covered 
                                      ,methodology ,no_of_hrs ,faculty_involve ,day_code ,cancel_flag ,city_name ,semester_type ,year_semester ,created_by ,created_date 
                                      ,created_host ,last_modified_by ,last_modified_date ,last_modified_host )  
                                select ws_course_proposal_workplan.course_code ,ws_course_proposal.ws_course_code ,ws_course_proposal_workplan.workplan_date 
                                      ,ws_course_proposal_workplan.from_date ,ws_course_proposal_workplan.to_date ,ws_course_proposal_workplan.from_time 
                                      ,ws_course_proposal_workplan.year_code ,ws_course_proposal_workplan.To_time ,ws_course_proposal_workplan.topic_covered 
                                      ,ws_course_proposal_workplan.methodology ,ws_course_proposal_workplan.no_of_hrs ,ws_course_proposal_workplan.faculty_involve 
                                      ,ws_course_proposal_workplan.day_code ,ws_course_proposal_workplan.cancel_flag ,ws_course_proposal_workplan.city_name 
                                      ,ws_course_proposal_workplan.semester_type ,ws_course_proposal_workplan.year_semester ,ws_course_proposal_workplan.created_by 
                                      ,ws_course_proposal_workplan.created_date ,ws_course_proposal_workplan.created_host ,ws_course_proposal_workplan.last_modified_by 
                                      ,ws_course_proposal_workplan.last_modified_date ,ws_course_proposal_workplan.last_modified_host   
                                from ws_course_proposal_workplan
                                inner join ws_course_proposal on ws_course_proposal.course_code=ws_course_proposal_workplan.course_code" +
                        " where ws_course_proposal_workplan.semester_type='" + semester_type + "' and ws_course_proposal_workplan.year_semester='" + year_semester + "'" +
                        " and ws_course_proposal_workplan.course_code in ('" + course_code + "') and ws_course_proposal.is_publish='Y' and ws_course_proposal.cancel_flag='Y'";

                        DBCommand.CommandText = SqlSelect;
                        DBCommand.CommandType = CommandType.Text;

                        res_temp = DBCommand.ExecuteNonQuery();
                    }

                    res = res_temp;
                }
            }
            catch (Exception ex)
            {
                dic_response["status"] = "False";
                dic_response["message"] = ex.ToString();
            }

            DBConnection.Close();

            if (res > 0)
            {
                dic_response["status"] = "True";
                dic_response["message"] = "All Courses are Published Successfully";
            }
            else
            {
                dic_response["status"] = "False";
                dic_response["message"] = "There are some problems in publishing courses , No Courses are Published";
            }

            return dic_response;
        }


