        public Boolean WS_Acceptance_Details_Update(ArrayList arrayList, string user_id, string host_name, string sem_code, string year_code)
        {
            /*************************/
            /* ESTABLISH CONNECTION */

            /*************************/
            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            for (int i = 0; i < arrayList.Count; i++)
            {
                Dictionary<string, object> dic_instructor_data = (Dictionary<string, object>)arrayList[i];
                SqlSelect += " Update ws_instructor_workload_detail set acceptance ='" + dic_instructor_data["acceptance"].ToString() + "',acceptance_type ='" + dic_instructor_data["acceptance_type"].ToString() + "',acceptance_justification='" + dic_instructor_data["acceptance_justification"].ToString() + "' ";

                DateTime acceptance_date = new DateTime();
                if (DateTime.TryParse(dic_instructor_data["acceptance_date"].ToString(), out acceptance_date))
                {
                    SqlSelect += " ,acceptance_date ='" + acceptance_date + "' ";

                }
                else
                {
                    SqlSelect += " ,acceptance_date = null ";
                }
                SqlSelect += " ,last_modified_by ='" + user_id + "',last_modified_date ='" + DateTime.Now + "',last_modified_host ='" + host_name + "' ";

                SqlSelect += " where cancel_flag='N' and course_code ='" + dic_instructor_data["course_code"].ToString() + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and instructor_code='" + dic_instructor_data["instructor_code"].ToString() + "'  ";

            }

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();

                return true;
            }
            catch (Exception)
            {

                return false;
            }
        }


        public Boolean Ws_changeCourseCodeWorkLoad(string changed_course_detail, string user_id, string host_name, string sem_code, string year_code)
        {

            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> Course_Master_data = ser.Deserialize<List<Dictionary<string, object>>>(changed_course_detail);
            /*************************/
            /* ESTABLISH CONNECTION */

            /*************************/
            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            for (int i = 0; i < Course_Master_data.Count; i++)
            {
                SqlSelect += " Update ws_instructor_workload_detail set ws_course_code ='" + Course_Master_data[i]["ws_course_code"].ToString() + "' ";
                SqlSelect += " ,last_modified_by ='" + user_id + "',last_modified_date ='" + DateTime.Now + "',last_modified_host ='" + host_name + "' ";
                SqlSelect += " where cancel_flag='N' and course_code ='" + Course_Master_data[i]["course_code"].ToString() + "' ";

                SqlSelect += @" UPDATE ws_course_budget_instructor_details
                                SET ws_course_code     = '" + Course_Master_data[i]["ws_course_code"].ToString() + @"',
                                    last_modified_by   = '" + user_id + @"',
                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                    last_modified_host = '" + host_name + @"'
                                WHERE course_code = '" + Course_Master_data[i]["course_code"].ToString() + @"'
                                  AND cancel_flag = 'N';
                                
                                UPDATE ws_course_budget_Travel_details
                                SET ws_course_code     = '" + Course_Master_data[i]["ws_course_code"].ToString() + @"',
                                    last_modified_by   = '" + user_id + @"',
                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                    last_modified_host = '" + host_name + @"'
                                WHERE course_code = '" + Course_Master_data[i]["course_code"].ToString() + @"'
                                  AND cancel_flag = 'N';
                                
                                UPDATE ws_course_budget_AnyOther_details
                                SET ws_course_code     = '" + Course_Master_data[i]["ws_course_code"].ToString() + @"',
                                    last_modified_by   = '" + user_id + @"',
                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                    last_modified_host = '" + host_name + @"'
                                WHERE course_code = '" + Course_Master_data[i]["course_code"].ToString() + @"'
                                  AND cancel_flag = 'N';
                                
                                UPDATE ws_course_budget_Expenses_details
                                SET ws_course_code     = '" + Course_Master_data[i]["ws_course_code"].ToString() + @"',
                                    last_modified_by   = '" + user_id + @"',
                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                    last_modified_host = '" + host_name + @"'
                                WHERE course_code = '" + Course_Master_data[i]["course_code"].ToString() + @"'
                                  AND cancel_flag = 'N';
                                
                                UPDATE ws_course_budget_parameter_details
                                SET ws_course_code     = '" + Course_Master_data[i]["ws_course_code"].ToString() + @"',
                                    last_modified_by   = '" + user_id + @"',
                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                    last_modified_host = '" + host_name + @"'
                                WHERE course_code = '" + Course_Master_data[i]["course_code"].ToString() + @"'
                                  AND cancel_flag = 'N';
                                
                                UPDATE ws_course_budget_master_details
                                SET ws_course_code     = '" + Course_Master_data[i]["ws_course_code"].ToString() + @"',
                                    last_modified_by   = '" + user_id + @"',
                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                    last_modified_host = '" + host_name + @"'
                                WHERE course_code = '" + Course_Master_data[i]["course_code"].ToString() + @"'
                                  AND cancel_flag = 'N'";

            }

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();

                return true;
            }
            catch (Exception ex)
            {

                return false;
            }
        }


