        public DataTable WS_get_VF_Finance_Report_data(string sem_code, string year_code, string dept_code, string prog_code)
        {
            String SqlSelect = "";
            //ISNULL(instructor_workload_detail.additional_hours,0) as additional_hours 
            SqlSelect = @"select ws_course_wise_instructor.course_code,instructor_mst.*,
                            (case ISNULL(instructor_workload_detail.rate_band,'') 
	                            when '' then instructor_workload_detail.rate_band
	                            else instructor_workload_detail.rate_band end)final_rate_band,                 
                            instructor_workload_detail.total_contact_hrs,instructor_workload_detail.total_hrs,
                            instructor_workload_detail.total_hrs_in_semester,instructor_workload_detail.total_preparation_hrs,
                            instructor_workload_detail.total_weeks,instructor_mst.justification,
                            instructor_workload_detail.hr_approved,(instructor_mst.admin_approved)personal_dtl_approved,
                            instructor_mst.rateband_approved,(instructor_workload_detail.admin_approved)workload_approved,
                            instructor_workload_detail.acceptance,instructor_workload_detail.acceptance_type,instructor_workload_detail.acceptance_justification,
                            instructor_workload_detail.acceptance_date,dept_name ='',
                            instructor_workload_detail.is_tutorial,
                            
                            (CASE WHEN instructor_workload_detail.additional_hours IS NOT NULL THEN instructor_workload_detail.additional_hours
                            WHEN instructor_workload_detail.additional_hours IS NULL THEN 0 END) AS additional_hours,instructor_workload_detail.Contact_Hrs,instructor_workload_detail.total_contact_hrs
                            from ws_course_wise_instructor
                            inner join instructor_mst on instructor_mst.instructor_code=ws_course_wise_instructor.instructor_code
                            inner join ws_instructor_workload_detail as instructor_workload_detail on instructor_workload_detail.instructor_code=ws_course_wise_instructor.instructor_code
                                    and instructor_workload_detail.course_code=ws_course_wise_instructor.course_code
                                    and instructor_workload_detail.semester_type=ws_course_wise_instructor.semester_type 
                                    and instructor_workload_detail.year_semester=ws_course_wise_instructor.year_semester 
                                    and instructor_workload_detail.cancel_flag='N'
                            inner join ws_course_mst cm on cm.course_code = ws_course_wise_instructor.course_code and cm.semester_type = ws_course_wise_instructor.semester_type
                            and cm.year_semester = ws_course_wise_instructor.year_semester ";

            SqlSelect = SqlSelect + " where ws_course_wise_instructor.cancel_flag='N' and instructor_mst.cancel_flag='N' and instructor_workload_detail.acceptance='Y' " +
                " and ws_course_wise_instructor.semester_type='" + sem_code + "' and ws_course_wise_instructor.year_semester='" + year_code + "'  ";
            if (Convert.ToInt32(year_code) >= 2023)
            {
                SqlSelect = SqlSelect + " and instructor_workload_detail.uso_hr_approved='Y'";
            }
            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and cm.dept_code = '" + dept_code + "'";
            }



            string temp_str = SqlSelect;

            SqlSelect = SqlSelect + " union " + temp_str.Replace("ws_course_wise_instructor", "ws_course_wise_TA");

            SqlSelect = SqlSelect + " order by instructor_code";

            return Get_data(SqlSelect);
        }

        #region SWS Attendance Details
        public DataTable SWS_course_wise_session_submit_list(string user_id, string user_type, string sem_code, string year_code, string user_prog_code, string prog_code, string prog_level_code, string dept_code)
        {
            String SqlSelect = "";

            if (user_type == "I2" || user_type == "PC" || user_type == "D")
            {
                SqlSelect = " select res3.*, " +
                            " (case ws_grade_submit_detail.faculty_approved when 'Y' then 'Approved' else '' end) as 'faculty_approval', " +
                            " (case ws_grade_submit_detail.progcoordinate_approved when 'Y' then 'Approved' else '' end) as 'progcoordinate_approval', " +
                            " (case ws_grade_submit_detail.ugpgoffice_approved when 'Y' then 'Approved' else '' end) as 'ugpg_approval', " +
                            " (case ws_grade_submit_detail.dean_approved when 'Y' then 'Approved' else '' end) as 'dean_approval'," +
                            " (case cws.is_submit when 'Y' then 'Submitted' when 'N' then 'Saved' else 'Not submitted' end) as 'attendance_status',cws.doc_pdf " +
                            " from " +
                            " ( select res1.* from ( " +
                            " select exams.course_code,exams.course_name,exams.total_exams,students.total_students from" +
                            " (select course_mst.course_code,course_mst.course_name,exams1.total_exams from ws_course_mst as course_mst " +
                                " left join(select course_code,COUNT(exam_code)total_exams from ws_exam_master" +
                                            " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'   " +
                                            " group by course_code" +
                                        " )exams1" +
                                " on course_mst.course_code=exams1.course_code" +
                                " where course_mst.semester_type='" + sem_code + "' and course_mst.year_semester='" + year_code + "' and course_mst.cancel_flag='N' ";
                SqlSelect = SqlSelect + " )exams" +
                             " left join " +
                                 " (SELECT course_code,COUNT(user_id)total_students" +
                                     " FROM ws_student_course_allocate_dtl" +
                                     " where semester_type='" + sem_code + "' and year_semester='" + year_code + "'and cancel_flag = 'N'" +
                                     " group by course_code" +
                                 " )students" +
                             " on exams.course_code=students.course_code" +
                             " )res1 " +
                             " inner join " +
                             " (" +
                                 " select course_wise_instructor.*,instructor_mst.user_id,instructor_mst.instructor_name " +
                                 " from ws_course_wise_instructor as course_wise_instructor" +
                                 " inner join instructor_mst on instructor_mst.instructor_code=course_wise_instructor.instructor_code" +
                                 " where instructor_mst.user_id='" + user_id + "' and course_wise_instructor.semester_type = '" + sem_code + "'" +
