        public dynamic ws_manully_save_session_dtl(String Course_Code, String Session_Name, String Session_Date, String semester, String year, String user_id, String HostName)
        {
            string[] arr = Session_Date.Split('/');
            String DocNo = "";
            String message = "";
            BLReturnObject objBLReturnObject = new BLReturnObject();
            DBConnection.Open();
            if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "UF", user_id, HostName, ref DocNo, ref message))
            {

                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                objBLReturnObject.ExecutionStatus = 2;
                return objBLReturnObject;
            }


            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Close();
            DBConnection.Open();
            // DBCommand.Transaction = DBConnection.BeginTransaction();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            try
            {
                string new_date = arr[2] + "-" + arr[1] + "-" + arr[0];
                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                SqlSelect = "INSERT INTO ws_course_wise_session_dtl (course_code,session_id,session_name,session_date,is_cancelled,cancel_flag,semester_type,year_semester, created_by, created_date, created_host) "
                          + " VALUES('" + Course_Code + "', '" + DocNo + "','" + Session_Name + "','" + Convert.ToDateTime(new_date).ToString("yyyy/MM/dd HH:mm:ss") + "', 'N', 'N', '" + semester + "', '" + year + "','" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "'); ";

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DBCommand.ExecuteNonQuery();

                DBConnection.Close();
                string status = ws_update_course_wise_session_mst(Course_Code, semester, year, user_id);
                return status;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();
                return "false";
            }

            // }
            return false;

        }


        public dynamic ws_update_course_wise_session_mst(string Course_Code, string semester, string year, string user_id)
        {
            /*************************/
            /* ESTABLISH CONNECTION */

            /*************************/


            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();


            String SqlSelect = "";


            SqlSelect = "IF EXISTS(select * from ws_course_wise_session_mst where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N') "
                      + " BEGIN "
                      + " update ws_course_wise_session_mst set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', no_of_session_held =(select COUNT(session_id) as session_count from ws_course_wise_session_dtl where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and is_cancelled ='N') where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N'"
                      + " END "
                  + " ELSE "
                      + " BEGIN "
                      + " INSERT INTO ws_course_wise_session_mst (course_code,no_of_session_held,is_submit,cancel_flag, semester_type, year_semester, created_by, created_date, created_host) "
                      + " VALUES('" + Course_Code + "',(select COUNT(session_id) as session_count from ws_course_wise_session_dtl where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and is_cancelled ='N' ),'N','N', '" + semester + "', '" + year + "', '" + user_id + "', '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', '" + HttpContext.Current.Request.UserHostName + "')"
                      + " END ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return "true";
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return "false";
            }
        }


        public Boolean ws_cancel_session_dtl(string session_id, String Course_Code, String semester, String year, string user_id, string host_name)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = "update ws_course_wise_session_dtl set is_cancelled ='Y',cancel_flag='Y',last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'" +
                        " where cancel_flag = 'N' and is_cancelled ='N' and session_id = '" + session_id + "'";

            SqlSelect = SqlSelect + "update ws_course_wise_session_mst set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', no_of_session_held =(select COUNT(session_id) as session_count from ws_course_wise_session_dtl where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and is_cancelled ='N') where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N'";
            SqlSelect = SqlSelect + "update ws_student_wise_session_attendence set last_modified_by = '" + user_id + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "', cancel_flag ='Y' where semester_type = '" + semester + "' and year_semester = '" + year + "'and course_code ='" + Course_Code + "' and cancel_flag='N' and session_id = '" + session_id + "'";


            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return false;
            }
        }


        public BLReturnObject ws_save_course_wise_session_dtl(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_GradingMaster server_course_att_master = (DSC_GradingMaster)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_GradingMaster objSessionMaster_upload = new DSC_GradingMaster();

                objSessionMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_att_master.ws_course_wise_session_dtl.Rows.Count; mprCnt++)
                {

                    objSessionMaster_upload.ws_course_wise_session_dtl.ImportRow(server_course_att_master.ws_course_wise_session_dtl.Rows[mprCnt]);
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "UF", UserID, HostName, ref DocNo, ref message))
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        objBLReturnObject.ExecutionStatus = 2;
                        return objBLReturnObject;
                    }
                    objSessionMaster_upload.ws_course_wise_session_dtl[mprCnt].session_id = DocNo;
                    // obj_fees_status.user_fees_status[mprCnt].doc_no = DocNo;
                    //objSessionMaster_upload.exam_master[mprCnt].doc_no = DocNo;
                }


                objSessionMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objSessionMaster_upload.ws_course_wise_session_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objSessionMaster_upload.ws_course_wise_session_dtl.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }


