        public DataTable ws_get_session_date_wise_dtl(String Course_Code, String semester, String year)
        {
            string column_name = "";
            string select_column_name = "";

            DataTable dt_ = ws_get_student_session_dtl(Course_Code, semester, year);
            DataTable dt = ws_get_course_wise_session_dtl(Course_Code, semester, year);
            if (dt != null)
            {
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    if (i == 0)
                    {
                        column_name += dt.Rows[i]["session_id"].ToString();
                        select_column_name += "(p." + dt.Rows[i]["session_id"].ToString() + ") as '" + dt.Rows[i]["session_name"] + " (" + dt.Rows[i]["session_date"].ToString() + ")'";
                    }
                    else
                    {
                        column_name += "," + dt.Rows[i]["session_id"].ToString();
                        select_column_name += ",(p." + dt.Rows[i]["session_id"].ToString() + ") as '" + dt.Rows[i]["session_name"] + " (" + dt.Rows[i]["session_date"].ToString() + ")'";
                    }

                }

            }

            String SqlSelect = "";
            SqlSelect = " Select  p.session_is_submit, p.user_id, p.course_code, p.full_name,p.sca_user_id, " + select_column_name + " from (" +
                " select ws_student_wise_session_attendence.is_submit as session_is_submit,ws_course_wise_session_dtl.session_id as course_session_id," +
                " ws_student_course_allocate_dtl.user_id as sca_user_id, " +
                " ws_student_wise_session_attendence.user_id,ws_student_wise_session_attendence.course_code,session_attended, " +
                " user_mst.full_name,ws_student_wise_course_attendence.no_of_session_attended, ws_student_wise_course_attendence.attendance_percentage,ws_student_wise_course_attendence.is_submit " +
                " from ws_student_course_allocate_dtl " +
                " inner join user_mst on user_mst.user_id = ws_student_course_allocate_dtl.user_id " +
                " left join ws_student_wise_course_attendence on ws_student_wise_course_attendence.user_id = ws_student_course_allocate_dtl.user_id " +
                " and ws_student_wise_course_attendence.year_semester = ws_student_course_allocate_dtl.year_semester " +
                " and ws_student_wise_course_attendence.semester_type = ws_student_course_allocate_dtl.semester_type " +
                " and ws_student_wise_course_attendence.course_code = ws_student_course_allocate_dtl.course_code " +
                " and ws_student_wise_course_attendence.cancel_flag ='N' " +
                " inner join ws_course_wise_session_dtl on ws_course_wise_session_dtl.course_code =  ws_student_course_allocate_dtl.course_code " +
                " and ws_course_wise_session_dtl.cancel_flag ='N' and ws_course_wise_session_dtl.is_cancelled ='N'  " +
                " and ws_course_wise_session_dtl.semester_type =  ws_student_course_allocate_dtl.semester_type " +
                " and ws_course_wise_session_dtl.year_semester =  ws_student_course_allocate_dtl.year_semester " +
                " left join ws_student_wise_session_attendence on ws_student_wise_session_attendence.session_id = ws_course_wise_session_dtl.session_id " +
                " and ws_student_wise_session_attendence.course_code = ws_course_wise_session_dtl.course_code " +
                " and ws_student_wise_session_attendence.semester_type = ws_course_wise_session_dtl.semester_type " +
                " and ws_student_wise_session_attendence.year_semester = ws_course_wise_session_dtl.year_semester " +
                " and ws_student_wise_session_attendence.user_id = user_mst.user_id and ws_student_wise_session_attendence.cancel_flag ='N' " +
                " where ws_student_course_allocate_dtl.course_code='" + Course_Code + "'  and ws_student_course_allocate_dtl.semester_type='" + semester + "' " +
                " and ws_student_course_allocate_dtl.year_semester='" + year + "' and ws_student_course_allocate_dtl.cancel_flag='N'  ";

            if (dt_ != null)
            {
                SqlSelect = SqlSelect + " and ws_student_wise_session_attendence.user_id is NOT NULL ) as t ";
            }
            else
            {
                SqlSelect = SqlSelect + " ) as t";
            }

            SqlSelect = SqlSelect + " pivot ( " +
                " MAX(session_attended) for Course_session_id in (" + column_name + ") ) As P ";
            SqlSelect = SqlSelect + " order by p.full_name asc ";
            return Get_data(SqlSelect);
        }

        public dynamic ws_save_attendance_dtl(String Course_Code, String semester, String year, String no_of_held, String user_id)
