        public BLReturnObject ws_save_student_session_att_dtl(DataSet ds_UploadData, string compnyid, String UserID, String HostName)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DSC_GradingMaster server_course_att_master = (DSC_GradingMaster)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DSC_GradingMaster objCourseMaster_upload = new DSC_GradingMaster();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_att_master.ws_student_wise_session_attendence.Rows.Count; mprCnt++)
                {

                    objCourseMaster_upload.ws_student_wise_session_attendence.ImportRow(server_course_att_master.ws_student_wise_session_attendence.Rows[mprCnt]);
                    //objCourseMaster_upload.exam_master[mprCnt].doc_no = DocNo;
                }


                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.ws_student_wise_session_attendence, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.ws_student_wise_session_attendence.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }
                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    return objBLReturnObject;
                }

            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }

        public DataTable ws_get_student_wise_absend_present_dtl(String Course_Code, String semester, String year)
        {
            String SqlSelect = "";
            SqlSelect = " select CASE WHEN (t1.user_id IS NULL) THEN t2.user_id ELSE t1.user_id END AS user_id, isnull(t1.absent,0) as absent, isnull(t2.present,0) as present from (" +
                " (select user_id, COUNT(session_attended) as absent from ws_student_wise_session_attendence where course_code ='" + Course_Code + "' and session_attended ='A' and cancel_flag ='N' " +
                " and semester_type ='" + semester + "' and year_semester ='" + year + "' group by user_id, session_attended) as t1 " +
                " full join " +
                " (select user_id, COUNT(session_attended) as present from ws_student_wise_session_attendence where course_code ='" + Course_Code + "' and session_attended ='P' and cancel_flag ='N' " +
                " and semester_type ='" + semester + "' and year_semester ='" + year + "' group by user_id, session_attended) as t2  on t1.user_id=t2.user_id) ";
            return Get_data(SqlSelect);
        }


