        public DataTable Get_Ws_allocate_student_dtl(string sem_code, string year_code, string dept_code, string prog_code, string type, string student_code, string course_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " select wsw.user_id,wsw.course_code,wsw.year_code,wsw.semester_code,wsw.current_sem_code,wsw.course_type,wsw.fees,wsw.credits, " +
                " wsw.gpa_nongpa,wsw.dept_code,wsw.priority,wsw.status,wsw.cancel_flag,wsw.course_drop,wsw.remark,wsw.semester_type,wsw.year_semester,wsw.round,wsw.course_number,um.prog_code,um.full_name,um.dept_code," +
                "  CASE WHEN (wsw.cancel_flag='Y') THEN 'Drop' " +
                "  WHEN (wsw.cancel_flag='N' ) THEN 'Allocated' ELSE wsw.status END as status_name " +
                " from ws_student_wise_course_dtl wsw " +
                " inner join user_mst um on um.user_id = wsw.user_id " +
                " where wsw.semester_type = '" + sem_code + "' and wsw.year_semester = '" + year_code + "'  ";

            if (type == "D")
            {
                SqlSelect = SqlSelect + " and wsw.cancel_flag ='Y'";
            }
            else if (type == "A")
            {
                SqlSelect = SqlSelect + " and wsw.cancel_flag ='N'";
            }
            if (dept_code != "")
            {

                SqlSelect = SqlSelect + " and um.dept_code = '" + dept_code + "' ";

            }

            if (prog_code != "")
            {

                SqlSelect = SqlSelect + " and um.prog_code = '" + prog_code + "' ";

            }

            if (student_code != "")
            {
                SqlSelect = SqlSelect + " and wsw.user_id = '" + student_code + "' ";
            }
            if (course_code != "")
            {
                SqlSelect = SqlSelect + " and wsw.course_code = '" + course_code + "' ";
            }

            SqlSelect = SqlSelect + " order by um.user_id ";
            return Get_data(SqlSelect);
        }


        public DataTable ws_get_assigned_report_data(string dept_code, string sem_code, string year_code, string prog_level_code)
        {
            String SqlSelect = "";

            SqlSelect = @" SELECT ws_student_course_allocate_dtl.user_id,user_mst.user_name,user_mst.mail,UCD.applicant_mobile_no, course_type,COUNT(course_code) as course_code,sum(cast(credits as int)) as credits , 
	                     user_mst.gender,dm.dept_name,pm.prog_name,pl.prog_level_name,pl.prog_level_code,pl.prog_level_desc 
	                     FROM ws_student_course_allocate_dtl 
	                     INNER JOIN user_mst on ws_student_course_allocate_dtl.user_id = user_mst.user_id  
	                     left join department_mst as dm on dm.dept_code=user_mst.dept_code
                         left join programme_mst as pm on pm.prog_code=user_mst.prog_code
                         left join programme_level_mst as pl on pl.prog_level_code = user_mst.prog_level_code 
	                     LEFT JOIN user_contact_dtl UCD WITH(NOLOCK) ON user_mst.enrollment_no = UCD.application_id
	                     where ws_student_course_allocate_dtl.cancel_flag = 'N' and ws_student_course_allocate_dtl.semester_type = '" + sem_code + "'  and ws_student_course_allocate_dtl.year_semester = '" + year_code + "'" +
                         "  and user_mst.user_status_flag = 'A' ";
            if (dept_code != "")
            {
                SqlSelect = SqlSelect + " and user_mst.dept_code = '" + dept_code + "' ";
            }
            if (prog_level_code != "")
            {
                SqlSelect = SqlSelect + " and pl.prog_level_code = '" + prog_level_code + "' ";
            }

            SqlSelect = SqlSelect + " GROUP BY ws_student_course_allocate_dtl.user_id,course_type,user_mst.user_name,user_mst.mail,UCD.applicant_mobile_no,user_mst.gender,dm.dept_name,pm.prog_name,pl.prog_level_name,pl.prog_level_code,pl.prog_level_desc ";
            SqlSelect = SqlSelect + " ORDER BY ws_student_course_allocate_dtl.user_id,course_type ";

            return Get_data(SqlSelect);
        }


        public DataTable Studio_Find_single_dual(String course_code, String sem_code, String year_code)
        {
            String SqlSelect = "";
            SqlSelect = @"Select CASE
                          WHEN iti.no_of_tutor = 'Single' THEN '19'
                          WHEN iti.no_of_tutor = 'Dual' THEN '24'
                          WHEN iti.no_of_tutor = 'Multiple' THEN '24'
                          ELSE '19'
                          END count_status from instructor_studio_details as isd
                          inner join instructor_teaching_interest as iti on iti.studio_code = isd.studio_code and
                          iti.semester_type = isd.semester_type and iti.year_semester = isd.year_semester and iti.cancel_flag = isd.cancel_flag
                          where isd.cancel_flag = 'N' and(isd.course_code = '" + course_code + "' or isd.new_course_code = '" + course_code + "') and isd.semester_type = '" + sem_code + "' and isd.year_semester = '" + year_code + "'";



            return Get_data(SqlSelect);

        }



