        public DataTable Check_Checkbox_enable_disable(String course_code, String sem_code, String year_code)
        {
            String SqlSelect = "";
            SqlSelect = @"select vss.course_code,iti.no_of_tutor,COUNT(vss.course_code) no_of_student,
						CASE
						WHEN (iti.no_of_tutor = 'Single' and COUNT(vss.course_code) <= 20) THEN  'True' 
						WHEN (iti.no_of_tutor = 'Dual' and COUNT(vss.course_code) <= 25) THEN  'True'
						WHEN (iti.no_of_tutor = 'Multiple' and COUNT(vss.course_code) <= 25) THEN  'True'
						ELSE 'False' 
                        END 'Checkbox'
						from vertical_studio_selection_dtl vss
						inner join instructor_studio_details isd on isd.new_course_code = vss.course_code
						and isd.semester_type = vss.semester_type and isd.year_semester = vss.year_semester
						and isd.cancel_flag = vss.cancel_flag
						inner join instructor_teaching_interest iti on iti.studio_code = isd.studio_code and 
						iti.cancel_flag= vss.cancel_flag
	                    where vss.course_code='" + course_code + "' and vss.semester_type='" + sem_code + "' and vss.year_semester='" + year_code + "' " +
                        " and vss.cancel_flag='N'  and vss.priority='1' and vss.status IN('R','A') " +
                        " Group by vss.course_code,iti.no_of_tutor,vss.course_code ";
            return Get_data(SqlSelect);

        }

