        public DataTable Get_Studio_total_count_dtl(String semester_type, String year_type, String course_code)
        {
            String SqlSelect = "";
            SqlSelect = @" select * from (
                            select t2.*,Count(status) TotalAllocate from(
                            select t1.*,COUNT(shortlist_student_status) Totalshortliststudent from
                            (select course_code,Count(user_id)TotalStudent,priority,MAX(semester_type)semester_type,MAX(year_semester)year_semester 
                            from vertical_studio_selection_dtl where semester_type='" + semester_type + "' and year_semester='" + year_type + "'  and cancel_flag='N' and course_code='" + course_code + @"'
                            group by course_code,priority) t1
                            left join vertical_studio_selection_dtl as vss on vss.course_code = t1.course_code 
                            and vss.semester_type = t1.semester_type and vss.year_semester= t1.year_semester
                             and (vss.shortlist_student_status='Y' or  vss.shortlist_student_status IS NULL) 
                            where  vss.cancel_flag='N' and vss.priority='1'
                            Group by t1.course_code,t1.priority,t1.semester_type,t1.year_semester,t1.TotalStudent) t2
                            left join vertical_studio_selection_dtl as vss on vss.course_code = t2.course_code and vss.priority= t2.priority
                            and vss.status = 'A'
                            and vss.semester_type = t2.semester_type and vss.year_semester= t2.year_semester
                            
                            Group by t2.course_code,t2.priority,t2.semester_type,t2.year_semester,t2.TotalStudent,t2.Totalshortliststudent) t3
                            order by t3.priority asc";
            return Get_data(SqlSelect);

        }

        public DataTable Student_wise_drop_dtl(String semester_type, String year_type, String dept_code)
        {
            String SqlSelect = "";
            SqlSelect = @"  select student_course_allocate_dtl.doc_no,student_course_allocate_dtl.user_id ,
                            user_mst.full_name,user_mst.mail,student_course_allocate_dtl.course_code + ' - ' + course_mst.course_name + ' ( Total Set : ' + dwc.available_seat + ' Allocated Set : '+(select CAST(COUNT(course_code) AS nvarchar(3)) course_count from student_course_allocate_dtl where semester_type='" + semester_type + @"' and year_semester='" + year_type + @"' and course_code= course_mst.course_code  and cancel_flag='N')
                            + ' Drop Set : '+(select CAST(COUNT(course_code) AS nvarchar(3)) course_count from student_course_allocate_dtl where semester_type='" + semester_type + @"' and year_semester='" + year_type + @"' and course_code= course_mst.course_code  and cancel_flag='Y')
                            +' )' as course_code ,course_mst.course_name,department_mst.dept_name, 
                            CONVERT(VARCHAR(5),student_course_allocate_dtl.last_modified_date,108) as time, CONVERT(VARCHAR(24),student_course_allocate_dtl.last_modified_date,105) as date 
                            from student_course_allocate_dtl 
                            inner join course_mst on student_course_allocate_dtl.course_code = course_mst.course_code 
                            INNER JOIN user_mst on student_course_allocate_dtl.user_id = user_mst.user_id
                            inner JOIN department_mst on user_mst.dept_code = department_mst.dept_code   
                            inner join department_wise_course_dtl dwc on dwc.course_code = course_mst.course_code and 
                            dwc.semester_type = course_mst.semester_type and dwc.year_semester = course_mst.year_semester
                            where  student_course_allocate_dtl.cancel_flag ='Y'  and student_course_allocate_dtl.semester_type = '" + semester_type + @"'
                            and student_course_allocate_dtl.year_semester = '" + year_type + @"' and course_mst.semester_type = '" + semester_type + @"' and course_mst.year_semester = '" + year_type + @"'";
