        public DataTable Get_total_contact_hrs(string inst_code, string sem_code, string year_code, string studio_code)
        {
            String SqlSelect = "";
            SqlSelect = @" Select t1.total_contact_hrs,t1.current_contact_hrs,(t1.total_contact_hrs + t1.current_contact_hrs) as contact_hrs,(40 - t1.total_contact_hrs) as remening_hrs from ( 
                           Select ISNULL (SUM(CAST(total_contact_hrs as float)), '0' ) as total_contact_hrs, current_contact_hrs = ( Select  ISNULL ( SUM(CAST(total_contact_hrs as float)),'0') as total_contact_hrs_ 
