        public Boolean Send_Mail_for_Course_auth(string course_code, string inst_code, string parameter, string remark, string sem_code, string year_code)
        {
            DataTable dt = Get_course_department_data_for_modification(sem_code, year_code, course_code);
            if (dt != null)
            {
                DataTable pc_dtl = pc_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable dean_dtl = dean_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                DataTable faculty_admin = fa_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());

                DataTable mail_from_id_password = check_frommail_id_password(parameter);
                DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body(parameter, "email");
                DataTable user_dtl = check_user_by_user_id(inst_code);
                Mail mail = new Mail();
                pc_dtl = null;
                dean_dtl = null;
                bool mail_status = mail.StudioproposalAuthorized(inst_code, pc_dtl, dean_dtl, faculty_admin, mail_from_id_password, AckDetails, user_dtl, remark);

            }
            return false;
        }

        public Boolean Send_Mail_for_Course_auth_without_course(string course_code, string inst_code, string parameter, string remark, string sem_code, string year_code)
        {
            DataTable dt_course_dtl = Getcoursewisedepartmentdtl(inst_code, sem_code, year_code);
            if (dt_course_dtl != null)
            {
                for (int i = 0; i < dt_course_dtl.Rows.Count; i++)
                {
                    DataTable dt = Get_course_department_data_for_modification(sem_code, year_code, dt_course_dtl.Rows[i]["course_code"].ToString());
                    if (dt != null)
                    {
                        DataTable pc_dtl = pc_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                        DataTable dean_dtl = dean_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());
                        DataTable faculty_admin = fa_dtl_dept_wise(dt.Rows[0]["dept_code"].ToString(), dt.Rows[0]["prog_code"].ToString(), dt.Rows[0]["prog_level_code"].ToString(), dt.Rows[0]["semester_type"].ToString(), dt.Rows[0]["year_semester"].ToString());

                        DataTable mail_from_id_password = check_frommail_id_password(parameter);
                        DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body(parameter, "email");
                        DataTable user_dtl = check_user_by_user_id(inst_code);
                        Mail mail = new Mail();
                        pc_dtl = null;
                        dean_dtl = null;
                        bool mail_status = mail.StudioproposalAuthorized(inst_code, pc_dtl, dean_dtl, faculty_admin, mail_from_id_password, AckDetails, user_dtl, remark);

                    }
                }
            }
            return false;
        }

