        public DataTable Get_Data_choice_preference(string student_id, string sem_code, string year_code, string user_type, string sub_cat_id, string dept_code, string prog_code, string prog_level_code)
        {
            String SqlSelect = "";
            SqlSelect = " select res1.edit_status as editstatus ,* from ( ";
            SqlSelect += " select um.full_name, CASE WHEN cpd.semester_type = 'S' THEN 'Spring ' +  cpd.year_semester WHEN cpd.semester_type = 'M' THEN 'Monsoon ' +  cpd.year_semester END appliedfor," +
                " CASE WHEN cpd.sub_cat_id = '23' THEN 'Studio' WHEN cpd.sub_cat_id = '29' THEN 'DRP' WHEN cpd.sub_cat_id = '26' THEN 'Internship' END Choice,FORMAT(cpd.created_date,'dd-MM-yyyy') created_date_by, " +
                " cpd.* from choice_preference_dtl as cpd " +
                " inner join user_mst um on um.user_id = cpd.user_id " +
                " where cpd.semester_type='" + sem_code + "' and cpd.year_semester='" + year_code + "'  and cpd.cancel_flag='N' and cpd.status in ('Y','N') ";
            if (user_type.ToLower().ToString() == "s")
            {
                SqlSelect = SqlSelect + " and cpd.user_id='" + student_id + "' ";

            }
            if (user_type.ToLower().ToString() != "s" && sub_cat_id != "")
            {
                SqlSelect = SqlSelect + " and cpd.sub_cat_id ='" + sub_cat_id + "'  ";
            }
            if (user_type.ToLower().ToString() != "s")
            {
                if (dept_code != "")
                {
                    SqlSelect = SqlSelect + " and um.dept_code='" + dept_code + "' ";
                }
                if (prog_code != "")
                {
                    SqlSelect = SqlSelect + " and um.prog_code='" + prog_code + "' ";
                }
                if (prog_level_code != "")
                {
                    SqlSelect = SqlSelect + " and um.prog_level_code ='" + prog_level_code + "' ";
                }
            }

            SqlSelect += " ) t1 left join (select edit_status,user_id from choice_preference_dtl where cancel_flag='N' and edit_status ='Y' AND semester_type='" + sem_code + @"' AND year_semester='" + year_code + @"'  ) res1  on res1.user_id = t1.user_id";

            return Get_data(SqlSelect);
        }


