            //SWSCalculateCredit.TotalApplyCredit = Convert.ToInt32(credit_dtl[0]["total_credits"].ToString());


            DataTable WavierCredit = GetStudentWavierCreditdata(dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString(), UserID);
            SWSCalculateCredit.RegisteredCredits = Convert.ToInt32(credit_dtl[0]["total_credits"].ToString());
            SWSCalculateCredit.ProvisionallyAllocatedCredits = 0;
            SWSCalculateCredit.RequiredToPay = 0;
            SWSCalculateCredit.WaiverCredit = 0;
            SWSCalculateCredit.WaiverCredit = Convert.ToInt32(WavierCredit.Rows[0]["fees_waiver_credits"].ToString());
            if (dt_swsCreditCount != null)
            {
                SWSCalculateCredit.TotalApplyCredit = Convert.ToInt32(dt_swsCreditCount.Rows[0]["TotalAppliedCredit"].ToString() == "" ? "0" : dt_swsCreditCount.Rows[0]["TotalAppliedCredit"].ToString());
                SWSCalculateCredit.TotalRemainingCredits = Convert.ToInt32(dt_swsCreditCount.Rows[0]["TotalRemainingCredits"].ToString() == "" ? "0" : dt_swsCreditCount.Rows[0]["TotalRemainingCredits"].ToString());

                SWSCalculateCredit.Srno = Convert.ToInt32(dt_swsCreditCount.Rows[0]["SrNo"].ToString()) + 1;
                rowcount = Convert.ToInt32(dt_swsCreditCount.Rows[0]["SrNo"].ToString()) + 1;
                SWSCalculateCredit.ProvisionallyAllocatedCredits = Convert.ToInt32(dt_swsCreditCount.Rows[0]["ProvisionallyAllocatedCredits"].ToString() == "" ? "0" : dt_swsCreditCount.Rows[0]["ProvisionallyAllocatedCredits"].ToString());


                #region CalculatePayFeesCreditWithWavierCredit

                SWSCalculateCredit.PaidFeesCredit = Convert.ToInt32(dt_swsCreditCount.Rows[0]["PaidFeesCredit"].ToString() == "" ? "0" : dt_swsCreditCount.Rows[0]["PaidFeesCredit"].ToString());
                if (SWSCalculateCredit.WaiverCredit > SWSCalculateCredit.PaidFeesCredit)
                {
                    SWSCalculateCredit.RemaningWaiverCredit = SWSCalculateCredit.WaiverCredit - SWSCalculateCredit.ProvisionallyAllocatedCredits;
                }
                else
                {
                    SWSCalculateCredit.PaidFeesWithWaiverCredit = SWSCalculateCredit.WaiverCredit + SWSCalculateCredit.PaidFeesCredit;
                    SWSCalculateCredit.RemaningWaiverCredit = SWSCalculateCredit.PaidFeesWithWaiverCredit - SWSCalculateCredit.ProvisionallyAllocatedCredits;

                }

                #endregion

                //First Check Waiver Credit

                SWSCalculateCredit.RegisteredCredits = Convert.ToInt32(credit_dtl[0]["total_credits"].ToString());

                if (SWSCalculateCredit.ProvisionallyAllocatedCredits != 0)
                {

                    SWSCalculateCredit.TotalApplyCredit = Convert.ToInt32(dt_swsCreditCount.Rows[0]["TotalAppliedCredit"].ToString());
                }
                else
                {
                    SWSCalculateCredit.TotalApplyCredit = Convert.ToInt32(credit_dtl[0]["total_credits"].ToString());
                }


                SWSCalculateCredit.WaiverCredit = Convert.ToInt32(WavierCredit.Rows[0]["fees_waiver_credits"].ToString());

                #region Calculate Credits
                SWSCalculateCredit.calculateCredit = SWSCalculateCredit.ProvisionallyAllocatedCredits + SWSCalculateCredit.RegisteredCredits;
                if (SWSCalculateCredit.RemaningWaiverCredit >= SWSCalculateCredit.RegisteredCredits)
                {
                    RequiredToPay = 0;
                    SWSCalculateCredit.RequiredToPay = 0;
                }
                else
                {
                    RequiredToPay = SWSCalculateCredit.RegisteredCredits - SWSCalculateCredit.RemaningWaiverCredit;
                    SWSCalculateCredit.RequiredToPay = RequiredToPay;

                }

                #endregion


            }
            else
            {
                // First Time
                TotalCredits = Convert.ToInt32(credit_dtl[0]["total_credits"].ToString());
                SWSCalculateCredit.TotalApplyCredit = TotalCredits;
                //SWSCalculateCredit.TotalApplyCredit = TotalCredits;
                if (Convert.ToInt32(credit_dtl[0]["total_credits"].ToString()) > Convert.ToInt32(WavierCredit.Rows[0]["fees_waiver_credits"].ToString() == "" ? "0" : WavierCredit.Rows[0]["fees_waiver_credits"].ToString()))
                {
                    RequiredToPay = Convert.ToInt32(credit_dtl[0]["total_credits"].ToString()) - Convert.ToInt32(WavierCredit.Rows[0]["fees_waiver_credits"].ToString() == "" ? "0" : WavierCredit.Rows[0]["fees_waiver_credits"].ToString());
                    SWSCalculateCredit.PaidFeesCredit = 0;
                }
                else
                {
                    RequiredToPay = 0;
                    SWSCalculateCredit.PaidFeesCredit = 0;
                }

                rowcount = 1;
            }

            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";

                try
                {
                    SqlSelect += " update ws_connect_student_reg_dtl set cancel_flag='Y',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where user_id='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' and status='R' " +
                        " and course_type='E' and FORMAT(GETDATE(),'yyyy-MM-dd') != Format(created_date,'yyyy-MM-dd') ";
                    SqlSelect += " update ws_credit_choice set cancel_flag='Y',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where user_id='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";
                    SqlSelect += " update ws_credit_choice_combination set cancel_flag='Y',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where user_id='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";
                    SqlSelect += " update ws_SWSCreditCalculation set cancel_flag='Y',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where UserID='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    int res_insert = DBCommand.ExecuteNonQuery();

                    try
                    {
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "CCW", UserID, host_name, ref DocNo, ref message))
                        {

                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            return false;
                        }

                        DBDataAdpterObject.SelectCommand.Parameters.Clear();
                        SqlSelect = "";

                        SqlSelect = " Insert into ws_credit_choice (doc_no,user_id,credit_choice,semester_type,year_semester,cancel_flag,created_by,created_date,created_host) " +
                                " VALUES('" + DocNo + "','" + UserID + "','" + credit_dtl[0]["total_credits"].ToString() + "','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "','N'," +
                                " '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "')";

                        DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                        int res_insert1 = DBCommand.ExecuteNonQuery();
                        if (res_insert1 <= 0)
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            return false;
                        }
                        try
                        {
                            DBDataAdpterObject.SelectCommand.Parameters.Clear();
                            SqlSelect = "";

                            for (int i = 0; i < credit_combination.Count; i++)
                            {
                                if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "CCC", UserID, host_name, ref DocNo_new, ref message))
                                {

                                    DBCommand.Transaction.Rollback();
                                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                                    return false;
                                }

                                SqlSelect += " insert into ws_credit_choice_combination (doc_no,user_id,no_of_credits,no_of_combination,credit_combination,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,course_type) " +
                                    " VALUES('" + DocNo_new + "','" + UserID + "','" + credit_combination[i]["no_of_credits"].ToString() + "','" + credit_combination[0]["no_of_combination"].ToString() + "','" + credit_combination[i]["credit_combination"].ToString() + "'," +
                                    " '" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "','N'," +
                                    " '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "','" + credit_combination[i]["select_drp_type"].ToString() + "')";

                                if (i == 0)
                                {
                                    SqlSelect += " INSERT INTO ws_SWSCreditCalculation (SrNo,UserID,TotalAppliedCredit,WaiverCredit,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,RegisteredCredits,RequiredToPay,PaidFeesCredit,ProvisionallyAllocatedCredits) " +
                                   " VALUES('" + rowcount + "','" + UserID + "','" + SWSCalculateCredit.TotalApplyCredit.ToString() + "','" + SWSCalculateCredit.WaiverCredit.ToString() + "','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "'," +
                                   " 'N' , '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "','" + SWSCalculateCredit.RegisteredCredits + "','" + RequiredToPay + "','" + SWSCalculateCredit.PaidFeesCredit + "','" + SWSCalculateCredit.ProvisionallyAllocatedCredits + "')";
                                }
                            }
                            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                            int res_insert_combination = DBCommand.ExecuteNonQuery();

                            if (res_insert_combination <= 0)
                            {
                                DBCommand.Transaction.Rollback();
                                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                                return false;
                            }

                        }
                        catch (Exception ex)
                        {

                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            return false;
                        }
                    }
                    catch (Exception ex)
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                        return false;
                    }
                }
                catch (Exception ex)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            return true;
        }

        public DataTable SWSCreditCalculation(string user_id, string sem_code, string year_code)
        {
            //DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            SqlSelect = @" SELECT  * FROM ws_SWSCreditCalculation wcc WITH(NOLOCK) ";
            SqlSelect += "  where 1=1 and wcc.semester_type='" + sem_code + "' and wcc.year_semester='" + year_code + "' and wcc.UserID='" + user_id + "' and wcc.cancel_flag = 'N' ";


            return Get_data(SqlSelect);
        }

        public DataTable SWSCreditCalculationWithGST(string user_id, string sem_code, string year_code, bool GSTType)
        {
            //DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            DataTable user_dtl = check_user_by_user_id(user_id);
            string user_type = "S";
            if (GSTType)
            {
                if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "S")
                {
                    user_type = "S";
                }
                else
                {
                    user_type = "P";
                }

            }
            DataTable calculate_fees_amount = Get_fees_amount_pre_credit_WS_user_type(sem_code, year_code, user_type, user_id);
            String SqlSelect = "";
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            if (GSTType)
            {
                SqlSelect = @" SELECT 
                                SUM('" + calculate_fees_amount.Rows[0]["fees_amount"] + @"' * RequiredToPay) AS total_amount_before_gst,
                                SUM(('" + calculate_fees_amount.Rows[0]["fees_amount"] + @"' * RequiredToPay) * 18 / 100) AS total_gst_amount,
                                SUM(('" + calculate_fees_amount.Rows[0]["fees_amount"] + @"' * RequiredToPay) + (('" + calculate_fees_amount.Rows[0]["fees_amount"] + @"' * RequiredToPay) * 18 / 100)) AS total_amount_with_gst ";
            }
            else
            {
                SqlSelect = @" SELECT 
                                SUM('" + calculate_fees_amount.Rows[0]["fees_amount"] + @"' * RequiredToPay) AS total_amount_before_gst,
                                SUM(('" + calculate_fees_amount.Rows[0]["fees_amount"] + @"' * RequiredToPay)) AS total_gst_amount,
                                SUM(('" + calculate_fees_amount.Rows[0]["fees_amount"] + @"' * RequiredToPay)) AS total_amount_with_gst ";
            }
            SqlSelect += " FROM ws_SWSCreditCalculation wcc WITH(NOLOCK) where 1=1 and wcc.semester_type='" + sem_code + "' and wcc.year_semester='" + year_code + "' and wcc.UserID='" + user_id + "' and wcc.cancel_flag = 'N' ";


            return Get_data(SqlSelect);
        }


        public DataTable SWs_credit_data_get(string user_id, string sem_code, string year_code)
        {
            //DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            SqlSelect = @" Select wcc.user_id, wc.credit_choice,wcc.no_of_credits,wcc.no_of_combination,wcc.credit_combination,wcc.no_of_course,wcc.semester_type,wcc.year_semester,wcc.course_type,
                           ISNULL(wsscc.ProvisionallyAllocatedCredits,0) as ProvisionallyAllocatedCredits
                            from ws_credit_choice_combination wcc WITH(NOLOCK) 
                            inner join ws_credit_choice wc WITH(NOLOCK) on wc.user_id = wcc.user_id and wc.cancel_flag= wcc.cancel_flag
                            and wc.semester_type = wcc.semester_type and wc.year_semester = wcc.year_semester 
                            left join ws_SWSCreditCalculation wsscc on wsscc.UserID = wcc.user_id 
							and wsscc.semester_type = wcc.semester_type and wsscc.year_semester = wcc.year_semester
							and wsscc.cancel_flag ='N' ";
            SqlSelect += " where wcc.cancel_flag='N' and wcc.semester_type='" + sem_code + "' and wcc.year_semester='" + year_code + "' and wcc.user_id='" + user_id + "' order by wcc.credit_combination asc";


            return Get_data(SqlSelect);
        }


