        public DataTable SWs_credit_data_get_after_payment(string user_id, string sem_code, string year_code)
        {
            //DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            //      SqlSelect = @" select 
            //                  ISNULL((select credit_choice from ws_credit_choice where user_id ='"+ user_id + @"' and semester_type='"+ sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N'),0) credit_combination_credit,t1.allocated_credit_count,
            //                  (select FORMAT(created_date,'dd-MM-yyyy')created_date from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N'
            //and FORMAT(created_date,'dd-MM-yyyy') = FORMAT(GETDATE(),'dd-MM-yyyy')) as created_date,
            //                  ISNULL(((select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N') - t1.allocated_credit_count), 0) remaning_credits,t1.user_id
            //                  from (
            //                  select ISNULL(SUM(CAST(wcs.credits as int)),0) allocated_credit_count, um.user_id from user_mst um 
            //                  left join ws_applicationpaymenttransaction wap on wap.user_id = um.user_id and wap.semester_type='" + sem_code + @"' and wap.year_semester='" + year_code + @"'  and wap.payment_response_code='0'
            //                  and wap.manually_course_status IS NULL
            //                  left join ws_connect_student_reg_dtl wcs on wcs.user_id = wap.user_id and wcs.semester_type= wap.semester_type and wcs.year_semester = wap.year_semester and wcs.status='P'
            //                  and wcs.cancel_flag='N' where um.user_id='" + user_id + @"' group by um.user_id) t1";
            SqlSelect = " IF EXISTS(select Top (1) * from ws_credit_choice_combination where user_id='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N' and no_of_combination='1') "
                             + " BEGIN ";

            SqlSelect += @" Select res4.credit_combination_credit,ISNULL((res4.allocated_credit_count - res4.drop_course_credit),0) allocated_credit_count
						, res4.created_date,ISNULL((res4.drop_course_credit + res4.remaning_credits),0)remaning_credits, res4.user_id,res4.payment_response_code,res4.status
						from (

						select res5.payment_response_code,res6.status, ISNULL(res3.drop_course_credit,0) drop_course_credit,ISNULL(res2.priorty_one_drop_course_credit,0) priorty_one_drop_course_credit,
                        ISNULL((select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N'),0) credit_combination_credit,
						
						t1.allocated_credit_count,
                        (select FORMAT(created_date,'dd-MM-yyyy')created_date from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N'
						and FORMAT(created_date,'dd-MM-yyyy') = FORMAT(GETDATE(),'dd-MM-yyyy')) as created_date,
                        

                        
                        
                        Case When t1.allocated_credit_count = 0 Then (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')
                        Else 
                        ISNULL((t1.allocated_credit_count - (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')), 0) END remaning_credits
                        ,t1.user_id

                        from (
                        select ISNULL(SUM(CAST(wcs.credits as int)),0) allocated_credit_count, wcs.user_id from user_mst um 
                        left join ws_applicationpaymenttransaction wap on wap.user_id = um.user_id and wap.semester_type='" + sem_code + @"' and wap.year_semester='" + year_code + @"'  and wap.payment_response_code='0'
                        and wap.manually_course_status IS NULL 
                        left join ws_connect_student_reg_dtl wcs on wcs.user_id = wap.user_id and wcs.semester_type= wap.semester_type and wcs.year_semester = wap.year_semester and wcs.status='P' 
                        and wcs.cancel_flag='N' where um.user_id='" + user_id + @"'   group by wcs.user_id) t1

						left join (select ISNULL(SUM(CAST(credits as int)),0) priorty_one_drop_course_credit,user_id from ws_connect_student_reg_dtl where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"'
						and cancel_flag='N' and user_id='" + user_id + @"' and course_drop_status='Y' and priority ='1' and credit_combination ='1' group by user_id ) res2 on res2.user_id=t1.user_id

						left join (select ISNULL(SUM(CAST(credits as int)),0) drop_course_credit,user_id from ws_connect_student_reg_dtl where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' 
						and cancel_flag='N' and user_id='" + user_id + @"' and course_drop_status='Y' and priority !='1' group by user_id ) res3 on res3.user_id=t1.user_id
                        
                        left join (select Top(1) payment_response_code,user_id  from ws_applicationpaymenttransaction where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"'
						and user_id='" + user_id + @"'  order by created_date desc ) res5 on res5.user_id=t1.user_id

						left join  (select Top(1) status,user_id  from ws_connect_student_reg_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + @"' 
						and user_id='" + user_id + @"' and status='P' and priority != '1' and course_drop_status IS NULL ) res6 on res6.user_id=t1.user_id ) res4 ";

            SqlSelect += @"  END ELSE BEGIN ";


            //ISNULL(( t1.allocated_credit_count - (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')), 0) End remaning_credits
            SqlSelect += @" Select res4.credit_combination_credit,ISNULL((res4.allocated_credit_count - res4.drop_course_credit),0) allocated_credit_count
						, res4.created_date,ISNULL((res4.drop_course_credit + res4.remaning_credits),0)remaning_credits, res4.user_id,res4.payment_response_code,res4.status
						from (

						select res5.payment_response_code,res6.status, ISNULL(res3.drop_course_credit,0) drop_course_credit,priorty_one_drop_course_credit = 0,
                        ISNULL((select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N'),0) credit_combination_credit,
						
						t1.allocated_credit_count,
                        (select FORMAT(created_date,'dd-MM-yyyy')created_date from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N'
						and FORMAT(created_date,'dd-MM-yyyy') = FORMAT(GETDATE(),'dd-MM-yyyy')) as created_date,
                       

                        Case When t1.allocated_credit_count = 0 Then (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')
                        Else 
                        CASE When t1.allocated_credit_count > (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')
						Then
						ISNULL(( t1.allocated_credit_count - (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')), 0)
						When 
						t1.allocated_credit_count < (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')
						Then ISNULL(( (select credit_choice from ws_credit_choice where user_id ='" + user_id + @"' and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')- t1.allocated_credit_count), 0)
						END
                        End remaning_credits
                        ,t1.user_id  from (
                        select ISNULL(SUM(CAST(wcs.credits as int)),0) allocated_credit_count, wcs.user_id from user_mst um 
                        left join ws_applicationpaymenttransaction wap on wap.user_id = um.user_id and wap.semester_type='" + sem_code + @"' and wap.year_semester='" + year_code + @"'  and wap.payment_response_code='0'
                        and wap.manually_course_status IS NULL
                        left join ws_connect_student_reg_dtl wcs on wcs.user_id = wap.user_id and wcs.semester_type= wap.semester_type and wcs.year_semester = wap.year_semester and wcs.status='P' 
                        and wcs.cancel_flag='N' where um.user_id='" + user_id + @"'   group by wcs.user_id) t1
						left join (select ISNULL(SUM(CAST(credits as int)),0) drop_course_credit,user_id from ws_connect_student_reg_dtl where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' 
						and cancel_flag='N' and user_id='" + user_id + @"' and course_drop_status='Y'  group by user_id ) res3 on res3.user_id=t1.user_id
                        
                        left join (select Top(1) payment_response_code,user_id  from ws_applicationpaymenttransaction where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"'
						and user_id='" + user_id + @"'  order by created_date desc ) res5 on res5.user_id=t1.user_id

						left join  (select Top(1) status,user_id  from ws_connect_student_reg_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + @"' 
						and user_id='" + user_id + @"' and status='P' and course_drop_status IS NULL ) res6 on res6.user_id=t1.user_id ) res4 ";

            SqlSelect += @"  END ";
            //and priority !='1'
            //left join (select ISNULL(SUM(CAST(credits as int)),0) priorty_one_drop_course_credit,user_id from ws_connect_student_reg_dtl where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"'
            //and cancel_flag='N' and user_id='" + user_id + @"' and course_drop_status='Y' and priority ='1' group by user_id ) res2 on res2.user_id=t1.user_id




            return Get_data(SqlSelect);
        }


        public DataTable SWs_get_pre_allocated_course(string user_id, string sem_code, string year_code)
        {
            //DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            SqlSelect = @" select * from ws_connect_student_reg_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and status='P' and user_id='" + user_id + "' and cancel_flag='N'";


            return Get_data(SqlSelect);
        }


