							union 
							select course_code from ws_connect_student_reg_dtl where semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' and status='P' and course_drop_status='Y' and user_id='" + user_id + @"'
							and cancel_flag='N'
							)";

            SqlSelect += @")  t1  order by t1.credit_combination asc,t1.course_code ";


            return Get_data(SqlSelect);
        }

