        public bool save_sws_course_reg_dtl(string ws_course_data, string host_name, string UserID)
        {
            Document Doc = new Document();
            String message = "";
            String DocNo = "";
            String DocNo_new = "";

            JavaScriptSerializer serializer = new JavaScriptSerializer();
            List<Dictionary<string, string>> credit_dtl = new List<Dictionary<string, string>>();
            credit_dtl = serializer.Deserialize<List<Dictionary<string, string>>>(ws_course_data);
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            DataTable dt_dataMexistOrNot = select_mandatory_course_dtl(UserID);
            if (dt_dataMexistOrNot != null)
            {
                return false;
            }

            try
            {
                int totalcredit = 0;
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";

                try
                {
                    SqlSelect = "update ws_connect_student_reg_dtl set cancel_flag='Y',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'," +
                        " last_modified_host = '" + host_name + "' where user_id='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' " +
                        " and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' and status ='S'";


                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    int res_insert = DBCommand.ExecuteNonQuery();

                    try
                    {
                        DBDataAdpterObject.SelectCommand.Parameters.Clear();
                        SqlSelect = "";

                        for (int i = 0; i < credit_dtl.Count; i++)
                        {
                            if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "", "CCWR", UserID, host_name, ref DocNo, ref message))
                            {

                                DBCommand.Transaction.Rollback();
                                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            }

                            totalcredit += Convert.ToInt32(credit_dtl[i]["course_credits"].ToString());
                            SqlSelect += " insert into ws_connect_student_reg_dtl (doc_no,user_id,course_code,course_type,credits," +
                                " priority,status,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,credit_combination) " +
                                " VALUES('" + DocNo + "','" + UserID + "','" + credit_dtl[i]["course_code"].ToString() + "','" + credit_dtl[i]["course_type"].ToString() + "'," +
                                " '" + credit_dtl[i]["course_credits"].ToString() + "','" + credit_dtl[i]["priority"].ToString() + "','" + credit_dtl[i]["status"].ToString() + "','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "','N'," +
                                " '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss.ffffff") + "','" + host_name + "','" + credit_dtl[i]["credit_combination"].ToString() + "')";

                            if (i == 0)
                            {
                                SqlSelect += " Update ws_preference_submit_dtl set cancel_flag='Y',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "'" +
                                    " where user_id ='" + UserID + "' and semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + "'";

                                SqlSelect += " insert into ws_preference_submit_dtl (user_id,preference_save_time,status," +
                                   " semester_type,year_semester,cancel_flag,created_by,created_date,created_host) " +
                                   " VALUES('" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss.ffffff") + "'," +
                                   " '" + credit_dtl[0]["status"].ToString() + "','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "','N'," +
                                   " '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss.ffffff") + "','" + host_name + "')";
                            }
                        }
                        DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                        int res_insert_combination = DBCommand.ExecuteNonQuery();

                        if (res_insert_combination <= 0)
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            return false;
                        }

                    }
                    catch (Exception ex)
                    {

                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        return false;
                    }
                }
                catch (Exception ex)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                bool savestatus = SWS_Mandatory_Credit_Save(UserID, host_name, totalcredit);


                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            return true;
        }


        public bool SWS_Mandatory_Credit_Save(string UserID, string host_name, int RegisteredCredits)
        {

            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            DataTable GetDataForCredit = new DataTable();
            bool status_insert = true;

            GetDataForCredit = GetFeesCalculationAndVerificationCreditWise(dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString(), UserID);

            if (GetDataForCredit == null)
            {
                GetDataForCredit = Get_No_Apply_For_Elective_Course_user(UserID);

            }
            else { status_insert = false; }
            DBConnection.Open();
            DBCommand.Transaction = DBConnection.BeginTransaction();

            String SqlSelect = "";

            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                SqlSelect = "";

                if (!status_insert)
                {
                    SqlSelect += " Update ws_SWSCreditCalculation set CourseType ='M',M_credit='" + RegisteredCredits + "',RequiredToPay='" + Convert.ToInt32(GetDataForCredit.Rows[0]["GetRemainingCreditPayment"]) + "',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where UserID='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";
                }
                else
                {

                    SqlSelect = " IF EXISTS(select * from ws_SWSCreditCalculation WITH(NOLOCK) where semester_type = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' and UserID='" + UserID + "') "
                        + " BEGIN "
                        + " Update ws_SWSCreditCalculation set CourseType ='M',M_credit='" + RegisteredCredits + "',RequiredToPay='" + Convert.ToInt32(GetDataForCredit.Rows[0]["GetRemainingCreditPayment"]) + "',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where UserID='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N'"
                        + " END "
                    + " ELSE "
                        + " BEGIN "
                        + " INSERT INTO ws_SWSCreditCalculation (SrNo,UserID,RegisteredCredits,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,RequiredToPay,CourseType,M_credit) " +
                          " VALUES('1','" + UserID + "','" + RegisteredCredits + "','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "'," +
                          " 'N' , '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "','" + Convert.ToInt32(GetDataForCredit.Rows[0]["GetRemainingCreditPayment"]) + "','M','" + RegisteredCredits + @"')"
                        + " END ";



                    //SqlSelect += " INSERT INTO ws_SWSCreditCalculation (SrNo,UserID,RegisteredCredits,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,RequiredToPay,CourseType,M_credit) " +
                    //           " VALUES('1','" + UserID + "','" + RegisteredCredits + "','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "'," +
                    //        " 'N' , '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "','" + Convert.ToInt32(GetDataForCredit.Rows[0]["GetRemainingCreditPayment"]) + "','M','"+ RegisteredCredits + @"')";
                }




                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                int res_insert_combination = DBCommand.ExecuteNonQuery();

                if (res_insert_combination <= 0)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

            }
            catch (Exception ex)
            {

                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }


            DBCommand.Transaction.Commit();
            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

            return true;
        }


