                           from ws_connect_student_reg_dtl wcs WITH(NOLOCK)
						   inner join user_mst um WITH(NOLOCK) on um.user_id = wcs.user_id 
                           inner join ws_course_mst wcm WITH(NOLOCK) on wcm.course_code = wcs.course_code and wcm.semester_type =  wcs.semester_type and wcm.year_semester =  wcs.year_semester and wcm.cancel_flag='N'
