                           and wcs.cancel_flag IN ('N') and wcs.user_id='" + user_id + @"' and wcs.status in('P','A') and wcs.course_type ='E'
                           AND wcs.course_drop_status IS NULL 
                            ";

            SqlSelect += @" UNION Select wcs.user_id,wcs.course_code,wcs.course_type,wcs.credits,priority = '0',wcs.course_drop_status,wcs.status,FORMAT(wcs.created_date,'dd-MM-yyyy HH:mm:ss') created_date,
