            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";

            SqlSelect = @"select CASE wcs.course_type WHEN 'E' THEN('<p style=color:blue;>' + 'Elective Credit choice for Course  ' + wcs.credit_combination + '  Credit : ' + wcs.credits + '</p>') END as new_credit,
                           wcs.user_id,wcs.course_code,wcs.course_type,wcs.credits,wcs.priority,wcs.course_drop_status,wcs.status,FORMAT(wcs.created_date,'dd-MM-yyyy HH:mm:ss') created_date,
						   um.full_name,wcs.credit_combination,wcm.course_name,wcm.category_location_wise,FORMAT(wcm.start_date,'dd-MM-yyyy') start_date,FORMAT(wcm.end_date,'dd-MM-yyyy') end_date,
                           (select parameter_value from parameter_mst where parameter_name ='sws_drop_course_rights') as drop_option,
                           (select publish_flag from ws_publish_allocation_dtl where semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' 
                           and year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' and cancel_flag='N') as enable_allocation,wcs.doc_no
                           from ws_connect_student_reg_dtl wcs WITH(NOLOCK)
						   inner join user_mst um WITH(NOLOCK) on um.user_id = wcs.user_id 
                           inner join ws_course_mst wcm WITH(NOLOCK) on wcm.course_code = wcs.course_code and wcm.semester_type =  wcs.semester_type and wcm.year_semester =  wcs.year_semester and wcm.cancel_flag='N'
						   where wcs.semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' and wcs.year_semester ='" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' 
                           and wcs.cancel_flag='N' and wcs.user_id='" + user_id + @"' and wcs.status in('P','A')  and (wcs.course_drop_status is NULL or wcs.course_drop_status ='N') order by wcs.credit_combination asc, wcs.priority";


            return Get_data(SqlSelect);
        }

