        public DataTable SWS_Course_Reg_Check_allocation(string user_id, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = " IF EXISTS(select * from student_course_allocate_dtl WITH(NOLOCK) where semester_type = CASE WHEN '" + sem_code + "' = 'W' THEN 'M' ELSE '" + sem_code + "' END and year_semester='" + year_code + "' and cancel_flag='N' and user_id='" + user_id + "') "
                        + " BEGIN "
                        + " select * from student_course_allocate_dtl WITH(NOLOCK) where semester_type = CASE WHEN '" + sem_code + "' = 'W' THEN 'M' ELSE '" + sem_code + "' END and year_semester='" + year_code + "' and cancel_flag='N' and user_id='" + user_id + "'"
                        + " END "
                    + " ELSE "
                        + " BEGIN "
                        + " select * from ws_request_base_registration WITH(NOLOCK) where semester_type  = '" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' and user_id='" + user_id + "' "
                        + " END ";

            return Get_data(SqlSelect);
        }




        public DataTable Get_student_wise_reg_dtl_new(string user_id, string sem_code, string year_code, string user_type, string dept_code, string course_code, string prog_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @" select wcs.user_id,wcs.course_code,wcs.course_type,wcs.credits,wcs.priority,wcs.status,wcs.credit_combination,wcs.semester_type,wcs.year_semester,wcs.cancel_flag,
                           wc.course_name,um.full_name,('<p style=color:blue;>' + wcs.user_id + ' : ' +um.full_name + '</p>') as um_full_name,dm.dept_name,um.mail,wcs.course_drop_status
                           from ws_connect_student_reg_dtl as wcs
                           inner join ws_course_mst wc on wc.course_code = wcs.course_code and wc.cancel_flag= wcs.cancel_flag
                           and wc.semester_type= wcs.semester_type and wc.year_semester = wcs.year_semester
                           inner join user_mst um on um.user_id = wcs.user_id 
                           left join department_mst dm on dm.dept_code = wc.dept_code
                           where wcs.semester_type='" + sem_code + @"' and wcs.year_semester='" + year_code + @"' and wcs.cancel_flag='N'  and (wcs.status != 'S')";
            //if (user_type == "FA")
            //{
            //    SqlSelect += " and um.dept_code in(select dept_code from department_wise_user_dtl where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' and user_id='" + user_id + "') ";
            //}
            if (dept_code != "")
            {
                SqlSelect += " and um.dept_code ='" + dept_code + "' ";
            }
            if (prog_code != "")
            {
                SqlSelect += " and um.prog_code ='" + prog_code + "' ";
            }
            if (course_code != "")
            {
                SqlSelect += " and wc.course_code ='" + course_code + "' ";
            }

            SqlSelect += " order by  wcs.user_id asc,wcs.priority ";
            return Get_data(SqlSelect);
        }


        public DataTable Get_SWS_course_wise_Reg_student_count(string sem_code, string year_code, string course_type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = @"  select wcm.course_code,wcm.course_name,wcm.inhabitation,(select count(course_code )  from ws_connect_student_reg_dtl where semester_type='"+ sem_code + @"' 
            //				 and year_semester='"+ year_code + @"' and cancel_flag='N' and status='R'
            //				 and course_code = wcm.course_code
            //				 ) as Total_Reg_student,dm.dept_name,wcm.available_seat from ws_course_mst wcm 
            //				 inner join department_mst dm on dm.dept_code = wcm.dept_code
            //				 where wcm.semester_type='" + sem_code + @"' and wcm.year_semester='"+ year_code + @"' and wcm.cancel_flag='N' and wcm.course_type='E'  order by wcm.course_code asc";

            if (course_type == "M")
            {
                SqlSelect = "";
                SqlSelect = @"  select count(wcs.course_code) allocated_seat,t1.course_code,t1.course_name,t1.dept_name,t1.Total_Reg_student,t1.Total_pro_student,t1.available_seat,t1.semester_type,t1.year_semester from
                            (select wcm.course_code,wcm.course_name,wcm.inhabitation,(select count(course_code )  from ws_connect_student_reg_dtl where semester_type= '" + sem_code + @"'
                            and year_semester= '" + year_code + @"' and cancel_flag='N' and status='R' and course_type='M'
                            and course_code = wcm.course_code
                            ) as Total_Reg_student,

                            (select count(course_code )  from ws_connect_student_reg_dtl where semester_type= '" + sem_code + @"'
                            and year_semester= '" + year_code + @"' and cancel_flag='N' and status='P' and course_type='M'
                            and course_code = wcm.course_code
                            ) as Total_pro_student,

                            dm.dept_name,wcm.available_seat,wcm.semester_type,wcm.year_semester from ws_course_mst wcm 
                            inner join department_mst dm on dm.dept_code = wcm.dept_code
                            where wcm.semester_type= '" + sem_code + @"' and wcm.year_semester= '" + year_code + @"' and wcm.cancel_flag='N' and wcm.course_type='M'  ) t1
                            left join ws_connect_student_reg_dtl wcs on wcs.course_code = t1.course_code and wcs.status='P' and wcs.course_drop_status IS NULL
                            and wcs.semester_type= t1.semester_type and wcs.year_semester= t1.year_semester
                            group by wcs.course_code,t1.course_code,t1.course_name,t1.dept_name,t1.Total_Reg_student,t1.Total_pro_student,t1.available_seat,t1.semester_type,t1.year_semester
                            order by wcs.course_code asc";


            }
            else
            {
                SqlSelect = @"  select count(wcs.course_code) allocated_seat,t1.course_code,t1.course_name,t1.dept_name,t1.Total_Reg_student,t1.Total_pro_student,t1.available_seat,t1.semester_type,t1.year_semester from
                            (select wcm.course_code,wcm.course_name,wcm.inhabitation,(select count(course_code )  from ws_connect_student_reg_dtl where semester_type= '" + sem_code + @"'
                            and year_semester= '" + year_code + @"' and cancel_flag='N' and status='R' and course_type='E'
                            and course_code = wcm.course_code
                            ) as Total_Reg_student,
                            (select count(course_code )  from ws_connect_student_reg_dtl where semester_type= '" + sem_code + @"'
                            and year_semester= '" + year_code + @"' and cancel_flag='N' and status='P' and course_type='E'
                            and course_code = wcm.course_code
                            ) as Total_pro_student,
                            dm.dept_name,wcm.available_seat,wcm.semester_type,wcm.year_semester from ws_course_mst wcm 
                            inner join department_mst dm on dm.dept_code = wcm.dept_code
                            where wcm.semester_type= '" + sem_code + @"' and wcm.year_semester= '" + year_code + @"' and wcm.cancel_flag='N' and wcm.course_type='E'  ) t1
                            left join ws_connect_student_reg_dtl wcs on wcs.course_code = t1.course_code and wcs.status='P' and wcs.course_drop_status IS NULL
                            and wcs.semester_type= t1.semester_type and wcs.year_semester= t1.year_semester
                            group by wcs.course_code,t1.course_code,t1.course_name,t1.dept_name,t1.Total_Reg_student,t1.Total_pro_student,t1.available_seat,t1.semester_type,t1.year_semester
                            order by wcs.course_code asc";

            }
            return Get_data(SqlSelect);
        }

        public DataTable Get_mandatory_course_dtl(string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";
            SqlSelect = @" Select CAST(NULL AS NVARCHAR(250)) AS Paymentcredit,wsa.payment_response_code,FORMAT(wcm.start_date,'dd-MM-yyyy') start_date,FORMAT(wcm.end_date,'dd-MM-yyyy') end_date,STUFF((SELECT distinct ', ' + instructor_mst.instructor_name 
						   FROM ws_course_wise_instructor c2 WITH(NOLOCK)
						   inner join instructor_mst WITH(NOLOCK) on instructor_mst.instructor_code=c2.instructor_code and instructor_mst.cancel_flag='N'
						   WHERE wcm.course_code = c2.course_code and wcm.cancel_flag = 'N'
							        and wcm.semester_type = c2.semester_type and wcm.year_semester = c2.year_semester
						   FOR XML PATH(''), TYPE ).value('.', 'NVARCHAR(MAX)') ,1,2,'') instructor_name,wcsr.status, * from ws_course_mst wcm
                           left join ws_connect_student_reg_dtl wcsr on wcsr.course_code = wcm.course_code and wcsr.year_semester = wcm.year_semester
						    and wcsr.semester_type = wcm.semester_type and wcsr.cancel_flag = wcm.cancel_flag and wcsr.user_id = '" + user_id + @"'
                            and (wcsr.course_drop_status is NULL or wcsr.course_drop_status ='N')
                            LEFT JOIN ws_applicationpaymenttransaction wsa on wsa.user_id = '" + user_id + @"'
							and wsa.payment_response_code ='0' and wsa.manually_course_status ='M' and wsa.semester_type = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' and wsa.year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"'

                           where wcm.semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' and wcm.year_semester ='" + dt_current_sem.Rows[0]["year_code"].ToString() + @"'
                           and wcm.cancel_flag='N' and wcm.course_type='M' ORDER BY CASE WHEN wcsr.status = 'R' THEN 1 ELSE 2 END ";
            return Get_data(SqlSelect);
        }


        public DataTable Get_No_Apply_For_Elective_Course_user(string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";
            SqlSelect = @" SELECT 
                           t2.user_id,
                           t2.user_type,
                           t2.ApplyTotalCredit,
                           t2.FeesWaiverCredit,
                           t2.prof_details,
                           t2.GetRemainingCreditPayment,
                           t2.PerCreditPrice,
                           (t2.GetRemainingCreditPayment * t2.PerCreditPrice) AS TotalAmount
                           FROM (
                               SELECT 
                                   t1.user_id,
                                   t1.ApplyTotalCredit,
                                   t1.FeesWaiverCredit,
                                   t1.user_type,
                                   t1.prof_details,
                                   CASE 
                                       WHEN t1.ApplyTotalCredit > t1.FeesWaiverCredit THEN t1.ApplyTotalCredit - t1.FeesWaiverCredit
                                       ELSE 0
                                   END AS GetRemainingCreditPayment,
                                   CASE
                                       WHEN (t1.user_type = 'E' AND t1.prof_details = 'P') THEN 7500
                                       ELSE 6000
                                   END AS PerCreditPrice
                               FROM (
                                   SELECT 
                                       WCS.user_id, 
                                       CAST(SUM(CAST(WCS.credits AS decimal(10,2))) AS decimal(10,2)) AS ApplyTotalCredit,
                                       MAX(ISNULL(fees_waiver_credits, 0)) AS FeesWaiverCredit,
                                       MAX(um.user_type) AS user_type,
                                       MAX(um.prof_details) AS prof_details
                                   FROM 
                                       ws_connect_student_reg_dtl WCS
                                   LEFT JOIN 
                                       ws_user_fees_status wuf 
                                       ON wuf.user_id = WCS.user_id
                                       AND wuf.semester_type = WCS.semester_type 
                                       AND wuf.year_type = WCS.year_semester 
                                       AND wuf.cancel_flag = 'N'
                                   LEFT JOIN 
                                       user_mst um 
                                       ON um.user_id = WCS.user_id
                                   WHERE 
                                       WCS.semester_type = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' 
                                       AND WCS.year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' 
                                       AND WCS.cancel_flag = 'N'
                                       AND WCS.course_type = 'M' 
                                       AND WCS.user_id = '" + user_id + @"' 
                                   GROUP BY WCS.user_id ) t1 ) t2 ";

            return Get_data(SqlSelect);
        }
        public DataTable SWS_allow_registration_for_particular_student(string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            string semcode = "S";
            if (dt_current_sem.Rows[0]["sem_code"].ToString() == "W")
            {
                semcode = "M";
            }

            SqlSelect = " IF EXISTS( select user_id from ws_request_base_registration WITH(NOLOCK) where semester_type  = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag ='P' and user_id='" + user_id + "') "
                       + " BEGIN "
                       + " Select user_id,cancel_flag from ws_request_base_registration WITH(NOLOCK) where semester_type  = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag ='P' and user_id='" + user_id + "' "
                       + " END "
                   + " ELSE "
                       + " BEGIN "
                       + " Select user_id,cancel_flag from ws_request_base_registration WITH(NOLOCK) where semester_type  = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag ='N' and user_id='" + user_id + "' "
                       + " Union "
                       + " Select user_id,cancel_flag from student_course_allocate_dtl WITH(NOLOCK) where semester_type  = '" + semcode + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' and user_id='" + user_id + "'  "
                       + " END ";
            return Get_data(SqlSelect);
        }


