        public DataTable SWS_Student_Shortlist_Timewise(string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"  select  ROW_NUMBER() OVER ( ORDER BY wcs.created_date ) row_num,ROW_NUMBER() OVER ( PARTITION BY wcs.course_code ORDER BY wcs.created_date asc ) course_count,*
						    from ws_connect_student_reg_dtl wcs
                            inner join ws_course_mst wcm on wcm.course_code = wcs.course_code and wcm.semester_type= wcs.semester_type
						   and wcm.year_semester = wcs.year_semester and wcm.cancel_flag='N' and wcm.available_seat != '0'
						    where wcs.semester_type='" + sem_code + @"' and wcs.year_semester='" + year_code + @"' and wcs.cancel_flag='N' and wcs.status='R'  and wcs.course_type='E' 
						    and FORMAT(wcs.created_date,'dd-MM-yyyy') = FORMAT(GETDATE(),'dd-MM-yyyy') order by wcs.created_date asc ";


            return Get_data(SqlSelect);
        }

        public DataTable SWS_Student_Get_data_date_wise(string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @"  Select * From ws_preference_submit_dtl as wpsd
							inner join ws_applicationpaymenttransaction wp on wp.user_id = wpsd.user_id
							and wp.semester_type= wpsd.semester_type and wp.year_semester= wpsd.year_semester
							and FORMAT(wp.created_date,'dd-MM-yyyy') = FORMAT(wpsd.created_date,'dd-MM-yyyy')
							where wpsd.cancel_flag='N' and wpsd.semester_type='" + sem_code + @"' 
							and wpsd.year_semester='" + year_code + @"' and FORMAT (wpsd.preference_save_time,'dd-MM-yyyy') = FORMAT (GETDATE(),'dd-MM-yyyy') 
							and wp.payment_response_code ='0'
							and wpsd.status='R'  order by wpsd.preference_save_time asc ";


            return Get_data(SqlSelect);
        }


