        public DataTable Get_SWS_elective_course_data(string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            //SqlSelect = @"  select * from ws_course_mst where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' and course_type='E' and available_seat != '0'";
            SqlSelect = @" select ISNULL(res1.allocated_seats,0) allocated_seats,
						 (ws.available_seat - ISNULL(res1.allocated_seats,0)) available_seat,ws.available_seat as TotalSeats,
						 ws.doc_no,ws.course_code,ws.course_credits,ws.prerequisite 
						  from ws_course_mst ws
						 left join (select Count(user_id) allocated_seats,course_code from ws_connect_student_reg_dtl where semester_type = '" + sem_code + @"' and year_semester = '" + year_code + @"'
                         and cancel_flag='N' and status='P' and course_drop_status IS NULL group by course_code ) res1 on res1.course_code= ws.course_code
						 where ws.semester_type = '" + sem_code + @"' and ws.year_semester='" + year_code + @"' and ws.cancel_flag='N' and ws.course_type='E' and ws.available_seat != '0' ";

            return Get_data(SqlSelect);
        }

