        public bool sws_allocation_save(DataTable ws_course_data, string host_name, string UserID, string sem_code, string year_code)
        {
            try
            {

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";

                try
                {
                    // DataRow [] dataRows = ws_course_data.Select("status ='P'");
                    for (int i = 0; i < ws_course_data.Rows.Count; i++)
                    {
                        SqlSelect += " Update ws_connect_student_reg_dtl set status ='P',last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'," +
                        " last_modified_host = '" + host_name + "' where semester_type='" + sem_code + "' " +
                        " and year_semester='" + year_code + "' and doc_no ='" + ws_course_data.Rows[i]["doc_no"].ToString() + "' and cancel_flag='N' " +
                        " and FORMAT (created_date,'dd-MM-yyyy') = FORMAT (GETDATE(),'dd-MM-yyyy')  ";

                    }
                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                    int res_insert = DBCommand.ExecuteNonQuery();


                }
                catch (Exception ex)
                {
