        public bool SWSUpdatCredits(string host_name, string UserID, string sem_code, string year_code)
        {
            try
            {
                DataTable dt_data = GetCreditCount(sem_code, year_code);
                DataTable dt_registerCreditData = GetSWSCreditCalculationData(sem_code, year_code);
                DataTable dtExpiredData = GetDataForNotAllocatedCourse(sem_code, year_code);
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";
                string newstring = "";

                try
                {
                    for (int i = 0; i < dt_data.Rows.Count; i++)
                    {
                        DataRow[] dr = dt_registerCreditData.Select(" UserID ='" + dt_data.Rows[i]["user_id"].ToString() + "'");
                        if (dr.Length > 0)
                        {
                            int ProvisionallyAllocatedCredits = Convert.ToInt32(dt_data.Rows[i]["sumcredit"].ToString()) + Convert.ToInt32(dr[0]["ProvisionallyAllocatedCredits"].ToString());
                            int TotalAppliedCredit = Convert.ToInt32(dr[0]["TotalAppliedCredit"].ToString());
                            if (TotalAppliedCredit >= ProvisionallyAllocatedCredits)
                            {
                                int TotalRemainingCredits = TotalAppliedCredit - ProvisionallyAllocatedCredits;

                                SqlSelect += " Update  CreditCalculationDataTest Set CancelFlag ='Y' where UserID ='" + UserID + "' and SemesterType ='" + sem_code + @"' and YearSemester = '" + year_code + @"'";
                                SqlSelect += " Insert INTO CreditCalculationDataTest (UserID,TotalAppliedCredit,ProvisionallyAllocatedCredits,Status,TotalRemainingCredits,CancelFlag,SemesterType,YearSemester) Values('" + dt_data.Rows[i]["user_id"].ToString() + "','" + TotalAppliedCredit + "','" + ProvisionallyAllocatedCredits + "','TRUE','0','N','" + sem_code + @"','" + year_code + @"')";

                                SqlSelect += @" UPDATE ws_SWSCreditCalculation
                                                SET 

                                                    ProvisionallyAllocatedCredits = '" + ProvisionallyAllocatedCredits + @"',
                                                    TotalRemainingCredits= '" + TotalRemainingCredits + @"',
                                                    last_modified_by = '" + UserID + @"',
                                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                                    last_modified_host = '" + host_name + @"'
                                                WHERE UserID = '" + dt_data.Rows[i]["user_id"].ToString() + @"' 
                                                AND cancel_flag = 'N'
                                                AND semester_type = '" + sem_code + @"'
                                                AND year_semester = '" + year_code + @"'
                                                AND FORMAT(created_date, 'dd-MM-yyyy') = FORMAT(GETDATE(), 'dd-MM-yyyy') ";

                            }
                            else
                            {
                                int zerodata = 0;
                                // mismatch calculation

                                SqlSelect += " Update  CreditCalculationDataTest Set CancelFlag ='Y' where UserID ='" + UserID + "' and SemesterType ='" + sem_code + @"' and YearSemester = '" + year_code + @"'";
                                SqlSelect += " Insert INTO CreditCalculationDataTest (UserID,TotalAppliedCredit,ProvisionallyAllocatedCredits,Status,TotalRemainingCredits,CancelFlag,SemesterType,YearSemester) Values('" + dt_data.Rows[i]["user_id"].ToString() + "','" + TotalAppliedCredit + "','" + ProvisionallyAllocatedCredits + "','False','0','N','" + sem_code + @"','" + year_code + @"')";

                                SqlSelect += @" UPDATE ws_SWSCreditCalculation
                                                SET 
                                                    ProvisionallyAllocatedCredits = '" + ProvisionallyAllocatedCredits + @"',
                                                    TotalRemainingCredits= '" + zerodata + @"',
                                                    last_modified_by = '" + UserID + @"',
                                                    last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',
                                                    last_modified_host = '" + host_name + @"'
                                                WHERE UserID = '" + dt_data.Rows[i]["user_id"].ToString() + @"' 
                                                AND cancel_flag = 'N'
                                                AND semester_type = '" + sem_code + @"'
                                                AND year_semester = '" + year_code + @"'
                                                AND FORMAT(created_date, 'dd-MM-yyyy') = FORMAT(GETDATE(), 'dd-MM-yyyy') ";

                            }
                        }
                    }

                    if (dtExpiredData != null)
                    {
                        for (int p = 0; p < dtExpiredData.Rows.Count; p++)
                        {
                            DataRow[] dr_Expireddata = dt_registerCreditData.Select("UserID = '" + dtExpiredData.Rows[p]["user_id"].ToString() + "'");
                            if (dr_Expireddata.Length > 0)
                            {
                                SqlSelect += " Update ws_SWSCreditCalculation Set TotalRemainingCredits='" + dr_Expireddata[0]["RegisteredCredits"].ToString() + "' " +
                                    " ,last_modified_by='" + UserID + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' Where UserID ='" + dr_Expireddata[0]["UserID"].ToString() + "' " +
                                    " and cancel_flag ='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and FORMAT (created_date,'dd-MM-yyyy') = FORMAT (GETDATE(),'dd-MM-yyyy')";
                            }
                        }
                    }


                    // Only Register ws_credit_choice Table not apply for Choice Filling 



                    //SqlSelect += @" Select credit_choice,user_id  INTO #CreditChoicesTemp  from ws_credit_choice where cancel_flag ='N' AND  semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' 
                    //        AND FORMAT(created_date ,'dd-MM-yyyy') = FORMAT(GETDATE(),'dd-MM-yyyy')
                    //		And user_id not in (select user_id from ws_connect_student_reg_dtl where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"'
                    //		AND FORMAT(created_date ,'dd-MM-yyyy') = FORMAT(GETDATE(),'dd-MM-yyyy')) ";
                    //
                    //SqlSelect += @" Update ws_SWSCreditCalculation set TotalRemainingCredits = ISNULL((SELECT credit_choice 
                    //         FROM #CreditChoicesTemp 
                    //         WHERE #CreditChoicesTemp.user_id = ws_SWSCreditCalculation.UserID), 0)
                    //         WHERE semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag ='N'
                    //		 AND FORMAT(created_date ,'dd-MM-yyyy') = FORMAT(GETDATE(),'dd-MM-yyyy') AND UserID in (SELECT user_id 
                    //         FROM #CreditChoicesTemp ) ";
                    //
                    //SqlSelect += "  DROP TABLE #CreditChoicesTemp ";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                    int res_insert = DBCommand.ExecuteNonQuery();
                }
                catch (Exception ex)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            return true;
        }

