        public DataTable Get_fees_amount_pre_credit_WS_year_wise_new(string user_id, string user_type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            DataTable user_dtl = check_user_by_user_id(user_id);
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            string sem_code = dt_current_sem.Rows[0]["sem_code"].ToString();
            string year_code = dt_current_sem.Rows[0]["year_code"].ToString();
            DataTable dt_credit_combination = Student_Credit_Combination_dtl(user_id);
            if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "P")
            {
                user_type = "P";
            }
            else if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "S")
            {
                user_type = "S";
            }
            SqlSelect = @"IF Exists (select *  from ws_connect_student_reg_dtl 
                        where semester_type ='" + sem_code + @"' and year_semester='" + year_code + @"' 
                        and cancel_flag='N' and user_id='" + user_id + @"' and course_type ='M' and course_drop_status is null and status ='R') BEGIN  ";
            SqlSelect += @" Select TOp(1) (Case When SIGN(Total_credits - CAST(ISNULL(wsa.total_credit_pay,0) as int)) = '-1' Then '0' 
                            When Total_credits <= fees_waiver_credits Then '0'
                           When CAST(ISNULL(wsa.total_credit_pay,0) as int) < fees_waiver_credits Then (Total_credits - fees_waiver_credits )
                           Else Total_credits - CAST(ISNULL(wsa.total_credit_pay,0) as int) End ) as Total_credits_remaning_payment,
                            Case when FORMAT(GETDATE(),'dd-MM-yyyy') = FORMAT(wsa.created_date,'dd-MM-yyyy') Then 'True' Else 'False' End Payment_button_status,
                           * from (
                          Select Sum(CAST(t1.credits as int)) Total_course_credits, ";

            if (dt_credit_combination == null)
            {
                SqlSelect += @"(select SUM(CAST(ISNULL(credits,0) as int)) Total_credits from ws_connect_student_reg_dtl
						  
						  where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and user_id='" + user_id + @"' and cancel_flag='N'
                          and course_type='M' and status='R' and course_drop_status IS NULL
                           )
						  Total_credits,";
            }
            else
            {
                SqlSelect += @"(Select SUM(CAST(ISNULL(wcsr.credits,0) as int)) Total_credits from ws_credit_choice
						  left join ws_connect_student_reg_dtl wcsr on wcsr.semester_type = ws_credit_choice.semester_type
						  and wcsr.year_semester = ws_credit_choice.year_semester
						  and wcsr.user_id = ws_credit_choice.user_id and wcsr.course_type in('M','E') and wcsr.cancel_flag='N' and wcsr.course_drop_status is null
						  where ws_credit_choice.semester_type='" + sem_code + @"' and ws_credit_choice.year_semester='" + year_code + @"' and ws_credit_choice.user_id='" + user_id + @"' and ws_credit_choice.cancel_flag='N' 
                           )
						  Total_credits,";
            }


            SqlSelect += @" (select wuf.fees_waiver_credits from ws_user_fees_status as wuf 
                          where wuf.semester_type='" + sem_code + @"' and wuf.year_type='" + year_code + @"' and wuf.cancel_flag='N' 
                          and wuf.user_id='" + user_id + @"') as fees_waiver_credits,t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          from (
                          select um.user_type as student_user_type,um.prof_details, ws_connect_student_reg_dtl.* from ws_connect_student_reg_dtl 
                          inner join user_mst um on um.user_id = ws_connect_student_reg_dtl.user_id
                          where ws_connect_student_reg_dtl.user_id='" + user_id + @"' and ws_connect_student_reg_dtl.cancel_flag='N' and ws_connect_student_reg_dtl.status in('R') and (ws_connect_student_reg_dtl.course_drop_status is NULL or ws_connect_student_reg_dtl.course_drop_status ='N') 
                          and ws_connect_student_reg_dtl.course_type='E' and ws_connect_student_reg_dtl.semester_type='" + sem_code + @"' and ws_connect_student_reg_dtl.year_semester='" + year_code + @"'
                          
                          union 
                          select um.user_type as student_user_type,um.prof_details, ws_connect_student_reg_dtl.* from ws_connect_student_reg_dtl 
                          inner join user_mst um on um.user_id = ws_connect_student_reg_dtl.user_id
                          where ws_connect_student_reg_dtl.user_id='" + user_id + @"' and ws_connect_student_reg_dtl.cancel_flag='N' and ws_connect_student_reg_dtl.status in('R') and (ws_connect_student_reg_dtl.course_drop_status is NULL or ws_connect_student_reg_dtl.course_drop_status ='N') 
                          and ws_connect_student_reg_dtl.course_type='M' and ws_connect_student_reg_dtl.semester_type='" + sem_code + @"' and ws_connect_student_reg_dtl.year_semester='" + year_code + @"' ) as t1
                          group by t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          ) as t2
                          inner join ws_fees_amount_per_credit wfa on wfa.semester_type = t2.semester_type and wfa.year_semester = t2.year_semester
                          and wfa.cancel_flag='N' and wfa.year_code ='" + HttpContext.Current.Session["year_code"].ToString() + @"' 
                          and wfa.user_type='" + user_type + "'";

            SqlSelect += @" inner join parameter_mst pm on pm.user_type = '" + user_type + @"' and pm.parameter_name ='ws_fees_payment'
                          left join ws_applicationpaymenttransaction wsa on wsa.semester_type = t2.semester_type
                          and wsa.year_semester = t2.year_semester and wsa.user_id = '" + user_id + @"' and wsa.payment_response_code = '0' and wsa.manually_course_status is NULL  order by wsa.created_date desc ";


            SqlSelect += @" END ELSE BEGIN ";
            SqlSelect += @" Select TOp(1) (Case When SIGN(Total_credits - CAST(ISNULL(wsa.total_credit_pay,0) as int)) = '-1' Then '0' 
                            When Total_credits <= (CAST(ISNULL(wsa.total_credit_pay,0) as int) + fees_waiver_credits) Then '0'
                            When Total_credits <= fees_waiver_credits Then '0'  
                            When CAST(ISNULL(wsa.total_credit_pay,0) as int) < fees_waiver_credits Then (Total_credits - fees_waiver_credits ) 
                            Else Total_credits - CAST(ISNULL(wsa.total_credit_pay,0) as int) End ) as Total_credits_remaning_payment,
                            Case when FORMAT(GETDATE(),'dd-MM-yyyy') = FORMAT(wsa.created_date,'dd-MM-yyyy') Then 'True' Else 'False' End Payment_button_status,
                           * from (
                          Select Sum(CAST(t1.credits as int)) Total_course_credits,
                          (Select CAST (credit_choice as int) + CAST(ISNULL(wcsr.credits,0) as int) Total_credits from ws_credit_choice
						  left join ws_connect_student_reg_dtl wcsr on wcsr.semester_type = ws_credit_choice.semester_type
						  and wcsr.year_semester = ws_credit_choice.year_semester
						  and wcsr.user_id = ws_credit_choice.user_id and wcsr.course_type='M' and wcsr.cancel_flag='N'
						  where ws_credit_choice.semester_type='" + sem_code + @"' and ws_credit_choice.year_semester='" + year_code + @"' and ws_credit_choice.user_id='" + user_id + @"' and ws_credit_choice.cancel_flag='N' 
                          
                           )
						  Total_credits,
                          (select wuf.fees_waiver_credits from ws_user_fees_status as wuf 
                          where wuf.semester_type='" + sem_code + @"' and wuf.year_type='" + year_code + @"' and wuf.cancel_flag='N' 
                          and wuf.user_id='" + user_id + @"') as fees_waiver_credits,t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          from (
                          select um.user_type as student_user_type,um.prof_details, ws_connect_student_reg_dtl.* from ws_connect_student_reg_dtl 
                          inner join user_mst um on um.user_id = ws_connect_student_reg_dtl.user_id
                          where ws_connect_student_reg_dtl.user_id='" + user_id + @"' and ws_connect_student_reg_dtl.cancel_flag='N' and ws_connect_student_reg_dtl.status in('R') and (ws_connect_student_reg_dtl.course_drop_status is NULL or ws_connect_student_reg_dtl.course_drop_status ='N') 
                          and ws_connect_student_reg_dtl.course_type='E' and ws_connect_student_reg_dtl.semester_type='" + sem_code + @"' and ws_connect_student_reg_dtl.year_semester='" + year_code + @"'
                          
                          union 
                          select um.user_type as student_user_type,um.prof_details, ws_connect_student_reg_dtl.* from ws_connect_student_reg_dtl 
                          inner join user_mst um on um.user_id = ws_connect_student_reg_dtl.user_id
                          where ws_connect_student_reg_dtl.user_id='" + user_id + @"' and ws_connect_student_reg_dtl.cancel_flag='N' and ws_connect_student_reg_dtl.status in('R') and (ws_connect_student_reg_dtl.course_drop_status is NULL or ws_connect_student_reg_dtl.course_drop_status ='N') 
                          and ws_connect_student_reg_dtl.course_type='M' and ws_connect_student_reg_dtl.semester_type='" + sem_code + @"' and ws_connect_student_reg_dtl.year_semester='" + year_code + @"' ) as t1
                          group by t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          ) as t2
                          inner join ws_fees_amount_per_credit wfa on wfa.semester_type = t2.semester_type and wfa.year_semester = t2.year_semester
                          and wfa.cancel_flag='N' and wfa.year_code ='" + HttpContext.Current.Session["year_code"].ToString() + @"' 
                          and wfa.user_type='" + user_type + "'";

            SqlSelect += @" inner join parameter_mst pm on pm.user_type = '" + user_type + @"' and pm.parameter_name ='ws_fees_payment'
                          left join ws_applicationpaymenttransaction wsa on wsa.semester_type = t2.semester_type
                          and wsa.year_semester = t2.year_semester and wsa.user_id = '" + user_id + @"' and wsa.payment_response_code = '0' and wsa.manually_course_status is NULL  order by wsa.created_date desc ";

            SqlSelect += @" END ";

            return Get_data(SqlSelect);
        }


        public DataTable calculate_fees_amount(string user_id, string user_type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            string sem_code = dt_current_sem.Rows[0]["sem_code"].ToString();
            string year_code = dt_current_sem.Rows[0]["year_code"].ToString();
            DataTable user_dtl = check_user_by_user_id(user_id);
            string amount = "6000";
            if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "P")
            {
                user_type = "P";
                amount = "7500";
            }
            else if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "S")
            {
                user_type = "S";
                amount = "6000";
            }
            //Sum(CAST(credits as int) * "+ amount + @") Total_course_credits,
            //(select credit_choice from ws_credit_choice where user_id='" + user_id + @"' and semester_type ='" + sem_code + @"' and year_semester='" + year_code + @"' and cancel_flag='N')
            SqlSelect = @" select ((res3.Total_course_credits) - (res3.Total_credits_amount + res3.Total_payment)) payamount,res3.user_id,res3.Total_course_credits,res3.Total_credits_amount,res3.Total_payment from (
						  select Sum(CAST(credits as int) *  " + amount + @") Total_course_credits,
                          wcs.user_id,Max(ISNULL(res1.Total_credits_amount,0)) Total_credits_amount,
						  Max(ISNULL(res2.fees_waiver_credits,0) * " + amount + @") Total_payment from  ws_connect_student_reg_dtl  wcs

						  left join (select Sum(CAST(amount as int)) Total_credits_amount,user_id from ws_applicationpaymenttransaction where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and payment_response_code ='0' and user_id ='" + user_id + @"'
						  
						  Group by user_id) res1 on res1.user_id = wcs.user_id

						  left join(select fees_waiver_credits,user_id from ws_user_fees_status where semester_type='" + sem_code + @"' and year_type='" + year_code + @"' and cancel_flag='N' and user_id ='" + user_id + @"'
						  ) res2 on res2.user_id = wcs.user_id

						  where wcs.semester_type='" + sem_code + @"' and wcs.year_semester='" + year_code + @"'  and wcs.status in( 'A','R','P')   and wcs.course_drop_status IS NULL
						  and wcs.cancel_flag='N' and wcs.user_id='" + user_id + @"' 
						  Group by wcs.user_id ) res3";

            //where wcs.semester_type='" + sem_code + @"' and wcs.year_semester='"+ year_code + @"'  and wcs.status in( 'A','R','P')   and wcs.course_drop_status IS NULL


            return Get_data(SqlSelect);
        }










        public DataTable Get_fees_amount_pre_credit_WS_year_wise_manually(string user_id, string user_type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            string sem_code = dt_current_sem.Rows[0]["sem_code"].ToString();
            string year_code = dt_current_sem.Rows[0]["year_code"].ToString();
            DataTable user_dtl = check_user_by_user_id(user_id);
            if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "P")
            {
                user_type = "P";
            }
            else if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "S")
            {
                user_type = "S";
            }

            SqlSelect = @" select Top(1) 
                          (Case When SIGN(Total_credits - CAST(ISNULL(wsa.total_credit_pay,0) as int)) = '-1' Then '0'  When Total_credits <= fees_waiver_credits Then '0' 
                          When CAST(ISNULL(wsa.total_credit_pay,0) as int) < fees_waiver_credits Then (Total_credits - fees_waiver_credits )
                          When total_allocated_credit >= fees_waiver_credits Then (Total_credits - total_allocated_credit )
                          Else 
                          Total_credits - CAST(ISNULL(wsa.total_credit_pay,0) as int) End ) as Total_credits_remaning_payment,
                          Case when FORMAT(GETDATE(),'dd-MM-yyyy') = FORMAT(wsa.created_date,'dd-MM-yyyy') Then 'True' Else 'False' End Payment_button_status,
                        
                          * from (
                          select Sum(CAST(t1.credits as int)) Total_credits,(select wuf.fees_waiver_credits from ws_user_fees_status as wuf 
                          where wuf.semester_type='" + sem_code + @"' and wuf.year_type='" + year_code + @"' and wuf.cancel_flag='N' 
                          and wuf.user_id='" + user_id + @"') as fees_waiver_credits
                         ,ISNULL((select sum(CAST(wswc.credits as int)) credits from ws_student_wise_course_dtl as wswc 
                          where wswc.semester_type='" + sem_code + @"' and wswc.year_semester='" + year_code + @"' and wswc.cancel_flag='N' and wswc.status ='A'  
                          and wswc.user_id='" + user_id + @"'), '0') as total_allocated_credit,
                          t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          from (
                          select um.user_type as student_user_type,um.prof_details, ws_connect_student_reg_dtl.* from ws_connect_student_reg_dtl 
                          inner join user_mst um on um.user_id = ws_connect_student_reg_dtl.user_id
                          where ws_connect_student_reg_dtl.user_id='" + user_id + @"' and ws_connect_student_reg_dtl.cancel_flag='N' and ws_connect_student_reg_dtl.status in('R','A')  and (course_drop_status is NULL or course_drop_status ='N') 
                          and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"') as t1
                          group by t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          ) as t2 
                          inner join ws_fees_amount_per_credit wfa on wfa.semester_type = t2.semester_type and wfa.year_semester = t2.year_semester
                          and wfa.cancel_flag='N' and wfa.year_code ='" + HttpContext.Current.Session["year_code"].ToString() + @"' 
                          and wfa.user_type='" + user_type + "'";

            SqlSelect += @" left join ws_applicationpaymenttransaction wsa on wsa.semester_type = t2.semester_type
                          and wsa.year_semester = t2.year_semester and wsa.user_id = '" + user_id + @"' and wsa.payment_response_code = '0'   order by wsa.created_date desc ";


            return Get_data(SqlSelect);
        }


        public DataTable Get_fees_amount_pre_credit_WS_year_wise_manually_new(string user_id, string user_type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            string sem_code = dt_current_sem.Rows[0]["sem_code"].ToString();
            string year_code = dt_current_sem.Rows[0]["year_code"].ToString();
            DataTable user_dtl = check_user_by_user_id(user_id);
            if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "P")
            {
                user_type = "P";
            }
            else if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "S")
            {
                user_type = "S";
            }

            SqlSelect = @" select * from (
                          select Sum(CAST(t1.credits as int)) Total_credits,(select wuf.fees_waiver_credits from ws_user_fees_status as wuf 
                          where wuf.semester_type='" + sem_code + @"' and wuf.year_type='" + year_code + @"' and wuf.cancel_flag='N' 
                          and wuf.user_id='" + user_id + @"') as fees_waiver_credits
                         ,ISNULL((select sum(CAST(wswc.credits as int)) credits from ws_student_wise_course_dtl as wswc 
                          where wswc.semester_type='" + sem_code + @"' and wswc.year_semester='" + year_code + @"' and wswc.cancel_flag='N' and wswc.status ='A'  
                          and wswc.user_id='" + user_id + @"'), '0') as total_allocated_credit,
                          t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          from (
                          select um.user_type as student_user_type,um.prof_details, ws_connect_student_reg_dtl.* from ws_connect_student_reg_dtl 
                          inner join user_mst um on um.user_id = ws_connect_student_reg_dtl.user_id
                          where ws_connect_student_reg_dtl.user_id='" + user_id + @"' and ws_connect_student_reg_dtl.cancel_flag='N' and ws_connect_student_reg_dtl.status in('M','A') and manually_course_status = 'M' and (course_drop_status is NULL or course_drop_status ='N') 
                          and semester_type='" + sem_code + @"' and year_semester='" + year_code + @"') as t1
                          group by t1.semester_type,t1.year_semester,t1.student_user_type,t1.prof_details
                          ) as t2
                          inner join ws_fees_amount_per_credit wfa on wfa.semester_type = t2.semester_type and wfa.year_semester = t2.year_semester
                          and wfa.cancel_flag='N' and wfa.year_code ='" + HttpContext.Current.Session["year_code"].ToString() + @"' 
                          and wfa.user_type='" + user_type + "'";

            SqlSelect += @" left join ws_applicationpaymenttransaction wsa on wsa.semester_type = t2.semester_type
                          and wsa.year_semester = t2.year_semester and wsa.user_id = '" + user_id + @"' and wsa.payment_response_code = '0' and wsa.manually_course_status ='M'";


            return Get_data(SqlSelect);
        }


