						   um.full_name,wcs.credit_combination,wcm.course_name,wcm.category_location_wise,FORMAT(wcm.start_date,'dd-MM-yyyy') start_date,FORMAT(wcm.end_date,'dd-MM-yyyy') end_date,
                           wcm.dept_code,wcm.gpa_status,um.year_code
                           from ws_connect_student_reg_dtl wcs WITH(NOLOCK)
						   inner join user_mst um WITH(NOLOCK) on um.user_id = wcs.user_id 
                           inner join ws_course_mst wcm WITH(NOLOCK) on wcm.course_code = wcs.course_code and wcm.semester_type =  wcs.semester_type and wcm.year_semester =  wcs.year_semester and wcm.cancel_flag='N'
						   where wcs.semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' and wcs.year_semester ='" + dt_current_sem.Rows[0]["year_code"].ToString() + @"'
                           and wcs.cancel_flag='N' and wcs.user_id='" + user_id + @"' and wcs.status in('R') and wcs.course_type ='M' and Format (wcs.created_date,'dd-MM-yyyy') = Format (GETDATE(),'dd-MM-yyyy') and (wcs.course_drop_status is NULL or wcs.course_drop_status ='N')";



            return Get_data(SqlSelect);
        }

        public BLReturnObject save_SWSCourse_fees_payment(DataSet ds_UploadData, string compnyid, String UserID, String HostName, ref XSD.Masters_WS.DS_Payment_WS ref_objCourseMaster_upload)
        {
            BLReturnObject objBLReturnObject = new BLReturnObject();
            try
            {
                objBLReturnObject.ExecutionStatus = 2;
                objBLReturnObject.ServerMessage = "Insufficient Arguments, Operation Canceled.";

                if (ds_UploadData == null)
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "There is no data to save";
                    return objBLReturnObject;
                }

                DS_Payment_WS server_course_master = (DS_Payment_WS)ds_UploadData;

                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String message = "";
                String DocNo = "";
                String DocNo1 = "";

                DS_Payment_WS objCourseMaster_upload = new DS_Payment_WS();

                objCourseMaster_upload.EnforceConstraints = false;

                for (int mprCnt = 0; mprCnt < server_course_master.ws_applicationpaymenttransaction.Rows.Count; mprCnt++)
                {
                    objCourseMaster_upload.ws_applicationpaymenttransaction.ImportRow(server_course_master.ws_applicationpaymenttransaction.Rows[mprCnt]);
                    if (objCourseMaster_upload.ws_applicationpaymenttransaction[mprCnt].transaction_id == "1")
                    {
                        objDocument = new Document();
                        if (!objDocument.W_GetNextDocumentNo(ref DBCommand, compnyid, "SPT", UserID, HostName, ref DocNo, ref message))
                        {
                            DBCommand.Transaction.Rollback();
                            if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                            objBLReturnObject.ExecutionStatus = 2;
                            return objBLReturnObject;
                        }
                        objCourseMaster_upload.ws_applicationpaymenttransaction[mprCnt].transaction_id = "TRNSID" + DocNo;
                        DocNo1 = "TRNSID" + DocNo;
                    }
                }

                //for (int mprCnt = 0; mprCnt < server_course_master.student_smartcard_reissue_dtl.Rows.Count; mprCnt++)
                //{
                //    objCourseMaster_upload.student_smartcard_reissue_dtl.ImportRow(server_course_master.student_smartcard_reissue_dtl.Rows[mprCnt]);
                //    objCourseMaster_upload.student_smartcard_reissue_dtl[mprCnt].doc_no = DocNo1;
                //}

                objCourseMaster_upload.EnforceConstraints = true;
                BLGeneralUtil.UpdateTableInfo objUpdateTableInfo;

                objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.ws_applicationpaymenttransaction, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.ws_applicationpaymenttransaction.Rows.Count)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                    return objBLReturnObject;
                }

                //objUpdateTableInfo = BLGeneralUtil.UpdateTable(ref DBCommand, objCourseMaster_upload.student_smartcard_reissue_dtl, BLGeneralUtil.UpdateWhereMode.KeyColumnsOnly, BLGeneralUtil.UpdateMethod.DeleteAndInsert);
                //if (objUpdateTableInfo.Status == true && objUpdateTableInfo.TotalRowsAffected != objCourseMaster_upload.student_smartcard_reissue_dtl.Rows.Count)
                //{
                //    DBCommand.Transaction.Rollback();
                //    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                //    objBLReturnObject.ExecutionStatus = 2;
                //    objBLReturnObject.ServerMessage = "Fail to Save Details.";
                //    return objBLReturnObject;
                //}

                else
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    objBLReturnObject.ExecutionStatus = 1;
                    objBLReturnObject.ServerMessage = "Data Saved Successfully";

                    ref_objCourseMaster_upload = objCourseMaster_upload;

                    return objBLReturnObject;
                }
            }

            catch (Exception ex)
            {
                objBLReturnObject.ServerMessage = "Problem in save data";
            }
            return objBLReturnObject;
        }


