        public bool sws_course_allocation_dtl(string UserID, string transaction_id)
        {
            ServerLog.ExceptionLog("Sws sws_course_allocation_dtl  : " + UserID + " " + transaction_id);

            string host_name = HttpContext.Current.Request.UserHostName.ToString();

            ServerLog.ExceptionLog("Sws sws_course_allocation_dtl  : " + host_name);
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            // DataTable dt_swsCreditCount = SWSCreditCalculation(UserID, dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString());
            try
            {
                if (DBConnection.State != ConnectionState.Open)
                    DBConnection.Open();

                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";

                try
                {
                    SqlSelect += @" Update ws_preference_submit_dtl set payment_status='Y',last_modified_by='" + UserID + @"',last_modified_date='" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',last_modified_host='" + host_name + @"' 
                                    where user_id ='" + UserID + "' and cancel_flag='N' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + @"'
                                    and FORMAT(preference_save_time,'dd-MM-yyyy') = FORMAT(GETDATE(), 'dd-MM-yyyy')  and status = 'R'";

                    SqlSelect += " IF EXISTS(select * from ws_user_fees_status where semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_type='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag = 'N' and (fees_status Is Null or fees_status = 'N') and user_id='" + UserID + "')  BEGIN ";
                    SqlSelect += " Update ws_user_fees_status set fees_status='Y',last_modified_by ='" + UserID + "',last_midified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'," +
                        " last_modified_host = '" + host_name + "' where user_id='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' " +
                        " and year_type='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";
                    SqlSelect += " END ";


                    ServerLog.ExceptionLog("Sws ExecuteNonQuery Result  : " + SqlSelect);

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                    int res_insert = DBCommand.ExecuteNonQuery();

                }
                catch (Exception ex)
                {
                    ServerLog.ExceptionLog("Sws EX  : " + ex.Message);
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                bool responsestatus = WS_DetailsUpdate_AfterPayment(dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString(), UserID, transaction_id);
                return true;
            }
            catch (Exception ex)
            {

                ServerLog.ExceptionLog("Second Sws EX  : " + ex.Message);
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            return true;
        }


        public dynamic WS_DetailsUpdate_AfterPayment(string sem_code, string year_code, string user_id, string transaction_id)
        {
            ServerLog.ExceptionLog("WS_DetailsUpdate_AfterPayment Start ");
            string host_name = HttpContext.Current.Request.UserHostName.ToString();
            try
            {
                if (DBConnection.State != ConnectionState.Open)
                    DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";
                DataTable dt_swsCreditCount = SWSCreditCalculation(user_id, sem_code, year_code);
                //DataTable dt_waiver_credit =
                try
                {
                    if (transaction_id != "" && dt_swsCreditCount != null)
                    {
                        int PaidFeesCredit = Convert.ToInt32(dt_swsCreditCount.Rows[0]["PaidFeesCredit"].ToString());
                        int RequiredToPay = Convert.ToInt32(dt_swsCreditCount.Rows[0]["RequiredToPay"].ToString());

                        int paidFeesCredit = string.IsNullOrEmpty(dt_swsCreditCount.Rows[0]["PaidFeesCredit"].ToString()) ? 0 : Convert.ToInt32(dt_swsCreditCount.Rows[0]["PaidFeesCredit"]);
                        int requiredToPay = string.IsNullOrEmpty(dt_swsCreditCount.Rows[0]["RequiredToPay"].ToString()) ? 0 : Convert.ToInt32(dt_swsCreditCount.Rows[0]["RequiredToPay"]);

                        int TotalFeesPaid = PaidFeesCredit + RequiredToPay;

                        SqlSelect += " update ws_SWSCreditCalculation set cancel_flag='Y',last_modified_by='" + user_id + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where UserID='" + user_id + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' ";

                        SqlSelect += " INSERT INTO ws_SWSCreditCalculation (SrNo,UserID,TotalAppliedCredit,WaiverCredit,semester_type,year_semester,cancel_flag,created_by,created_date,created_host,RegisteredCredits,RequiredToPay,PaidFeesCredit,ProvisionallyAllocatedCredits,DropCredits,TotalRemainingCredits) " +
                                   " VALUES('" + dt_swsCreditCount.Rows.Count + "','" + user_id + "','" + dt_swsCreditCount.Rows[0]["TotalAppliedCredit"].ToString() + "','" + dt_swsCreditCount.Rows[0]["WaiverCredit"].ToString() + "','" + sem_code + "','" + year_code + "'," +
                                   " 'N' , '" + user_id + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "','" + dt_swsCreditCount.Rows[0]["RegisteredCredits"].ToString() + "','" + dt_swsCreditCount.Rows[0]["RequiredToPay"].ToString() + "','" + TotalFeesPaid + "','" + dt_swsCreditCount.Rows[0]["ProvisionallyAllocatedCredits"].ToString() + "','" + dt_swsCreditCount.Rows[0]["DropCredits"].ToString() + "','" + dt_swsCreditCount.Rows[0]["TotalRemainingCredits"].ToString() + "')";

                    }

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    int res_insert = DBCommand.ExecuteNonQuery();

                }
                catch (Exception ex)
                {
                    DBCommand.Transaction.Rollback();
                    ServerLog.ExceptionLog(ex.Message);
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                ServerLog.ExceptionLog(ex.Message);
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            return true;
        }


        public bool sws_course_allocation_dtl_new(string UserID)
        {
            string host_name = HttpContext.Current.Request.UserHostName.ToString();

            String message = "";
            String DocNo = "";
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            DataTable dt_user_dtl = get_user_dept_code_student(UserID);
            DataTable dt_credit_param_data = Get_current_total_pay_credit(UserID);
            DataTable dt_current_credit_data = Student_Credit_select_dtl(UserID);
            DataTable dt_sws_mandotry_data = Get_sws_mandotry_course_dtl(UserID, dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString());

            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";

                try
                {
                    SqlSelect += " Insert into ws_preference_submit_dtl (user_id,preference_save_time,status," +
                                 " semester_type,year_semester,cancel_flag,created_by,created_date,created_host) " +
                                 " VALUES('" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss.ffffff") + "'," +
                                 " 'Y','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "','N'," +
                                 " '" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss.ffffff") + "','" + host_name + "')";


                    ServerLog.ExceptionLog("Sws changes 1 : " + SqlSelect);
                    Document objDocument = new Document();
                    if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "2000", "SPT", UserID, host_name, ref DocNo, ref message))
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                    }

                    string doc_noe = "TRNSID" + dt_current_sem.Rows[0]["sem_code"].ToString() + dt_current_sem.Rows[0]["year_code"].ToString() + DocNo;

                    SqlSelect += @"insert into ws_applicationpaymenttransaction(transaction_id,user_id,current_sem_code,payment_send_flag,payment_return_flag,semester_type,year_semester,dept_id,payment_response_code,payment_response_msg,
						   amount,status_is_active,created_by,created_date,created_host,total_amount,total_credit,total_credit_pay)
						   values('" + doc_noe + "','" + UserID + "','0','Y','Y','" + dt_current_sem.Rows[0]["sem_code"].ToString() + "','" + dt_current_sem.Rows[0]["year_code"].ToString() + "','" + dt_user_dtl.Rows[0]["dept_code"] + "','0','Waiver Transaction Successfull'," +
                           " '0','Y','" + UserID + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "','0' ";

                    if (dt_credit_param_data != null && dt_current_credit_data != null)
                    {

                        if (Convert.ToInt32(dt_credit_param_data.Rows[0]["total_credit_pay"].ToString()) >= Convert.ToInt32(dt_current_credit_data.Rows[0]["credit_choice"].ToString()))
                        {
                            SqlSelect += @",'" + dt_current_credit_data.Rows[0]["credit_choice"] + "','" + dt_credit_param_data.Rows[0]["total_credit_pay"] + "'";
                        }
                        else
                        {
                            SqlSelect += @",'" + dt_current_credit_data.Rows[0]["credit_choice"] + "','" + dt_credit_param_data.Rows[0]["total_credit_pay"] + "'";
                        }
                    }
                    else
                    {
                        if (dt_current_credit_data != null)
                        {
                            SqlSelect += @",'" + dt_current_credit_data.Rows[0]["credit_choice"] + "','" + dt_current_credit_data.Rows[0]["credit_choice"] + "'";
                        }
                        else
                        {
                            SqlSelect += @",'" + dt_sws_mandotry_data.Rows[0]["credits"] + "','" + dt_sws_mandotry_data.Rows[0]["credits"] + "'";
                        }

                    }

                    SqlSelect += @" )";


                    DataTable dt_swsCreditCount = SWSCreditCalculation(UserID, dt_current_sem.Rows[0]["sem_code"].ToString(), dt_current_sem.Rows[0]["year_code"].ToString());

                    if (dt_swsCreditCount != null && dt_swsCreditCount.Rows[0]["RequiredToPay"].ToString() == "0")
                    {
                        SqlSelect += " update ws_SWSCreditCalculation set cancel_flag='Y',last_modified_by='" + UserID + @"',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' where UserID='" + UserID + "' and semester_type='" + dt_current_sem.Rows[0]["sem_code"].ToString() + "' and year_semester='" + dt_current_sem.Rows[0]["year_code"].ToString() + "' and cancel_flag='N' ";

                        if (dt_swsCreditCount != null)
                        {
                            string Host = HttpContext.Current.Request.UserHostName;
                            string Date = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                            string semester_code = dt_current_sem.Rows[0]["sem_code"].ToString();
                            string year_code = dt_current_sem.Rows[0]["year_code"].ToString();
                            int PaidFeesCreditAdd = 0;
                            int PaidFeesCredit = Convert.ToInt32(dt_swsCreditCount.Rows[0]["PaidFeesCredit"].ToString());
                            if (Convert.ToInt32(dt_swsCreditCount.Rows[0]["RequiredToPay"].ToString()) != 0)
                            {
                                PaidFeesCreditAdd = PaidFeesCredit + Convert.ToInt32(dt_swsCreditCount.Rows[0]["RequiredToPay"].ToString());
                            }
                            else { PaidFeesCreditAdd = PaidFeesCredit; }




                            SqlSelect += " INSERT INTO ws_SWSCreditCalculation (SrNo, UserID, TotalAppliedCredit, WaiverCredit, PaidFeesCredit, ProvisionallyAllocatedCredits, DropCredits, " +
                                   " TotalRemainingCredits, RegisteredCredits, RequiredToPay, semester_type, year_semester, cancel_flag,created_by, created_date, created_host) " +
                                   " VALUES (" +
                                     FormatValue(dt_swsCreditCount.Rows[0]["SrNo"]) + "," +
                                     FormatValue(UserID) + "," +
                                     FormatValue(dt_swsCreditCount.Rows[0]["TotalAppliedCredit"]) + "," +
                                     FormatValue(dt_swsCreditCount.Rows[0]["WaiverCredit"]) + "," +
                                     FormatValue(PaidFeesCreditAdd) + "," +
                                     FormatValue(dt_swsCreditCount.Rows[0]["ProvisionallyAllocatedCredits"]) + "," +
                                     FormatValue(dt_swsCreditCount.Rows[0]["DropCredits"]) + "," +
                                     FormatValue(dt_swsCreditCount.Rows[0]["TotalRemainingCredits"]) + "," +
                                     FormatValue(dt_swsCreditCount.Rows[0]["RegisteredCredits"]) + "," +
                                     FormatValue(dt_swsCreditCount.Rows[0]["RequiredToPay"]) + "," +
                                     FormatValue(dt_current_sem.Rows[0]["sem_code"].ToString()) + "," +
                                     FormatValue(dt_current_sem.Rows[0]["year_code"].ToString()) + ",'N'," +
                                     FormatValue(UserID) + "," +
                                     FormatValue(Date) + "," +
                                     FormatValue(Host) +
                                     ")";
                        }


                    }

                    ServerLog.ExceptionLog("Sws changes 2 : " + SqlSelect);
                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    int res_insert = DBCommand.ExecuteNonQuery();
                    ServerLog.ExceptionLog("Sws ExecuteNonQuery Result  : " + SqlSelect);



                }
                catch (Exception ex)
                {
                    ServerLog.ExceptionLog("Sws EX  : " + ex.Message);
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            return true;
        }

