        public DataTable ws_course_allocate_user_for_send_mail(string sem_code, string year_code, string course_type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            if (course_type == "M")
            {
                SqlSelect = @" select student_course_allocate_dtl.user_id,SUM(cast(credits as int)) ,user_mst.dept_code , user_mst.prog_code ,user_mst.mail
                        from ws_connect_student_reg_dtl as student_course_allocate_dtl
                        inner join user_mst on student_course_allocate_dtl.user_id = user_mst.user_id
                        where semester_type =@sem_code and year_semester =@year_code and student_course_allocate_dtl.cancel_flag ='N' and student_course_allocate_dtl.status = 'A' and student_course_allocate_dtl.course_type='M'
                        and user_mst.user_status_flag ='A' and user_mst.cancel_flag ='N' and (student_course_allocate_dtl.course_drop_status is NULL or student_course_allocate_dtl.course_drop_status = 'N')
                        group by student_course_allocate_dtl.user_id,user_mst.dept_code,user_mst.prog_code,user_mst.mail
                        order by user_mst.dept_code,user_mst.prog_code";
            }
            else
            {
                SqlSelect = @" select student_course_allocate_dtl.user_id,SUM(cast(credits as int)) ,user_mst.dept_code , user_mst.prog_code ,user_mst.mail
                        from ws_connect_student_reg_dtl as student_course_allocate_dtl
                        inner join user_mst on student_course_allocate_dtl.user_id = user_mst.user_id
                        where semester_type =@sem_code and year_semester =@year_code and student_course_allocate_dtl.cancel_flag ='N' and student_course_allocate_dtl.status = 'A'
                        and user_mst.user_status_flag ='A' and user_mst.cancel_flag ='N' and (student_course_allocate_dtl.course_drop_status is NULL or student_course_allocate_dtl.course_drop_status = 'N')
                        group by student_course_allocate_dtl.user_id,user_mst.dept_code,user_mst.prog_code,user_mst.mail
                        order by user_mst.dept_code,user_mst.prog_code";
            }
            IDataParameter para2 = DBObjectFactory.GetParameterObject();

            para2.ParameterName = "@sem_code";
            para2.DbType = DbType.String;
            para2.Value = sem_code;
            DBDataAdpterObject.SelectCommand.Parameters.Add(para2);

            para2 = DBObjectFactory.GetParameterObject();
            para2.ParameterName = "@year_code";
            para2.DbType = DbType.String;
            para2.Value = year_code;
            DBDataAdpterObject.SelectCommand.Parameters.Add(para2);

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds.Tables[0];
            }
            catch (Exception ex)
            {
                return null;
            }
        }


