        public dynamic WS_Course_allocation_Final(string sem_code, string year_code, string user_id)
        {
            string host_name = HttpContext.Current.Request.UserHostName.ToString();
            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                String SqlSelect = "";

                try
                {
                    SqlSelect = @" INSERT INTO ws_student_wise_course_dtl(doc_no,user_id,year_code,course_code,course_type,credits,gpa_nongpa,dept_code,priority,
							status,cancel_flag,semester_type,year_semester,created_by,created_date,created_host)

							select doc_no,user_id, (select um.year_code from user_mst um where um.user_id = ws_connect_student_reg_dtl.user_id) as year_code,   course_code,course_type,credits,
							gpa_nongpa =(select  gpa_status from ws_course_mst where semester_type = '" + sem_code + @"' and year_semester= '" + year_code + @"'  and cancel_flag='N' and course_code = ws_connect_student_reg_dtl.course_code),
							dept_code = (select  dept_code from ws_course_mst where semester_type = '" + sem_code + @"' and year_semester= '" + year_code + @"' and course_code = ws_connect_student_reg_dtl.course_code and cancel_flag='N')
							
							,priority,status='A','N',semester_type,year_semester,'" + user_id + @"',GETDATE(),'" + host_name + @"'
							
							from ws_connect_student_reg_dtl 
							where semester_type= '" + sem_code + @"' and year_semester= '" + year_code + @"' and status='P' and course_drop_status IS NULL and cancel_flag='N'		
							

							INSERT INTO ws_student_course_allocate_dtl(doc_no,user_id,year_code,course_code,course_type,credits,gpa_nongpa,dept_code,priority,
							cancel_flag,semester_type,year_semester,created_by,created_date,created_host)

							select doc_no,user_id, (select um.year_code from user_mst um where um.user_id = ws_connect_student_reg_dtl.user_id) as year_code,   course_code,course_type,credits,
							gpa_nongpa =(select  gpa_status from ws_course_mst where semester_type= '" + sem_code + @"' and year_semester= '" + year_code + @"'  and cancel_flag='N' and course_code = ws_connect_student_reg_dtl.course_code),
							dept_code = (select  dept_code from ws_course_mst where semester_type= '" + sem_code + @"' and year_semester= '" + year_code + @"' and course_code = ws_connect_student_reg_dtl.course_code and cancel_flag='N')
							
							,priority,'N',semester_type,year_semester,'" + user_id + @"',GETDATE(),'" + host_name + @"'
							
							from ws_connect_student_reg_dtl 
							where semester_type= '" + sem_code + @"' and year_semester= '" + year_code + @"' and status='P' and course_drop_status IS NULL and cancel_flag='N'

                            Update ws_connect_student_reg_dtl set status='A' where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' and status='P'
							and course_drop_status IS NULL and cancel_flag='N' ";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    int res_insert = DBCommand.ExecuteNonQuery();


                }
                catch (Exception ex)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            return true;
        }



