        public DataTable user_type_wise_get_department(string user_id, string user_type, string sem_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";
            if (user_type == "FA")
            {
                SqlSelect = @"  select distinct dwu.dept_code,dm.dept_name from department_wise_user_dtl dwu
							inner join department_mst dm on dm.dept_code = dwu.dept_code
							where dwu.semester_type='" + sem_code + @"' and dwu.year_semester='" + year_code + @"' and dwu.user_type='FA'
							and dwu.user_id='" + user_id + "'";
            }
            else if (user_type == "PC")
            {
                SqlSelect = @"select * from department_mst where dept_code in (select distinct dept_code from programme_coordinator_dtl where cancel_flag='N' 
                    and semester_type = '" + sem_code + "' and year_semester='" + year_code + "' and user_id='" + user_id + "')";

            }
            else
            {
                SqlSelect = @"select * from department_mst where cancel_flag='N'";
            }
            return Get_data(SqlSelect);
        }


