                        " ,created_by = '" + user_id + "',created_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',created_host = '" + host_name + "' " +
                        " where cancel_flag='N' and course_code ='" + course_code + "' and semester_type='" + sem_code + "' " +
                        " and year_semester='" + year_code + "' and instructor_code='" + inst_code + "'  ";

