                               && get_rateband_dtl.Rows[0]["total_exp"].ToString() == get_inst_dtl.Rows[0]["total_exp_new"].ToString())
                            {
                                SqlSelect += @" ,'" + get_data.Rows[0]["uso_hr_approved"].ToString() + "','" + get_data.Rows[0]["Contact_Hrs"].ToString() + "'," +
                                    " '" + add_hourse + "','" + get_data.Rows[0]["hr_approved"].ToString() + "','" + total_hrs + "' )";
                            }
