                                )
                                VALUES ( '" + DocNo + "','" + inst_code + "','" + course_code + "'" +
                                        " ,'" + dr_rateband[0]["total_experiance"].ToString() + "'" +
                                        " ,'" + dr_rateband[0]["rate_band"].ToString() + "' ,'Y'  ,'N'" +
                                        " ,'" + user_id + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + host_name + "'," +
                                        " '" + sem_code + "' ,'" + year_code + "' ";
                                SqlSelect += @" ,'N','" + contac_hrs + "','" + add_hourse + "','N','" + total_hrs + "' )";
                            }
                            else { return false; }

                        }



                        DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                        int res_insert_combination = DBCommand.ExecuteNonQuery();

