        public dynamic save_comments(string user_id, string inst_code, string host_name, string user_type, string json_All_table_course_data, string year_code)
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();
            ArrayList data_dtl = ser.Deserialize<ArrayList>(json_All_table_course_data.Replace("'", "''"));
            ArrayList comments = (ArrayList)data_dtl[0];
            String SqlSelect = "";
            Dictionary<string, object> dic_comments_dtl = (Dictionary<string, object>)comments[0];
            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                try
                {
                    if (user_type == "HR")
                    {
                        SqlSelect = " update faculty_appraisal_application_mst set comment_by_review_committee ='" + dic_comments_dtl["comments"] + "',uso_approve ='Y',";
                    }
                    else if (user_type == "D")
                    {
                        SqlSelect = " update faculty_appraisal_application_mst set over_all_comment_by_dean ='" + dic_comments_dtl["over_all_comment_by_dean"] + "',comment_by_review_committee ='" + dic_comments_dtl["comment_by_review_committee"] + "',dean_approve ='Y',";
                    }


                    SqlSelect += " last_modified_by = '" + user_id + "',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "',last_modified_host = '" + host_name + "' " +
                        " where cancel_flag='N' and year='" + year_code + "' and instructor_code='" + inst_code + "'";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                    int res_insert = DBCommand.ExecuteNonQuery();

                    if (res_insert <= 0)
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        return false;
                    }


                }
                catch (Exception ex)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }



            return "1";
        }

