        public DataTable get_faculty_course_code(string instructor_code, string year)
        {
            string[] FileArray = new string[4];
            if (year != "")
            {
                FileArray = year.Split(new Char[] { '-' }, StringSplitOptions.RemoveEmptyEntries);
            }

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect += @" select cwi.course_code,cwi.instructor_code,CONCAT(cwi.semester_type, '-',cwi.year_semester ) as semester,cm.course_credits,cm.course_name,ISNULL(iwd.total_hrs_in_semester,'0') total_hrs_in_semester,ISNULL(iwd.additional_hours,'0') add_total_hrs_in_semester 
                            ,(select Count(course_code) from course_wise_instructor where instructor_code='" + instructor_code + @"' and cancel_flag='N' and course_code=cwi.course_code) as total_no_of_year_count
                            from course_wise_instructor as cwi
                            inner join course_mst cm on cm.course_code = cwi.course_code and cm.semester_type= cwi.semester_type and cm.year_semester = cwi.year_semester
                            and cm.cancel_flag='N' and cm.ugpgoffice_approved='Y'
                            left join instructor_workload_detail iwd on iwd.course_code = cwi.course_code and iwd.semester_type = cwi.semester_type 
                            and iwd.year_semester = cwi.year_semester and iwd.cancel_flag='N' and iwd.instructor_code = cwi.instructor_code
                            inner join department_wise_course_dtl dwc on dwc.course_code  = cwi.course_code
                            and dwc.semester_type = cwi.semester_type and dwc.year_semester= cwi.year_semester
                            and dwc.cancel_flag='N' and dwc.course_typology Not in ('25','29')
                            where cwi.semester_type in ('M') and cwi.year_semester in ('" + FileArray[0].ToString() + @"') 
                            and cwi.cancel_flag='N' and cwi.instructor_code='" + instructor_code + @"' 
                            union all 
                           
                            select cwi.course_code,cwi.instructor_code,CONCAT(cwi.semester_type, '-',cwi.year_semester ) as semester,cm.course_credits,cm.course_name,ISNULL(iwd.total_hrs_in_semester,'0') total_hrs_in_semester,ISNULL(iwd.additional_hours,'0') add_total_hrs_in_semester 
                            ,(select Count(course_code) from course_wise_instructor where instructor_code='" + instructor_code + @"' and cancel_flag='N' and course_code=cwi.course_code) as total_no_of_year_count
                            from course_wise_instructor as cwi
                            inner join course_mst cm on cm.course_code = cwi.course_code and cm.semester_type= cwi.semester_type and cm.year_semester = cwi.year_semester
                            and cm.cancel_flag='N' and cm.ugpgoffice_approved='Y'
                            left join instructor_workload_detail iwd on iwd.course_code = cwi.course_code and iwd.semester_type = cwi.semester_type 
                            and iwd.year_semester = cwi.year_semester and iwd.cancel_flag='N' and iwd.instructor_code = cwi.instructor_code
                            inner join department_wise_course_dtl dwc on dwc.course_code  = cwi.course_code
                            and dwc.semester_type = cwi.semester_type and dwc.year_semester= cwi.year_semester
                            and dwc.cancel_flag='N' and dwc.course_typology Not in ('25','29')
                            where cwi.semester_type in ('S') and cwi.year_semester in ('" + FileArray[1].ToString() + @"') 
                            and cwi.cancel_flag='N' and cwi.instructor_code='" + instructor_code + @"' 

                            union all 

                            select cwi.course_code,cwi.instructor_code,CONCAT(cwi.semester_type, '-',cwi.year_semester ) as semester ,wcm.course_credits,wcm.course_name,ISNULL(iwd.total_hrs_in_semester,ISNULL(iwd.Contact_Hrs,'0')) total_hrs_in_semester,ISNULL(iwd.additional_hours,'0') add_total_hrs_in_semester
                            ,(select Count(course_code) from ws_course_wise_instructor where instructor_code='" + instructor_code + @"' and cancel_flag='N' and course_code=cwi.course_code) as total_no_of_year_count
                            from ws_course_wise_instructor as cwi   
                            inner join ws_course_mst wcm on wcm.course_code = cwi.course_code and wcm.semester_type= cwi.semester_type and wcm.year_semester = cwi.year_semester
                            left join ws_instructor_workload_detail iwd on iwd.course_code = cwi.course_code and iwd.semester_type = cwi.semester_type 
                            and iwd.year_semester = cwi.year_semester and iwd.cancel_flag='N' and iwd.instructor_code = cwi.instructor_code
                            left join department_wise_course_dtl dwc on dwc.course_code  = cwi.course_code
                            and dwc.semester_type = cwi.semester_type and dwc.year_semester= cwi.year_semester
                            and dwc.cancel_flag='N' and dwc.course_typology Not in ('25','29')
                            where cwi.semester_type in ('W') and cwi.year_semester in ('" + FileArray[0] + @"') and cwi.cancel_flag='N' and cwi.instructor_code='" + instructor_code + @"'  
                            union all 

                            select cwi.course_code,cwi.instructor_code,CONCAT(cwi.semester_type, '-',cwi.year_semester ) as semester ,wcm.course_credits,wcm.course_name,ISNULL(iwd.total_hrs_in_semester,ISNULL(iwd.Contact_Hrs,'0')) total_hrs_in_semester,ISNULL(iwd.additional_hours,'0') add_total_hrs_in_semester
                            ,(select Count(course_code) from ws_course_wise_instructor where instructor_code='" + instructor_code + @"' and cancel_flag='N' and course_code=cwi.course_code) as total_no_of_year_count
                            from ws_course_wise_instructor as cwi   
                            inner join ws_course_mst wcm on wcm.course_code = cwi.course_code and wcm.semester_type= cwi.semester_type and wcm.year_semester = cwi.year_semester
                            left join ws_instructor_workload_detail iwd on iwd.course_code = cwi.course_code and iwd.semester_type = cwi.semester_type 
                            and iwd.year_semester = cwi.year_semester and iwd.cancel_flag='N' and iwd.instructor_code = cwi.instructor_code
                            left join department_wise_course_dtl dwc on dwc.course_code  = cwi.course_code
                            and dwc.semester_type = cwi.semester_type and dwc.year_semester= cwi.year_semester
                            and dwc.cancel_flag='N' and dwc.course_typology Not in ('25','29')
                            where cwi.semester_type in ('S') and cwi.year_semester in ('" + FileArray[1] + @"') and cwi.cancel_flag='N' and cwi.instructor_code='" + instructor_code + @"'  ";




            return Get_data(SqlSelect);
        }


