        public DataTable get_faculty_apprisal_dtl(string year, string user_id, string user_type)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect += @" select dm.dept_code,dm.dept_name,im.instructor_name,im.instructor_code,faa.dean_approve,faa.faculty_approve,
                            faa.uso_approve,faa.managment_approve,faa.uplodaFile1,faa.uplodaFile2,faa.uplodaFile3  from faculty_appraisal_application_mst as faa
                            inner join instructor_mst im on im.instructor_code = faa.instructor_code
                            inner join user_mst um on um.user_id = faa.instructor_code
                            inner join cpop_superviser_mst csm on csm.superviser_code = faa.instructor_code
                            inner join department_mst dm on dm.dept_name = csm.department
                            where faa.cancel_flag='N' and faa.year ='" + year + @"' and
                            csm.publish_flag='Y' and csm.approval_flag='Y'  and csm.cancel_flag='N' ";
            if (user_type == "D")
            {
                SqlSelect += @" and dm.dept_code in(
                            select dept_code from dean_dtl where cancel_flag='N' and instructor_code='" + user_id + @"' 
                            and semester_type in (select sem_code from cept_current_semester where active_flag='Y' and type_desc='all') 
                            and year_semester in (select year_code from cept_current_semester where active_flag='Y' and type_desc='all'))";
            }
            if (user_type == "I2")
            {
                SqlSelect += @" and im.instructor_code='" + user_id + "' ";
            }
            SqlSelect += "union ";

            SqlSelect += @" select  dm.dept_code,dm.dept_name,im.instructor_name,im.instructor_code,dean_approve = 'P',faculty_approve ='P',uso_approve ='P',managment_approve ='P'
                            ,uplodaFile1 = NULL,uplodaFile2 = NULL,uplodaFile3 = NULL from cpop_superviser_mst csm 
							left join instructor_mst im on im.instructor_code = csm.superviser_code
                            left join user_mst um on um.user_id = csm.superviser_code
							left join department_mst dm on dm.dept_name = csm.department 
                            where csm.publish_flag='Y' and csm.approval_flag='Y'  and csm.cancel_flag='N' 
                        and csm .superviser_code Not in (select instructor_code from faculty_appraisal_application_mst where cancel_flag='N' and year ='" + year + @"') ";
            if (user_type == "D")
            {
                SqlSelect += @" and dm.dept_code in(
                            select dept_code from dean_dtl where cancel_flag='N' and instructor_code='" + user_id + @"' 
                            and semester_type in (select sem_code from cept_current_semester where active_flag='Y' and type_desc='all') 
                            and year_semester in (select year_code from cept_current_semester where active_flag='Y' and type_desc='all'))";
            }
            if (user_type == "I2")
            {
                SqlSelect += @" and im.instructor_code='" + user_id + "' ";
            }

            return Get_data(SqlSelect);
        }


