        public DataTable get_calculate_rate_band_dtl(string sem_code, string year_code, string inst_code)
        {
            DataTable get_inst_dtl = get_instructor_dtl(inst_code);
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            if (sem_code == "W")
            {
                sem_code = "M";
            }
            String SqlSelect = "";

            SqlSelect += @" select (CAST(ISNULL('" + get_inst_dtl.Rows[0]["total_experiance"].ToString() + @"', 0) as INT) * CAST('12' as INT) + CAST(ISNULL('" + get_inst_dtl.Rows[0]["total_experiance_months"].ToString() + @"', '') as INT)) total_exp, * from rate_band_range where ISNULL(rate_band_range.degree, '') = ISNULL('" + get_inst_dtl.Rows[0]["highest_qualification"].ToString() + @"', '')
                 and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL('" + get_inst_dtl.Rows[0]["total_experiance"].ToString() + @"', 0) as INT) * CAST('12' as INT) + CAST(ISNULL('" + get_inst_dtl.Rows[0]["total_experiance_months"].ToString() + @"', '') as INT))
                 and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL('" + get_inst_dtl.Rows[0]["total_experiance"].ToString() + @"', 0) as INT) * CAST('12' as INT) + CAST(ISNULL('" + get_inst_dtl.Rows[0]["total_experiance_months"].ToString() + @"', '') as INT))
                 and ISNULL(rate_band_range.designation,'') = case ISNULL('" + get_inst_dtl.Rows[0]["designation"].ToString() + @"', '')
                 when 'instructor' then 'VF' when 'temp' then 'VF'  else ISNULL('" + get_inst_dtl.Rows[0]["designation"].ToString() + @"', '') end
                 and rate_band_range.typology_sub_group = 'SG003' and rate_band_range.semester_type = '" + sem_code + @"' and rate_band_range.year_semester = '" + year_code + @"' and rate_band_range.cancel_flag = 'N' ";

            return Get_data(SqlSelect);
        }


        public DataTable Get_current_sem_allocated_course_credits(string sem_code, string year_code, string user_id)
        {
            //DataTable get_inst_dtl = get_instructor_dtl(inst_code);

            string ws_sem = "";
            string ws_year = "";
            if (sem_code == "S")
            {
                ws_sem = "S";
                ws_year = year_code;
            }
            else if (sem_code == "M")
            {
                ws_sem = "W";
                ws_year = year_code;
            }
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect += @" select
						t1.user_id,t1.full_name,t1.year_code ,
						ISNULL(Sum(CAST(t1.credits_completed as int)),'0') credits_completed
						,ISNULL(Sum(CAST(t1.mandatory_credits_completed as int)),'0') mandatory_credits_completed,ISNULL( Sum(CAST(t1.elective_credits_completed as int)),'0')elective_credits_completed  
						
						from (
						select tt.user_id,tt.full_name,tt.year_code ,
						ISNULL(credits_completed,'0') credits_completed
						,ISNULL(mandatory_credits_completed,'0') mandatory_credits_completed,ISNULL(elective_credits_completed,'0')elective_credits_completed  
						from user_mst tt
						left join (select user_id,ISNULL(SUM(CAST(credits as int)),0)credits_completed from student_course_allocate_dtl where semester_type ='" + sem_code + @"' and year_semester = '" + year_code + @"' and user_id='" + user_id + @"' and cancel_flag='N'
						group by user_id
                        )res1 on res1.user_id=tt.user_id
                        left join (select user_id,
						ISNULL(SUM(CAST(credits as int)),0)
						mandatory_credits_completed from student_course_allocate_dtl where semester_type ='" + sem_code + @"' and year_semester='" + year_code + @"' and user_id='" + user_id + @"' and cancel_flag='N' and course_type='M' group by user_id
                        )res2 on res2.user_id=tt.user_id
                        left join (select user_id,ISNULL(SUM(CAST(credits as int)),0)elective_credits_completed from student_course_allocate_dtl where semester_type ='" + sem_code + @"' and year_semester='" + year_code + @"' and user_id='" + user_id + @"' and cancel_flag='N' and course_type='E' group by user_id
                        )res3 on res3.user_id=tt.user_id
						where tt.user_id='" + user_id + @"'
						
						Union 
						select tt.user_id,tt.full_name,tt.year_code ,
						ISNULL(credits_completed,'0') credits_completed
					   ,ISNULL(mandatory_credits_completed,'0') mandatory_credits_completed,ISNULL(elective_credits_completed,'0')elective_credits_completed  
						from user_mst tt
						left join (select user_id,ISNULL(SUM(CAST(credits as int)),0)credits_completed from ws_student_course_allocate_dtl where semester_type = '" + ws_sem + @"' and year_semester = '" + ws_year + @"' and user_id='" + user_id + @"' and cancel_flag='N'
						group by user_id
                        )res1 on res1.user_id=tt.user_id
                        left join (select user_id,
						ISNULL(SUM(CAST(credits as int)),0)
						mandatory_credits_completed from ws_student_course_allocate_dtl where semester_type = '" + ws_sem + @"' and year_semester = '" + ws_year + @"' and user_id='" + user_id + @"' and cancel_flag='N' and course_type='M' group by user_id
                        )res2 on res2.user_id=tt.user_id
                        left join (select user_id,ISNULL(SUM(CAST(credits as int)),0)elective_credits_completed from ws_student_course_allocate_dtl where semester_type = '" + ws_sem + @"' and year_semester = '" + ws_year + @"' and user_id='" + user_id + @"' and cancel_flag='N' and course_type='E' group by user_id
                        )res3 on res3.user_id=tt.user_id
						where tt.user_id='" + user_id + @"') t1
						group by t1.user_id,t1.full_name,t1.year_code ";

            return Get_data(SqlSelect);

        }



        public DataTable Get_Datetime_wise_parameter_dtl(string parameter_name, string user_type)
        {

            if (user_type == "E")
            {
                user_type = "E";
            }
            else if (user_type == "S")
            {
                user_type = "S";
            }

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            // DBDataAdpterObject.SelectCommand.Parameters.Add(DBObjectFactory.MakeParameter_new("@user_id", DbType.String, ObjParam["user_id"]);

            String SqlSelect = "";

            SqlSelect += @" select FORMAT(Start_Date,'dd-MM-yyyy') as sws_start_date, * from parameter_mst where parameter_name='" + parameter_name + @"' and (FORMAT(GETDATE(),'yyyy-MM-dd') BETWEEN FORMAT(Start_Date,'yyyy-MM-dd') AND FORMAT(End_Date,'yyyy-MM-dd')) 
                            and (Format (GETDATE(),'HH:mm:ss') BETWEEN start_time AND end_time)  and user_type='" + user_type + "'";

            return Get_data(SqlSelect);
        }

