               + '<option value=C selected>Close for all</option>'
               + '<option value=ONP>Online Payment Only</option>'
               + '<option value=OFP>Offline Payment Only</option>'
                WHEN parameter_value = 'ONP' THEN
               '<option style=display:none>' + parameter_value + '</option>'
               + '<option value=P>---please select any option---</option>'
               + '<option value=O>Open for all</option>'
               + '<option value=C>Close for all</option>'
               + '<option value=ONP selected>Online Payment Only</option>'
               + '<option value=OFP>Offline Payment Only</option>'
                WHEN parameter_value = 'OFP' THEN
               '<option style=display:none>' + parameter_value + '</option>'
               + '<option value=P>---please select any option---</option>'
