        public Boolean update_SWS_Parameter_mst(List<Dictionary<string, object>> interested_program_data, string user_id)
        {
            /*************************/
            /* ESTABLISH CONNECTION */


            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                string SqlSelect = "";

                for (var i = 0; i < interested_program_data.Count; i++)
                {

                    SqlSelect += @"UPDATE parameter_mst SET Start_Date='" + interested_program_data[i]["Start_Date"].ToString() + "', End_Date='" + interested_program_data[i]["End_Date"].ToString() + "', start_time='" + interested_program_data[i]["start_time"].ToString() + "',end_time = '" + interested_program_data[i]["end_time"].ToString() + "' , parameter_value = '" + interested_program_data[i]["parameter_value"].ToString() + "' where parameter_id='" + interested_program_data[i]["parameter_id"].ToString() + "' ";
                }
                /*************************/
                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                int noofrows = DBCommand.ExecuteNonQuery();
                if (noofrows > 0 && noofrows == interested_program_data.Count)
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return true;
                }
                else
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;

                }



            }

            catch (Exception Ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
        }

        public bool Get_Review_data(string sem_code, string year_code, string course_code)
