        public DataTable Get_tab_data(string sem_code, string year_code, string status)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";

            SqlSelect = @" Select 
(
	'<table class=table id = rateband_txt border=0 cellpadding=0 cellspacing=0>
		<tr>
		  <td><b>Instructor Name</b>: @@Fullname</td>
		  <td><b>Instructor Code</b>: @@instructor_code</td>
		  <td><b>VF Code</b>: @@VF_code</td>
		</tr>
		<tr>
		  <td><b>Type</b>: @@designation</td>
		  <td><b>Highest Qualification</b>:  @@highestqualification</td>
		  <td><b>Nationality</b>: @@nationality </td>
		</tr>
		<tr>
		  <td><b>Email ID</b>: @@mail</td>
		  <td><b>Total Year of Experiance</b>: @@TotalExperiance</td>
          <td id=rate_band_id><b>Rate Band</b>: @@totalratebandvalue</td>
		  
		</tr>
		<tr>
		  <td><b>Aadhar No</b>: @@aadhaar_no</td>
		  <td><b>Passport No</b>:  @@passport_no</td>
		  <td><b>PAN Card No</b>: @@pan_card_no</td>
		</tr>
		<tr>
		  <td><b>CV</b>: <a href=# class=pdf_download  id= @@cv_file_name title=Download PDF><i class=icon-download-alt style=font-size: 17px;></i></a></td>
		  <td><b>Portfolio</b>: <a href=# class=port_download id= @@portfolio_file_name title=Download PDF><i class=icon-download-alt style=font-size: 17px;></i></a></td>
		  <td><b>Image</b>: <a href=# class=imag_download id= @@profile_photo title=Download Image><i class=icon-download-alt style=font-size: 17px;></i></a></td>
		</tr>
		<tr>
		<td><b>Personal Document</b>: <a href=# class=pdf_download_doc id=@@instructor_code title=Download Document><i class=icon-download-alt style=font-size: 17px;></i></a></td>
		<td><textarea id= remark_data@@instructor_code class=@@instructor_code name=remark rows=2 cols=50>@@remark_value</textarea> </td>
		<td style=display:@@block_pending;><button id= @@instructor_code type=button onclick=sendremark(this) class= cls_btn_pdf btn btn-primary >Send</button>
        <button id= @@instructor_code type=button onclick=rowClick_Hr_Authorized(this) class= cls_btn_pdf btn btn-primary  >Approve</button></td>
        <td style=display:@@block_approved ; id=@@approved_status>Approved</td>
		
		</tr>
        <tr>
        <td><button id= @@instructor_code type=button onclick=rowClick_edit(this) class= cls_btn_pdf btn btn-primary >Edit Personal Detail</button></td>
</tr>
	</table>
') htmltext,button_status ='FALSE',

* 
from (  
                           Select rate_band_range.rate_band as new_rate_band,t1.instructor_code,
                           Case ISNULL(t1.rate_band,'') When '' Then rate_band_range.rate_band Else 
                           t1.rate_band End rate_band,
                           
                           t1.degree,t1.designation,
						    (CAST(ISNULL(t1.total_experiance,0) as INT)) total_experiance,
						   (CAST(ISNULL(t1.total_experiance_months,0) as INT)) total_experiance_months,
						   CAST(ISNULL(t1.TotalExperiance,0) AS INT) AS TotalExperiance,
						   t1.course_code, 
                           t1.nationality,t1.full_name,t1.VF_code,t1.mail,
						   Case ISNULL(t1.aadhaar_no,'') When '' THen NULL Else t1.aadhaar_no End aadhaar_no,
                           Case ISNULL(t1.pan_card_no,'') When '' THen NULL Else t1.pan_card_no End pan_card_no,
						   Case ISNULL(t1.cv_file_name,'') When '' THen NULL Else t1.cv_file_name End cv_file_name,
						   Case ISNULL(t1.portfolio_file_name,'') When NULL THen '' Else t1.portfolio_file_name End portfolio_file_name,
                          t1.total_contact_hrs,t1.total_weeks,t1.additional_hours,
                          (((CAST(ISNULL(t1.total_hrs_in_semester,0) as float) + CAST(ISNULL(t1.additional_hours,0) as float)) ) ) as total_hrs_in_semester,
                           ((CAST(ISNULL(t1.total_hrs_in_semester,0) as float) + CAST(ISNULL(t1.additional_hours,0) as float)) * CAST(t1.rate_band as float)) TotalPay,
                           t1.uso_hr_approved,t1.hr_approved,t1.admin_approved, status_rateband = NULL,
						   Case ISNULL(t1.highest_qualification,'') When '' THen NULL  When 'NULL' THen NULL Else t1.highest_qualification End highest_qualification
						   
						   ,Case ISNULL(t1.passport_no,'') When '' THen NULL Else t1.passport_no End passport_no
						  ,Case ISNULL(t1.profile_photo,'') When '' THen NULL Else t1.profile_photo End profile_photo,t1.country  ,CASt(t1.remark AS NVARCHAR(MAX)) AS remark
						  
                           from (
                           select iwd.instructor_code,um.full_name,im.VF_code,um.nationality,um.mail,
                           iwd.rate_band,
                           
						   im.highest_qualification,
						   (CAST(ISNULL(im.total_experiance,0) as INT)) total_experiance,
						   (CAST(ISNULL(im.total_experiance_months,0) as INT)) total_experiance_months,
						   CAST((CAST(ISNULL(im.total_experiance,0) as INT) * 12) + CAST(ISNULL(im.total_experiance_months,0) as INT) AS INT) TotalExperiance
						   
						   ,im.designation,im.degree,iwd.course_code,
                           im.aadhaar_no,im.pan_card_no,im.cv_file_name,im.portfolio_file_name,iwd.total_contact_hrs,iwd.total_weeks,iwd.additional_hours,iwd.total_hrs_in_semester,
                           iwd.uso_hr_approved,iwd.hr_approved,iwd.admin_approved,im.passport_no ,um.profile_photo,um.country,CASt(iwd.remark AS NVARCHAR(MAX)) AS remark
                           from instructor_workload_detail iwd 
                           inner join instructor_mst im on im.instructor_code = iwd.instructor_code
                           inner join user_mst um on um.user_id = iwd.instructor_code
                           inner join department_wise_course_dtl dm on dm.course_code = iwd.course_code
                           and dm.semester_type = iwd.semester_type and dm.year_semester = iwd.year_semester and dm.course_typology='24'
                           where iwd.semester_type = '" + sem_code + @"' and iwd.year_semester='" + year_code + @"' and iwd.cancel_flag='N' 
                           and im.designation='VF' and um.user_type='I2'and iwd.instructor_code in (select distinct instructor_code 
                           from Studio_Applicant_Instructor_Mst where semester_type= '" + sem_code + @"' and year_semester= '" + year_code + @"' 
                           and cancel_flag='N')) t1 
                           left join rate_band_range on ISNULL(rate_band_range.degree,'') = ISNULL(t1.highest_qualification,'') 
                           and CAST(rate_band_range.from_experiance as INT) <= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'') as INT)) 
                           and CAST(rate_band_range.to_experiance as INT) >= (CAST(ISNULL(t1.total_experiance,0) as INT) * CAST('12' as INT) + CAST(ISNULL(t1.total_experiance_months,'')as  INT)) 
                           and ISNULL(rate_band_range.designation,'') = CASE WHEN (t1.designation IS NULL OR t1.designation = '') THEN ''  
                           WHEN t1.designation IN ('instructor','temp') THEN 'VF' WHEN t1.designation = 'TEA' THEN 'TEA' ELSE t1.designation END 
                           and rate_band_range.typology_sub_group ='SG003'and rate_band_range.semester_type='" + sem_code + "' and rate_band_range.year_semester= '" + year_code + "' and rate_band_range.cancel_flag='N') rest";
            if (status == "A")
            {
                SqlSelect += @"  where rest.uso_hr_approved ='Y' and rest.hr_approved ='Y' and rest.admin_approved ='Y' ";
            }
            else if (status == "P")
            {
                SqlSelect += @"  where rest.uso_hr_approved ='N' or rest.uso_hr_approved IS NULL or rest.hr_approved ='N' or rest.hr_approved IS NULL or rest.admin_approved ='N' or rest.admin_approved IS NULL ";
            }
            SqlSelect += @" order by rest.instructor_code asc ";
            return Get_data(SqlSelect);
        }



        public DataTable Approved_rateband_dtl(string sem_code, string year_code)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect += @"

                           select *  from instructor_workload_detail iwd 
                           inner join instructor_mst im on im.instructor_code = iwd.instructor_code
                           inner join user_mst um on um.user_id = iwd.instructor_code
                           inner join department_wise_course_dtl dm on dm.course_code = iwd.course_code
                           and dm.semester_type = iwd.semester_type and dm.year_semester = iwd.year_semester and dm.course_typology='24'
                           where iwd.semester_type = '" + sem_code + @"' and iwd.year_semester='" + year_code + @"' and iwd.cancel_flag='N' 
						   and iwd.hr_approved='Y' and iwd.uso_hr_approved='Y' and iwd.admin_approved='Y'
                           and im.designation='VF' and um.user_type='I2'and iwd.instructor_code in (select instructor_code 
                           from Studio_Applicant_Instructor_Mst where semester_type= '" + sem_code + @"' and year_semester= '" + year_code + @"' 
                           and cancel_flag='N') ";

            return Get_data(SqlSelect);
        }



