        public dynamic SaveUSOData(string user_id, string inst_code, string host_name, string user_type, string json_All_table_course_data)
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();
            ArrayList data_dtl = ser.Deserialize<ArrayList>(json_All_table_course_data.Replace("'", "''"));
            // ArrayList comments = (ArrayList)data_dtl[0];
            String SqlSelect = "";
            Dictionary<string, object> dic_deancomment_dtl = (Dictionary<string, object>)data_dtl[0];
            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                try
                {
                    string gh21 = "";
                    if (dic_deancomment_dtl["confirmation_date"].ToString() != "")
                    {
                        DateTime confirmation_date = Convert.ToDateTime(dic_deancomment_dtl["confirmation_date"].ToString());
                        gh21 = confirmation_date.ToString("yyyy-MM-dd");

                        //string[] sdg21 = confirmation_date.Split('/');
                        //gh21 = sdg21[2].ToString() + "-" + sdg21[1].ToString() + "-" + sdg21[0].ToString();
                    }
                    string confirmationdate = string.IsNullOrEmpty(gh21) ? "NULL" : "'" + gh21 + "'";
                    string gh22 = "";
                    if (dic_deancomment_dtl["date_of_join_cept"].ToString() != "")
                    {
                        string[] sdg22 = dic_deancomment_dtl["date_of_join_cept"].ToString().Split('/');
                        gh22 = sdg22[2].ToString() + "-" + sdg22[1].ToString() + "-" + sdg22[0].ToString();
                    }

                    string date_of_join_cept = string.IsNullOrEmpty(gh22) ? "NULL" : "'" + gh22 + "'";
                    string gh23 = "";
                    if (dic_deancomment_dtl["teaching_year"].ToString() != "")
                    {
                        string[] sdg23 = dic_deancomment_dtl["teaching_year"].ToString().Split('/');
                        if (sdg23.Length == 1)
                        {
                            gh23 = sdg23[0].ToString();
                        }
                        else { gh23 = sdg23[2].ToString() + "-" + sdg23[1].ToString() + "-" + sdg23[0].ToString(); }

                    }

                    string teaching_year = string.IsNullOrEmpty(gh23) ? "NULL" : "'" + gh23 + "'";

                    if (user_type == "HR")
                    {
                        SqlSelect += " UPDATE instructor_mst set total_experiance_months = '" + dic_deancomment_dtl["total_experiance_months"] + "', total_experiance='" + dic_deancomment_dtl["total_year_experience"] + "', join_date =" + date_of_join_cept + ", confirmation_date =" + confirmationdate + "," +
                                    " teaching_year =" + teaching_year + ",total_teaching_experiance ='" + dic_deancomment_dtl["previous_year_experience"] + "' where instructor_code ='" + dic_deancomment_dtl["instructor_code"] + "'";
                    }

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                    int res_insert = DBCommand.ExecuteNonQuery();

                    if (res_insert <= 0)
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        return false;
                    }


                }
                catch (Exception ex)
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }



            return "1";
        }


