        public bool ApplyForProvisionalCertificate(string UserID, string Status, string Host, string declaration_1, string declaration_2, string submit_status, string Remark)
        {
            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                string SqlSelect = "";
                //SqlSelect = @" INSERT INTO StudentApplyForProvisionalCertificate (Student_id,StudentStatus,Cancel_flag,created_by,created_host)
                //               Values('" + UserID + @"','" + Status + @"','N','" + UserID + @"','" + Host + @"')";


                SqlSelect += @" IF Not EXISTS(Select * from StudentApplyForProvisionalCertificate where  Cancel_flag = 'N' and Student_id = '" + UserID + @"') "
                    + " BEGIN "
                    + " INSERT INTO StudentApplyForProvisionalCertificate (Student_id,StudentStatus,Cancel_flag,created_by,created_host)"
                    + " Values('" + UserID + @"','" + Status + @"','N','" + UserID + @"','" + Host + @"')"
                    + " END ";




                SqlSelect += @" IF EXISTS(Select * from StudentProvisionalCertificateDeclarationDtl where  Cancel_flag = 'N' and studentid = '" + UserID + @"') "
                    + " BEGIN "
                    + " update StudentProvisionalCertificateDeclarationDtl set Cancel_flag ='Y' , last_modified_by='" + UserID + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "' where Cancel_flag = 'N' and studentid = '" + UserID + @"'"
                    + " INSERT INTO StudentProvisionalCertificateDeclarationDtl (studentid,declaration_1,declaration_2,submit_status,Remark,Cancel_flag,created_by,created_date,created_host)"
                    + " VALUES('" + UserID + @"','" + declaration_1 + @"','" + declaration_2 + @"', "
                    + " '" + submit_status + @"','" + Remark + @"','N', '" + UserID + @"','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"','" + HttpContext.Current.Request.UserHostName + @"'"
                    + " ) "
                    + " END "
                + " ELSE "
                   + " BEGIN "
                   + " INSERT INTO StudentProvisionalCertificateDeclarationDtl (studentid,declaration_1,declaration_2,submit_status,Remark,Cancel_flag,created_by,created_date,created_host)"
                    + " VALUES('" + UserID + @"','" + declaration_1 + @"','" + declaration_2 + @"', "
                    + " '" + submit_status + @"','" + Remark + @"','N', '" + UserID + @"','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"','" + HttpContext.Current.Request.UserHostName + @"'"
                    + " ) "
                    + " END ";



                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                int noofrows = DBCommand.ExecuteNonQuery();
                if (noofrows > 0)
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();

                    DataTable current_dt = getCurrentSemYearCallForStudio();
                    DataTable mail_from_id_password = check_frommail_id_password("ProvisionalCertificate_form_submit");
                    DataTable AckDetails = Get_VF_TA_AA_Letter_Email_Body("ProvisionalCertificate_form_submit", "email");
                    DataTable user_dtl = check_user_by_user_id(UserID);
                    DataTable faculty_admin = fa_dtl_dept_wise(user_dtl.Rows[0]["dept_code"].ToString(), user_dtl.Rows[0]["prog_code"].ToString(), user_dtl.Rows[0]["prog_level_code"].ToString(), current_dt.Rows[0]["sem_code"].ToString(), current_dt.Rows[0]["year_code"].ToString());
                    Mail mail = new Mail();
                    bool mail_status = mail.SendProvisnalCertificate(faculty_admin, mail_from_id_password, AckDetails, user_dtl);

                    // Faculty Send Mail 
                    DataTable mail_from_id_password_faculty = check_frommail_id_password("ProvisionalCertificate_form_acknowledge");
                    DataTable AckDetails_faculty = Get_VF_TA_AA_Letter_Email_Body("ProvisionalCertificate_form_acknowledge", "email");

                    Mail mail_faculty = new Mail();
                    bool mail_faculty_status = mail_faculty.SendProvisnalCertificateFaculty(faculty_admin, mail_from_id_password_faculty, AckDetails_faculty, user_dtl);


                    return true;
                }
                else
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;

                }
            }
            catch (Exception Ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
        }

        public DataTable GetApplyForProvisionalCertificate(string userid, string usertype, string dept_code, string prog_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            string SqlSelect = @"Select 
                                CASE
                                When SAP.StudentStatus = 'A' Then '<b style=color:green>Submitted<b>' 
                                When SAP.StudentStatus = 'H' Then '<b style=color:green>Hold<b>'
                                Else '<b style=color:red>Pending</b>' End StudentStatustxt,
                                CASE
                                When SAP.FAStatus = 'A' Then '<b style=color:green>Approved</b>' 
                                When SAP.FAStatus = 'H' Then '<b style=color:green>Hold<b>'
                                Else '<b style=color:red>Pending</b>' End FAStatustxt,
                                CASE
                                When SAP.AdminStatus = 'A' Then '<b style=color:green>Approved</b>' 
                                When SAP.AdminStatus = 'H' Then '<b style=color:green>Hold<b>'
                                Else '<b style=color:red>Pending</b>' End AdminStatustxt,
                                CASE
                                When SAP.AccountStatus = 'A' Then '<b style=color:green>Approved</b>' 
                                When SAP.AccountStatus = 'H' Then '<b style=color:green>Hold<b>'
                                Else '<b style=color:red>Pending</b>' End AccountStatustxt,
                                CASE
                                When SAP.ExaminationStatus = 'A' Then '<b style=color:green>Approved</b>'
                                When SAP.ExaminationStatus = 'H' Then '<b style=color:green>Hold<b>'
                                Else '<b style=color:red>Pending</b>' End ExaminationStatustxt,
                                SAP.*,um.*,SPC.declaration_1,SPC.declaration_2,SPC.submit_status,SPC.Remark,FORMAT(SAP.created_date,'dd-MM-yyyy') As CreatedDate
                                
                                FROM StudentApplyForProvisionalCertificate SAP
                                INNER JOIN user_mst um on um.user_id = SAP.Student_id
                                Left join StudentProvisionalCertificateDeclarationDtl SPC on SPC.studentid = SAP.Student_id and SPC.Cancel_flag ='N'
                                where SAP.Cancel_flag ='N'  ";
            if (usertype == "S")
            {
                SqlSelect += " AND SAP.Student_id ='" + userid + "'";
            }
            if (dept_code != "")
            {
                SqlSelect += " AND um.dept_code ='" + dept_code + "'";
            }

            if (prog_code != "")
            {
                SqlSelect += " AND um.prog_code ='" + prog_code + "'";
            }

            SqlSelect += "order by SAP.created_date desc ";
            return Get_data(SqlSelect);
        }


