                (CAST(ISNULL(IM.total_experiance, 0) AS INT) * CAST('12' AS INT) + CAST(ISNULL(IM.total_experiance_months, '') AS INT))
            ELSE 
                CAST(ISNULL(SWAR.TotalExperience, 0) AS INT)
        END AS TotalExperiance,
        CASE 
            WHEN ISNULL(SWAR.highest_qualification, '') = '' THEN 
                IM.highest_qualification
            ELSE 
                ISNULL(SWAR.highest_qualification, '')
        END AS highest_qualification,
        --CASE 
        --    WHEN ISNULL(SWAR.designation, '') = '' THEN 
        --        IM.designation
        --    ELSE 
        --        ISNULL(SWAR.designation, '')
        --END AS designation,
        IM.designation AS designation,
        CASE 
            WHEN ISNULL(SWAR.designation_letter, '') = '' THEN 
                IM.designation_letter
            ELSE 
                ISNULL(SWAR.designation_letter, '')
        END AS designation_letter,
        CASE 
            WHEN IM.total_experiance IS NULL OR IM.total_experiance = '' THEN '0'
            ELSE IM.total_experiance 
        END AS total_experiance,
        IM.total_experiance_months,
        IM.total_teaching_experiance,
        CASE 
            WHEN ISNULL(SWAR.rate_band, '') = '' THEN 
                rate_band_range.rate_band
            ELSE 
                SWAR.rate_band
        END AS rate_band,
    ISNULL(InstructorRemark.Remark,NULL)hr_remark,
	ISNULL(SWAR.ApproveRateBand,'N') ApproveRateBand,CSM.superviser_code,
    Format(UserPersonalDetailsStatus.created_date,'dd-MM-yyyy hh:m:ss') as createddate
            --,
        --ROW_NUMBER() OVER (PARTITION BY IM.instructor_code ORDER BY 
        --    CASE 
        --        WHEN SWI.pc_status = 'A' AND SWI.hr_status = 'A' AND SWI.approved = 'Y' THEN 1
        --        WHEN SWI.pc_status = 'A' AND SWI.hr_status = 'A' THEN 2
        --        WHEN SWI.pc_status = 'A' THEN 3
        --        ELSE 4
        --    END) AS rn
    FROM 
        course_wise_AA SWI
    INNER JOIN 
        instructor_mst IM ON IM.instructor_code = SWI.instructor_code
    LEFT JOIN 
        semester_wise_applicant_rateband_approve SWAR ON SWAR.instructor_code = SWI.instructor_code
        AND SWAR.cancel_flag = 'N' 
        AND SWAR.semester_type = SWI.semester_type
        AND SWAR.year_semester = SWI.year_semester

LEFT JOIN 
        InstructorRemark ON InstructorRemark.user_id = SWI.instructor_code
        AND InstructorRemark.cancel_flag = 'N' 
        AND InstructorRemark.semester_type = SWI.semester_type
        AND InstructorRemark.year_semester = SWI.year_semester

LEFT JOIN UserPersonalDetailsStatus on UserPersonalDetailsStatus.UserId = SWI.instructor_code
	AND UserPersonalDetailsStatus.SemesterType = SWI.semester_type
	AND UserPersonalDetailsStatus.SemesterYear = SWI.year_semester
	AND UserPersonalDetailsStatus.CancelFlag ='N'

    LEFT JOIN 
        rate_band_range ON ISNULL(rate_band_range.degree, '') = ISNULL(IM.highest_qualification, '')
        AND CAST(rate_band_range.from_experiance AS INT) <= (CAST(ISNULL(IM.total_experiance, 0) AS INT) * CAST('12' AS INT) + CAST(ISNULL(IM.total_experiance_months, '') AS INT)) 
        AND CAST(rate_band_range.to_experiance AS INT) >= (CAST(ISNULL(IM.total_experiance, 0) AS INT) * CAST('12' AS INT) + CAST(ISNULL(IM.total_experiance_months, '') AS INT))
        AND ISNULL(rate_band_range.designation, '') = CASE 
            WHEN ISNULL(IM.designation, '') = 'instructor' THEN 'VF' 
            WHEN IM.designation IN ('temp') THEN 'AA' 
            WHEN (IM.designation_letter = 'TEA') THEN 'TEA' 
            ELSE ISNULL(IM.designation, '') 
        END
        AND rate_band_range.semester_type = '" + sem + @"' 
        AND rate_band_range.year_semester = '" + year + @"'
        AND rate_band_range.typology_sub_group = 'SG003'
LEFT JOIN cpop_superviser_mst CSM on CSM.superviser_code = IM.instructor_code and CSM.cancel_flag ='N'
    WHERE 
        SWI.cancel_flag = 'N' 
        AND SWI.year_semester = '" + year + @"' 
        AND SWI.semester_type = '" + sem + @"'
)
