        public string GetCurrentAndLastTwoSemesters(string currentSemester, int currentYear, string intcode)
        {
            //DataTable dtcurrentsem = Get_cept_current_sem_data("course");
            List<Dictionary<string, string>> semesters = new List<Dictionary<string, string>>();
            semesters.Add(new Dictionary<string, string> { { "Semester", currentSemester }, { "Year", currentYear.ToString() } });
            for (int i = 0; i < 2; i++)
            {
                if (currentSemester == "Monsoon")
                {
                    currentSemester = "Spring";
                }
                else
                {
                    currentSemester = "Monsoon";
                    currentYear--;
                }
                semesters.Add(new Dictionary<string, string> { { "Semester", currentSemester }, { "Year", currentYear.ToString() } });
            }

            if (semesters.Count > 0)
            {
                String SqlSelect = "";
                for (int i = 0; i < semesters.Count; i++)
                {

                    if (i == 0)
                    {
                        SqlSelect = " Select * from instructor_workload_detail " +
                            "  inner join instructor_mst im on im.instructor_code = instructor_workload_detail.instructor_code " +
                            " where instructor_workload_detail.cancel_flag='N' AND instructor_workload_detail.acceptance ='Y' AND uso_hr_approved='Y' AND im.designation ='VF' " +
            "and instructor_workload_detail.instructor_code ='" + intcode + "' " +
            "and semester_type='" + (semesters[i]["Semester"] == "Monsoon" ? "M" : "S") + "' " +
            "and year_semester='" + semesters[i]["Year"] + "'";
                    }
                    else
                    {
                        SqlSelect += "Union ALL Select * from instructor_workload_detail " +
                            "  inner join instructor_mst im on im.instructor_code = instructor_workload_detail.instructor_code " +
                            " where instructor_workload_detail.cancel_flag ='N' AND instructor_workload_detail.acceptance ='Y' and uso_hr_approved='Y' AND im.designation ='VF'" +
            "and instructor_workload_detail.instructor_code ='" + intcode + "' " +
            "and semester_type='" + (semesters[i]["Semester"] == "Monsoon" ? "M" : "S") + "' " +
            "and year_semester='" + semesters[i]["Year"] + "'";
                    }

                }
                DataTable dataTable = Get_data(SqlSelect);
                if (dataTable != null)
                {
                    return "true";
                }

            }
            return "false";
        }


        public DataTable CalCulateTotalContactHours(string sem_code, string year_code, string instcode, string coursecode, ArrayList instructor, ArrayList formattedTA, ArrayList formattedAA)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            string SqlSelect = "";


            SqlSelect += @" 
                IF EXISTS (
                    SELECT * 
                    FROM instructor_workload_detail
                    WHERE semester_type = '" + sem_code + @"'
                    AND year_semester = '" + year_code + @"'
                    AND course_code NOT IN ('" + coursecode + @"')
                    AND cancel_flag = 'N'
                    AND instructor_code IN (" + instcode + @")
                    AND admin_approved = 'Y'
                    AND hr_approved = 'Y'
                )
                BEGIN 
                    SELECT * 
                    FROM (
                        SELECT im.instructor_code,im.instructor_name, CASE 
            WHEN t2.total_contact_hrs = 0 THEN 41
            ELSE (t2.total_contact_hrs +t2.total_contact_hrs_new )
        END AS TotalHours
                        FROM (
                            SELECT instructor_code, 
                                   ISNULL(SUM(CAST(total_contact_hrs AS FLOAT)), 0) AS total_contact_hrs,
                                   CASE 
                                       WHEN (40 - ISNULL(SUM(CAST(total_contact_hrs AS FLOAT)), 0)) < 0 THEN 0
                                       ELSE (40 - ISNULL(SUM(CAST(total_contact_hrs AS FLOAT)), 0))
                                   END AS remaining_hrs,ISNULL(TEMP.total_contact_hrs, 0) AS total_contact_hrs_new
                            FROM instructor_workload_detail
                            WHERE semester_type = '" + sem_code + @"'
                            AND year_semester = '" + year_code + @"'
                            AND course_code NOT IN ('" + coursecode + @"')
                            AND cancel_flag = 'N'
                            AND instructor_code IN (" + instcode + @")
                            AND admin_approved = 'Y' 
                            AND hr_approved = 'Y'
                            GROUP BY instructor_code
                        ) t1 
                        INNER JOIN instructor_mst im 
                            ON im.instructor_code = t1.instructor_code
                        LEFT JOIN #TempInstructorWorkload TEMP on im.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS = TEMP.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS
                        
                    ) t2 DROP TABLE #TempInstructorWorkload
                END ELSE BEGIN  SELECT im.instructor_code,im.instructor_name,TEMP.total_contact_hrs as TotalHours FROM  #TempInstructorWorkload TEMP INNER JOIN instructor_mst im 
                            ON im.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS = TEMP.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS DROP TABLE #TempInstructorWorkload END ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBConnection.Close();
                DBConnection.Open();
                DBDataAdpterObject.Fill(ds);
                DBConnection.Close();
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                {
                    return ds.Tables[0];
                }
            }
            catch (Exception ex)
            {
                return null;
            }

        }

        public DataTable TempTableData(string sem_code, string year_code, string instcode, string coursecode, ArrayList instructor, ArrayList formattedTA, ArrayList formattedAA)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            string insertQuery = @" 
            CREATE TABLE #TempInstructorWorkload (
                instructor_code VARCHAR(50),
                total_contact_hrs FLOAT
            );";
            if (instructor.Count > 0)
            {
                for (int inst = 0; inst < instructor.Count; inst++)
                {
                    if (((Dictionary<string, object>)instructor[inst]).ContainsKey("percent_load"))
                    {
                        insertQuery += @"
                                INSERT INTO #TempInstructorWorkload (instructor_code, total_contact_hrs)
                                VALUES ('" + ((Dictionary<string, object>)instructor[inst])["instructor_code"].ToString().Trim() + "', '" + ((Dictionary<string, object>)instructor[inst])["percent_load"].ToString().Trim() + "');";
                    }
                    else if (((Dictionary<string, object>)instructor[inst]).ContainsKey("total_contact_hrs"))
                    {
                        insertQuery += @"
                                INSERT INTO #TempInstructorWorkload (instructor_code, total_contact_hrs)
                                VALUES ('" + ((Dictionary<string, object>)instructor[inst])["instructor_code"].ToString().Trim() + "', '" + ((Dictionary<string, object>)instructor[inst])["total_contact_hrs"].ToString().Trim() + "');";
                    }

                }

            }

            if (formattedTA.Count > 0)
            {
                for (int instTa = 0; instTa < formattedTA.Count; instTa++)
                {
                    insertQuery += @"
                                INSERT INTO #TempInstructorWorkload (instructor_code, total_contact_hrs)
                                VALUES ('" + ((Dictionary<string, object>)formattedTA[instTa])["instructor_code"].ToString().Trim() + "', '" + ((Dictionary<string, object>)formattedTA[instTa])["percent_load"].ToString().Trim() + "');";
                }

            }

            if (formattedAA.Count > 0)
            {
                for (int instAA = 0; instAA < formattedAA.Count; instAA++)
                {
                    insertQuery += @"
                                INSERT INTO #TempInstructorWorkload (instructor_code, total_contact_hrs)
                                VALUES ('" + ((Dictionary<string, object>)formattedAA[instAA])["instructor_code"].ToString().Trim() + "', '" + ((Dictionary<string, object>)formattedAA[instAA])["percent_load"].ToString().Trim() + "');";
                }

            }

            insertQuery += @"
                            IF EXISTS (
                                SELECT * 
                                FROM instructor_workload_detail
                                WHERE admin_approved = 'Y'
                                AND hr_approved = 'Y' 
                                AND semester_type = '" + sem_code + @"'
                                AND year_semester = '" + year_code + @"'
                                AND course_code NOT IN ('" + coursecode + @"')
                                AND cancel_flag = 'N'
                                AND instructor_code IN (" + instcode + @")
                                
                            )
                            BEGIN
                            select STUFF((
                                    SELECT ',' + t4.instructor_name   from (
                            SELECT t3.instructor_code,t3.instructor_name,t3.TotalHours from (
                            SELECT t2.instructor_code,t2.instructor_name,
                            	CASE 
                                        WHEN t2.total_contact_hrs = 0 THEN 41
                                        ELSE (t2.total_contact_hrs +t2.total_contact_hrs_new )
                                    END AS TotalHours from (
                                SELECT 
                                    im.instructor_code,
                                    im.instructor_name,
                                    ISNULL(t1.total_contact_hrs, 0) AS total_contact_hrs,
                                    CASE 
                                        WHEN (40 - ISNULL(t1.total_contact_hrs, 0)) < 0 THEN 0
                                        ELSE (40 - ISNULL(t1.total_contact_hrs, 0))
                                    END AS remaining_hrs,ISNULL(TEMP.total_contact_hrs, 0) AS total_contact_hrs_new
                                FROM (
                                    SELECT 
                                        instructor_code, 
                                        SUM(CAST(total_contact_hrs AS FLOAT)) AS total_contact_hrs
                                    FROM instructor_workload_detail
                                    WHERE semester_type = '" + sem_code + @"'
                                    AND year_semester = '" + year_code + @"'
                                    AND course_code NOT IN ('" + coursecode + @"')
                                    AND cancel_flag = 'N'
                                    AND instructor_code IN (" + instcode + @")
                                    AND admin_approved = 'Y' 
                                    AND hr_approved = 'Y'
                                    GROUP BY instructor_code
                                ) t1 
                                INNER JOIN instructor_mst im 
                                    ON im.instructor_code = t1.instructor_code
                                LEFT JOIN #TempInstructorWorkload TEMP 
                                    ON im.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS = TEMP.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS ) AS t2 ) as t3
                            where t3.TotalHours > 40 ) t4
                            		FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') AS InstructorCodes 
                            
                            END 
                            ELSE 
                            BEGIN
                             SELECT STUFF((
                                SELECT 
                                    ',' + im.instructor_name
                                FROM #TempInstructorWorkload TEMP 
                                INNER JOIN instructor_mst im 
                                    ON im.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS = TEMP.instructor_code COLLATE SQL_Latin1_General_CP1_CI_AS
                            WHERE TEMP.total_contact_hrs > 40
                            		 FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') AS InstructorCodes 
                            END
                            DROP TABLE #TempInstructorWorkload";


            DBDataAdpterObject.SelectCommand.CommandText = insertQuery;

            DataSet ds = new DataSet();
            try
            {
                DBConnection.Open();
                DBDataAdpterObject.Fill(ds);
                DBConnection.Close();
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                {
                    return ds.Tables[0];
                }
            }
            catch (Exception ex)
            {
                return null;
            }

            //return Get_data(SqlSelect);

        }


