        public DataTable GetRateBandSemesterWiseApproveHR(string sem_code, string year_code, string instcode)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect += @" 
                SELECT 
            COALESCE(rate_band, '0') AS rate_band, 
            COALESCE(TotalExperience, '0') AS TotalExperience
            FROM 
                semester_wise_applicant_rateband_approve 
            WHERE 
                cancel_flag = 'N' 
                AND semester_type = '" + sem_code + @"' 
                AND year_semester = '" + year_code + @"'
                AND instructor_code = '" + instcode + @"'
                AND ApproveRateBand = 'A'
            UNION ALL
            SELECT 
                '0' AS rate_band, 
                '0' AS TotalExperience 
            WHERE NOT EXISTS (
                SELECT 1 
                FROM semester_wise_applicant_rateband_approve 
                WHERE cancel_flag = 'N' 
                AND semester_type = '" + sem_code + @"' 
                AND year_semester = '" + year_code + @"'
                AND instructor_code = '" + instcode + @"'
                AND ApproveRateBand = 'A'";

            return Get_data(SqlSelect);

        }

