        public Boolean instructor_wise_Rateband_update(string sem_code, string year_code, string course_code, string user_id, string total_weeks, string total_contact_hrs, string total_hrs, string total_hrs_in_semester, string instructor_code, string inst_type, string course_cancel_flag, string add_hrs)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            string total_exp = "";
            string rate_band = "";
            string alternet_rate_band = "";
            DataTable Get_workload_dtl = workload_Exist_or_not(sem_code, year_code, instructor_code, course_code);

            bool status = course_wise_update_workload(instructor_code, course_code, sem_code, year_code, user_id, HttpContext.Current.Request.UserHostName, total_weeks, total_contact_hrs, total_hrs, total_hrs_in_semester, add_hrs);
            DataTable dt = get_vf_course_wise_workload_detail_v2(course_code, sem_code, year_code, "N");
            DataTable get_studio_code = Get_studio_code_course_wise(course_code, sem_code, year_code);
            DataTable Compaire_workload_old_new_data = compaire_workload_rows(Get_workload_dtl.Rows[0]["doc_no"].ToString(), instructor_code, sem_code, year_code, course_code);
            DataTable get_ta_typology = get_department_wise_get_typology(course_code, sem_code, year_code);
            if (dt != null)
            {
                DataRow[] dr = dt.Select("instructor_code = '" + instructor_code + "'");
                if (dr.Length > 0)
                {
                    total_exp = dr[0]["total_experiance"].ToString();
                    rate_band = dr[0]["rate_band"].ToString();
                    alternet_rate_band = dr[0]["upper_rate_band"].ToString();
                }

                DBConnection.Close();
                DBConnection.Open();
                string strmsg = "[{\"weeks\":\"" + total_weeks + "\",\"contact_hrs\":\"" + total_contact_hrs + "\"}]";
                string SqlSelect = "";
                if (inst_type.ToUpper().Trim() == "TA")
                {
                    if (get_ta_typology != null)
                    {
                        SqlSelect = SqlSelect + " update TA_department_wise_apply set hr_approved ='N',last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'" +
                       " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' and faculty_selected ='Y' and user_id ='" + instructor_code + "'" +
                       " and studio_code in ('" + course_code + "') ";
                    }
                    else
                    {

                        SqlSelect = SqlSelect + " update TA_department_wise_apply set hr_approved ='N',last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'" +
                        " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N' and faculty_selected ='Y' and user_id ='" + instructor_code + "'" +
                        " and studio_code in (select studio_code from instructor_studio_details where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and new_course_code='" + course_code + "' and cancel_flag='N') ";
                    }

                }
                SqlSelect += @"UPDATE course_wise_instructor SET week='" + total_weeks + "',percent_load='" + total_contact_hrs + "'," +
                  " last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag IN ('Y','N') and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and course_code='" + course_code + "' and instructor_code='" + instructor_code + "' ";

                //Changes By Nitinbhai uso hr_approved = Y (Null) Task 2841

                if (Compaire_workload_old_new_data == null)
                {
                    SqlSelect += @"UPDATE instructor_workload_detail SET total_weeks='" + total_weeks + "',total_contact_hrs='" + total_contact_hrs + "',total_hrs='" + total_hrs + "',total_hrs_in_semester='" + total_hrs_in_semester + "',additional_hours='" + add_hrs + "',hours_bifurcation='" + strmsg + "'," +
                            " total_exp='" + total_exp + "',rate_band='" + rate_band + "',alternate_band='" + alternet_rate_band + "',edit_workload = 'Y',admin_approved='Y'";


                    if (get_studio_code == null)
                    {
                        // changes by nitinbhai (call 06012024)
                        if (user_id == "ugpgoffice" || user_id == "phdoffice" || user_id == "ug" || user_id == "pg")
                        {
                            SqlSelect = SqlSelect + " ,hr_approved= 'Y' ";
                        }
                        else { SqlSelect = SqlSelect + " ,hr_approved= NULL"; }

                    }
                    //else 
                    //{
                    //    SqlSelect = SqlSelect + " hr_approved='Y',"; 
                    //}
                    SqlSelect = SqlSelect + " ,acceptance=NULL,acceptance_type=NULL,uso_hr_approved=NULL, last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'  where cancel_flag = 'N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and course_code='" + course_code + "' and instructor_code='" + instructor_code + "' ";

                    //new 11012023
                    SqlSelect = SqlSelect + " update studio_wise_instructor_dtl set approved ='N',pc_status='A',hr_status=NULL,last_modified_by='" + user_id + "', last_modified_date=GETDATE(), last_modified_host='" + HttpContext.Current.Request.UserHostName + "'" +
                           " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and cancel_flag='N'  and instructor_code ='" + instructor_code + "'" +
                           " and studio_code in (select studio_code from instructor_studio_details where semester_type='" + sem_code + "' and year_semester='" + year_code + "' and new_course_code='" + course_code + "' and cancel_flag='N') ";
                }




                /*************************/
                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                try
                {
                    DBCommand.ExecuteNonQuery();
                    DBConnection.Close();

                    return true;
                }
                catch (Exception Ex)
                {
                    DBConnection.Close();

                    return false;
                }
            }
            return true;
