        public string workload_exe_rateband_update(string course_code, string sem_code, string year_code, string inst_code)
        {
            DataTable dt_typology_dtl = get_department_wise_get_typology(course_code, sem_code, year_code);
            DataTable dt = new DataTable();
            if (dt_typology_dtl == null)
            {
                dt = get_vf_course_wise_workload_detail_v2(course_code, sem_code, year_code, "N");
            }
            else
            {
                dt = get_vf_course_wise_workload_detail_v2_TA(course_code, sem_code, year_code, "N");
            }

            dt = dt.Select("instructor_code = '" + inst_code + "'").CopyToDataTable();


            DBConnection.Close();
            DBConnection.Open();
            //DBCommand.Transaction = DBConnection.BeginTransaction();
            string SqlSelect = "";
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                // change by  Nitinbhai 23092024 new RateBand Logic

                //old data 
                //SqlSelect += @"UPDATE instructor_workload_detail SET total_exp='" + dt.Rows[i]["total_experiance"].ToString() + "',rate_band='" + dt.Rows[i]["rate_band"].ToString() + "',alternate_band='" + dt.Rows[i]["upper_rate_band"].ToString() + "'" +
                // "  where cancel_flag = 'N' and instructor_code = '" + inst_code + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and course_code='" + course_code + "' ";


                SqlSelect += @" UPDATE instructor_workload_detail SET total_exp= (SELECT 
	            COALESCE( (SELECT TotalExperience FROM semester_wise_applicant_rateband_approve WHERE instructor_code = '" + inst_code + @"' and semester_type ='" + sem_code + @"' and year_semester ='" + year_code + @"' and cancel_flag ='N' AND ApproveRateBand = 'A'
	            ), '0') AS expr),rate_band = (SELECT 
	            COALESCE( (SELECT rate_band FROM semester_wise_applicant_rateband_approve WHERE instructor_code = '" + inst_code + @"' and semester_type ='" + sem_code + @"' and year_semester ='" + year_code + @"' and cancel_flag ='N' AND ApproveRateBand = 'A'
	            ), '0') AS RateBand),alternate_band='" + dt.Rows[i]["upper_rate_band"].ToString() + "'" +
                "  where cancel_flag = 'N' and instructor_code = '" + inst_code + "' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' and course_code='" + course_code + "' ";
            }

            /*************************/
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();

                DBConnection.Close();

                return "true";
            }
            catch (Exception Ex)
            {
                DBConnection.Close();

                return "false";
            }


        }

