        public bool Update_workload_data_onetime(DataTable dt_insert_rate_band, string sem_code, string year_code, string course_code, string action)
        {
            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                string SqlSelect = "";
                string rate_band = "0";
                for (int i = 0; i < dt_insert_rate_band.Rows.Count; i++)
                {
                    DataTable RatebandData = GetRateBandSemesterWiseApproveHR(sem_code, year_code, dt_insert_rate_band.Rows[i]["instructor_code"].ToString());

                    if (RatebandData != null)
                    {
                        rate_band = RatebandData.Rows[0]["rate_band"].ToString();
                    }
                    if (action == "A")
                    {
                        SqlSelect += @" UPDATE instructor_workload_detail set uso_hr_approved='Y',admin_approved='Y',hr_approved='Y',rate_band='" + rate_band + @"' 
                                    where course_code='" + course_code + @"' and instructor_code='" + dt_insert_rate_band.Rows[i]["instructor_code"].ToString() + @"'
                                    and cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' ";
                    }
                    else
                    {
                        SqlSelect += @" UPDATE instructor_workload_detail set rate_band='" + rate_band + @"' 
                                    where course_code='" + course_code + @"' and instructor_code='" + dt_insert_rate_band.Rows[i]["instructor_code"].ToString() + @"'
                                    and cancel_flag='N' and semester_type='" + sem_code + "' and year_semester='" + year_code + "' ";
                    }
                }


                DBDataAdpterObject.SelectCommand.Parameters.Clear();

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                int noofrows = DBCommand.ExecuteNonQuery();
                if (noofrows > 0)
                {
                    DBCommand.Transaction.Commit();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return true;
                }
                else
                {
