        public DataTable GetStudentWavierCreditdata(string sem_code, string year_code, string userid)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";

            SqlSelect += @" 
                SELECT 
                CASE 
        WHEN EXISTS (SELECT 1 
                     FROM ws_user_fees_status 
                     WHERE semester_type = '" + sem_code + @"' 
                       AND year_type = '" + year_code + @"' 
                       AND cancel_flag = 'N' 
                       AND user_id = '" + userid + @"') 
        THEN (SELECT fees_waiver_credits 
              FROM ws_user_fees_status 
              WHERE semester_type = '" + sem_code + @"' 
                AND year_type = '" + year_code + @"' 
                AND cancel_flag = 'N' 
                AND user_id = '" + userid + @"') 
        ELSE 0 
    END AS fees_waiver_credits";

            return Get_data(SqlSelect);

        }

        public DataTable GetFeesCalculationAndVerificationCreditWise(string sem_code, string year_code, string userid)
        {
            DataTable Currentdt = Get_ws_cept_current_sem_data();
            if (userid != "" && sem_code == "")
            {
                sem_code = Currentdt.Rows[0]["sem_code"].ToString();
                year_code = Currentdt.Rows[0]["year_code"].ToString();
            }
            DBDataAdpterObject.SelectCommand.Parameters.Clear();


            String SqlSelect = "";

            SqlSelect += @" WITH RES_1 AS (
    SELECT 
        t1.user_id,
        t1.AllocatedCredits,
        t1.fees_waiver_credits,
        CASE 
            WHEN t1.AllocatedCredits >= t1.fees_waiver_credits THEN t1.AllocatedCredits - t1.fees_waiver_credits
            ELSE 0
        END AS PaymentRecivedCredit,
        CASE 
            WHEN t1.fees_waiver_credits >= t1.AllocatedCredits THEN t1.fees_waiver_credits - t1.AllocatedCredits
            ELSE 0
        END AS RemaningWavierCredit,
        t1.user_type, 
        t1.prof_details,
        (SELECT 
            COALESCE((
                SELECT 
                    CAST(SUM(CAST(credits AS decimal(10,2))) AS decimal(10,2)) 
                FROM 
                    ws_connect_student_reg_dtl 
                WHERE 
                    semester_type = '" + sem_code + @"' 
                    AND year_semester = '" + year_code + @"'
                    AND cancel_flag = 'N' 
                    AND status IN ('R', 'A') 
                    AND course_drop_status IS NULL 
                    AND course_type = 'M' 
                    AND user_id = t1.user_id
                GROUP BY user_id
            ), 0) ) AS ApplyManditoryCourseCredit
			
    FROM (
        SELECT 
            wcs.user_id, 
            CAST(SUM(CAST(wcs.credits AS decimal(10,2))) AS decimal(10,2)) AS AllocatedCredits, 
            MAX(ISNULL(NULLIF(WU.fees_waiver_credits, ''), 0)) AS fees_waiver_credits,
            MAX(UM.user_type) AS user_type, 
            MAX(UM.prof_details) AS prof_details
        FROM ws_connect_student_reg_dtl wcs
        LEFT JOIN ws_user_fees_status WU 
            ON WU.user_id = wcs.user_id
            AND WU.semester_type = wcs.semester_type
            AND WU.year_type = wcs.year_semester 
            AND WU.cancel_flag = wcs.cancel_flag
        LEFT JOIN user_mst UM 
            ON UM.user_id = wcs.user_id
        WHERE 
            wcs.semester_type = '" + sem_code + @"'
            AND wcs.year_semester = '" + year_code + @"'
            AND wcs.cancel_flag = 'N' 
            AND wcs.course_drop_status IS NULL 
            AND wcs.status IN ('A')
        GROUP BY wcs.user_id
    ) t1
)

SELECT 
    RES.user_id,
    RES.AllocatedCredits,
    RES.fees_waiver_credits,
    RES.PaymentGet,
    RES.PaymentGetApplication,
    CASE 
        WHEN RES.PaymentGet > RES.PaymentGetApplication THEN 'Less Payment'
        WHEN RES.PaymentGet = RES.PaymentGetApplication THEN 'Equal'
        ELSE 'Extra Payment'
    END AS Status,
    CAST((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
        WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
        ELSE 6000 
    END) AS decimal(10,2)) AS PaymentRecivedCredit,
    
    CAST(((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
        WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
        ELSE 6000 
    END) + RES.fees_waiver_credits) AS decimal(10,2)) AS PaymentRecivedCreditWith,
    
    CAST(CASE 
        WHEN (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) != 0 AND RES.AllocatedCredits > ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details ='P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits)) 
        THEN (RES.AllocatedCredits - ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits))
        ELSE (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) - RES.AllocatedCredits)
    END AS decimal(10,2)) AS RemaningWavierCredit,
    RES.ApplyManditoryCourseCredit,  RES.ParCreditFees,
    -- Applying the condition here
	
	
	CASE 
	WHEN RES.ApplyManditoryCourseCredit != 0 AND RES.ApplyManditoryCourseCredit > CAST(CASE 
        WHEN (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) != 0 AND RES.AllocatedCredits > ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details ='P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits)) 
        THEN (RES.AllocatedCredits - ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits))
        ELSE (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) - RES.AllocatedCredits)
    END AS decimal(10,2))
	THEN 

	CAST((RES.ApplyManditoryCourseCredit - CAST(CASE 
        WHEN (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) != 0 AND RES.AllocatedCredits > ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details ='P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits)) 
        THEN (RES.AllocatedCredits - ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits))
        ELSE (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) - RES.AllocatedCredits)
    END AS decimal(10,2))) AS decimal(10,2) )
	WHEN RES.ApplyManditoryCourseCredit != 0 AND CAST(CASE 
        WHEN (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) != 0 AND RES.AllocatedCredits > ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details ='P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits)) 
        THEN (RES.AllocatedCredits - ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits))
        ELSE (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) - RES.AllocatedCredits)
    END AS decimal(10,2)) > RES.ApplyManditoryCourseCredit
	THEN 0
	ELSE 
	0
	END AS GetRemainingCreditPayment ,
   
      CAST((CASE 
	WHEN RES.ApplyManditoryCourseCredit != 0 AND RES.ApplyManditoryCourseCredit > CAST(CASE 
        WHEN (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) != 0 AND RES.AllocatedCredits > ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details ='P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits)) 
        THEN (RES.AllocatedCredits - ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits))
        ELSE (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) - RES.AllocatedCredits)
    END AS decimal(10,2))
	THEN
   (RES.ApplyManditoryCourseCredit - CAST(CASE 
        WHEN (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) != 0 AND RES.AllocatedCredits > ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details ='P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits)) 
        THEN (RES.AllocatedCredits - ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits))
        ELSE (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) - RES.AllocatedCredits)
    END AS decimal(10,2)))
WHEN RES.ApplyManditoryCourseCredit != 0 AND CAST(CASE 
        WHEN (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) != 0 AND RES.AllocatedCredits > ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details ='P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits)) 
        THEN (RES.AllocatedCredits - ((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits))
        ELSE (((CAST(RES.PaymentGetApplication AS decimal(10,2)) / CASE 
            WHEN (RES.user_type = 'E' AND RES.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) + RES.fees_waiver_credits) - RES.AllocatedCredits)
    END AS decimal(10,2)) > RES.ApplyManditoryCourseCredit
THEN
   0
ELSE 0
END * RES.ParCreditFees) AS decimal(10,2)) AS GetRemainingPaymentWithFees
	
FROM (
    SELECT 
        t2.user_id,
        t2.AllocatedCredits,
        t2.fees_waiver_credits,
        t2.PaymentRecivedCredit,
        t2.RemaningWavierCredit,
        (t2.PaymentRecivedCredit * CASE 
            WHEN (t2.user_type = 'E' AND t2.prof_details = 'P') THEN 7500
            ELSE 6000 
        END) AS PaymentGet,

		CASE 
            WHEN (t2.user_type = 'E' AND t2.prof_details = 'P') THEN 7500
            ELSE 6000 
        END AS ParCreditFees,
        (
            SELECT 
                CAST(SUM(CAST(WSAP.amount AS decimal(10,2))) AS decimal(10,2)) 
            FROM ws_applicationpaymenttransaction WSAP 
            WHERE WSAP.semester_type = '" + sem_code + @"'
              AND WSAP.year_semester = '" + year_code + @"'
              AND WSAP.payment_response_code = '0' 
              AND WSAP.user_id = t2.user_id
            GROUP BY WSAP.user_id
        ) AS PaymentGetApplication,
        t2.user_type, 
        t2.prof_details,
		t2.ApplyManditoryCourseCredit
    FROM RES_1 t2
) RES

Where 1=1";
            if (userid != "")
            {
                SqlSelect += " And RES.user_id = '" + userid + @"'";
            }


            return Get_data(SqlSelect);

        }

        public DataTable GetStudentWiseFeesRefundDetails(string sem_code, string year_code)
        {
