            String SqlSelect = "";

            SqlSelect += @" 
                Select um.full_name,um.mail,SA.account_holder_name as AccountHolderName,SA.account_number as AccountNumber,SA.bank_name as BankName,
				SA.branch_name,SA.ifsc_code as IFSCCode,SA.branch_city as BankAddress,SA.branch_state,WSR.* from ws_RefundDetails WSR
                Inner JOIN user_mst um on um.user_id = WSR.UserID
                LEFT JOIN ws_refund_application_dtl SA on SA.user_id = WSR.UserId
