        public DataTable SWSCreditCalculation(string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            String SqlSelect = "";
            SqlSelect = @" SELECT T3.*,
                          (SELECT Status FROM ws_RefundDetails WHERE semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' 
                           AND year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' AND UserId='" + user_id + @"' AND Cancel_flag ='N' ) STUDENTSTATUS,
                           (SELECT AdminStatus FROM ws_RefundDetails WHERE semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' 
                           AND year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' AND UserId='" + user_id + @"' AND Cancel_flag ='N' ) ADMINSTATUS,
                           (SELECT AccountStatus FROM ws_RefundDetails WHERE semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' 
                           AND year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' AND UserId='" + user_id + @"' AND Cancel_flag ='N' ) ACCOUNTSTATUS,
                           (SELECT Remark FROM ws_RefundDetails WHERE semester_type ='" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"' 
                           AND year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"' AND UserId='" + user_id + @"' AND Cancel_flag ='N' ) REMARK,
                           CASE 
						   When (T3.BranchCity IS Not NULL AND T3.BranchState IS Not NULL AND T3.BranchName IS Not NULL AND T3.BankName IS Not NULL AND T3.AccountHolderName IS Not NULL
						   AND T3.AccountNumber IS Not NULL AND T3.IFSCCode IS Not NULL)
						   Then 'TRUE'
						   ELSE 
						   'False'
						   End 
						   As BANK_STATUS

                                From ( SELECT 
                                T2.*,
                                CASE 
                                    WHEN T2.TotalRemaningCredits != 0 AND T2.TotalCreditDepositFeesWise > TotalRemaningCredits
                                    THEN T2.TotalCreditDepositFeesWise - TotalRemaningCredits
                                    WHEN T2.TotalRemaningCredits = 0 
                                    THEN T2.TotalCreditDepositFeesWise
                                    ELSE 0
                                END AS ReFundCredit, 
                                (CASE 
                                    WHEN T2.TotalRemaningCredits != 0 AND T2.TotalCreditDepositFeesWise > TotalRemaningCredits
                                    THEN T2.TotalCreditDepositFeesWise - TotalRemaningCredits
                                    WHEN T2.TotalRemaningCredits = 0 
                                    THEN T2.TotalCreditDepositFeesWise
                                    ELSE 0
                                END) * T2.PerCreditFees AS ReFundPayment
                            FROM (
                                SELECT 
                                    T1.*,
                                    CASE 
                                        WHEN T1.user_type = 'E' AND T1.prof_details = 'P'
                                        THEN 7500
                                        ELSE 6000
                                    END AS PerCreditFees,
                                    CAST(T1.TotalAmount / CASE 
                                        WHEN T1.user_type = 'E' AND T1.prof_details = 'P'
                                        THEN 7500
                                        ELSE 6000
                                    END AS DECIMAL(10, 2)) AS TotalCreditDepositFeesWise,
                                    CASE 
                                        WHEN AllocatedCredit != 0
                                        THEN ISNULL((AllocatedCredit - fees_waiver_credits), 0)
                                        ELSE 0
                                    END AS TotalRemaningCredits
                                FROM (
                                    SELECT 
                                        WSA.USER_ID,
                                        CAST(SUM(WSA.total_amount) AS DECIMAL(10, 2)) AS TotalAmount,
                                        ISNULL(
                                            (SELECT CAST(SUM(CAST(WSC.credits AS INT)) AS DECIMAL(10, 2))
                                             FROM ws_connect_student_reg_dtl WSC
                                             WHERE WSC.user_id = WSA.user_id
                                               AND WSC.semester_type = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"'
                                               AND WSC.year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"'
                                               AND WSC.cancel_flag = 'N'
                                               AND WSC.status IN('P','A')
                                               AND WSC.course_drop_status IS NULL
                                             GROUP BY WSC.user_id), 0) AS AllocatedCredit,
                                        --MAX(ISNULL(WUF.fees_waiver_credits, 0)) AS fees_waiver_credits,
                                        MAX(CASE 
											WHEN ISNULL(LTRIM(RTRIM(WUF.fees_waiver_credits)), '') = '' THEN 0 
											ELSE WUF.fees_waiver_credits END) AS fees_waiver_credits,
                                        MAX(UM.user_type) AS user_type,
                                        MAX(UM.prof_details) AS prof_details,
                                        MAX(SA.account_number) AS AccountNumber,
										MAX(SA.ifsc_code) AS IFSCCode,
										MAX(SA.account_holder_name) AS AccountHolderName,
										MAX(SA.bank_name) AS BankName,
										MAX(SA.branch_name) AS BranchName,
										MAX(SA.branch_city) AS BranchCity,
										MAX(SA.branch_state) AS BranchState
                                    FROM 
                                        ws_applicationpaymenttransaction WSA
                                    LEFT JOIN 
                                        ws_user_fees_status WUF 
                                        ON WUF.user_id = WSA.user_id
                                        AND WUF.semester_type = WSA.semester_type 
                                        AND WUF.year_type = WSA.year_semester
                                        AND WUF.cancel_flag = 'N'
                                    LEFT JOIN 
                                        user_mst UM 
                                        ON UM.user_id = WSA.user_id
                                     LEFT JOIN 
                                        ws_refund_application_dtl SA 
                                        ON SA.user_id = WSA.user_id
										AND SA.semester_type = WSA.semester_type
										AND SA.year_semester = WSA.year_semester
										AND SA.cancel_flag = 'N'
                                    WHERE 
                                        WSA.semester_type = '" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"'
                                        AND WSA.year_semester = '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"'
                                        AND WSA.payment_response_code = '0'
                                        AND WSA.total_amount != 0 
                                    GROUP BY 
                                        WSA.user_id
                                ) AS T1
                            ) T2 ) T3 
                            WHERE 1 = 1 
                                AND T3.user_id = '" + user_id + @"'  AND T3.ReFundPayment !=0 ";


            return Get_data(SqlSelect);
        }


        public bool ws_apply_refund_dtl(string UserID)
        {
            string host_name = HttpContext.Current.Request.UserHostName.ToString();
            string Host = HttpContext.Current.Request.UserHostName;
            string Date = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            DataTable GetRefundDetails = SWSCreditCalculation(UserID);

            if (GetRefundDetails != null)
            {


                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();
                String SqlSelect = "";

                try
                {
                    string feesWaiverCredits = string.IsNullOrWhiteSpace(GetRefundDetails.Rows[0]["fees_waiver_credits"].ToString()) ? "0" : GetRefundDetails.Rows[0]["fees_waiver_credits"].ToString();

                    SqlSelect += @"INSERT INTO ws_RefundDetails (
                    UserId, 
                    TotalAllocatedCredit, 
                    TotalFeesWaiverCredit,
                    TotalPaidFeesAmount, 
                    TotalReFundAmount,
                    Status,
                    semester_type, 
                    year_semester, 
                    Cancel_flag, 
                    created_by, 
                    created_date, 
                    created_host
                )
                VALUES (
                    '" + UserID + @"', 
                    '" + GetRefundDetails.Rows[0]["AllocatedCredit"].ToString() + @"', 
                    '" + feesWaiverCredits + @"', 
                    '" + GetRefundDetails.Rows[0]["TotalAmount"].ToString() + @"', 
                    '" + GetRefundDetails.Rows[0]["ReFundPayment"].ToString() + @"', 
                    'Y', 
                    '" + dt_current_sem.Rows[0]["sem_code"].ToString() + @"', 
                    '" + dt_current_sem.Rows[0]["year_code"].ToString() + @"', 
                    'N', 
                    '" + UserID + @"', 
                    '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss.ffffff") + @"', 
                    '" + host_name + @"')";

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                    int res_insert = DBCommand.ExecuteNonQuery();

                }
                catch (Exception ex)
                {
                    ServerLog.ExceptionLog("Sws EX  : " + ex.Message);
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }

                DBCommand.Transaction.Commit();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return true;
            }
            return false;


        }


