        public Boolean update_student_Bank_dtl(string user_id, Dictionary<string, object> address_data)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DataTable dt_current_sem = Get_ws_cept_current_sem_data();
            string sem = dt_current_sem.Rows[0]["sem_code"].ToString();
            string year = dt_current_sem.Rows[0]["year_code"].ToString();
