        public DataTable GetTRFStatus(string user_id, string semester_type, string year_semester, string doc_no)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @" DECLARE @docNumber INT; 

                           IF EXISTS (
                               SELECT 1 
                               FROM TRF_OtherDetails 
                               WHERE 
                                 semester_type = '" + semester_type + @"'  
                                 AND year_semester = '" + year_semester + @"'  
                                 AND cancel_flag = 'N' 
                                 AND FacultyStatus = 'N'
                                 AND doc_no = '" + doc_no + @"'
                           )
                           BEGIN
                               -- If data exists, get the document number
                               SELECT @docNumber = doc_no
                               FROM TRF_OtherDetails 
                               WHERE semester_type = '" + semester_type + @"'  
                                 AND year_semester = '" + year_semester + @"'
                                 AND cancel_flag = 'N' 
                                 AND FacultyStatus = 'N' AND doc_no = '" + doc_no + @"' ;
                                 
                               -- Return or use the doc number as needed
                               SELECT @docNumber AS DocumentNumber;
                           END
                           ELSE
                           BEGIN
                               -- If data does not exist, update the next_doc_no table
                               UPDATE next_doc_no
                               SET next_doc_no = next_doc_no + 1
                               WHERE company_id ='01' AND doc_type ='TRF' ; 
                           
                               -- Get the new document number
                               SELECT @docNumber = next_doc_no
                               FROM next_doc_no
                               WHERE company_id ='01' AND doc_type ='TRF';
                               
                               SELECT @docNumber AS DocumentNumber;
                           END ";


            return Get_data(SqlSelect);
        }

