        }

        public DataTable GetTRFDetails(string user_id, string semester_type, string year_semester)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            String SqlSelect = "";
            SqlSelect = @" SELECT TRF_OtherDetails.doc_no AS TRF_doc, im.instructor_name, im.mail, im.mobile_no, TRF_OtherDetails.FacultyStatus
                            FROM TRF_OtherDetails
                            LEft JOIN instructor_mst im ON im.user_id = TRF_OtherDetails.Userid
                            WHERE TRF_OtherDetails.Userid = '" + user_id + @"'
                            AND TRF_OtherDetails.cancel_flag = 'N'
                            AND TRF_OtherDetails.semester_type ='" + semester_type + @"' and TRF_OtherDetails.year_semester='" + year_semester + @"'
                            
                            UNION
                            
                            SELECT TRF_PersonalDetails.doc_no AS TRF_doc, TRF_PersonalDetails.Name AS instructor_name,
                                   NULL AS mail, TRF_PersonalDetails.ContactNo AS mobile_no,
                                   --TRF_PersonalDetails.EditRights AS FacultyStatus
                                   CASE 
								   When (select FacultyStatus from TRF_OtherDetails where doc_no = TRF_PersonalDetails.doc_no) = 'Y' Then 'Y'
								   Else TRF_PersonalDetails.EditRights ENd  AS FacultyStatus
                            FROM TRF_PersonalDetails
                            WHERE TRF_PersonalDetails.UserId = '" + user_id + @"'
                              AND TRF_PersonalDetails.cancel_flag = 'N'
                              AND TRF_PersonalDetails.doc_no IN (SELECT doc_no
                                FROM TRF_OtherDetails 
                                WHERE TRF_OtherDetails.semester_type ='" + semester_type + @"' and TRF_OtherDetails.year_semester='" + year_semester + @"'
                                AND TRF_OtherDetails.cancel_flag = 'N')
                              AND NOT EXISTS (
                                SELECT 1
                                FROM TRF_OtherDetails
                                WHERE TRF_OtherDetails.doc_no = TRF_PersonalDetails.doc_no
                                  AND TRF_OtherDetails.Userid = TRF_PersonalDetails.UserId
                                  AND TRF_OtherDetails.cancel_flag = 'N'
                                  AND TRF_OtherDetails.semester_type ='" + semester_type + @"' and TRF_OtherDetails.year_semester='" + year_semester + @"'
                              );
                            ";


            return Get_data(SqlSelect);
        }


        public DataSet GetTRFAllData(string doc_no)
        {

            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";


            SqlSelect = @"Select TRFM.FacultyName As NameOFFaculty, * From TRF_OtherDetails Left join instructor_mst im on im.instructor_code = TRF_OtherDetails.UserId 
                           Left join TRF_FacultyMaster TRFM on TRFM.FacultyCode = TRF_OtherDetails.FacultyType
                          where TRF_OtherDetails.doc_no ='" + doc_no + @"' and TRF_OtherDetails.cancel_flag ='N'
                          Select 
                          Case When Gender = 'M' Then 'Male' Else 'Female' End GenderDtl,Case When MealRequest = 'Y' Then 'Yes' Else 'No' End MealDtl,
                          * From TRF_PersonalDetails where doc_no = '" + doc_no + @"' and cancel_flag = 'N'
                          Select* From TRF_TravelDetails where doc_no = '" + doc_no + @"' and cancel_flag = 'N'
                          Select * From TRF_TaxiDetails where doc_no = '" + doc_no + @"' and cancel_flag = 'N'
                          Select Case When PaymentMode = 'O' Then 'Online'
                          When PaymentMode = 'C' Then 'Case'
                          Else 'Card' End PaymentModeDtl,* From TRF_AccommodationDetails where doc_no = '" + doc_no + @"' and cancel_flag = 'N'
                          SELECT full_name,mobile_no,mail from user_mst where user_id = (select created_by from TRF_OtherDetails where doc_no = '" + doc_no + @"' and cancel_flag='N')
                          SELECT instructor_name,mobile_no,mail from instructor_mst  where instructor_code = (select created_by from TRF_OtherDetails where doc_no = '" + doc_no + @"' and cancel_flag='N')";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

            DataSet ds = new DataSet();
            try
            {
                DBDataAdpterObject.Fill(ds);
                if (ds.Tables[0].Rows.Count <= 0)
                    return null;
                else
                    return ds;
            }
            catch (Exception ex)
            {
                return null;
            }
        }


        public DataTable GetProvisionalCertificatePdf(string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            //SqlSelect = @" Select dm.degree_name as degreename,REPLACE(SUBSTRING(STD.graduation_date_code, 6, 3), '_', '') + ' ' + 
            //               SUBSTRING(STD.graduation_date_code, 1, 4) AS graduationdate,'Faculty Of '+ dep.dept_name as deptName,
            //               Format(GETDATE(),'dd MMM yyyy') As issueDate,* from user_mst um
            //               Left join degree_mst dm on dm.prog_level_code = um.prog_level_code and dm.cancel_flag ='N'
            //               left join student_transcript_dtl STD on STD.user_id = um.user_id
            //               LEft join department_mst dep on dep.dept_code = um.dept_code
            //               where um.user_id='" + user_id +"'";

            SqlSelect = @"  Select dm.degree_name as degreename,REPLACE(SUBSTRING(STD.graduation_date_code, 6, 3), '_', '') + ' ' + 
                           SUBSTRING(STD.graduation_date_code, 1, 4) AS graduationdate_old,
						   stcd.graduation_date AS graduationdate,'Faculty of '+ dep.dept_name as deptName,
                           Format(GETDATE(),'dd MMM yyyy') As issueDate,stco.completion_date,dbo.fn_ProperCase(um.user_name) AS user_name  from user_mst um
                           --Left join degree_mst dm on dm.prog_level_code = um.prog_level_code and dm.cancel_flag ='N'
                           left join student_transcript_dtl STD on STD.user_id = um.user_id
                           Left join degree_mst dm on dm.degree_code = STD.degree_code and dm.cancel_flag ='N' and dm.prog_level_code = um.prog_level_code
						   left join student_transcript_convocation_date stcd on stcd.graduate_date_code = STD.graduation_date_code and stcd.cancel_flag ='N'
						   left join student_transcript_completion_date stco on stco.completion_date_code = STD.completion_date_code and stco.cancel_flag ='N'
                           LEft join department_mst dep on dep.dept_code = um.dept_code
                           where um.user_id='" + user_id + "'";



            return Get_data(SqlSelect);
        }


        public DataTable GetCurrentSemCreditAllocatedUser(string user_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @" SELECT ISNULL(SUM(total_credits_completed),0) AS total_credits_all_semesters,(Select sem_code from cept_current_semester where type_desc ='all') sem_code,
                                (Select year_code from cept_current_semester where type_desc ='all') year_code,
                                (Select prog_code from user_mst where user_id = '" + user_id + @"') prog_code
                           FROM (
                               SELECT SUM(CAST(credits AS INT)) AS total_credits_completed
                               FROM student_course_allocate_dtl
                               WHERE semester_type = (Select sem_code from cept_current_semester where type_desc ='all')
                                 AND year_semester = (Select year_code from cept_current_semester where type_desc ='all')
                                 AND cancel_flag = 'N'
                                 AND user_id = '" + user_id + @"'
                               GROUP BY user_id
                           
                               UNION ALL
                           
                               SELECT SUM(CAST(credits AS INT)) AS total_credits_completed
                               FROM ws_student_course_allocate_dtl
                               WHERE semester_type = (Select sem_code from ws_current_semester where cancel_flag='N')
                                 AND year_semester = (Select year_code from ws_current_semester where cancel_flag='N')
                                 AND cancel_flag = 'N'
                                 AND user_id = '" + user_id + @"'
                               GROUP BY user_id
                           ) AS combined_credits;";



            return Get_data(SqlSelect);
        }


        public Boolean StudentWiseSaveSGPACGPAData(string user_id, Dictionary<string, object>[] personal_data_dict, string host)
        {

            DBConnection.Open();
            DBCommand.Transaction = DBConnection.BeginTransaction();
            String SqlSelect = "";
            bool SQlStatus = false;
            try
            {
                JavaScriptSerializer ser = new JavaScriptSerializer();
                DBDataAdpterObject.SelectCommand.Parameters.Clear();




                for (int q = 0; q < personal_data_dict.Length; q++)
                {

                    SqlSelect = "";

                    SqlSelect = " IF EXISTS(select * from StudentWiseSaveSGPACGPA where studentid = @studentid and semester= @semester and year_semester = @year_semester and cancel_flag = 'N') "
                          + " BEGIN "
                          + " update StudentWiseSaveSGPACGPA set cancel_flag = 'Y',last_modified_by = @last_modified_by, "
                          + " last_modified_date = @last_modified_date ,last_modified_host = @last_modified_host where studentid = @studentid and semester= @semester and year_semester = @year_semester and cancel_flag = 'N' "
                          + " END ";
                    Dictionary<string, object> dict = personal_data_dict[q];
                    DBDataAdpterObject.SelectCommand.Parameters.Clear();
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@studentid", DbType.String, dict["user_id"]));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semester", DbType.String, dict["semester_type"]));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@year_semester", DbType.String, dict["year_semester"]));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@last_modified_date", DbType.DateTime, DateTime.Now));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@last_modified_host", DbType.String, host));
                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@last_modified_by", DbType.String, user_id));

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    if (DBCommand.ExecuteNonQuery() > 0)
                    {
                        SQlStatus = true;
                    }


                }



                SqlSelect = "";
                SqlSelect += @" INSERT INTO StudentWiseSaveSGPACGPA (studentid,EnrollmentYear,TotalCreditRegistered,CreditCompleted,EarnGPACredits,EarnNGPACredits,SemesterGPA,TotalCGPA,semester,year_semester,cancel_flag,created_by,created_date,created_host,semester_wise_cgpa,Total_cgpa_four_digit,semester_wise_cgpa_four_digit,dept_code,prog_code,semestercode)
                                VALUES (@studentid,@EnrollmentYear,@TotalCreditRegistered,@CreditCompleted,@EarnGPACredits,@EarnNGPACredits,@SemesterGPA,@TotalCGPA,@semester,@year_semester,@cancel_flag,@created_by,@created_date,@created_host,@semester_wise_cgpa,@Total_cgpa_four_digit,@semester_wise_cgpa_four_digit,@dept_code,@prog_code,@semestercode);";


                for (int p = 0; p < personal_data_dict.Length; p++)
                {
                    try
                    {
                        Dictionary<string, object> dict = personal_data_dict[p];


                        DBDataAdpterObject.SelectCommand.Parameters.Clear();
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@studentid", DbType.String, dict["user_id"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@EnrollmentYear", DbType.String, dict["year_code_actual"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@TotalCreditRegistered", DbType.String, dict["semester_wise_total_credit"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@CreditCompleted", DbType.String, dict["credits_completed"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@EarnGPACredits", DbType.String, dict["earn_gpa_credit"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@EarnNGPACredits", DbType.String, dict["earn_ngpa_credit"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@dept_code", DbType.String, dict["dept_code"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@prog_code", DbType.String, dict["prog_code"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semestercode", DbType.String, dict["semestercode"]));

                        if (dict["semester_wise_cgpa"].ToString() != "NaN" && dict["semester_wise_cgpa"].ToString() != "")
                        {
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semester_wise_cgpa", DbType.Decimal, Convert.ToDecimal(dict["semester_wise_cgpa"])));
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semester_wise_cgpa_four_digit", DbType.Decimal, Convert.ToDecimal(dict["semester_wise_cgpa_four_digit"])));
                        }
                        else
                        {
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semester_wise_cgpa", DbType.Decimal, Convert.ToDecimal("0")));
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semester_wise_cgpa_four_digit", DbType.Decimal, Convert.ToDecimal("0")));
                        }



                        if (dict["sem_grade_point_ratio_actual"].ToString() != "-" && dict["sem_grade_point_ratio_actual"].ToString() != "")
                        {
                            decimal semGradePointRatioActual = Convert.ToDecimal(dict["sem_grade_point_ratio_actual"]);
                            decimal roundedSemesterGPA = Math.Round(semGradePointRatioActual, 1);
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@SemesterGPA", DbType.Decimal, roundedSemesterGPA));

                        }
                        else
                        {
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@SemesterGPA", DbType.String, "0"));
                        }
                        if (dict["Total_CGPA"].ToString() != "-")
                        {
                            decimal totalCGPA = Convert.ToDecimal(dict["Total_CGPA"]);
                            decimal roundedTotalCGPA = Math.Round(totalCGPA, 1);
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@TotalCGPA", DbType.Decimal, roundedTotalCGPA));
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Total_cgpa_four_digit", DbType.Decimal, Convert.ToDecimal(dict["Total_cgpa_four_digit"])));
                        }
                        else
                        {
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@TotalCGPA", DbType.Decimal, Convert.ToDecimal("0")));
                            DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Total_cgpa_four_digit", DbType.String, "0"));
                        }

                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@semester", DbType.String, dict["semester_type"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@year_semester", DbType.String, dict["year_semester"]));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@cancel_flag", DbType.String, "N"));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@created_date", DbType.DateTime, DateTime.Now));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@created_host", DbType.String, host));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@created_by", DbType.String, user_id));


                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@last_modified_date", DbType.DateTime, DateTime.Now));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@last_modified_host", DbType.String, host));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@last_modified_by", DbType.String, user_id));


                        DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                        if (DBCommand.ExecuteNonQuery() > 0)
                        {
                            SQlStatus = true;
                        }
                        else
                        {
                            DBCommand.Transaction.Rollback();
                            DBConnection.Close();
                            return false;
                        }
                    }
                    catch (Exception EX)
                    {
                        DBCommand.Transaction.Rollback();
                        DBConnection.Close();
                        return false;
                    }


                }
                SqlSelect = "";

                SqlSelect = " Update StudentWiseSaveSGPACGPA set TotalCGPA = @TotalCGPA,Total_cgpa_four_digit = @Total_cgpa_four_digit "
                      + "  Where studentid = @studentid and cancel_flag = 'N' ";
                for (int s = 0; s < personal_data_dict.Length; s++)
                {
                    Dictionary<string, object> dict = personal_data_dict[s];
                    DBDataAdpterObject.SelectCommand.Parameters.Clear();

                    if (dict["Total_CGPA"].ToString() != "-")
                    {
                        decimal totalCGPA = Convert.ToDecimal(dict["Total_CGPA"]);
                        decimal roundedTotalCGPA = Math.Round(totalCGPA, 1);
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@TotalCGPA", DbType.Decimal, roundedTotalCGPA));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Total_cgpa_four_digit", DbType.Decimal, Convert.ToDecimal(dict["Total_cgpa_four_digit"])));
                    }
                    else
                    {
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@TotalCGPA", DbType.String, "0"));
                        DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@Total_cgpa_four_digit", DbType.String, "0"));
                    }

                    DBDataAdpterObject.SelectCommand.Parameters.Add(BLGeneralUtil.MakeParameter("@studentid", DbType.String, dict["user_id"]));
                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    if (DBCommand.ExecuteNonQuery() > 0)
                    {
                        SQlStatus = true;
                    }
                    else
                    {
                        DBCommand.Transaction.Rollback();
                        DBConnection.Close();
                        return false;
                    }
                }
                if (SQlStatus)
                {
                    DBCommand.Transaction.Commit();
                }
                else
                {
                    DBCommand.Transaction.Rollback();
                    DBConnection.Close();
                    return false;
                }


                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                DBConnection.Close();
                return false;
            }
        }


