        public Boolean InsertDataSemesterCount(string year)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Open();
            /*************************/
            String SqlSelect = "";
            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                SqlSelect = "";

                string currentsem = "M " + year.Substring(1, 4);
                SqlSelect = @" DECLARE @SemesterCount INT = 1;
                                DECLARE @CurrentSemester VARCHAR(10) = '" + currentsem + @"';
                                DECLARE @CurrentYear INT = '" + year.Substring(1, 4) + @"';  
                                DECLARE @EnrollmentYear INT = '" + year.Substring(1, 4) + @"';  
                                
                                WHILE @SemesterCount <= 20
                                BEGIN
                                    IF NOT EXISTS (SELECT 1 FROM SemesterTable WHERE Semester = @CurrentSemester AND EnrollmentYear = @EnrollmentYear )
                                    BEGIN
                                        INSERT INTO SemesterTable (Semester, SemesterCount, EnrollmentYear)
                                        VALUES (@CurrentSemester, @SemesterCount, @EnrollmentYear);
                                    END
                                    IF LEFT(@CurrentSemester, 1) = 'M'
                                    BEGIN
                                        SET @CurrentSemester = 'S ' + CAST(@CurrentYear + 1 AS VARCHAR(4));
                                    END
                                    ELSE
                                    BEGIN
                                        SET @CurrentYear = @CurrentYear + 1; 
                                        SET @CurrentSemester = 'M ' + CAST(@CurrentYear AS VARCHAR(4));
                                    END
                                    SET @SemesterCount = @SemesterCount + 1;
                                END; ";

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception)
            {
                DBConnection.Close();
                return false;
            }
        }


