        public DataTable GetStudentMigratioDetails(string student_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @" SELECT 
                           UM.user_id,
                           UM.full_name + ' (' + UM.user_id + ')' AS FullName,
                           PLM.prog_level_name,
                           'Faculty of ' + dm.dept_name AS deptName,
                           'Monsoon ' + SUBSTRING(UM.year_code, 2, 6) AS Dateofjoining,
                           STCD.graduation_date as graduation_dates,
                           SUBSTRING(UPPER(SUBSTRING(STCD.graduation_date, 1, 1)), 1, 1) + LOWER(SUBSTRING(STCD.graduation_date, 2, LEN(STCD.graduation_date))) AS graduation_date,
                           UM.dob,
                           FORMAT(TRY_CAST(UM.dob AS DATETIME), 'dd MMMM yyyy') AS DateOfBirth,
                           
                           CASE WHEN UM.gender = 'F' THEN 'Her' ELSE 'His' END AS PossessivePronoun,
                           CASE WHEN UM.gender = 'F' THEN 'She' ELSE 'He' END AS SubjectPronoun,
                           
                           dg.degree_name AS DegreeAwarded, 
                           STD.degree_code,
                           SECD.FA_Status,
                           SECD.UGPG_Status,
                           SECD.Examination_Status,
                           FORMAT(GETDATE(),'dd MMMM yyyy') as CurrentDate,
                           LTRIM(RTRIM(SECD.student_id)) AS CleanedStudentID,
                       
                           CASE
                               WHEN SECD.FA_Status = 'N' OR SECD.FA_Status IS NULL THEN 'FA Not Approved'
                               WHEN SECD.UGPG_Status = 'N' OR SECD.UGPG_Status IS NULL THEN 'UGPG Not Approved'
                               WHEN SECD.Examination_Status = 'N' OR SECD.Examination_Status IS NULL THEN 'Examination Not Approved'
                               ELSE 'Approved'
                           END AS StatusForApprove,
                       
                           CASE
                               WHEN SECD.FA_Status = 'N' OR SECD.FA_Status IS NULL THEN 'N'
                               WHEN SECD.UGPG_Status = 'N' OR SECD.UGPG_Status IS NULL THEN 'N'
                               WHEN SECD.Examination_Status = 'N' OR SECD.Examination_Status IS NULL THEN 'N'
                               ELSE 'Y'
                           END AS StatusFlag,
                           STD.completion_date_code,
                           SCD.completion_date as completiondates,
                           SUBSTRING(UPPER(SUBSTRING(SCD.completion_date, 1, 1)), 1, 1) + LOWER(SUBSTRING(SCD.completion_date, 2, LEN(SCD.completion_date))) AS completiondate,
                           SCD.convocation_year As convocationyear,SECD.Migration_no,
	                      (Select Top(1) CASE When semester_type ='S' Then 'Spring' Else 'Monsoon' End + ' ' + year_semester As semesterEnd  from student_course_allocate_dtl where user_id = '" + student_id + @"' and cancel_flag='N' order by created_date desc) As semesterEnd,
                       'No: CEPT/' + 
                        CASE 
                            WHEN UM.dept_code = '1' THEN 'FA'
                            WHEN UM.dept_code = '2' THEN 'FD'
                            WHEN UM.dept_code = '3' THEN 'FM'
                            WHEN UM.dept_code = '4' THEN 'FP'
                            WHEN UM.dept_code = '5' THEN 'FT'
                            WHEN UM.dept_code = '6' THEN 'FC'
                            WHEN UM.dept_code = '7' THEN 'FSW'
                            WHEN UM.dept_code = '8' THEN 'FAU'
                            WHEN UM.dept_code = '9' THEN 'FCF'
                            WHEN UM.dept_code = '10' THEN 'FD'
                            WHEN UM.dept_code = '91' THEN 'FCS' ELSE ''
                        END  + '-' +PM.prog_name + '/' + ISNULL(SCD.convocation_year, '') + '/' + 
                            
                            ISNULL(CAST(SECD.Migration_Sq_no AS NVARCHAR), '1')
                            AS TitleMigration
                       FROM 
                           user_mst UM
                       LEFT JOIN 
                           programme_level_mst PLM ON PLM.prog_level_code = UM.prog_level_code
                       LEFT JOIN 
                           department_mst dm ON dm.dept_code = UM.dept_code
                       LEFT JOIN 
                           Student_Eligiblity_Convocation_Details SECD ON SECD.student_id = UM.user_id AND SECD.cancel_flag = 'N'
                       LEFT JOIN 
                           student_transcript_dtl STD ON STD.user_id = UM.user_id
                       LEFT JOIN 
                           student_transcript_convocation_date STCD ON STCD.graduate_date_code = STD.graduation_date_code
                       LEFT JOIN 
                           degree_mst dg ON dg.degree_code = STD.degree_code AND dg.cancel_flag = 'N'
                       LEFT JOIN 
                           student_transcript_completion_date SCD on SCD.completion_date_code = STD.completion_date_code and SCD.cancel_flag='N'

                        LEFT JOIN programme_mst PM On PM.prog_code = UM.prog_code and PM.cancel_flag='N'
                       WHERE 
                           UM.user_type = 'S' AND UM.user_id = '" + student_id + @"'";
            return Get_data(SqlSelect);
        }



        public DataTable GetStudentLasterSemester(string student_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @" Select * From
                           (
                               Select Top(1) 
                                   CASE 
                                       When semester_type = 'S' Then 'Spring' 
                                       Else 'Monsoon' 
                                   End + ' ' + year_semester As semesterEnd,
                                   CAST(year_semester AS INT) AS yearCheck,
                                   semester_type as SemCode
                               From student_course_allocate_dtl 
                               Where user_id = '" + student_id + @"' 
                                 And cancel_flag = 'N' 
                               Order by created_date desc
                           ) AS student_allocate
                           
                           Union ALL
                           
                           Select * From
                           (
                               Select Top(1) 
                                   CASE 
                                       When semester_type = 'S' Then 'Spring' 
                                       Else 'Monsoon' 
                                   End + ' ' + year_semester As semesterEnd,
                                   CAST(year_semester AS INT) AS yearCheck,
                                   semester_type as SemCode
                               From ws_student_course_allocate_dtl 
                               Where user_id = '" + student_id + @"'
                                 And cancel_flag = 'N' 
                               Order by created_date desc
                           ) AS ws_student_allocate;
                            ";


            return Get_data(SqlSelect);
        }
        public DataTable GetStudentApaarId(string Prog_code, string dept_code, string year_code)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @" Select um.full_name,um.mail,um.mobile_no,um.user_id,
						   student_id_master.university_register_id,student_apaar_id.apaar_id,student_apaar_id.student_name
						   From user_mst um
						   LEFT join student_id_master on student_id_master.student_id = um.user_id AND student_id_master.cancel_flag='N' 
