        public dynamic Update_TA_department_wise_apply_dtl(string Course_Code, string semester, string year, string user_id, string loginuserid)
        {
            /*************************/
            /* ESTABLISH CONNECTION */

            /*************************/


            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();


            String SqlSelect = "";


            SqlSelect = @"IF EXISTS(Select distinct studio_code from instructor_studio_details where (studio_code = '" + Course_Code + @"' 
                            or course_code = '" + Course_Code + @"' or new_course_code = '" + Course_Code + @"') 
							and cancel_flag = 'N' and semester_type = '" + semester + @"' and year_semester = '" + year + @"' ) "
                      + " BEGIN "
                      + " update TA_department_wise_apply set hr_approved ='Y', last_modified_by = '" + loginuserid + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' "
                      + " where semester_type = '" + semester + "' and year_semester = '" + year + "' and hr_approved='N' and faculty_selected ='Y' and cancel_flag='N' "
                      + " AND user_id in (" + user_id + @") AND studio_code in (Select distinct studio_code from instructor_studio_details where (studio_code = '" + Course_Code + @"' 
                          OR course_code = '" + Course_Code + @"' or new_course_code = '" + Course_Code + @"') 
					      AND cancel_flag = 'N' and semester_type = '" + semester + @"' and year_semester = '" + year + @"' )"
                      + " END "
                  + " ELSE "
                      + " BEGIN "
                      + " update TA_department_wise_apply set hr_approved ='Y', last_modified_by = '" + loginuserid + "' , last_modified_host = '" + HttpContext.Current.Request.UserHostName + "' , last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' "
                      + " where semester_type = '" + semester + "' and year_semester = '" + year + "' and hr_approved='N' and faculty_selected ='Y' and cancel_flag='N' "
                      + " AND user_id in (" + user_id + @") AND studio_code in ('" + Course_Code + @"')"
                      + " END ";

            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBConnection.Close();
                return false;
            }
        }

