        public dynamic WS_Insert_Transaction_data(string StudentID, string transactionId, string credit, string PaymentMode, string Amount, string loginuserid)
        {
            Document objDocument = new Document();
            DBConnection.Open();
            DBCommand.Transaction = DBConnection.BeginTransaction();

            string DocNo = "";
            string message = "";
            if (!objDocument.W_GetNextDocumentNo(ref DBCommand, "01", "SPT", loginuserid, HttpContext.Current.Request.UserHostName, ref DocNo, ref message))
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;
            }
            DocNo = "TRNSID" + DocNo;
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @"IF Not EXISTS(select * from ws_applicationpaymenttransaction where user_id='" + StudentID + @"' and semester_type = (select sem_code from ws_current_semester where cancel_flag='N')
                        and year_semester = (select year_code from ws_current_semester where cancel_flag='N') and payment_transaction_reference_id ='" + transactionId + @"' ) "
                      + " BEGIN "
                      + @" INSERT INTO ws_applicationpaymenttransaction (transaction_id,user_id,current_sem_code,payment_send_flag,payment_return_flag,semester_type,year_semester,dept_id,payment_response_code,
                           payment_response_msg,payment_transaction_reference_id,amount,status_is_active,created_by,created_date,created_host,Citrus_PaymentMode,Citrus_TxStatus)
                           Values('" + DocNo + @"','" + StudentID + @"','0','Y','Y',(select sem_code from ws_current_semester where cancel_flag='N'),(select year_code from ws_current_semester where cancel_flag='N'),(select dept_code from user_mst where user_id ='" + StudentID + @"'),'0',
                          'Manually Transaction Successfull','" + transactionId + @"','" + Amount + @"','Y','" + loginuserid + @"','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + HttpContext.Current.Request.UserHostName + @"','" + PaymentMode + "','SUCCESS') "
                          + " Update ws_user_fees_status set fees_status ='Y' Where  user_id='" + StudentID + @"' and cancel_flag='N' 
                            and semester_type = (select sem_code from ws_current_semester where cancel_flag='N') and year_type = (select year_code from ws_current_semester where cancel_flag='N') "
                      + " END ";


            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
            try
            {
                DBCommand.ExecuteNonQuery();
                DBCommand.Transaction.Commit();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                DBConnection.Close();
                return false;
            }
        }



