        public Boolean Send_Mail_for_ProvisionalCertificate(string UserID, string user_type, string LoginUserID)
        {
            DataTable Get_Remark = GetDataForProvisnalCertificate(UserID);
            DataTable current_dt = getCurrentSemYearCallForStudio();
            DataTable mail_from_id_password = new DataTable();
            DataTable AckDetails = new DataTable();
            if (user_type == "A1")
            {
                mail_from_id_password = check_frommail_id_password("ProvisionalCertificate_ugpg_remark");
                AckDetails = Get_VF_TA_AA_Letter_Email_Body("ProvisionalCertificate_ugpg_remark", "email");
            }
            else if (user_type == "FA")
            {
                mail_from_id_password = check_frommail_id_password("ProvisionalCertificate_admin_remark");
                AckDetails = Get_VF_TA_AA_Letter_Email_Body("ProvisionalCertificate_admin_remark", "email");
            }
            else if (user_type == "AC")
            {
                mail_from_id_password = check_frommail_id_password("ProvisionalCertificate_account_remark");
                AckDetails = Get_VF_TA_AA_Letter_Email_Body("ProvisionalCertificate_account_remark", "email");
            }
            else if (user_type == "exam")
            {
                mail_from_id_password = check_frommail_id_password("ProvisionalCertificate_exam_remark");
                AckDetails = Get_VF_TA_AA_Letter_Email_Body("ProvisionalCertificate_exam_remark", "email");
            }
            DataTable user_dtl = check_user_by_user_id(UserID);
            DataTable Loginuserid = check_user_by_user_id(LoginUserID);
            DataTable faculty_admin = fa_dtl_dept_wise(user_dtl.Rows[0]["dept_code"].ToString(), user_dtl.Rows[0]["prog_code"].ToString(), user_dtl.Rows[0]["prog_level_code"].ToString(), current_dt.Rows[0]["sem_code"].ToString(), current_dt.Rows[0]["year_code"].ToString());
            Mail mail = new Mail();
            bool mail_status = mail.SendProvisnalCertificateFacultyComman(faculty_admin, mail_from_id_password, AckDetails, user_dtl, Get_Remark, user_type, Loginuserid);

            return false;
        }


