        public DataTable GetTotalFeesDetails(string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @"SELECT 
                    FORMAT(applicationpaymenttransaction.created_date, 'dd-MM-yyyy') AS CreatedDate,
                    (CASE 
                        WHEN semester_type = 'S' THEN 'Spring' 
                        WHEN semester_type = 'M' THEN 'Monsoon' 
                    END) + ' ' + year_semester + ' Installment ' + cash_collected_by AS Description,
                    ('Ref No :- ' + payment_transaction_reference_id + ' , ' + ' Bank Name:- ' + Citrus_TxGateway + ' , ' + 'Paymentmode:- ' + Citrus_PaymentMode ) AS REFERENCE,
                    amount AS Credit,(CASE 
        WHEN semester_type = 'S' THEN 'Spring' 
        WHEN semester_type = 'M' THEN 'Monsoon' 
    END) + ' ' + year_semester as semester,semester_type,year_semester,cash_collected_by,um.full_name,dm.dept_name
                FROM applicationpaymenttransaction 
                inner join user_mst um on um.user_id = applicationpaymenttransaction.user_id
				Inner join department_mst dm on dm.dept_code = um.dept_code
                WHERE applicationpaymenttransaction.user_id = '" + user_id + @"' 
                AND payment_response_code = '0'
                
               
                
                
                
                ORDER BY cash_collected_by ASC;";

            return Get_data(SqlSelect);
        }
        public DataTable GetTotalFeesDetailsSWS(string user_id)
        {
            String SqlSelect = "";

            SqlSelect = @"
                
                SELECT 
                    FORMAT(ws_applicationpaymenttransaction.created_date, 'dd-MM-yyyy') AS CreatedDate,
                    (CASE 
                        WHEN semester_type = 'S' THEN 'Summer' 
                        WHEN semester_type = 'W' THEN 'Winter' 
