                    amount AS Credit,(CASE 
        WHEN semester_type = 'S' THEN 'Spring' 
        WHEN semester_type = 'W' THEN 'Monsoon' 
    END) + ' ' + year_semester as semester,Case When 
	semester_type = 'W' Then 'M' Else 'S' End  as semester_type,year_semester,cash_collected_by ='5',um.full_name,dm.dept_name
                FROM ws_applicationpaymenttransaction 
            inner join user_mst um on um.user_id = ws_applicationpaymenttransaction.user_id
				Inner join department_mst dm on dm.dept_code = um.dept_code
                WHERE ws_applicationpaymenttransaction.user_id = '" + user_id + @"' 
                AND payment_response_code = '0'
                
                Union ALl
SELECT 
                    FORMAT(ws_RefundDetails.created_date, 'dd-MM-yyyy') AS CreatedDate,
                    (CASE 
                        WHEN semester_type = 'S' THEN 'Summer' 
                        WHEN semester_type = 'W' THEN 'Winter' 
