        public DataTable GetStudentDetailsIciciBank(string student_id)
        {
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            SqlSelect = @" SELECT
                                um.user_name,
                                    um.user_id,
                                    dm.dept_name,
                                	pm.prog_name,
                                    CASE 
                                        WHEN applicant_mobile_no IS NOT NULL AND applicant_mobile_no <> '' AND LEN(applicant_mobile_no) = 10 THEN applicant_mobile_no
                                        WHEN guardian_mobile_no IS NOT NULL AND guardian_mobile_no <> '' AND LEN(guardian_mobile_no) = 10 THEN guardian_mobile_no
                                        ELSE '7968310000'
                                    END AS mobilenumber,
                                    um.mail,
                                    CASE
                                        WHEN guardian_mobile_no IS NOT NULL AND guardian_mobile_no <> '' AND LEN(guardian_mobile_no) = 10 THEN guardian_mobile_no
                                        ELSE '7968310000'
                                    END AS guardianmobileno
                                FROM user_mst um
                                INNER JOIN user_contact_dtl ucd ON ucd.user_id = um.user_id
                                INNER JOIN department_mst dm ON dm.dept_code = um.dept_code
                                INNER JOIN programme_mst pm ON pm.prog_code = um.prog_code
                                WHERE um.user_id = '" + student_id + @"';";


            return Get_data(SqlSelect);
        }
        public Boolean InsertRateBandDataExcel(DataTable dt_data, string user_id, string SemesterCode, string YearCode, string host_name)
        {
            /*************************/
            /* ESTABLISH CONNECTION */
            DBConnection.Close();
            DBConnection.Open();
            DBCommand.Transaction = DBConnection.BeginTransaction();
            /*************************/

            String SqlSelect = "";

            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                SqlSelect = "";

                if (dt_data.Rows.Count > 0)
                {

                    for (int i = 0; i < dt_data.Rows.Count; i++)
                    {
                        SqlSelect +=
                                       "IF NOT EXISTS (" +
                                       "   SELECT * FROM semester_wise_applicant_rateband_approve " +
                                       "   WHERE instructor_code = '" + dt_data.Rows[i]["instructor_code"].ToString().Trim() + "' " +
                                       "   AND cancel_flag = 'N' " +
                                       "   AND semester_type = '" + SemesterCode.ToString().Trim() + "' " +
                                       "   AND year_semester = '" + YearCode.ToString().Trim() + "'" +
                                       ") " +
                                       "BEGIN " +
                                       "   INSERT INTO semester_wise_applicant_rateband_approve (" +
                                       "       instructor_code, rate_band, designation, designation_letter, TotalExperience, " +
                                       "       highest_qualification, ApproveRateBand, semester_type, year_semester, DegreeID, " +
                                       "       cancel_flag, created_by, created_host, created_date" +
                                       "   ) VALUES (" +
                                       "       '" + dt_data.Rows[i]["instructor_code"].ToString().Trim() + "', " +
                                       "       '" + dt_data.Rows[i]["rate_band"].ToString() + "', " +
                                       "       '" + dt_data.Rows[i]["designation"].ToString() + "', " +
                                       "       '" + dt_data.Rows[i]["designation_letter"].ToString() + "', " +
                                       "       '" + dt_data.Rows[i]["TotalExperience"].ToString() + "', " +
                                       "       '" + dt_data.Rows[i]["highest_qualification"].ToString() + "', " +
                                       "       '" + dt_data.Rows[i]["ApproveRateBand"].ToString() + "', " +
                                       "       '" + SemesterCode + "', " +
                                       "       '" + YearCode + "', " +
                                       "       '" + dt_data.Rows[i]["DegreeID"].ToString() + "', " +
                                       "       'N', '" + user_id + "', '" + host_name + "', " +
                                       "       '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "'" +
                                       "   ); " +
                                       "END;";

                    }

                }

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;
                DBCommand.ExecuteNonQuery();
                DBCommand.Transaction.Commit();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                DBConnection.Close();
                return false;
            }
        }


        public DataTable GetRateBandDataExistOrNot(string user_id, string sem_code, string year_code, string studio_code)
        {
            String SqlSelect = "";
            SqlSelect = @" WITH RankedData AS (
            SELECT 
        (TotalExperience + month) AS TotalMonth,SWARA.instructor_code, SWARA.created_date,SWARA.TotalExperience,SWARA.semester_type,SWARA.year_semester,
		SWARA.designation as OLDdesignation,SWARA.highest_qualification as OLDhighest_qualification,SWARA.rate_band as OLDRateBand,SWARA.designation_letter as OLDdesignation_letter,
		
        ROW_NUMBER() OVER (PARTITION BY SWARA.instructor_code ORDER BY SWARA.created_date DESC) AS RowNum
        FROM semester_wise_applicant_rateband_approve SWARA
        INNER JOIN RateBandExpAdd RBE 
        ON RBE.semester_type = SWARA.semester_type
        AND RBE.year_semester = SWARA.year_semester
        AND RBE.cancel_flag = SWARA.cancel_flag
        WHERE SWARA.instructor_code IN (
        SELECT studio_wise_instructor_dtl.instructor_code
        FROM studio_wise_instructor_dtl 
        INNER JOIN instructor_mst im 
            ON im.instructor_code = studio_wise_instructor_dtl.instructor_code
        WHERE studio_wise_instructor_dtl.studio_code = '" + studio_code + @"' 
          AND im.designation = 'VF'
        )
        AND SWARA.cancel_flag = 'N'
        AND SWARA.ApproveRateBand = 'A'
        )
        SELECT *
        FROM RankedData
        LEFT JOIN 
        rate_band_range ON rate_band_range.degree = RankedData.OLDhighest_qualification
		AND CAST(rate_band_range.from_experiance AS INT) <= RankedData.TotalMonth 
        AND CAST(rate_band_range.to_experiance AS INT) >= RankedData.TotalMonth
        AND rate_band_range.designation = 'VF'
        AND rate_band_range.semester_type = '" + sem_code + @"' 
        AND rate_band_range.year_semester = '" + year_code + @"'
        AND rate_band_range.typology_sub_group = 'SG003'
        WHERE RowNum = 1 and RankedData.instructor_code Not in(Select instructor_code 
        From semester_wise_applicant_rateband_approve where semester_type='" + sem_code + @"' and year_semester='" + year_code + @"' 
        And cancel_flag='N' )
        ORDER BY RankedData.created_date DESC ";

            return Get_data(SqlSelect);
        }


        public bool CalculateRateBandMonthWise(string user_id, string sem_code, string year_code, string studio_code)
        {
            String SqlSelect = "";

            DataTable dt_get_rateband_Data = GetRateBandDataExistOrNot(user_id, sem_code, year_code, studio_code);
            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            DBCommand.Transaction = DBConnection.BeginTransaction();
            try
            {
                if (dt_get_rateband_Data != null)
                {
                    for (int i = 0; i < dt_get_rateband_Data.Rows.Count; i++)
                    {
                        SqlSelect += @" INSERT INTO semester_wise_applicant_rateband_approve (instructor_code,rate_band,designation,semester_type,year_semester,cancel_flag,TotalExperience,highest_qualification,designation_letter,created_by,created_date,created_host,ApproveRateBand)"
                          + " VALUES('" + dt_get_rateband_Data.Rows[i]["instructor_code"] + @"','" + dt_get_rateband_Data.Rows[i]["rate_band"] + @"','" + dt_get_rateband_Data.Rows[i]["OLDdesignation"] + @"', "
                          + " '" + sem_code + @"','" + year_code + @"','N', '" + dt_get_rateband_Data.Rows[i]["TotalMonth"] + @"','" + dt_get_rateband_Data.Rows[i]["OLDhighest_qualification"] + @"','" + dt_get_rateband_Data.Rows[i]["OLDdesignation_letter"] + @"','" + user_id + @"','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"','" + HttpContext.Current.Request.UserHostName + @"','A'"
                          + " ) ";
                    }

                    DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                    int res_insert = DBCommand.ExecuteNonQuery();

                    if (res_insert > 0)
                    {
                        DBCommand.Transaction.Commit();
                        DBConnection.Close();
                        return true;

                    }
                    else
                    {
                        DBCommand.Transaction.Rollback();
                        if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                        return false;
                    }

                }
                else
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;

            }

            return false;
        }

        public DataTable CheckAadharCardPanCardExist(string user_id, string pan_card_no, string aadhaar_no, string passport_no)
        {
            if (pan_card_no == "")
            {
                pan_card_no = "############";
            }
            if (aadhaar_no == "")
            {
                aadhaar_no = "############";
            }
            if (passport_no == "")
            {
                passport_no = "############";
            }
            String SqlSelect = "";
            // SqlSelect = @" 
            // SELECT aadhaar_no, pan_card_no, instructor_code,
            // CASE 
            //  WHEN aadhaar_no != Case When '" + aadhaar_no + @"' = '' Then '##' Else '"+ aadhaar_no + @"' End  THEN 'Aadhar No Not exists'
            //  WHEN pan_card_no != Case When '" + pan_card_no + @"' = '' Then '##' Else '"+ pan_card_no + @"' End  THEN 'PAN No Not exists'
            // END AS field_exists
            //  FROM instructor_mst
            //  WHERE instructor_code != '" + user_id + @"'
            //     AND (pan_card_no = Case When '" + pan_card_no + @"' = '' Then '##' Else '"+ pan_card_no + @"' End OR aadhaar_no = Case When '" + aadhaar_no + @"' = '' Then '##' Else '"+ aadhaar_no + @"' End); ";

            SqlSelect = @" SELECT aadhaar_no,passport_no, pan_card_no, instructor_code,
       CASE 
           WHEN COALESCE(aadhaar_no, '') = '" + aadhaar_no + @"' THEN 'Aadhaar No Exists'
