        public Boolean UpdateNEFTRTGSezpay(string trans_id, string ResponseData, string user_id)
        {

            DataTable dt_data = GetTrsWiseData(trans_id);

            string status = "";
            string ezpaytranid = "";
            string amount = "";
            string trandate = "";
            string pgreferenceno = "";
            string sdt = "";
            string BA = "";
            string PF = "";
            string TAX = "";
            string paymentMode = "";


            string[] parameters = ResponseData.Split('&');
            if (parameters.Length > 0)
            {
                status = parameters[0].Split('=')[1];         // "Success"
                ezpaytranid = parameters[1].Split('=')[1];    // "ICL50301220813067"
                amount = parameters[2].Split('=')[1];         // "44650"
                trandate = parameters[3].Split('=')[1];       // "2025-03-01 15:10:22"
                pgreferenceno = parameters[4].Split('=')[1];  // "FCCFARPAT244581P2526185565"
                sdt = parameters[5].Split('=')[1];            // "2025-03-01 18:40:07"
                BA = parameters[6].Split('=')[1];             // "44650"
                PF = parameters[7].Split('=')[1];             // "0"
                TAX = parameters[8].Split('=')[1];            // "0"
                paymentMode = parameters[9].Split('=')[1];
                if (status == "Success")
                {
                    DBConnection.Close();
                    DBConnection.Open();
                }
                else { return false; }


            }
            else
            {
                return false;
            }
            string SqlSelect = "";


            SqlSelect = @"UPDATE applicationpaymenttransaction 
                  SET payment_response_code ='0' ,
                      payment_response_msg='Transaction Successful',payment_transaction_reference_id='" + ezpaytranid + @"',
                      payment_authorization_code='" + ezpaytranid + @"',Citrus_PaymentMode='" + paymentMode + @"',Citrus_TxGateway='ICICI',Citrus_TxRefNo='" + ezpaytranid + @"',Citrus_TxStatus='SUCCESS',
                      status_is_payment_received='Y', payment_return_flag='Y',
                      last_modified_by = '" + user_id + @"', 
                      last_modified_date = GETDATE(), 
                      last_modified_host = '" + HttpContext.Current.Request.UserHostName + @"'
                      WHERE applicationpaymenttransaction.transaction_id  ='" + trans_id + @"'
                      And applicationpaymenttransaction.status_is_payment_received ='N' ";


            SqlSelect += @"UPDATE user_fees_installment_dtl SET ";
            if (dt_data.Rows[0]["cash_collected_by"].ToString() == "1")
            {
                SqlSelect += @" is_installment1_paid ='Y',";
            }
            else if (dt_data.Rows[0]["cash_collected_by"].ToString() == "2")
            {
                SqlSelect += @" is_installment2_paid ='Y',";
            }
            else if (dt_data.Rows[0]["cash_collected_by"].ToString() == "3")
            {
                SqlSelect += @" is_installment3_paid ='Y',";
            }
            else if (dt_data.Rows[0]["cash_collected_by"].ToString() == "4")
            {
                SqlSelect += @" is_installment4_paid ='Y',";
            }
            else if (dt_data.Rows[0]["cash_collected_by"].ToString() == "5")
            {
                SqlSelect += @" is_installment5_paid ='Y',";
            }

            SqlSelect += @"last_modified_by = '" + user_id + @"', 
                      last_midified_date = GETDATE(), 
                      last_modified_host = '" + HttpContext.Current.Request.UserHostName + @"'";

            SqlSelect += @" Where 1=1 and user_id = '" + user_id + @"' and year_semester ='" + dt_data.Rows[0]["year_semester"].ToString() + @"' 
                            And semester_type ='" + dt_data.Rows[0]["semester_type"].ToString() + @"' and cancel_flag ='N'";
            // Clear any existing parameters
            DBDataAdpterObject.SelectCommand.Parameters.Clear();

            // Set the command text
            DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;



            try
            {
                int res = DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception Ex)
            {
                DBConnection.Close();
                // Optionally log the exception here
                return false;
            }

        }

