            String SqlSelect = "";

            //SqlSelect = "update user_mst set agree_affidavit ='Y' , agree_reg_process = 'Y'   , last_modified_by = '" + user_id + "' , last_modified_host = '" + host_name + "' , last_midified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "' where user_id = '" + user_id + "' ";
            
            SqlSelect = @"update instructor_workload_detail set uso_hr_approved = 'Y',total_weeks='" + total_weeks + @"',total_contact_hrs='" + total_contact_hrs + @"',total_hrs='" + total_contact_hrs + @"',total_hrs_in_semester='" + total_hrs_in_semester_dtl + @"',justification='" + justification + @"',additional_hours='" + additional_hours + @"',hours_bifurcation='" + strmsg + @"'
            ,last_modified_by = '" + user_id + @"',last_modified_date = '" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + @"',last_modified_host = '" + HttpContext.Current.Request.UserHostName + @"'";
            if (rateband_new != "false")
            {
                SqlSelect += @",rate_band = '"+ rateband_new + @"'";
            }
            SqlSelect += @" where semester_type = '" + sem_code + @"' and year_semester = '" + year_code + @"' and cancel_flag = 'N' and instructor_code = '" + inst_code + @"' and course_code = '" + course_code + @"'";
