                DBCommand.ExecuteNonQuery();
                DBConnection.Close();
                return true;
            }
            catch (Exception)
            {
                DBConnection.Close();
                return false;
            }
        }

        public DataTable Get_Fees_Calculation_paid_fees(string semester, string year_code)
        {
            String SqlSelect = "";
            SqlSelect = @" Select
                        	(t1.fees_amount - FeesPaid - COALESCE(NULLIF(t1.apprve_scholarship_amount, ''), 0)) Outstanding_fees,
                        t1.* from (
                        
                        SELECT 
                            COALESCE(
                                CASE 
                                    WHEN UFI.is_installment1_paid = 'Y' THEN TRY_CAST(UFI.installment1 AS DECIMAL(18, 2)) ELSE 0 END
                                + CASE 
                                    WHEN UFI.is_installment2_paid = 'Y' THEN TRY_CAST(UFI.installment2 AS DECIMAL(18, 2)) ELSE 0 END
                                + CASE 
                                    WHEN UFI.is_installment3_paid = 'Y' THEN TRY_CAST(UFI.installment3 AS DECIMAL(18, 2)) ELSE 0 END
                                + CASE 
                                    WHEN UFI.is_installment4_paid = 'Y' THEN TRY_CAST(UFI.installment4 AS DECIMAL(18, 2)) ELSE 0 END
                                + CASE 
                                    WHEN UFI.is_installment5_paid = 'Y' THEN TRY_CAST(UFI.installment5 AS DECIMAL(18, 2)) ELSE 0 END, 
                            0) AS FeesPaid,COALESCE(NULLIF(SSD.apprve_scholarship_amount, ''), 0) apprve_scholarship_amount,
                        
                        	
                        	UFI.*
                            
                        FROM user_fees_installment_detail UFI
                        Left join student_scholarship_dtl SSD on SSD.user_id = UFI.user_id
                         and SSD.semester_type = UFI.semester_type and SSD.year_semester= UFI.year_semester
                         and SSD.cancel_flag = UFI.cancel_flag
                        
                        WHERE UFI.cancel_flag = 'N' 
                        AND UFI.semester_type = '" + semester + @"' 
                        AND UFI.year_semester = '" + year_code + @"'
                        
                        ) as t1  ";
            return Get_data(SqlSelect);
        }


        public bool SessionInsert(string user_id, string user_type, string Session_id)
        {
            String SqlSelect = "";
            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            DBCommand.Transaction = DBConnection.BeginTransaction();
            try
            {
                SqlSelect += @" INSERT INTO SessionDtl (User_id,User_type,Session_id,created_by,created_date,created_host) 
                                Values('" + user_id + "','" + user_type + "','" + Session_id + "','" + user_id + "',GetDate(),'" + HttpContext.Current.Request.UserHostName + "')";

                DBDataAdpterObject.SelectCommand.CommandText = SqlSelect;

                int res_insert = DBCommand.ExecuteNonQuery();

                if (res_insert > 0)
                {
                    DBCommand.Transaction.Commit();
                    DBConnection.Close();
                    return true;
                }
                else
                {
                    DBCommand.Transaction.Rollback();
                    if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                    return false;
                }
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                if (DBConnection.State == ConnectionState.Open) DBConnection.Close();
                return false;

            }

            return false;
        }


        public dynamic insert_short_list_mail(string sem_code, string year_code, string detalis)
        {

            string[] details_value = detalis.Split('_');
            DataTable dt_inst = getStudiowiseinst(details_value[1].ToString());

            if (details_value[2].ToString() == "CT")
            {
                DataTable dt_CT_User = SendMailForUserOnlyCTUser(details_value[1].ToString(), sem_code, year_code);
                if (dt_CT_User != null)
                {
                    DataRow[] dr = dt_CT_User.Select("instructor_code = '" + details_value[0].ToString() + "'");
                    if (dr.Length > 0)
                    {
                        bool SendMailForCTUser = Send_Mail_for_Instr_CT(details_value[1].ToString(), dr[0]["instructor_code"].ToString(), "StudioProposalAuthorized_CT", "");

                        if (SendMailForCTUser)
                        {
                            return "true";
                        }
                    }


                }
                else return "This studio Not Authorized";

            }

            if (details_value[2].ToString() == "T")
            {
                DataTable dt = SendMailForUser(details_value[1].ToString(), sem_code, year_code);

                if (dt != null)
                {
                    DataRow[] dr = dt.Select("instructor_code = '" + details_value[0].ToString() + "'");
                    bool statusdata = Send_Mail_for_Instr(details_value[1].ToString(), dr[0]["instructor_code"].ToString(), "StudioProposalAuthorized", "");
                    if (statusdata)
                    {
                        return "true";
                    }
                }
            }

            //Developby nitinbhai 08042025




            return "false";

        }


