        public DataTable GetAwpTypeMasterDetails_dtl(string year)
        {
            string SqlSelect = "";
            SqlSelect = @"Select distinct ATWM.work_type_code,work_type_name,astwm.awp_type_code from awp_type_work_master ATWM
	                      inner join awp_sub_type_work_master astwm on astwm.work_type_code = ATWM.work_type_code and astwm.cancel_flag = ATWM.cancel_flag and astwm.year = ATWM.year
	                      where ATWM.cancel_flag ='N' and ATWM.year ='" + year + "'";

            return Get_data(SqlSelect);
        }

        public DataTable GetAwpSubTypeMasterDetails(string year)
        {
            string SqlSelect = "";
            SqlSelect = @"Select * from awp_sub_type_master where cancel_flag='N' and year ='" + year + "'";
            return Get_data(SqlSelect);
        }

        public DataTable GetAWpMainMasterDetails(string year)
        {
            string SqlSelect = "";
            SqlSelect = @" Select * from  awp_main_details_master where cancel_flag='N' and year='" + year + @"'";
            return Get_data(SqlSelect);
        }
        public DataTable GetAWPCpopSuperviserDetails(string year, string inst_code)
        {
            string SqlSelect = "";
            SqlSelect = @" Select CSM.supervisor_name,CSM.designation,CSM.department,CSM.email,CSM.contact 
                           From instructor_mst IM
						   INNER join cpop_superviser_mst CSM on CSM.superviser_code = IM.instructor_code
						   where IM.instructor_code ='" + inst_code + @"' and CSM.publish_flag='Y' and CSM.cancel_flag ='N'";
            return Get_data(SqlSelect);
        }
        public DataTable GetAWPStandardInstitutionalHour(string year)
        {
            string SqlSelect = "";
            SqlSelect = @" Select  FORMAT(
        CASE 
            WHEN divide_value_of_week = 0 THEN 0 
            ELSE total_hours / divide_value_of_week 
        END, 'N2') AS t1_hours,
    FORMAT(
        CASE 
            WHEN divide_value_of_week = 0 THEN 0 
            ELSE total_hours / divide_value_of_week 
        END, 'N2') AS t2_hours, 
                                  '<option value='+awp_hour_code+'> '+dept_code+ '</option>' as BindDropDown, * 
								  From  awp_standard_institutional_hour_master where  cancel_flag='N' and year='" + year + "'";

            return Get_data(SqlSelect);
        }

        public DataTable GetAwpSubTypeMasterDetailsWithawm(string year)
        {
            string SqlSelect = "";

            SqlSelect = @"select awm.awp_type_code,awm.awp_type_name,awp_sub_type_master.* from awp_sub_type_master
							inner join awp_type_master awm on awm.awp_type_code = awp_sub_type_master.awp_type_code and awm.cancel_flag = awp_sub_type_master.cancel_flag
							and awm.year = awp_sub_type_master.year
							where awp_sub_type_master.cancel_flag ='N' and awp_sub_type_master.year ='" + year + "'";
            return Get_data(SqlSelect);
        }

        public DataTable GetAwpSubTypeMasterDetailsMaster(string year)
        {
            string SqlSelect = "";

            SqlSelect = @"SELECT 
                            astw.awp_type_code,
                            astw.sub_order_no,
                            astw.sub_work_code,
                            astw.work_type_code,
                            asihm.awp_hour_code,
                            asihm.dept_code,astw.sub_work_name
                        FROM 
                            awp_type_work_master atwm
                        INNER JOIN 
                            awp_sub_type_work_master astw 
                            ON astw.work_type_code = atwm.work_type_code
                            AND astw.cancel_flag = atwm.cancel_flag 
                            AND astw.year = atwm.year
                        INNER JOIN 
                            awp_standard_institutional_hour_master asihm 
                            ON asihm.sub_work_code = astw.sub_work_code
                            AND asihm.cancel_flag = 'N' 
                            AND asihm.year = '" + year + @"'
                        WHERE 
                            atwm.cancel_flag = 'N' 
                            AND atwm.year = '" + year + @"'";
            return Get_data(SqlSelect);
        }

