        public DataTable GetFacultySaveOtherDetails(string year, string inst_code, string plan_one, string plan_two)
        {
            string SqlSelect = "";
            SqlSelect = @"
            IF EXISTS (
            SELECT 1 
            FROM awp_faculty_institutional_work_hours 
            WHERE cancel_flag = 'N' AND year = '" + year + @"' AND usercode = '" + inst_code + @"' AND awp_plan_code in ('PLA001','PLA002')
            
            UNION
            
            SELECT 1 
            FROM awp_faculty_university_institutional_work_details 
            WHERE cancel_flag = 'N' AND year = '" + year + @"' AND usercode = '" + inst_code + @"' AND awp_plan_code in ('PLA001','PLA002')
            )
            BEGIN 
            SELECT 
            usercode,
            awp_type_code,
            sub_work_code as SubType,
            sr_no,
            description as CourseFullName,
            MAX(CASE WHEN awp_plan_code = 'PLA001' THEN no_of_hours ELSE 0 END) AS Proposed_jun_dec,
            MAX(CASE WHEN awp_plan_code = 'PLA002' THEN no_of_hours ELSE 0 END) AS Proposed_jan_jun,
            (MAX(CASE WHEN awp_plan_code = 'PLA001' THEN no_of_hours ELSE 0 END) + 
             MAX(CASE WHEN awp_plan_code = 'PLA002' THEN no_of_hours ELSE 0 END)) As TotalHours,
            MAX(work_type_code) AS work_type_code,
            MAX(awp_hour_code) AS awp_hour_code
            FROM awp_faculty_institutional_work_hours 
            WHERE cancel_flag='N' AND year='" + year + @"' AND usercode='" + inst_code + @"' AND awp_plan_code in ('PLA001','PLA002')
            GROUP BY 
                usercode,
                awp_type_code,
                sub_work_code,
                sr_no,
                description

            UNION
            
            SELECT 
                usercode,
                awp_type_code,
                sub_work_code as SubType,
                sr_no,
                description as CourseFullName,
                MAX(CASE WHEN awp_plan_code = 'PLA001' THEN no_of_hours ELSE 0 END) AS Proposed_jun_dec,
                MAX(CASE WHEN awp_plan_code = 'PLA002' THEN no_of_hours ELSE 0 END) AS Proposed_jan_jun,
                (MAX(CASE WHEN awp_plan_code = 'PLA001' THEN no_of_hours ELSE 0 END) + 
                 MAX(CASE WHEN awp_plan_code = 'PLA002' THEN no_of_hours ELSE 0 END)) As TotalHours,
                MAX(work_type_code) AS work_type_code,
                MAX(awp_hour_code) AS awp_hour_code
            FROM awp_faculty_university_institutional_work_details 
            WHERE cancel_flag='N' AND year='" + year + @"' AND usercode='" + inst_code + @"' AND awp_plan_code in ('PLA001','PLA002')
            GROUP BY 
                usercode,
                awp_type_code,
                sub_work_code,
                sr_no,
                description
            
            ORDER BY
                usercode, SubType, sr_no
            
            END
            ELSE
            BEGIN

            SELECT 
                usercode,
                awp_type_code,
                sub_work_code as SubType,
                sr_no = 1,
                description as CourseFullName,
                MAX(CASE WHEN awp_plan_code = 'PLA001' THEN no_of_hours * Cast(no_of_week as float) ELSE 0 END) AS Proposed_jun_dec,
                MAX(CASE WHEN awp_plan_code = 'PLA002' THEN no_of_hours * Cast(no_of_week as float) ELSE 0 END) AS Proposed_jan_jun,
                (MAX(CASE WHEN awp_plan_code = 'PLA001' THEN no_of_hours * Cast(no_of_week as float) ELSE 0 END) + 
                 MAX(CASE WHEN awp_plan_code = 'PLA002' THEN no_of_hours * Cast(no_of_week as float) ELSE 0 END)) As TotalHours,
                MAX(work_type_code) AS work_type_code,
                MAX(awp_hour_code) AS awp_hour_code
                FROM awp_pre_assigned_faculty_work 
                WHERE cancel_flag='N' AND year='" + year + @"' AND usercode='" + inst_code + @"' AND status ='N' AND awp_plan_code in ('PLA001','PLA002')
                GROUP BY 
                usercode,
                awp_type_code,
                sub_work_code,
                description;  END ";

            //SqlSelect = SqlSelect.Replace("PLA001", plan_one);
            //SqlSelect = SqlSelect.Replace("PLA002", plan_two);


            SqlSelect = SqlSelect.Replace("PLA001", "@@PLA001");
            SqlSelect = SqlSelect.Replace("PLA002", "@@PLA002");
            SqlSelect = SqlSelect.Replace("@@PLA001", plan_one);
            SqlSelect = SqlSelect.Replace("@@PLA002", plan_two);
            return Get_data(SqlSelect);
        }


