        public DataTable GetAwpPlaneCreditdtl(string year, string parametername, string usercode)
        {
            String[] year_string = year.Split(new Char[] { '-' }, StringSplitOptions.RemoveEmptyEntries);
            string SqlSelect = "";
            string semester = "";
            string year_semester = "";
            if (parametername == "Proposed_Planned")
            {
                semester = "M";
                year_semester = year_string[0];
            }
            else if (parametername == "Actual_June_to_Dec")
            {
                semester = "M";
                year_semester = year_string[0];
            }
            else if (parametername == "Actual_Jan_to_June")
            {
                semester = "S";
                year_semester = year_string[1];
            }


            SqlSelect = " IF EXISTS(Select * from awp_user_hour_type_mst where cancel_flag ='N' and semester ='" + semester + @"' and year_semester ='" + year_semester + "' and usercode ='" + usercode + @"') "
                       + " BEGIN "
                       + @" Select total_hours,plan_one,plan_two,awhtm.year,bench_percentage,bench_hours,awhtm.hour_type from awp_user_hour_type_mst awhtm 
                            inner join awp_total_hours_mst athm on athm.hour_type = awhtm.hour_type
                            and athm.year = awhtm.year
                            where awhtm.semester = '" + semester + @"' and awhtm.year_semester = '" + year_semester + @"' and awhtm.cancel_flag = 'N'
                            and awhtm.usercode = '" + usercode + "'"
                       + " END "
                   + " ELSE "
                       + " BEGIN "
                       + @" Select total_hours,plan_one,plan_two,awhtm.year,bench_percentage,bench_hours,awhtm.hour_type from awp_user_hour_type_mst awhtm 
                            inner join awp_total_hours_mst athm on athm.hour_type = awhtm.hour_type
                            and athm.year = awhtm.year
                            where awhtm.semester = '" + semester + @"' and awhtm.year_semester = '" + year_semester + @"' and awhtm.cancel_flag = 'N'
                            and awhtm.usercode = 'all'"
                       + " END ";


            //SqlSelect = @"Select * from awp_total_hours_mst where cancel_flag ='N' and year='" + year + "'";
            return Get_data(SqlSelect);
        }


        public DataTable GetAwpPlaneCreditdtl_both(string year, string parametername, string usercode)
