            String[] year_string = year.Split(new Char[] { '-' }, StringSplitOptions.RemoveEmptyEntries);
            string SqlSelect = "";
            string semester = "";
            string year_semester = "";

            string semester_2 = "";
            string year_semester_2 = "";
            if (parametername == "Proposed_Planned")
            {
                semester = "M";
                year_semester = year_string[0];
                semester_2 = "S";
                year_semester_2 = year_string[1];
            }
            else if (parametername == "Actual_June_to_Dec")
            {
                semester = "M";
                year_semester = year_string[0];
                semester_2 = "S";
                year_semester_2 = year_string[1];
            }
            else if (parametername == "Actual_Jan_to_June")
            {
                semester = "M";
                year_semester = year_string[0];
                semester_2 = "S";
                year_semester_2 = year_string[1];
            }

            else if (parametername == "Actual_both")
            {
                semester = "M";
                year_semester = year_string[0];
                semester_2 = "S";
                year_semester_2 = year_string[1];
            }


            SqlSelect = @" SELECT *
                                    FROM (
                                        
                                        SELECT TOP 1 total_hours, plan_one, plan_two, awhtm.year, bench_percentage, bench_hours, awhtm.hour_type 
                                        FROM awp_user_hour_type_mst awhtm
                                        INNER JOIN awp_total_hours_mst athm 
                                            ON athm.hour_type = awhtm.hour_type AND athm.year = awhtm.year
                                        WHERE awhtm.semester = '" + semester + @"' 
                                          AND awhtm.year_semester = '" + year_semester + @"' 
                                          AND awhtm.cancel_flag = 'N' 
                                          AND awhtm.usercode IN ('" + usercode + @"', 'all')
                                        ORDER BY CASE WHEN awhtm.usercode = '" + usercode + @"' THEN 0 ELSE 1 END
                                    ) AS Semester1
                                    
                                    UNION ALL
                                    
                                    SELECT *
                                    FROM (
                                       
                                        SELECT TOP 1 total_hours, plan_one, plan_two, awhtm.year, bench_percentage, bench_hours, awhtm.hour_type 
                                        FROM awp_user_hour_type_mst awhtm
                                        INNER JOIN awp_total_hours_mst athm 
                                            ON athm.hour_type = awhtm.hour_type AND athm.year = awhtm.year
                                        WHERE awhtm.semester = '" + semester_2 + @"' 
                                          AND awhtm.year_semester = '" + year_semester_2 + @"'
                                          AND awhtm.cancel_flag = 'N' 
                                          AND awhtm.usercode IN ('" + usercode + @"', 'all')
                                        ORDER BY CASE WHEN awhtm.usercode = '" + usercode + @"' THEN 0 ELSE 1 END
                                    ) AS Semester2";
            //SqlSelect = @"Select * from awp_total_hours_mst where cancel_flag ='N' and year='" + year + "'";
            return Get_data(SqlSelect);
        }


