	                       From awp_faculty_total_planned_allocated_hours as AFT
	                       
                           inner join awp_type_master on awp_type_master.awp_type_code = AFT.awp_type_code
	                       and awp_type_master.year = AFT.year and awp_type_master.cancel_flag = AFT.cancel_flag
						   
