	                       AFT.usercode,AFT.awp_type_code,
	                       AFT.description,awp_sub_type_master.awp_sub_type_code 
                            


                           UNION 
                           

                           Select awp_type_master.awp_type_name,awp_sub_type_master.awp_sub_type_name,
	                       AFT.usercode,AFT.awp_type_code,
	                       AFT.description,awp_sub_type_master.awp_sub_type_code,work_type_code=NULL,
	                       MAX(CASE WHEN AFT.awp_plan_code = 'PLA001' THEN AFT.no_of_hours ELSE 0 END) AS Proposed_jun_dec,
                           MAX(CASE WHEN AFT.awp_plan_code = 'PLA002' THEN AFT.no_of_hours ELSE 0 END) AS Proposed_jan_jun,
