	From awp_faculty_institutional_work_hours as AFT
	
    inner join awp_type_master on awp_type_master.awp_type_code = AFT.awp_type_code
	and awp_type_master.year = AFT.year and awp_type_master.cancel_flag = AFT.cancel_flag

	inner join awp_sub_type_work_master on awp_sub_type_work_master.sub_work_code = AFT.sub_work_code
	and awp_sub_type_work_master.cancel_flag ='N' and awp_sub_type_work_master.year = AFT.year
	


    where AFT.cancel_flag ='N' and AFT.usercode='" + inst_code + @"' and AFT.year ='" + year + @"'
	GROUP BY 
    awp_type_master.awp_type_name,awp_sub_type_work_master.sub_work_name,
