	                       AFT.usercode,AFT.awp_type_code,
	                       AFT.description,awp_sub_type_master.awp_sub_type_code,work_type_code=NULL,
	                       

                           
                           MAX(CASE WHEN AFT.awp_plan_code = 'PLA001' THEN AFT.no_of_hours ELSE 0 END) AS Proposed_plan1,
                           MAX(CASE WHEN AFT.awp_plan_code = 'PLA002' THEN AFT.no_of_hours ELSE 0 END) AS Proposed_plan2,
                           MAX(CASE WHEN AFT.awp_plan_code = 'ACT001' THEN AFT.no_of_hours ELSE 0 END) AS Actual_plan1,
                           MAX(CASE WHEN AFT.awp_plan_code = 'ACT002' THEN AFT.no_of_hours ELSE 0 END) AS Actual_plan2,
                           
                            (MAX(CASE WHEN AFT.awp_plan_code = 'PLA001' THEN AFT.no_of_hours ELSE 0 END) + 
                            MAX(CASE WHEN AFT.awp_plan_code = 'PLA002' THEN AFT.no_of_hours ELSE 0 END)) As TotalHours
	                       From awp_faculty_unallocated_hours as AFT
	                       
                           inner join awp_type_master on awp_type_master.awp_type_code = AFT.awp_type_code
						   and awp_type_master.year = AFT.year and awp_type_master.cancel_flag = AFT.cancel_flag

						   inner join awp_sub_type_master on awp_sub_type_master.awp_sub_type_code = AFT.awp_sub_type_code
	                       and awp_sub_type_master.cancel_flag ='N' and awp_sub_type_master.year = AFT.year
	                       

                           where AFT.cancel_flag ='N' and AFT.usercode='" + inst_code + @"' and AFT.year ='" + year + @"'
	                       GROUP BY 
                           awp_type_master.awp_type_name,awp_sub_type_master.awp_sub_type_name,
	                       AFT.usercode,AFT.awp_type_code,
	                       AFT.description,awp_sub_type_master.awp_sub_type_code ";



            //SqlSelect = SqlSelect.Replace("PLA001", "@@PLA001");
            //SqlSelect = SqlSelect.Replace("PLA002", "@@PLA002");
            //SqlSelect = SqlSelect.Replace("@@PLA001", "PLA001");
            //SqlSelect = SqlSelect.Replace("@@PLA002", "PLA002");

            return Get_data(SqlSelect);
        }

        public DataTable AWPGetSubmittedData(string year, string plan_type, string user_type, string user_id)
        {

            string SqlSelect = "";
            if (user_type == "I2")
            {
                SqlSelect = @" SELECT *
                                FROM (
                                    SELECT 
                                        COALESCE(NULLIF(csm.superviser_code, ''), afam.usercode) AS superviser_code,
                                        (CASE WHEN afam.faculty_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS faculty_status,
                                        (CASE WHEN afam.dean_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS dean_status,
                                        (CASE WHEN afam.hr_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS hr_status,
                                        csm.supervisor_name,
                                        csm.department,csm.designation,csm.email,
                                        MAX(CASE WHEN afam.awp_plan_code = 'PLA001' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jun_dec_faculty_status_PLA001,
                                        MAX(CASE WHEN afam.awp_plan_code = 'PLA002' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jan_jun_faculty_status_PLA002,
										MAX(CASE WHEN afam.awp_plan_code = 'ACT001' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jun_dec_faculty_status_ACT001,
                                        MAX(CASE WHEN afam.awp_plan_code = 'ACT002' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jan_jun_faculty_status_ACT002
                                    FROM cpop_superviser_mst csm
                                    LEFT JOIN awp_faculty_application_master afam
                                        ON afam.usercode = csm.superviser_code
                                        AND afam.cancel_flag = 'N'
                                        AND afam.faculty_status ='Y'
                                        AND afam.year = '" + year + @"'
                                        where csm.cancel_flag ='N' and csm.publish_flag ='Y' and csm.superviser_code = '" + user_id + @"'
                                    GROUP BY 
                                        COALESCE(NULLIF(csm.superviser_code, ''), afam.usercode),
                                        afam.faculty_status,
                                        afam.dean_status,
                                        afam.hr_status,
                                        csm.supervisor_name,
                                        csm.department,
                                        csm.designation,
                                        csm.email
                                ) AS result
                                ORDER BY 
                                    CASE faculty_status WHEN 'Submitted' THEN 0 ELSE 1 END,
                                    superviser_code";

            }
            else if (user_type == "HR")
            {
                SqlSelect = @" SELECT *
                                FROM (
                                    SELECT 
                                        COALESCE(NULLIF(csm.superviser_code, ''), afam.usercode) AS superviser_code,
                                        (CASE WHEN afam.faculty_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS faculty_status,
                                        (CASE WHEN afam.dean_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS dean_status,
                                        (CASE WHEN afam.hr_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS hr_status,
                                        csm.supervisor_name,
                                        csm.department,csm.designation,csm.email,
                                        MAX(CASE WHEN afam.awp_plan_code = 'PLA001' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jun_dec_faculty_status_PLA001,
                                        MAX(CASE WHEN afam.awp_plan_code = 'PLA002' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jan_jun_faculty_status_PLA002,
										MAX(CASE WHEN afam.awp_plan_code = 'ACT001' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jun_dec_faculty_status_ACT001,
                                        MAX(CASE WHEN afam.awp_plan_code = 'ACT002' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jan_jun_faculty_status_ACT002
                                    FROM cpop_superviser_mst csm
                                    LEFT JOIN awp_faculty_application_master afam
                                        ON afam.usercode = csm.superviser_code
                                        AND afam.cancel_flag = 'N'
                                        AND afam.faculty_status ='Y'
                                        AND afam.year = '" + year + @"'
                                        where csm.cancel_flag ='N' and csm.publish_flag ='Y' 
                                    GROUP BY 
                                        COALESCE(NULLIF(csm.superviser_code, ''), afam.usercode),
                                        afam.faculty_status,
                                        afam.dean_status,
                                        afam.hr_status,
                                        csm.supervisor_name,
                                        csm.department,
                                        csm.designation,
                                        csm.email
                                ) AS result
                                ORDER BY 
                                    CASE faculty_status WHEN 'Submitted' THEN 0 ELSE 1 END,
                                    superviser_code";
            }
            else if (user_type == "D")
            {
                SqlSelect = @" SELECT *
                                FROM (
                                    SELECT 
                                        COALESCE(NULLIF(csm.superviser_code, ''), afam.usercode) AS superviser_code,
                                        (CASE WHEN afam.faculty_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS faculty_status,
                                        (CASE WHEN afam.dean_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS dean_status,
                                        (CASE WHEN afam.hr_status = 'Y' THEN 'Submitted' ELSE 'Pending' END) AS hr_status,
                                        csm.supervisor_name,
                                        csm.department,csm.designation,csm.email,
                                        MAX(CASE WHEN afam.awp_plan_code = 'PLA001' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jun_dec_faculty_status_PLA001,
                                        MAX(CASE WHEN afam.awp_plan_code = 'PLA002' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jan_jun_faculty_status_PLA002,
										MAX(CASE WHEN afam.awp_plan_code = 'ACT001' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jun_dec_faculty_status_ACT001,
                                        MAX(CASE WHEN afam.awp_plan_code = 'ACT002' THEN afam.faculty_status ELSE 'N' END) AS Proposed_jan_jun_faculty_status_ACT002
                                    FROM cpop_superviser_mst csm
                                    LEFT JOIN awp_faculty_application_master afam
                                        ON afam.usercode = csm.superviser_code
                                        AND afam.cancel_flag = 'N'
                                        AND afam.faculty_status ='Y'
                                        AND afam.year = '" + year + @"'
                                        where csm.cancel_flag ='N' and csm.publish_flag ='Y' 
                                        AND csm.department IN (Select dm.dept_name from dean_dtl 
                                        inner join department_mst dm on dm.dept_code = dean_dtl.dept_code and dm.cancel_flag = dean_dtl.cancel_flag
                                        where dean_dtl.cancel_flag ='N' and dean_dtl.instructor_code = '" + user_id + @"' )
                                    GROUP BY 
                                        COALESCE(NULLIF(csm.superviser_code, ''), afam.usercode),
                                        afam.faculty_status,
                                        afam.dean_status,
                                        afam.hr_status,
                                        csm.supervisor_name,
                                        csm.department,
                                        csm.designation,
                                        csm.email
                                ) AS result
                                ORDER BY 
                                    CASE faculty_status WHEN 'Submitted' THEN 0 ELSE 1 END,
                                    superviser_code";
            }

            return Get_data(SqlSelect);
        }



