        public bool GetUpdateEmailtemplateContantData(string ToMailId, string FromMailID, string FromPassword, string subject, string body, string ccMailid, string attachment_url)
        {
            string sql = @"INSERT INTO SendMailDetails 
                   (ToMailId, FromMailId, FromPassword, CCMailId, Subject, body, attachment_url, cancel_flag) 
                   VALUES 
                   (@ToMailId, @FromMailId, @FromPassword, @CCMailId, @Subject, @Body, @AttachmentUrl, 'N')";

            string connection = ConfigurationManager.ConnectionStrings["CEPT_Admission"].ToString();

            using (SqlConnection con = new SqlConnection(connection))
            using (SqlCommand cmd = new SqlCommand(sql, con))
            {
                cmd.Parameters.AddWithValue("@ToMailId", ToMailId);
                cmd.Parameters.AddWithValue("@FromMailId", FromMailID);
                cmd.Parameters.AddWithValue("@FromPassword", FromPassword);
                cmd.Parameters.AddWithValue("@CCMailId", ccMailid);
                cmd.Parameters.AddWithValue("@Subject", subject);
                cmd.Parameters.AddWithValue("@Body", body);
                cmd.Parameters.AddWithValue("@AttachmentUrl", attachment_url);

                cmd.Parameters.AddWithValue("@CreatedDate", DateTime.Now);
                cmd.Parameters.AddWithValue("@CreatedHost", HttpContext.Current.Request.UserHostName);

                if (HttpContext.Current != null && HttpContext.Current.Session != null &&
                    HttpContext.Current.Session["UserId"] != null && !string.IsNullOrWhiteSpace(HttpContext.Current.Session["UserId"].ToString()))
                {
                    cmd.Parameters.AddWithValue("@CreatedBy", HttpContext.Current.Session["UserId"].ToString());
                }
                else
                {
                    cmd.Parameters.AddWithValue("@CreatedBy", "AutoUser");
                }

                try
                {
                    con.Open();
                    int rowsAffected = cmd.ExecuteNonQuery();
                    return rowsAffected > 0; // Return true if insert succeeded
                }
                catch (Exception ex)
                {
                    return false;
                }
            }
        }


        public DataTable GetRateBandDetailsNew(string semester, string year_code, string commaSeparated)
        {
            String SqlSelect = "";
            SqlSelect = @" WITH LastThreeSemesters AS (
                    	SELECT semester_type, year_semester, month AS months_ago
                        FROM RateBandExpAdd 
                        WHERE doc_no IN ('1', '2', '3') AND cancel_flag = 'N'
                    ),
                    BaseInstructors AS (
                        SELECT DISTINCT iwd.instructor_code, im.designation,((ISNULL(total_experiance,0)*12) + ISNULL(total_experiance_months,0)) as TotalExperiance,im.highest_qualification,im.instructor_name
                        FROM instructor_workload_detail iwd 
                        INNER JOIN instructor_mst im ON im.instructor_code = iwd.instructor_code
                        WHERE iwd.semester_type = '" + semester + @"' AND iwd.year_semester = '" + year_code + @"' 
                          AND iwd.cancel_flag = 'N' AND im.designation = 'VF'
                          AND iwd.instructor_code NOT IN (
                              SELECT instructor_code 
                              FROM semester_wise_applicant_rateband_approve 
                              WHERE semester_type = '" + semester + @"' AND year_semester = '" + year_code + @"'
                                AND cancel_flag = 'N' AND designation = 'VF'
                          )
                    ),
                    InstructorPrevSemesterData AS (
                        SELECT swp.instructor_code, 
                               swp.semester_type, 
                               swp.year_semester,
                               lts.months_ago,
                               ROW_NUMBER() OVER (PARTITION BY swp.instructor_code ORDER BY lts.months_ago) AS rn
                        FROM semester_wise_applicant_rateband_approve swp
                        INNER JOIN LastThreeSemesters lts 
                            ON swp.semester_type = lts.semester_type 
                           AND swp.year_semester = lts.year_semester
                        WHERE swp.cancel_flag = 'N' AND swp.designation = 'VF'
                    )
                    select t1.*,rate_band from (
                    SELECT 
                        bi.instructor_code,
                        bi.designation,
                        ip.semester_type + ' ' + ip.year_semester AS last_active_semester,
                        (ISNULL(ip.months_ago,0)) months_ago,bi.TotalExperiance,
                    	(ISNULL(ip.months_ago,0)) + (ISNULL(bi.TotalExperiance,0)) as CurrentExperiance,
                    	bi.highest_qualification,bi.instructor_name
                    FROM BaseInstructors bi
                    LEFT JOIN InstructorPrevSemesterData ip 
                        ON bi.instructor_code = ip.instructor_code AND ip.rn = 1) t1
                    
                    	LEFT JOIN 
                            rate_band_range ON rate_band_range.degree = t1.highest_qualification
                    		AND CAST(rate_band_range.from_experiance AS INT) <= t1.CurrentExperiance
                            AND CAST(rate_band_range.to_experiance AS INT) >= t1.CurrentExperiance
                            AND rate_band_range.designation = 'VF'
                            AND rate_band_range.semester_type = '" + semester + @"'
                            AND rate_band_range.year_semester = '" + year_code + @"'
                            AND rate_band_range.typology_sub_group = 'SG003'  ";

            if (commaSeparated != "")
            {
                SqlSelect += " Where t1.instructor_code in (" + commaSeparated + @")";
            }
            return Get_data(SqlSelect);
        }

