        public DataTable GetSWSCourseDtl(string admission_year, string year_semester)
        {
            String SqlSelect = "";
            SqlSelect = @" WITH SWS_CTE AS (
    SELECT *,
        CAST(SUBSTRING(EnrollmentYear, 2, 4) AS INT) AS enroll_year_int,
        CASE WHEN semester_type = 'S' THEN CAST(year_semester AS INT) - 1
             ELSE CAST(year_semester AS INT)
        END AS academic_start,
        CASE WHEN semester_type IN ('M','W') THEN 1 ELSE 2 END AS sem_offset,
        CASE
            WHEN ((CASE WHEN semester_type = 'S' THEN CAST(year_semester AS INT) - 1 ELSE CAST(year_semester AS INT) END) 
                  - CAST(SUBSTRING(EnrollmentYear, 2, 4) AS INT)) * 2 
                 + (CASE WHEN semester_type IN ('M','W') THEN 1 ELSE 2 END) < 1
            THEN NULL
            ELSE ((CASE WHEN semester_type = 'S' THEN CAST(year_semester AS INT) - 1 ELSE CAST(year_semester AS INT) END) 
                  - CAST(SUBSTRING(EnrollmentYear, 2, 4) AS INT)) * 2 
                 + (CASE WHEN semester_type IN ('M','W') THEN 1 ELSE 2 END)
        END AS semester_code
    FROM WS_StudentWiseSaveGradePoint
    WHERE cancel_flag = 'N'
)
SELECT
    sws.year_semester AS year,
    NULL AS MONTH,
    sws.semester_code AS SEM,
    NULL AS EXAM_TYPE,
    CASE
        WHEN sws.semester_type = 'S' THEN 'Summer'
        WHEN sws.semester_type = 'W' THEN 'Winter'
        ELSE 'N/A'
    END AS TERM_TYPE,
    NULL AS TOT_CREDIT,
    NULL AS TOT_CREDIT_POINTS,
    NULL AS CGPA,
    NULL AS SGPA,
    wcm.course_code AS SUB1,
    wcm.course_name AS SUB1NM,
    'G' AS SUB1_REMARKS,
    wcm.course_type AS SUB1_TYPE,
    wcm.course_credits AS SUB1_CREDIT,
    sws.Grade AS SUB1_GRADE,
    sws.GradePoint AS SUB1_GRADE_POINTS,
    (ISNULL(TRY_CAST(wcm.course_credits AS DECIMAL(10,2)),0)
     * ISNULL(TRY_CAST(sws.GradePoint AS DECIMAL(10,2)),0)) AS SUB1_CREDIT_POINTS,
    CASE WHEN sws.FaillPassStatus = 'FAIL' THEN 'FAIL' ELSE 'PASS' END AS SUB1_STATUS,
    sws.studentid AS user_id,
    'sws' AS SOURCE_TYPE
        FROM SWS_CTE sws
        INNER JOIN ws_course_mst wcm
    ON wcm.course_code = sws.Course_Code
    AND wcm.semester_type = sws.semester_type
    AND wcm.year_semester = sws.year_semester
    WHERE wcm.is_cancel = 'N' and sws.EnrollmentYear = '" + admission_year + "' ";


            if (year_semester != "")
            {
                SqlSelect += " and year_semester ='" + year_semester + "'";
            }

            return Get_data(SqlSelect);
        }
        public DataTable GetNADCourseReportDtl(string programcode, string admissionyear, string dept_code, string semestertype, string yearsemester)
        {
            String SqlSelect = "";
            SqlSelect = @"  Select student_exam_marks_dtl.year_semester as year,MONTH =NULL, 
                    SEM = ((CAST(student_exam_marks_dtl.year_semester AS INT) 
                            - CAST(SUBSTRING(student_exam_marks_dtl.year_code, 2, 4) AS INT)) * 2)
                          + CASE 
                                WHEN student_exam_marks_dtl.semester_type = 'S' THEN 0 
                                ELSE 1 
                            END,EXAM_TYPE = NULL,
							Case When student_exam_marks_dtl.semester_type = 'S' Then 'Spring' Else 'Monsoon' End as TERM_TYPE,
							TOT_CREDIT = NULL,TOT_CREDIT_POINTS = NULL,swsgpa.Total_cgpa_four_digit as CGPA,
							swsgpa.semester_wise_cgpa_four_digit as SGPA,
							cm.course_code as SUB1,cm.course_name as SUB1NM,cm.gpa_ngpa as SUB1_REMARKS,
                            dwc.course_type as SUB1_TYPE,
                            student_exam_marks_dtl.credits as SUB1_CREDIT,
                            semd.final_grade as SUB1_GRADE ,
							semd.final_grade_point as SUB1_GRADE_POINTS ,
							(ISNULL(TRY_CAST(student_exam_marks_dtl.credits AS DECIMAL(10,2)),0) * ISNULL(TRY_CAST(semd.final_grade_point AS DECIMAL(10,2)),0)) AS SUB1_CREDIT_POINTS,
                           CASE When semd.final_grade = 'F' then 'FAIL' Else 'PASS' END SUB1_STATUS ,
							student_exam_marks_dtl.user_id  from student_course_allocate_dtl as student_exam_marks_dtl
							inner join course_mst cm on cm.course_code = student_exam_marks_dtl.course_code
							and cm.semester_type = student_exam_marks_dtl.semester_type and cm.year_semester = student_exam_marks_dtl.year_semester
							inner join department_wise_course_dtl dwc on dwc.course_code = student_exam_marks_dtl.course_code
							and dwc.semester_type = student_exam_marks_dtl.semester_type and dwc.year_semester = student_exam_marks_dtl.year_semester
							left join StudentWiseSaveSGPACGPA swsgpa on swsgpa.studentid = student_exam_marks_dtl.user_id 
							and swsgpa.semester = student_exam_marks_dtl.semester_type and swsgpa.year_semester = student_exam_marks_dtl.year_semester
							and swsgpa.cancel_flag ='N'
							inner join user_mst um on um.user_id = student_exam_marks_dtl.user_id
                            LEFT JOIN student_exam_marks_dtl semd on semd.course_code =student_exam_marks_dtl.course_code
							and semd.semester_type = student_exam_marks_dtl.semester_type 
							and semd.year_semester = student_exam_marks_dtl.year_semester
							and semd.cancel_flag = student_exam_marks_dtl.cancel_flag
							and semd.student_code = student_exam_marks_dtl.user_id
							where  student_exam_marks_dtl.cancel_flag ='N' and dwc.cancel_flag ='N'  ";

            if (programcode != "")
            {
                SqlSelect += " and dwc.prog_code='" + programcode + "'";
            }

            if (dept_code != "")
            {
                SqlSelect += " and um.dept_code ='" + dept_code + "'";
            }
            if (admissionyear != "")
            {
                SqlSelect += " and student_exam_marks_dtl.year_code ='" + admissionyear + "'";
            }

            if (semestertype != "")
            {
                SqlSelect += " and student_exam_marks_dtl.semester_type ='" + semestertype + "'";
            }

            if (yearsemester != "")
            {
                SqlSelect += " and student_exam_marks_dtl.year_semester ='" + yearsemester + "'";
            }

            SqlSelect += " order by student_exam_marks_dtl.user_id,dwc.semester_code asc ";
            return Get_data(SqlSelect);
        }


