        public bool insert_published_allocation_new(string semester, string year_code, string user_id, string host_name, string commaSeparated)
        {
            DataTable dt = GetRateBandDetailsNew(semester, year_code, commaSeparated);
            try
            {
                DBConnection.Open();
                DBCommand.Transaction = DBConnection.BeginTransaction();

                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    string instructor_code = dt.Rows[i]["instructor_code"].ToString().Replace("'", "''");
                    string rate_band = dt.Rows[i]["rate_band"].ToString().Replace("'", "''");
                    string designation = dt.Rows[i]["designation"].ToString().Replace("'", "''");
                    string experience = dt.Rows[i]["CurrentExperiance"].ToString().Replace("'", "''");
                    string qualification = dt.Rows[i]["highest_qualification"].ToString().Replace("'", "''");
                    string semester_type = semester.ToString().Replace("'", "''");
                    string year_semester = year_code.ToString().Replace("'", "''");
                    string created_date = DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss");

                    string SqlInsert = "INSERT INTO semester_wise_applicant_rateband_approve " +
                        "(instructor_code, rate_band, designation, TotalExperience, highest_qualification, ApproveRateBand, semester_type, year_semester, cancel_flag, created_by, created_host, created_date) VALUES (" +
                        $"'{instructor_code}', '{rate_band}', '{designation}', '{experience}', '{qualification}', 'A', '{semester_type}', '{year_semester}', 'N', '{user_id.Replace("'", "''")}', '{host_name.Replace("'", "''")}', '{created_date}')";

                    DBCommand.Connection = DBConnection;
                    DBCommand.CommandText = SqlInsert;
                    DBCommand.ExecuteNonQuery();
                }

                DBCommand.Transaction.Commit();
                DBConnection.Close();
                return true;
            }
            catch (Exception ex)
            {
                DBCommand.Transaction.Rollback();
                DBConnection.Close();
                return false;
            }
        }


        public DataTable GetSWSCourseBudgetDtl(string course_code, string semester_type, string year_semester)
        {
            String SqlSelect = "";
            SqlSelect = @" SELECT 
                            course_name,
                            CASE 
                                WHEN ws_course_proposal.course_type = 'E' THEN 'Elective' 
                                ELSE 'Mandatory' 
                            END AS course_type,
                            dm.dept_name,
                            ws_course_proposal.course_credits,
                            category_location_wise,
                            available_seat,
                            (wfa.fees_amount) AS Student_Fees_per_Credit,
                            image_name,image_source,course_code,inhabitation,wfa.year_semester,ws_course_proposal.total_instructors_involved,
                            --wcbc.min,wcbc.max

(SELECT min_value.min 
FROM (
    SELECT * 
    FROM ws_course_budget_credit_tutor_mst 
    WHERE number_of_tutors IN (
        SELECT CASE 
                   WHEN COUNT(course_code) > 1 THEN 2 
                   ELSE 1 
               END 
        FROM ws_course_proposal_instructor 
        WHERE cancel_flag IN ('N','Y') 
          AND course_code = '" + course_code + @"' 
          AND year_semester = '" + year_semester + @"'
          AND semester_type = '" + semester_type + @"'
        GROUP BY course_code
    )
      AND intake_desc = ws_course_proposal.category_location_wise
      AND course_credits = ws_course_proposal.course_credits
) AS min_value) as min,

(select minimum_seat from ws_course_proposal  where course_code ='" + course_code + @"'AND semester_type='" + semester_type + @"' 
AND year_semester ='" + year_semester + @"' and cancel_flag in ('N','Y')) as  max
                        FROM 
                            ws_course_proposal
                        INNER JOIN 
                            department_mst dm 
                            ON dm.dept_code = ws_course_proposal.inhabitation
                        INNER JOIN 
                            ws_course_budget_course_wise_fees_dtl wfa 
                            ON wfa.semester_type = ws_course_proposal.semester_type 
                            AND wfa.year_semester = ws_course_proposal.year_semester 
                            AND wfa.cancel_flag = 'N' And wfa.course_type =ws_course_proposal.course_type and wfa.prog_code ='1'
                        --INNER JOIN ws_course_budget_credit_tutor_mst wcbc on wcbc.number_of_tutors = ws_course_proposal.total_instructors_involved
							--and wcbc.intake_desc = ws_course_proposal.category_location_wise and wcbc.course_credits = ws_course_proposal.course_credits
                        WHERE 
                            ws_course_proposal.course_code = '" + course_code + @"'
                            AND wfa.semester_type = '"+ semester_type + @"'
                            AND wfa.year_semester = '"+ year_semester + @"'
                            AND wfa.year_desc = '" + year_semester + @"'
                            AND wfa.user_type = 'S' ";
            return Get_data(SqlSelect);
        }
