           //                And (wiwd.course_code ='"+ course_code + @"' or wiwd.ws_course_code ='"+ course_code + @"')
           //                And course_code in (select wcp.ws_course_code from ws_course_proposal wcp where (wcp.course_code ='"+ course_code + @"' or wcp.ws_course_code = '"+ course_code + @"') 
           //                and wcp.semester_type ='"+ semester_type + @"' and wcp.year_semester='" + year_semester + @"' and wcp.cancel_flag in('Y','N')) ";


            SqlSelect = @" Select CAST(
                           ISNULL(TRY_CAST(t1.rate_band AS DECIMAL(18,2)), 0) *
                           ISNULL(TRY_CAST(t1.AdditionalHrs AS DECIMAL(18,2)), 0)
                           AS DECIMAL(18,2)
                           ) AS TotalRateband,typedata ='input', t1.* from (
                           Select ws_course_proposal_instructor.instructor_code, contact_hrs as ContactHrs,AdditionalHours as AdditionalHrs,TotalHours as TotalHrs,im.designation,im.instructor_name,
                           (select rate_band from  rate_band_range
                           where ISNULL(degree,'') = im.highest_qualification
                           and CAST(from_experiance as INT) <= CAST(ISNULL((ISNULL(NULLIF(im.total_experiance, ''), 0) * 12) + ISNULL(NULLIF(im.total_experiance_months, ''), 0),0) as INT)
                           and CAST(to_experiance as INT) >= CAST(ISNULL((ISNULL(NULLIF(im.total_experiance, ''), 0) * 12) + ISNULL(NULLIF(im.total_experiance_months, ''), 0), 0) as INT)
                           and semester_type = CASE WHEN '" + semester_type + @"' = 'W' Then 'M' Else '" + semester_type + "' END and year_semester = '" + year_semester + @"' and designation = CASE 
						   WHEN im.designation = 'instructor' Then 'VF' 
						   WHEN im.designation = 'temp' Then 'VF' 
						   Else im.designation End and typology_sub_group ='SG003' 
                           AND (
                           CASE 
                           WHEN (CASE WHEN im.designation IN ('instructor', 'temp') THEN 'VF' ELSE im.designation END) = 'VF' 
                           THEN 1
                           ELSE CASE 
                           WHEN DegreeID IN ( SELECT DegreeID FROM rate_band_mst WHERE cancel_flag = 'N' 
                           AND DegreeID = (
                           SELECT CASE 
                            WHEN highest_qualification = 'UG' THEN 'UG003'
                            WHEN highest_qualification = 'PG' THEN 'PG001'
                            WHEN highest_qualification = 'PHD' THEN 'PHD001'
                            ELSE 'UG000' END
                           FROM instructor_mst WHERE user_id = im.instructor_code AND cancel_flag = 'N' ) ) THEN 1 ELSE 0 END END ) = 1 ) as rate_band
                           From ws_course_proposal_instructor
                           inner join instructor_mst im on im.instructor_code = ws_course_proposal_instructor.instructor_code
                           where course_code ='" + course_code + @"'
                           and semester_type='"+ semester_type + @"' and year_semester='"+ year_semester + @"'
                           and ws_course_proposal_instructor.cancel_flag in ('Y','N')
                           union all
                           select ws_course_proposal_TA.instructor_code,ContactHrs,AdditionalHrs,TotalHrs,im.designation,im.instructor_name,
                           (select rate_band from rate_band_range 
                           where ISNULL(degree,'') = im.highest_qualification
                           and CAST(from_experiance as INT) <= CAST(ISNULL((ISNULL(NULLIF(im.total_experiance, ''), 0) * 12) + ISNULL(NULLIF(im.total_experiance_months, ''), 0),0) as INT)
                           and CAST(to_experiance as INT) >= CAST(ISNULL((ISNULL(NULLIF(im.total_experiance, ''), 0) * 12) + ISNULL(NULLIF(im.total_experiance_months, ''), 0), 0) as INT)
                           and semester_type = CASE WHEN '" + semester_type  + @"' = 'W' Then 'M' Else '"+ semester_type + "' END and year_semester ='" + year_semester + @"' and designation = CASE 
						   WHEN im.designation = 'instructor' Then 'VF' 
						   WHEN im.designation = 'temp' Then 'VF' 
						   Else im.designation End and typology_sub_group ='SG003'
                           AND (
                           CASE 
                           WHEN (CASE WHEN im.designation IN ('instructor', 'temp') THEN 'VF' ELSE im.designation END) = 'VF' 
                           THEN 1
                           ELSE CASE 
                           WHEN DegreeID IN (
                           SELECT DegreeID 
                           FROM rate_band_mst 
                           WHERE cancel_flag = 'N' 
                           AND DegreeID = (
                           SELECT CASE 
                            WHEN highest_qualification = 'UG' THEN 'UG003'
                            WHEN highest_qualification = 'PG' THEN 'PG001'
                            WHEN highest_qualification = 'PHD' THEN 'PHD001'
                            ELSE 'UG000' END
                        FROM instructor_mst 
                        WHERE user_id = im.instructor_code 
                          AND cancel_flag = 'N' ) ) THEN 1 ELSE 0 END END) = 1 ) as rate_band
                           from ws_course_proposal_TA 
                           inner join instructor_mst im on im.instructor_code = ws_course_proposal_TA.instructor_code
                           where course_code ='" + course_code + @"'
                           and semester_type='"+ semester_type + @"' and year_semester='"+ year_semester + @"'
                           and ws_course_proposal_TA.cancel_flag in ('Y','N')) as t1";
            
            return Get_data(SqlSelect);
        }

        public DataTable GetSWSCourseBudgetRatebandNumberofparameters(string course_code, string semester_type, string year_semester,string course_credit, string course_type)
        {
            if (course_type == "Elective")
            {
