                            AND number_of_tutors in (SELECT ( SELECT COUNT(course_code)  FROM ws_course_proposal_instructor 
		WHERE cancel_flag IN('N','Y') AND course_code = '"+ course_code + @"' 
		AND year_semester = '"+ year_semester + @"' AND semester_type = '"+ semester_type + @"'
    ) AS TotalCount) ";
            return Get_data(SqlSelect);
        }

