        public bool SubmitCourseInfo(Dictionary<string, object> row, string user_id, string user_host, string user_type, DataTable dt)
        {

            DBConnection.Open();
            DBDataAdpterObject.SelectCommand.Parameters.Clear();
            String SqlSelect = "";
            try
            {
                DBDataAdpterObject.SelectCommand.Parameters.Clear();
                SqlSelect = "";

                if (user_type == "D" && dt != null)
                {
                    SqlSelect = "INSERT INTO ws_course_budget_master_details (ws_course_code, course_code, course_type, course_level, course_credits, type_of_course, min_student_suggest,min_student_decided,fees_per_credit,total_expected_fees,uni_component,fac_componet,total_expenses,budget_status,budget_approve_status,cancel_flag,created_by,created_date,created_host,semester_type,year_semester,is_submit,FA_status, dean_status,ugpg_status)  " +
                    "values('" + row["course_code"] + "','" + row["course_code"] + "','" + row["course_type"] + "','" + row["course_level"] + "','" + row["course_credit"] + "','" + row["type_of_course"] + "','" + row["min_student"] + "','" + row["dec_min_student"] + "','" + row["FeesPerCredit"] + "','" + row["total_expected_fees"] + "','" + row["University_Component"] + "','" + row["Faculty_Component"] + "','" + row["TotalExpenses"] + "','" + row["surplusvalue"] + "','" + row["SurplusStatus"] + "','N','" + user_id + "','" + DateTime.Now.ToString("yyyy/MM/dd HH:mm:ss") + "','" + user_id + "','" + row["semester_type"] + "','" + row["year_semester"] + "','" + dt.Rows[0]["is_submit"].ToString() + "'" +
                    ",'" + dt.Rows[0]["FA_status"].ToString() + "','Y','" + dt.Rows[0]["ugpg_status"].ToString() + "') ";
                }
                else if (user_type == "FA" && dt != null)
