        public DataTable Get_course_budget_details(string sem_code,string year_code,string course_code, string user_type,string user_id)
        {
            DataTable dt = null;
            if (user_type == "FA")
            {
                dt = get_department_wise_user_dtl(user_id, sem_code, year_code);
            }
            else if (user_type == "D")
            {
                dt = get_semyearwise_dean_user_dtl(user_id,"", sem_code, year_code);
            }
            String SqlSelect = "";
            SqlSelect = @"  Select  distinct wscb.ws_course_code,wscb.course_code,course_desc,course_name,wcp.course_type,wscb.type_of_course,
							wscb.min_student_decided,wscb.min_student_suggest,wscb.fees_per_credit,wscb.total_expected_fees,wscb.uni_component,wscb.fac_componet,wscb.total_expenses,
							wscb.budget_status,wscb.budget_approve_status,wscb.is_submit,wscb.dean_status,wscb.ugpg_status,
                            Case when wscb.is_submit = 'Y' Then 'Approved' Else 'Pending' End As Faculty_status, 
							Case when wscb.dean_status = 'Y' Then 'Approved' Else 'Pending' End As Dean_status, 
							Case when wscb.ugpg_status = 'Y' Then 'Approved' Else 'Pending' End As Ugpg_status,
                            wscb.semester_type,wscb.year_semester,wcb.rate_band,wcb.TotalHrs,wiw.rate_band as workloadrateband,wiw.total_hrs as totalhrsworkload,wcp.inhabitation
                            ,wcb.instructor_code,wcb.instructor_name
                            From ws_course_budget_master_details wscb
							inner join ws_course_proposal wcp on wcp.course_code = wscb.course_code
                            inner join ws_course_budget_instructor_details wcb on wcb.course_code = wscb.course_code
							and wcb.ws_course_code = wscb.ws_course_code
							and wcb.cancel_flag ='N' and wcb.semester_type = wscb.semester_type and wcb.year_semester = wscb.year_semester
							left join ws_instructor_workload_detail wiw on wiw.course_code = wscb.course_code and wiw.ws_course_code = wscb.ws_course_code
							and wiw.cancel_flag ='N' and wiw.semester_type = wscb.semester_type and wiw.year_semester = wscb.year_semester
							where wscb.cancel_flag ='N' and wscb.semester_type ='" + sem_code + @"' and wscb.year_semester ='"+ year_code + @"'";
            if (course_code != "")
            {
                SqlSelect += @" And (course_code = '" + course_code + @"' or ws_course_code = '" + course_code + @"')";
            }
           
            
            
            if (dt != null)
            {
                SqlSelect += @" And wcp.inhabitation = '"+ dt.Rows[0]["dept_code"].ToString() + @"' ";
            }
            return Get_data(SqlSelect);
        }


