        public DataTable get_instructor_course_details(String semester, String year, String prog_code)
        {
            String SqlSelect = "";

            SqlSelect = @" WITH CTE AS (
                                SELECT
                                    i.instructor_code,
                                    i.instructor_name,
                                    i.designation,
                                    i.mobile_no,
                                    i.mail,
                                    i.cv_file_name,
                                    i.portfolio_file_name,
                                    c.course_name,
                                    ROW_NUMBER() OVER(
                                        PARTITION BY i.instructor_code
                                        ORDER BY c.course_code
                                    ) AS rn
                                FROM instructor_mst i
                                INNER JOIN course_wise_instructor cwi
                                    ON cwi.instructor_code = i.instructor_code
                                   AND cwi.cancel_flag = 'N'
                                INNER JOIN course_mst c
                                    ON c.course_code = cwi.course_code
                                   AND c.year_semester = '" + year + @"'
                                   AND c.semester_type = '" + semester + @"'
                                WHERE cwi.year_semester = '" + year + @"'
                                  AND cwi.semester_type = '" + semester + @"'
                            )
                            SELECT
                                instructor_code,
                                instructor_name,
                                designation,
                                mobile_no,
                                mail,
                                cv_file_name,
                                portfolio_file_name,
                                MAX(CASE WHEN rn = 1 THEN course_name END) AS course1_name,
                                MAX(CASE WHEN rn = 2 THEN course_name END) AS course2_name,
                                MAX(CASE WHEN rn = 3 THEN course_name END) AS course3_name,
                                MAX(CASE WHEN rn = 4 THEN course_name END) AS course4_name,
                                MAX(CASE WHEN rn = 5 THEN course_name END) AS course5_name
                            FROM CTE
                            GROUP BY
                                instructor_code,
                                instructor_name,
                                designation,
                                mobile_no,
                                mail,
                                cv_file_name,
                                portfolio_file_name;";


            return Get_data(SqlSelect);

        }
