        }

        public DataTable get_instructor_acedemic_details(String semester, String year, String prog_code, String type_code)
        {
            String SqlSelect = "";

            SqlSelect = @"	select i.instructor_code,i.instructor_name,i.designation,iaw.detail_type,
	                        iaw.sr_no,pm.prog_name,iaw.degree,iaw.specialization,iaw.university,iaw.edu_start_date,iaw.edu_end_date,iaw.edu_type,iaw.edu_percentage,iaw.edu_mode
	                        from instructor_mst i 
	                        inner join instructor_academic_work_dtl iaw
	                        on iaw.instructor_code = i.instructor_code 
                            left join programme_mst pm on pm.prog_code=iaw.program_code
