            String SqlSelect = "";

            SqlSelect = @" select AM.instructor_code,IM.instructor_name,AM.sr_no,AM.trainings_programs_attended,AM.total_hours,AM.Type,AM.Date,AM.Organizer,AM.ModeofTraining,AM.Title
                           from faculty_appraisal_training_program_dtl AM
                           inner join instructor_mst IM on IM.instructor_code = AM.instructor_code and IM.cancel_flag='N'
                           where AM.cancel_flag='N' and AM.year='" + year + "'";

            return Get_data(SqlSelect);

        }

        public DataTable get_faculty_appraisal_Favourable_details(String year, String type_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select AM.instructor_code,IM.instructor_name,AM.sr_no,AM.mention_facilitating
                           from faculty_appraisal_favourable_role_dtl AM
                           inner join instructor_mst IM on IM.instructor_code = AM.instructor_code and IM.cancel_flag='N'
                           where AM.cancel_flag='N' and AM.year='" + year + "'";

            return Get_data(SqlSelect);

        }

        public DataTable get_faculty_appraisal_Unfavourable_details(String year, String type_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select AM.instructor_code,IM.instructor_name,AM.sr_no,AM.mention_inhibiting
                           from faculty_appraisal_unfavourable_role_dtl AM
                           inner join instructor_mst IM on IM.instructor_code = AM.instructor_code and IM.cancel_flag='N'
                           where AM.cancel_flag='N' and AM.year='" + year + "'";

            return Get_data(SqlSelect);

        }

        public DataTable get_faculty_appraisal_Training_Required_details(String year, String type_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select AM.instructor_code,IM.instructor_name,AM.sr_no,AM.training_skill
                           from faculty_appraisal_training_dtl AM
                           inner join instructor_mst IM on IM.instructor_code = AM.instructor_code and IM.cancel_flag='N'
                           where AM.cancel_flag='N' and AM.year='" + year + "'";

            return Get_data(SqlSelect);

        }

        public DataTable get_faculty_appraisal_Certificate_details(String year, String type_code)
        {
            String SqlSelect = "";

            SqlSelect = @" select AM.instructor_code,IM.instructor_name,AM.uplodaFile1,AM.uplodaFile2,AM.uplodaFile3,AM.uplodaFile4
                           from faculty_appraisal_application_mst AM
                           inner join instructor_mst IM on IM.instructor_code = AM.instructor_code and IM.cancel_flag='N'
                           where AM.cancel_flag='N' and AM.year='" + year + "'";

            return Get_data(SqlSelect);

        }
    }
}





